local P = LoreForeverPacks.Begin("LoreForever_Lang_svSE")
P.entries["npc:merissa-stilwell"] = {n="Merissa Stilwell",s="På Northshire Abbey välkomnar Merissa Stilwell nykomlingar till Northshire Valley. Den unga mänskliga stadsbon hälsar glatt och erbjuder en hjälpande hand åt dem som tränar i närheten.",h="På Northshire Abbey välkomnar Merissa Stilwell nykomlingar till Northshire Valley.",kw={"elwynn","merissa","northshire","stilwell"},ang={["faction:Alliance"]="Som rekryt i Alliansen lämnar du Northshires skyddade kloster, och hos Merissa möter du Elwynns varma gästfrihet innan Defias-hotets hårda verklighet gör sig påmind."},sec={{t="Ett välkomnande ansikte i Northshire",b="Från sin plats vid Northshire Abbey hälsar Merissa Stilwell nya rekryter välkomna när de anländer till Northshire Valley. Hon erbjuder nykomlingarna enkel gästfrihet och praktiska råd om vila och om hur de hittar rätt. Hennes efternamn delas av hantverkare och nybyggare runt om i kungariket, däribland smeden Jordan Stilwell och Westfalls försvarare Daphne Stilwell. Merissa förblir en fridfull lokal närvaro medan spänningarna i kungariket växer."}},faq={{q="Vem är Merissa Stilwell?",a="Merissa Stilwell är en vänlig mänsklig invånare vid Northshire Abbey i Elwynn Forest. Hon ger råd och ett varmt välkomnande till resenärer som anländer dit.",al={"merissa stilwell","vem är merissa","stilwell-flicka northshire"}},{q="Var hittar jag Merissa Stilwell?",a="Du hittar Merissa Stilwell vid Northshire Abbey i Northshire Valley, i Elwynn Forest.",al={"merissa stilwell plats","var är merissa","hitta merissa"}},{q="Är Merissa släkt med de andra Stilwell i kungariket?",a="Merissa Stilwell delar efternamn med smeden Jordan Stilwell och Daphne Stilwell i Westfall. Hon lever ett stillsamt liv vid Northshire Abbey och välkomnar resenärer i stället för att bekämpa banditer eller smida klingor.",al={"stilwell-familjen","daphne stilwell släkting","jordan stilwell släkting"}},{q="Ger Merissa Stilwell några uppdrag?",a="Nej. Merissa Stilwell har inga uppgifter åt resenärer; hon hälsar bara nykomlingar som passerar genom Northshire.",al={"merissa uppdrag","merissa stilwell uppdrag"}}},fx={a071eba0={q="På vems sida står Merissa Stilwell?",a="Merissa Stilwell är en lojal undersåte till den Stora Alliansen och kungariket Stormwind. Hon bor fridfullt i Northshire Abbey och välkomnar resande och rekryter som anländer till dalen.",al={"merissa stilwells fraktion","tillhör merissa stilwell alliansen"}},["57a6fac4"]={q="Varför är Merissa Stilwell i Northshire?",a="Merissa tillbringar sina dagar kring Northshire Abbey. Liksom många vanliga invånare i kungariket lever hon i Elwynn Forest och välkomnar nykomlingarna som anländer till dalen.",al={"varför är merissa stilwell här","vad gör merissa i northshire"}}},fp="16,163,30.412.0,24.130.0,34.93.0,57.206.0,39.103.0"}
P.entries["npc:merrin-rockweaver"] = {n="Merrin Rockweaver",s="Merrin Rockweaver är en dvärgforskare som företräder Explorers' League i Wetlands. Efter en våldsam raptorinvasion som översvämmade Whelgar's Excavation Site sökte hon skydd tillsammans med Prospector Whelgar på en höjd med utsikt över platsen.",h="Merrin Rockweaver är en dvärgforskare som företräder Explorers' League i Wetlands.",kw={"explorers' league","merrin rockweaver","raptorer","tooling around","wetlands","whelgar's excavation site","whelgars tillflyktsplats"},ang={["faction:Alliance"]="Merrin företräder Ironforges akademiska närvaro i Wetlands, och att säkra hennes forskning bidrar till att bevara Alliances bräckliga fotfäste i de vilda träskmarkerna.",["race:Dwarf"]="För dvärgäventyrare handlar det om det nationella arvet att hjälpa Merrin. De skyddar de dyrbara titanreliker och historiska dokument som Explorers' League riskerade livet för att gräva fram."},sec={{t="Fördriven från utgrävningen",b="Merrin Rockweaver reste till Wetlands på uppdrag av Ironforge Explorers' League för att gräva fram uråldriga hemligheter efter titaner, begravda i dyn. Expeditionen slutade i katastrof när de stora ben som de grävde fram lockade raptorer till utgrävningen. Hårdföra förhistoriska bestar svärmade över schakten och tvingade Merrin och den överlevande besättningen att överge utrustning, anteckningar och allt de åstadkommit. Nu är hon fångad med de få överlevande på en klippa med utsikt över de översvämmade ruinerna."},{t="Rädda expeditionen",b="De överlevande är fångade på klippan, men vägrar låta expeditionen bli ett fullständigt misslyckande. Ormer Ironbraid smider planer på hämnd mot bestarna, och Prospector Whelgar letar efter de tavelfragment som lämnades kvar i de raptorhärjade schakten. Merrin tänker på sin make Tarrel, som inte har hört från henne på flera veckor. Hon förlitar sig på spejaren som Longbraid skickade för att hitta gruppen, så att han kan föra besked om deras belägenhet till Tarrel."}},faq={{q="Vem är Merrin Rockweaver?",a="Merrin Rockweaver är en dvärgarcheolog knuten till Explorers' League i Ironforge. Hon var stationerad vid Whelgar's Excavation Site i Wetlands innan raptorerna översvämmade utgrävningen.",al={"merrin rockweaver bakgrund","vem är merrin","dvärgen merrin i wetlands"}},{q="Varför är hon fångad ovanför utgrävningen?",a="Fläckiga raptorer lockades av de stora ben som gruppen grävde fram och övermannade utgrävningen nedanför. Många liv gick förlorade. Ormer Ironbraid skyddade Merrin och Prospector Whelgar när de flydde till den närliggande klippan, där de fortfarande är fångade.",al={"varför är merrin vid tillflyktsplatsen","whelgars tillflyktsplats merrin","vad hände med hennes läger"}},{q="Vad behöver Merrin hjälp med?",a="Merrin behöver någon som kan ta med ett brev om katastrofen till hennes make Tarrel. Han har varit utom sig av oro sedan hennes brev slutade komma.",al={"merrins uppdrag","merrin rockweavers uppgifter","tooling around bakgrund"}},{q="Vad försökte expeditionen hitta?",a="Som de flesta av Explorers' Leagues expeditioner hade utgrävningen i Wetlands fått i uppdrag att hitta uråldriga föremål med koppling till dvärgarnas ursprung och de mystiska titanreliker som finns gömda i Khaz Modan.",al={"vad gräver de efter","utgrävningsplatsens syfte"}}},fx={["86a5e24a"]={q="På vems sida står Merrin Rockweaver?",a="Merrin Rockweaver står helt på Ironforge-dvärgarnas och Alliansens sida. Som aktiv kartläggare och medlem av Explorers' League är hon lojal mot lärda och utgrävare som skickats från Ironforge för att utforska sitt folks uråldriga ursprung i Khaz Modan.",al={"merrin rockweavers fraktion","merrin rockweavers lojalitet","vem tjänar merrin"}},f33c6ea8={q="Vilka har Merrin Rockweaver band till?",a="Merrin följer med Prospector Whelgars expedition vid utgrävningsplatsen i Wetlands. Ormer Ironbraid hjälper till att försvara deras läger mot rovfåglarna som omringar det.",al={"merrin rockweavers förbindelser","merrin rockweavers medarbetare","vem arbetar merrin med"}}},fp="17,178,20.425.0,23.377.0,25.177.0,38.212.0,32.131.0,39.135.0"}
P.entries["npc:miles-welsh"] = {n="Miles Welsh",s="Miles Welsh är en prästtränare från de Förfallna som bor djupt inne i The Pools of Vision under Thunder Bluff. Han lär ut andlighet och skuggdisciplin till präster som färdas genom taurenhuvudstaden.",h="Miles Welsh är en prästtränare från de Förfallna som bor djupt inne i The Pools of Vision under Thunder Bluff.",kw={"devouring plague","de förfallna","miles welsh","the pools of vision","prästtränare","spirit rise","thunder bluff"},ang={["class:Priest"]="För präster som färdas genom Kalimdor är Miles Welsh en av få platser i Hordens centrala områden där de kan studera nya besvärjelser och utveckla sin andliga träning.",["race:Undead"]="Miles ger en välbekant, kall uppsyn från Lordaeron i en annars jordnära och solbadad taurenhuvudstad."},sec={{t="En skugga i grottorna",b="Miles Welsh befinner sig långt från de pesthärjade ruinerna i Ruins of Lordaeron och har sitt hem i den fuktiga grottan full av andar under Thunder Bluff, känd som The Pools of Vision. Som präst från de Förfallna undervisar han resenärer som kanaliserar gudomliga och skuggiga energier. Hans närvaro i hjärtat av Mulgore speglar de sköra diplomatiska banden mellan de Förfallna och Horden. Han delar fristad med taurenmystiker och schamaner och vägleder samtidigt akolyter i skuggans och trons konster."}},faq={{q="Vem är Miles Welsh?",a="Miles Welsh är en odöd prästtränare stationerad i The Pools of Vision under Thunder Bluff. Han hjälper präster i Horden med deras träning och specialiserade discipliner.",al={"miles welshs roll","vem är miles welsh","miles welsh prästtränare"}},{q="Var hittar jag Miles Welsh?",a="Han finns i The Pools of Vision, ett underjordiskt grottsystem under Spirit Rise i Thunder Bluff. Du kommer dit genom en grottöppning på platån.",al={"miles welshs plats","var finns miles welsh","hur hittar man miles welsh"}},{q="Varför finns en odöd prästtränare i Thunder Bluff?",a="De Förfallna och tauren är allierade inom Horden. Tauren, särskilt Magatha Grimtotem, förespråkade att de Förfallna skulle tas upp i fraktionen, vilket gjorde det möjligt för sändebud och tränare som Miles Welsh att erbjuda sina tjänster i Mulgore.",al={"varför finns de förfallna i thunder bluff","odöd präst i taurenstad"}},{q="Vilka förmågor lär han ut?",a="Miles Welsh tränar präster i allmänna besvärjelser och hjälper akolyter från de Förfallna och troll som söker särskilda rasförmågor, som Touch of Weakness eller Shadowguard.",al={"prästsbesvärjelser i thunder bluff","vad lär miles welsh ut"}}},fx={c3aae6f3={q="På vems sida står Miles Welsh?",a="Miles Welsh står på de Förkastades och den bredare Hordens sida. Tauren följer en helt annan andlig väg med rötter i Jordmodern, men Miles bor under deras platå bland deras allierade. Där erbjuder han sin kunskap om prästerskapet till Horde-resande som söker den.",al={"miles welshs fraktion","miles welsh: horden eller alliansen","vem tjänar miles welsh"}},["9239b409"]={q="Vad vill Miles Welsh?",a="Miles Welsh undervisar präster som besöker Thunder Bluff. Djupt nere i de avskilda Pools of Vision delar han med sig av sin disciplin och mörka magi till dem som vandrar skuggans och trons väg. Därmed får Hordens lärjungar vägledning även långt från Lordaeron.",al={"vad gör miles welsh","miles welshs syfte","miles welshs mål"}},["03472250"]={q="Vilka har Miles Welsh band till?",a="Miles Welsh är knuten till de Förkastade i Undercity. Hans närvaro i Thunder Bluff placerar honom bland de Förkastades sändebud och resande, som taurenfolkets huvudstad välkomnar genom den spirande pakten mellan Cairne Bloodhoofs folk och Lady Sylvanas Windrunners anhängare.",al={"miles welshs allierade","vem arbetar miles welsh för","miles welshs förbindelser"}}},fp="11,169,23.437.0,19.144.0,29.137.0,49.173.0,29.163.0"}
P.entries["npc:milli-featherwhistle"] = {n="Milli Featherwhistle",s="Milli Featherwhistle är en skicklig ingenjör som bygger mekanostridare och arbetar vid Steelgrill's Depot i Dun Morogh. Efter Gnomeregans fall bygger och underhåller hon omsorgsfullt de urverksriddjur som hennes folk föredrar. Hon säljer sina uppskattade mekaniska skapelser till andra gnomer och betrodda allierade till de fördrivna överlevande från Gnomeregan.",h="Milli Featherwhistle är en skicklig ingenjör som bygger mekanostridare och arbetar vid Steelgrill's Depot i...",kw={"dun morogh","gnomeregan","kharanos","mekanostridare","mekkatorque","milli featherwhistle","riddjursförsäljare","steelgrill's depot"},ang={["faction:Alliance"]="Allianshjältar som vinner Gnomeregan Exiles fullständiga respekt kan söka upp Milli och ta tyglarna på ett av Azeroths snabbaste mekaniska riddjur.",["profession:Engineering"]="Millis mekanostridare står på höjden av storskaliga gnomiska transportmedel och förenar gyroskopiska balanseringsenheter med mekaniska ben med högt vridmoment.",["race:Gnome"]="Milli Featherwhistle är ditt folks främsta riddjursingenjör och för vidare övertekniker Mekkatorques tekniska genialitet, trots att hon förvisats från ert hem under jord."},sec={{t="Mästerlig mekanostridaringenjör",b="Utomhus i den bitande kylan vid Steelgrill's Depot, strax öster om Kharanos, ansvarar Milli Featherwhistle för att förse Gnomeregans fördrivna invånare med urverkshästar. Till skillnad från de biologiska riddjur som dvärgar och nattalver föredrar bygger Milli hela sitt lager själv. Hon finjusterar personligen kugghjul, kolvar och balanserande gyron, så att varje mekanisk fågel fungerar optimalt bland Dun Moroghs snöiga klippor."},{t="Mekkatorques arv",b="Varje ram och fjäder i Millis verkstad bygger på ritningar som ursprungligen utformades av övertekniker Gelbin Mekkatorque. Under årens lopp har Milli lagt till moderna prestandaförbättringar genom att göra chassina lättare och förfina avgasventilerna, men hon följer troget överteknikarens grundläggande ritningar. Hennes mekaniska underverk visar att gnomernas tekniska ambition förblir obruten, även i exil."}},faq={{q="Vem är Milli Featherwhistle?",a="Milli Featherwhistle är gnomerna från Gnomeregans främsta uppfödare och ingenjör av mekanostridare. Vid Steelgrill's Depot i Dun Morogh bygger hon mekanostridare för hand och säljer dem till behöriga ryttare.",al={"milli featherwhistle","vem är milli","försäljare av mekanostridare"}},{q="Var hittar jag Milli Featherwhistle?",a="Hon finns vid Steelgrill's Depot, en ingenjörsutpost en kort promenad österut längs vägen från staden Kharanos i Dun Morogh.",al={"millis plats","var finns milli featherwhistle","hitta milli"}},{q="Vem får köpa riddjur av henne?",a="Som regel är det bara gnomiska äventyrare som genast har tillstånd och kunnande nog att köpa hennes skapelser. Medlemmar av andra Alliance-folk måste vinna Gnomeregan Exiles fullständiga förtroende och uppnå upphöjd status innan hon anförtros dem en mekanostridare.",al={"kan jag köpa en mekanostridare","krav för mekanostridare","vem kan rida mekanostridare"}},{q="Hur byggs mekanostridare?",a="Milli Featherwhistle bygger varje mekanostridare själv, efter de välkända ritningar som övertekniker Gelbin Mekkatorque utformade. Hon lägger samtidigt till egna förbättringar av motor och balans.",al={"hur mekanostridare byggs","vem bygger mekanostridare","mekanostridarnas ursprung"}},{q="Vilka varianter av riddjur erbjuder hon?",a="Hon erbjuder flera finjusterade modeller, från standardramar utan färg till blå, gröna och röda, samt noggrant trimmade snabba varianter med vit, grön och gul ytbehandling.",al={"millis riddjursfärger","mekanostridarmodeller","vilka riddjur säljer milli"}},{q="Varför arbetar hon ute i snön vid Steelgrill's Depot?",a="Efter att den radioaktiva katastrofen och trogginvasionen drev bort gnomerna från Gnomeregan samlades flyktingarna där de kunde. Steelgrill's Depot fungerar som en naturlig samlingsplats utanför Kharanos för fordonstester och mekaniskt underhåll, tillsammans med dvärgarnas ingenjörer.",al={"varför är milli i dun morogh","varför steelgrill's depot"}}},fx={["2267a2b3"]={q="På vems sida står Milli Featherwhistle?",a="Milli Featherwhistle är hängiven Gnomeregan och den Stora Alliansen. Hon arbetar från Steelgrill's Depot tillsammans med dvärghantverkare och förser sina gnomkamrater och betrodda allianshjältar med mekanostridare, om de har förtjänat Gnomeregan Exiles fulla respekt.",al={"milli featherwhistles fraktion","vem tjänar milli featherwhistle","tillhör milli alliansen"}},f07f7c95={q="Vad vill Milli Featherwhistle?",a="Milli vill bygga och underhålla de bästa mekanostridarna i Dun Morogh. Hon utgår från högtekniker Mekkatorques ursprungliga ritningar och förbättrar ständigt konstruktionen, så att pålitliga mekaniska riddjur finns tillgängliga för gnomresande och beprövade allierade.",al={"vad gör milli featherwhistle","milli featherwhistles mål","vad försöker milli göra"}}},fp="20,199,25.300.0,21.295.0,28.161.0,38.96.0,43.209.0,29.132.0,36.149.0,57.274.0"}
P.entries["npc:milton-sheaf"] = {n="Milton Sheaf",s="I Stormwind Keep vakar Milton Sheaf rikets skrivna historia. Han sköter Royal Library och ber Alliance-resenärer att återfinna förlorade böcker och dokument.",h="I Stormwind Keep vakar Milton Sheaf rikets skrivna historia.",kw={"böcker","historia","bibliotekarie","milton sheaf","royal library","stormwind keep"},ang={["faction:Alliance"]="Som Alliance-resenär kan du hjälpa Milton Sheaf att bevara de mänskliga rikenas och den vidare Alliances nedtecknade arv.",["race:Human"]="Som människa delar du den historia som Milton Sheaf skyddar genom att bevara krönikor som överlevde Stormwinds fall och återuppbyggnad."},sec={{t="Vårdaren av Stormwinds historia",b="Milton Sheaf sköter Royal Library inne i Stormwind Keep. Medan hovet hanterar politik, adliga tvister och militära frågor bevarar han de skriftliga uppteckningarna. Han ser det som sin plikt att bevara korrekta historier om Alliance och Eastern Kingdoms, särskilt under krig, förluster och oroliga tider."},{t="Återfinna förlorade böcker",b="Milton Sheaf skickar resenärer för att återfinna böcker som spritts över riket. Böckerna slits av användning, medan dokument ligger i klosterarkiv, avlägsna utposter och bortglömda ruiner. Han skickar Alliance-äventyrare från Northshire Abbey till Southshore i norr för att hämta felplacerade böcker, undersöka gamla texter och tryggt återföra sällsynta manuskript till borgen."}},faq={{q="Vem är Milton Sheaf?",a="Milton Sheaf är en mänsklig lärd som sköter Royal Library inne i Stormwind Keep i Stormwind City. Han ansvarar för rikets böcker och krönikor.",al={"vem är milton sheaf","milton sheafs roll","stormwinds bibliotekarie"}},{q="Var hittar jag Milton Sheaf?",a="Du hittar Milton Sheaf i Royal Library-delen av Stormwind Keep, strax intill palatsets huvudkorridorer.",al={"milton sheafs plats","var finns milton sheaf","stormwinds bibliotek plats"}},{q="Varför behöver Milton Sheaf äventyrare?",a="Milton Sheaf förlitar sig på resande Alliance-äventyrare för att hitta historiska manuskript, ersätta skadade böcker och samarbeta med lärda och präster runtom i riket för att utöka Royal Librarys arkiv.",al={"milton sheafs uppdrag","vad vill milton ha","varför ge uppdrag"}},{q="Har Milton Sheaf kontakt med andra lärda i riket?",a="Ja. Milton Sheaf har kontakt med klostrens arkivarier och religiösa lärda, däribland Brother Paxton i Northshire Valley, för att bevara heliga läror och historiska dokument.",al={"milton northshire","milton brother paxton","miltons kontakter"}}},fx={["440d1fb9"]={q="På vems sida står Milton Sheaf?",a="Milton Sheaf tjänar kungariket Stormwind och Alliansen. Han är stationerad i själva Stormwind Keep och arbetar direkt för kronans kungliga arkiv. Där katalogiserar han historien och bevarar kunskap åt kungarikets lärda och ledare.",al={"milton sheafs fraktion","vem tjänar milton sheaf","milton sheaf och alliansen"}},["1fad6188"]={q="Varför är Milton Sheaf här i Stormwind Keep?",a="Milton ansvarar för att förvalta och underhålla Royal Library. Han vårdar kungarikets stora samling av skriftrullar, böcker och historiska dokument och ser till att viktiga skildringar av Azeroths förflutna skyddas och finns tillgängliga för hovet.",al={"varför är milton sheaf i royal library","milton sheafs syfte här","varför är milton i stormwind"}}},fp="12,122,36.288.0,21.356.0,20.147.0,30.106.0,39.200.0,62.184.0"}
P.entries["npc:miner-johnson"] = {n="Miner Johnson",s="Miner Johnson är en svårfunnen, erfaren gruvarbetare som tillhör Defias Brotherhood djupt inne i The Deadmines. Undangömd i en sidonisch tillsammans med vanliga arbetare övervakar denna farliga guldgrävare utgrävningarna före de tunga maskinerna längre ner under jord. Eftersom han irrar omkring oförutsägbart i de underjordiska tunnlarna stöter äventyrare bara ibland på honom.",h="Miner Johnson är en svårfunnen, erfaren gruvarbetare som tillhör Defias Brotherhood djupt inne i The...",kw={"nisch","the deadmines","defias","elit","miner johnson","moonbrook","sällsynt","rivare","westfall"},ang={["faction:Alliance"]="När Johnson fälls störs den stadiga strömmen av smältbar malm till Defias krigsmaskin, gömd under Moonbrook.",["profession:Mining"]="För guldgrävare står Johnson för den hårda, laglösa sidan av arbetet under jord. Han vaktar rika mineralfyndigheter djupt under Westfall med blod och hacka."},sec={{t="Ett sällsynt möte i djupet",b="Medan hundratals arbetare hackar i de underjordiska ådrorna i The Deadmines för att förse Edwin VanCleefs dolda fäste, utmärker sig Miner Johnson som en ovanligt fruktansvärd gestalt bland dem. Han lurar i en skuggig nisch till vänster före de dundrande rivarna i Mast Room och är mycket tåligare och mer aggressiv än den vanliga arbetsstyrkan. Hans oförutsägbara närvaro gör honom till ett legendariskt mål för utforskare som färdas genom Defias tunnlar."},{t="Bränsle till Defias krigsmaskin",b="Defias Brotherhoods hemliga verksamhet under Moonbrook kräver enorma mängder råmalm för att smida vapen, förstärka schakt och sätta ihop mekaniska konstruktioner. Gruvarbetare som Johnson står för kraften bakom metallen och hackar loss de rika mineralådrorna under Westfall. Den som råkar komma in i Johnsons arbetsområde upptäcker snart att han försvarar sin gruvplats med dödlig glöd."}},faq={{q="Vem är Miner Johnson?",a="Miner Johnson är en sällsynt elitmässig mänsklig gruvarbetare som är allierad med Defias Brotherhood. Han arbetar djupt inne i The Deadmines, i en sidonisch med andra arbetare strax före goblinrivaren.",al={"miner johnson bakgrund","vem är miner johnson","miner johnson i the deadmines"}},{q="Var finns Miner Johnson exakt?",a="Du hittar honom i de övre schakten i The Deadmines, innan du når rummet där Sneed och hans rivare finns. Leta efter en liten utgrävningsnisch till vänster, där en grupp gruvarbetare hackar i berget.",al={"miner johnsons plats","var finns miner johnson","hur hittar man miner johnson"}},{q="Varför är Miner Johnson inte alltid där?",a="Miner Johnson är en sällsynt spawn, vilket innebär att han bara dyker upp ibland när en expedition går in i The Deadmines. De flesta grupper som tar sig genom gruvschakten hittar i stället en vanlig gruvarbetare på hans plats.",al={"miner johnson dyker inte upp","är miner johnson sällsynt","miner johnsons spawnfrekvens"}},{q="Ingår Miner Johnson i något uppdrag?",a="Miner Johnson är inte knuten till någon formell uppdragsbelöning. Han är helt enkelt ett tillfälligt möte för de grottutforskargrupper som har turen att hitta honom vid ådern.",al={"miner johnson uppdrag","har miner johnson ett uppdrag"}},{q="Vilken roll har Miner Johnson i The Deadmines?",a="Han är en erfaren förman eller mästergrävare som hjälper Defias Brotherhood att utvinna ädelmetall, sten och resurser som behövs för att bygga deras väldiga underjordiska bas och dolda juggernaut.",al={"vad gör miner johnson","miner johnsons roll"}},{q="Är Miner Johnson farlig jämfört med andra gruvarbetare?",a="Ja. De vanliga grävarna i The Deadmines är relativt sköra, men Miner Johnson är en elitkrigare med betydligt större livskraft och slagstyrka. En samordnad grupp krävs för att besegra honom säkert.",al={"hur svår är miner johnson","är miner johnson elit"}}},fx={["3a6e6cc9"]={q="På vems sida står Miner Johnson?",a="Han står på Defias Brotherhoods och deras arbetares sida. Miner Johnson sliter djupt inne i The Deadmines tillsammans med de andra arbetarna och delar deras lojalitet till Edwin VanCleefs uppror. Han svingar sin hacka mot alla inkräktare som tar sig in i deras underjordiska fäste.",al={"miner johnsons fraktion","vem arbetar miner johnson för","tillhör miner johnson defias"}},c0432457={q="Varför är Miner Johnson i The Deadmines?",a="Han arbetar i en liten nisch vid gruvgångarna, strax före shreddern, där han gräver fram guld och järn åt Defias Brotherhood. Tillsammans med de vanliga arbetarna hjälper han till att leverera råmetallen som behövs för Edwin VanCleefs hemliga projekt.",al={"varför är miner johnson här","varför miner johnson i the deadmines","vad förde miner johnson hit"}}},fp="13,185,23.282.0,30.251.0,21.164.0,39.175.0,37.106.0,35.102.0,46.131.0,52.129.0"}
P.entries["npc:minor-manifestation-of-earth"] = {n="Minor Manifestation of Earth",s="En Minor Manifestation of Earth är en lokaliserad elementarande bunden till heliga stenar i Mulgore och Durotar. Den är osynlig för vanliga ögon och visar sig bara för blivande shamaner som dricker den heliga Earth Sapta. Den ger dem den råa kvartsen som krävs för att snida deras allra första jordtotem.",h="En Minor Manifestation of Earth är en lokaliserad elementarande bunden till heliga stenar i Mulgore och...",kw={"call of earth","earth sapta","earth totem","kodo rock","minor manifestation of earth","rough quartz","spirit rock"},ang={["class:Shaman"]="Varje ung shaman i Horde måste kommunicera med en Minor Manifestation of Earth under påverkan av Earth Sapta för att förtjäna sitt allra första totem.",["race:Tauren"]="Unga tauren färdas österut genom Mulgore till Kodo Rock för att söka kontakt med denna manifestation som en del av sina förfäders andliga prövningar."},sec={{t="Stenens röst",b="Jordens andar bor överallt under jord och sten, men för att kommunicera med dem krävs en medveten ritual. Vid heliga platser som Kodo Rock i Mulgore och Spirit Rock i Durotar dröjer Minor Manifestations of Earth kvar i den osynliga världen, omgivna av ännu mindre elementarväsen. Bara lärlingar som har druckit Earth Sapta, en rituell dryck bryggd av shamanernas mentorer, kan lyfta slöjan mellan den fysiska världen och elementen. När anden har blivit erkänd skänker den jordens välsignelser tillsammans med en bit Rough Quartz, som ger novisen den andliga fokuspunkt som behövs för att skapa ett Earth Totem."}},faq={{q="Varför kan jag inte se Minor Manifestation of Earth?",a="Manifestationen finns på elementarplanet och förblir osynlig för blotta ögat. Du måste dricka Earth Sapta, som din shamantränare ger dig, för att nå det förändrade medvetandetillstånd som krävs för att uppfatta och tala med elementarandar.",al={"kan inte se manifestation","var finns jordanden","jordmanifestation osynlig"}},{q="Var finns dessa jordandar?",a="De visar sig vid Kodo Rock på The Rolling Plains i Mulgore och vid Spirit Rock i Durotars torra raviner. Båda platserna tjänar som traditionella prövningsplatser för unga tauren-, orc- och trollshamaner.",al={"mindre manifestations plats","var hittar man jordmanifestationen"}},{q="Vad är andens syfte under riten?",a="Manifestationen prövar och erkänner formellt lärlingens förbindelse med jordelementet. När du talar med shamanen skänker den en bit Rough Quartz, som tas tillbaka till en shamantränare för att skapa ett Earth Totem.",al={"vad gör manifestationen","manifestationens syfte i uppdraget"}},{q="Vad är de mindre varelserna runt den?",a="Runt den centrala anden finns mindre jordmanifestationer. De är små ekon av elementet som dragits till de heliga markerna och finns där enbart som en del av den naturliga samhörigheten. Du kan inte interagera direkt med dem.",al={"mindre manifestationer","små jordelementarer runt den"}}},fx={["40387732"]={q="Vem är Minor Manifestation of Earth?",a="Minor Manifestation of Earth är en elementarande av jord som åkallas och vördas på heliga platser som Kodo Rock i Mulgore och Spirit Rock i Durotar. Den är osynlig för vanliga ögon och visar sig bara för schamaner som har vidgat sin andliga medvetenhet genom rituella drycker som Earth Sapta.",al={"vad är minor manifestation of earth","vem är jordmanifestationen","minor manifestation of earth i berättelsen"}},f34b34da={q="På vems sida står Minor Manifestation of Earth?",a="Den tjänar varken Horde eller Alliance. Som en förkroppsligad del av elementen står den på naturens balans sida och hör bönerna från noviser som visar den respekt och andliga klarhet som krävs för att få kontakt med jorden.",al={"minor manifestation of earths fraktion","är minor manifestation of earth vänligt sinnad","vilken sida står jordmanifestationen på"}},["95a7d1ef"]={q="Vad vill Minor Manifestation of Earth?",a="Den vill få kontakt med dem som vandrar schamanens väg. När en novis som har druckit Earth Sapta närmar sig, prövar den novisens beslutsamhet och skänker en bit Rough Quartz som grund för den första totemen.",al={"vad vill jordmanifestationen","jordmanifestationens önskan","vad söker minor manifestation"}},["17161102"]={q="Varför är Minor Manifestation of Earth här?",a="Den finns på heliga platser med elementarkraft, som Kodo Rock i Mulgore och Spirit Rock i Durotar, där den fungerar som en bro mellan det levande landet och blivande schamaner som genomgår Call of Earth.",al={"varför är minor manifestation of earth vid kodo rock","varför är jordmanifestationen här","varför är jordanden här"}}},fp="28,205,18.553.0,49.174.0,39.164.0,45.196.0,46.193.0"}
P.entries["npc:minor-manifestation-of-water"] = {n="Minor Manifestation of Water",s="Minor Manifestation of Water är en elementande som finns längs North Tide's Run vid Silverpine Forests kust. Den utgör ett viktigt prov för hordens shamaner, som vill få kontakt med och bemästra vattenelementet. Innan de kan rådfråga denna fridfulla ande måste de först rena dess fördärvade motsvarighet.",h="Minor Manifestation of Water är en elementande som finns längs North Tide's Run vid Silverpine Forests kust.",kw={"call of water","elemental","minor manifestation of water","north tide's run","shamanuppdrag","silverpine forest","water totem"},ang={["class:Shaman"]="Att rena elementanden från fördärv och ta emot dess välsignelse är det sista steget i att stämma in sig på tidvattnet och skapa din Water Totem.",["faction:Horde"]="Troll-, orc- och tauren-shamaner färdas hela vägen från Kalimdor till Lordaerons stränder för att få kontakt med denna ande."},sec={{t="En ande från västliga tidvatten",b="Längs North Tide's Runs dimhöljda stränder, väster om The Sepulcher i Silverpine Forest, utgör Minor Manifestation of Water ett viktigt övergångsprov för blivande shamaner. Vattenelementar förkroppsligar liv, förnyelse och föränderlighet, men de kan lätt falla offer för ondskefullt fördärv. En novis måste möta och besegra en fördärvad manifestation av detta element innan den rena Minor Manifestation of Water kan visa sig. När anden har renats vägleder den shamaner som fullbordar sin heliga resa för att skapa en Water Totem."}},faq={{q="Var hittar jag Minor Manifestation of Water?",a="Minor Manifestation of Water finns längs North Tide's Run, vid Silverpine Forests västkust, strax väster om The Sepulcher.",al={"minor manifestation of water plats","var finns manifestation of water","elemental north tides run"}},{q="Varför är elementanden fientlig när jag närmar mig första gången?",a="En shaman måste först frammana och förgöra Corrupt Minor Manifestation of Water. Först när den fördärvade närvaron har besegrats visar sig den fridfulla manifestationen, så att du kan tala med den.",al={"corrupt minor manifestation","varför är water manifestation arg","manifestation attackerar mig"}},{q="Vilket uppdrag handlar om denna elemental?",a="Denna ande är en viktig kontakt i shamanernas uppdragskedja ”Call of Water”, där shamaner till slut får förmågan att kasta sin Water Totem.",al={"call of water uppdrag","water totem-uppdrag silverpine","vilket uppdrag är detta till"}},{q="Kan andra än shamaner interagera med denna ande?",a="Minor Manifestation of Water finns särskilt till för att vägleda shamaner som genomgår sina andliga prov. Andra äventyrare har liten anledning att interagera med den.",al={"är detta endast för shamaner","kan vem som helst tala med manifestationen","vem talar med minor manifestation"}}},fx={["8e58f5e5"]={q="Vem är Minor Manifestation of Water?",a="Minor Manifestation of Water är en ande från elementarvattnen som kallas fram för att pröva och vägleda blivande schamaner. När den har renats från fördärv blir den en kanal för vattnets naturliga flöde och visdom och hjälper dem som lär sig att lyssna till elementens kallelse.",al={"vem är minor manifestation of water","vad är minor manifestation of water","vem är den här elementaren"}},c7703042={q="På vems sida står Minor Manifestation of Water?",a="Manifestationen tillhör varken Horde eller Alliance. Den tjänar elementens egen balans och svarar på kallelsen från schamaner som söker kontakt med vattnet. Den visar också om den som ber om hjälp har den styrka och renhet i sinnet som krävs för att kunna använda dess krafter.",al={"minor manifestation of waters fraktion","vem tjänar vattenmanifestationen","tillhör minor manifestation of water horde"}},["9e575f56"]={q="Vad vill Minor Manifestation of Water?",a="Den här anden vill pröva alla schamaner som söker mästerskap över vattnet. Den kräver att du visar att du kan övervinna fördärvande krafter innan den delar med sig av sin rena essens och skänker sin välsignelse.",al={"minor manifestation of waters mål","vad önskar vattenmanifestationen","vattenmanifestationens syfte"}},["05f89621"]={q="Varför är Minor Manifestation of Water här?",a="Manifestationen dras till platser där vattnets kraft samlas och väntar på schamanernas ritualer när de svarar på Call of Water. Den visar sig särskilt för att få kontakt med dem som deras elementarmentorer har lett till den.",al={"varför är vattenmanifestationen här","varför befinner sig vattenmanifestationen där"}}},fp="28,189,29.454.0,50.127.0,51.154.0,35.132.0,42.136.0"}
P.entries["npc:misha"] = {n="Misha",s="Misha är Rexxars, Hordens mästares, trogna björnkamrat. Hon vandrar troget genom Kalimdor vid den halvorchiska bestmästarens sida.",h="Misha är Rexxars, Hordens mästares, trogna björnkamrat.",kw={"björn","bestmästare","desolace","feralas","misha","rexxar","stonetalon"},ang={["class:Hunter"]="För jägare står Misha för det högsta idealet av en djurkamrat: ett obrytligt livslångt band som vuxit fram ur ömsesidig respekt, inte enbart dominans.",["faction:Horde"]="Misha stred vid Rexxars sida för att säkra den unga Hordens frihet vid Theramore Isle och vann veteranernas tysta respekt i hela Durotar."},sec={{t="Ett gränslöst band",b="Misha är en brunbjörn som vandrar vid Rexxars sida. Han är en ensam själ som litar mer på djur än på folk. Tillsammans har de byggt upp ett starkt och beskyddande band som stått emot otaliga vildmarker och blodiga strider."},{t="Durotars försvarare",b="Misha är mycket mer än ett tamt husdjur. Hon är en härdad krigare. Hon stred vid Rexxars sida i den brutala konflikten mot storamiral Daelin Proudmoore vid Theramore Isle och hjälpte till att säkra den unga Hordens överlevnad. När de inte strider blir hennes skarpa sinnen och styrka en förlängning av Rexxars vilja."},{t="Kalimdors vildmarker",b="Resenärer som färdas längs de långa stigarna genom Stonetalon Mountains, Desolace och Feralas kan just nu få syn på Misha, som tassar tyst bredvid Rexxar. Hon är vild nog att slita sönder varje rovdjur som hotar dem, men förblir Rexxars fasta punkt i en annars opålitlig värld."}},faq={{q="Vem är Misha?",a="Misha är en våldsam brunbjörn och Rexxars livslånga följeslagare. Rexxar är Hordens mästare. Hon vandrar genom vildmarkerna vid hans sida i centrala Kalimdor.",al={"rexxars björn","vem är björnen med rexxar","misha björn"}},{q="Var finns Misha just nu?",a="Misha strövar längs de långa patrullstigarna i Stonetalon Mountains, Desolace och Feralas. Hon vandrar troget vid Rexxars sida på hans ändlösa färder.",al={"mishas plats","var är misha","hitta misha"}},{q="Deltog Misha i grundandet av Durotar?",a="Ja. Efter det tredje kriget följde Misha med Rexxar i striden mot storamiral Daelin Proudmoores styrkor vid Theramore Isle för att försvara den unga Horden.",al={"misha theramore","stred misha mot daelin","misha tredje kriget"}},{q="Är Misha fientlig mot alliansspelare?",a="Ja. Som följeslagare till Hordens mästare försvarar Misha Rexxar med ursinne och angriper alla alliansintränglingar som kommer för nära.",al={"kan alliansen attackera misha","är misha aggressiv"}},{q="Varför föredrar Rexxar bestar som Misha framför folk?",a="Desillusionerad av svek och krig mellan humanoida raser valde Rexxar vildmarkens ensamhet. Han tror att bestar är raka och ärliga, och finner i Misha en följeslagare som aldrig sviker.",al={"varför har rexxar bestar","rexxars björnkamrat"}}},fp="5,140,16.243.0,19.303.0,17.310.0,13.157.0,35.154.0,47.164.0,37.141.0,51.194.0"}
P.entries["npc:misha-tor-kren"] = {n="Misha Tor'kren",s="På Tor'kren Farm i västra Durotar väntar Misha Tor'kren på besked om sin son. Kron gick västerut mot Southfury River för att jaga krokilisker, men har inte återvänt.",h="På Tor'kren Farm i västra Durotar väntar Misha Tor'kren på besked om sin son.",kw={"krokilisk","kron","förlorad men inte glömd","misha","misha tor'kren","southfury river","thunder ridge","tor'kren farm"},ang={["class:Hunter"]="Mishas son råkade ut för flodens rovdjur innan han hade lärt sig att bemästra vildmarken.",["race:Orc"]="Krons försök att bevisa sin styrka mot Durotars vilda djur visar vad ungdomligt högmod kan kosta."},sec={{t="En mors vaka",b="Misha Tor'kren sköter sin gård nära Thunder Ridge, sydost om åsen. Hennes son Kron gick västerut mot Southfury River för att jaga krokilisker och bevisa sitt mod, men han kom aldrig hem. Durotars faror vid gränsen gör att orchernas vakttorn är hårt ansträngda, och Misha har inte fått veta var han är. Hon behöver resenärer som är villiga att söka längs flodstränderna efter tecken på sonen."},{t="Ett dystert tecken",b="Kron föll offer för krokiliskerna i Southfury River. Misha kan bara ta emot hans bärgade amulett, en bitter påminnelse om farorna unga orcher möter när de försöker bevisa sin styrka i Kalimdors vildmark."}},faq={{q="Vem är Misha Tor'kren?",a="Misha Tor'kren sköter Tor'kren Farm i västra Durotar, sydost om Thunder Ridge.",al={"misha torkren","vem är misha","ägare till torkren farm"}},{q="Vart tog hennes son Kron vägen?",a="Kron gick västerut mot Southfury River för att jaga krokilisker och bevisa att han var en skicklig jägare, men han kom inte hem igen.",al={"var är kron","vad hände med kron","mishas son"}},{q="Vad händer när du letar efter Kron?",a="Misha ber resenärer att leta efter Kron längs floden. Hans försvinnande tynger henne, och hon behöver någon som undersöker saken.",al={"är kron död","hitta kron","förlorad men inte glömd"}},{q="Är hon släkt med Rexxars björn Misha?",a="Nej. Misha är en orcisk jordbrukare i Durotar och en annan person än Rexxars lojala björnkamrat, som har samma namn.",al={"misha björn","rexxars björn misha","är hon björnen"}}},fx={["971252e3"]={q="På vems sida står Misha Tor'kren?",a="Misha Tor'kren är en trogen medlem av Horde och lever som en anspråkslös orcisk nybyggare i Durotar. Hon bor på Tor'kren Farm, brukar den hårda röda jorden och förlitar sig på resande från Horde och lokala hjältar för att hjälpa familjen i kristider.",al={"misha tor'krens fraktion","vem tjänar misha tor'kren","misha torkren och horde"}},b9e15925={q="Vad vill Misha Tor'kren?",a="Misha vill desperat hitta sin försvunne son Kron. Den unge orcen försvann under en jakt längs Southfury Rivers farliga stränder, och hon ber förbipasserande äventyrare att söka igenom vattnet, ta reda på vad som hänt honom och återvända med något som kan visa hans öde.",al={"vad vill misha","misha tor'krens mål","varför behöver misha hjälp"}},["8e838196"]={q="Vilka band har Misha Tor'kren?",a="Misha har starka band till sin familj, framför allt till sin försvunne son Kron. Hon sköter Tor'kren-gården sydost om Thunder Ridge, där familjens försörjning hänger på att de överlever farorna i Durotars vildmark.",al={"misha tor'krens familj","vem är misha släkt med","misha torkrens son"}}},fp="14,166,16.369.0,12.201.1,22.86.0,26.119.0,36.135.1,38.104.0"}
P.entries["npc:mitsuwa"] = {n="Mitsuwa",s="Mitsuwa är en Darkspear-troll som är stationerad vid Zoram'gar Outpost längs Ashenvales dimmiga kust. Djupt skakad av bakhållet mot sina resande fränder tar han hjälp av Hordens hjältar för att hämnas de fallna och återta stulna andliga talismaner.",h="Mitsuwa är en Darkspear-troll som är stationerad vid Zoram'gar Outpost längs Ashenvales dimmiga kust.",kw={"ashenvale","darkspear","furbolg","marukai","mitsuwa","thistlefur","troll","troll charm","zoram'gar"},ang={["faction:Horde"]="Zoram'gar Outpost är en isolerad och belägrad garnison. Att hjälpa Mitsuwa stärker Hordens utsatta närvaro mot vilddjur och Alliansens spejare i Kalimdors västra utkanter.",["race:Troll"]="Mitsuwas maning till strid går Darkspear-äventyrare nära, eftersom återtagandet av heliga förfädersamuletter från grova furbolgraidare ger deras mördade bröder och systrar frid."},sec={{t="Hämnd för de fallna fränderna",b="Vid den avlägsna utposten Zoram'gar Outpost på The Zoram Strand tjänar Mitsuwa Horden tillsammans med sin följeslagare Marukai. När en grupp troll på väg till lägret överfölls och slaktades av de aggressiva Thistlefur-furbolgerna i norra Ashenvale, tog Mitsuwa förlusten som en svår förolämpning. Driven av plikt och vrede skickar han stridsdugliga krigare till Thistlefur-lyorna för att återta de stulna trollamuletterna och se till att hans fränders andar hedras och att deras heliga ägodelar återtas från bestarna."}},faq={{q="Vem är Mitsuwa?",a="Mitsuwa är ett Darkspear-djungeltroll som bor vid Zoram'gar Outpost i nordvästra Ashenvale. Tillsammans med sin följeslagare Marukai vakar han över gränsposten och samordnar vedergällning mot fientliga hot i området.",al={"mitsuwa","vem är mitsuwa","mitsuwas bakgrund"}},{q="Vad hände med trollen som reste till Zoram'gar?",a="En grupp troll som färdades genom Ashenvale för att förstärka eller besöka Zoram'gar Outpost överfölls och slaktades av de inhemska Thistlefur-furbolgerna, som tog de fallna resenärernas personliga ägodelar.",al={"döda troll i ashenvale","thistlefur anfaller troll"}},{q="Varför är trollamuletterna så viktiga för Mitsuwa?",a="Amuletterna har andlig och kulturell betydelse för Darkspear-stammen. Att låta heliga reliker stanna hos Thistlefur-furbolgerna efter en brutal massaker är en stor skymf mot de dödas andar.",al={"varför trollamuletter","varför uppdraget med trollamuletter"}},{q="Var finns amuletterna?",a="Thistlefur-furbolgerna förde amuletterna till sin by och sitt vidriga näste, som ligger i norra Ashenvale öster om The Zoram Strand.",al={"var finns trollamuletterna","thistlefur villages läge"}}},fx={["24ae2c07"]={q="På vems sida står Mitsuwa?",a="Mitsuwa är lojal mot Horde och bor bland sina fränder vid Zoram'gar Outpost längs Ashenvales kust. Han arbetar nära andra resande från Horde och hoppas att äventyrare från Horde ska hämnas hans fallna kamrater.",al={"mitsuwas fraktion","tillhör mitsuwa horde","vem tjänar mitsuwa"}},ec72a5f0={q="Vad vill Mitsuwa?",a="Mitsuwa söker rättvisa för en grupp trollkamrater som slaktades på väg till Zoram'gar Outpost. De aggressiva Thistlefur-furbolgerna överföll resenärerna och stal deras heliga trollamuletter, och Mitsuwa vill att de stulna arvegodsen återtas från bestarna.",al={"mitsuwas mål","vad behöver mitsuwa","mitsuwas uppdrag"}},b936450a={q="Varför är Mitsuwa vid Zoram'gar Outpost?",a="Mitsuwa är stationerad vid Zoram'gar Outpost, ett avlägset läger för Horde på Ashenvales västra kust. Härifrån håller han uppsikt över vildmarken och ser till resande som trotsar de förrädiska vägarna genom furbolgernas och nattalvernas områden.",al={"varför är mitsuwa i zoram'gar","mitsuwas syfte i ashenvale","varför är mitsuwa här"}}},fp="7,149,23.362.0,15.170.0,51.166.0,49.158.0,29.116.0"}
P.entries["npc:monte-gazlowe"] = {n="Monte Gazlowe",s="I Ratchet håller Monte Gazlowe en neutral hamn öppen för handelsmän från alla sidor. Han grundade staden med den förmögenhet han tjänade som hordens chefsingenjör under bygget av Durotar och Orgrimmar.",h="I Ratchet håller Monte Gazlowe en neutral hamn öppen för handelsmän från alla sidor.",kw={"barrens","durotar","freebooters","gazlowe","monte","orgrimmar","pozzik","ratchet","steamwheedle"},ang={["faction:Alliance"]="Gazlowe bryr sig föga om Stormwinds tron eller de gräl du tar med dig från Eastern Kingdoms. Ratchet välkomnar dig om ditt guld är äkta och du håller klingan i skidan.",["faction:Horde"]="Gazlowe ber om dina mynt som vilken goblin som helst, men han har varit en trofast allierad till Thrall sedan det tredje kriget. Han hjälpte till att gräva grunden till din huvudstad.",["profession:Engineering"]="Gazlowe är en av Kalimdors främsta gobliningenjörer. Han samordnar projekt från stadens vattenledningar till höghastighetsriggarna vid Mirage Raceway.",["race:Orc"]="Orgrimmars vattenförsörjning kom från tunnlar som Gazlowes sprängare grävde. Han har fortfarande goblinmekaniker stationerade i Durotar för att hjälpa till med större byggprojekt."},sec={{t="Ratchets mästerhjärna",b="I Ratchet driver Monte Gazlowe en hamn där rivaler kan handla under Steamwheedle Cartel. Han grundade staden på den karga kusten efter att ha fått bra betalt för sitt ingenjörsarbete åt den nya horden. Handelsmän från horden, alliansen och fristående grupper får göra bytesaffärer där, så länge de håller vapnen i skidan och har välfyllda börsar."},{t="Ingenjör åt Horden",b="Efter det tredje kriget anställde överhövding Thrall Monte Gazlowe som Durotars chefsingenjör för att lösa brådskande problem åt den nya orkh huvudstaden. Gazlowe tog sig an det farliga arbetet med att säkra färskvatten åt Orgrimmar. Hans tunnlar bröt igenom till koboldernas underjordiska hålor, men den kringvandrande bestmästaren Rexxar kom i tid för att hjälpa till att spränga igen grottorna. Gazlowe slutförde sina uppdrag och är fortfarande en uppskattad uppdragstagare och vän till Thrall. Han har till och med skickat sin förman, Rezlak, för att fortsätta hjälpa till med orkbyggen runt om i Durotar."},{t="Problem vid The Merchant Coast",b="Handeln ger goda intäkter i Ratchet, men sjörövare och tjuvar ställer till problem för Monte Gazlowes affärer. Southsea Freebooters har läger längs den närbelägna Merchant Coast, där de kapar last på väg till Ratchet och stjäl allt från råmalm till Gazlowes specialbeställda stövlar. För att skydda sina vinster anlitar hamnchefen ofta förbipasserande legosoldater från alla läger för att rensa piratläger, återta stulna leveranser och göra upp med bråkmakare vid hamnen."}},faq={{q="Vem är Gazlowe?",a="Monte Gazlowe styr Ratchet, den största handelshamnen vid The Barrens kust. Han tjänade sin förmögenhet som chefsingenjör med ansvar för bygget av Orgrimmar och grundade sedan Ratchet som en öppen, neutral hamn under Steamwheedle Cartel.",al={"vem är monte gazlowe","gazlowes historia","ratchets boss"}},{q="Är Gazlowe lojal mot Horden eller Alliansen?",a="Monte Gazlowe driver Ratchet under Steamwheedle Cartel och öppnar hamnen för resenärer från alliansen och horden. Han har också ett nära band och en lönsam historia med överhövding Thrall, eftersom han konstruerade viktiga delar av Durotars bosättningar.",al={"är gazlowe horde","är ratchet neutralt","gazlowes fraktion"}},{q="Vad byggde Gazlowe i Durotar?",a="När Durotar grundades anställde överhövding Thrall Monte Gazlowe som sin chefsingenjör. Gazlowe övervakade grävningen av tunnlar för att hitta en underjordisk vattenkälla åt Orgrimmar. När gruvarbetarna släppte lös fientliga kobolder anlitade Gazlowe Rexxar för att hjälpa sprängarna att försegla tunnlarna.",al={"gazlowe orgrimmar","gazlowe thrall","gazlowes vattenförsörjning"}},{q="Varför anlitar Gazlowe äventyrare i Ratchet?",a="Monte Gazlowe anlitar beväpnade legosoldater mot Southsea Freebooters, som har läger längs Merchant Coast och plundrar last som är avsedd för Ratchets hamn. Han betalar prisjägare för att göra sig av med piraterna, återta stulna lastmanifest och hämta försvunna leveranser.",al={"gazlowes uppdrag","southsea freebooters ratchet","gazlowes problem"}},{q="Vilken koppling har Gazlowe till Mirage Raceway?",a="Monte Gazlowe är en hängiven beundrare av ingenjörskonst och fart. Han sponsrar goblinlag som tävlar mot gnomer i The Shimmering Flats i Thousand Needles, hjälpte till att bygga deras tävlingsrigg och försöker få tag på prototypregulatorer för bränsle.",al={"gazlowe shimmering flats","gazlowe thousand needles","gazlowes tävlingar"}}},fx={cabfa558={q="Varför är Gazlowe i Ratchet?",a="Efter att ha tjänat en förmögenhet på att hjälpa Thrall bygga Orgrimmar investerade Gazlowe vinsten i att grunda Ratchet. Staden ligger vid Southfury Rivers mynning på The Barrens kust och fungerar som Steamwheedle Cartels främsta neutrala handelshamn i Kalimdor. Därifrån kan han övervaka sjöfarten, regionala ingenjörsprojekt och lukrativa kontrakt över hela kontinenten.",al={"varför kom gazlowe till ratchet","varför är gazlowe här","gazlowes syfte i ratchet"}},["0afdf6f5"]={q="Vilka är Gazlowes främsta allierade och affärspartner?",a="Gazlowe har nära band till krigshövding Thrall och Horde, eftersom han var deras chefsingenjör när Durotar grundades. Inom Steamwheedle Cartel gör han affärer med Baron Revilgaz i Booty Bay. Han sponsrar också goblinernas racinglag vid Mirage Raceway i The Shimmering Flats.",al={"gazlowes allierade","vilka band har gazlowe","gazlowes kontakter","gazlowes partner"}}},fp="13,204,25.335.0,22.522.0,29.469.0,15.231.0,46.244.0,34.264.0,45.262.0,51.222.0"}
P.entries["npc:moon-priestess-amara"] = {n="Moon Priestess Amara",s="Moon Priestess Amara är en Night Elf-prästinna som är stationerad längs huvudvägen väster om Dolanaar i Teldrassil. Med lojala jägare som vakter håller hon uppsikt över skogsstigarna mellan trädets hjärta och huvudstaden Darnassus.",h="Moon Priestess Amara är en Night Elf-prästinna som är stationerad längs huvudvägen väster om Dolanaar i...",kw={"amara nightwalker","dolanaar","elanaria","moon priestess amara","nhemai","teldrassil","vägen till darnassus","yaeliura"},ang={["class:Priest"]="Som medlem av The Sisterhood of Elune förkroppsligar Priestess Amara Night Elf-folkets hängivenhet till mångudinnan och tjänar som vägledare i andliga frågor för unga akolyter som ger sig av från Shadowglen.",["race:NightElf"]="Amara markerar en viktig milstolpe på din resa bort från Dolanaar och erbjuder vägledning och uppdrag som leder vidare till den mäktiga staden Darnassus."},sec={{t="Väktare av grenstigarna",b="Moon Priestess Amara är stationerad vid en stillsam vägpost väster om Dolanaar och företräder både The Sisterhood of Elunes andliga auktoritet och den vaksamhet som krävs för att hålla Teldrassils vägar säkra. Hon färdas och håller vakt tillsammans med två jägarföljeslagare, Nhemai och Yaeliura. För resande som färdas västerut visar Amara vägen och leder äventyrare längs vägen mot Darnassus. Hon ger också dem med betungade sinnen i uppdrag att söka vägar till försoning."}},faq={{q="Vem är Moon Priestess Amara?",a="Moon Priestess Amara, även känd som Amara Nightwalker i sina uppdrag som vaktpost, är en prästinna i The Sisterhood of Elune, stationerad på vägen mellan Dolanaar och Darnassus i Teldrassil. Hon vakar över resenärernas säkerhet och andliga välbefinnande när de färdas genom grenverket.",al={"vem är amara","prästinnan amara","vaktposten amara nightwalker"}},{q="Var hittar jag Moon Priestess Amara?",a="Hon finns längs den asfalterade landsvägen strax väster om Dolanaar i Teldrassil, där hon håller vakt tillsammans med två vaktpostjägarinnor.",al={"var finns amara","amaras plats","prästinnan amara karta"}},{q="Vilka jägare står tillsammans med henne?",a="Hon vaktas och åtföljs av Huntress Nhemai och Huntress Yaeliura, två Night Elf-vaktposter som hjälper till att skydda vägen från bestar och fientlig korruption.",al={"amaras följeslagare","nhemai och yaeliura","amaras vakter"}}},fx={["3d569ab2"]={q="På vems sida står Moon Priestess Amara?",a="Moon Priestess Amara tjänar Elunes prästerskap och Alliance och vakar över Teldrassils heliga grenar. Tillsammans med sina Sentinel-kamrater vägleder hon resande och försvarar kaldoreiernas hemland mot det fördärv som hotar dess fridfulla skogar.",al={"amaras fraktion","amaras lojalitet","vem tjänar amara"}},["75dde252"]={q="Varför är Moon Priestess Amara stationerad här?",a="Amara är stationerad längs huvudvägen väster om Dolanaar för att skydda resande på väg mot Darnassus. Teldrassils stigar hemsöks allt oftare av fördärvade bestar och lurande timberlings, så hennes närvaro är avgörande för att hålla skogsvägarna säkra.",al={"varför är amara här","amaras syfte på platsen","varför är moon priestess amara på vägen"}},["74974fcb"]={q="Vad vill Moon Priestess Amara?",a="Hon söker dugliga äventyrare som kan hjälpa till att säkra vägen till huvudstaden Darnassus. Amara ber resande att röja undan de vidriga gnarlpine-furbolgerna och våldsamma skogsvarelserna som trakasserar dem som färdas västerut under Världsträdets grenar.",al={"vad behöver amara","amaras motiv för uppdrag","varför ger amara dig uppdrag"}}},fp="20,149,25.381.0,28.221.0,38.116.0,41.150.0"}
P.entries["npc:mor-rogal"] = {n="Mor'rogal",s="Mor'rogal är en tauren som bor i Sun Rock Retreat i Stonetalon Mountains. Han tjänar som rådgivare och vägvisare åt resenärer som söker ära och faror i klippornas oländiga underjordiska djup.",h="Mor'rogal är en tauren som bor i Sun Rock Retreat i Stonetalon Mountains.",kw={"boulderslide ravine","earthen vaknar","mor'rogal","morrogal","stonetalon","sun rock retreat","tauren"},ang={["faction:Horde"]="För resenärer som når Sun Rock Retreats tillflyktsort ger Mor'rogal viktig information om hoten som lurar i klipporna utanför bosättningens gränser.",["race:Tauren"]="Mor'rogal förkroppsligar taurenfolkets respekt för fysiska och andliga prövningar och ser Kalimdors djupa stenhålor som helig mark där man kan bevisa sitt värde."},sec={{t="Väktare bland klipporna",b="I skydd av Sun Rock Retreat intresserar sig Mor'rogal särskilt för de djupa skrevor och grottor som skär genom Stonetalon Mountains. Han vet att regionens vindlande underjordiska passager rymmer både stora rikedomar och livsfarliga faror, och skickar därför modiga Horde-vandrare för att undersöka oroliga områden som Boulderslide Ravine. För Mor'rogal handlar det inte bara om överlevnad att utforska dessa förrädiska djup, utan också om att pröva sinnet hos dem som följer sitt hjärta och sin själ i jakten på ära."}},faq={{q="Vem är Mor'rogal?",a="Mor'rogal är en tauren som delar ut uppdrag och bor i Sun Rock Retreat i Stonetalon Mountains. Han fungerar som lokal vägvisare och uppmanar Horde-äventyrare att pröva sin styrka i de farliga grottor och raviner som finns utspridda över den klippiga bergskedjan.",al={"morrogal","vem är mor'rogal","mor rogal berättelse"}},{q="Var hittar jag Mor'rogal?",a="Han står i Sun Rock Retreat, Horde:s främsta utpost, gömd bland topparna i centrala Stonetalon Mountains.",al={"mor'rogals plats","var finns mor'rogal","morrogal plats"}},{q="Vilka uppgifter erbjuder Mor'rogal?",a="Mor'rogal anlitar dugliga mästare för att bege sig till grottan vid Boulderslide Ravine, där kobolder febrilt bryter Resonite-kristaller, och därefter döda Goggeroc, en slumrande Earthen som kobolderna grävde upp.",al={"mor'rogals uppdrag","vad vill mor'rogal"}},{q="Varför fokuserar Mor'rogal på grottor och raviner?",a="Mor'rogal tror att Stonetalon Mountains farofyllda underjordiska grottor rymmer verkliga äventyr och prövningar av den andliga viljan, och erbjuder ära och rikedom åt dem som är villiga att riskera livet.",al={"varför grottor","mor'rogals grottor"}}},fx={["9b06cf83"]={q="Vilken sida står Mor'rogal på?",a="Mor'rogal står på Hordens och sina tauren-fränders sida. Han är stationerad i Sun Rock Retreat, en avskild Horde-utpost högt uppe i Stonetalon Mountains, där han ger vägledning och uppdrag till äventyrare som tjänar Hordens intressen i området.",al={"mor'rogals fraktion","mor'rogal horden eller alliansen","mor'rogals lojalitet"}},["27de9984"]={q="Vad vill Mor'rogal?",a="Mor'rogal söker modiga äventyrare som vågar sig in i de farliga grottorna och ravinerna i Stonetalon Mountains. Han skickar spejare till fientliga platser som Boulderslide Ravine och uppmanar djärva själar att möta farorna från jorden under marken i utbyte mot ära och rikedomar.",al={"mor'rogals mål","vad gör mor'rogal","syftet med mor'rogals uppdrag"}}},fp="9,107,20.355.0,17.190.0,27.119.0,32.179.1,46.158.0"}
P.entries["npc:morgan-pestle"] = {n="Morgan Pestle",s="I Stormwind driver Morgan Pestle Pestle's Apothecary i Trade District. Han arbetar med sin bror William Pestle i Goldshire och hanterar förnödenheter och alkemisk forskning åt huvudstaden.",h="I Stormwind driver Morgan Pestle Pestle's Apothecary i Trade District.",kw={"alkemist","morgan pestle","pestle apothecary","leverans till stormwind","stormwind","trade district","william pestle"},ang={["faction:Alliance"]="Om du anländer till Stormwind från Elwynn som äventyrare i Alliansen erbjuder Morgans butik praktiska alkemiska förnödenheter och lokala leveranser i staden.",["profession:Herbalism"]="Morgan är beroende av färska ingredienser som samlas in runtom i Elwynn Forest och bortom för att förse sitt apotek i Stormwinds Trade District."},sec={{t="Stadens apotekare",b="Morgan Pestle säljer alkemiska varor, reagenser och praktiska läkemedel på Pestle's Apothecary i Stormwinds Trade District. Hans bror William har en verkstad på Lion's Pride Inn i Goldshire, medan Morgan sköter deras familjehandel i huvudstaden. Han får förnödenheter från landsbygdens hjärtland, däribland ljus som William skickar."}},faq={{q="Var hittar jag Morgan Pestle?",a="Du hittar Morgan Pestle inne på Pestle's Apothecary i Stormwind Citys Trade District.",al={"morgan pestles plats","var finns morgan pestle","pestle apothecary stormwind"}},{q="Hur är Morgan Pestle släkt med William Pestle?",a="Morgan Pestle och William Pestle är bröder och arbetar båda som alkemister i Elwynn. Morgan driver deras butik i Stormwind, medan William arbetar i Goldshire.",al={"william pestle bror","är william och morgan släkt","pestlebröderna"}},{q="Vilken roll har han i uppdragen i Elwynn?",a="Morgan tar emot ljusen som William skickar norrut från Goldshire till Pestle's Apothecary och betalar kuriren bra för leveransen.",al={"leverans till stormwind morgan","uppdrag med morgan pestle"}}},fx={["2e5b0856"]={q="Vem är Morgan Pestle?",a="Morgan Pestle är en mänsklig alkemist och köpman som håller till i Trade District i Stormwind City. Han äger och driver Pestle's Apothecary, där han säljer reagenser, läkemedel och olika alkemiska blandningar till stadens invånare.",al={"vem är morgan pestle","morgan pestles bakgrund","vem är pestle"}},ae642a6d={q="Vilken sida står Morgan Pestle på?",a="Morgan Pestle är en lojal medborgare i Alliansen. Hans verksamhet ligger mitt i Trade District i Stormwind City och gynnar både lokalbefolkningen och kungariket i stort.",al={"morgan pestles fraktion","är morgan pestle med i alliansen","morgan pestles lojalitet"}},["2ef8a55a"]={q="Varför är Morgan Pestle här?",a="Morgan Pestle bor i Stormwind City för att sköta sin butik, Pestle's Apothecary. Från sin butikslokal i det livliga Trade District säljer han drycker och småsaker och tar emot leveranser från sin bror William, som arbetar i Goldshire.",al={"varför är morgan pestle i stormwind","morgan pestle trade district"}}},fp="13,161,19.325.0,31.81.0,47.155.0,40.128.0"}
P.entries["npc:morgan-the-collector"] = {n="Morgan the Collector",s="Vid Brackwell Pumpkin Patch leder Morgan the Collector Defias utpressning och insamling i Elwynn Forest. Som högt uppsatt agent samordnar han lokala stölder från bondgården medan vakten i Goldshire håller uppsikt i närheten.",h="Vid Brackwell Pumpkin Patch leder Morgan the Collector Defias utpressning och insamling i Elwynn Forest.",kw={"brackwell","brödraskap","defias","dughan","människojakt","morgan","pumpkin patch","signet","uppköparen"},ang={["class:Rogue"]="Som rogue ser du hur Morgans disciplin förvandlar spridda tjuvar till ett organiserat underjordiskt syndikat som finansierar ett uppror.",["race:Human"]="Som människa slår du tillbaka mot förrädarna som har förvandlat Stormwinds fridfulla gårdar till befästa banditnästen när du besegrar Morgan."},sec={{t="Elwynns tionde",b="Morgan the Collector tar en del av guldet från Elwynn Forests gruvor åt Defias Brotherhood. Medan vanliga banditer trakasserar resande på vägarna leder han organiserade rån och samlar in stulna mynt och förnödenheter till brödraskapets större nätverk. Hans högkvarter är bondgården vid Brackwell Pumpkin Patch, där lojala hantlangare som Surena Caledon och Erlan Drudgemoor omger honom."},{t="Ett sigill från förr",b="Morgan bär en särskild signetring som visar hans auktoritet. Utredare i Goldshire ser ringen som bevis för att de maskerade tjuvarna som terroriserar hjärtlandet har kopplingar till det vanärade Stonemasons Guild, som återuppbyggde Stormwind City efter det andra kriget. När ringen återfinns avslöjas vem som leder banditerna i skogen."}},faq={{q="Vem är Morgan the Collector?",a="Morgan är en högt uppsatt officer i Defias Brotherhood som samlar in guld från Elwynn Forests gruvor och samordnar banditverksamheten i trakten.",al={"vem är morgan","morgans historia","uppköpare i elwynn"}},{q="Var hittar man Morgan?",a="Morgan förvarar sitt stöldgods i bondgården vid Brackwell Pumpkin Patch i östra Elwynn Forest.",al={"morgans plats","var finns morgan the collector","huset vid brackwell pumpkin patch"}},{q="Varför jagar Stormwind honom?",a="Marshal Dughan och de lokala myndigheterna vill få Morgan undanröjd för att slå ut Defias ledning i Elwynn och återfå bevis för vem som organiserar upproren på landsbygden.",al={"varför döda morgan","jaktmål"}},{q="Vad är speciellt med ringen han bär?",a="Morgan bär en signetring som ger myndigheterna bevis i deras utredning av hans verksamhet i Elwynn Forest.",al={"uppköparens ring","uppköparens signetring","morgans ringhistoria"}}},fx={["8321821e"]={q="Vilken sida står Morgan the Collector på?",a="Morgan the Collector är en hängiven agent för Defias Brotherhood. Han är ingen vanlig stråtrövare, utan en officer inom den kriminella organisationen som arbetar direkt mot kungariket Stormwind och samordnar brödraskapets verksamhet i hjärtat av Elwynn Forest.",al={"morgan the collectors fraktion","vilken fraktion tillhör morgan","tillhör morgan defias"}},["5f1d52ce"]={q="Vad vill Morgan the Collector?",a="Morgan leder Defias verksamhet i hela Elwynn Forest. Hans tillnamn är ”the Collector”, och hans mål är att samla rikedomar, resurser och inflytande åt brödraskapets uppror. Han har etablerat ett befäst fäste i pumpafältet, mitt framför näsan på Stormwinds vakter.",al={"vad försöker morgan göra","morgan the collectors mål","morgan the collectors motiv"}},["2a29f808"]={q="Varför är Morgan the Collector i Elwynn Forest?",a="Morgan har slagit sig ner på Brackwell Pumpkin Patch för att själv leda Defias Brotherhoods lokala verksamhet. Genom att ta sin tillflykt till bondgården tillsammans med löjtnanterna Surena Caledon och Erlan Drudgemoor håller han banditerna i regionen under noggrann uppsikt.",al={"varför är morgan vid brackwell pumpkin patch","vad förde morgan hit"}},ceb85f69={q="Vilka har Morgan the Collector kopplingar till?",a="Hans signetring blir bevismaterial i en utredning av de laglösa som plågar Elwynn Forest och deras kontakter.",al={"vilka arbetar morgan med","morgan the collectors medarbetare","morgan stonemasons"}}},fp="20,209,19.394.0,20.330.1,28.156.0,22.103.0,29.152.0,42.113.1"}
P.entries["npc:morin-cloudstalker"] = {n="Morin Cloudstalker",s="Morin Cloudstalker är en tauren-spejare som håller vakt längs vägen österut från Bloodhoof Village mot The Barrens i Mulgore. Från sin post på slätterna bevakar han lokala handelsvägar och undersöker hoten som närmar sig och utsätter taurenresenärer för fara.",h="Morin Cloudstalker är en tauren-spejare som håller vakt längs vägen österut från Bloodhoof Village mot The...",kw={"bloodhoof village","great gate","morin cloudstalker","mulgore","ravaged caravan","supervisor fizsprocket","venture co"},ang={["faction:Horde"]="Morin ger Hordes mästare en tidig möjlighet att skydda förråden och de heliga markerna hos sina nya tauren-allierade.",["race:Tauren"]="För tauren som beger sig ut från Bloodhoof Village står Morin för ett vaksamt försvar av hemlandet mot både lycksökande banditer och företagsförstörare."},sec={{t="Väktare på den södra leden",b="Morin Cloudstalker står vid grusvägen som slingrar sig österut mot The Barrens och fungerar både som spejare och beskyddare för resenärer genom Mulgore. Grässlätterna här är vanligtvis fredliga, men handelsvägar och gränser som flyttas har fört lycksökare och banditer farligt nära taurenfolkets hjärta."},{t="Undersökning av karavanen",b="Morins spejare anföll och brände nyligen en Venture Co.-karavan på Stonebull Lakes norra strand. När goblinernas bärgare sågs nära de utbrända vagnarna skickade han äventyrare för att undersöka de överlevande förrådslådorna och ta reda på vad Venture Co. fraktade."},{t="Försvar mot Venture Co.",b="Utöver vanliga stråtrövare oroar sig Morin djupt för att Venture Company etablerar industriell verksamhet i Mulgore. Han uppmanar Horde-äventyrare på genomresa att slå mot deras skogsavverkning och gruvposter och rikta in sig på viktiga ledare som Supervisor Fizsprocket för att hejda miljöförstörelsen som hotar de heliga slätterna."}},faq={{q="Var hittar jag Morin Cloudstalker?",a="Morin Cloudstalker står vid grusleden öster om Bloodhoof Village i Mulgore, längs vägen som leder ut mot The Barrens.",al={"morins plats","var är morin","morin cloudstalker karta"}},{q="Vilken roll har Morin i Mulgore?",a="Han är en vaksam tauren-spejare som ansvarar för att hålla uppsikt över resor genom södra Mulgore och organisera försvaret mot banditer och företagsinkräktare.",al={"vem är morin cloudstalker","morins roll"}},{q="Varför undersöker Morin den förstörda karavanen?",a="Morins spejare anföll och brände en Venture Co.-karavan nära Stonebull Lake. När goblinernas bärgare sågs kring vraket bad han äventyrare att undersöka de överlevande förrådslådorna och ta reda på vad Venture Co. transporterade.",al={"uppdraget ravaged caravan","karavanattack i mulgore"}},{q="Varför vill Morin stoppa Venture Company?",a="Venture Company utarmar Mulgore på naturresurser med maskiner och skogsskövling. Morin försöker störa deras destruktiva verksamhet genom att röja deras förmän ur vägen, däribland Supervisor Fizsprocket.",al={"venture co i mulgore","varför döda fizsprocket"}},{q="Vem rapporterar Morin till?",a="Morin verkar på uppdrag av de äldste och hövdingarna i Bloodhoof Village samt taurenfolkets bredare ledarskap i Mulgore.",al={"morins lojalitet","vem skickade morin"}},{q="Ger Morin uppdrag till Alliance-spelare?",a="Nej. Morin är en NPC som är lojal enbart mot Horde och interagerar bara med Horde-äventyrare.",al={"kan alliance prata med morin","morins fraktion"}}},fx={["2ee6eb23"]={q="Vem är Morin Cloudstalker?",a="Morin Cloudstalker är en tauren-spejare som vakar över Mulgore. Han står längs vägen österut från Bloodhoof Village mot The Barrens och håller skarp uppsikt över hot som tränger in i taurenfolkets förfäders marker. Han skickar ut dugliga äventyrare från Horden för att skydda slätterna från plundrare och utsugare.",al={"vem är morin cloudstalker","vem är morin","morins bakgrund"}},b362fb80={q="Vilken sida står Morin Cloudstalker på?",a="Morin är orubbligt lojal mot Thunder Bluff och Horden. Han vaktar taurenfolkets hjärtland och erbjuder bara vägledning och uppdrag till andra Horde-resenärer som är villiga att försvara den sköra freden i Mulgore.",al={"morin cloudstalkers fraktion","morin alliansen eller horden","är morin med i horden"}},["7047ff15"]={q="Vad vill Morin Cloudstalker?",a="Morin vill skydda vägarna och naturresurserna i Mulgore. Han skickar äventyrare för att söka efter Venture Co.-karavanen som hans spejare brände och stoppa Venture Companys skadliga verksamhet. Han kräver särskilt att Supervisor Fizsprockets rovdrift i kullarna får ett slut.",al={"vad vill morin","morins mål","morins uppdrag"}},["9ad7af70"]={q="Varför är Morin Cloudstalker stationerad här?",a="Morin är stationerad längs vägen öster om Bloodhoof Village för att hålla uppsikt över trafiken genom Mulgore. Den här viktiga vägkorsningen låter honom övervaka karavaner och hejda hot som tränger sig på, till exempel Venture Companys skövlande folk, innan de når Bloodhoof Village.",al={"varför är morin här","varför står morin på vägen","varför är morin på den platsen"}}},fp="18,172,29.267.0,25.253.0,29.255.1,36.106.0,32.109.0,46.225.0,48.164.0,25.114.0,44.74.0"}
P.entries["npc:motega-firemane"] = {n="Motega Firemane",s="Motega Firemane är en taurenlärd vid Whitereach Post i Thousand Needles. Han ägnar sig åt att katalogisera ravinens farliga djurliv, men hans studier störs av en hämndlysten vindormsande och hans unge assistents vårdslösa upptåg.",h="Motega Firemane är en taurenlärd vid Whitereach Post i Thousand Needles.",kw={"arikara","cairne bloodhoof","kanati greycloud","magatha grimtotem","motega firemane","pao'ka swiftmountain","thousand needles","whitereach post"},ang={["class:Hunter"]="Jägare finner en gemensam grund med Motega, som förlitar sig på skickliga spårare för att samla in ravinens växter, spåra wyverner vid Highperch och smyga sig på den mäktiga anden Arikara.",["faction:Horde"]="Motega står för Hordes expansion till Kalimdors vilda områden. Han upprätthåller en osäker forskningsutpost samtidigt som han skyddar överhövding Cairne Bloodhoof från andliga hot.",["race:Tauren"]="Med sin vördnad för naturen och sin trogna hängivenhet till Cairne Bloodhoof förkroppsligar Motega taurenfolkets ideal: att studera Jordmoderns varelser och försvara stammen mot uråldriga andar."},sec={{t="Ravinernas lärde",b="Fyra år efter det tredje kriget reste Motega Firemane söderut till Thousand Needles för att studera och dokumentera de särpräglade bestar som överlevde bland de höga platåbergen. Han slog läger vid Whitereach Post tillsammans med Kanati Greycloud och sin unge assistent Pao'ka Swiftmountain, vars beskyddande far ogärna lät honom lämna Mulgore. Motega hade egentligen sökt sig dit för stillsamma naturstudier, men de hårda farorna på ravinens botten tvingade honom ständigt att ta till mer stridsinriktade metoder för att överleva."},{t="Arikaras vrede",b="Motegas fridfulla forskning avbröts när besked kom från Freewind Post om att Arikara, en våldsam och legendarisk bevingad ormande, hade återvänt till ravinerna för att hämnas på Cairne Bloodhoof. Motega kunde inte förstå varför varelsen hyste agg mot överhövdingen, men agerade snabbt för att skydda Horde. Han beordrade spejare att samla in Incendia agave från ravinens bäcken och föra den till äldste Magatha Grimtotem i Thunder Bluff, där den skulle förtrollas till ett heligt pulver. Med hjälp av pulvret lockade jägarna fram orm anden och dödade den. De återförde dess skinn till Whitereach Post som bevis på att Cairne var i säkerhet."},{t="Whitereachs väktare",b="Arikara var inte den enda faran som hotade Motegas vistelse vid Whitereach Post. De lokala Galak-centaurerna prövade ständigt lägrets försvar och smidde till och med planer på att mörda Kanati Greycloud och hans följeslagare. Som om det inte vore nog lämnade unge Pao'ka lägereldens trygghet och försvann bland de wyvernangripna höjderna vid Highperch. Motega var frustrerad över den unge krigarens tanklöshet, men kände en enorm lättnad när resenärer från Horde eskorterade honom tillbaka vid liv."}},faq={{q="Vem är Motega Firemane?",a="Motega Firemane är en taurenforskare vid Whitereach Post i Thousand Needles. Han kom till ravinerna för att studera det lokala djurlivet tillsammans med andra krigare och sin assistent Pao'ka Swiftmountain.",al={"motega firemane berättelse","vem är motega","whitereach motega"}},{q="Var hittar man Motega Firemane?",a="Han finns vid Whitereach Post, ett litet Horde-läger i Thousand Needles, längs vägen i områdets nordvästra del, nära Camp E'thok.",al={"motegas plats","var finns motega firemane","motega firemane karta"}},{q="Varför oroar sig Motega för Arikara?",a="Arikara är en hämndlysten orm ande som har visat sig i Thousand Needles och är ute efter Cairne Bloodhoof. Motega kan inte förstå varför anden hyser agg mot överhövdingen, men tar hotet på allvar och ber jägarna att locka fram och döda varelsen.",al={"vem är arikara","varför döda arikara","arikara cairne"}},{q="Vilken roll spelar Magatha Grimtotem i Motegas planer?",a="Motega ber äventyrarna att samla in Incendia agave och föra den till Magatha Grimtotem på Elder Rise i Thunder Bluff. Med sin kunskap om schamanism förtrollar Magatha växten till ett heligt pulver som kan locka fram den svårfångade Arikara.",al={"magatha incendia powder","motega och magatha","berättelse om uppdraget helig eld"}},{q="Vad hände med Motegas följeslagare Pao'ka?",a="Pao'ka Swiftmountain irrade in bland de farliga wyvernbon vid Highperch och gick vilse. Motega oroade sig för vad som hänt den unge mannen, särskilt eftersom Pao'kas far hade varit så ovillig att låta honom ge sig av. Men resenärer lyckades eskortera honom tillbaka till Whitereach Post.",al={"pao'ka swiftmountain","försvunnen tauren highperch","uppdraget homeward bound"}},{q="Vilka andra faror hotar Whitereach Post?",a="Förutom kringirrande andar och rovdjur är lägret ett aktivt mål för de närliggande Galak-centaurerna. De ligger i bakhåll och planerar mord på Kanati Greycloud och de andra tauren som är stationerade vid utposten.",al={"hot mot whitereach post","centaur vid whitereach","galak-centaurernas plan"}}},fx={ca68f68f={q="Vilken sida står Motega Firemane på?",a="Motega Firemane är lojal mot taurenfolket och Horden. Han är stationerad vid Whitereach Post tillsammans med Kanati Greycloud, samarbetar nära med Horde-resenärer och värnar om Cairne Bloodhoofs och stammarnas intressen under Thunder Bluffs baner.",al={"motega firemanes fraktion","motega firemane horden eller alliansen","är motega med i horden"}},["8b7dc2d8"]={q="Vad vill Motega Firemane?",a="Motega fokuserar främst på att studera Thousand Needles unika djurliv och hålla ett öga på sin unge följeslagare, Pao'ka Swiftmountain. Men hot mot Thunder Bluff får snabbt högsta prioritet. När han varnas för den hämndlystna vindormen Arikara vill han kalla fram besten och förgöra den innan den kan hota Cairne Bloodhoof.",al={"vad vill motega","motega firemanes mål","vad försöker motega göra"}},["12cba981"]={q="Varför är Motega Firemane här?",a="Motega reste ner i Thousand Needles för att iaktta och studera de exotiska bestar som lever på kanjonens botten och de omgivande platåbergen. Whitereach Post fungerar som basläger för hans forskning, men lokala problem, från försvunna följeslagare till hotfulla mytiska ormar, drar honom ofta bort från studierna.",al={"varför är motega i thousand needles","vad förde motega till whitereach post","motega firemanes syfte"}}},fp="15,267,22.511.0,20.632.1,22.483.1,23.204.0,35.140.0,38.275.1,56.248.1,44.276.1,45.212.0"}
P.entries["npc:mountaineer-barleybrew"] = {n="Mountaineer Barleybrew",s="Mountaineer Barleybrew är en bergsvakt från Ironforge, stationerad vid South Gate Outpost i Dun Morogh. Han vaktar passet österut mot Loch Modan och förlitar sig på kraftiga dvärgbrygder för att hålla vaktposterna alerta i den bitande kylan.",h="Mountaineer Barleybrew är en bergsvakt från Ironforge, stationerad vid South Gate Outpost i Dun Morogh.",kw={"barleybrew","dun morogh","bergsvakt","shimmer stout","south gate outpost","wellart"},ang={["race:Dwarf"]="För dvärgar står Barleybrew för den viktiga balansen mellan gränstjänst och starka förfriskningar som håller Khaz Modan säkert."},sec={{t="Vakt vid det östra passet",b="Mountaineer Wellart Barleybrew står vid South Gate Outpost och vaktar den snöiga vägen mot Loch Modan som en del av Ironforges gränsvakt. Liksom många bergsvakter som tjänstgör i Dun Moroghs isande vindar uppskattar han styrkan hos ett gott dvärgbryggt öl. Han bär den berömda Barleybrew-klanens namn och hjälper till att se till att leveranser av kraftig Shimmer Stout når andra vakter som behöver värme och uthållighet under långa skift längs bergspassen."}},faq={{q="Var hittar jag Mountaineer Barleybrew?",a="Mountaineer Barleybrew är stationerad vid South Gate Outpost, dvärgarnas befästning som vaktar det östra passet mellan Dun Morogh och Loch Modan.",al={"barleybrews plats","var finns mountaineer barleybrew","barleybrew npc"}},{q="Vad har han för uppgift vid South Gate Outpost?",a="Han tjänstgör som vakt i bergen, skyddar vägen och hjälper till att samordna förråd, däribland Shimmer Stout till andra bergsvakter som är stationerade längs passen.",al={"barleybrews uppgift","vad gör barleybrew"}},{q="Är han släkt med de andra Barleybrew?",a="Ja. Hans bror är bryggaren Rejold Barleybrew, och han kan också vara släkt med Marleth, Malgin och Yorus Barleybrew.",al={"barleybrews familj","yorus barleybrews släkting"}}},fx={["583559ff"]={q="Vem är Mountaineer Barleybrew?",a="Mountaineer Wellart Barleybrew är en dvärgisk vaktpost som försvarar Dun Moroghs östra gränser. Liksom alla bergsvakter från Ironforge håller han vakt mot bestar, troggar och frosttroll som hotar bergsvägarna, samtidigt som han förenar sin stränga gränstjänst med dvärgarnas särskilda förkärlek för gott öl.",al={"vem är mountaineer barleybrew","vem är barleybrew","mountaineer barleybrews bakgrund"}},["399d0350"]={q="Vilken sida står Mountaineer Barleybrew på?",a="Han är en ståndaktig soldat från Ironforge och lojal mot Alliansen. Han lyder Bronzebeard-klanens och kung Magnis order och ser till att resenärer och viktiga bergspass i riket är trygga.",al={"mountaineer barleybrews fraktion","vem tjänar barleybrew","är barleybrew med i alliansen"}},fc186c57={q="Vad vill Mountaineer Barleybrew?",a="Utöver att hålla vägen fri från inkräktare uppskattar Mountaineer Barleybrew ett kraftigt öl som värmer i den iskalla bergsluften. Han förlitar sig på förbipasserande resenärer för att förmedla meddelanden och förnödenheter, däribland en skvätt stark Shimmer Stout, mellan sin postering och närliggande allierade.",al={"vad vill barleybrew","vad behöver wellart barleybrew","vad letar barleybrew efter"}},b2269341={q="Varför är Mountaineer Barleybrew här?",a="Han är placerad vid passet vid South Gate Outpost för att vakta den viktiga vägen mellan Dun Morogh och Loch Modan. De höga passen hotas regelbundet av kringströvande vilddjur och aggressiva troggkrigarskaror, så disciplinerade bergsvakter måste hålla portarna befästa och säkra.",al={"varför är barleybrew vid south gate","varför är mountaineer barleybrew stationerad här","varför är barleybrew på den platsen"}}},fp="22,147,27.390.0,40.145.0,39.151.0,39.116.0"}
P.entries["npc:mountaineer-kadrell"] = {n="Mountaineer Kadrell",s="Mountaineer Kadrell är en pålitlig dvärgväktare som är stationerad mitt emot Stoutlager Inn i Thelsamar. Som viktig förbindelselänk inom Loch Modans Mountaineers samordnar han spaning, leveranser av förnödenheter och gränsförsvar i hela regionen.",h="Mountaineer Kadrell är en pålitlig dvärgväktare som är stationerad mitt emot Stoutlager Inn i Thelsamar.",kw={"kadrell","loch modan","mountaineer","rockgar","stormpike","stoutlager inn","thelsamar"},ang={["faction:Alliance"]="Kadrell förlitar sig på alliansresenärer som passerar genom Thelsamar för att bära meddelanden och hjälpa avlägsna mountaineer-utposter som kämpar mot hoten i regionen.",["race:Dwarf"]="Som en del av den berömda Mountaineer-kåren representerar Kadrell den främre bevakningen som skyddar Ironforges östra territorier från hoten i den framryckande vildmarken."},sec={{t="Thelsamars väktare",b="Mountaineer Kadrell håller vakt i den livliga bosättningen Thelsamar och är en hörnsten i dvärgarnas försvar i Loch Modan. Utposterna vid dalens utkanter utsätts för ständiga angrepp från troggar, gnoller och traktens vilda djur, medan Kadrell stannar mitt i staden för att organisera förstärkningar, vidarebefordra order och bedöma rapporter från kringvandrande spejare."},{t="Hålla förbindelserna öppna",b="Kadrells uppgifter innebär ofta att hålla kontakten mellan Thelsamar och avlägsna framskjutna positioner. Han samordnar med Mountaineer Stormpike eller skickar äventyrare för att rapportera till väktare som Mountaineer Rockgar, och ser till att de isolerade utposterna som bevakar bergspassen får viktiga förnödenheter, förstärkningar och försvarsunderrättelser."}},faq={{q="Var hittar man Mountaineer Kadrell?",a="Kadrell är stationerad precis mitt emot vägen från Stoutlager Inn i staden Thelsamar, bland de böljande kullarna i Loch Modan.",al={"kadrells plats","var finns kadrell","hitta kadrell"}},{q="Vilken roll har Kadrell i Loch Modan?",a="Han tillhör dvärgarnas Mountaineers och har i uppgift att vara förbindelselänk mellan Thelsamars lokala ledning och de avlägsna vaktposterna runtom i regionen. Han samordnar patruller, förnödenheter och gränsrapporter.",al={"vad gör kadrell","kadrells uppgift","kadrells arbete"}},{q="Varför skickar andra mountaineers budbärare till Kadrell?",a="Eftersom han har en central plats intill värdshuset och huvudvägen i Thelsamar fungerar Kadrell som nav för fältrapporter. Han ser till att brådskande rapporter från avlägsna spejare når stadens försvarsnätverk.",al={"rapportera till kadrell","varför rapportera till kadrell"}},{q="Vilka samordnar Kadrell med?",a="Kadrell samarbetar ofta med andra mountaineers ute i fält, däribland Mountaineer Stormpike och Mountaineer Rockgar. Tillsammans hanterar de spaningsuppdateringar och försvarsuppdrag mot lokala hot.",al={"kadrells kontakter","vilka känner kadrell"}}},fx={fc9aa592={q="Vem är Mountaineer Kadrell?",a="Mountaineer Kadrell är en dvärgisk försvarare stationerad i Thelsamar. Som medlem av Mountaineers, Ironforges särskilda territoriella vaktstyrka, hjälper han till att övervaka försvaret av Loch Modan-regionen. Han organiserar lokal spaning och ser till att försörjningsleder och utposter är säkra.",al={"vem är kadrell","mountaineer kadrell","kadrells identitet"}},["24c7e32d"]={q="På vems sida står Mountaineer Kadrell?",a="Kadrell står stadigt på kungariket Ironforges och Alliansens sida. Hans plikter innebär att han tjänar King Magni Bronzebeard och samarbetar med andra bergsvakter, stadsvakter och lokala dvärgar för att hålla Khaz Modans gränser mot hot som tränger sig på.",al={"kadrells fraktion","tillhör kadrell alliansen","kadrells lojalitet"}},["3819644d"]={q="Vad vill Mountaineer Kadrell?",a="Kadrell vill säkra Thelsamar och den omgivande vildmarken i Loch Modan. De lokala styrkorna är hårt ansträngda, så han söker skickliga resenärer som kan hjälpa till att rensa tunnlarna från råttkobolder i de västra utlöparna, kringströvande gnollflockar och andra skadedjur som hotar vägarna och avlägsna vaktstationer.",al={"vad vill kadrell","kadrells mål","kadrells uppgifter"}},["56ea1ebe"]={q="Varför är Mountaineer Kadrell i Thelsamar?",a="Kadrell är stationerad mitt emot Stoutlager Inn för att fungera som en central kontaktpunkt i Thelsamar. Eftersom staden är Loch Modans främsta knutpunkt kan han ta emot rapporter från avlägsna vaktposter och skicka resenärer dit hjälpen behövs mest.",al={"varför är kadrell i thelsamar","varför är kadrell här","kadrells postering"}},f9923f59={q="Vilka har Mountaineer Kadrell band till?",a="Kadrell har nära band till nätverket av Ironforge-bergsvakter som patrullerar dalen, däribland Mountaineer Stormpike och Mountaineer Rockgar. Han samordnar sig med utposternas spanare runt Loch Modan för att förmedla information och förstärkningar dit gränsposterna är hårt ansatta.",al={"kadrells kontakter","vilka arbetar kadrell med","kadrells band"}}},fp="19,93,23.291.0,22.311.0,39.122.0,37.199.0,50.198.0,33.192.0"}
P.entries["npc:mountaineer-stormpike"] = {n="Mountaineer Stormpike",s="Mountaineer Stormpike är en bergsvakt från Ironforge, stationerad vid Algaz Station i norra Loch Modan. Han vakar över bergspasset mot Wetlands och arbetar outtröttligt för att hålla viktiga försörjningsleder säkra från lurande troggs och kobolder. Som stolt medlem av Stormpike-klanen är han trogen Ironforge och dvärgarnas länder.",h="Mountaineer Stormpike är en bergsvakt från Ironforge, stationerad vid Algaz Station i norra Loch Modan.",kw={"algaz","dun","kobold","loch","modan","bergsvakt","station","stormpike","wetlands"},ang={["faction:Alliance"]="Algaz Station är en knutpunkt på den viktiga landvägen mellan Ironforge och Menethil Harbor i Wetlands. Därför är Stormpikes vaksamhet avgörande för Alliansens logistik.",["race:Dwarf"]="För en dvärg från Ironforge är det en hedersplikt att hjälpa en annan bergsvakt som Stormpike och skydda Khaz Modans inre gränser mot asätande skadedjur."},sec={{t="Väktare vid Algaz Station",b="Algaz Station ligger vid Loch Modans norra gräns och är en viktig kontrollpost före den farliga nedstigningen till Wetlands. Mountaineer Stormpike är stationerad här, bland klippiga berg och ständiga faror i vildmarken. Hans främsta uppgift är att upprätthålla kommunikationslinjen och hålla vägarna öppna för resenärer och försörjningskaravaner genom Dun Algaz."},{t="Kampen mot lokala hot",b="Loch Modans norra delar plågas av ständiga skadedjur, från kobolder som tagit över närliggande utgrävningar till underjordiska troggs. Stormpike ber regelbundet äventyrare på genomresa att slå tillbaka hoten, särskilt kobolderna som tagit sig in i Silver Stream Mine och lagt sina smutsiga tassar på Miners' Leagues lagrade dvärgverktyg."}},faq={{q="Var hittar jag Mountaineer Stormpike?",a="Han är stationerad vid Algaz Station i norra Loch Modan, längs bergsvägen som leder norrut genom Dun Algaz-passet mot Wetlands.",al={"stormpikes plats","var finns stormpike","mountaineer stormpikes plats"}},{q="Vem är Mountaineer Stormpike?",a="Han är en bergsvakt från Ironforge och tillhör den berömda Stormpike-klanen. Han tjänstgör som vakt och spejare vid en utpost och har i uppdrag att säkra Loch Modans norra pass mot faror i den omgivande vildmarken.",al={"vem är stormpike","mountaineer stormpikes bakgrund","vem är mountaineer stormpike"}},{q="Vilka hot hanterar han vid Algaz Station?",a="Utposten utsätts ofta för intrång av troggs och kobolder som håller till på sluttningarna och i stenbrotten. Stormpike arbetar för att undanröja hoten så att kurirlinjer och karavaner kan passera säkert.",al={"faror vid algaz station","vad attackerar algaz station","hot i norra loch modan"}},{q="Vad är syftet med Algaz Station?",a="Algaz Station fungerar som en utpost för Ironforge som bevakar gränsen mellan Loch Modan och Dun Algaz karga tunnlar. Den är en rastplats för bergsvakter som patrullerar gränsen och håller handelsvägen fri.",al={"vad är algaz station","algaz stations bakgrund","algaz stations syfte"}},{q="Är han släkt med Stormpike Guard i Alterac Valley?",a="Han bär namnet från den framstående Stormpike-klanen, en dvärgsläkt som är välkänd i Ironforge för sina krigare och prospektörer. Hans närmaste order håller honom dock utplacerad längs passen i Loch Modan.",al={"stormpike i alterac","stormpike-klanens koppling","tillhör han stormpike guard"}},{q="Vilka uppdrag ger Mountaineer Stormpike äventyrare?",a="Han skickar äventyrare för att hämta tillbaka Miners' Leagues utrustning från det koboldinfesterade Silver Stream Mine och för att bära hans beställning av en ny sköld hela vägen till dvärgarnas pansarsmed Furen Longbeard i Stormwind.",al={"stormpike-uppdrag","mountaineer stormpikes uppgifter","uppdraget med smutsiga tassar"}}},fx={["21d9c7b3"]={q="På vems sida står Mountaineer Stormpike?",a="Mountaineer Stormpike är djupt lojal mot Ironforge och Bronzebeard-klanen och tjänar stolt bland dvärgarnas Mountaineers. Han vaktar bergspasset på uppdrag av King Magni Bronzebeard och står stadigt på Alliansens sida. Han hyser en djup misstro mot Dark Iron-klanen.",al={"mountaineer stormpikes fraktion","vem tjänar mountaineer stormpike","stormpikes lojalitet"}},["1b65a761"]={q="Vad vill Mountaineer Stormpike?",a="Stormpike är stationerad längs den karga norra vägen och vill hålla passet säkert från troggar, kobolder och andra hot som kommer ner från kullarna. Han söker pålitliga kurirer och dugliga kämpar som kan leverera varor, rensa bort skadedjur som tränger sig på och upprätthålla förbindelserna mellan Algaz Station och resten av Loch Modan.",al={"vad vill stormpike","stormpikes mål","mountaineer stormpikes uppgift"}},["60d9a34d"]={q="Varför är Mountaineer Stormpike här vid Algaz Station?",a="Algaz Station vaktar den viktiga norra rutten som förbinder Loch Modan med Wetlands. Stormpike är placerad här för att bevaka passet, samordna patruller och se till att förnödenheter och rapporter når fram säkert mellan de utspridda bergsutposterna och Ironforges större försvarsnätverk.",al={"varför är mountaineer stormpike här","varför är stormpike vid algaz station","orsak till stormpikes placering"}}},fp="21,201,25.307.0,29.246.0,39.141.0,29.143.0,48.152.0,32.213.0,55.200.0,58.212.0"}
P.entries["npc:mountaineer-thalos"] = {n="Mountaineer Thalos",s="Mountaineer Thalos är en dvärgvakt vid Coldridge Pass mynning i Coldridge Valley. Han har fått i uppdrag att bevaka vägen och varnar resande för det plötsliga angreppet av troggs som täpper till tunneln. Äventyrare med brådskande rapporter från dalen förlitar sig på att han visar dem den säkra vägen mot Kharanos.",h="Mountaineer Thalos är en dvärgvakt vid Coldridge Pass mynning i Coldridge Valley.",kw={"coldridge pass","coldridge valley","dun morogh","bergsvakt från ironforge","kharanos","mountaineer thalos","senir whitebeard","troggs"},ang={["faction:Alliance"]="Thalos håller kommunikationen igång längs den viktiga bergsvägen som förbinder dalens försvarsstyrkor med Ironforges centrala befäl.",["race:Dwarf"]="För unga dvärgar som lämnar sitt hemlands barnkammare är Thalos en allvarlig påminnelse om att hotet från troggs inte är någon vanlig övning, utan en belägring som pressar hårt mot Ironforges gränser.",["race:Gnome"]="Gnomer som lämnar Gnomeregans flyktingläger finner Thalos på vakt längs den huvudsakliga landvägen mot Kharanos och Ironforge."},sec={{t="Väktare av Coldridge Pass",b="Vid den snötäckta gränsen där Coldridge Valley övergår i de djupare klipporna i Dun Morogh står Mountaineer Thalos som första försvarslinje för resande som lämnar dvärgarnas träningsmarker. Coldridge Pass har blivit en förrädisk flaskhals, översvämmad av fientliga troggs som grävt sig upp från djupen under jorden. Thalos håller vakt i kylan, varnar de oförberedda att vända om och bedömer om härdade kurirer har mod nog att kämpa sig igenom till det vidsträckta kungariket."},{t="En kurirs vägspärr",b="När Grelin Whitebeard har avslutat sin rapport om Frostmane-trollens rörelser i den avskilda dalen får kuriren som ska överlämna den till hans bror Senir i Kharanos rådet att tala med Mountaineer Thalos innan tunneln beträds. När Thalos har försäkrat sig om att en äventyrare klarar den angripna passagen visar han vägen vidare till Kharanos, där regionala befälhavare samordnar försvaret av Dun Morogh. Hans vaksamma närvaro ser till att viktig information når Ironforges militära ledare i stället för att försvinna i snön."}},faq={{q="Vem är Mountaineer Thalos?",a="Mountaineer Thalos är en bergsvakt från Ironforge som är stationerad vid den södra öppningen till Coldridge Pass. Hans post bevakar gränsen mellan Coldridge Valley och de vidsträckta områdena i Dun Morogh.",al={"thalos historia","vem är thalos","mountaineer thalos"}},{q="Varför varnar Mountaineer Thalos resande?",a="En våldsam invasion av Rockjaw-troggs har tagit över Coldridge Pass. Thalos varnar civila och oerfarna kämpar för att försöka ta sig igenom och släpper bara in dugliga kurirer och härdade kämpar.",al={"varför är passet stängt","troggs i passet","fara i coldridge pass"}},{q="Vart skickar Mountaineer Thalos äventyrare?",a="Efter att ha granskat brådskande fältrapporter från Coldridge Valley visar Thalos resande genom passet mot Kharanos, den närmaste bosättningen på vägen till Ironforge.",al={"vart går jag efter thalos","thalos destination","nästa stad"}},{q="Vilken rapport får Thalos från Senir Whitebeard?",a="Ingen från Senir själv. Rapporten som passerar Thalos är Grelin Whitebeards redogörelse för hotet från Frostmane-trollen i Coldridge Valley, som en kurir bär till Grelins bror Senir i Kharanos. Thalos varnar budbäraren för troggsen och skickar vidare dem genom tunneln.",al={"senirs iakttagelser","senirs rapport","vad läser thalos"}},{q="Vilken fraktion tillhör Mountaineer Thalos?",a="Thalos är en svuren medlem av Ironforge Mountaineers, de härdade gränsvakterna som patrullerar Dun Moroghs gränser, tunnlar och snötäckta bergsstigar för Alliansen.",al={"thalos fraktion","är thalos från ironforge","alliansens bergsvakter"}},{q="Är Coldridge Pass oframkomligt utan att tala med Thalos?",a="Passet är fysiskt öppet för alla som vågar gå in i det, men genom att tala med Thalos ser en äventyrare till att viktiga spaningsuppgifter når Kharanos och får veta vilka faror som väntar längre fram.",al={"måste jag tala med thalos","gå förbi thalos"}}},fx={["37207617"]={q="Vad vill Mountaineer Thalos?",a="Mountaineer Thalos vill hålla resenärer säkra genom att varna dem för det förrädiska Coldridge Pass. Tunneln har tagits över av fientliga troggar, så den är farlig att ta sig igenom för den som inte är förberedd. När han möter äventyrare med brådskande ärenden uppmanar han dem att gå försiktigt genom tunneln och föra Grelin Whitebeards rapport säkert vidare till hans bror Senir i dvärgstaden Kharanos.",al={"vad vill thalos","thalos mål","mountaineer thalos uppgift"}},ae07b8df={q="Vilka har Mountaineer Thalos band till?",a="Thalos tjänar som vaktpost för Ironforges bergsvakter och bevakar stigen som leder ut ur Coldridge Valley. Kurirer som bär Grelin Whitebeards rapport om Frostmane-trollen till Grelins bror Senir Whitebeard i Kharanos får tala med Thalos innan de ger sig in i den troggfyllda tunneln.",al={"thalos allierade","vilka arbetar thalos med","thalos och senir whitebeard"}}},fp="18,176,26.347.0,22.404.0,26.156.0,49.148.0,47.111.0,54.263.0,47.144.0,56.141.0"}
P.entries["npc:mr-smite"] = {n="Mr. Smite",s="Mr. Smite är en väldig tauren och förste styrman på Defias Brotherhoods flaggskepp, djupt inne i The Deadmines. Som vapenspecialist under Captain Greenskin behärskar han vägen från kajen till det gömda slagskeppet med järnhård disciplin. Inkräktare som möter honom måste stå emot hans skiftande arsenal och förödande fysiska styrka.",h="Mr.",kw={"captain greenskin","the deadmines","förste styrman","ironclad cove","mr smite","mr. smite","smite's mighty hammer","smite's reaver","taurenpirat","thief's blade"},ang={["class:Warrior"]="Smite visar prov på anmärkningsvärd stridsdisciplin och växlar sömlöst mellan snabba enhandsattacker, dubbla yxor och skoningsamma slag med tvåhandshammaren.",["faction:Alliance"]="Smite är det främsta hindret för Alliance-agenter som försöker storma landgången och nå Captain Greenskin och Edwin VanCleef.",["race:Tauren"]="För en resenär från Mulgore är det en skakande syn att se en annan tauren tjäna som hänsynslös förste styrman bland sjöfarande laglösa i Eastern Kingdoms."},sec={{t="Förste styrman i viken",b="Mr. Smite vaktar kajerna i Ironclad Cove och tjänar som förste styrman åt goblinen Captain Greenskin. Defias Brotherhood består till största delen av rättslösa människor och deras allierade goblinuppfinnare, men Smite är ett slående undantag: en väldig, stridsvan tauren långt från Kalimdors slätter. Han har fått i uppdrag att hålla ordning på ett stökigt piratmanskap och ser till att arbetet med att färdigställa Edwin VanCleefs hemliga slagskepp fortgår utan avbrott."},{t="En dödlig vapenspecialist",b="Smite är inte bara en råbarkad upprätthållare av ordningen, utan också en teatralisk och mångsidig vapenspecialist. Han njuter av att leka med blivande hjältar och drar medvetet ut på striden för att ge motståndarna falska förhoppningar. När han pressas släpper han lös en häpnadsväckande, jordskakande stampning som bedövar fienderna medan han rotar i sin närliggande vapenkista. Han inleder striden med en smidig duellklinga, går sedan över till två klyvyxor och tar till sist fram sin kolossala tvåhandshammare när han blir riktigt provocerad."}},faq={{q="Varför arbetar en tauren med mänskliga banditer i Westfall?",a="De flesta tauren bor i Kalimdor tillsammans med sina Horde-allierade, men legosoldater som hamnat utanför och kringvandrande tauren tar sig ibland österut. Smite tjänar Defias Brotherhood som Captain Greenskins förste styrman och håller manskapet i schack i viken medan slagskeppet görs klart för att gå till sjöss.",al={"varför tauren i deadmines","mr smites bakgrund","taurenpirat"}},{q="Vem är Mr. Smites överordnade?",a="Smite lyder direkt under Captain Greenskin, goblinen som leder piratskeppet för ankar i Ironclad Cove. Över dem båda i sammansvärjningen står Edwin VanCleef, Defias Brotherhoods övergripande ledare.",al={"vem är smites chef","vem arbetar mr smite för"}},{q="Vilka vapen använder Mr. Smite under striden?",a="Smite inleder striden med Thief's Blade. När striden vänder emot honom drar han sig tillbaka till sin kista och tar på sig ett par Smite's Reavers, och till sist plockar han fram Smite's Mighty Hammer när han pressas till det yttersta.",al={"smites vapen","vad tar smite fram ur kistan"}},{q="Var hittar man Mr. Smite?",a="Mr. Smite står vakt på träbryggorna i Ironclad Cove, den sista grottan i The Deadmines, och bevakar landgången upp till Defias jättelika slagskepp.",al={"mr smites plats","var är smite"}},{q="Strider Mr. Smite ensam?",a="Smite håller två smygande Defias-rövare gömda vid sin sida, redo att överfalla alla inkräktare som går längs bryggan mot skeppet.",al={"smites förstärkningar","smites livvakter"}},{q="Vad gör Mr. Smite så farlig på nära håll?",a="Hans signaturförmåga, taurens War Stomp, skickar chockvågor genom träkajen och bedövar hela äventyrargrupper så länge att han hinner rusta om från sin fotkista och återuppta anfallet med tyngre vapen.",al={"smites bedövning","smites war stomp"}}},fx={ecfcf591={q="Vem är Mr. Smite?",a="Mr. Smite är en väldig tauren-vapenmästare som tjänar som styrman ombord på det jättelika skepp som gömts djupt inne i The Deadmines. Han lyder direkt under Captain Greenskin, leder Defias Brotherhoods hamnförsvar och håller deras skurkar i schack med järnhand och ett förråd av dödliga vapen.",al={"vem är smite","mr. smites identitet","vad är mr. smite"}},["8cad5068"]={q="På vems sida står Mr. Smite?",a="Trots att Mr. Smite är tauren svär han ingen trohet till Horden eller sitt folk i Kalimdor. Han står helt på Edwin VanCleefs Defias Brotherhoods sida och är andreman under deras goblinske sjöbefälhavare, Captain Greenskin.",al={"mr. smites fraktion","vem arbetar smite för","är smite horde eller defias"}},["1c026e95"]={q="Varför är Mr. Smite berömd eller fruktad?",a="Smite är fruktad för sin råa fysiska brutalitet och oberäkneliga skicklighet i strid. Han är ökänd för att leka med sina offer och låta dem tro att de fått övertaget, innan han bedövar dem med ett jordskakande stamp och drar allt dödligare vapen ur sin kista för att göra slut på dem.",al={"varför är mr. smite fruktad","mr. smites rykte","varför är smite berömd"}}},fp="9,286,22.383.0,21.441.0,55.239.0,28.197.0,49.156.0,29.143.0,27.116.0,52.171.0"}
P.entries["npc:mull-thunderhorn"] = {n="Mull Thunderhorn",s="Mull Thunderhorn är en taurenäldste som bor i Bloodhoof Village i Mulgore. Han är djupt hängiven Jordmodern och landets balans och vakar över de heliga vattenkällorna som finns utspridda över slätterna. När utomstående exploatörer hotar områdets livgivande vatten vägleder Mull unga tauren genom ritualerna som krävs för att rena förfädernas källor.",h="Mull Thunderhorn är en taurenäldste som bor i Bloodhoof Village i Mulgore.",kw={"bloodhoof village","mulgore","mull thunderhorn","förgifta vatten","thunderhorn-totem","venture company","vattenkällor","rening av wildmane","rening av winterhoof"},ang={["class:Druid"]="Druider delar Mulls brådska och ser med egna ögon hur de förorenade vattenkällorna förgiftar balansen i Mulgorebornas djurliv.",["class:Shaman"]="Schamaner känner igen Mulls tillit till elementens harmoni, då hans reningstotem använder förfädersandar för att läka vatten som slitits sönder av mekanisk girighet.",["faction:Horde"]="Mulls kamp belyser Hordens motsättningar med oberoende och exploaterande organisationer som Venture Company, som utarmar Kalimdors rikedomar utan lov.",["race:Tauren"]="För tauren står Mull Thunderhorn för stammarnas minne och förfädernas plikt. Han vägleder unga krigare i att skydda de heliga slätterna mot giriga utländska inkräktare."},sec={{t="Väktare av de heliga vattnen",b="Mull Thunderhorn vakar i Bloodhoof Village och bär ansvaret för Mulgorebornas andliga välbefinnande. De nomadiska stammarna har samlats under högöverhövding Cairne Bloodhoof för att grunda ett permanent hem, men deras marker hotas redan av girighet och vårdslös expansion. Mull är ett andligt stöd för de unga krigare som lämnar Camp Narache och uppmanar dem att skydda sina förfäders livsviktiga resurser."},{t="Förgiftade källor och Venture Company",b="Den främsta krisen Mull står inför är den sjukdom som plötsligt sprider sig genom Mulgorebornas vattenkällor: Winterhoof-, Thunderhorn- och Wildmane-källorna. Denna otäcka farsot spåras till Venture Companys gobliner, ett samvetslöst handelsföretag som etablerar verksamhet i de omgivande kullarna och dumpar gifter i det lokala grundvattnet. Mull ger unga tauren i uppdrag att förbereda särskilda reningstotemer och utföra reningsriter vid varje förfäderskälla innan föroreningen sprider sig oåterkalleligt till marken och dess djurliv."}},faq={{q="Vem är Mull Thunderhorn?",a="Mull Thunderhorn är en uppdragsgivare av rasen tauren i Bloodhoof Village i Mulgore. Han vakar över områdets heliga vattenkällor och erbjuder riter och ritualer för att hålla jorden och dess vatten rena från yttre föroreningar.",al={"mull thunderhorns historia","vem är mull","mull i bloodhoof village"}},{q="Varför oroar sig Mull Thunderhorn för vattenkällorna?",a="Förfädernas vattenkällor, som Winterhoof-, Thunderhorn- och Wildmane-källorna, är livgivande vatten för stammarna och djurlivet i Mulgore. Närliggande intrång har förorenat dessa heliga källor med giftigt avfall och utsläpp och hotar slätternas naturliga balans.",al={"varför är källorna förgiftade","vattenkällor i mulgore","förgiftad winterhoof-källa"}},{q="Vem förorenar vattenkällorna i Mulgore?",a="Föroreningen orsakas av Venture Company, ett vårdslöst goblinföretag som etablerar industriella fästen för gruvdrift och skogsavverkning längs Mulgorebornas utkanter. Deras verksamhet visar ingen hänsyn till det heliga landskapet och släpper ut industriella gifter i det lokala grundvattnet.",al={"vem förgiftade vattnet","venture company i mulgore","vem förorenade källorna"}},{q="Varför handlar Mulls reningsuppdrag bara om tauren?",a="Vattenkällorna har djup förfädersmässig och andlig betydelse för taurenstammarnas grundande släktlinjer, däribland klanerna Thunderhorn, Winterhoof och Wildmane. Att rena dem betraktas som en helig övergångsrit och en kulturell plikt för tauren som håller på att bli vuxna.",al={"uppdrag bara för tauren","varför bara tauren","mull thunderhorns krav"}},{q="Hur renas vattenkällorna?",a="Mull instruerar resenärer att sätta samman särskilt välsignade totem med offergåvor från landet, som tassar, näbbar, klor och tänder från Mulgorebornas bestar. När totemen har välsignats förs de direkt till de förorenade källorna för att kanalisera andlig rening och tvätta bort de onaturliga gifterna.",al={"hur renar man källorna","reningstotem","rena vattnet"}},{q="Vad är Synens rit?",a="Synens rit är en grundläggande andlig resa som unga tauren företar för att kommunicera med sina förfäder och djurandar. De som ska invigas skickas till Zarlman Two-Moons i Bloodhoof Village för att genomgå denna visionära prövning som en av Jordmoderns riter.",al={"uppdraget synens rit","vad är synens rit"}}},fx={["7b9ffdeb"]={q="På vems sida står Mull Thunderhorn?",a="Mull är lojal mot sitt folk och Horden och hängiven stammarna i Mulgore. Som en respekterad medlem av Bloodhoof Village vakar han över de förfäders slätter och hörsammar den andliga kallelsen att skydda sitt folk och dess heliga land från yttre korrumpering.",al={"mull thunderhorns fraktion","tillhör mull horden","vem tjänar mull"}},be00c091={q="Vad vill Mull Thunderhorn?",a="Mull vill återställa och rena Mulgores heliga vattenkällor, däribland Winterhoof-, Thunderhorn- och Wildmane-källorna. Han söker pålitliga tauren som kan tillverka traditionella totem och utföra de viktiga reningsriter som behövs för att häva den hemska förorening som hotar landets livsnerv.",al={"vad vill mull","mull thunderhorns mål","varför behöver mull hjälp"}}},fp="16,246,29.366.0,37.402.1,24.138.0,54.241.0,44.220.0,54.212.0,33.248.0,27.228.0"}
P.entries["npc:mupsi-shacklefridd"] = {n="Mupsi Shacklefridd",s="Utanför Ratchet i The Barrens hjälper Mupsi Shacklefridd resenärer att reparera sina relationer med Steamwheedle Cartel.",h="Utanför Ratchet i The Barrens hjälper Mupsi Shacklefridd resenärer att reparera sina relationer med...",kw={"the barrens","goblin","mupsi","ratchet","anseende","shacklefridd","steamwheedle"},sec={{t="I utkanten av Ratchet",b="Mupsi Shacklefridd arbetar längs kustvägen strax utanför Ratchet. Steamwheedle-vakter patrullerar hamnstadens utkanter medan köpmän kommer och går. Resenärer som är på kant med goblinerna kan försöka vinna tillbaka Steamwheedle Cartels välvilja genom Mupsi, om de tar med sig de förnödenheter och utför det arbete som krävs."}},faq={{q="Vem är Mupsi Shacklefridd?",a="Mupsi Shacklefridd är en goblin som är stationerad strax utanför Ratchet i The Barrens. Hon hjälper resenärer att återupprätta sitt anseende hos Steamwheedle Cartel.",al={"mupsi","vem är mupsi","ratchet mupsi"}},{q="Var hittar jag henne?",a="Du hittar Mupsi strax utanför Ratchet i The Barrens, där hamnvakter och patruller ibland passerar.",al={"mupsis plats","var finns mupsi shacklefridd","hitta mupsi"}},{q="Varför skulle någon prata med Mupsi Shacklefridd?",a="Om du har retat upp Steamwheedle Cartel kan Mupsi hjälpa dig att reparera ditt anseende med hjälp av förnödenheter. Det sker ofta efter bråk med gobliner eller när du tagit piraternas sida.",al={"läka gamla sår ratchet","lämna in för rykte ratchet","mupsi uppdrag"}}},fx={["8798c45f"]={q="På vems sida står Mupsi Shacklefridd?",a="Mupsi Shacklefridd hör till Steamwheedle Cartel och verkar under Ratchets hamnmyndighet. Liksom de flesta gobliner i bosättningen är hon affärsmässigt neutral gentemot både Alliansen och Horden. Hon sätter handel, material och mynt framför politisk krigföring.",al={"mupsi shacklefridds fraktion","vem arbetar mupsi för","är mupsi shacklefridd neutral"}},a81ff16f={q="Vad vill Mupsi Shacklefridd?",a="Mupsi söker hjälp åt de många sjömän som sårats i en sammandrabbning med Bloodsail Buccaneers. Hon ger folk chansen att vinna gunst och förbättra sitt ansträngda anseende hos Steamwheedle Cartel genom att ta med linnetyg till bandage och tomma flaskor till brygder.",al={"vad vill mupsi","mupsi shacklefridds motiv","varför hjälpa mupsi"}},["8b7e7b21"]={q="Varför är Mupsi Shacklefridd stationerad utanför Ratchet?",a="Hon är stationerad i utkanten av Ratchet och sköter kontakten med resenärer och logistiken för dem som närmar sig den livliga hamnen. Genom att hålla till strax utanför de centrala hamnbryggorna kan hon fånga upp handelsmän, utstötta och äventyrare som vill byta till sig förnödenheter eller reparera sina relationer med kartellen.",al={"varför är mupsi här","orsak till mupsi shacklefridds placering","varför är mupsi utanför ratchet"}}},fp="18,108,27.298.0,26.150.0,21.104.0,45.165.0"}
P.entries["npc:mutanus-the-devourer"] = {n="Mutanus the Devourer",s="Mutanus the Devourer är en monstruös, blek murloc som har frammanats direkt ur Emerald Nightmare. Den lurar i de mörkaste skrymslena av den sovande dru iden Naralexs sinne och träder fram för att sluka alla som försöker bryta mardrömmens grepp om Wailing Caverns. Att döda denna förvridna varelse är det sista steget för att befria Naralex från hans plågade slummer.",h="Mutanus the Devourer är en monstruös, blek murloc som har frammanats direkt ur Emerald Nightmare.",kw={"albinofärgad murloc","the barrens","deep fathom ring","devourer","emerald nightmare","murloc","mutanus","naralex","wailing caverns"},ang={["class:Druid"]="Mutanus visar hur fruktansvärda faror som väntar den som tränger för djupt in i Emerald Dream utan skydd, när en annan druids sinne helt togs över av fördärvelsen.",["faction:Horde"]="Horden kan inte låta Mutanus och mardrömmen fördärva hjärtat av The Barrens och hota de livsviktiga oasvattnen som försörjer Durotar och Mulgore.",["race:NightElf"]="För kaldorei är Mutanus en tragedi som fått liv, en påminnelse om hur Naralex ädla ambition att hela The Barrens förvandlades till en monstruös mardröm."},sec={{t="En drömmarens värsta fruktan",b="När nattalvsdruiden Naralex utnyttjade de underjordiska källorna under The Barrens ville han återställa liv i de torra ödemarkerna genom att förbinda dem med The Emerald Dream. I stället invaderade en uråldrig fördärvelse, känd som Emerald Nightmare, hans tankar. Fångad i en plågsam syn tog Naralexs undermedvetna rädslor fysisk form. Fördärvelsen gav mardrömmen skepnaden av en väldig, albinofärgad murloc."},{t="Den vakna mardrömmen",b="Mutanus sändes ut i den vakna världen av den mörka kraft som hemsökte Naralexs sinne, med uppgiften att se till att druiden aldrig vaknar. När en Disciple of Naralex utför ritualen för att återuppliva sin mästare bryter Mutanus igenom gränsen mellan dröm och verklighet. Så länge Mutanus lever är Naralex fånge i sin egen fördärvade fantasi."}},faq={{q="Vad är Mutanus the Devourer?",a="Mutanus the Devourer är en enorm, blek, murlocliknande varelse som fötts ur Emerald Nightmare. Han är ingen vanlig invånare på Azeroth, utan en levande mardröm som frammanats till verkligheten ur den sovande dru iden Naralexs fördärvade sinne.",al={"vem är mutanus","vilken sorts varelse är mutanus","är mutanus en murloc"}},{q="Varför ser Mutanus ut som en jättelik murloc?",a="Mutanus är en gestaltning av Naralexs mardröm, och fördärvelsen gav den formen av en kolossal albinofärgad murloc. Ingen vet varför mardrömmen valde just den skepnaden.",al={"varför murloc","varför är mutanus en murloc","naralex rädsla för murlocer"}},{q="Varför dyker Mutanus upp i slutet av ritualen?",a="Den mörka närvaro som fördärvar Emerald Dream beordrade Mutanus att hindra alla från att bryta Naralexs slummer. När Naralexs lärjungar inleder uppvakningsritualen tar sig Mutanus över till den fysiska grottan för att sluka räddarna.",al={"när dyker mutanus upp","varför framkalla mutanus","naralex ritualboss"}},{q="Var kommer Mutanus ifrån?",a="Mutanus har sitt ursprung i Emerald Nightmare, det fördärvade rike som har snärjt Naralex.",al={"mutanus ursprung","kommer mutanus från mardrömmen","emerald nightmare mutanus"}},{q="Räddar man Naralex genom att döda Mutanus?",a="Ja. När Mutanus har dödats krossas mardrömmens omedelbara grepp om Naralexs sinne. Då kan hans lärjungar väcka druiden och bryta grottans mörka trans.",al={"blir naralex räddad","vad händer när mutanus dör","väcka naralex"}},{q="Varför är Mutanus immun mot skuggmagi?",a="Mutanus är en avvikelse vävd av mörka mardrömsenergier, vilket gör honom naturligt motståndskraftig mot nekrotiska besvärjelser och skuggmagi som skulle skada vanliga bestar.",al={"mutanus immunitet mot skuggmagi","skuggmagi mot mutanus","är mutanus immun mot skuggmagi"}}},fx={c0fe9c52={q="Vad har Mutanus the Devourer för koppling?",a="Mutanus är direkt knuten till nattalvdruiden Naralex. Han är inget naturligt odjur från The Barrens, utan en fysisk manifestation som uppstått ur de mörkaste vrårna av Naralex eget fördärvade sinne. Han förkroppsligar druidens undermedvetna rädslor som en förvriden mardröm i den fysiska världen.",al={"mutanus koppling naralex","mutanus relation naralex","vem är mutanus knuten till"}},["1d17d2ec"]={q="På vems sida står Mutanus the Devourer?",a="Mutanus tjänar den mörka, korrumperande kraft som har infekterat The Emerald Dream och fångat Naralex i hans mardröm. Han agerar inte efter egna nycker eller för Barrens inhemska djurliv, utan lyder Mardrömmens vilja. Han har skickats till den vakna världen enbart för att se till att druiden fortsätter sova och vara korrumperad.",al={"vem styr mutanus","mutanus fraktion","mutanus lojalitet"}},["93f250d8"]={q="Vad vill Mutanus the Devourer?",a="Mutanus finns till för att hindra varje försök att väcka Naralex ur hans förvridna slummer. Han vill sluka alla som försöker befria den sovande druiden ur Mardrömmens grepp och se till att Naralex förblir hjälplös medan den mörka korrumperingen fortsätter att sprida sig i Wailing Caverns.",al={"mutanus mål","varför slåss mutanus","vad försöker mutanus göra"}}},fp="20,358,22.414.0,20.344.1,29.236.0,42.164.0,49.236.0,29.93.0,34.184.1,38.158.0"}
P.entries["npc:mux-manascrambler"] = {n="Mux Manascrambler",s="Mux Manascrambler är en excentrisk gobliningenjör som bor i ökenutposten Gadgetzan. Till skillnad från många av sina gelikar, som enbart fokuserar på sprängämnen eller gruvutrustning, hyser Mux en märklig fascination för det övernaturliga och ockulta krafter.",h="Mux Manascrambler är en excentrisk gobliningenjör som bor i ökenutposten Gadgetzan.",kw={"ektoplasma","gadgetzan","spöke","gobliningenjör","manascrambler","mux","tanaris"},ang={["profession:Engineering"]="Mux är en särling bland goblinuppfinnare. Han använder mekaniska kugghjul och kraftceller för att fånga in och destillera osynliga övernaturliga krafter i stället för att bara spränga saker i luften."},sec={{t="En uppfinnare av det osedda",b="Inne i en byggnad i centrala Gadgetzan, bakom Driz Plunkbow och hans skramlande Butcherbots, sitter Mux Manascrambler. Medan Steamwheedle Cartel handlar med olja, vapen och skrot, riktar Mux sin uppfinningsrikedom mot mer esoteriska sysslor: andarnas värld och övernaturliga fenomen. Han använder sin tekniska skicklighet till att konstruera bisarra apparater som kan upptäcka, destillera och interagera med spektrala rester, och förenar grovt goblinhantverk med de dödas osynliga världar."}},faq={{q="Var hittar jag Mux Manascrambler?",a="Mux bor i Gadgetzan i norra Tanaris. Du hittar honom inne i en byggnad nära mitten av öknens handelsnav, precis bakom Driz Plunkbow och hans köttstyckande Butcherbots.",al={"mux plats","var finns mux","mux manascrambler karta"}},{q="Vad arbetar Mux med?",a="Mux är en ingenjör som är besatt av spektrala och osedda krafter. I stället för vanlig sprängning eller transport bygger han specialanordningar som kan avslöja andar, destillera ektoplasma och utnyttja övernaturlig arkan kraft.",al={"mux yrke","vad säljer mux","mux forskning"}},{q="Tillhör Mux någon fraktion?",a="Mux tillhör Steamwheedle Cartel, som verkar från Gadgetzan. Som självständig goblinagent upprätthåller han strikt kommersiell neutralitet och hjälper gärna äventyrare från både Horde och Alliance.",al={"är mux horde","är mux neutral","mux alliance"}}},fp="17,249,24.504.0,35.208.0,30.236.0,29.215.0"}
P.entries["npc:mydrannul"] = {n="Mydrannul",s="Mydrannul är en Night Elf-handlare med allmänna varor på Warrior's Terrace i Darnassus. Han ser till att huvudstadens väktare, soldater och besökare har tillgång till grundläggande förnödenheter, ammunition och proviant.",h="Mydrannul är en Night Elf-handlare med allmänna varor på Warrior's Terrace i Darnassus.",kw={"ammunition","darnassus","allmänna varor","mydrannul","teldrassil","handlare","warrior's terrace"},ang={["faction:Alliance"]="Alliansresenärer som anländer till Teldrassil kan lita på att handlare som Mydrannul på Warrior's Terrace har basutrustning, ammunition och fältransoner.",["race:NightElf"]="För Night Elves som tränar i Darnassus tillhandahåller Mydrannul viktig vardagsutrustning och pilar så att väktarna har ordentligt med förnödenheter."},sec={{t="Förnödenheter på Warrior's Terrace",b="Bland Warrior's Terrace militära paviljonger och övningsområden förser Mydrannul både Darnassus försvarare och resande äventyrare med viktig utrustning. Hans varor omfattar praktiska vardagsföremål för livet i fält: ammunition till bågskyttar och skyttar, kastknivar, flinta, påsar och enkel proviant. Genom att sköta sitt stånd i stadens militära distrikt ser han till att väktarna och rekryterna som förbereder sig för tjänstgöring på Teldrassil har det nödvändigaste."}},faq={{q="Var hittar man Mydrannul?",a="Mydrannul finns på Warrior's Terrace, det militära distriktet i Darnassus sydöstra del, beläget på Teldrassils krona.",al={"mydrannuls plats","var finns mydrannul","mydrannuls karta"}},{q="Vilka varor säljer Mydrannul?",a="Han säljer allmänna varor som behållare, enkel proviant, dryck och verktyg för lägerlivet, till exempel flinta och fnöske, samt kastvapen och ammunition som pilar och kulor.",al={"mydrannuls varor","vad säljer mydrannul","mydrannuls handlarföremål"}},{q="Erbjuder Mydrannul några uppdrag?",a="Ja. Förutom att sälja förnödenheter skickar Mydrannul äventyrare till sin vän Nessa Shadowsong, en fiskhandlare i Rut'theran Village som behöver få ett paket levererat till Darkshore.",al={"mydrannuls uppdrag","uppdrag från mydrannul"}}},fx={cca0dfd1={q="Vem är Mydrannul?",a="Mydrannul är en nattalvshandlare som bor i Darnassus och arbetar i Warrior's Terrace. Han säljer allmänna varor i nattalvernas huvudstad och förser både resande, lokalbor och soldater med viktiga vardagsvaror, förnödenheter och ammunition.",al={"vem är mydrannul","mydrannuls identitet","mydrannul darnassus"}},["34e3a734"]={q="Vems sida står Mydrannul på?",a="Mydrannul är trogen Darnassus och Alliansen. Som nattalv som bor i hjärtat av deras heliga världsträd tjänar han gärna sitt folk och alla äventyrare från Alliansen som passerar genom staden.",al={"mydrannuls fraktion","mydrannuls lojalitet","är mydrannul med i alliansen"}},["6cf1b6fe"]={q="Varför är Mydrannul här?",a="Mydrannul har en butik i Warrior's Terrace i Darnassus där han utrustar dem som förbereder sig för patrullering eller långväga resor. Tack vare honom har stadens försvarare och vägfarare lätt tillgång till nödvändiga förnödenheter nära stadens träningsplatser.",al={"varför är mydrannul här","mydrannuls syfte i darnassus","vad gör mydrannul här"}},a5485425={q="Vad vill Mydrannul?",a="Mydrannul vill bedriva hederlig handel och erbjuder pålitliga småvaror, mat och ammunition till alla i Darnassus som vill handla med honom.",al={"vad vill mydrannul","mydrannuls mål","mydrannuls motiv"}}},fp="9,114,33.377.0,29.118.0,31.107.0,32.147.0"}
P.entries["npc:nalpak"] = {n="Nalpak",s="Nalpak är en tauren-druid och lärjunge som vakar över de oroliga Wailing Caverns i The Barrens. Från en hög klippgrotta med utsikt över grottöppningen värvar han äventyrare som passerar för att hejda mardrömmen som förvrider det underjordiska ekosystemet.",h="Nalpak är en tauren-druid och lärjunge som vakar över de oroliga Wailing Caverns i The Barrens.",kw={"druid i the barrens","deviate-hudar","naralex lärjungar","nalpak","naralex","tauren","wailing caverns"},ang={["class:Druid"]="För andra druider är Nalpak en dyster påminnelse om hur farligt det kan vara att röra vid The Emerald Dream när mörkret slår rot i det som var tänkt som en läkande ritual.",["race:Tauren"]="Nalpak står för taurenfolkets hängivenhet åt att läka Kalimdors uttorkade marker och vägrar överge uppdraget även när katastrofen drabbar drömmarna."},sec={{t="Väktaren ovanför grottorna",b="Nalpak sitter i en dold grotta direkt ovanför mynningen till Wailing Caverns och förblir trogen Naralex vision. Hans mästare ligger fångad i en förvriden slummer djupt där nere, och Nalpak arbetar för att hålla den spridande förvridningen stången. Han ber äventyrare samla deviate-hudar som ska användas till läder."}},faq={{q="Var finns Nalpak?",a="Nalpak finns i en grotta högt uppe på klippväggen, direkt ovanför den naturliga klippformationen som leder in i Wailing Caverns i centrala The Barrens.",al={"nalpaks plats","var finns nalpak","hitta nalpak"}},{q="Vem är Nalpak?",a="Han är en tauren-druid och en av Naralex lärjungar. Han har i uppgift att hålla uppsikt över de förvridna varelser som kommer ut ur Wailing Caverns medan hans mästare försöker återställa The Barrens genom The Emerald Dream.",al={"vem är nalpak","nalpaks historia"}},{q="Varför vill Nalpak ha deviate-hudar?",a="Nalpak vill undersöka hudarna från de deviate-varelser som hemsöker Wailing Caverns. Trots deras onda natur tror han att deras ovanliga hudar kan komma till nytta i lädertillverkning.",al={"varför deviate-hudar","uppdraget med deviate-hudar"}},{q="Vilken relation har Nalpak till Naralex?",a="Nalpak är en trogen elev och anhängare till druiden Naralex. Han är en av lärjungarna som skickats för att stödja det djärva försöket att väcka källorna i The Barrens till liv igen.",al={"är nalpak naralex lärjunge","nalpak och naralex"}}},fx={a6c930b7={q="Vems sida står Nalpak på?",a="Nalpak är lärjunge till Naralex och tjänar druiderna som försöker läka The Barrens. Han är en tauren som välkomnar dem som kommer in i grottorna för att hjälpa till, men hans främsta lojalitet ligger hos Naralex vision och återställandet av de fördärvade underjordiska källorna.",al={"nalpaks fraktion","vem tjänar nalpak","tillhör nalpak horden"}},ddc6c0b5={q="Varför är Nalpak i Wailing Caverns?",a="Nalpak kom till Wailing Caverns tillsammans med Naralex och andra lärjungar för att kanalisera The Emerald Dream till det torra The Barrens. När ritualen gick fruktansvärt fel stannade han vid grottans ingång för att värva äventyrare till att samla in fördärvade material och ta itu med de förvridna bestarna där inne.",al={"varför är nalpak här","varför är nalpak i wailing caverns","vad förde nalpak hit"}}},fp="6,259,25.309.0,24.154.0,14.216.0,35.190.0,41.173.0"}
P.entries["npc:nara-meideros"] = {n="Nara Meideros",s="I Stormwinds Park vägleder Nara Meideros unga sökare i Elunes lära. Som nattalvprästinna i människornas huvudstad ger hon sina fränder en välbekant andlig närvaro.",h="I Stormwinds Park vägleder Nara Meideros unga sökare i Elunes lära.",kw={"elune","nara meideros","nattalvpräst","prästtränare","stormwind","parken"},ang={["class:Priest"]="Som nattalvpräst på resa i Eastern Kingdoms kan du söka N aras vägledning i viktiga rasmässiga böner utan att återvända till Kalimdor.",["race:NightElf"]="Långt från Ashenvale och Teldrassil kan du finna en tröstande bit av hemmet hos Nara Meideros i Parken, bland Stormwinds stenmurar."},sec={{t="En prästinna i Stormwind",b="Nara Meideros tjänar Elune långt från Kalimdor, på andra sidan Stora havet i Stormwind City. I Parken har nattalvdruider och präster vårdat en grönskande fristad. Nara vägleder unga sökare i hängivenhet till Mångudinnan. Mänskliga präster tjänar det heliga ljuset i närbelägna Cathedral Square, medan Nara ger nattalver som besöker eller bor i Eastern Kingdoms en koppling till sin egen tro."}},faq={{q="Var hittar jag Nara Meideros?",a="Hitta Nara Meideros i Stormwind Citys Parkdistrikt, bland månbrunnar och höga träd som påminner nattalvresenärer om hemmet.",al={"nara meideros plats","var finns nara meideros","prästtränare i parken"}},{q="Vilken roll har Nara Meideros?",a="Nara utbildar präster och hjälper både noviser och präster under utveckling. Hon hänvisar mänskliga präster till Cathedral of Light för att lära sig böner och besvärjelser som Desperate Prayer.",al={"vad gör nara","nara meideros uppgift","vem är nara meideros"}},{q="Varför bor en nattalvprästinna i Stormwind?",a="Nattalvernas band till Grand Alliance blir allt starkare. Sändebud, druider och präster från Darnassus håller en aktiv närvaro i Parken för att hjälpa sina fränder och företräda sina andliga traditioner.",al={"varför är hon i stormwind","nattalv i stormwind"}}},fx={["07f550b7"]={q="Vem är Nara Meideros?",a="Nara Meideros är en nattalvprästinna som tjänar månen och The Sisterhood of Elune. Hon är stationerad långt hemifrån bland Alliansens dödliga allierade och vägleder hängivna akolyter i sitt folks andliga traditioner och heliga läror.",al={"vem är nara meideros","vem är nara","nara meideros bakgrund"}},["6f64ae70"]={q="Vems sida står Nara Meideros på?",a="Hon är helt trogen kaldorei och Alliansen. Som nattalvernas trosambassadör vägleder hon präster som söker gemenskap med det gudomliga Ljuset och Elunes läror.",al={"nara meideros fraktion","vem tjänar nara meideros","nara meideros och alliansen"}}},fp="13,172,24.363.0,31.129.0,35.179.0,51.202.0"}
P.entries["npc:narain-soothfancy"] = {n="Narain Soothfancy",s="Narain Soothfancy är en excentrisk gnom som bor i en avskild strandstuga strax norr om Steamwheedle Port i Tanaris. Han gör högljutt reklam för sig själv som en mästersiare som kan förutsäga framtiden, men de som känner honom ser hans psykiska förmågor som rena farsen jämfört med hans verkliga genialitet inom ingenjörskonst.",h="Narain Soothfancy är en excentrisk gnom som bor i en avskild strandstuga strax norr om Steamwheedle Port i...",kw={"azuregos","ingenjör","narain","soothfancy","siare","steamwheedle port","tanaris"},ang={["profession:Engineering"]="Ingenjörer kommer att tycka att Narains vilda uppfinningar är fascinerande, även om han föredrar att låtsas att hans mekaniska bedrifter egentligen är mystiska syner.",["race:Gnome"]="Narain förkroppsligar den excentriska ytterligheten av gnomisk uppfinningsrikedom och förenar briljant teknisk problemlösning med bisarra, tvångsmässiga fritidsintressen."},sec={{t="Psykiska syner och praktisk ingenjörskonst",b="Narain Soothfancy bor på Tanaris östra kust, strax norr om goblinernas kajer, och lever som pensionerad ingenjör och självutnämnd mästersiare. Han hälsar regelbundet besökare genom att trycka oöppnade kuvert mot pannan eller göra vilt felaktiga gissningar om deras ärende, till exempel genom att undra om de kommit för att söka efter den legendariska Ashbringer. Trots sitt teatraliska skådespel besitter Narain djupa tekniska kunskaper. Till och med uråldriga väsen som den blå draken Azuregos noterar att Narain är en usel siare, men obestridligen ett tekniskt geni. En handbok med titeln ”Spådomskonst för dummies” ligger i närheten."},{t="En krasch vid stranden",b="Innan Narain slog sig ner vid Steamwheedle Port råkade han ut för en katastrofal krasch med sin flygmaskin långt söderut längs Land's End Beach. Han överlevde olyckan tack vare en oväntad räddningsinsats, men hans excentriska personlighet och märkliga besattheter har hållit honom isolerad vid öknens stränder, där han pysslar med teknologi med koppling till det mystiska och säljer tvivelaktiga profetior till alla som passerar."}},faq={{q="Vem är Narain Soothfancy?",a="Narain Soothfancy är en pensionerad gnomingenjör som bor i Tanaris norr om Steamwheedle Port. Han gör reklam för sig själv som en mästersiare, trots att hans spådomar är berömt opålitliga.",al={"narain soothfancy historia","vem är narain","synsk gnom i tanaris"}},{q="Är Narain faktiskt synsk?",a="Nej. Maktfulla bekanta som draken Azuregos beskriver honom öppet som en usel siare. Hans verkliga talang ligger inom ingenjörskonst och uppfinningsrikt pyssel, trots hans teatraliska försök att läsa tankar.",al={"kan narain se framtiden","är narain synsk","soothfancy spåman"}},{q="Vad är boken ”Spådomskonst för dummies” bredvid honom?",a="Det är en handbok som förvaras i Nარains koja och som hör ihop med särskilda yrken. Narain hänvisar resande som söker sådan kunskap till boken.",al={"spådomskonst för dummies","narains yrkesbok"}},{q="Hur känner Narain Azuregos?",a="Narain är en gammal bekant till den blå draken Azuregos, som strövar omkring i Azshara. Trots Narains bisarra anspråk respekterar draken hans oöverträffade förmåga inom ingenjörskonst och hantverk.",al={"narain och azuregos","blå drake narain"}}},fp="17,315,37.654.0,17.384.0,25.187.0,29.209.0,54.138.0,30.187.0"}
P.entries["npc:naralex"] = {n="Naralex",s="Naralex är en nattalv-druid som ville återställa The Barrens torra marker till en frodig skog med hjälp av The Emerald Dreams krafter. I stället uppslukades hans sömn av en mörk mardröm som förvrängde Wailing Caverns under marken och förvandlade hans följare till giftiga bestar.",h="Naralex är en nattalv-druid som ville återställa The Barrens torra marker till en frodig skog med hjälp av...",kw={"cenarion circle","avvikande","naralex lärjunge","druids of the fang","emerald dream","emerald nightmare","naralex","the barrens","wailing caverns"},ang={["class:Druid"]="Naralex öde är en mörk varning till druider: den som blint ingriper i naturens ursprungliga tillstånd eller söker sig för djupt in i Drömmen utan försiktighet kan släppa lös katastrofala förvrängningar av vildmarken.",["faction:Horde"]="En nattalvs misslyckade mystiska experiment har förgiftat hjärtat av The Barrens. Nu måste Hordens styrkor från The Crossroads hantera de rasande bestar som väller upp ur grottan.",["race:NightElf"]="Naralex försökte läka Kalimdor, men hans tygellösa ambition djupt inne på Hordens territorium drog skam över Cenarion Circle och skapade de förrädiska Druids of the Fang.",["race:Tauren"]="De förvridna vattnen under The Barrens hotar direkt oasernas vattenhål och djurlivet som Mulgore-stammarna är beroende av."},sec={{t="En vision av grönska",b="Långt före den stora klyvningen var The Barrens solbrända slätter en livfull skog. Naralex såg förlusten som en tragedi och reste till The Barrens med en grupp hängivna lärjungar för att få slut på torkan. Djupt under savannen upptäckte han ett sinnrikt nätverk av underjordiska källor och forsande gejsrar. Han döpte platsen till Wailing Caverns efter det ylande ljudet från vinden och ångan som stönade genom berget. Han trodde att det livgivande vattnet skulle nå ytan och få hela ödemarken att blomstra om han gick in i djup trans och ledde The Emerald Dreams rena energier ner i de underjordiska vattnen."},{t="Den vakna mardrömmen",b="Naralex satte sig i djup meditation långt inne i de underjordiska grottorna, men hans ädla plan föll samman i samma stund som hans medvetande nådde Drömmens rike. I stället för fridfulla källor till vild natur fångades hans sinne av en ondskefull, växande fördärvelse: en Emerald Nightmare. Den ruttnande fördärvelsen tog den sovande druidens kropp i besittning och förvandlade honom till en öppen kanal där mörka energier läckte in i den levande världen. De rena källorna blev förgiftade, svampblommor muterade och grottornas inhemska bestar förvandlades till glupska, avvikande fasor."},{t="Fallna lärjungar",b="Mardrömmen stannade inte vid djurlivet. Naralex egna lärjungar blev fullständigt galna av den psykiska motreaktion som läckte ut från deras mästares trans. De bröt med Cenarion Circles traditioner. De övergav sin vördnad för balansen, antog ormskepnader och kallade sig Druids of the Fang. De tror att deras förvridna tillväxt måste spridas över Kalimdor. Nu vaktar de Naralex sovande kropp för att hindra honom från att vakna, medan bara några få trogna lärjungar söker allierade som vågar bryta transen."}},faq={{q="Vem är Naralex?",a="Naralex är en nattalv-druid i Cenarion Circle. Han ledde en expedition till Wailing Caverns för att nå The Emerald Dream och göra The Barrens torra marker till den frodiga skog de varit före klyvningen.",al={"naralexs historia","vem är den sovande alven","den sovande i wailing caverns"}},{q="Varför sover Naralex i Wailing Caverns?",a="Han gick in i en meditativ trans för att leda energier direkt från The Emerald Dream till grundvattenmagasinen under The Barrens. Men en överväldigande mardröm tog hans sinne i besittning och fångade honom i en febrig sömn som han inte kan vakna ur på egen hand.",al={"varför sover naralex","vad gör naralex","naralex trans"}},{q="Vad skapade Druids of the Fang?",a="De var ursprungligen Naralex trogna lärjungar. När Emerald Nightmare fördärvade Naralex förbindelse med drömmen drev den läckande ondskan hans följare till vansinne. De övergav Cenarion Circle, tog till sig ormtotemer och skyddar nu hans sömn för att låta fördärvelsen spridas.",al={"druids of the fang ursprung","vilka är druids of the fang","naralex lärjungar"}},{q="Vad fick Wailing Caverns att mutera?",a="Naralex sovande kropp blev en öppen kanal för Emerald Nightmare. De giftiga drömenergierna sipprade rakt in i det underjordiska flodsystemet och förvrängde grottornas växter, krokodiler, rovraptorer och ormar till aggressiva, avvikande mutanter.",al={"varför är wailing caverns fördärvade","de avvikande bestarnas ursprung","svamp i wailing caverns"}},{q="Kan Naralex väckas?",a="Ja, med hjälp utifrån. En trogen lärjunge till Naralex samarbetar med äventyrare som vågar bege sig ner i djupet, döda de förvridna Druids of the Fang och utföra en ritual för att befria Naralex sinne från mardrömmens grepp.",al={"hur räddar man naralex","väcka naralex","naralex uppdrag"}},{q="Varför ville Naralex förändra The Barrens?",a="Naralex fick veta att The Barrens en gång var en blomstrande skog, innan den stora klyvningen slet sönder Kalimdor. Han såg områdets nuvarande torra tillstånd som ett sår i naturen och ville återställa dess urgamla, grönskande trädkronor.",al={"varför återställa the barrens","naralex mål i the barrens","varför the barrens"}}},fx={ec55d9d1={q="Vems sida står Naralex på?",a="Naralex tillhör Cenarion Circle, vilket gör honom neutral gentemot både Alliansen och Horden. Hans lojalitet ligger hos naturens balans, inte Kalimdors politiska gräl. Tyvärr har hans fångade sinne helt förlorat kontrollen. Förvridna före detta akolyter vaktar hans sovande kropp och anfaller alla som kommer in.",al={"tillhör naralex alliansen eller horden","naralex fraktion","vem tjänar naralex"}},["4a5a8c9e"]={q="Vilka är Naralex kopplingar?",a="Naralex är en vördnadsvärd nattalvdruid i Cenarion Circle som tog med sig en skara trogna lärjungar till The Barrens. De flesta av hans anhängare dukade under för den mörka mardrömmen som grep hans sinne och förvandlades till de monstruösa Druids of the Fang. Några förblir lojala, som Nalpak och Ebru i grottan ovanför ingången och en Disciple of Naralex som väntar inne i grottorna.",al={"naralex allierade","naralex lärjungar","vilka är naralex anhängare"}}},fp="7,277,17.656.0,20.602.0,16.544.1,15.231.0,49.256.0,36.285.0,42.245.0,24.215.1,43.216.0"}
P.entries["npc:nat-pagle"] = {n="Nat Pagle",s="Nat Pagle hyllas vida omkring som Azeroths mest berömda sportfiskare, trots att han hävdar att han bara fiskar för att få en ursäkt att dricka ordentligt. Han bor vid en avskild vik i Dustwallow Marsh, där han tränar elitfiskare från både Alliansen och Horden som lyckas bevisa sitt tålamod.",h="Nat Pagle hyllas vida omkring som Azeroths mest berömda sportfiskare, trots att han hävdar att han bara...",kw={"mästarfiske","dustwallow marsh","gahz'ranka","grimnur stonebrand","lumak","nat pagle","pagle","pagles udde"},ang={["faction:Alliance"]="Dvärgmästare i sportfiske som Grimnur Stonebrand i Ironforge håller Nat högt aktad och skickar erfarna alliansfiskare till Dustwallow Marsh för att lära sig hantverkets sista hemligheter.",["faction:Horde"]="Lumak, fisketränaren i Valley of Honor i Orgrimmar, räknar Nat Pagle som en pålitlig vän och skickar lovande hordefiskare söderut för att träna med honom."},sec={{t="Mästerfiskaren",b="Även om hans namn är synonymt med mästerligt sportfiske i hela den kända världen, tar Nat Pagle sitt hantverk med anmärkningsvärd lätthet. Efter flera decennier med fiskespö i hand erkänner han ofta att han inte hyser någon större vördnad för själva sporten och kallar den berömt för lite mer än en bekväm ursäkt att luta sig tillbaka och dricka ordentligt. Trots denna kärva nonchalans förstår Nat vattenlevande djur och sportfiskets konst bättre än någon annan i livet, och han utfärdar till och med licenser för fiskeutrustning som yrkesfiskare eftertraktar."},{t="En eremit i träskmarken",b="Pagle slår läger på en liten landtunga längs Dustwallow Marshs östra kust, långt från Eastern Kingdoms livliga värdshus. Han är fullständigt självständig och ointresserad av fraktionspolitik, och välkomnar både alliansresenärer som skickats av tränare som Grimnur Stonebrand och hordaspiranter som Lumak i Orgrimmar har hänvisat till honom. För Nat förtjänar alla som är villiga att genomsöka världens alla hörn efter sällsynta exemplar en lektion i riktigt sportfiske."},{t="Gamla berättelser och sjömonster",b="Pagle har vågat sig ut på farliga vatten, bland annat på en färd till ruinerna i Zul'Gurub. Där tappade han bort sitt favoritmåttband och sin beteslåda nära vattnen där det monstruösa hydramonstret Gahz'ranka stryker omkring."}},faq={{q="Vem är Nat Pagle?",a="Nat Pagle är Azeroths mest berömda fiskare. Efter årtionden av sportfiske lever han nu ett stillsamt liv vid Dustwallow Marshs kust och tränar erfarna fiskare som har vuxit ifrån vanliga tränare.",al={"vem är nat","nat pagles bakgrund","vem är fiskekillen"}},{q="Var hittar man Nat Pagle?",a="Han bor på en liten landtunga på Dustwallow Marshs östra kust i Kalimdor, sydväst om Theramore Isle.",al={"var finns nat pagle","nat pagles plats","hitta nat pagle"}},{q="Varför fiskar Nat Pagle om han säger att han ogillar det?",a="Pagle har öppet erkänt att han främst ser fisket som en respektabel och ostörd ursäkt att sitta vid vattnet och dricka ordentligt i timmar.",al={"gillar nat fiske","varför fiskar nat","nat pagle drickande"}},{q="Tränar Nat Pagle medlemmar av Horden?",a="Ja. Nat är helt neutral i fraktionsrivaliteten. Hordefiskare som når den övre gränsen för vanlig skicklighet skickas direkt till honom av hans vän Lumak i Orgrimmar.",al={"är nat bara för alliansen","horden nat pagle","kan horden prata med nat"}},{q="Vilken koppling har Nat Pagle till Zul'Gurub?",a="Nat fiskade en gång i den uråldriga trollstaden Zul'Gurub och lämnade sin beteslåda och sitt dyrbara måttband nära vattnen där den stora hydran Gahz'ranka håller till.",al={"nat i zg","nat pagles beteslåda","nat pagle zul gurub"}}},fp="9,298,17.480.0,18.473.0,26.212.0,17.202.0,29.115.0,50.156.0,42.172.0,49.169.0"}
P.entries["npc:natalia-mar-alith"] = {n="Natalia Mar'alith",s="Mistress Natalia Mar'alith är en Night Elf-prästinna och forskare inom Cenarion Circle som försvann djupt inne i silithidernas bon i Hive'Regal. Hon gav sig ut i Silithus ödemarker tillsammans med sin make, Commander Mar'alith, innan hon begav sig på en expedition in i bikuporna.",h="Mistress Natalia Mar'alith är en Night Elf-prästinna och forskare inom Cenarion Circle som försvann djupt...",kw={"brann bronzebeard","cenarion hold","hive'regal","in i vansinnets käftar","mar'alith","maralith","natalia","silithus"},ang={["faction:Alliance"]="Rutgar Glyphshaper och Frankal Stonebridge vid Bronzebeard Encampment berättar för Alliansens utforskare de mörka detaljerna om hennes fall när de följer i Branns fotspår.",["race:NightElf"]="Natalias tragiska fall påminner kaldorei om att även deras mest hängivna prästinnor är sårbara för de forntida fasor som ligger begravda under Silithus sand."},sec={{t="Ett tragiskt fall",b="När Cenarion Circle upprättade sin utpost vid Cenarion Hold för att bevaka den vaknande sanden följde Natalia med sin make, Commander Mar'alith, ut i ödemarken. Hon ville ivrigt lösa mysteriet bakom silithidernas återkomst och de forntida Qiraji-ruinerna, och anslöt sig till en utforskningsgrupp ledd av den berömde upptäcktsresanden Brann Bronzebeard, tillsammans med dvärgforskarna Rutgar Glyphshaper och Frankal Stonebridge."},{t="Kristallen i Hive'Regal",b="Expeditionen följde märkliga utstrålningar till de södra delarna av Hive'Regal. Djupt inne i bikupans hjärta fann de en väldig kristall täckt av forntida Qiraji-glyfer. Lockad av dess viskande resonans lutade sig Natalia nära för att studera tecknen. Den mörka magin överväldigade hennes sinne på några ögonblick, krossade hennes förstånd och band hennes vilja till C'Thun. Hennes dvärgkamrater bar henne till Cenarion Hold, där druiderna väckte henne, men flera veckor senare stormade hon tillbaka in i lägret, besatt och krävande att få återvända till bikupan. De tvingades slåss mot henne. Nu vaktar hon nitiskt bikupans skräckinjagande härskare."},{t="Befälhavarens förtvivlan",b="Tillbaka vid Cenarion Hold klamrar sig Commander Mar'alith desperat fast vid hoppet om att hans hustru kan räddas och vägrar acceptera att hennes sinne har krossats för alltid. Men den som vågar sig in i Hive'Regal finner ingen fånge i behov av räddning, utan en skoningslös tjänare åt vansinnet, som brukar helig prästmag i förvriden form av den gamle gudens illvilja."}},faq={{q="Vem är Natalia Mar'alith?",a="Natalia Mar'alith är en Night Elf-prästinna i Cenarion Circle och Commander Mar'aliths hustru. Hon följde med på Brann Bronzebeards spaningsexpedition till Hive'Regal för att undersöka silithidernas återkomst, men föll offer för mörk forntida magi.",al={"natalia mar'alith","vem är natalia","commander mar'aliths hustru"}},{q="Var hittar jag Natalia Mar'alith?",a="Hon finns djupt inne i Hive'Regals insektsliknande tunnlar i södra Silithus, där hon vakar framför en lysande kristall täckt av glyfer.",al={"natalias plats","var finns natalia","prästinna i hive'regal"}},{q="Varför är Natalia fientlig mot äventyrare?",a="När Natalia undersökte en Qiraji-kristall blev hon helt korrumperad och mentalt knäckt av viskningarna från den gamle guden C'Thun. Nu försvarar hon fanatiskt kristallen mot alla som tar sig in i bikupan.",al={"varför attackerade natalia mig","varför är natalia galen","natalia hjärntvättad"}},{q="Vilka var med Natalia när hon försvann?",a="Hon gav sig in i Hive'Regal med Brann Bronzebeard, Rutgar Glyphshaper och Frankal Stonebridge. Rutgar och Frankal överlevde prövningen och drog sig tillbaka till Bronzebeard Encampment i södra Silithus för att berätta vad som hänt.",al={"natalias expedition","vem var med natalia","brann och natalia"}},{q="Varför är hon så farlig i strid?",a="Natalia har kvar sina mäktiga prästkrafter. Hon skingrar ständigt angripare med Psychic Scream och återfår sin styrka med Greater Heal, som nästan inte kostar någon mana. Därför är hon mycket svår att besegra utan ständiga avbrott.",al={"natalia strid","hur besegrar man natalia","natalia helar"}}},fp="17,280,16.427.0,25.634.1,23.333.1,25.255.1,35.139.0,38.198.1,43.219.0,34.232.0"}
P.entries["npc:nathanos-blightcaller"] = {n="Nathanos Blightcaller",s="Nathanos Blightcaller, en gång Nathanos Marris, står vid sitt förstörda hem i Eastern Plaguelands som drottning Sylvanas Windrunners dödliga förkämpe. I livet var han Quel'Thalas första och enda mänskliga Ranger Lord. I undeath tränar han Forsaken-jägare och vaktar den östra gränsen med bitsk förakt för alla som närmar sig.",h="Nathanos Blightcaller, en gång Nathanos Marris, står vid sitt förstörda hem i Eastern Plaguelands som...",kw={"blightcaller","farstrider","jakttränare","marris","the marris stead","nathanos","plaguelands","sylvanas"},ang={["class:Hunter"]="Nathanos är Forsakens högst rankade jakttränare och lär ut Quel'Thalas Farstriders stränga, legendariska skyttetekniker till Lordaerons odöda.",["faction:Alliance"]="Att se en dekorerad hjälte från Lordaeron och en hyllad Farstrider strida under Forsakens fana är en svidande förolämpning och ett dödligt taktiskt problem för Stormwind.",["faction:Horde"]="Nathanos ger Horden avgörande taktiska råd och jaktträning i Plaguelands, men bemöter besökare med syrligt förakt.",["race:Undead"]="Som Dark Ladys förkämpe förkroppsligar Nathanos Forsakens bittra motståndskraft, men han har föga tålamod med inkompetens bland sina jämlikar."},sec={{t="Den enda mänskliga Farstrider",b="Före tredje kriget var Nathanos Marris en enastående skytt och taktisk begåvning från Lordaerons lantliga utkanter. Han utbildades av Quel'Thalas högalver och stod Sylvanas Windrunner nära. Han blev den enda människan någonsin att nå den ansedda graden Ranger Lord. Hans hem förblev familjegodset i Lordaeron, Marris Stead."},{t="Fallet och återkomsten",b="När prins Arthas och Scourge svepte genom Lordaeron efter utrensningen av Stratholme slukade pesten kungariket. Nathanos gjorde ett desperat motstånd vid sitt gods, men föll för monstret Ramstein the Gorger. Han återuppstod som en tanklös odöd träl och strövade omkring på de pestdrabbade fälten och dödade i Lich Kings namn. Efter att Sylvanas brutit Scourges mentala grepp och grundat Forsaken i Undercity kom hon efter honom, precis som han på något vis hade vetat att hon skulle. Hon slet hans medvetande loss från Lich Kings vilja och återgav honom hans taktiska briljans och brinnande lojalitet till henne."},{t="Bansheedrottningens förkämpe",b="Nathanos antog tillnamnet Blightcaller och bosatte sig permanent på det förfallna Marris Stead. Han tjänar Sylvanas som förkämpe, jakttränare och regional spionmästare i det omstridda Eastern Plaguelands, skyddad av vidriga plaguehounds. Alliansens underrättelsetjänst har med stor oro upptäckt att han överlevt. Highlord Bolvar Fordragon ser en mästerlig taktiker av Nathanos kaliber som leder odöda styrkor som ett oacceptabelt hot mot människors överlevnad och skickar ut insatsstyrkor för att mörda den fallne Ranger Lord."}},faq={{q="Vem är Nathanos Blightcaller?",a="Nathanos Blightcaller var Nathanos Marris, en berömd mänsklig skytt och den enda icke-alven som någonsin blev Ranger Lord i Quel'Thalas. Efter sin död och återuppståndelse under tredje kriget befriade Sylvanas hans sinne från Scourge. Nu tjänar han henne som förkämpe och jakttränare i sitt förfädershem i Eastern Plaguelands.",al={"vem är nathanos","nathanos historia","vem är mannen vid marris stead"}},{q="Varför är Nathanos på Marris Stead?",a="Marris Stead var Nathanos hem i livet, och det var där han föll när han försvarade Lordaeron. I undeath valde han att återvända till sitt förstörda gods och göra det till en utpost där han tränar Forsaken-jägare och bevakar Alliansens och Scourges rörelser.",al={"var finns nathanos","varför är nathanos i plaguelands","marris stead nathanos"}},{q="Hur blev Nathanos odöd?",a="Nathanos dödades vid sitt hem under tredje kriget av Scourge-abominationen Ramstein the Gorger. Han återuppstod som en lydig, tanklös träl under Lich King tills Sylvanas kom efter honom och befriade hans sinne, så att han kunde ansluta sig till Forsaken.",al={"hur dog nathanos","vem dödade nathanos","nathanos död"}},{q="Varför vill Alliansen döda honom?",a="Alliansens ledning i Stormwind upptäckte att Nathanos Marris, en av Alliansens främsta militära tänkare och taktiska begåvningar, inte hade gått under för gott utan i stället anslutit sig till Forsaken. Highlord Bolvar Fordragon ser hans taktiska briljans som en enorm fara och beordrar att han ska röjas ur vägen.",al={"varför döda nathanos","alliansuppdrag nathanos","ordningen måste återställas"}},{q="Vad har han för relation till Sylvanas?",a="Nathanos stod Sylvanas nära i livet, när alverna i Quel'Thalas gjorde honom till sin enda mänskliga Ranger Lord, och nu är han hennes förkämpe. I undeath är hans lojalitet mot Banshee Queen fortfarande absolut och orubblig.",al={"sylvanas och nathanos","älskade sylvanas nathanos","romans mellan nathanos och sylvanas"}},{q="Vilka är hundarna som står nära honom?",a="Det är blodtörstiga plaguehounds som Nathanos själv har tränat. De hålls vid hans sida för att vakta ruinerna av Marris Stead och anfaller alla inkräktare som är dumdristiga nog att beträda hans område.",al={"nathanos hundar","marris stead hundar","blightcallers husdjur"}}},fp="21,344,25.354.0,20.606.0,29.515.1,29.329.0,36.251.0,34.244.0,39.301.0,39.214.0,37.188.0"}
P.entries["npc:nida"] = {n="Hilary",s="Hilary är en ung mänsklig flicka som bor i Lakeshire vid sjön i Redridge Mountains. Efter att ha tappat en kär gåva från sin far i sjön gråter hon vid stadens bryggor.",h="Hilary är en ung mänsklig flicka som bor i Lakeshire vid sjön i Redridge Mountains.",kw={"barn","hilary","lake everstill","lakeshire","halsband","nida","redridge","shawn"},ang={["faction:Alliance"]="Medan Redridge Mountains kämpar med större regionala kriser ger hjälpen till Hilary Lakeshires utsatta invånare en liten känsla av värme och oskuld tillbaka."},sec={{t="Ett barns förlorade minnessak",b="Med hotet från gnollinvasioner och Blackrock-orchärar som tränger sig på Lakeshire måste stadens barn ändå hantera vardagliga bekymmer. Hilary råkade tappa ett halsband som hennes far gett henne i Lake Everstills grumliga vatten. Rädd för att hennes far ska bli arg väntar den förtvivlade flickan vid stadens brygga och gråter, i hopp om att någon modig nog ska dyka ner i sjön och hämta det."}},faq={{q="Vem är Hilary?",a="Hilary är ett ungt människobarn som bor i Lakeshire i Redridge Mountains. Hon syns ofta gråtande nära bryggorna.",al={"vem är nida","nida lakeshire","gråtande flicka lakeshire"}},{q="Varför gråter Hilary?",a="Hilary har tappat ett dyrbart halsband som hennes far köpte åt henne. Det gled ner i Lake Everstills vatten, och hon är rädd för att hennes far ska bli arg när han upptäcker att det är borta.",al={"varför gråter hon","varför är nida ledsen","nidas gråtlåt"}},{q="Vem försöker hjälpa henne att hitta halsbandet?",a="Hennes lekkamrat Shawn märker hur ledsen hon är och ber äventyrare som passerar att dyka ner i Lake Everstill och hämta det sjunkna halsbandet åt henne.",al={"vem hjälper nida","nidas vän","vem ger nida ett uppdrag"}},{q="Var finns det förlorade halsbandet?",a="Halsbandet ligger under Lake Everstills yta, nedsänkt nära stadens bryggor där Hilary tappade det.",al={"var är nidas halsband","halsbandets plats lake everstill"}}},fx={["7ae322dc"]={q="Vems sida står Hilary på?",a="Hilary är ett ungt människobarn som lever fredligt under Alliansens beskydd i Lakeshire. Hon tar ingen del i politik eller soldatliv, utan lever sin barndom bland ortens invånare vid Lake Everstill.",al={"nidas fraktion","tillhör nida alliansen","vems sida står nida på"}},["3c3e0c86"]={q="Varför är Hilary i Lakeshire?",a="Lakeshire är Hilarys hem. Hon bor i bosättningen vid sjön med sin familj och tillbringar dagarna med att leka kring hamnen och strandkanten tillsammans med barndomsvännen Shawn.",al={"varför är nida här","varför är nida i lakeshire","vad gör nida här"}}},fp="6,82,23.302.0,14.77.0,21.142.0,44.111.0,35.97.0"}
P.entries["npc:nikova-raskol"] = {n="Nikova Raskol",s="I Old Town sörjer Nikova Raskol sitt mördade barnbarn. Den äldre Stormwind-bon söker rättvisa mot upprorsmakarna i Defias Brotherhood som hålls fångna i The Stockade.",h="I Old Town sörjer Nikova Raskol sitt mördade barnbarn.",kw={"defias-bandana","mac","nikova raskol","old town","stockade","stormwind","blodets färg"},ang={["faction:Alliance"]="För Alliansens mästare i Stormwind är det en påminnelse om att försvaret av kungariket också innebär att skydda vanligt folk, vars familjer har slitits sönder av oroligheterna, att hjälpa Nikova."},sec={{t="En farmors sorg",b="Nikova Raskol vandrar omkring i Old Town med sorgen efter en nylig förlust. Hennes älskade barnbarn Mac dödades av banditer från Defias Brotherhood. Medan kungariket står inför storskaligt förräderi bär Nikova den personliga kostnaden av Brotherhoods laglösa framfart."},{t="Hämnd i The Stockade",b="Många brottslingar som härjade vilt greps och låstes in i The Stockade, men ett våldsamt fånguppror har tagit över fängelset. Vakterna har misslyckats med att återställa ordningen, och Nikova vänder sig till äventyrare som ska bege sig in. Hon ber dem ta med röda Defias-bandanas tillbaka som bevis på att hennes barnbarns mördare har fått sitt straff."}},faq={{q="Vem är Nikova Raskol?",a="Nikova Raskol är en äldre invånare i Stormwind som går längs Old Towns ovala väg. Hon sörjer sitt barnbarn Mac, som mördades av Defias-busarna.",al={"vem är nikova","nikova raskols roll","nikova raskols historia"}},{q="Vad hände med hennes barnbarn Mac?",a="Mac var fjorton år. När armén marscherade till fronten tog han till vapen som vakt i The Stockade, där Defias hålls inlåsta. När han tillrättavisade fångar för att de rev sönder sina yllefiltar och gjorde gänghalsdukar av dem, högg de honom i ryggen.",al={"vem är mac","vad hände med mac","hur dog mac"}},{q="Varför vill hon ha röda bandanas från The Stockade?",a="Den röda bandanan kännetecknar Defias Brotherhood. Nikova ber kämpar som går in i det upproriska The Stockade att ta med halsdukarna tillbaka som bevis på att brottslingarna som tog oskyldigas liv har oskadliggjorts.",al={"blodets färg","varför röda bandanas","defias-bandanas"}},{q="Var hittar man Nikova Raskol?",a="Nikova går fram och tillbaka längs Old Towns huvudgata, nära Pig and Whistle Tavern och Stormwind Citys träningsområden.",al={"var finns nikova","nikovas plats","nikova raskols väg"}}},fx={dc3813b4={q="Vems sida står Nikova Raskol på?",a="Nikova Raskol står helt på Stormwinds och Alliansens sida. Hon är en äldre invånare i huvudstadens hjärta, och hennes hat riktas helt mot Defias Brotherhood, som hon anklagar för att ha mördat hennes familj.",al={"tillhör nikova alliansen","nikova raskols fraktion","vems sida står nikova på"}},cb2616e5={q="Varför är Nikova Raskol i Old Town?",a="Nikova strövar omkring på Old Towns stenlagda gator eftersom Stormwind är hennes hem. Uppslukad av sorg och törst efter rättvisa vandrar hon genom staden och söker efter dugliga hjältar som kan slå tillbaka mot de kriminella konspiratörer som håller till under gatorna.",al={"varför är nikova här","varför är nikova raskol i stormwind","varför är nikova raskol i old town"}}},fp="13,186,21.224.0,25.326.0,21.133.0,34.241.0,49.204.0,33.119.0"}
P.entries["npc:nissa-firestone"] = {n="Nissa Firestone",s="Nissa Firestone är en dvärgisk läkare som arbetar ovanför vimlet vid Great Forge i Ironforge. Hon undervisar i fältmedicin och lär resenärer och soldater att lägga om sår och förbinda skador.",h="Nissa Firestone är en dvärgisk läkare som arbetar ovanför vimlet vid Great Forge i Ironforge.",kw={"alliance trauma","bandage","första hjälpen","great forge","läkare","ironforge physician","nissa firestone"},ang={["faction:Alliance"]="Alla äventyrare från Alliansen som passerar genom Khaz Modan förlitar sig på tränare som Nissa för att skaffa viktiga färdigheter för överlevnad utan gudomlig eller magisk kraft.",["race:Dwarf"]="För dvärgar som återvänder från skärmytslingar med troggar eller frosttroll står Nissa för Ironforges praktiska och rättframma läkartradition."},sec={{t="En läkare ovanför städet",b="Bland klangen från metall och den brännande hettan vid Great Forge utövar Nissa Firestone läkekonst på övervåningen i Ironforge Physician. Dvärgiska krigare är kända för sin uthållighet, men även hud hård som sten spricker av klingor och klor. Nissa ser till att de som ger sig ut i Dun Moroghs snö eller ännu längre bort vet hur de kan hålla sig själva och sina allierade vid liv med enkla bandage och förband för fältbruk."},{t="Triage och avancerad traumavård",b="För fältmediciner som behärskar grunderna i tyg och ludd inser Nissa när en elev har vuxit ur hennes klinik. När utövare når gränsen för vad hon kan lära dem hänvisar hon dem till specialiserade triageansvariga vid avlägsna utposter och visar skickliga läkare vart Alliansens sårade behöver vård som mest."}},faq={{q="Vem är Nissa Firestone?",a="Nissa Firestone är en dvärgisk första hjälpen-tränare som håller till i Ironforge Physician, beläget vid södra kanten av Great Forge.",al={"vem är nissa firestone","nissa firestones roll","första hjälpen-tränare i ironforge"}},{q="Var hittar jag Nissa Firestone?",a="Hon finns på övervåningen i Ironforge Physician, som ligger vid södra kanten av ringen kring Great Forge i Ironforge.",al={"nissa firestones plats","var finns nissa","ironforge physician plats"}},{q="Vad lär Nissa Firestone ut?",a="Hon lär Alliansens äventyrare första hjälpen och visar hur man tillverkar bandage och motgifter för att behandla skador man får ute i fält.",al={"vad lär nissa ut","första hjälpen ironforge","lära sig bandage i ironforge"}},{q="Kan Nissa lära ut triage på mästarnivå?",a="Nej. När en läkare når avancerad skicklighet hänvisar Nissa dem vidare genom uppdraget Alliance Trauma till erfarna fältkirurger som är stationerade nära aktiva krigszoner.",al={"alliance trauma-uppdrag","mästartränare i första hjälpen ironforge","första hjälpen över 225"}}},fx={f16b91f7={q="Vems sida står Nissa Firestone på?",a="Nissa Firestone står helt på Ironforges och Alliansens sida. Högt uppe i huvudstaden använder hon sina medicinska kunskaper för att hålla Ironforges försvarare och resande från Alliansen vid liv med sårvård och behandling av skador.",al={"nissa firestones fraktion","tillhör nissa alliansen","vem tjänar nissa"}},bc93403c={q="Varför är Nissa Firestone i Ironforge?",a="Nissa arbetar i Ironforge Physician-butiken ovanför Great Forge. Från den centrala platsen i dvärgarnas huvudstad kan hon vårda stadens sjuka och skadade och samtidigt träna äventyrliga fältsjukvårdare i att förbinda sår och hejda blödningar innan de marscherar ut i strid.",al={"varför är nissa här","varför är nissa firestone här","vad förde nissa till ironforge"}},["2ef2db38"]={q="Vad vill Nissa Firestone?",a="Som läkare och tränare vill Nissa framför allt se till att Alliansens kämpar kan ta hand om sina skador ute i fält. När lovande sjukvårdare har vuxit ur hennes undervisning hänvisar hon dem till mer avancerade fältkirurger som kan lära dem triage i krigstid.",al={"vad vill nissa","nissa firestones mål","nissa firestones motiv"}}},fp="15,98,25.423.0,26.224.0,23.123.0,33.122.0,32.130.0,36.169.0"}
P.entries["npc:nogg"] = {n="Nogg",s="Nogg är en gobliningenjör som driver en verkstad i Valley of Honor i Orgrimmar. Han erbjuder Horden sin expertis inom finmekanik och sitt specialiserade hantverk, och analyserar bland annat märkliga mekaniska fynd från djupet av Gnomeregan.",h="Nogg är en gobliningenjör som driver en verkstad i Valley of Honor i Orgrimmar.",kw={"gnomeregan","gobliningenjör","mekanisk verkstad","nogg","orgrimmar","ringens återkomst"},ang={["faction:Horde"]="För Hordens krigare som återvänder från farliga uppdrag i Eastern Kingdoms överbryggar Nogg klyftan mellan grova fynd och finjusterad stridsutrustning.",["profession:Engineering"]="Ingenjörskollegor tittar ofta in i Noggs verkstad i Valley of Honor för att hämta delar, prata fack och förundras över hur lätt goblinhänder kan ge avancerad gnomisk teknik ett nytt syfte."},sec={{t="Noggs verkstad",b="Undangömd i Valley of Honor i Orgrimmar driver Nogg en fristående ingenjörsverkstad för både äventyrare och hantverkare. Medan staden omkring honom förlitar sig starkt på traditionellt orchiskt stål och råstyrka, erbjuder Nogg den specialiserade mekaniska finess som bara en goblin kan bidra med. Han är mycket intresserad av främmande manicker och teknik och undersöker gärna märkliga småsaker och mekaniska egenheter som släpas hem från Alliansens länder eller underjordiska ruiner."},{t="Gnomiska manicker och fynd",b="Nogg intresserar sig särskilt för föremål från Gnomeregans fallna huvudstad. När Hordens operatörer hämtar detaljerade ringar eller tekniska lämningar ur de bestrålade valven på andra sidan havet, är Nogg en av få i Durotar som kan plocka isär, tyda och bygga om dessa märkliga urverksmekanismer för Hordens bruk."}},faq={{q="Var hittar jag Nogg?",a="Nogg finns i Valley of Honor i Orgrimmar, där han driver sin egen ingenjörsverkstad.",al={"noggs plats","var finns nogg","noggs mekaniska verkstad"}},{q="Vad har Nogg för koppling till Gnomeregan?",a="När äventyrare från Horden ger sig in i Gnomeregans bestrålade tunnlar i Khaz Modan kan de hitta detaljerade tekniska småsaker. Nogg är den lokala experten i Orgrimmar som undersöker och bygger om dessa främmande gnomiska ringar.",al={"varför nogg gnomeregan","nogg ring","ringens återkomst"}},{q="Tillhör Nogg Horden?",a="Nogg är en fristående goblinhantverkare som verkar mitt i Orgrimmar. Han hjälper aktivt Hordens äventyrare och bidrar med sina tekniska färdigheter till deras krigsinsats.",al={"är nogg med i horden","noggs fraktion"}},{q="Kan Nogg ändra eller smida om ringar?",a="Ja. Om en äventyrare tar med sig en ring från Gnomeregan som tagits ut med Sparklematic och vill ha andra förtrollningar eller mekaniska egenskaper, vet Nogg hur han ska plocka isär och bygga om den så att den passar äventyrarens behov bättre.",al={"gör om ring","ändra gnomereganring"}}},fx={["81166680"]={q="Vem är Nogg?",a="Nogg är en företagsam gobliningenjör som driver Nogg's Machine Shop i Valley of Honor i Orgrimmar. Liksom många gobliner i Hordens huvudstad säljer han sina mekaniska tjänster till både klurmakare och äventyrare, med skarp blick för fascinerande apparater och tekniskt skrot.",al={"vem är nogg","noggs bakgrund","noggs identitet"}},c0d235dc={q="Vad vill Nogg?",a="Nogg vill ha nyskapande ingenjörsdelar, märkliga mekaniska artefakter och lukrativa möjligheter. Han är intresserad av att undersöka intrikata ringar som äventyrare hittar och hålla ett öga på det tekniska kaoset i konflikter som riggkrigen i Gnomeregan för att stärka butikens affärer.",al={"vad vill nogg","noggs mål","noggs syfte med uppdragen"}},["0ba8fca5"]={q="Varför är Nogg i Orgrimmar?",a="Nogg håller till i Valley of Honor i Orgrimmar, där den livliga huvudstaden ger ett stadigt flöde av kunder, råmaterial och äventyrslystna legosoldater som är villiga att utföra farliga ärenden. Hans verkstad blomstrar tack vare hordens ständiga behov av ingenjörskunskaper.",al={"varför är nogg här","varför är nogg i orgrimmar","orsak till noggs plats"}}},fp="4,141,15.288.0,27.262.0,22.72.0,40.161.0,26.105.0,32.152.0"}
P.entries["npc:nori-pridedrift"] = {n="Nori Pridedrift",s="Nori Pridedrift är en driftig dvärg som säljer sin rykande heta Scalding Mornbrew i det snöiga Coldridge Valley. Han försörjer sig genom att trotsa kylan och förse huttrande bergsvakter med deras morgonuppiggare, och anlitar ofta snabba bud för leveranser medan drycken fortfarande ryker.",h="Nori Pridedrift är en driftig dvärg som säljer sin rykande heta Scalding Mornbrew i det snöiga Coldridge...",kw={"brygd","coldridge valley","dun morogh","dvärg","mornbrew-mugg","nori pridedrift","scalding mornbrew"},ang={["profession:Cooking"]="Kulinariskt intresserade äventyrare i Dun Morogh uppskattar Noris hängivenhet till att servera sin specialdryck rykande het trots den isande luften.",["race:Dwarf"]="Alla dvärgar vet hur viktigt det är med en värmande stark dryck i kylan, så Noris rykande Mornbrew är en välkommen syn på bergets vaktposter."},sec={{t="En rykande kopp i snön",b="Livet i Coldridge Valley är hårt och bittert kallt, och inget skingrar kylan som en klunk Scalding Mornbrew. Nori Pridedrift har skapat sig en försörjning genom att brygga och distribuera denna varma, kaffeliknande morgondryck över de frusna vidderna. För att drycken ska uppskattas fullt ut måste den drickas medan den fortfarande är skållhet, så leveransen blir en kamp mot vädrets makter. Nori anlitar ofta snabba bud som springer med nybryggda klunkar till huttrande vaktposter innan bergsluften tar värmen ur drycken. Hans begränsade förråd av tåliga muggar är nästan lika viktiga som själva brygden, och han förväntar sig att buden lämnar tillbaka dem omgående."}},faq={{q="Vem är Nori Pridedrift?",a="Nori Pridedrift är en driftig dvärghandlare med bas i Coldridge Valley. Han brygger och säljer Scalding Mornbrew, en varm, kaffeliknande dryck som håller traktens vakter och gruvarbetare varma.",al={"vem är nori","nori pridedrifts bakgrund","försäljare av scalding mornbrew"}},{q="Vad är Scalding Mornbrew?",a="Scalding Mornbrew är en särskild varm dryck som bryggs av Nori Pridedrift. Den liknar rykande hett kaffe eller kryddat morgonöl, och är mycket uppskattad av dalens invånare för att hålla den bittra kylan i Dun Morogh stången.",al={"scalding mornbrew","vilken dryck säljer nori","mornbrew"}},{q="Varför är leveranserna så brådskande?",a="Dryckens hela tjusning ligger i att den är rykande het. I Coldridge Valleys iskalla bergsvindar tappar en kopp snabbt värmen, så Noris bud måste springa till sina törstiga kunder.",al={"varför skynda med leveransen","brådskande mornbrew-leverans","varför kallnar drycken"}},{q="Varför bryr sig Nori så mycket om att få tillbaka muggarna?",a="Nori har ett begränsat förråd av dryckeskärl i dalen. Om kunderna går iväg med hans muggar eller krossar dem i snödrivorna tar morgonhandeln snabbt stopp.",al={"varför lämna tillbaka muggen","noris muggar","återlämning av mugg"}}},fx={ddac60d5={q="På vems sida står Nori Pridedrift?",a="Nori står helt och hållet på Ironforge-dvärgarnas och Alliansens sida. Han är en oberoende lokal köpman som håller till i Coldridge Valley och betjänar bergsjägarna, rekryterna och invånarna som försvarar och bor i dalen.",al={"nori pridedrifts fraktion","vem arbetar nori för","nori pridedrift och alliansen"}},["26ccfe8e"]={q="Vad vill Nori Pridedrift?",a="Nori vill driva ett lönsamt bryggeri i Coldridge Valley. Hans främsta bekymmer är att hans berömda Scalding Mornbrew når törstiga kunder medan den fortfarande är rykande het, och att varje tom mugg hittar tillbaka till hans lager.",al={"nori pridedrifts mål","vad vill nori","noris motiv"}},["10ad6fd1"]={q="Varför är Nori Pridedrift här?",a="Nori strövar omkring i Coldridge Valley eftersom hans törstiga stamkunder finns där. Det hårda, iskalla bergsklimatet gör hans rykande heta morgondryck särskilt populär bland de lokala vakterna och rekryterna, vilket ger honom en stadig inkomst.",al={"varför är nori i coldridge valley","varför är nori här","nori pridedrifts plats"}}},fp="15,175,26.385.0,23.151.0,26.130.0,29.157.0,48.144.0"}
P.entries["npc:novice-elreth"] = {n="Novice Elreth",s="Novice Elreth är en odöd medlem av Forsaken som håller till i kapellet i Deathknell. När nyuppståndna odöda vaknar till sitt andra liv leder hon dem till att bekämpa de tanklösa Scourge som hemsöker gravarna i närheten och ta hand om pestens tragiska följder.",h="Novice Elreth är en odöd medlem av Forsaken som håller till i kapellet i Deathknell.",kw={"kapell","kyrka","deathknell","forsaken","marlas sista önskan","novice elreth","de fördömda","tirisfal glades"},ang={["class:Priest"]="Bland Lordaerons forna heliga platser förkroppsligar Elreth den skarpa, pragmatiska övergången från helig dyrkan till odöd nödvändighet.",["race:Undead"]="För nyblivna Forsaken som kravlar upp ur graven erbjuder Novice Elreth några av de första praktiska stegen mot överlevnad och riktar deras iskalla hat mot de tanklösa Scourge."},sec={{t="En vägvisare i de fördömdas kyrka",b="I det vanhelgade kapellet i Deathknell hjälper Novice Elreth de nyuppståndna odöda när de försöker förstå sitt fasansfulla uppvaknande. I stället för att ge efter för förtvivlan eller Scourges tanklösa hunger måste Forsaken snabbt organisera sig för att säkra sitt territorium. Elreth ger de nybefriade själarna sina första uppgifter och leder dem till att samla tassar och vingar från vargarna och fladdermössen i söder samt hantera de kvarlevande spåren av Lordaerons tragiska fall, däribland sorgen efter hennes vän Marla Fipps, som dödades av sin egen make Samuel efter att han anslutit sig till de tanklösa Scourge."}},faq={{q="Var finns Novice Elreth?",a="Novice Elreth står inne i kapellet i Deathknell, den förstörda byn i Tirisfal Glades där nyblivna Forsaken vaknar.",al={"elreth plats","var finns elreth","novice elreth kyrka"}},{q="Vilken roll har Novice Elreth i Deathknell?",a="Hon fungerar som lokal vägvisare och uppdragsledare för nyuppståndna Forsaken. Hon ger dem viktiga inledande instruktioner och lär de nyuppväckta odöda att slå till mot tanklösa Scourge som stryker omkring på byns begravningsplats.",al={"vad gör elreth","elreths roll","novice elreth uppgift"}},{q="Vilka uppdrag erbjuder Novice Elreth?",a="Hon delar ut uppdrag som The Damned, där äventyrare ska hämta asätarvargtassar och skymningsfladdermusvingar, och Marla's Last Wish, där de ska besegra den tanklöse Samuel Fipps och begrava hans kvarlevor bredvid hans hustru Marlas grav.",al={"novice elreth uppdrag","elreths uppgifter"}},{q="Varför kallas hon ”Novice”?",a="Med tanke på sin plats i kapellet och sin titel är Elreth en novis i Forsakens religiösa eller samhälleliga rangordning. Hon lär sig hur man i praktiken hanterar Tirisfals nyuppväckta odöda under Forsakenordens skugga.",al={"varför novice","novice betydelse elreth","är elreth präst"}}},fx={["04e44638"]={q="Vem är Novice Elreth?",a="Novice Elreth är en odöd tjänare som är stationerad i den vanhelgade kyrkan i Deathknell. Som en av de tidiga vårdarna som hjälper nyvaknade Forsaken vägleder hon nyuppståndna själar genom den hårda verkligheten i deras odödhet och införlivar dem i tjänsten under den mörka damen.",al={"vem är novice elreth","novice elreths bakgrund","om novice elreth"}},["36f54bd8"]={q="På vems sida står Novice Elreth?",a="Hon är helt lojal mot Forsaken och drottning Sylvanas Windrunner. Från Deathknell stöder hennes arbete direkt Undercitys ansträngningar att säkra Tirisfal Glades genom att bedöma och vägleda de nyuppståndna.",al={"novice elreths fraktion","vem tjänar novice elreth","novice elreths lojalitet"}},d753a6ea={q="Vad vill Novice Elreth?",a="Elreth vill se till att nyligen frigjorda odöda förstår sitt tillstånd, möter sanningen om sina gravar och finner sin plats bland Forsaken. Hon prövar de nyuppståndnas beslutsamhet och hänvisar dugliga personer till det lokala ledarskapet för att hjälpa till i krigsinsatsen.",al={"vad vill elreth","elreths mål","varför ger elreth uppdrag"}},a4872bf3={q="Varför är Novice Elreth här i Deathknell?",a="Deathknell är platsen där Forsaken gräver fram och återupplivar nya lik för att fylla sina led. Elreth stannar i kapellet för att ta hand om de förvirrade själarna så snart de vaknar, så att de inte ger efter för förtvivlan eller vänder sig mot sina nya fränder.",al={"varför är elreth i deathknell","varför är novice elreth i kyrkan"}}},fp="13,188,35.450.0,31.122.0,43.168.0,37.167.0,27.199.0"}
P.entries["npc:oben-rageclaw"] = {n="Oben Rageclaw",s="Oben Rageclaw är anden efter en rastlös Night Elf-druid som hemsöker de fördärvade djupen i Ban'ethil Barrow Den på Teldrassil. Medan hans ande vandrar fångad i gravhögen har hans sovande kropp fallit under den ondskefulla furbolgmagins inflytande.",h="Oben Rageclaw är anden efter en rastlös Night Elf-druid som hemsöker de fördärvade djupen i Ban'ethil Barrow...",kw={"ban'ethil barrow den","druid of the claw","emerald dream","gnarpine","oben rageclaw","teldrassil","den sovande druids"},ang={["class:Druid"]="Obens öde påminner om hur sårbara druider är när de i transliknande meditation talar med The Emerald Dream och heliga gravhögar lämnas utan försvar.",["race:NightElf"]="Gnarlpine-furbolgernas vanhelgande av Oben Rageclaw visar hur djupt korruptionen har besudlat Teldrassils inhemska invånare och heliga helgedomar."},sec={{t="En vanhelgad slummer",b="Liksom många Druids of the Claw drog sig Oben Rageclaw tillbaka till Ban'ethil Barrow Dens underjordiska helgedom för att tala med naturen och vandra i The Emerald Dream. Men när de inhemska Gnarlpine-furbolgerna korrumperades och tog över gravhögarna blev Oben helt försvarslös i sin trans. I stället för att bara döda honom använde de korrumperade Gnarlpine-schamanerna mörka ritualer för att ta kontroll över hans livlösa kropp. Hans fördrivna ande blev kvar som ett plågat spöke, oförmögen att gå vidare eller vakna."},{t="Bandet till kroppen bryts",b="Eftersom Oben inte kan återta sin kropp från schamanernas förtrollning förlitar han sig på resenärer som tar sig genom de farliga tunnlarna för att få slut på hans plåga. Hans band till de dödligas värld kan bara brytas om hans marionettstyrda kropp hittas och förstörs. När hans kapade kropp dödas befrias Obens plågade spöke till slut från det underjordiska mörkret och kan finna evig vila i The Emerald Dream."}},faq={{q="Vem är Oben Rageclaw?",a="Oben Rageclaw är en Night Elf Druid of the Claw vars spöke hemsöker Ban'ethil Barrow Den på Teldrassil, efter att korrumperade furbolger skilt honom från hans kropp.",al={"vem är oben","oben rageclaw berättelse","ande i gravhög"}},{q="Varför är Oben Rageclaw ett spöke?",a="Medan Oben sov i en djup druidisk trans och talade med The Emerald Dream trängde Gnarlpine-furbolgschamaner in i gravhögen. De kastade ondskefull magi över hans kropp, tog kontroll över den och fångade hans ande utanför kroppen som en vålnad.",al={"varför är oben död","hur dog oben","varför är oben ett spöke"}},{q="Var finns Obens kropp?",a="Hans kropp ligger längre in i Ban'ethil Barrow Dens slingrande gångar, bevakad och styrd av Gnarlpine-schamanerna som korrumperade gravhögen.",al={"hitta obens kropp","var finns obens kropp","plats för sovande druid"}},{q="Vad händer när Obens kropp förstörs?",a="När hans marionettstyrda kropp förstörs bryts Gnarlpine-schamanernas mörka grepp om honom. Då kan hans ande lämna Teldrassil i frid och vila för evigt i The Emerald Dream.",al={"obens öde","vad händer med obens ande","rädda oben"}}},fx={["9c749c17"]={q="På vems sida står Oben Rageclaw?",a="Oben Rageclaw står på nattalvernas och Cenarion Circles sida. En korrumperad Gnarlpine-schaman manipulerar för närvarande hans slumrande fysiska kropp djupt inne i gravhögarna, men Obens sanna ande är fortfarande trogen sitt folk och söker hjälp från förbipasserande äventyrare för att få slut på sin plåga.",al={"är oben rageclaw vänligt sinnad","oben rageclaws fraktion","vem tjänar oben"}},["98315864"]={q="Vad vill Oben Rageclaw?",a="Oben vill bli fri från det onaturliga grepp som binder hans ande till Ban'ethil Barrow Den. Eftersom ond Gnarlpine-magi har tagit kontroll över hans fysiska kropp ber han dig förgöra hans korrumperade gestalt, så att hans rastlösa ande äntligen kan finna frid i The Emerald Dream.",al={"vad vill oben","oben rageclaws mål","oben rageclaws motiv"}}},fp="13,148,20.396.0,19.309.1,21.149.0,29.213.0,30.134.0,44.146.1"}
P.entries["npc:oggleflint"] = {n="Oggleflint",s="Under Orgrimmar leder Oggleflint troggstammen i Ragefire Chasm. Hans flock klättrar från lavafyllda tunnlar mot ytan, där han befaller dem nära grottans ingång och hotar Hordens huvudstad ovanför.",h="Under Orgrimmar leder Oggleflint troggstammen i Ragefire Chasm.",kw={"oggleflint","orgrimmar","ragefire chasm","searing blade","trogg"},ang={["class:Warrior"]="Som krigare möter du en tung best som förlitar sig på rå muskelstyrka och ursinne, inte rustning eller disciplin.",["faction:Horde"]="Under Thralls fästning utgör Oggleflints trogger en vild, oförutsägbar säkerhetsrisk mitt i Durotar.",["race:Orc"]="Som en ung ork som ska bevisa sitt mod i vapenkonstens prövning sätts din kampdisciplin på prov när du möter hövdingen under Drag."},sec={{t="Djupets hövding",b="Djupt under Orgrimmar klättrade Oggleflint och hans trogger från eldiga tunnlar in i Ragefire Chasm. De högg ut ett primitivt revir bland den smälta stenen och försvarar det med brutal kraft. Trogger har föga avancerad civilisation, och Oggleflint styr sin flock med ren styrka."},{t="Död åt sändebuden",b="Äldstekrönan Magatha Grimtotem skickade diplomater in i ravinen för att sluta fred med troggerna. Troggerna vände sig mot dem och dödade dem. Maur Grimtotem, en av sändebuden, ligger död i grottorna under Oggleflints uppsikt. Nära grottans ingång väntar hövdingen och går till anfall mot främlingar som vågar sig in i mörkret."},{t="Hotet under Orgrimmar",b="Oggleflints stam lever rakt under Thralls huvudstad, en fara Horden inte kan tolerera. Troggerna kryper närmare ytan, och deras oberäkneliga natur hotar att föra dem in i Drag och Cleft of Shadow om de lämnas ostörda."}},faq={{q="Vem är Oggleflint?",a="Oggleflint är en mäktig trogghövding som leder sin flock i Ragefire Chasm under Orgrimmar.",al={"oggleflint","vem är oggleflint","ragefires troggboss"}},{q="Var hittar man Oggleflint?",a="Oggleflint väntar i Ragefire Chasms övre grottor, nära ingångstunneln. Hans flock håller tunnlarna närmast ytan.",al={"var finns oggleflint","oggleflints plats","hitta oggleflint"}},{q="Varför är troggerna i Ragefire Chasm?",a="Trogger lever naturligt djupt under jord i underjordiska vulkaniska nätverk. Oggleflints flock har klättrat från de lavafyllda tunnlarna under Orgrimmar mot ytan.",al={"varför finns trogger under orgrimmar","ragefires trogglore"}},{q="Varför är Oggleflint fientlig mot Horden?",a="Trogger är våldsamma och försvarar sitt revir med ursinnig kraft. När Oggleflint och hans anhängare tränger mot ytan hotar de Hordens tunnlar och staden ovanför.",al={"varför döda oggleflint","varför slåss mot oggleflint"}},{q="Vilken relation har Oggleflint till Searing Blade?",a="Oggleflints trogger och Searing Blade-kultisterna delar ravinen, men ingenting gör dem till allierade. Troggerna håller tunnlarna nära ingången, medan kultisterna verkar i de djupare kamrarna.",al={"searing blade och oggleflint","är troggerna med kulten"}}},fx={b435b0f8={q="På vems sida står Oggleflint?",a="Oggleflint kämpar enbart för sig själv och sina troggfränder. Han är inte lojal mot Horden, Alliansen eller kultisterna i Searing Blade, som också lurar i klyftan, och hans trogger anfaller alla hordförsvarare som tar sig ner i mörkret.",al={"oggleflints fraktion","oggleflint, alliansen eller horden","vem tjänar oggleflint"}},e0483c37={q="Vad vill Oggleflint?",a="Oggleflint vill hålla sina tunnlar. Hans trogger har trängt upp från de lavafyllda djupen mot ytan, och de dödar alla främlingar som kommer in i klyftan, även sändebud som skickats för att sluta fred.",al={"oggleflints mål","vad troggerna vill i ragefire","oggleflints syfte"}}},fp="10,218,21.279.0,15.319.0,28.244.0,18.96.0,30.127.0,37.173.0,39.154.0,57.195.0"}
P.entries["npc:ogtinc"] = {n="Ogtinc",s="Ogtinc är en självständig furbolgjägare på en hög bergskam med utsikt över Ruins of Eldarath i Azshara. Efter att ha lämnat sin stam för att tjäna naturens balans är han en betrodd bundsförvant och mentor åt Cenarion Circle. Skickliga jägare som vill pröva sin förmåga mot Kalimdors vildaste bestar söker ofta hans vägledning.",h="Ogtinc är en självständig furbolgjägare på en hög bergskam med utsikt över Ruins of Eldarath i Azshara.",kw={"azshara","cenarion","eldarath","furbolg","jägare","ogtinc","timbermaw"},ang={["class:Druid"]="Som en trofast partner till Cenarion Circle utgör Ogtinc en ovanlig länk mellan okorrumperade furbolgers vilda visdom och druidernas naturvård.",["class:Hunter"]="Ogtinc erbjuder erfarna jägare djupa andliga och praktiska prövningar som testar deras träffsäkerhet och överlevnadsförmåga mot Kalimdors dödligaste varelser."},sec={{t="En furbolg för sig",b="Medan de flesta furbolger i Kalimdor fortfarande är starkt bundna till sina stammar, eller har fallit för korruption efter det tredje kriget, valde Ogtinc en egen väg. Han lämnade sina fränder och ägnade sin båge och sina kunskaper om överlevnad åt att hjälpa Cenarion Circle. Han slår läger högt uppe på en klippa sydost om Timbermaw Hold och vakar uppmärksamt över Azsharas urgamla, sönderslagna marker."},{t="Jaktens mästare",b="Ogtinc är känd bland erfarna spårare för sin djupa förståelse av Kalimdors vildmark. Han sätter jägare på prov efter att de finslipat sina färdigheter över kontinenterna och skickar dem att samla sällsynta troféer, som hjorthorn från springare, fjäll från vågpiskade havsormar och delar från gröna draklingar. Genom dessa prövningar lär han ut att sann jakt hedrar naturen och bevarar balansen i stället för att ta liv utan eftertanke."}},faq={{q="Vem är Ogtinc?",a="Ogtinc är en skicklig furbolgjägare som håller till på Azsharas klippor. Till skillnad från de flesta av sina tillbakadragna eller korrumperade fränder lämnade han sin förfäders stam för att erbjuda sina spårningskunskaper och sin visdom åt druiderna i Cenarion Circle.",al={"vem är ogtinc","ogtincs historia","furbolg i azshara"}},{q="Var kan Ogtinc hittas?",a="Han finns i Azshara, på en lägerplats vid klippkanten med utsikt över de urgamla Ruins of Eldarath, strax sydost om Timbermaw Hold.",al={"var finns ogtinc","ogtincs plats","hur hittar man ogtinc"}},{q="Varför lämnade Ogtinc sin stam?",a="Ogtinc lämnade sina fränder för att hjälpa Cenarion Circle att bevara naturen. Även om hans exakta stamursprung inte har angetts står hans klara sinne och fridsamma sätt i skarp kontrast till de korrumperade stammarna på andra håll i norra Kalimdor.",al={"varför lämnade ogtinc","ogtincs stam","är ogtinc timbermaw"}},{q="Vilken roll har Ogtinc för jägare?",a="Ogtinc är en mästerlig mentor för erfarna jägare som når höjdpunkten av sin träning. Han ger dem i uppgift att spåra upp fruktansvärda bestar över hela Kalimdor, från snabba springare till den gröna drakflyktens avkomma, för att bevisa att de behärskar vildmarken.",al={"ogtincs jägaruppdrag","jägartränaren ogtinc","varför besöka ogtinc"}},{q="Är Ogtinc knuten till Timbermaw Hold?",a="Ogtinc slår läger nära Timbermaw Hold, men verkar självständigt i direkt samarbete med Cenarion Circle. Han är naturligt vänligt inställd till resenärer som närmar sig fredligt, oavsett deras anseende hos Timbermaw-stammen.",al={"ogtinc timbermaw","ogtinc och anseende hos timbermaw","är ogtinc vänligt inställd"}},{q="Varför vakar Ogtinc över Ruins of Eldarath?",a="Utsiktsplatsen högt ovanför ruinerna ger honom fri sikt över den oroliga vildmarken nedanför, där naga, elementaler och kvarlevande magiska ekon hotar kustskogens sköra balans.",al={"varför är ogtinc i azshara","eldarath ogtinc","ogtincs klippa"}}},fp="6,350,15.381.0,18.456.0,14.243.0,26.137.0,31.267.0,39.257.0,41.231.0,49.209.0"}
P.entries["npc:ogunaro-wolfrunner"] = {n="Ogunaro Wolfrunner",s="I Valley of Honor i Orgrimmar sköter Ogunaro Wolfrunner Hordens främsta varghägn vid Hunter’s Hall. Han föder upp och tränar vildsinta vargar åt orkiska mästare och deras betrodda allierade.",h="I Valley of Honor i Orgrimmar sköter Ogunaro Wolfrunner Hordens främsta varghägn vid Hunter’s Hall.",kw={"skräckvarg","ogunaro wolfrunner","riddjur i orgrimmar","timmervarg","valley of honor","vargriddjur"},ang={["faction:Horde"]="Troll, tauren och Forsaken måste bevisa sin hängivenhet och ära inför Orgrimmar innan Ogunaro överlåter en varg till dem.",["race:Orc"]="För orker är det en förfäders tradition att rida på varg, med rötter hos Draenors klaner. Ogunaro håller det krigiska bandet vid liv."},sec={{t="Flockens mästare",b="Ogunaro Wolfrunner sköter Orgrimmars stridsvargar vid Hunter’s Hall i Valley of Honor. Orker och vargar har delat ett band i generationer, på Draenors slätter och i Durotars vildmark. Det bygger på ömsesidig respekt, inte enkel domesticering. Ogunaro överlåter bara de härdigaste djuren, från skräckvargar till smidiga skogsvandrare, åt krigare som har bevisat sin styrka och sitt värde för krigshövdingen."}},faq={{q="Vem är Ogunaro Wolfrunner?",a="Ogunaro Wolfrunner är Hordens främsta varguppfödare och riddjursförsäljare. Han finns utanför Hunter’s Hall i Valley of Honor i Orgrimmar.",al={"ogunaro","vargförsäljare orgrimmar","försäljare av riddjur för orcer"}},{q="Kan vem som helst köpa en varg av honom?",a="Orker kan få vargar genom sitt arv när de har tränats ordentligt. Andra medlemmar av Horden måste nå upphöjd status och vinna Orgrimmars yttersta förtroende innan Ogunaro överlåter en varg till dem.",al={"kan icke-orcer köpa vargar","ryktekrav för vargriddjur"}},{q="Vilka slags vargar erbjuder han?",a="Ogunaro erbjuder svarta, bruna, skräck- och skogsvargar, samt snabba, bepansrade raser lämpade för krigsveteraner.",al={"typer av vargriddjur","vilka vargar säljer ogunaro"}}},fx={["37d9a7a8"]={q="På vems sida står Ogunaro Wolfrunner?",a="Ogunaro Wolfrunner är helt lojal mot Horden och staden Orgrimmar. Han tar hand om hordens uppskattade riddravar i Valley of Honor och förser sina orciska fränder och dem som har förtjänat Orgrimmars djupa förtroende och vördnad med riddjur.",al={"ogunaro wolfrunners fraktion","vem tjänar ogunaro","ogunaro, horden eller alliansen"}},c9c48f43={q="Varför är Ogunaro Wolfrunner här i Valley of Honor?",a="Ogunaro bor i Orgrimmars Valley of Honor, precis utanför Hunter's Hall. Det här kvarteret är en tränings- och samlingsplats för hordens hårdaste krigare och jägare, så det är den naturliga platsen att stalla, föda upp och erbjuda tåliga krigsvargar till beprövade mästare.",al={"varför är ogunaro i orgrimmar","ogunaro wolfrunners plats","varför är ogunaro här"}},c3908665={q="Vad vill Ogunaro Wolfrunner?",a="Ogunaro ägnar sitt hantverk åt att föda upp och tillhandahålla starka, pålitliga vargar åt hordens mästare. Han vill bara se till att orcfolkets ikoniska riddjur får skickliga ryttare som vet hur de ska behandlas och ledas i strid.",al={"vad vill ogunaro","ogunaros mål","ogunaro wolfrunners motiv"}}},fp="18,200,18.419.0,26.143.0,36.181.0,37.115.0"}
P.entries["npc:old-murk-eye"] = {n="Old Murk-Eye",s="Nära Westfall Lighthouse stryker Old Murk-Eye omkring längs sydkusten. Hans gelikar vördar honom, och sjömän fruktar det dödliga hot han utgör för alla som kommer nära fyren.",h="Nära Westfall Lighthouse stryker Old Murk-Eye omkring längs sydkusten.",kw={"captain grayson","kustens hot","murk-eye","murloc","old murk-eye","westfall","westfall lighthouse"},ang={["faction:Alliance"]="För alliansens äventyrare som rensar Westfall är Old Murk-Eye ett ökänd rovdjur som jagar strandade resenärer och skeppsbesättningar."},sec={{t="Kustens skräck",b="Old Murk-Eye stryker omkring i bränningarna runt Westfall Lighthouse, där han är betydligt tåligare och mer aggressiv än de murlocs som är vanliga längs Westfalls stränder. Hans attacker har vållat de lokala sjömännen så mycket sorg att den vålnadslika Captain Grayson vill se honom död. Grayson utlovar en belöning för Old Murk-Eyes felfria fjäll och hoppas kunna bryta hans grepp om de grunda vattnen."}},faq={{q="Var strövar Old Murk-Eye omkring?",a="Old Murk-Eye patrullerar de sandiga stränderna och grunda vattnen i sydvästra Westfall, längs kusten nära Westfall Lighthouse.",al={"old murk eye plats","var hittar man old murk eye","var finns murk eye"}},{q="Varför vill Captain Grayson att Old Murk-Eye ska dö?",a="Captain Grayson ser Old Murk-Eye som ett ständigt hot mot kustvattnen. Han utlovar en belöning för ett fjäll som bevis på dådet och hoppas kunna hejda våldet längs stranden.",al={"grayson murk eye","varför döda old murk eye"}},{q="Skiljer sig Old Murk-Eye från vanliga murlocs?",a="Ja. Old Murk-Eye är starkare, tåligare och mer aggressiv än lakejerna Coastrunner och Tidehunter omkring honom. Han fungerar som en stamkämpe bland de lokala flockarna längs kusten.",al={"hur tuff är murk eye","är murk eye en elit"}}},fx={["0038f035"]={q="Vem är Old Murk-Eye?",a="Old Murk-Eye är en ökänd och härdig murloc som patrullerar Westfalls kust nära Westfall Lighthouse. Både lokalbefolkningen och sjömän känner honom som ett kustnära hot. Bland sina fränder utmärker han sig som en ovanligt tålig och listig varelse vars närvaro ständigt hotar alla som går längs västkusten.",al={"vem är murk-eye","vem är old murk-eye","old murk-eyes bakgrund"}},["295d9e5f"]={q="På vems sida står Old Murk-Eye?",a="Old Murk-Eye kämpar bara för sig själv och sina murlocfränder längs stranden. Han är inte lojal mot något kungarike, gille eller någon fraktion och ser luftandare och landkrabbor som inkräktare på hans revir, som ska drivas bort eller dödas.",al={"murk-eyes fraktion","vem arbetar murk-eye för","tillhör murk-eye alliansen"}},["48ac0465"]={q="Varför är Old Murk-Eye i Westfall?",a="Old Murk-Eye gör anspråk på kustvattnen och de klippiga stränderna kring Westfall Lighthouse som sitt jaktområde. Den isolerade kusten erbjuder gott om fisk och en bas för räder mot oförsiktiga resenärer eller sjömän som lidit skeppsbrott längs den klippiga kusten.",al={"varför är murk-eye här","varför är old murk-eye i westfall","murk-eyes bakgrund och plats"}},["5afdb8dc"]={q="Varför är Old Murk-Eye berömd eller fruktad?",a="Old Murk-Eye har blivit känd bland sjömän och lokalbefolkningen som ett beryktat hot i bränningarna vid Westfall. Han är starkare och mer aggressiv än vanliga kustmurlocer, har överlevt otaliga skärmytslingar och terroriserat alla som närmar sig kusten vid fyren, tills sådana som Captain Grayson sätter en belöning på hans huvud.",al={"varför är murk-eye fruktad","varför är old murk-eye ökänd","legenden om murk-eye"}}},fp="12,178,23.354.0,31.128.0,48.177.0,48.182.0"}
P.entries["npc:old-serra-kis"] = {n="Old Serra'kis",s="Old Serra'kis är en uråldrig, väldig threshadon som lever i Blackfathom Deeps nedsänkta underjordiska vatten. Det enorma odjuret gömmer sig i en översvämmad grotta under ruinerna och är dödligt för alla som söker upp det.",h="Old Serra'kis är en uråldrig, väldig threshadon som lever i Blackfathom Deeps nedsänkta underjordiska vatten.",kw={"blackfathom deeps","forgotten pool","moonshrine sanctum","old serrakis","serrakis","threshadon","twilight's hammer","undervattensboss"},ang={["class:Druid"]="Vildmarksdruider har stor nytta av Aquatic Form när de dyker ner i den ljuslösa pölen för att möta detta förhistoriska rovdjur.",["class:Shaman"]="Water Breathing-besvärjelser, som ges genom andlig samhörighet med elementen, ser till att dina följeslagare inte drunknar när de kämpar mot den uråldriga threshadonen.",["class:Warlock"]="En warlocks förmåga att skänka Unending Breath gör ett annars dödligt bakhåll i den luftlösa underjordiska grottan till en hanterbar strid."},sec={{t="Obesegrad i djupet",b="Twilight's Hammer har slagit sig ner i de sjunkna Moonshrine Ruins, men i det mörka vattnet under Moonshrine Sanctum döljer sig äldre och vildare ting. Old Serra'kis, den största threshadonen i det sjunkna templet, lurar i Forgotten Pool, en översvämmad grotta under ruinerna där få skulle komma på att leta."},{t="Ett dolt hot",b="För att nå Old Serra'kis måste du dyka djupt under tempelgolvet, ner i en översvämmad grotta under ruinerna. Grottan saknar luftfickor och är lika dödlig som odjuret därinne. Den som tränger in honom i ett hörn upptäcker att Serra'kis har en onaturlig motståndskraft som suger åt sig skuggor. Han dränerar livet ur sina angripare och håller sig själv vid liv i det grumliga mörkret."}},faq={{q="Vad är Old Serra'kis för slags varelse?",a="Old Serra'kis är en väldig, uråldrig threshadon, en långhalsad vattenreptil som hör hemma i Azeroths sjöar och kustvatten.",al={"vad är serrakis","är serrakis en hydra","serrakis varelsetyp"}},{q="Varför dödade inte Twilight's Hammer honom?",a="Inget tyder på att sekten någonsin jagade honom. Old Serra'kis lurar utom synhåll i Forgotten Pool, en översvämmad, lufttom grotta under ruinerna, och är dödlig för alla som dyker ner efter honom.",al={"varför lever serrakis fortfarande","twilight's hammer serrakis"}},{q="Var finns Old Serra'kis?",a="Han lurar i en nedsänkt grotta under vattnet kring Moonshrine Sanctum i Blackfathom Deeps. Den som simmar måste dyka under ruinerna, ner i en lufttom pöl, för att möta honom.",al={"hur hittar man serrakis","serrakis plats","var finns old serrakis"}},{q="Vad gör det farligt att strida mot honom?",a="Förutom att striden utkämpas helt under vatten utan naturliga luftfickor, suger Old Serra'kis åt sig skuggenergi från alla fiender i närheten och läker sina egna sår under striden.",al={"serrakis förmågor","hur besegrar man serrakis"}},{q="Tjänar Serra'kis Twilight's Hammer?",a="Nej. Till skillnad från andra odjur som sekten har korrumperat eller dresserat är Old Serra'kis fortfarande ett helt otämjt vilddjur som försvarar sitt underjordiska näste.",al={"är serrakis ett sektens husdjur","vem kontrollerar serrakis"}},{q="Kan du andas under striden mot Serra'kis?",a="Hans slutna grotta saknar luftfickor vid taket. Därför måste den som strider under vatten hålla koll på andningen, använda magisk hjälp för att andas under vatten eller locka odjuret mot öppet vatten.",al={"drunkna serrakis","andas under vatten med serrakis"}}},fx={fc1a5d36={q="Varför är Old Serra'kis fruktad?",a="Old Serra'kis är den största tröskaren i Blackfathom Deeps, gömd i en översvämmad grotta under Moonshrine Ruins där det inte finns någon luft att andas. Han suger livet ur dem som slåss mot honom för att läka sina egna sår, vilket gör honom till en dödlig fiende för alla som dyker ner efter honom.",al={"serra'kis rykte","varför är serra'kis berömd","varför frukta serra'kis"}}},fp="13,192,25.298.0,15.331.0,39.123.0,42.171.0,31.180.0,34.157.0,43.137.0,49.170.0"}
P.entries["npc:onyxia"] = {n="Onyxia",s="Onyxia är svartdrakarnas modersdrake och Deathwings lömska dotter. I sitt draknäste i Dustwallow Marsh vakar hon över sin växande avkomma och samordnar sig med de ondskefulla svartdrakarna för att dominera de dödligas riken.",h="Onyxia är svartdrakarnas modersdrake och Deathwings lömska dotter.",kw={"anduin wrynn","svartdrakarna","bolvar fordragon","deathwing","nefarian","onyxia","stormwind"},sec={{t="Modersdraken vid hovet",b="Medan hennes bror Nefarian samlar sina styrkor i Blackrock Spire söker Onyxia makt genom list. Förklädd till Lady Katrana Prestor har hon nästlat sig in bland Stormwinds främsta adelsfamiljer. Som betrodd rådgivare åt Adelsrådet saboterar hon systematiskt rikets militära insatser. Hon undanhåller medvetet soldater och resurser från utposterna i Westfall, Redridge och Burning Steppes för att lämna de dödligas riken försvarslösa."},{t="Ruinens arkitekt",b="Bakom Lady Prestors leende döljer sig ett rovdjurs skarpsinniga planerare. När kung Varian försvunnit på väg till ett fredstoppmöte i Theramore utövar Prestor stort inflytande över pojkkungen Anduin och snärjer Highlord Bolvar Fordragon. Tronen balanserar på klorna till att falla i hennes händer."}},faq={{q="Vem är Lady Katrana Prestor?",a="Lady Katrana Prestor är en adelsdam från Stormwind och en betrodd rådgivare vid hovet. Sedan kung Varian försvunnit står hon vid pojkkungen Anduins och Highlord Bolvar Fordragons sida i Stormwind Keep. Hennes råd väger tungt hos Adelsrådet.",al={"prestorms identitet","vem är prestor","katrana prestors verkliga identitet"}},{q="Varför siktar Onyxia in sig på Stormwind?",a="Onyxia vill lägga kungariket Stormwind under svartdrakarnas inflytande, oskadliggöra dess militära styrka och hjälpa sin bror Nefarian att härska över området.",al={"onyxias mål","varför anfalla stormwind","prestors motiv"}},{q="Var bor Onyxia?",a="Onyxias hem är ett underjordiskt näste bland träsken i Dustwallow Marsh, där hon vakar över svartdrakarnas kullar.",al={"var finns onyxia","onyxias plats","var ligger onyxias näste"}},{q="Vilken koppling har hon till Nefarian och Deathwing?",a="Onyxia är aspekten Deathwings dotter. Hon är också Nefarians yngre syster och samarbetar nära med honom för att återupprätta svartdrakarnas herravälde över Azeroth.",al={"onyxias bror","onyxias far","onyxias familj"}}},fx={fd0ec0c3={q="På vems sida står Onyxia?",a="Onyxia tillhör enbart den svarta drakflykten och tjänar sin familjs mörka planer. I nära förbund med sin bror Nefarian arbetar hon för att återuppbygga deras korrumperade flykt och kuva de dödliga raserna. Hon svär ingen trohet till Alliansen eller Horden; dödliga kungadömen finns bara till för att manipuleras, försvagas och krossas så att de svarta drakarna kan härska.",al={"onyxias sida","vem tjänar onyxia","onyxias fraktion","onyxia alliansen eller horden"}},d77da3f3={q="Vad vill Onyxia?",a="Onyxia vill lägga kungariket Stormwind under den svarta drakflyktens inflytande. Hon försöker försvaga dess arméer och lämna riket försvarslöst, så att hennes avkomma och hennes bror Nefarians styrkor kan resa sig utan motstånd.",al={"vad vill onyxia","onyxias mål","onyxias motiv","vad är onyxis plan"}},ba62a202={q="Varför är Onyxia så fruktad?",a="Som Deathwings dotter och den svarta drakflyktens urmoder är Onyxia lika dödlig med sin fysiska styrka som med sin list. Även om hon är förhållandevis liten för att vara en fullvuxen drake är hennes attacker blixtsnabba, och hennes eldandedräkt kan smälta järn på några ögonblick. Tillsammans med hennes lömska förmåga att väva lögner bland dödliga utgör hon ett existentiellt hot mot Azeroth.",al={"varför är onyxia fruktad","är onyxia mäktig","onyxias rykte"}}},fp="6,267,28.488.1,17.294.2,28.254.2,33.170.2,23.138.2,49.178.0"}
P.entries["npc:orendil-broadleaf"] = {n="Orendil Broadleaf",s="Orendil Broadleaf är en skicklig Night Elf-ört- och läkekunnig vid Maestra's Post i västra Ashenvale. Han är känd för sina djupa kunskaper om skogens växter och blandar livsviktiga läkemedel för att rädda unga liv i de oroliga skogarna.",h="Orendil Broadleaf är en skicklig Night Elf-ört- och läkekunnig vid Maestra's Post i västra Ashenvale.",kw={"ashenvale","astranaar","bathran's hair","maestra's post","orendil broadleaf","orendil's cure","relara whitemoon"},ang={["profession:Herbalism"]="Orendil visar hur viktiga traktens växter är för att rädda liv. I fält förlitar han sig på sällsynta växter som Bathran's Hair för att brygga kraftfulla motgifter.",["race:NightElf"]="För Night Elves som försvarar Ashenvale är Orendil en oumbärlig livets väktare. Hans milda läkemedel kan rädda även ett dödssjukt barn."},sec={{t="Skogens gränsläkare",b="Vid Maestra's Post längs Ashenvales västra gräns tar Orendil Broadleaf hand om de sjuka som skicklig läkare. Han är känd för sina gedigna kunskaper om lokala örter och läkekonst och förlitar sig på förbipasserande resenärer för att samla sällsynta naturliga ingredienser. Även när spänningar och konflikter tränger in i skogen är hans outtröttliga fokus att skydda sitt folk och lindra deras sjukdomar."},{t="En kamp mot sjukdomen",b="Framför allt spelar Orendil en central roll i det desperata försöket att bota Relara Whitemoon, ett sjukt barn i Astranaar. Genom noggranna studier av skogens växter, däribland Bathran's Hair, tar han fram kraftfulla elixir som kan hålla dödlig sjukdom stången. Det visar hur kunskaper i örtlära förblir ett viktigt skydd mot farorna som hemsöker Ashenvale."}},faq={{q="Vem är Orendil Broadleaf?",a="Orendil Broadleaf är en Night Elf-ört- och läkekunnig som bor vid Maestra's Post i västra Ashenvale. Hans färdigheter med örter och läkekonst är välkända.",al={"orendil broadleaf","vem är orendil","orendil ashenvale"}},{q="Var finns Orendil Broadleaf?",a="Han finns vid Maestra's Post, en Night Elf-utpost längs huvudvägen i västra Ashenvale, nära gränsen till Darkshore.",al={"orendil broadleaf plats","hitta orendil","var finns orendil"}},{q="Vad försöker Orendil bota?",a="Orendil blandar till en läkande dryck för att rädda Relara Whitemoon, ett sjukt Night Elf-barn som bor i Astranaar. Han använder sällsynta örter som samlats i Ashenvales avlägsna vildmarker.",al={"orendils botemedel","vem botar orendil","relara whitemoons botemedel"}}},fx={c4fe2e8b={q="På vems sida står Orendil Broadleaf?",a="Orendil Broadleaf står stadigt på Alliansens och Darnassus nattalvers sida. Han är stationerad vid Maestra's Post och arbetar tillsammans med Väktarna för att försvara Ashenvale mot Hordens angrepp, samtidigt som han tar hand om sina fränders skador och sjukdomar.",al={"orendil broadleafs fraktion","är orendil broadleaf med i alliansen","orendil broadleafs lojalitet"}},["5dbbc739"]={q="Vad vill Orendil Broadleaf?",a="Orendil Broadleaf vill bota sjuka och sårade samtidigt som han skyddar skogen. Hans främsta uppgift är att blanda ett livsviktigt botemedel åt Relara Whitemoon, ett sjukt nattalvsbarn i Astranaar, och han förlitar sig på resande utifrån för att samla in de sällsynta örter som behövs för att rädda henne.",al={"vad vill orendil","orendil broadleafs mål","orendil broadleafs motiv"}},["9af45c4c"]={q="Varför är Orendil Broadleaf här?",a="Orendil stannar vid Maestra's Post som hängiven örtkännare och helare vid Ashenvales västra gräns. Där tar han hand om sina fränders sjukdomar och förlitar sig på förbipasserande resande för att samla in de sällsynta örter som hans läkemedel kräver.",al={"varför är orendil broadleaf vid maestras post","varför är orendil i ashenvale","vad gör orendil broadleaf här"}},["7beb4a99"]={q="Vilka har Orendil Broadleaf band till?",a="Orendil Broadleaf arbetar tillsammans med Väktarna som försvarar Maestra's Post och samordnar sig nära med Pelturas Whitemoon i Astranaar för att skydda Pelturas unga dotter, Relara.",al={"orendil broadleafs kontakter","med vilka arbetar orendil broadleaf","orendil broadleafs lärlingar"}}},fp="17,184,27.391.0,23.316.1,25.143.0,37.143.0,31.162.0"}
P.entries["npc:orenthil-whisperwind"] = {n="Orenthil Whisperwind",s="Orenthil Whisperwind är en Night Elf som bor på Teldrassil och påträffas under Shadowglens grenar.",h="Orenthil Whisperwind är en Night Elf som bor på Teldrassil och påträffas under Shadowglens grenar.",kw={"orenthil","shadowglen","teldrassil","whisperwind"},sec={{t="Ett välbekant ansikte på Teldrassil",b="Orenthil Whisperwind bor bland nattalverna i Shadowglen, under Teldrassils lövverk. Det finns få uppgifter om hans personliga historia."}},faq={{q="Vem är Orenthil Whisperwind?",a="Han är en Night Elf som finns i Shadowglen på Teldrassil. Han välkomnar äventyrare som ger sig av bland Världsträdets grenar.",al={"orenthil","information om orenthil whisperwind","vem är den här alven"}},{q="Var hittar jag Orenthil Whisperwind?",a="Orenthil bor i Shadowglen, nattalvernas startbosättning på Teldrassil.",al={"orenthils plats","var finns orenthil","orenthil karta"}}},fx={["38b36176"]={q="På vems sida står Orenthil Whisperwind?",a="Orenthil står stadigt på Darnassus nattalvers och den större Alliansens sida. Han bor bland sina fränder i Teldrassils grenar och hälsar nya resande välkomna när de kommer för att hjälpa hans folk.",al={"orenthil whisperwinds fraktion","är orenthil med i alliansen","vem tjänar orenthil"}},["71428597"]={q="Varför är Orenthil Whisperwind här?",a="Orenthil bor i Shadowglen på Teldrassil. Det finns inga uppgifter om varför han själv valde att slå sig ner där.",al={"orenthil whisperwinds syfte","varför är orenthil i dolanaar","vad gör orenthil"}}},fp="20,94,29.134.0,28.141.0,38.101.0"}
P.entries["npc:orgnil-soulscar"] = {n="Orgnil Soulscar",s="I Razor Hill håller Orgnil Soulscar utkik efter hot i Durotar. Han samlar in underrättelser och samordnar försvaret mot faror som hotar den unga orch-nationen, särskilt Burning Blade-kulten i ravinerna.",h="I Razor Hill håller Orgnil Soulscar utkik efter hot i Durotar.",kw={"burning blade","durotar","margoz","orgnil soulscar","razor hill","shadow council","skull rock"},ang={["class:Warlock"]="Som häxmästare måste du gå varsamt fram kring Orgnil, som fokuserar på att rensa ut okontrollerad demonisk korruption i Durotar.",["faction:Horde"]="Som medlem av Horden kan du lita på att Orgnil skyddar dess kärnland från kultister inom dess gränser medan Horden bygger sin nya nation.",["race:Orc"]="Som ung orch kan du se Orgnil som ett skydd mot den demoniska besmittelse som en gång förslavade klanerna. Hans arbete påminner nya rekryter om att hålla sig vaksamma och bevara sitt hemland rent."},sec={{t="Väktare i Razor Hill",b="I Razor Hill spårar Orgnil Soulscar dolda hot i hela Durotar. Medan grunt-patruller håller utkik efter Alliansens styrkor och kentaurplundrare letar han efter faror bland orcherna själva. Spejare kommer med rapporter från hela regionen, och han granskar dem efter tecken på korrumperade ritualer och hemliga sammankomster."},{t="På jakt efter Shadow Councils kvarlevor",b="Orgnil Soulscar jagar Burning Blade-kulten, vars häxmästare gömmer sig i grottor som Skull Rock. Felmagi ödelade orchfolket för generationer sedan, och han tänker inte låta demonisk dyrkan vinna mark nära Orgrimmar. Han skickar betrodda rekryter mot kultister för att samla in rituella talismaner. Han ber dem också rådfråga lokala eremiter och schamaner som Margoz om den mörka magi som verkar här."}},faq={{q="Vem är Orgnil Soulscar?",a="Orgnil Soulscar är en orchisk ämbetsman i Razor Hill som utreder hot och samordnar Durotars försvar. Han leder krigare och spejare mot faror som hotar de nyligen bosatta orchmarkerna.",al={"vem är orgnil","orgnil soulscars bakgrund","uppdragsgivare i razor hill"}},{q="Vilket hot oroar Orgnil mest?",a="Orgnil Soulscar har fullt fokus på att rensa ut Burning Blade-kulten. Dess närvaro i Durotars dolda grottor och dess korrumperande felmagi hotar den nystart för Horden som Thrall föreställer sig.",al={"vad vill orgnil","orgnils fiender","vem slåss orgnil mot"}},{q="Varför skickar Orgnil resande till Margoz?",a="Margoz är en kunnig eremit som bor norr om Razor Hill och förstår Burning Blades tecken och ritualer. Orgnil skickar spejare till honom för att tyda kultens rörelser och utreda den spridande magiska korruptionen.",al={"varför margoz","orgnil och margoz","vem är margoz för orgnil"}},{q="Var hittar man Orgnil Soulscar?",a="Orgnil Soulscar är stationerad utomhus i Razor Hill, nära Durotars centrala vägkorsning.",al={"orgnils plats","var finns orgnil","hitta orgnil soulscar"}},{q="Vad är Burning Blade i Durotar?",a="Burning Blade är en kult som står i förbund med demoniska herrar och Skuggornas råd. Dess medlemmar gömmer sig i raviner som Skull Rock och Dustwind Cave, där de försöker förgifta Durotars djurliv och locka unga orcher tillbaka i demonernas tjänst.",al={"burning blade i durotar","burning blade-kulten","vilka är burning blade"}},{q="Arbetar Orgnil direkt för Thrall?",a="Orgnil Soulscar verkar inom den regionala försvarsstyrkan i Razor Hill och utför hövdingens order att skydda Durotar från uppror och demoniskt inflytande.",al={"orgnil och thrall","är orgnil krigshövdingens vakt"}}},fx={["68dd86eb"]={q="På vems sida står Orgnil Soulscar?",a="Orgnil är helt lojal mot Horden och försvaret av Durotar. Han är stationerad i Razor Hill och upprätthåller den lokala ordningen och säkerheten. Han ägnar sina krafter åt att skydda de unga orchbosättningarna mot lömska inre hot, som Burning Blade-kultisterna som lurar i ravinens skuggor.",al={"orgnil soulscars fraktion","vem tjänar orgnil","orgnils lojalitet"}},["07ede484"]={q="Vad vill Orgnil Soulscar?",a="Orgnil vill spåra upp och utplåna Burning Blades skugga i Durotar. Han söker tillförlitliga upplysningar om kultisternas verksamhet och ger dugliga äventyrare i uppdrag att döda deras häxmästare, återta stulna talismaner och rådfråga lokala eremiter som Margoz för att reda ut den demoniska korruption som sprider sig över landet.",al={"vad vill orgnil","orgnils mål","orgnils syfte"}},["9d37257b"]={q="Varför är Orgnil Soulscar här i Razor Hill?",a="Razor Hill är Durotars centrala nav för försvar och logistik utanför Orgrimmar. Orgnil är stationerad här som utredare och beskyddare, med ett utmärkt läge för att hålla uppsikt över misstänkta rörelser i de torra dalarna och mobilisera resande mot kultister och fördärvade bestar som närmar sig.",al={"varför är orgnil i razor hill","orgnils roll i razor hill","varför är orgnil här"}},["05bd4129"]={q="Vilka har Orgnil Soulscar band till?",a="Orgnil samarbetar med Hordens lokala försvarare mot Burning Blade och hänvisar äventyrare till Margoz, som bor nordost om Razor Hill.",al={"orgnils allierade","orgnils kontakter","med vilka arbetar orgnil"}}},fp="15,206,21.304.0,37.388.1,23.187.0,41.192.0,41.220.0,35.87.0,37.225.1,37.166.0"}
P.entries["npc:orgrim-doomhammer"] = {n="Orgrim Doomhammer",s="Orgrim Doomhammer var den gamla hordens överste krigshövding under hela det andra kriget och ihågkoms som en av historiens största orchkrigare. Han dog när han befriade fånglägren i Arathi Highlands, men hans arv lever vidare i huvudstaden Orgrimmar och genom Thrall, som ärvde hans mäktiga krigshammare och svarta plåtrustning.",h="Orgrim Doomhammer var den gamla hordens överste krigshövding under hela det andra kriget och ihågkoms som en...",kw={"blackhand","blackrock","doomhammer","hammerfall","orgrim","orgrimmar","thrall","krigshövding"},ang={["faction:Alliance"]="För alliansen är Doomhammer fortfarande en mörk symbol för hur nära Eastern Kingdoms var att gå under under det andra kriget. Han slaktade otaliga mästare innan han besegrades vid Blackrock Spire.",["race:Orc"]="Orcherna vördar Orgrim Doomhammer som befriare. Han räddade deras folk från slöhet och fångenskap, och valde heder framför demoniskt slaveri."},sec={{t="Krigshövdingens väg till makten",b="Orgrim var först ställföreträdare åt Blackhand i Blackrock-klanen. Han avböjde det demoniska blod som Gul'dan erbjöd, men dolde sina tvivel bakom en stark lojalitet. Mot slutet av det första kriget äcklades han av Skuggrådets förräderi och mordet på barndomsvännen Durotan. Då dödade han Blackhand i en hedervärd strid. Som ny krigshövding rensade han skoningslöst ut Gul'dans trollkarlar och ledde horden genom Eastern Kingdoms under det andra kriget. Han var en förödande strateg som drev människornas kungadömen till ruinens brant, men besegrades till slut och tillfångatogs utanför Blackrock Spire efter att Gul'dans förräderi splittrat hans styrkor."},{t="Fall och arv",b="Efter att ha flytt från människornas fångenskap levde Doomhammer gömd tills han mötte Thrall, Durotans föräldralösa son. Den unge schamanens vision gav Orgrim ny kraft, och han samlade det som återstod av orchklanerna för att storma fånglägren och befria sitt folk. Under ett våldsamt slag vid ett läger i Arathi Highlands träffades krigshövdingen i ryggen av en lans. När han låg för döden gav han sin svarta plåtrustning, sitt förfädersvapen Doomhammer och titeln som krigshövding till Thrall. Till hans ära fick den befriade utposten namnet Hammerfall, och den nygrundade huvudstaden i Durotar döptes till Orgrimmar."}},faq={{q="Vem var Orgrim Doomhammer?",a="Han var hövding för Blackrock-klanen och krigshövdingen som ledde horden under det andra kriget. Flera år senare, efter att ha flytt från människornas fångenskap, stred han tillsammans med Thrall för att befria sina fängslade fränder. Han dog i Arathi Highlands.",al={"vem är doomhammer","orgrim doomhammer bakgrund","vem var krigshövding doomhammer"}},{q="Hur dog Orgrim Doomhammer?",a="Orgrim dödades under ett anfall mot ett mänskligt fångläger i Arathi Highlands, träffad i ryggen av en riddarlans. Thrall övertog hans uppdrag, och platsen för segern fick namnet Hammerfall till minne av hans offer.",al={"orgrim doomhammer död","hur dog doomhammer","vem dödade doomhammer"}},{q="Varför heter hordens huvudstad Orgrimmar?",a="Thrall gav den befästa staden i Durotar namn efter sin mentor och föregångare. Orgrim såg Thralls potential och utsåg honom till ny krigshövding, så att horden kunde återuppbyggas med heder i stället för demonisk fördärvelse.",al={"varför heter det orgrimmar","orgrimmars namne","stad uppkallad efter orgrim"}},{q="Drack Orgrim demonblodet?",a="Nej. Orgrim avstod från det demoniska blodet och dolde sina tvivel bakom sin lojalitet mot Blackhand. Därför kunde han behålla sitt klara sinne och till slut krossa Gul'dans Skuggråd inifrån.",al={"drack doomhammer blod","var orgrim korrumperad","orgrims demonblod"}}},fp="17,342,20.674.0,15.625.0,26.251.0,30.231.0,41.218.0,33.197.0"}
P.entries["npc:ormak-grimshot"] = {n="Ormak Grimshot",s="I Orgrimmars Valley of Honor tränar Ormak Grimshot jägare för ett liv i vildmarken. Med vargen Grimfang vid sin sida lär han Horde-jägare att spåra, skjuta och tämja bestar.",h="I Orgrimmars Valley of Honor tränar Ormak Grimshot jägare för ett liv i vildmarken.",kw={"bestträning","grimfang","jägartränare","hunter's hall","orgrimmar","ormak grimshot","valley of honor"},ang={["class:Hunter"]="Som Horde-jägare kan du lära dig av Ormak hur du tämjer och tar hand om en trogen djurföljeslagare.",["race:Orc"]="Som orch kan du se Ormaks samarbete med Grimfang som ett exempel på hur man arbetar sida vid sida med vargar och inhemska rovdjur för att försvara Durotar."},sec={{t="Jaktens mästare",b="Ormak Grimshot tränar Horde-spårare och prickskyttar i Hunter's Hall. Med vargen Grimfang vid sin sida lär han ut färdigheterna som krävs för att överleva i Kalimdors vildmark. Orcher och troll som har klarat sina prövningar i Durotar lär sig av honom att tämja och styra vilda bestar och skapa ett varaktigt band till ett djur som följer dem."}},faq={{q="Vem är Ormak Grimshot?",a="Ormak Grimshot tränar Horde-jägare i Orgrimmars Valley of Honor. Han lär ut distidsstrid och hur man bemästrar bestar.",al={"vem är ormak","ormak grimshot berättelse","ormak jägare tränare"}},{q="Var hittar jag Ormak Grimshot?",a="Ormak finns inne i Hunter's Hall i Orgrimmars Valley of Honor. Vargen Grimfang är nära honom.",al={"ormaks plats","var finns grimshot","hitta ormak"}},{q="Vem är vargen bredvid honom?",a="Vargen vid Ormak heter Grimfang och är hans trogna följeslagare. Deras band visar hur en jägare och ett djur som följer honom samarbetar.",al={"ormak varg","grimfang","ormaks husdjur"}},{q="Vilken roll har han för nya jägare?",a="Ormak lär nyblivna orcher och troll som är jägare att träna, mata och sköta bestar som de har tämjt efter sina grundläggande prövningar i Durotar.",al={"jägarens husdjursuppdrag orgrimmar","ormaks tämjningsuppdrag","training the beast ormak"}}},fx={["84e77df7"]={q="På vems sida står Ormak Grimshot?",a="Ormak är helt hängiven Horden och försvaret av Durotar. Han står bland tränarna i Valley of Honor och är lojal mot krigshövding Thralls nya nation och jägarna som skyddar dess gränser.",al={"ormaks fraktion","ormak horden eller alliansen","vem tjänar ormak"}},dac02825={q="Vad vill Ormak Grimshot?",a="Ormak vill se till att Hordens jägare är disciplinerade och skickliga skyttar som kan överleva i vildmarken. Tillsammans med sin tama varg, Grimfang, vill han vässa lovande spejares talanger och pröva deras påhittighet genom krävande utmaningar.",al={"ormaks mål","vad behöver ormak","ormak grimshots syfte"}},["88908d62"]={q="Varför är Ormak Grimshot i Valley of Honor?",a="Ormak är stationerad i Orgrimmars Valley of Honor, där han tränar skyttar i Hunter's Hall. Han håller sig nära Hordens militära nav, dit både erfarna spejare och unga lärlingar kommer för att få vägledning i bestbehärskning och fältkunskap.",al={"varför är ormak här","varför befinner sig ormak grimshot där","varför är ormak i orgrimmar"}}},fp="14,169,18.342.0,22.118.0,32.98.0,27.124.0,39.129.0"}
P.entries["npc:ormer-ironbraid"] = {n="Ormer Ironbraid",s="Ormer Ironbraid är en dvärgarkeolog stationerad vid Whelgar's Excavation Site i södra Wetlands. Hans teams historiska forskning har avbrutits våldsamt av glupska rovfåglar som invaderat utgrävningen. Ormer söker äventyrslystna bundsförvanter som kan röja undan bestarna och hämnas på dem som drev bort gruvarbetarna från platsen.",h="Ormer Ironbraid är en dvärgarkeolog stationerad vid Whelgar's Excavation Site i södra Wetlands.",kw={"dvärg","utgrävning","explorers league","ironbraid","ormer","rovfåglar","wetlands","whelgar"},ang={["class:Hunter"]="Jägare känner igen uppgiften Ormer ger dem och får mäta sin spårningsförmåga och skicklighet i att fälla bestar mot några av de våldsammaste rovfåglarna i Khaz Modan.",["faction:Alliance"]="Genom att hjälpa Ormer säkrar du vägen genom södra Wetlands och stöder Ironforges viktiga arkeologiska arbete.",["race:Dwarf"]="Ormer personifierar dvärgisk uthållighet – han vägrar låta en flock övervuxna ödlor ta forntida fädernegrund i besittning."},sec={{t="En utgrävning ur kurs",b="Ormer Ironbraid kom till Wetlands som en del av dvärgarnas försök att hitta titanreliker och utforska forntida historia vid Whelgar's Excavation Site. Tyvärr grävde de fram forntida stenar och grävde samtidigt upp – eller retade åtminstone upp – flockar av vilda rovfåglar från Wetlands. I stället för att katalogisera forntida lerkrukor och tavlor tillbringar Ormer dagarna med att se bestarna ströva bland ruinerna och ge näring åt sitt starka hat mot varelserna som störde deras arbete."},{t="En bitter fejd med klor",b="Ormer vägrar överge utgrävningen, men han har inte råstyrkan som krävs för att rensa platsen på egen hand. Han riktar sin frustration mot en systematisk utrotningskampanj och tar hjälp av förbipasserande resenärer för att döda allt större och våldsammare rovfåglar. För Ormer handlar det inte bara om artefakterna att återta utgrävningen – det är en djupt personlig fråga om dvärgisk stolthet och hämnd på den lokala faunan."}},faq={{q="Vem är Ormer Ironbraid?",a="Ormer Ironbraid är en dvärgforskare som övervakar arbetet vid Whelgar's Excavation Site i Wetlands. Han företräder Explorers' Leagues intressen i studierna av de forntida ruiner som ligger begravda i träsket.",al={"vem är ormer","ormer ironbraid","ormer wetlands"}},{q="Var hittar jag Ormer Ironbraid?",a="Han står på utsiktsplatsen ovanför Whelgar's Excavation Site, i de södra klipporna i Wetlands, strax öster om huvudvägen mot Loch Modan.",al={"ormers plats","var finns ormer","hitta ormer ironbraid"}},{q="Varför hatar Ormer rovfåglar så mycket?",a="De lokala rovfågelflockarna invaderade utgrävningsplatsen, drev bort dvärgarbetarna och stoppade alla arkeologiska framsteg. Ormer tog störningen som en personlig förolämpning och vill ge igen med full kraft.",al={"varför rovfåglar","ormer rovfåglar","ormers revenge bakgrund"}},{q="Vad är Whelgar's Excavation Site?",a="Det är en arkeologisk utgrävningsplats som grundades av dvärgar från Ironforge för att gräva fram forntida titanruiner och jordbundna ruiner under Wetlands. Aggressiva vilddjur har dock förvandlat utgrävningen till ett farligt slagfält.",al={"whelgars excavation site","vad är utgrävningsplatsen","utgrävningsplats i wetlands"}},{q="Vilka uppdrag erbjuder Ormer?",a="Ormer erbjuder den tredelade uppdragskedjan \"Ormer's Revenge\" där äventyrare får i uppgift att gallra ut allt större rovfåglar vid utgrävningsplatsen.",al={"ormers uppdrag","slå till mot jorden","ormers revenge uppdrag"}},{q="Tillhör Ormer Explorers' League?",a="Ja. Liksom många dvärgar som gräver ut forntida ruiner runt om i Khaz Modan arbetar Ormer för Ironforges arkeologiska expeditioner, som ägnar sig åt att hitta sitt folks titanarv.",al={"ormer explorers league","är ormer arkeolog"}}},fx={["97454981"]={q="På vems sida står Ormer Ironbraid?",a="Ormer är en lojal dvärg från Ironforge som står på Alliansens sida och stödjer dvärgarnas expeditioner runt Khaz Modan. Även om hans främsta fokus är att överleva i Wetlands vildmark och säkra utgrävningsplatsen står han stadigt vid sina fränders och Alliansens sida.",al={"ormers fraktion","är ormer med i alliansen","ormer ironbraids lojalitet"}},f4da8dc2={q="Vad vill Ormer Ironbraid?",a="Ormer vill inget hellre än att utrota de glupska rovfåglar som härjar vid Whelgar's Excavation Site. Bestarna invaderade expeditionens utgrävningar och drev bort utgrävarna. Han söker hämnd och upprättelse genom att döda varelserna så att platsen kan återtas.",al={"ormers mål","vad vill ormer","varför söker ormer hämnd"}},["60616fd2"]={q="Varför är Ormer Ironbraid här i Wetlands?",a="Ormer kom till Wetlands som del av den dvärgarkeologiska expeditionen vid Whelgar's Excavation Site. I stället för att lugnt gräva fram forntida skatter fann han sig dock fångad i en bitter kamp för överlevnad när traktens rovfåglar svärmade över utgrävningen.",al={"varför är ormer vid utgrävningsplatsen","ormer ironbraids syfte i wetlands","varför är ormer här"}}},fp="15,162,14.399.0,24.397.0,23.138.0,33.139.0,36.169.0,34.208.0,29.121.0,47.166.0"}
P.entries["npc:orokk-omosh"] = {n="Orokk Omosh",s="I Orgrimmars Valley of Honor håller Orokk Omosh familjens smideshantverk vid liv. Den åldrande orchen har inga barn som kan ärva det, så han söker värdiga lärlingar från Horde som kan lära sig familjen Omoshs hemligheter inom rustningssmide.",h="I Orgrimmars Valley of Honor håller Orokk Omosh familjens smideshantverk vid liv.",kw={"barbaric battlements","smide","glädjedansen","omosh","orksmed","orgrimmar","orokk omosh","valley of honor"},ang={["faction:Horde"]="Som medlem av Horde kan du hjälpa till att bevara traditionella orciska tekniker för plåt- och ringbrynjor, så att de finns tillgängliga för krigarna som försvarar den spirande Horde.",["profession:Blacksmithing"]="Som smed från Horde kan du lära dig av Orokk Omosh och hjälpa till att bevara familjens urgamla hantverk."},sec={{t="En släktlinje vid vägs ände",b="I Valley of Honor är Orokk Omosh den siste smeden i Omosh-släkten. Han har inga barn som kan ärva hans hantverk, och han tänker inte låta familjens tekniker dö med honom. Skickliga smeder från Horde kan genomgå hans krävande prov i metallarbete. De som visar sin hängivenhet får lära sig de högt aktade hemligheterna inom Omosh-rustningssmide."},{t="Ässjans anda",b="Bland andra hantverkare är Orokk känd för sin högljudda glädje över verklig skicklighet. De som klarar hans hantverksprov får ofta se honom utföra Omosh glädjedans, ett jublande firande av traditionellt smide som ekar genom Orgrimmars salar."}},faq={{q="Vem är Orokk Omosh?",a="Orokk Omosh är en åldrande orcisk smed i Orgrimmars Valley of Honor. Han är den siste smeden i Omosh-släkten och söker värdiga lärlingar från Horde som kan bevara familjens hantverk.",al={"vem är orokk","orokk omosh-lore","orksmed orgrimmar"}},{q="Var finns Orokk Omosh?",a="Du hittar Orokk Omosh vid smidesugnarna och städen i Orgrimmars Valley of Honor, i den nordöstra delen av staden.",al={"orokk omoshs plats","var finns orokk","hitta orokk omosh"}},{q="Varför lär Orokk ut familjehemligheterna till utomstående?",a="Orokk har inga barn som kan ärva familjens hantverk. Han undervisar skickliga smeder från Horde som visar sig klara hans prov, så att Omosh-teknikerna inte dör med honom.",al={"varför ger orokk uppdrag","omosh-arvet","varför lära smeder"}},{q="Vad är ”Omosh Dance of Joy”?",a="Omosh glädjedans är en jublande dans som Orokk utför när en hantverkare visar sitt värde och bemästrar hans släkts smidestekniker. Det är hans livfulla hyllning till hantverket.",al={"glädjedansen","omosh-dansen","omosh glädje"}}},fx={df415c30={q="På vems sida står Orokk Omosh?",a="Orokk Omosh är lojal mot Thralls Horde. Från Orgrimmars livliga hjärta delar han gärna med sig av släktens hårt förvärvade hantverk och gamla metallurgiska traditioner, men endast med lovande smeder från Horden.",al={"orokk omoshs fraktion","vem tjänar orokk omosh","är orokk omosh med i horden"}},["1085ff21"]={q="Vad vill Orokk Omosh?",a="Som den sista levande medlemmen av en vördad släkt av orksmeder, och utan egna barn, vill Orokk framför allt bevara sin familjs arv. Han söker skickliga smeder som förtjänar att bemästra och föra Omosh-familjens vapensmedsteknik vidare innan den går förlorad för alltid.",al={"vad vill orokk omosh","orokk omoshs mål","varför söker orokk efter smeder"}},["5e3af98e"]={q="Varför är Orokk Omosh här i Orgrimmar?",a="Orokk har slagit sig ned i Valley of Honor i Orgrimmar, där hordens främsta krigare, slagskämpar och hantverkare samlas. Det är den självklara mötesplatsen för de mäktiga hantverkare och hängivna rustningssmeder som han hoppas ska föra hans förfäders yrke vidare.",al={"varför är orokk omosh i orgrimmar","varför är orokk omosh här"}}},fp="11,205,20.325.0,23.257.0,19.179.0,31.130.0,57.166.0,33.175.0"}
P.entries["npc:orphan-matron-battlewail"] = {n="Orphan Matron Battlewail",s="I Valley of Honor i Orgrimmar tar Orphan Matron Battlewail hand om barn som förlorat sina familjer i krig. Tillsammans med Tosamina ger hon dem husrum och uppfostrar unga orcher.",h="I Valley of Honor i Orgrimmar tar Orphan Matron Battlewail hand om barn som förlorat sina familjer i krig.",kw={"battlewail","children's week","orgrimmar","orphan matron battlewail","barnhem","tosamina","valley of honor","hordens vårdare"},ang={["faction:Horde"]="För Horde ger Battlewail vägledning och husrum åt barn som kriget lämnat efter sig och hjälper till att bevara folkets framtid.",["race:Orc"]="Som orch som söker ett varaktigt hemland i Durotar kan du se i Battlewails barnhem vilka uppoffringar ditt folk uthärdar."},sec={{t="Hordens ungdomars vårdare",b="Orphan Matron Battlewail tar hand om barn som förlorat sina anhöriga i våld. I Orgrimmar, där krigets följder når ända in i den unga huvudstaden, ger hon och Tosamina nästa generation i Horde husrum och omsorg. Barnhemmet i Valley of Honor öppnar sina dörrar för äventyrare på genomresa. Under Children's Week får resenärer i uppdrag att vägleda barnen."}},faq={{q="Vem är Orphan Matron Battlewail?",a="Orphan Matron Battlewail är en orch som förestår barnhemmet i Orgrimmar. Hon ger husrum åt barn vars föräldrar dött i strid och uppfostrar dem.",al={"battlewails roll","vem är battlewail","moder battlewail"}},{q="Var i Orgrimmar kan hon hittas?",a="Battlewail och Tosamina tar hand om barnen i Valley of Honor i Orgrimmar, i stadens östra delar.",al={"battlewails plats","var ligger barnhemmet","hitta battlewail"}},{q="Vilken roll har hon under Children's Week?",a="Under Children's Week skickar Battlewail frivilliga hjältar på äventyr med ett föräldralöst barn för att visa det Hordes under och arv.",al={"battlewail under children's week","hordens vårdare","föräldralös uppdrag"}},{q="Vem hjälper Battlewail på barnhemmet?",a="Tosamina bor och arbetar tillsammans med Battlewail och hjälper till att vaka över och skydda barnen de tar hand om.",al={"tosamina","hjälpare åt föräldralösas föreståndare"}}},fx={["5bd84e8a"]={q="Vilken sida står Orphan Matron Battlewail på?",a="Matron Battlewail står troget på hordens sida. Hon bor i Orgrimmar och ägnar sitt liv åt att uppfostra barnen till stupade krigare i horden, så att de växer upp starka, trygga och stolta över sitt folks arv.",al={"battlewails fraktion","är battlewail med horden"}},c46a64f6={q="Vad vill Orphan Matron Battlewail?",a="Hennes främsta mål är att se till att de föräldralösa barn hon tar hand om är trygga, mår bra och får växa upp. Särskilt under Barnens vecka söker hon pålitliga äventyrare som kan ta med barnen ut i världen och visa dem livet utanför Orgrimmars murar.",al={"battlewails mål","vad vill föreståndaren för barnhemmet"}},["8b214374"]={q="Varför är Orphan Matron Battlewail här?",a="Battlewail driver barnhemmet i Orgrimmar i Valley of Honor tillsammans med sin följeslagare Tosamina. Ständiga konflikter runtom i Kalimdor gör att många unga orcher förlorar sina föräldrar, så hennes medkännande men ståndaktiga omsorg är livsviktig för staden.",al={"varför är battlewail i orgrimmar","varför är battlewail här"}}},fp="24,166,30.365.0,32.139.0,36.108.0,40.129.0,40.105.0"}
P.entries["npc:orphan-matron-nightingale"] = {n="Orphan Matron Nightingale",s="På Cathedral Square tar Orphan Matron Nightingale hand om Stormwinds föräldralösa barn. Hon och Matron Shellene ger dem tak över huvudet och vägledning, och bjuder in Alliansens äventyrare att tillbringa Children's Week med dem.",h="På Cathedral Square tar Orphan Matron Nightingale hand om Stormwinds föräldralösa barn.",kw={"cathedral square","children's week","matron shellene","nightingale","orphan matron nightingale","stormwind","stormwind barnhem"},ang={["class:Priest"]="Som präst känner du igen medkänslan och tjänstvilligheten som Nightingale visar utanför Cathedral of Light, dygder som Ljusets präster står för.",["faction:Alliance"]="Som mästare i Alliansen ser du i Nightingale krigets stillsamma kostnad och plikten att skydda rikets kommande generationer."},sec={{t="De fördrivnas beskyddare",b="Utanför barnhemmet, sydost om Cathedral of Light, tar Orphan Matron Nightingale hand om Stormwinds mest utsatta barn. Nyliga krig, gnollattacker och Defias Brotherhoods framväxt har lämnat många utan hem eller föräldrar. Nightingale och Matron Shellene ger dem tak över huvudet, grundläggande omsorg och vägledning under Church of the Holy Lights uppsikt."},{t="Barnens veckas beskyddare",b="Matron Nightingale tror att barn behöver hopp såväl som mat och tak över huvudet. Varje Children's Week ber hon Alliansens hjältar att ta med ett föräldralöst barn på resor genom Azeroth. Hon hoppas att möten med berömda mästare ska stärka barnens självförtroende, visa dem den större världen bortom stadsmurarna och påminna dem om att de inte är bortglömda."}},faq={{q="Var hittar man Orphan Matron Nightingale?",a="Orphan Matron Nightingale finns utanför Stormwind Orphanage på Cathedral Square, sydost om Cathedral of Light.",al={"matron nightingale plats","stormwind barnhem plats","var finns nightingale"}},{q="Varför finns det så många föräldralösa barn i Stormwind?",a="Stormwind har många föräldralösa barn eftersom förödande krig, däribland det tredje kriget, och pågående skärmytslingar med Defias Brotherhood, rester av orcher och fientliga bestar har dödat många stadsbor och gränsbönder och lämnat barn utan hem.",al={"varför finns det föräldralösa barn","stormwinds föräldralösa barns ursprung","vilka är barnen"}},{q="Vad är Children's Week?",a="Children's Week är en årlig högtid i Stormwind som anordnas av Matron Nightingale. Alliansens äventyrare följer med ett föräldralöst barn på resor för att se den större världens underverk och hjältar.",al={"childrens week stormwind","vad är children's week","evenemang för föräldralösa barn"}},{q="Vem hjälper Matron Nightingale att sköta barnhemmet?",a="Matron Shellene hjälper Nightingale att uppfostra, mata och ge barnen tak över huvudet i och omkring barnhemmet.",al={"annan barnhemsföreståndarinna","vem driver barnhemmet","matron shellene"}}},fx={["9dba66e4"]={q="Vem är Orphan Matron Nightingale?",a="Orphan Matron Nightingale är den omtänksamma föreståndaren som driver barnhemmet i Stormwind City tillsammans med Matron Shellene. Hon håller till mitt i Cathedral Square och ägnar dagarna åt att ge skydd och omsorg åt barn som förlorat sina familjer i de skoningslösa krig och umbäranden som hotar kungariket.",al={"vem är matron nightingale","orphan matron nightingales bakgrund","vem driver barnhemmet i stormwind"}},e8925ab2={q="Vilken sida står Orphan Matron Nightingale på?",a="Hon är helt lojal mot Grand Alliance och folket i Stormwind. Hennes uppdrag utförs i Cathedral of Lights beskyddande skugga, där hon outtröttligt hjälper kungarikets mest utsatta unga invånare och förlitar sig på hjältar från alliansen för att berika barnens liv.",al={"nightingales fraktion","är nightingale med alliansen","matron nightingales lojalitet"}},["1cac5069"]={q="Vad vill Orphan Matron Nightingale?",a="Hennes främsta angelägenhet är att barnen under hennes uppsikt mår bra, är lyckliga och får växa upp. Hon vill ge dem en trygg fristad i oroliga tider och tar under Barnens vecka hjälp av erfarna resenärer för att ge de unga hopp och en glimt av den stora världen utanför stadsmurarna.",al={"matron nightingales mål","vad vill nightingale","nightingales syfte"}},e192fa2f={q="Varför är Orphan Matron Nightingale här?",a="Hon håller till precis utanför barnhemmets trappa i Cathedral Square för att ta hand om barnen och hälsa besökare välkomna. Från stadens livliga, heliga hörn sköter hon barnhemmets dagliga rutiner och söker upp välvilliga äventyrare som är villiga att hjälpa barnen hon ansvarar för.",al={"varför är matron nightingale i cathedral square","varför är nightingale utanför barnhemmet","varför är nightingale här"}}},fp="25,206,25.357.0,22.348.0,45.129.0,43.261.0,24.186.0,47.100.0"}
P.entries["npc:osric-strang"] = {n="Osric Strang",s="I Stormwinds Old Town förser den erfarne rustningshandlaren Osric Strang trötta resenärer och Alliansens försvarare med slitstark utrustning. Hans butik, Limited Immunity, specialiserar sig på tung ringbrynja och plåtrustningar samt sköldar.",h="I Stormwinds Old Town förser den erfarne rustningshandlaren Osric Strang trötta resenärer och Alliansens...",kw={"dungar longdrink","tung rustning","limited immunity","old town","osric strang","sköldar","handlare i stormwind"},ang={["class:Warrior"]="Som krigare på besök i Old Town kan du hitta pålitlig ringbrynja, fjällrustning, plåtrustning och sköldar hos Osric, som ger ett stadigt skydd.",["faction:Alliance"]="Som medlem av Alliansen kan du lita på att Stormwindbon Osric utrustar kungarikets försvarare och hjälper kurirer att hålla försörjningsförbindelserna mellan Stormwind och avlägsna bosättningar vid liv."},sec={{t="Föreståndare för Limited Immunity",b="Osric Strang driver Limited Immunity, där kämpar hittar tunga rustningar och sköldar. Han hjälper också kurirer som anländer och behöver en kontaktperson i huvudstaden, däribland de som kommer från närliggande bosättningar som Sentinel Hill i Westfall."}},faq={{q="Vad säljer Osric Strang?",a="Osric säljer tung skyddande rustning, däribland förstärkt ringbrynja, polerad fjällrustning, robusta helplåtrustningar, bucklare och heater shields.",al={"osrics föremål","vad har osric strang","varor från limited immunity"}},{q="Var hittar jag Osric Strang?",a="Du hittar Osric i Limited Immunity, en rustningsbutik i Old Town nära Stormwinds södra stadsdel.",al={"osrics plats","var finns osric strang","limited immunitys plats"}},{q="Varför skickas jag till Osric Strang på ett uppdrag?",a="Kurirer som transporterar varor genom kungariket, däribland leveranser som anländer med gryphon master från Westfall, hänvisas till Osrics butik i Old Town för att lämna över dem och ta emot meddelanden tillbaka.",al={"varför prata med osric","uppdrag hos osric strang","leverans till osric"}}},fx={a4d8c3b8={q="Vem är Osric Strang?",a="Osric Strang är en rustningshandlare som arbetar i Limited Immunity, en butik i det livliga Old Town i Stormwind. Han försörjer sig på att utrusta äventyrare och stadsvakter med tunga ringbrynjor, plåtrustningar och rejäla sköldar.",al={"vem är osric","osric strangs bakgrund","osric strangs historia"}},["66b236b5"]={q="Vilken sida står Osric Strang på?",a="Osric Strang är en lojal medborgare i kungariket Stormwind och står stadigt med alliansen. Han tillhandahåller stolt skyddande krigsutrustning åt dem som försvarar riket.",al={"osric strangs fraktion","osric strangs lojalitet","är osric med alliansen"}},["9aee9a9e"]={q="Varför är Osric Strang i Stormwind?",a="Osric Strang driver Limited Immunity mitt i Old Town, en stadsdel känd för sina erfarna krigare, hantverkare och vapensmedjor. I Stormwind hittar han en stadig ström av rekryter, resenärer och försvarare som söker pålitliga tunga rustningar.",al={"varför är osric strang här","osric strangs butik","osric strang limited immunity"}}},fp="12,209,30.228.0,28.131.0,30.105.0,41.175.0"}
P.entries["npc:overlord-mok-morokk"] = {n="Overlord Mok'Morokk",s="Overlord Mok'Morokk är den brutale hövdingen över Stonemaul-ogrerna och styr Brackenwall Village i Dustwallow Marsh. Rexxar utsåg honom först för hans styrka, men han har blivit en tyrannisk och feg härskare som vägrar försvara sin klan mot den svarta drakflygeln.",h="Overlord Mok'Morokk är den brutale hövdingen över Stonemaul-ogrerna och styr Brackenwall Village i Dustwallow...",kw={"brackenwall","draz'zilb","dustwallow","mok'morokk","ogre","överherre","rexxar","stonemaul"},ang={["class:Warrior"]="Mok'Morokk är ett skolboksexempel på rå stridsstyrka utan heder eller mod. Han visar hur lätt brutal styrka förfaller till feghet och tyranni.",["faction:Horde"]="Stonemaul-ogrerna är värdefulla allierade som svurit trohet till Horden sedan Rexxars fälttåg, men Mok'Morokks ineffektiva och fega ledarskap hotar att göra Brackenwall Village helt försvarslöst."},sec={{t="En tyrann i träsket",b="När Rexxar besegrade den förre hövdingen Kor'gall och ledde Stonemaul-klanen till Durotars försvar, lämnade han Mok'Morokk vid makten eftersom han såg löften i hans råa stridsstyrka. Det förtroendet visade sig vara felplacerat. Mok'Morokk dukade snabbt under för det absoluta enväldets fördärvande inflytande och styr genom skrämsel och självsvåld i stället för att ta ansvar. I stället för att ta hand om sina fränder kräver han oförtjänt tribut, slappar i Brackenwall Village och trakasserar alla som ifrågasätter hans makt."},{t="Brackenwalls fegis",b="Mok'Morokks ledarskap föll samman helt när den svarta drakflygeln anföll Stonemaul Village, klanens uråldriga hem, dödade många ogrer och drev de överlevande ut i Brackenwalls träsk. I stället för att samla till motangrepp för att återta hemmet eller hämnas de döda förbjöd Mok'Morokk alla försök och hukade sig av rädsla för drakarnas vrede. Missnöjet gror bland hans rådgivare, som ogremagikern Draz'Zilb. De söker i det tysta efter hjältar utifrån som är villiga att utmana överherrens skamliga styre."}},faq={{q="Vem är Overlord Mok'Morokk?",a="Mok'Morokk är hövding över Stonemaul-ogrerna och bor nu i Brackenwall Village i Dustwallow Marsh. Rexxar utsåg honom till ledare, men han förföll snabbt till en självisk och krävande despot.",al={"vem är mok'morokk","ledare i brackenwall","stonemaul-ogrernas ledare"}},{q="Hur blev Mok'Morokk ledare för Stonemaul-klanen?",a="Under Durotars grundande besegrade Rexxar, hordens förkämpe, klanens förre ledare och tog kommandot över Stonemaul. När Rexxar gav sig av för att ströva genom vildmarken utsåg han Mok'Morokk till överherre på grund av hans råa fysiska styrka.",al={"hur fick mok'morokk makten","rexxar valde mok'morokk","varför är han hövding"}},{q="Varför befinner sig Stonemaul-ogrerna i Brackenwall Village?",a="Stonemaul-ogrerna bodde ursprungligen i Stonemaul Village, men svarta drakar anföll och ödelade deras bosättning. De överlevande flydde norrut in i träskmarkerna och grundade Brackenwall Village som en utpost för flyktingar.",al={"varför flyttade ogrerna till brackenwall","vad hände med stonemaul village","svarta drakar anfaller ogre"}},{q="Varför tänker Mok'Morokk inte strida mot den svarta drakflygeln?",a="Trots sin väldiga storlek och sitt rykte som fruktad kämpe är Mok'Morokk livrädd för drakarna. I stället för att leda ett motangrepp för att återta sin klans uråldriga territorium sitter han sysslolös i Brackenwall, samlar på sig tribut och ignorerar sitt folks rop på hjälp.",al={"varför strider inte mok'morokk mot drakar","är mok'morokk feg","återta stonemaul"}},{q="Respekterar de andra Stonemaul-ogrerna Mok'Morokk?",a="Klanen blir alltmer bitter över hans lättja, feghet och mobbande. Hans rådgivare oroar sig för Stonemauls framtid under hans styre.",al={"gillar ogrerna mok'morokk","draz'zilb mok'morokk","stonemaul-uppror"}}},fp="19,280,21.497.0,25.495.1,27.205.0,55.258.0,51.209.0,50.250.0,48.148.1"}
P.entries["npc:overlord-ramtusk"] = {n="Overlord Ramtusk",s="Overlord Ramtusk är en väldig quilboar-krigsherre som leder krigarna djupt inne i Razorfen Kraul. Han vrålar efter seger och åkallar Agamaggan när han strider i spetsen för sitt elitgarde. Fäller du honom krossar du Kraul-försvararnas militära ryggrad.",h="Overlord Ramtusk är en väldig quilboar-krigsherre som leder krigarna djupt inne i Razorfen Kraul.",kw={"the barrens","deaths head","overlord ramtusk","quilboar","ramtusk","razorfen kraul"},ang={["class:Warrior"]="Ramtusk är sinnebilden av en rå, stridsvan veteran. Han förlitar sig på dånande slag och befallande stridsrop snarare än schamanernas geomanti eller törnmagi.",["race:Orc"]="Quilboarerna har aktivt plundrat Hordens bosättningar sedan Durotar grundades och utposterna i The Barrens anlades. Om du bryter Ramtusks militära befäl säkrar du södra The Barrens.",["race:Tauren"]="I generationer har The Barrens nomadstammar utkämpat bittra skärmytslingar mot quilboarerna i Kraul. När du fäller honom hämnas du de stupade krigarna."},sec={{t="Kraulens krigsherre",b="Overlord Ramtusk för befälet djupt inne i Razorfen Krauls taggiga labyrint, quilboar-fästet i södra The Barrens. Han går ut i strid med ett krigsrop till galtens halvgud Agamaggan och styr Krauls krigare med obeveklig auktoritet."},{t="Befälhavare över Kraul",b="Bland Krauls slingrande snår leder Ramtusk quilboar-krigarna. Som deras krigsherre upprätthåller han strikt disciplin bland de borstiga kämpar som försvarar stammens helgedom. Med elitbågskyttar vid sin sida strider Ramtusk som en berserk i främsta ledet. Han vrålar uppmuntrande rop och utdelar jordskakande slag som kan bryta fiendens stridslinjer på några sekunder."}},faq={{q="Vem är Overlord Ramtusk?",a="Overlord Ramtusk är en quilboar-krigsherre som för befälet över krigare djupt inne i Razorfen Kraul. Han är en väldig, respektingivande kämpe som går ut i strid med rop efter seger och till Agamaggans ära.",al={"vem är ramtusk","ramtusks bakgrund","overlord ramtusk"}},{q="Var finns Overlord Ramtusk?",a="Han för befälet över sitt elitgarde från den taggiga kärnan av Razorfen Kraul, längst söderut i The Barrens.",al={"ramtusks plats","var finns ramtusk","overlord ramtusk karta"}},{q="Vilka fiender har Ramtusk stridit mot tidigare?",a="Inget finns nedtecknat om hans tidigare strider. I Kraul strider han i spetsen för sitt elitgarde och ropar efter seger och till Agamaggans ära mot alla främlingar som tränger igenom snåren.",al={"ramtusks fiender","vem gav ramtusk ärr","ramtusks stridshistoria"}},{q="Vilken stam tillhör Ramtusk?",a="Han är en av Razorfen-quilboarerna som håller det taggiga fästet Razorfen Kraul i södra The Barrens och vördar galtens halvgud Agamaggan.",al={"ramtusks fraktion","ramtusks stam","vilken quilboar-stam tillhör ramtusk"}},{q="Varför jagas Ramtusk av äventyrare?",a="Som krigsherren som leder Krauls krigare tillfogar Ramtusks död quilboarernas militära hierarki ett förödande slag och kastar deras försvarslinje i fullständig oordning.",al={"varför döda ramtusk","uppdraget take them down","skottpengar på ramtusk"}},{q="Hur strider Ramtusk?",a="Ramtusk strider som en klassisk, stridsvan krigare. Han använder nedbrytande rop för att stärka sin trupp, krossande chockvågor för att få fiender ur balans och samordnar sina rörelser med elitlivvakter beväpnade med avståndsvapen.",al={"ramtusks taktik","ramtusks stridsstil","ramtusks förmågor"}}},fx={["26eecf20"]={q="Vilken sida står Overlord Ramtusk på?",a="Overlord Ramtusk är en krigsherre bland quilboarerna i Razorfen Kraul. Han tjänar stammen som håller till i den taggiga labyrinten, leder deras krigare i försvaret av de förfäders törnsnår och riktar deras aggression mot främlingar som tränger in på deras område.",al={"vem tjänar ramtusk","ramtusks fraktion","ramtusks lojalitet"}},a2bf0d01={q="Varför är Overlord Ramtusk här i Razorfen Kraul?",a="Ramtusk övervakar försvaret och krigsordningen i Razorfen Kraul. Som överherre över Kraul-krigarna leder han sina trupper från törnsnårets djup och samordnar stammens kämpar för att skydda kraulens hjärta mot invaderande fiender.",al={"varför är ramtusk här","vad gör ramtusk i razorfen kraul","ramtusks roll"}},b0113e9e={q="Varför fruktar man Overlord Ramtusk?",a="Overlord Ramtusk är en väldig quilboarisk krigsherre som slåss i spetsen för sina elitvakter och ropar efter seger och Agamaggan. Med förkrossande slag och eggande stridsrop leder han Kraul-krigarna med en auktoritet som inger skräck hos alla som utmanar honom.",al={"varför fruktar man ramtusk","hur stark är ramtusk","ramtusks rykte"}}},fp="16,184,20.216.0,22.316.0,24.156.0,36.110.0,44.167.0,34.128.0,39.142.0,23.180.0"}
P.entries["npc:ozzie-togglevolt"] = {n="Ozzie Togglevolt",s="Ozzie Togglevolt är en gnomingenjör och överlevare från Gnomeregans fall. Han arbetar nu i den snöiga byn Kharanos i Dun Morogh. Förföljd av tragedin som drabbade hans folk forskar han tillsammans med sin partner Razzle Sprysprocket efter ett botemedel för de bestrålade spetälskegnomerna.",h="Ozzie Togglevolt är en gnomingenjör och överlevare från Gnomeregans fall.",kw={"dun morogh","gnoarn","gnomeregan","kharanos","spetälskegnom","ozzie","strålning","razzle","sprysprocket","togglevolt"},ang={["faction:Alliance"]="Ozzie håller till strax utanför Ironforge i Kharanos. Han hjälper resande samtidigt som han upprätthåller Alliansens fästen i Dun Moroghs iskalla kullar.",["profession:Engineering"]="Ozzie visar gnomernas hantverk i praktiken, där apparater kan slå tillbaka dramatiskt i strid eller leda till geniala genombrott inom biokemisk sanering.",["race:Gnome"]="För gnomäventyrare står Ozzie för de överlevandes sorg och beslutsamhet efter Gnomeregans fall. Han vägrar överge sina bestrålade fränder åt deras öde."},sec={{t="Flykt från djupet",b="Ozzie Togglevolt befann sig bland Gnomeregans underjordiska underverk när katastrofen slog till. När det giftiga nedfallet släpptes ut i korridorerna för att hejda trogginvasionen stod Ozzie precis bredvid sin gnomvän Gnoarn. En plötslig radioaktiv urladdning träffade Gnoarn direkt och förändrade honom för alltid inför Ozzies ögon. Ozzie lyckades ta sig upp till ytan levande och nå tryggheten i Dun Morogh, men det fasansfulla minnet av katastrofen lämnade honom aldrig."},{t="Verkstaden i Kharanos",b="Nu när Ozzie har slagit sig ner i Kharanos ägnar han dagarna åt att experimentera tillsammans med Razzle Sprysprocket. Deras främsta tekniska och vetenskapliga arbete är djupt personligt: att hitta ett sätt att vända det fasansfulla mutagena nedfallet från deras förlorade hem och bota de lidande spetälskegnomerna."}},faq={{q="Vem är Ozzie Togglevolt?",a="Ozzie Togglevolt är en gnomingenjör som bor i Kharanos i Dun Morogh. Han flydde Gnomeregans radioaktiva förödelse och ägnar nu sin tekniska expertis åt att hitta ett botemedel för sina drabbade fränder.",al={"vem är ozzie","ozzie togglevolts bakgrund","gnomen ozzie i kharanos"}},{q="Vad försöker Ozzie bota?",a="Ozzie och hans kollega Razzle Sprysprocket forskar efter en metod för att rena den giftiga strålning som förvandlade så många av deras fränder till vansinniga spetälskegnomer.",al={"vad forskar ozzie om","ozzies botemedel mot spetälskegnomer","botemedel mot spetälskegnomer"}},{q="Vad har Gnoarn för relation till Ozzie?",a="Gnoarn var med Ozzie i Gnomeregan när de giftiga utsläppen släpptes lös. Ozzie såg en radioaktiv blixt träffa Gnoarn direkt, en tragisk händelse som fick honom att bli besatt av att vända föroreningen.",al={"ozzie och gnoarn","vad hände med gnoarn","vem är gnoarn"}},{q="Vem arbetar med Ozzie i Kharanos?",a="Ozzie arbetar tillsammans med Razzle Sprysprocket. Tillsammans experimenterar de i Kharanos, tar fram blandningar och samlar in förorenade prover ute i fält för att analysera det radioaktiva nedfallet.",al={"ozzies partner","vem är razzle","razzle sprysprocket"}},{q="Vilka uppdrag erbjuder Ozzie?",a="Ozzie ber resande i Dun Morogh att samla in bestrålade rester och komponenter runt Gnomeregan genom uppdrag som 'The Day After', 'Gnogaine' och 'The Only Cure is More Green Glow'.",al={"ozzies uppdrag","togglevolts uppdrag","vilka uppdrag ger ozzie"}}},fx={["86f7524c"]={q="Vilken sida står Ozzie Togglevolt på?",a="Ozzie står helhjärtat med Gnomeregan Exiles och alliansen. Liksom många överlevande från Gnomeregans förödande fall har han tagit sin tillflykt bland dvärgarna i Dun Morogh och ägnar all sin tankekraft och skicklighet åt att hjälpa sina fördrivna gnomer.",al={"ozzie togglevolts fraktion","ozzie togglevolt med alliansen eller horden","vem tjänar ozzie togglevolt"}},["3c84fab0"]={q="Varför är Ozzie Togglevolt här i Dun Morogh?",a="Ozzie flydde till Kharanos efter den tragiska föroreningen av Gnomeregan. Han undkom den dödliga strålning som förvanskade så många av hans fränder och öppnade en verkstad med andra uppfinnare för att skapa en trygg bas nära nog för att studera följderna och hjälpa överlevande.",al={"varför är ozzie togglevolt i kharanos","varför är ozzie här","varför är ozzie togglevolt här"}}},fp="16,173,20.310.0,21.201.0,24.176.0,29.155.0,23.174.0,38.167.0,29.179.0"}
P.entries["npc:pao-ka-swiftmountain"] = {n="Pao'ka Swiftmountain",s="Pao'ka Swiftmountain är en ung taurennaturforskare som blivit strandsatt bland Highperchs vilda wyverner i Thousand Needles. Under resan söderut med Motega Firemane blev hans nyfikenhet för stor när han kom för nära en boplats och blev instängd bland klipporna.",h="Pao'ka Swiftmountain är en ung taurennaturforskare som blivit strandsatt bland Highperchs vilda wyverner i...",kw={"highperch","homeward bound","motega firemane","pao'ka swiftmountain","thousand needles","whitereach post","wyverner"},ang={["faction:Horde"]="Pao'ka står för nästa generation taurenlärda som utforskar Kalimdor. Om han överlever bevaras de starka banden till de äldre vid Whitereach Post.",["race:Tauren"]="Tauren vördar wyverner djupt som allierade och trogna riddjur, så Pao'kas illa planerade intrång är både pinsamt och farligt."},sec={{t="En naturforskare i knipa",b="Pao'ka kom till Thousand Needles kanjonland tillsammans med Motega Firemane, ivrig att katalogisera och studera de farliga bestarna i kanjonerna. Hans far hade tvekat inför att låta sin son ge sig ut på en så farofylld resa, och Pao'kas senaste missöde visar att oron var befogad. Den unge lärde fascinerades av de ståtliga wyvernerna på Highperch och smög uppför bergsstigen bakom en ensam taurentotem. Föga förvånande tog de revirhävdande bestarna illa upp av intrånget och drev honom djupt in bland klipporna. Där blev han instängd och skräckslagen, oförmögen att smita förbi rovdjuren som störtdök för att ta sig tillbaka till Whitereach Post."}},faq={{q="Vem är Pao'ka Swiftmountain?",a="Pao'ka är en ung taurenlärd som följde med Motega Firemane till Thousand Needles för att studera traktens djurliv, men blev instängd av revirhävdande wyverner på Highperch.",al={"vem är pao'ka","paoka swiftmountain","vem är tauren på highperch"}},{q="Var kan Pao'ka Swiftmountain hittas?",a="Han är strandsatt högst uppe på Highperch i Thousand Needles. För att nå honom måste du hitta en väldig taurentotem nära klipporna. En smal stig bakom den klättrar uppför bergssidan till wyvernernas boplatser.",al={"var är paoka","stigen på highperch","hur hittar man paoka"}},{q="Varför gömmer han sig på Highperch?",a="Hans fascination för wyverner fick honom att komma för nära ett av deras nästen. De rasande bestarna jagade bort honom och spärrade hans väg tillbaka, så han tvingades gömma sig i flera dagar.",al={"varför är paoka fast","varför attackerade wyverner paoka"}},{q="Vad händer när du hjälper honom att fly?",a="När han eskorterats ut ur boplatserna i säkerhet flyr Pao'ka tillbaka till Motega Firemane vid Whitereach Post. Han hoppas förtvivlat att hans mentor inte ska berätta om misstaget för hans far.",al={"utfallet av homeward bound","kommer paoka tillbaka"}}},fx={["3733bdd0"]={q="Vilken sida står Pao'ka Swiftmountain på?",a="Pao'ka tillhör horden. Han är en ung taurennaturkännare som reste in i ravinen under vägledning av sitt folks äldste och förlitar sig på hjältar från horden för att ta sig fram bland farorna i Thousand Needles.",al={"paoka swiftmountains fraktion","är paoka med horden","vilken sida står paoka swiftmountain på"}},ca840f79={q="Vad vill Pao'ka Swiftmountain?",a="Pao'ka vill ha säker eskort ut från Highperch och tillbaka till Whitereach Post utan att råka ut för sin mentors vrede. Han klättrade ivrigt upp bland klipporna för att studera de vilda wyvernerna, men efter att ha stört ett bo och blivit jagad till ett gömställe vill han framför allt komma därifrån med livet i behåll och slippa skickas hem till sin far i vanära.",al={"paokas mål","vad vill paoka","paoka swiftmountains motiv"}},["29fbd111"]={q="Vilka band har Pao'ka Swiftmountain?",a="Pao'ka går i lära hos Motega Firemane vid Whitereach Post, som övertalade Pao'kas tveksamma far att låta den unge ge sig ut i vildmarken för att studera traktens djur. Pao'ka bävar för att göra Motega besviken eller ge sin överbeskyddande far rätt genom att misslyckas med expeditionen.",al={"paoka swiftmountains kontakter","vem känner paoka","paokas mentor"}}},fp="20,303,23.650.0,28.172.0,40.202.0,30.169.0,39.178.1"}
P.entries["npc:parqual-fintallas"] = {n="Parqual Fintallas",s="Parqual Fintallas är en Forsaken-lärd och före detta mänsklig historiker från Lordaeron, som nu bor i Undercitys Apothecarium. Trots den dystra omgivningen i sitt odöda tillstånd behåller han sitt artiga sätt och sin bestående passion för forntida kunskap. Han hjälper ofta resande som skickats till honom för att ta del av hans djupa historiska sakkunskap.",h="Parqual Fintallas är en Forsaken-lärd och före detta mänsklig historiker från Lordaeron, som nu bor i...",kw={"apothecarium","fintallas","historiker","lordaeron","parqual","lärd","test of lore","undercity"},ang={["faction:Horde"]="När Hordens äventyrare ställs inför tankens prövningar snarare än klingan, bidrar Parqual med den djupa historiska visdom som behövs för att avslöja Azeroths forntida sanningar.",["race:Undead"]="Parqual påminner om Lordaerons intellektuella förflutna. I Apothecariums dysterhet håller han stillsamt fast vid lärdom och civiliserade samtal."},sec={{t="Lärd om det förlorade Lordaeron",b="I livet var Parqual en ansedd mänsklig lärd från Lordaeron som kunde allt om kungariket och fördjupade sig i historiska texter. När de odödas farsot slog till var Parqual en av de många invånare som dödades och återuppväcktes, tills han till slut bröt sig fri under Lady Sylvanas Windrunner. Medan Forsaken till stor del omfamnar kall pragmatism och vänder sig bort från sina forna liv, behåller Parqual sin passion för lärdom och sitt trevliga sätt. Han söker fortfarande upplysning, om än av ett annat slag än i livet."},{t="Väktare av forntida kunskap",b="Parqual bor bland de bubblande karen och alkemisterna i Undercitys Apothecarium. Trots sin makabra omgivning är han en ovärderlig källa till kunskap om Azeroths historia. När äventyrare ställs inför krävande intellektuella prövningar, som den svårfunna Test of Lore, hänvisas de till Parqual. Han skickar dem till Scarlet Monasterys bibliotek för att hämta en bok och ställer sedan en egen fråga till dem."}},faq={{q="Var hittar jag Parqual Fintallas?",a="Parqual Fintallas står i Apothecarium i Undercity, Forsakens huvudstad under ruinerna av Lordaeron.",al={"parqual fintallas plats","var finns parqual","parqual undercity"}},{q="Vad är Parqual Fintallas känd för?",a="I livet var Parqual en framstående historiker som nästan visste allt om kungariket Lordaeron. Även i döden är han en intellektuell auktoritet som hjälper äventyrare på jakt efter svårfunna historiska texter och forntida kunskap.",al={"vem är parqual","vad gör parqual","parqual fintallas bakgrund"}},{q="Varför medverkar Parqual i Test of Lore?",a="I Test of Lore måste äventyrarna visa prov på både kunskap och styrka. Tack vare sin lärda bakgrund står Parqual för en av prövningarna. Han skickar dem till Scarlet Monastery efter boken Beginnings of the Undead Threat och ställer sedan en fråga om den.",al={"parqual test of lore","test of lore undercity","parqual fintallas uppdrag"}},{q="Har Parqual samma fientliga sätt som de flesta Forsaken?",a="I vardagliga samtal är han vänlig och säger att det är trevligt när någon tar sig tid att prata med honom. Men han kan vara skarpt skeptisk mot dem som påstår sig ha klarat Braug Dimspirits prövningar, och han hyser bara förakt för Scarlet Crusade.",al={"är parqual vänlig","parquals personlighet"}}},fx={["8cab13a3"]={q="Vem är Parqual Fintallas?",a="Parqual Fintallas var en gång en berömd mänsklig historiker som visste allt som fanns att veta om kungariket Lordaeron. Pesten tog honom, och han återuppstod som odöd. Nu bor han bland de Förfallna i Undercitys Apothecarium. Trots sitt tillstånd har han kvar sin djupa passion för historia, böcker och stilla lärdom.",al={"vem är parqual","parqual fintallas","vem är fintallas"}},d8934933={q="På vems sida står Parqual Fintallas?",a="Parqual står på de Förfallnas och Hordens sida och bor i lugn och ro i Undercity. Till skillnad från många av sina förbittrade fränder hyser han föga agg mot resenärer och delar gärna med sig av sina historiekunskaper till Horde-vandrare som söker kunskap.",al={"vem tjänar parqual","parquals fraktion","är parqual med horden"}},["5af35229"]={q="Vad vill Parqual Fintallas?",a="Parqual vill bevara Lordaerons historia och fortsätta sina lärda studier som odöd. Han värderar kunskap långt högre än styrka. Han hjälper gärna dem som söker bortglömda uppteckningar och historisk visdom, men skickar dem först för att hämta sällsynta böcker som Beginnings of the Undead Threat från Scarlet Monastery.",al={"vad vill parqual","parqual fintallas mål","parquals motiv"}},["03c3b7bf"]={q="Varför är Parqual Fintallas här i Apothecarium?",a="Parqual bor i Undercitys Apothecarium, omgiven av forskare och lärda. Staden är full av mörkare alkemiska verk, men han använder dess lugna vrår för att studera och bevara historiska uppteckningar. Han hjälper dem som söker förlorad kunskap.",al={"varför är parqual här","varför är parqual i undercity","vad gör parqual i apothecarium"}}},fp="17,331,25.518.0,22.428.0,35.155.0,36.257.0,44.273.0,57.259.0"}
P.entries["npc:pelturas-whitemoon"] = {n="Pelturas Whitemoon",s="Pelturas Whitemoon är en Night Elf-far i Astranaar, vars unga dotter Relara har drabbats av en fruktansvärd, fördärvande sjukdom. I sin desperation att rädda henne samarbetar han nära med den lokala örtkännaren Orendil Broadleaf och resande Alliance-hjältar för att samla heliga läkemedel från vildmarken omkring dem. Hans försök att bota Relara för äventyrare till några av Ashenvales äldsta heliga lundar och ruiner.",h="Pelturas Whitemoon är en Night Elf-far i Astranaar, vars unga dotter Relara har drabbats av en fruktansvärd...",kw={"ashenvale","astranaar","elune's tear","fallen sky lake","månsten","orendil broadleaf","pelturas","relara","the ruins of stardust","whitemoon"},ang={["class:Priest"]="De renande ritualerna och de heliga ingredienserna som vigts åt Elune visar den läkande kraft och heliga vördnad som The Sisterhood of Elune för med sig till Night Elf-kulturen.",["faction:Alliance"]="När du hjälper Pelturas att rädda hans dotter visar du Alliance åtagande att försvara och hjälpa Kaldorei-bosättningarna i Kalimdor.",["profession:Herbalism"]="De naturliga brygder, örtomslag och växtbaserade tinkturer som behövs för Relara visar hur starkt Kaldorei-medicinen är knuten till örtmedicin.",["race:NightElf"]="Pelturas kamp speglar hur utsatta vanliga Kaldorei-familjer är när forntida gläntor faller offer för fördärv och regionala konflikter."},sec={{t="En fars prövning i Astranaar",b="I Astranaars fridfulla trädkronor lever Pelturas Whitemoon det stillsamma liv som är typiskt för skogslevande Kaldorei. Han ger sig ofta ut med sin unga dotter Relara för att samla skimrande månstenar vid Fallen Sky Lake. Men när Relara blir kritiskt sjuk av en mystisk åkomma rasar hans lugna värld samman i desperat panik. Astranaar är belägrat från många håll, men för Pelturas finns inget i den stora skogen som betyder mer än att rädda hans barn."},{t="Forntida botemedel och fördärvade lundar",b="Vanliga örtmediciner hjälper inte mot Relaras åkomma, så Pelturas vänder sig till örtkännaren Orendil Broadleaf. För att behandla sjukdomen krävs sällsynta och heliga ingredienser knutna till landet och Mångudinnan. De omfattar en Elune's Tear och skimrande stjärndamm från forntida Kaldorei-ruiner, som ska kyla hennes brännande feber. Varje steg håller nätt och jämnt döden stången och visar hur djupt fördärvet som sprider sig genom Ashenvales jord och vatten har börjat nå dess invånare."},{t="Fallen Sky Lake",b="För att återställa Relaras krafter helt söker Pelturas en månsten hos Shadethicket Oracle vid Fallen Sky Lake. Sjön var en gång en fridfull plats där far och dotter samlade stenar tillsammans, men har blivit farlig efter att fördärvade kärrbestar trätt fram med våldsam kraft. Pelturas krossar den återfunna månstenen och blandar den i ett stärkande te. Då försvinner till slut den kvardröjande svagheten, och Relara blir frisk."}},faq={{q="Vem är Pelturas Whitemoon?",a="Pelturas Whitemoon är en Night Elf som bor i Astranaar i centrala Ashenvale. Han är mest känd för att be resande Alliance-farare om hjälp att samla heliga ingredienser som kan bota hans svårt sjuka dotter Relara.",al={"pelturas","vem är pelturas whitemoon","pelturas astranaar"}},{q="Vad är det för fel på hans dotter Relara?",a="Relara lider av en plötslig, aggressiv sjukdom som orsakar svår feber och djup svaghet. Sjukdomen verkar vara knuten till det onaturliga fördärv som sprider sig genom Ashenvales vildmark. Vanlig medicin biter inte på den, och heliga ingredienser krävs för att rena henne.",al={"relara sjukdom","varför är relara sjuk","relaras sjukdom"}},{q="Vem hjälper Pelturas att behandla sjukdomen?",a="Pelturas ber Orendil Broadleaf om råd. Orendil är en kunnig lokal Night Elf som ordinerar traditionella Kaldorei-läkemedel, däribland renande stenar och örtomslag.",al={"pelturas örtkännare","vem hjälper relara","orendil broadleaf pelturas"}},{q="Vilka ingredienser behövs för att bota Relara?",a="För att rädda Relara krävs flera behandlingar: först en örtbrygd från Orendil, sedan en renande Elune's Tear och pulveriserat stjärndamm från forntida ruiner som häver hennes brännande feber. Till sist blandas en månsten från Fallen Sky Lake i te för att återställa hennes krafter.",al={"botemedel ingredienser pelturas","relara botemedel ingredienser","vad botar relara"}},{q="Varför är Fallen Sky Lake viktig för Pelturas?",a="Fallen Sky Lake var en plats där Pelturas och Relara brukade tillbringa tid tillsammans och samla månstenar. På senare tid har fientliga Shadethicket-kärrbestar tagit över sjön, så Pelturas måste be äventyrare hämta månstenen som behövs för att hans dotter ska tillfriskna.",al={"fallen sky lake pelturas","månsten fallen sky lake"}},{q="Är Pelturas medlem i Cenarion Circle eller Sentinels?",a="Nej. Pelturas är en civil invånare i Astranaar och representerar de vanliga Kaldorei-familjer som bor i Ashenvale och drabbas av farorna som tränger in i skogen.",al={"är pelturas en sentinel","pelturas fraktion roll"}}},fx={["6580d64d"]={q="På vems sida står Pelturas Whitemoon?",a="Pelturas är lojal mot nattalverna i Darnassus och står stadigt på Alliansens sida. Han bor i Astranaar och förlitar sig på sina kaldoreifränders beskydd. Han välkomnar alla Alliansens resenärer som kan hjälpa hans familj i deras svåra stund.",al={"pelturas whitemoons fraktion","är pelturas med alliansen","pelturas lojalitet"}},["806ac345"]={q="Vad vill Pelturas Whitemoon?",a="Framför allt vill Pelturas rädda sin älskade dotter Relara från den mystiska sjukdom som plågar henne. Han är desperat efter att samla kraftfulla läkande ingredienser, från heliga tårar till uråldrig stjärndamm, i hopp om att skapa ett botemedel som äntligen bryter hennes feber och återger henne hennes krafter.",al={"vad vill pelturas","pelturas whitemoons mål","vad försöker pelturas göra"}},["8d08bbb7"]={q="Varför är Pelturas Whitemoon i Astranaar?",a="Pelturas bor i Astranaar, hjärtat av nattalvernas bosättningar i Ashenvale. Förr strövade han med sin dotter i de närliggande skogarna och längs stränderna vid platser som Fallen Sky Lake. Nu är han hänvisad till tryggheten i byn för att ta hand om hennes försämrade tillstånd.",al={"varför är pelturas i astranaar","varför är pelturas här","var bor pelturas"}},["3f413488"]={q="Vem har Pelturas Whitemoon band till?",a="Pelturas liv kretsar kring hans unga dotter Relara, som han outtröttligt kämpar för att skydda. I sina försök att bota henne samarbetar han nära med Orendil Broadleaf, en lokal nattalv som är kunnig i läkande kurer och vägleder honom mot möjliga botemedel.",al={"pelturas whitemoons familj","vem är pelturas släkt med","pelturas dotter"}}},fp="18,202,30.350.0,34.403.1,15.374.1,26.175.0,40.237.0,38.174.0,40.225.0,47.214.0,61.113.0"}
P.entries["npc:pilot-bellowfiz"] = {n="Pilot Bellowfiz",s="Pilot Bellowfiz, kärleksfullt kallad ”Fizzer”, är en dvärgisk förare stationerad vid Steelgrill's Depot i Dun Morogh. Som medlem av Ironforge Siege Brigade ansvarar han för att underhålla och bemanna tunga dvärgiska krigsmaskiner, särskilt sin egen belägringsmaskin, Jetsteam.",h="Pilot Bellowfiz, kärleksfullt kallad ”Fizzer”, är en dvärgisk förare stationerad vid Steelgrill's Depot i Dun...",kw={"bellowfiz","dun morogh","fizzer","jetsteam","pilot bellowfiz","pilot stonegear","siege brigade","steelgrill's depot"},ang={["profession:Engineering"]="För dvärgiska och gnomiska mekaniker är Bellowfiz ett föredöme inom praktisk fältingenjörskonst: han håller högpresterande belägringsmaskiner igång i det iskalla bergsvädret.",["race:Dwarf"]="Bellowfiz personifierar stoltheten hos Ironforges mekaniserade brigader och visar upp ingenjörskonsten och den tunga eldkraften som skyddar Khaz Modan."},sec={{t="Mästare på Jetsteam",b="Pilot Bellowfiz är stationerad strax utanför Ironforges livliga salar vid Steelgrill's Depot och står för ryggraden i dvärgarnas militärmaskineri. Han styr den kraftfulla belägringsmaskinen Jetsteam och ägnar dagarna åt att finjustera komponenter, skaffa viktiga delar och hålla maskinen stridsklar. Tillsammans med sin kamrat Pilot Stonegear diskuterar Bellowfiz ständigt fordonskonstruktioner, pansarplåt och motoreffekt för att se till att bergarikets mekaniserade eldkraft förblir oöverträffad i hela Khaz Modan."}},faq={{q="Vem är Pilot Bellowfiz?",a="Pilot Bellowfiz är en dvärgisk pilot i Ironforge Siege Brigade. Han finns vid Steelgrill's Depot i Dun Morogh och underhåller och kör tunga belägringsmaskiner för att försvara Khaz Modan.",al={"pilot bellowfiz","fizzer","vem är fizzer"}},{q="Vilken maskin kör Bellowfiz?",a="Han kör en dvärgisk belägringsmaskin som heter Jetsteam. Inför ett långt uppdrag med Siege Brigade fyller han den med proviant för en månad, som vildsvinskött och björnpäls, och ser till att ha Rejold Barleybrew's Evershine till hands att kasta in i ugnen för en kraftökning.",al={"bellowfizs stridsvagn","jetsteam","vilken belägringsmaskin kör bellowfiz"}},{q="Var finns Pilot Bellowfiz?",a="Du hittar honom stationerad i snön vid Steelgrill's Depot, en ingenjörs- och uppställningsplats längs vägen öster om Kharanos i Dun Morogh.",al={"bellowfizs plats","var finns pilot bellowfiz","hitta bellowfiz"}},{q="Vad gör han tillsammans med Pilot Stonegear?",a="Bellowfiz och Pilot Stonegear är förarkollegor i Siege Brigade. När de inte sköter om sina fordon brukar de småprata och diskutera detaljerna i belägringsmaskiners konstruktion, pansar och mekanik.",al={"stonegear och bellowfiz","samtal med bellowfiz"}}},fx={["8ff6759c"]={q="På vems sida står Pilot Bellowfiz?",a="Bellowfiz tjänar kungariket Ironforge och den Stora Alliansen som aktiv förare i Ironforges Siege Brigade. Han är trogen King Magni Bronzebeard och de dvärgiska försvarsstyrkor som skyddar Dun Morogh.",al={"pilot bellowfiz fraktion","vem tjänar bellowfiz","är bellowfiz med alliansen"}},["292f21ec"]={q="Vad vill Pilot Bellowfiz?",a="Bellowfiz ser till att hans belägringsstridsvagn Jetsteam är stridsklar och har bränsle. Han förlitar sig på resenärer som kan samla förnödenheter inför ett långt uppdrag för Siege Brigade: vildsvinskött som mat, björnpäls som bädd och en tunna Rejold Barleybrews Evershine som håller honom varm och ger Jetsteams ugn en kraftstöt.",al={"vad behöver bellowfiz","pilot bellowfiz mål","varför behöver bellowfiz förnödenheter"}},["53346562"]={q="Varför är Pilot Bellowfiz här vid Steelgrill's Depot?",a="Steelgrill's Depot är uppställningsplats och testområde för Ironforges tunga pansarfordon. Bellowfiz är stationerad här för att justera, testa och proviantera sitt belägringsfordon tillsammans med andra mekaniker och förare innan de ger sig ut i snön.",al={"varför är bellowfiz vid steelgrills depot","varför är pilot bellowfiz i dun morogh","bellowfiz syfte i dun morogh"}}},fp="15,177,22.282.0,23.163.0,34.254.0,35.143.0,37.177.0"}
P.entries["npc:pilot-hammerfoot"] = {n="Pilot Hammerfoot",s="Pilot Hammerfoot är en dvärgisk förare av belägringsmaskiner i Ironforge Siege Brigade, stationerad nära bergspassen mellan Dun Morogh och Loch Modan. Han oroar sig för en pilotkamrat som försvunnit i kullarna och söker äventyrare som vill leta efter sin vän. Hans närvaro visar vilka faror dvärgar möter längs de höga alpina åsarna.",h="Pilot Hammerfoot är en dvärgisk förare av belägringsmaskiner i Ironforge Siege Brigade, stationerad nära...",kw={"dun morogh","ironforge","loch modan","mangeclaw","morter","north gate outpost","pilot hammerfoot","troggar"},ang={["faction:Alliance"]="Genom att hjälpa Hammerfoot säkrar du viktiga spaningsposter längs huvudvägen mellan Dun Morogh och Loch Modan.",["race:Dwarf"]="Hammerfoot förkroppsligar den starka kamratskapen bland Ironforges bergsbor och vägrar låta mordet på en fallen broder förbli obesvarat."},sec={{t="Ögon i bergen",b="Ironforges belägringsmaskiner är Siege Brigades stolthet, men att köra dem genom oländig bergsterräng är förenat med stor fara. Pilot Hammerfoot är stationerad vid North Gate Outpost med utsikt över gränsen mellan Dun Morogh och Loch Modan. Han vaktar piloternas maskiner och håller uppsikt över bergspassen. När en pilot försvinner blir det en prioritet att hitta honom snabbt, särskilt när vilda bestar stryker omkring i kullarna i närheten."},{t="Hämnd för en kamrat",b="Hammerfoot stod nära Pilot Mori Hildelve, en pilotkamrat som slog sönder sin maskin på en brant sluttning när de båda letade efter en sällsynt malm. Sedan fortsatte Hildelve ensam till fots. När Hammerfoot får veta att Hildelve slets ihjäl av Mangeclaw, en enorm isklo-björn, förvandlas hans uppdrag från rutinmässig gränsbevakning till personlig hämnd. Han kräver vedergällning mot besten som dödade hans vän."}},faq={{q="Vem är Pilot Hammerfoot?",a="Pilot Hammerfoot är en dvärgisk förare av belägringsmaskiner i Ironforge. Han är stationerad vid North Gate Outpost längs passet mellan Dun Morogh och Loch Modan. Där håller han uppsikt över regionens gränser och sina pilotkamrater.",al={"hammerfoot-lore","vem är hammerfoot","information om pilot hammerfoot"}},{q="Var hittar man Pilot Hammerfoot?",a="Han finns vid North Gate Outpost, längs bergsvägen som bevakar tunnelpasset mellan Dun Morogh och Loch Modan.",al={"hammerfoots plats","var finns pilot hammerfoot","var finns hammerfoot"}},{q="Vad hände med Hammerfoots partner, Pilot Hildelve?",a="Pilot Mori Hildelve hade sönder sin belägringsmaskin på en brant sluttning när han letade efter sällsynt malm och fortsatte till fots. Hammerfoot har inte hört av honom och ber resande att undersöka saken.",al={"pilot morters öde","vad hände med morter","morters död"}},{q="Varför oroar sig Hammerfoot för sin partner?",a="Hammerfoot och Mori Hildelve är nära vänner och piloter i Siege Brigade. Hildelve har försvunnit i farlig bergsterräng, och Hammerfoot behöver någon som tar reda på vad som hänt.",al={"varför vill han hämnas","varför hämnas morter","mangeclaws agg"}}},fx={["9955f46b"]={q="På vems sida står Pilot Hammerfoot?",a="Pilot Hammerfoot är en lojal dvärg från Ironforge och tjänar Alliansen. Han är stationerad vid utposten som bevakar passet mellan Dun Morogh och Loch Modan. Där arbetar han för att förse bergsmännen med förnödenheter och hålla de lokala bergspassen fria från hot som tränger sig på.",al={"hammerfoots fraktion","vem tjänar pilot hammerfoot","är hammerfoot med alliansen"}},["4a134edc"]={q="Varför är Pilot Hammerfoot stationerad här?",a="Hammerfoot bevakar belägringsfordonen vid North Gate Outpost nära passet mellan Dun Morogh och Loch Modan. Han och Mori Hildelve kom till kullarna för att leta efter sällsynt malm, men Hildelve fortsatte till fots när hans fordon gick sönder och har inte återvänt.",al={"varför är hammerfoot här","hammerfoots utpost","varför är pilot hammerfoot vid utposten"}}},fp="16,182,21.308.0,18.335.1,24.218.0,36.131.0,54.188.0,44.188.0"}
P.entries["npc:pilot-longbeard"] = {n="Pilot Longbeard",s="Pilot Longbeard är en dvärgisk belägringsmaskinspilot i Ironforge Siege Brigade, stationerad i Hall of Arms i Ironforges Military Ward. Trots att han är placerad i bergsstaden håller han nära kontakt med gnomiska uppfinnare och andra racingentusiaster långt borta i The Shimmering Flats.",h="Pilot Longbeard är en dvärgisk belägringsmaskinspilot i Ironforge Siege Brigade, stationerad i Hall of Arms i...",kw={"brassbolts","hall of arms","ironforge","military ward","pilot longbeard","shimmering deep","thousand needles"},ang={["profession:Engineering"]="Som belägringsmaskinspilot med kontakter bland gnomiska uppfinnare uppskattar Longbeard den mekaniska uppfinningsrikedom som krävs för att hålla maskiner igång och tävlingsklara.",["race:Dwarf"]="Pilot Longbeard förkroppsligar dvärgarnas äventyrslystna anda och förenar traditionell militärtjänst i Ironforge med spänningen kring belägringsmaskiner och gnomisk mekanik."},sec={{t="En pilot i belägringsbrigaden",b="Bland Ironforges Military Wards stridsutställningar och vapensmeder står Pilot Longbeard, som representerar Khaz Modans stolta belägringsmaskinskår. Hans tjänstgöring håller honom i fästningsstaden, men Longbeard håller öronen öppna efter nyheter och innovationer från mekaniker på andra håll på kontinenten, däribland bröderna Brassbolts, som mekar på Kalimdors saltöken."},{t="Förbindelser mellan kontinenter",b="Longbeard fungerar som kontakt för äventyrslystna resenärer på väg söderut till Kalimdor. Han visar ofta lovande rekryter och kurirer vägen till The Shimmering Flats i Thousand Needles, där gnomiska uppfinnare tänjer på de mekaniska gränserna tillsammans med sina goblinrivaler."}},faq={{q="Var hittar jag Pilot Longbeard?",a="Han finns inne i Hall of Arms i Ironforges Military Ward, nära tränarna och militärutställningarna.",al={"pilot longbeard plats","var finns longbeard i ironforge","hitta pilot longbeard"}},{q="Vilken roll har Pilot Longbeard?",a="Pilot Longbeard är en uppdragsgivare som leder Alliansens äventyrare mot äventyr i främmande länder och särskilt sammanför resenärer med sina vänner, bröderna Brassbolts, i Thousand Needles.",al={"vad gör longbeard","pilot longbeard uppdrag","varför prata med longbeard"}},{q="Vilka är bröderna Brassbolts för Longbeard?",a="De är gnomiska uppfinnare och bekanta till Longbeard, verksamma i The Shimmering Flats och förenade av sitt gemensamma intresse för ingenjörskonst och experimentella maskiner.",al={"kopplingen till brassbolts","varför känner longbeard brassbolts","longbeard shimmering deep"}},{q="Är Pilot Longbeard släkt med Furen Longbeard?",a="De delar det framstående klannamnet Longbeard i Ironforge, vilket antyder släktskap inom klanen, även om Pilot Longbeard ägnar sig åt belägringsmaskiner och tekniska kontakter snarare än smide.",al={"furen longbeard bror","longbeard dvärgsläkt","är han släkt med furen"}}},fx={e17c59b9={q="På vems sida står Pilot Longbeard?",a="Pilot Longbeard står stadigt med Ironforges dvärgar och Alliansen. Han är pilot i Ironforges Siege Brigade och stationerad i Hall of Arms i Ironforges Military Ward. Han är stolt över brigadens belägringsfordon och hjälper vänner och andra piloter i Alliansen.",al={"pilot longbeards fraktion","är pilot longbeard med alliansen","longbeards lojalitet"}},["97d29847"]={q="Vad vill Pilot Longbeard?",a="Pilot Longbeard vill hjälpa sina vänner och andra piloter, även om hans plikter håller honom i Ironforge. Han skickar resenärer med hjälmar till belägringsfordon åt sina vänner, bröderna Brassbolt, vars raketbilsförare fortsätter att krascha i Shimmering Flats. Han hjälper också Pilot Stonegear att spåra upp en sällsynt malm.",al={"pilot longbeards mål","vad behöver longbeard","pilot longbeards uppdrag"}},["5f9eba76"]={q="Varför är Pilot Longbeard här?",a="Som pilot i Ironforges Siege Brigade är Longbeard stationerad i Hall of Arms i Ironforges Military Ward. Hans plikter håller honom i staden, så han förlitar sig på resenärer som kan hjälpa vänner långt borta, som bröderna Brassbolt och deras gnomiska racinglag.",al={"varför är pilot longbeard i ironforge","varför är longbeard i military ward","varför är longbeard här"}}},fp="15,300,28.385.0,29.278.0,33.122.0,31.191.0,45.159.0,46.181.0"}
P.entries["npc:pilot-stonegear"] = {n="Pilot Stonegear",s="Pilot Stonegear, med smeknamnet ”Stone”, är en dvärgmekaniker och förare i Ironforges belägringsbrigad, stationerad vid Steelgrill's Depot. Han kör den fruktade belägringsmaskinen Trollplow och arbetar outtröttligt för att förbättra dess prestanda och pansar. Äventyrare som färdas genom Dun Morogh hjälper honom ofta att skaffa sällsynta material så att hans krigsmaskin alltid är redo för strid.",h="Pilot Stonegear, med smeknamnet ”Stone”, är en dvärgmekaniker och förare i Ironforges belägringsbrigad...",kw={"dun morogh","ironforges belägringsbrigad","pilot bellowfiz","pilot hammerfoot","pilot stonegear","belägringsmaskin","steelgrill's depot","stonegear","trollplow"},ang={["profession:Engineering"]="Ingenjörer kan uppskatta Stonegears hängivenhet åt att modifiera Trollplow ute i fält och balansera dödlig stridseffekt med förarkomfort.",["profession:Mining"]="Gruvarbetare bidrar med de livsviktiga råmalmer och flyktiga fyndigheter under jord som Stonegear behöver för att smida förstärkta pansarplåtar och ammunition.",["race:Dwarf"]="Stonegear är ett exempel på dvärgarnas kärlek till tungt stål, dånande motorer och att krossa bergens fiender under massiva järnlarvband.",["race:Gnome"]="Gnomer som arbetar tillsammans med belägringsbrigaden känner samhörighet med Stonegear, som alltid gärna experimenterar med nya konstruktioner och optimerar produktionen."},sec={{t="Trollplows mästare",b="Bland de mullrande ångpannorna och klapprande larvbanden vid Steelgrill's Depot tjänar Pilot Stonegear Ironforge som stolt förare i belägringsbrigaden. Hans stolthet och glädje är Trollplow, en tung belägringsstridsvagn byggd för att slå sig igenom fiendens linjer. Stonegear tar sin maskin på allvar och vet att förarens liv i stridens hetta helt beror på kugghjulens, plåtarnas och ångtryckets tålighet. Han försöker ständigt finjustera både Trollplows stridseffektivitet och den dagliga bekvämligheten i dess trånga förarhytt."},{t="Mekande och metallurgi",b="Precis som många andra dvärgiska och gnomiska smörjapa vid depån nöjer sig Stonegear sällan med fabrikens specifikationer. Han tillbringar ofta lediga timmar med att diskutera konstruktionsritningar med kamrater som Pilot Bellowfiz. Oavsett om han följer rykten om exotiska malmer eller letar efter flyktiga mineraler för förbättrade pansarplåtar och ammunition, förlitar sig Stonegear på ivriga rekryter som ger sig ut på provianteringsturer i Dun Moroghs snöiga vildmark och farliga grottor."}},faq={{q="Vem är Pilot Stonegear?",a="Pilot Stonegear, ofta kallad ”Stone”, är en dvärg från Ironforge och medlem i Ironforges belägringsbrigad. Han är stationerad vid Steelgrill's Depot i Dun Morogh, där han underhåller och kör sin belägringsmaskin Trollplow.",al={"pilot stonegear historia","vem är stonegear","pilot stone"}},{q="Var finns Pilot Stonegear?",a="Stonegear finns strax utanför Kharanos, vid Steelgrill's Depot i Dun Morogh, omgiven av belägringsstridsvagnar, reservdelar och andra piloter.",al={"pilot stonegear plats","var finns stonegear","hitta stonegear"}},{q="Vad är Trollplow?",a="Trollplow är Pilot Stonegears personliga belägringsmaskin. Han arbetar ständigt med att förbättra dess mekaniska driftsäkerhet, pansarplåtar och invändiga komfort, så att den klarar frontstridens brutala påfrestningar.",al={"vad är trollplow","trollplow stridsvagn","stonegears stridsvagn"}},{q="Varför behöver Stonegear äventyrare?",a="Stonegear tar hjälp av resenärer för att spana efter hot i närheten och samla sällsynta mineraler, som Incendicite Ore, för att uppgradera och underhålla belägringsbrigadens tunga krigsmaskiner.",al={"pilot stonegear uppdrag","varför har stonegear uppdrag","stonegears sökande"}},{q="Vilka arbetar Pilot Stonegear med?",a="Han tjänstgör i Ironforges belägringsbrigad tillsammans med andra förare som Pilot Bellowfiz och Pilot Hammerfoot. Vid depån diskuterar han ofta mekaniska uppgraderingar och maskinkonstruktioner med Bellowfiz.",al={"stonegears vänner","belägringsbrigadens piloter","bellowfiz och stonegear"}},{q="Vad är Ironforges belägringsbrigad?",a="Ironforges belägringsbrigad är den mekaniserade pansardivisionen i dvärgarnas militär. De kör ångstridsvagnar och belägringsmaskiner och hanterar tungt artilleri för att ge pansarstöd åt försvaret av Dun Morogh och visa Ironforges militära styrka i hela Khaz Modan.",al={"ironforges belägringsbrigad","belägringsbrigadens historia","dvärgarnas stridsvagnsbrigad"}}},fx={["6ae24a1f"]={q="På vems sida står Pilot Stonegear?",a="Pilot Stonegear tjänar Ironforge och Alliansen som hängiven förare i Ironforges Siege Brigade. Han är stationerad vid Steelgrill's Depot och är helt lojal mot dvärgarnas kungarike. Han försvarar Dun Moroghs snöiga bergsryggar och ser till att stadens tunga krigsmaskiner är trimmade för alla hot mot hans folk.",al={"pilot stonegears fraktion","stonegears lojalitet","vem tjänar pilot stonegear"}},["5e3743ba"]={q="Varför är Pilot Stonegear här vid Steelgrill's Depot?",a="Stonegear är stationerad vid Steelgrill's Depot för att testa, underhålla och förbättra sitt belägringsfordon Trollplow. Tillsammans med andra förare i brigaden använder han depåns verkstäder för att övervaka reparationer, prata motorer och skaffa de sällsynta malmer och mineraler som behövs för att göra maskinen tåligare i fält.",al={"varför är stonegear i dun morogh","varför är pilot stonegear här","stonegear vid steelgrills depot"}}},fp="15,276,23.344.0,24.328.0,23.174.0,33.142.0,22.141.0,41.188.0,35.205.0,36.208.0"}
P.entries["npc:pixel"] = {n="Pixel",s="Pixel är en driftig goblinkurir med utgångspunkt i Splintertree Post i Ashenvale. Hon försörjer sig på att leverera tungt gods genom farliga områden och hanterar leveranser som Warsong Saw Blades åt de lokala styrkorna i Horde, men hon lämnar aldrig ifrån sig någon last utan ordentlig ersättning.",h="Pixel är en driftig goblinkurir med utgångspunkt i Splintertree Post i Ashenvale.",kw={"ashenvale","kurir","goblin","pixel","satyr horns","splintertree post","warsong saw blades"},ang={["faction:Horde"]="För Hordes kämpar som försöker få fotfäste i Ashenvale tillhandahåller Pixel den industriella utrustning som Warsong Clan desperat behöver för att hålla sina avverkningsmaskiner igång."},sec={{t="Affärer i djupskogen",b="Medan Splintertree Post fungerar som ett befäst fäste för Horde bland Ashenvales fientliga trädkronor, håller Pixel blicken stadigt på vinsten. Som självständig kurir är hon villig att frakta gods in i aktiva krigszoner och står för viktig logistik åt Warsong Clans skogsavverkning. Men i sann goblintradition är det avtal och mynt som styr hennes samarbete. Hon håller fast vid leveranserna tills kunden betalar. För sågbladen vill hon ha en Deadly Blunderbuss som skydd på vägen. Hon är alltid uppmärksam på nya möjligheter och betalar också förbipasserande äventyrare för Satyr Horns, som är mycket efterfrågade i Ratchet."}},faq={{q="Vem är Pixel?",a="Pixel är en frilansande goblinkurir stationerad vid Splintertree Post i östra Ashenvale. Hon försörjer sig på att frakta gods genom farliga områden och hanterar just nu en leverans av sågblad som är avgörande för den lokala skogsavverkningen åt Warsong Clan.",al={"vem är den här goblinen","pixels bakgrund","goblin vid splintertree"}},{q="Varför lämnar Pixel inte genast ifrån sig sågbladen?",a="Som vilken listig goblin som helst följer Pixel strikt affärsprinciper. Trots Hordes brådska i Ashenvale vägrar hon lämna ifrån sig sågbladen utan ordentlig ersättning eller bytesvaror som täcker hennes avgift.",al={"varför vill pixel ha betalt","leverans av warsong saw blades","uppdrag med sågblad"}},{q="Varför vill hon ha satyrhorn?",a="Satyr Horns är mycket efterfrågade i Ratchet, dit Pixel ska härnäst. Hon kan inte mäta sig med satyrerna i Night Run, Satyrnaar och Xavian på egen hand, så hon betalar äventyrare för att samla in hornen som hon kan sälja.",al={"varför satyrhorn","pixel och satyrer","satyruppdrag vid splintertree"}},{q="Är Pixel officiellt medlem i Horde?",a="Pixel arbetar nära Horde vid Splintertree Post tack vare lukrativa avtal med Warsong Clans timmerverksamhet, men hennes främsta lojalitet ligger hos handel, vinst och att fullfölja sina leveransavtal.",al={"är pixel med i horde","pixels fraktion","är pixel neutral"}}},fx={c8b7be1d={q="Varför är Pixel i Ashenvale?",a="Pixel är en företagsam goblinkurir som försörjer sig på att frakta gods genom Kalimdor och längre bort. Hon reste in i Ashenvales omstridda skogar för att leverera en viktig försändelse med Warsong Saw Blades direkt till Hordens utpost Splintertree Post.",al={"varför är pixel här","varför pixel vid splintertree post","pixel i ashenvale"}},["37ebabcf"]={q="Vem arbetar Pixel åt?",a="Pixel arbetar självständigt som frilansande leveransspecialist och svär inte trohet till någon enskild fraktion. Hennes nuvarande affärer knyter henne till Warsong Outriders och styrkorna vid Splintertree Post, som hon förser med industrimaskiner för deras skogsarbete.",al={"vem har pixel band till","pixels uppdragsgivare","pixels kontakter"}}},fp="5,170,26.457.0,13.185.0,53.177.0,30.222.0,42.190.0"}
P.entries["npc:piznik"] = {n="Piznik",s="Piznik är en missnöjd goblinmätare som gömmer sig djupt inne i Windshear Mine i Stonetalon Mountains. Han var en gång en högt uppsatt förman inom Venture Companys lokala verksamhet, men den hänsynslöse Gerenzo Wrenchwhistle satte honom åt sidan. Nu samlar Piznik i hemlighet information för att sabotera sin tidigare arbetsplats, driven av agg.",h="Piznik är en missnöjd goblinmätare som gömmer sig djupt inne i Windshear Mine i Stonetalon Mountains.",kw={"gerenzo wrenchwhistle","piznik","stonetalon","venture co","windshear crag","windshear mine","ziz fizziks"},ang={["profession:Mining"]="Gruvarbetare som tar sig genom Windshear Mine stöter på Piznik, ett levande exempel på hur snabbt en organisations rangordning kan rasa under tyngden av företagsgirighet."},sec={{t="Fallet från nåden",b="Innan Gerenzo Wrenchwhistle tog den högsta makten över Windshear Crag hade Piznik den avundsvärda titeln som andreman för hela verksamheten. Men omstruktureringar inom Venture Company lämnar ingen pardon. När Gerenzo tog full kontroll blev Piznik åsidosatt och förpassad till de dunkla djupen av Windshear Mine. I stället för att stillatigande acceptera sin degradering väntar Piznik under jord, håller ett vakande öga på vad som sker i gruvan och smider i tysthet planer på hämnd mot chefen som degraderade honom."},{t="Företagsspioneri",b="Pizniks stillsamma uppror fick praktisk form genom en allians med Ziz Fizziks, en agent som befinner sig utanför och som Gerenzo också hade stött bort. Som Zizs man på insidan samlar Piznik in allt han kan om Gerenzos planer. Han smugglar ut ett prov av den mystiska guldgröna malm som Gerenzo har beordrat att bryta i stora mängder och skickar det till Ziz. På så vis försöker Piznik i skuggorna störa Venture Companys skogsavverkning och gruvdrift och se till att Gerenzos ambitiösa ledarskap ständigt drabbas av plågsamma bakslag."}},faq={{q="Var hittar jag Piznik?",a="Piznik håller till inne i Windshear Mine, ett grottsystem uthugget i sluttningarna vid Windshear Crag i Stonetalon Mountains. Du hittar honom djupt inne i gångarna, omgiven av arbetare från Venture Company.",al={"pizniks plats","var finns piznik","hitta piznik i stonetalon"}},{q="Varför hyser Piznik agg mot Gerenzo Wrenchwhistle?",a="Piznik var tidigare den näst högsta auktoriteten vid Windshear Crag. När Gerenzo Wrenchwhistle tog full kontroll över avverknings- och gruvprojektet degraderade han Piznik, vilket gjorde den tidigare förmannen bitter och angelägen om att se Gerenzo gå under.",al={"varför hatar piznik gerenzo","pizniks och gerenzos fejd"}},{q="Vilken roll spelar Piznik i Ziz Fizziks planer?",a="Gerenzo avskedade Ziz Fizziks, medan Piznik bara blev degraderad. Piznik använder sin kvarvarande tillgång till Windshear Mines djup för att fungera som informatör. Han samlar information om Gerenzos planer och ser till att ett prov av den mystiska malm som Gerenzo har beordrat att bryta når Ziz.",al={"piznik och ziz","vem arbetar piznik med"}},{q="Är Piznik fortfarande lojal mot Venture Company?",a="Bara på papperet. Han bär fortfarande Venture Companys emblem för att kunna stanna kvar i gruvan, men Piznik är i själva verket bara lojal mot sina egna intressen och sin önskan att sabotera för Gerenzo.",al={"tillhör piznik venture co","pizniks fraktion"}}},fx={["73f53239"]={q="Vem är Piznik?",a="Piznik är en goblinagent som gömmer sig djupt inne i Windshear Mine i Stonetalon Mountains. Han var en gång andreman för hela Venture Companys verksamhet i Windshear Crag och hade stort anseende och inflytande, tills Gerenzo Wrenchwhistle anlände, tog över och systematiskt fråntog honom hans ställning.",al={"vem är piznik","pizniks bakgrund"}},["04ccaf91"]={q="Vad vill Piznik?",a="Piznik vill hämnas på Gerenzo Wrenchwhistle för att han förstörde Pizniks ställning i Venture Company, och tjäna en hacka. På uppdrag av sin tidigare chef Ziz Fizziks, som Gerenzo sparkade, stannar han i gruvan för att ta reda på Gerenzos planer. Han smugglar också ut ett prov av den guldgröna malm som Gerenzo har beordrat att bryta i stora mängder, så att Zizs nya arbetsgivare kan undersöka den.",al={"vad vill piznik","pizniks mål","pizniks motiv"}},e9de2964={q="Varför är Piznik i Windshear Mine?",a="När Gerenzo Wrenchwhistle tog kontroll över Venture Companys lokala verksamhet skickade han ner Piznik för att arbeta i Windshear Mine. Piznik stannar i tunnlarna på Ziz Fizziks begäran och agerar informatör inifrån. Han samlar i tysthet in upplysningar utan att väcka resten av verksamhetens uppmärksamhet.",al={"varför är piznik här","varför är piznik i windshear mine","varför piznik är där"}}},fp="6,175,17.388.0,19.420.1,24.144.0,54.205.0,44.179.0,45.134.0"}
P.entries["npc:pozzik"] = {n="Pozzik",s="Pozzik är en ansedd goblintekniker och racerförare som håller till på Mirage Raceway i The Shimmering Flats i Thousand Needles. En gång en av de mest respekterade ingenjörerna i Undermine ägnar han nu sitt tekniska geni åt att bygga experimentella raketbilar och avgöra den yttersta frågan om ingenjörskonstens överlägsenhet gentemot sin motsvarighet bland gnomer.",h="Pozzik är en ansedd goblintekniker och racerförare som håller till på Mirage Raceway i The Shimmering Flats i...",kw={"fizzle brassbolts","mirage raceway","pozzik","raketbil","the shimmering flats","thousand needles","tekniker","undermine"},ang={["profession:Engineering"]="För ingenjörer av båda lägren, gobliner såväl som gnomer, står Pozzik för den absoluta höjdpunkten inom högriskmekanik i hög hastighet.",["race:Gnome"]="Gnomer som besöker banan finner i Pozzik sin favoritrival: en högljudd gobliningenjör som är övertygad om att rå dragkraft slår varsam precision."},sec={{t="En mästare från Undermine",b="Innan Pozzik drog sig tillbaka till Thousand Needles hårda saltslätter hade han byggt upp ett legendariskt rykte bland gobliner. Som en av de mest respekterade teknikerna från Undermine sträcker sig hans tekniska kunnande över komplex förbränningsmotorik, framdrivning och riskfylld chassikonstruktion. I stället för att dra sig undan i bekväm obemärkthet tog Pozzik sitt mekaniska mästerskap ut i öknen för att pressa höghastighetsmaskiner långt bortom bristningsgränsen."},{t="Duellen på saltslätterna",b="På Mirage Raceway slog Pozzik sig ihop med sin ständige gnomrival Fizzle Brassbolts. Trots den historiska rivaliteten mellan goblinernas sprängämnen och gnomernas varsamma kalibrering arbetade de tillsammans för att bygga den vidsträckta tävlingsbanan över den uttorkade sjöbottnen. De ställer upp med var sitt racingstall och testar prototyper av raketbilar för att en gång för alla bevisa vilken arts konstruktionsfilosofi som dominerar banan. Pozzik håller förstås alltid utkik efter företagsamma äventyrare som kan skaffa delar och minska vikten på hans konstruktioner."}},faq={{q="Vem är Pozzik?",a="Pozzik är en veteran bland goblinteknikerna, tidigare från Undermine, som nu leder den ena sidan av raketracetävlingen på Mirage Raceway i Thousand Needles.",al={"pozzik","vem är pozzik","pozziks bakgrund"}},{q="Varför är Pozzik i Thousand Needles?",a="Efter att ha dragit sig tillbaka från sitt formella arbete i Undermine kom Pozzik till The Shimmering Flats för att bygga och tävla med experimentella raketbilar över de vidsträckta, obrutna saltslätterna.",al={"varför är pozzik här","pozzik the shimmering flats"}},{q="Vilken relation har han till Fizzle Brassbolts?",a="Fizzle Brassbolts är Pozziks långvariga gnomrival och medgrundare av tävlingsbanan. Även om de arbetar sida vid sida med att sköta Mirage Raceway tävlar de ständigt om att bevisa att goblinernas ingenjörskonst överträffar gnomernas hantverk.",al={"pozzik och fizzle","pozziks gnomrival"}},{q="Arbetar Pozzik för Horden eller Alliansen?",a="Pozzik är helt neutral och arbetar som en självständig goblinföretagare vid tävlingsbanan. Han gör gärna affärer och erbjuder uppdrag till resenärer från både Alliansen och Horden.",al={"är pozzik neutral","pozziks fraktion"}},{q="Vilka projekt arbetar Pozzik med just nu?",a="Pozzik är besatt av att pressa ut ännu högre hastigheter ur sina raketbilar. Han utvecklar chassin för tävlingsbilar med flera motorer, samlar sällsynta lättviktsmalmer och skickar ut upptäcktsresande för att leta efter bärgade delar och komponenter.",al={"pozziks uppdrag","vad bygger pozzik"}}},fx={["186dfe38"]={q="Varför är Pozzik berömd?",a="Innan Pozzik slog sig ner i The Shimmering Flats hade han gjort sig ett namn som en av de mest respekterade uppfinnarna i Undermine. Hans legendariska ingenjörskonst kom till uttryck i hans raketbilsdesigner, där han revolutionerade sporten genom att utveckla kraftfulla racerbilar med två motorer.",al={"pozziks berömmelse","är pozzik berömd","varför är pozzik välkänd"}}},fp="6,347,21.446.0,26.542.0,14.157.0,38.167.0,48.234.0,47.172.0,53.199.0"}
P.entries["npc:priestess-a-moora"] = {n="Priestess A'moora",s="Priestess A'moora är en from Night Elf som tjänar månens gudinna i Temple of the Moon i Darnassus. Under High Priestess Tyrande Whisperwinds ledning utför hon ritualer för andlig rening och gemenskap med Elune. Resenärer som utforskar Teldrassil hänvisas ofta till henne när det gäller heliga offergåvor och boughs mystiska djurliv.",h="Priestess A'moora är en from Night Elf som tjänar månens gudinna i Temple of the Moon i Darnassus.",kw={"a'moora","darnassus","elune","prästinna","sathrah","tears of the moon","teldrassil","temple of the moon"},ang={["class:Priest"]="Präster som vandrar genom Temple of the Moons salar kan se A'moora som ett exempel på hängiven gudsdyrkan, en bro mellan templets ritualer och naturen utanför stadsportarna.",["faction:Alliance"]="Priestess A'moora hjälper resenärer från Alliansen som utforskar Darnassus heliga hjärta och introducerar dem till The Sisterhood of Elunes heliga seder.",["race:NightElf"]="För nattalver står Priestess A'moora för Elunes tidlösa traditioner och förankrar Teldrassils unga grenar i folkets uråldriga andliga arv."},sec={{t="Elunes tjänarinna",b="I Temple of the Moons fridfulla marmorsalar ägnar Priestess A'moora sina dagar åt begrundan och tjänst. Som vigd prästinna åt Elune hjälper hon till att vårda Darnassus andliga behov och bevara de känsliga ritualer som förts vidare genom årtusenden. Medan mycket av The Sisterhood of Elune ansvarar för militärt försvar eller diplomati, inriktar sig A'moora på traditionell gudsdyrkan och heliga angelägenheter som rör Teldrassils naturandar."},{t="Månens tårar",b="A'moora är knuten till Lady Sathrahs sorgliga öde, en jättespindel som en gång var älskad av Elune och vars silvriga dagg förvarades i templet för sina läkande krafter. När Sathrah blev vansinnig skickade A'moora unga äventyrare till Teldrassils norra gräns nära Wellspring Lake för att göra slut på hennes lidande och hämta tillbaka hennes Silvery Spinnerets. När de offras vid templets fontän blir spinnerets ett offer till Elune, så att Sathrah kan återfödas i frid."}},faq={{q="Var hittar jag Priestess A'moora?",a="Priestess A'moora finns inne i Temple of the Moon i Darnassus, huvudstaden som vilar i Teldrassils trädkrona. Hon står bland prästinnorna som tjänar vid Elunes altare.",al={"a'mooras plats","var finns priestess amoora","amoora darnassus"}},{q="Vilken roll har Priestess A'moora i Darnassus?",a="Hon är medlem av The Sisterhood of Elune och ansvarar för särskilda religiösa ceremonier och heliga offergåvor. Hon ger uppdrag och vägleder resenärer som vill utföra forntida renings- och offerriter på Teldrassil.",al={"vad gör amoora","priestess amoora syfte"}},{q="Vilka uppdrag erbjuder Priestess A'moora?",a="Hon ger uppdragskedjan Tears of the Moon och skickar äventyrare för att döda den vansinniga spindeln Lady Sathrah nära Wellspring Lake och sedan offra hennes Silvery Spinnerets vid templets fontän.",al={"amoora uppdrag","priestess amoora uppdragskedja"}},{q="Hur är Priestess A'moora knuten till Temple of the Moon?",a="Hon tjänstgör i Temple of the Moon, nattalvernas kulturs andliga hjärta, som styrs av High Priestess Tyrande Whisperwind. A'moora hjälper till med den andliga undervisning och de rituella uppgifter som utförs under templets tak.",al={"är amoora en tempelprästinna","the sisterhood of elune amoora"}},{q="Vem är Sathrah, och varför talar A'moora om henne?",a="Lady Sathrah är en jättespindel som en gång var älskad av Elune och håller till längs Teldrassils norra gräns nära Wellspring Lake. Hon har blivit vansinnig, så A'moora ber äventyrarna att göra slut på hennes lidande och offra hennes spinnerets till Elune, så att hon kan återfödas i frid.",al={"sathrahs offer","vem är sathrah"}},{q="Tillhör A'moora Alliansen?",a="Ja. Som nattalvsprästinna stationerad i huvudstaden Darnassus är hon helt lojal med Alliansen och erbjuder varken hjälp eller uppdrag till Hordens medlemmar.",al={"tillhör amoora alliansen","kan horden tala med amoora"}}},fx={["05fd0978"]={q="Vem är Priestess A'moora?",a="Priestess A'moora är en from Night Elf som tjänar Elune i det storslagna Temple of the Moon i Darnassus. Som en av templets hängivna prästinnor tillgodoser hon sitt folks andliga behov med böner, råd och vägledning under Mångudinnans nåd.",al={"vem är priestess amoora","vem är a'moora","priestess amoora i berättelsen"}},["4daa0bfc"]={q="Vad vill Priestess A'moora?",a="Priestess A'moora vill bevara Temple of the Moons heliga ritualer och okränkbarhet. Hon vänder sig till värdiga äventyrare för hjälp med trosfrågor och ritualer och ber dig bidra med heliga offergåvor, som Tears of the Moon, för att hedra Elune och upprätthålla templets heliga riter.",al={"priestess amoora mål","vad vill amoora","amoora motiv"}},e929c23e={q="Varför är Priestess A'moora i Darnassus?",a="A'moora bor i Temple of the Moon eftersom det är centrum för Elunes dyrkan bland Night Elf-folket. Hon sköter helgedomens dagliga andakter, bistår översteprästinnan Tyrande Whisperwinds prästerskap och ser till att huvudstadens andliga harmoni förblir orubbad.",al={"varför är amoora i darnassus","priestess amoora i temple of the moon","varför är amoora här"}}},fp="17,165,18.309.0,17.388.0,35.163.0,46.185.0,41.194.0,59.197.0,50.261.0,36.133.0"}
P.entries["npc:priestess-alathea"] = {n="Priestess Alathea",s="Priestess Alathea är en Night Elf-prästtränare som bor i Temple of the Moon i Darnassus. Hon är hängiven mångudinnan och vägleder noviser i heliga konster och rasens välsignelser från Elune. Hennes undervisning hjälper Night Elf-präster att rikta sina sinnen mot skyddsböner och himmelsk magi.",h="Priestess Alathea är en Night Elf-prästtränare som bor i Temple of the Moon i Darnassus.",kw={"alathea","darnassus","elune","elune's grace","prästtränare","priestess alathea","stars of elune","temple of the moon"},ang={["class:Priest"]="Priestess Alathea är en viktig kontakt för Alliance-präster som besöker Darnassus. Hon hjälper dem att avancera i graderna och vägleder kaldorei-akolyter till deras unika himmelska krafter.",["faction:Alliance"]="Alathea låter alla resande medlemmar av Alliance som studerar prästkonsterna ta del av undervisningen i Temple of the Moon.",["race:NightElf"]="Som prästinna i hjärtat av Darnassus förkroppsligar Alathea The Sisterhood of Elunes levande andliga traditioner, som har skyddat kaldorei i årtusenden."},sec={{t="Hängivenhet i Temple of the Moon",b="I Darnassus ståtligaste helgedom tjänar Priestess Alathea The Sisterhood of Elune som lärare och andlig vägledare. När Night Elf-noviser lämnar Shadowglens stilla grenar hänvisas de till Temple of the Moon för att fördjupa sitt förbund med gudinnan. Alathea är en av prästinnorna som förmedlar helig kunskap till dem som viger sina liv åt läkedom, beskydd och gudomligt ljus."},{t="Den vita damens välsignelser",b="Till skillnad från präster inom Holy Light, som hämtar sin kraft ur mänskliga och dvärgiska traditioner, hämtar kaldorei-präster sin kraft direkt från Elunes nåd. Alathea har en viktig roll när hon prövar och ger välsignelser för Night Elf, som Stars of Elune och Elune's Grace. Med hennes vägledning lär sig akolyter att väva stjärnljus till sköldar som ger snabbhet och skydd mot de växande faror som hotar Kalimdor."}},faq={{q="Vem är Priestess Alathea?",a="Priestess Alathea är en kaldorei-prästtränare i Temple of the Moon i Darnassus. Hon tränar blivande präster och vägleder Night Elf-akolyter genom deras heliga prövningar.",al={"vem är alathea","alathea darnassus","alathea prästtränare"}},{q="Vilka förmågor lär hon ut?",a="Hon erbjuder vanlig prästträning i besvärjelser samt särskilda prövningar för Night Elf-rasförmågor, däribland Starshards och Elune's Grace. De kanaliserar mångudinnans direkta kraft och beskydd.",al={"alatheas förmågor","alatheas besvärjelser","prästbesvärjelser darnassus"}},{q="Var hittar jag Priestess Alathea?",a="Hon finns på bottenvåningen i Temple of the Moon, i södra Darnassus, omgiven av helgedomens lysande vatten och andra prästinnor.",al={"var finns alathea","alatheas plats"}},{q="Varför besöker Night Elf-präster henne särskilt?",a="När kaldorei-präster utvecklas i sin träning skickar nybörjartränare runt om på Teldrassil dem till Alathea för att genomgå andliga riter, som Stars of Elune och Elune's Grace. Riterna markerar deras övergång till att tjäna gudinnan fullt ut.",al={"prästuppdrag alathea","uppdraget stars of elune"}},{q="Tränar hon andra raser än Night Elf?",a="Ja. Mänskliga präster och dvärgpräster tillhör Church of the Holy Light, men alla präster i Alliance som besöker Darnassus kan lära sig allmänna besvärjelser av henne. Hon håller dock bara i kaldorei-specifika rasprövningar för Night Elf.",al={"kan människor träna med alathea","alathea dvärgpräst"}},{q="Hur skiljer sig hennes tro från mänskliga prästers och dvärgprästers?",a="Prästerna i Stormwind och Ironforge åkallar Holy Light som en närvarande kraft och filosofi. Alathea och hennes systrar vördar Elune som en levande gudom och brukar stjärnljus och månbelysta skyddsbesvärjelser tillsammans med läkande magi.",al={"elune eller holy light","night elf-prästers bakgrund"}}},fx={d359d229={q="Vems sida står Priestess Alathea på?",a="Priestess Alathea står fast på The Sisterhood of Elunes, Night Elf-folkets och Grand Alliances sida. Hon tjänar översteprästinnan Tyrande Whisperwind i det heliga Temple of the Moon och ägnar sig helt åt att tjäna Elune och vägleda trogna Night Elves.",al={"priestess alatheas fraktion","alathea och alliansen","vem tjänar alathea"}},["58a787d3"]={q="Varför är Priestess Alathea i Temple of the Moon?",a="Alathea bor i Darnassus för att utbilda och vägleda blivande Night Elf-präster. Som en hängiven tjänare till Elune i huvudstadens ståtligaste helgedom lär hon noviser att väva in Mångudinnans välsignelse i besvärjelser som skyddar och i stridens stjärneld.",al={"varför är priestess alathea här","alatheas plats i darnassus","vad gör alathea här"}},f062e3c8={q="Vad vill Priestess Alathea?",a="Alathea vill stärka den andliga hängivenheten hos Night Elf-noviser och fördjupa deras band till Elune. Hon vill att unga präster ska föra Mångudinnans visdom, nåd och stridsljus över Kalimdor för att skydda sina förfäders land.",al={"alatheas mål","vad söker alathea","priestess alatheas uppgift"}},a22ea658={q="Vem har Priestess Alathea band till?",a="Hon har nära band till The Sisterhood of Elune och tjänar under översteprästinnan Tyrande Whisperwind. Hon är stationerad bland Darnassus seniora prästinnor och samordnar utbildningen med andra akolyter i hela Temple of the Moon.",al={"priestess alatheas band","alatheas relationer","vem arbetar alathea med"}}},fp="17,203,34.310.0,27.313.0,25.127.0,30.155.0,35.151.0,48.196.0,44.209.0,57.185.0"}
P.entries["npc:priestess-anetta"] = {n="Priestess Anetta",s="Inne i Northshire Abbey lär Priestess Anetta nya präster deras första riter inom Det heliga ljuset. Hon är en mänsklig präst och medlem av Brotherhood of Northshire.",h="Inne i Northshire Abbey lär Priestess Anetta nya präster deras första riter inom Det heliga ljuset.",kw={"anetta","brotherhood of northshire","elwynn forest","det heliga ljuset","biblioteksflygel","northshire abbey","prästtränare","priestess anetta"},ang={["class:Priest"]="Som ung mänsklig präst som börjar i Northshire möter du Priestess Anetta som din första mentor. Hon bekräftar din heliga kallelse och lär dig att kommunicera direkt med Ljuset.",["faction:Alliance"]="Priestess Anetta förbereder unga präster på att stödja dem som försvarar Northshire Valley."},sec={{t="De troendes vägledare",b="På bottenvåningen i Northshire Abbey håller Priestess Anetta till i den lugna biblioteksflygeln. Defias-banditer och kobolder plågar dalen, och hon påminner dem som passerar om att Ljuset en dag kan vara det enda som räddar dem."},{t="Vägledning för novispräster",b="Nya mänskliga präster kommer till Priestess Anetta i klostergången med ett helgat introduktionsbrev. Hon lär dem att kanalisera heliga ord för att läka kött och kalla ner straffande strålglans mot ondskan. Under hennes vägledning förbereder sig de unga akolyterna på att föra Ljuset bortom Northshires avskilda murar."}},faq={{q="Vem är Priestess Anetta?",a="Priestess Anetta är en mänsklig präst inom Det heliga ljuset och medlem av Brotherhood of Northshire. På bottenvåningen i Northshire Abbey vägleder hon nyanlända präster i deras första heliga riter.",al={"vem är anetta","priestess anettas historia","priestess anetta northshire"}},{q="Var hittar jag Priestess Anetta?",a="Priestess Anetta finns inne i Northshire Abbey i norra Elwynn Forest. Gå in genom huvudingången, fortsätt in i stora salen och leta på bibliotekets bottenvåning.",al={"var finns priestess anetta","anettas plats","hitta anetta"}},{q="Vilken roll spelar hon i klostrets försvar?",a="Stormwinds marskalkar och rekryter kämpar för att återta dalen från Defias-banditer och kobolder, medan Priestess Anetta tränar präster i att hela och skydda sina kamrater med Ljuset.",al={"vad gör anetta","anettas roll"}},{q="Vilken träning erbjuder hon?",a="Priestess Anetta lär unga präster grundläggande böner och prästbesvärjelser, bland annat hur de helar och slår ner fiender i Det heliga ljusets namn.",al={"kan anetta lära mig besvärjelser","prästerbesvärjelser hos anetta"}}},fx={d2501181={q="Vems sida står Priestess Anetta på?",a="Priestess Anetta står fast på Kingdom of Stormwinds, det heliga ljusets och Brotherhood of Northshires sida. I Northshire Abbey hjälper hon rikets försvarare och värnar den fridfulla fristaden mot hoten i omgivningen.",al={"anettas fraktion","vem tjänar anetta","priestess anettas lojalitet"}},bbb44d1e={q="Vad vill Priestess Anetta?",a="Priestess Anetta vill förbereda en ny generation på att utöva det heliga ljuset. Hennes uppgift är att vägleda blivande präster i deras andliga disciplin och lära dem grunderna i att hela och skydda andra med ljuset.",al={"anettas mål","vad försöker anetta göra","anettas syfte"}},["00624d11"]={q="Varför är Priestess Anetta här?",a="Priestess Anetta bor i Northshire Abbey och är ordinerad medlem av Brotherhood of Northshire. Hon är stationerad i klostrets biblioteksflygel, där hon lär ut ljusets grunder till noviser som hörsammar Stormwinds kallelse.",al={"varför är anetta i northshire","anettas uppgift här","varför är priestess anetta i klostret"}},["1b4a2e6e"]={q="Vem har Priestess Anetta band till?",a="Anetta är en hängiven medlem av Brotherhood of Northshire och tjänar tillsammans med klostrets präster och vakter. Genom sina heliga löften och sina utbildningsuppgifter är hon nära knuten till Church of the Holy Light och Stormwinds försvar.",al={"anettas band","vem är anetta knuten till","anettas band till fraktioner"}}},fp="16,158,22.221.0,22.289.0,24.200.0,34.173.0,47.175.0,29.147.0"}
P.entries["npc:priestess-josetta"] = {n="Priestess Josetta",s="I Goldshire vägleder Priestess Josetta unga präster efter deras första prövningar i Northshire. Hon lär dem tro, hängivenhet och att tjäna andra.",h="I Goldshire vägleder Priestess Josetta unga präster efter deras första prövningar i Northshire.",kw={"desperate prayer","elwynn forest","goldshire","holy light","josetta","lion's pride inn","prästtränare","priestess josetta"},ang={["class:Priest"]="Som präst på väg från Northshire kan du lära dig grundläggande besvärjelser av Josetta och hur du omsätter dina helande löften i praktiken.",["faction:Alliance"]="Som medlem av Alliansen i Elwynn kan du vända dig till Josetta för andligt stöd och helande hjälp åt de lokala försvararna.",["race:Human"]="Som mänsklig präst får du höra Ljusets kyrkas läror i Josettas vägledning och lära dig böner ur ditt folks traditioner."},sec={{t="Ett ljus i Goldshire",b="Priestess Josetta tar hand om folket i Elwynn Forest från ett rum på övervåningen i Lion's Pride Inn. Resenärer, vakter och ortens arbetare kan komma till henne där. Hon erbjuder andlig omsorg bland vanligt folk och visar att man kan tjäna det heliga Ljuset varhelst människor behöver tröst."},{t="Att vägleda unga akolyter",b="Priestess Josetta vägleder unga präster som har avslutat sina första studier vid Northshire Abbey. Hon skickar ut dem på landsbygden för att hjälpa skadade vakter och trösta dem som lider. Deras arbete lär dem att prästyrket kräver mer än böner man lärt sig utantill. De måste låta Ljuset verka och hjälpa till att läka en trasig värld."},{t="En stilla ånger",b="Priestess Josetta ångrar att hon inte reste längre när hon var ung. Hon valde välbekanta trakter framför Azeroths vidsträckta vägar. Även om hon är nöjd med sin heliga tjänst i Goldshire uppmanar hon de unga lärjungar som besöker henne att vara modigare och bära sin tro till avlägsna gränstrakter."}},faq={{q="Var hittar jag Priestess Josetta?",a="Priestess Josetta bor i rummet på andra våningen intill Michelle Belle i Lion's Pride Inn i Goldshire.",al={"josettas plats","var finns priestess josetta","plats för prästtränare i goldshire"}},{q="Vilken uppgift har Priestess Josetta?",a="Priestess Josetta tränar Alliansens präster i heliga besvärjelser, disciplin och plikterna i deras kall efter Northshire.",al={"vad gör josetta","priestess josettas uppgift"}},{q="Varför håller Josetta till på ett värdshus i stället för i en kyrka?",a="Goldshire har inget separat kapell, och Lion's Pride Inn är stadens centrum. Från sitt rum på övervåningen kan Josetta ta hand om trötta resenärer, skadade vakter och ortsbor.",al={"varför på ett värdshus","varför lions pride inn"}},{q="Vilken personlig ånger delar Josetta med sina lärjungar?",a="Priestess Josetta ångrar att hon saknade mod att lämna hemmet och resa när hon var ung. Hon uppmanar unga äventyrare att utforska områden bortom Elwynn.",al={"josettas bakgrund","josettas ånger över att inte ha rest"}},{q="Vilka slags uppgifter ger Josetta nya präster?",a="Priestess Josetta skickar akolyter för att hjälpa skadade försvarare ute i fält. De lär sig helande böner och inser att Ljuset måste nå dem som behöver det.",al={"josettas uppdrag","garments of the light-uppdraget"}},{q="Lär Josetta ut prästerbesvärjelser för olika raser?",a="Ja. Som mänsklig prästinna i Elwynn lär Josetta mänskliga präster böner som deras folk föredrar, däribland Desperate Prayer.",al={"tränare för desperate prayer","besvärjelser för mänskliga präster"}}},fx={["41d8cc17"]={q="Vems sida står Priestess Josetta på?",a="Priestess Josetta står fast på det heliga ljusets, kyrkans och Grand Alliances sida. I Goldshire tjänar hon under Stormwinds baner och ägnar sig åt att vägleda blivande präster i riket, så att de håller sina heliga löften och tjänar sitt folk och sina allierade.",al={"priestess josettas fraktion","är priestess josetta med i alliansen","vem tjänar josetta"}},["165cad46"]={q="Vad vill Priestess Josetta?",a="Priestess Josetta vill uppmuntra hängivenhet och disciplin hos nästa generation heliga utövare. Hon ångrar i hemlighet att hon inte vågade ge sig ut i Azeroth när hon var yngre, men ägnar sig i stället åt att vägleda dig och andra noviser, så att ni kan hjälpa de sårade och föra ljuset långt bortom Goldshire.",al={"vilka mål har josetta","vad vill priestess josetta","josettas motiv"}}},fp="17,150,21.267.0,22.335.0,14.272.0,35.106.0,39.120.0,59.174.0,55.152.0,55.148.0,40.127.0"}
P.entries["npc:prospector-ironband"] = {n="Prospector Ironband",s="Prospector Darteus Ironband är en hederlig och flitig dvärgisk lantmätare som leder en arkeologisk utgrävning i sydöstra Loch Modan. Han arbetar under Dwarven Explorers' Guilds fana och är fast besluten att blottlägga det jordbundna arvet som ligger begravt under Khaz Modan. Trots motgångar och fientliga varelser i trakten fortsätter Ironband att skicka regelbundna lägesrapporter och uppgrävda reliker till Ironforge.",h="Prospector Darteus Ironband är en hederlig och flitig dvärgisk lantmätare som leder en arkeologisk utgrävning...",kw={"agmond","darteus ironband","lägesrapport om utgrävningen","utgrävningsplats","explorers' guild","ironband","loch modan","prospektör","skydda leveransen"},ang={["faction:Alliance"]="När Ironbands utgrävningsplats får förnödenheter och skydd kan Alliance hålla troggs borta från sydöstra Loch Modan och bevara värdefulla reliker.",["profession:Mining"]="Ironbands utgrävning använder vanliga hackor och grävtekniker som varje gruvarbetare känner till. Arbetet bygger på skarpa ögon som kan upptäcka bearbetad sten och begravda jordlager bland klipporna.",["race:Dwarf"]="Prospector Ironband arbetar i frontlinjen för kung Magnis strävan att förstå dvärgarnas ursprung. Därför är utgrävningen en fråga om djup kulturell stolthet för alla söner och döttrar av Ironforge."},sec={{t="Att gräva fram det förflutna",b="Darteus Ironband leder utgrävningen vid Ironband's Excavation Site, bland kullarna i sydöstra Loch Modan. Liksom många fältforskare i Explorers' Guild tror Ironband att Khaz Modans jord döljer viktiga sanningar om dvärgarnas ursprung. Hans läger arbetar outtröttligt med att gräva diken och sålla bland rasmassor i jakt på forntida reliker, stentavlor och jordbundna artefakter. Historien går långsamt att gräva fram, men Ironbands beslutsamhet rubbas inte, och han söker alltid skickliga äventyrare som kan skydda verksamheten."},{t="Problem vid gränslandet",b="En utgrävning i den karga vildmarken är aldrig lugn. Platsen utsätts för ständiga angrepp från lokala troggs och vilda djur, vilket hotar försörjningslederna och utrustningen som är nödvändiga för arbetet. Reliker och värdefull lantmäteriutrustning riskerar hela tiden att stjälas eller förstöras innan de kan undersökas. Ironband förlitar sig på förbipasserande Alliance-resenärer för att skydda godstransporterna, hålla fientliga rövare borta och undersöka vart försvunna kontakter i gillet tagit vägen i det angränsande ödemarksområdet."}},faq={{q="Vem är Prospector Ironband?",a="Prospector Darteus Ironband är en hängiven dvärgisk lantmätare som leder en arkeologisk utgrävning i sydöstra Loch Modan. Han arbetar för Dwarven Explorers' Guild och samordnar fältutgrävningar för att återfinna förlorade reliker från titanernas och de jordbundnas historia.",al={"ironband-berättelse","vem är darteus ironband","prospector ironband"}},{q="Var hittar jag Prospector Ironband?",a="Han håller till vid Ironband's Excavation Site, bland kullarna i sydöstra Loch Modan, strax öster om huvudvägen mot den södra gränsen.",al={"ironbands plats","var är ironband","ironband's excavation site plats"}},{q="Vad gräver Explorers' Guild efter här?",a="Explorers' Guild gräver ut forntida stenruiner runt om i Khaz Modan för att lägga pusslet om dvärgfolkets ursprung och hitta artefakter som titanerna lämnat efter sig.",al={"varför gräver ironband","vad gräver de ut","ironbands utgrävningsmål"}},{q="Varför behöver Ironband äventyrare som skyddar transporter?",a="Utgrävningen är starkt beroende av sprängkrut och förnödenheter som skickas från Thelsamar genom Loch Modan. En tidigare krutleverans kom aldrig fram, och Dark Iron-dvärgar hotar bärarna på vägen samtidigt som lokala troggs trakasserar själva lägret.",al={"berättelse om att skydda leveransen","varför försvara godset","ironbands förnödenheter"}},{q="Vem är Agmond och varför frågar Ironband efter honom?",a="Agmond var en dvärgisk lantmätarkollega som gav sig av för att undersöka utgrävningar längre söderut. När kontakten bröts bad Ironband resenärer att söka igenom Badlands för att ta reda på vad som hänt honom.",al={"hitta agmond","vem är agmond","agmonds öde"}},{q="Är Prospector Ironband släkt med Bardin Ironband?",a="De har samma efternamn och arbetar båda nära dvärgarnas verksamhet vid gränslandet, vilket antyder ett släktskap. Darteus håller dock strikt fokus på arkeologin och rapporterna till gillet.",al={"är bardin ironband släkt","ironband-familjen","darteus och bardin"}}},fx={["8f75b961"]={q="Vems sida står Prospector Ironband på?",a="Ironband tjänar Ironforge och Alliansen genom Dwarven Explorers' Guild. Han lyder under gillets ledare och King Magni Bronzebeard och ägnar sina krafter åt att hitta uråldrig kunskap om titanerna och forntida artefakter i Khaz Modan, till gagn för dvärgfolket.",al={"ironbands fraktion","åt vem arbetar ironband","ironband och alliansen"}}},fp="19,300,19.437.0,17.385.0,27.173.0,37.159.0,46.156.0,56.211.0,50.169.0,50.196.0"}
P.entries["npc:prospector-remtravel"] = {n="Prospector Remtravel",s="Prospector Remtravel är en dvärgarkeolog knuten till Explorers' League och stationerad djupt inne i Darkshores dystra skogsmarker. Han leder en utgrävning där gamla reliker grävs fram, men hans splittrade uppmärksamhet och farliga omgivning gör att han ständigt behöver hjälp.",h="Prospector Remtravel är en dvärgarkeolog knuten till Explorers' League och stationerad djupt inne i...",kw={"tankspridd prospektör","darkshore","explorers' league","fossil","ironforge","prospector remtravel","remtravel","remtravels utgrävning"},ang={["race:Dwarf"]="Remtravel står för Explorers' Leagues outtröttliga beslutsamhet att pussla ihop dvärgarnas ursprung, även när det innebär att slå upp tält i Kalimdors kalla, fuktiga skogar.",["race:NightElf"]="Nattalverna tolererar fredliga gäster från Alliansen, men ligans högljudda grävande och störande av gammal jord sätter ofta lokala vaktposters och druider tålamod på prov."},sec={{t="En dvärggrävning i alvernas land",b="Prospector Remtravel skickades långt över havet av Explorers' League och anlade sin utgrävning i södra Darkshore. Nattalverna värnar ofta om sina förfäders områden, men ligans omättliga strävan efter att avslöja Azeroths ursprung driver prospektörer till varje bortglömd vrå. Remtravels arbete gräver fram fossiliserad historia och gamla stenar, men aggressiva vilda djur och fientliga hot i trakten gör det nästan för mycket för en tankspridd dvärg att sköta en utpostgrävning."},{t="Den tankspridde lärde",b="Remtravel lever upp till sitt rykte och försjunker lätt i sina tankar och forskningsanteckningar. När han beger sig för långt från lägret i jakt på fossil eller förlorade artefakter slutar det ofta illa, och han blir inträngd av rovdjur eller fientliga varelser. De som stöter på honom ute i vildmarken får vanligtvis i uppgift att skydda hans ömtåliga fynd – och rädda prospektören själv innan farorna i Darkshore sätter stopp för hans uppdrag."}},faq={{q="Vem är Prospector Remtravel?",a="Han är en arkeolog och kartläggare från Ironforge som företräder Explorers' League. Han har upprättat ett litet utgrävningsläger i södra Darkshore för att hitta gamla reliker och fossil.",al={"vem är remtravel","remtravels bakgrund","vem är dvärgen i darkshore"}},{q="Varför gräver en dvärg från Ironforge i Darkshore?",a="Explorers' League söker igenom den kända världen efter titanartefakter, förlorad historia och gamla fossil. Darkshore är ett uråldrigt, ödelagt land med djupa band till det avlägsna förflutna, vilket gör det till en idealisk plats för dvärgarnas arkeologiska undersökningar.",al={"varför är en dvärg i darkshore","vad gör explorers' league i darkshore","varför gräva här"}},{q="Varför kallas han tankspridd?",a="Remtravel brukar tappa bort sig i omgivningen och glömma sin egen utrustning när han är uppslukad av sina lärda sysslor. Han vandrar ofta in i farliga områden utan att märka rovdjuren och bestarna som närmar sig.",al={"varför är han tankspridd","är remtravel galen","vad hände med remtravel"}},{q="Är Prospector Remtravel släkt med någon i ligan?",a="Han tros vara den äventyrlige farbror som Karna Remtravel nämner. Hon är en upptäcktsresande som säger att hennes farbror inspirerade hennes passion för upptäckter och den vida världen.",al={"remtravels familj","karna remtravels farbror","vem är karna remtravel"}}},fx={a4e27c5f={q="Vems sida står Prospector Remtravel på?",a="Prospector Remtravel är en lojal undersåte till Ironforge och agent för dvärgarnas Explorers' League. Eftersom Ironforge står vid Darnassus sida i Grand Alliance arbetar han öppet i Night Elf-länder och förlitar sig på att vänligt sinnade resenärer hjälper honom med forskningen och håller farorna i området på avstånd.",al={"prospector remtravels fraktion","vem tjänar remtravel","remtravel och alliansen"}},a325ae20={q="Vad vill Prospector Remtravel?",a="Precis som många andra i Explorers' League söker Remtravel efter forntida reliker och geologiska märkvärdigheter begravda i okänd mark. Han är fast besluten att avslöja historien under Darkshores yta, men hans tankspridda fokus på fynden gör honom ofta blind för de omedelbara faror som lurar kring utgrävningsplatsen.",al={"vad letar remtravel efter","remtravels mål","varför gräver remtravel"}}},fp="20,176,28.418.0,25.292.1,28.194.0,47.199.0,31.165.0,56.164.0"}
P.entries["npc:prospector-ryedol"] = {n="Prospector Ryedol",s="Prospector Ryedol är en kartläggare i Explorers' League, stationerad på en dammig höjd med utsikt över östra Badlands. Han vakar över de farofyllda utgrävningarna nedanför och kämpar för att återfinna förlorade dvärgreliker och hålla hoppet vid liv i en karg ödemark som svämmar över av troggs och vilddjur.",h="Prospector Ryedol är en kartläggare i Explorers' League, stationerad på en dammig höjd med utsikt över östra...",kw={"badlands","utgrävningsplats","explorers' league","hammertoe","ironforge","prospector ryedol","ryedol"},ang={["faction:Alliance"]="För alliansens äventyrare som färdas genom Badlands farliga ödemarker erbjuder Ryedol ett vänligt ansikte och brådskande uppgifter till stöd för Explorers' League.",["race:Dwarf"]="Ryedol står för Ironforges orubbliga vilja att avslöja dvärgarnas ursprung, även när utgrävningarna sker i Khaz Modans mest ogästvänliga trakter."},sec={{t="Vakar över utgrävningarna",b="På en karg kulle strax söder om Hammertoe's Digsite står Prospector Ryedol som en representant för Ironforges Explorers' League och dess fortsatta arbete i Badlands. Den torra dalen rymmer uråldriga hemligheter om titanerna och ett rikt jordbundet arv, men fältexpeditioner här plågas ständigt av vilda troggs, glupska prärievargar och revirhävdande drakar. Ryedol samordnar arbetet med att återta dvärgutrustning som stulits av Dark Iron-dvärgarna och söker tecken på hopp bland de förstörda utposterna. Han tänker inte låta ligans uppoffringar i ödemarken vara förgäves."}},faq={{q="Vem är Prospector Ryedol?",a="Ryedol är en dvärgisk fältforskare i Explorers' League. Han har slagit läger på en hög kulle med utsikt över Hammertoe's Digsite i östra Badlands, där han hjälper till att leda bärgnings- och återvinningsuppdrag.",al={"ryedol","vem är ryedol","prospector ryedols plats"}},{q="Vad gör Ryedol i Badlands?",a="Han är stationerad i Badlands för att stödja Explorers' Leagues arkeologiska expeditioner. Flera utgrävningsplatser i närheten har tagits över eller hotas av Dark Iron-dvärgar och troggs. Därför samarbetar han med resenärer för att säkra återfunna reliker, spåra förlorade verktyg och ta reda på vad som hänt hans dvärgiska kamrater.",al={"vad gör ryedol","ryedols uppdrag","varför är ryedol här"}},{q="Vad är Ryedol's Hammer?",a="Ryedol's Hammer är en belöning för att återta hans Lucky Pick från Dark Iron-dvärgarna som angrep Hammertoe's Digsite. Det stulna föremålet är hans hacka, inte belöningshammaren.",al={"ryedols hammare","dvärg och hans verktyg"}}},fp="17,268,22.553.0,25.209.0,37.289.0,24.170.0"}
P.entries["npc:prospector-stormpike"] = {n="Prospector Stormpike",s="Prospector Stormpike är en rättfram dvärg med kort stubin, stationerad i biblioteket i Hall of Explorers i Ironforge. Som medlem av den berömda Stormpike-klanen ansvarar han för logistiskt stöd till avlägsna arkeologiska utgrävningar och använder sitt skarpa intellekt till att tyda kodade meddelanden.",h="Prospector Stormpike är en rättfram dvärg med kort stubin, stationerad i biblioteket i Hall of Explorers i...",kw={"argus wake","explorers league","hall of explorers","ironforge","joren ironband","bibliotek","prospector stormpike","stormpike-klanen"},ang={["faction:Alliance"]="Utöver utgrävningarna hjälper Stormpikes kunskaper i kryptografi Alliansens verksamhet i de nordliga länderna mot skumma människokulter som Argus Wake.",["race:Dwarf"]="Stormpike förkroppsligar Explorers' Leagues målmedvetna och rättframma anda. Han ser forntida forskning och logistik som frågor som väcker den största dvärgiska stoltheten."},sec={{t="Lärd vid Hall of Explorers",b="Bland de höga bokhyllorna i Hall of Explorers samordnar Prospector Stormpike utgrävningar i Khaz Modan och längre bort. Trots sitt barska sätt och sin otålighet med tomt prat är han djupt hängiven åt att upptäcka dvärgarnas historia och se till att avlägsna platser får viktiga förnödenheter, som sprängpulver. Under den hårda ytan döljer sig ett skarpsinnigt analytiskt sinne med fallenhet för att knäcka invecklade chiffer. Det gör honom till en oväntad tillgång för Alliansens spejare som hanterar hemliga hot."}},faq={{q="Vem är Prospector Stormpike?",a="Han är arkeolog och logistikansvarig från den välkända Stormpike-klanen och håller till i biblioteksdelen av Hall of Explorers i Ironforge.",al={"vem är stormpike","prospector stormpikes bakgrund","stormpike npc"}},{q="Var hittar jag Prospector Stormpike?",a="Han står i biblioteket, som ligger i Hall of Explorers i den östra delen av Ironforge.",al={"stormpikes plats","var finns prospector stormpike"}},{q="Vad arbetar han med?",a="Stormpike sköter försörjningslinjer och rapporter för arkeologiska utgrävningar. Han skickar till exempel sprängpulver till prospektörer ute i fält, som Prospector Ironband i Loch Modan, och hjälper till att knäcka komplicerade chiffer som spejare för med sig tillbaka.",al={"stormpike uppdrag","vad gör stormpike"}},{q="Varför behöver Southshore hans hjälp?",a="Alliansens myndigheter i Southshore förlitar sig på hans kunskaper i kryptografi för att tyda avlyssnade brev från den hemlighetsfulla kulten Argus Wake.",al={"argus wake chiffer","southshore stormpike"}}},fx={["676ebbc6"]={q="På vems sida står Prospector Stormpike?",a="Prospector Stormpike är lojal mot kungariket Ironforge och Alliansen. Som agent för dvärgarnas Explorers' League tjänar hans fältuppdrag och arkeologiska forskning direkt King Magni Bronzebeard och dvärgrikets intressen.",al={"stormpikes fraktion","prospector stormpike och alliansen","vem tjänar stormpike"}},b4a2ac01={q="Vad vill Prospector Stormpike?",a="Prospector Stormpike vill tyda viktig information och samordna arkeologiska expeditioner utan onödiga störningar. Han övervakar forskning vid utgrävningar som Ironband's Excavation Site i Loch Modan och använder sin expertis inom kryptoanalys för att dechiffrera kodade meddelanden. Han kräver full koncentration och har inget tålamod med onödiga distraktioner.",al={"vad behöver stormpike","prospector stormpikes mål","stormpikes motiv"}},["1b565b81"]={q="Varför är Prospector Stormpike i Ironforge?",a="Du hittar Prospector Stormpike i biblioteket i Ironforges Hall of Explorers, eftersom det är Explorers' Leagues operativa centrum. Där granskar han fältrapporter, översätter återfunna reliker och tyder avlyssnad korrespondens som kräver lärd expertis.",al={"varför är stormpike här","prospector stormpike bibliotek","varför hall of explorers för stormpike"}},dbd365e1={q="Vilka band har Prospector Stormpike?",a="Han tillhör den inflytelserika Stormpike-klanen, en ansedd dvärgsläkt som är välkänd i hela Khaz Modan. Utanför klanen arbetar han direkt med andra fältprospektörer, som Prospector Ironband, och hjälper Alliansens ledare i Southshore genom att knäcka fiendens chiffer.",al={"stormpikes klanband","prospector stormpikes allierade","stormpikes band till ligan"}},d5ca9c54={q="Varför är Prospector Stormpike berömd eller fruktad?",a="Prospector Stormpike är känd för sin enastående förmåga att tyda komplexa, krypterade dokument och sitt beryktade, häftiga temperament. Få lärda har både hans skarpa sinne för kryptoanalys och hans explosiva otålighet med dem som slösar bort hans tid.",al={"stormpikes rykte","varför är prospector stormpike känd","stormpikes häftiga temperament"}}},fp="20,191,32.336.0,28.156.0,38.110.0,29.199.0,34.122.0"}
P.entries["npc:prospector-whelgar"] = {n="Prospector Whelgar",s="Prospector Whelgar är en arkeologisk dvärg som arbetar vid en utgrävning i Wetlands, öster om Menethil Harbor. Hans uppdrag att hitta titanreliker har stannat av sedan våldsamma rovraptorer tog över utgrävningen. Nu söker han tåliga äventyrare som vågar trotsa bestarna för att återfinna forntida artefakter.",h="Prospector Whelgar är en arkeologisk dvärg som arbetar vid en utgrävning i Wetlands, öster om Menethil Harbor.",kw={"dvärg","utgrävningsplats","explorers league","goaz stone","prospector whelgar","avslöja det förflutna","wetlands","whelgar"},ang={["profession:Mining"]="De karga åsarna kring Whelgars utgrävning innehåller rika mineralådror, men prospektörer måste tampas med samma rovraptorer som plågar Whelgars team.",["race:Dwarf"]="Whelgars uppdrag tjänar direkt Explorers' League och King Magni Bronzebeards pågående sökande efter dvärgarnas titanrötter."},sec={{t="En utgrävning under belägring",b="Prospector Whelgar skickades ut i Wetlands sumpiga vildmark för att gräva fram dvärgarnas historia och anlade ett arkeologiskt läger kallat Whelgar's Excavation Site. Dalen var en gång rik på uråldriga stenreliker, men de lokala rovraptorerna blev snabbt revirhävdande och drev hans team i skydd. Trots faran vägrar Whelgar att överge sin plikt. Han är fast besluten att återfinna värdefulla reliker, däribland den gåtfulla Goaz Stone, innan vilda rovdjur eller rivaliserande skurkar förstör platsen helt."}},faq={{q="Vem är Prospector Whelgar?",a="Prospector Whelgar är en dvärgarkeolog från Ironforge med uppdraget att leda en expedition i Wetlands. Han övervakar utgrävningsplatsen öster om Menethil Harbor och studerar reliker från dvärgarnas tidigaste historia.",al={"whelgar","vem är whelgar","prospector whelgar berättelse"}},{q="Var hittar jag Prospector Whelgar?",a="Han håller sig i skydd på en ås med utsikt över Whelgar's Excavation Site, öster om Menethil Harbor och sydväst om Dun Modr i Wetlands.",al={"whelgars plats","var är whelgar","whelgar wetlands karta"}},{q="Varför har Whelgar problem vid utgrävningen?",a="Hårdföra rovraptorer från trakten har tagit över utgrävningen helt, dödat eller skingrat hans besättning och tvingat Whelgar att hålla sig i ett försvarbart hörn. Han kan inte fortsätta gräva fram reliker utan beskydd utifrån.",al={"rovraptorer vid utgrävningen","vad hände vid whelgars utgrävning","rovraptorer vid whelgars utgrävning"}},{q="Vad är Goaz Stone?",a="Goaz Stone är en forntida artefakt som hittades bland ruinerna vid utgrävningen. Whelgar försöker tyda dess inskrifter för att bättre förstå dvärgfolkets bortglömda ursprung och forntida historia.",al={"goaz stone","vad är goaz stone","relik från det förflutna"}}},fx={["430ccc65"]={q="På vems sida står Prospector Whelgar?",a="Prospector Whelgar är obrottsligt lojal mot Ironforge och Alliansen. Liksom andra dvärgprospektörer utför han sina expeditioner i dvärgarnas kulturarvs och Explorers' Leagues tjänst och gräver fram forntida historia för sitt folk.",al={"whelgars fraktion","är whelgar med i alliansen","vem tjänar whelgar"}},["3be180e4"]={q="Vad vill Prospector Whelgar?",a="Whelgar vill kunna genomföra sina utgrävningar säkert och hitta reliker från det förflutna, framför allt förstå forntida föremål som Goaz Stone. Men lokala hot, som rovfåglarna som tagit över utgrävningsplatsen, sätter ständigt käppar i hjulen för hans arkeologiska arbete.",al={"vad behöver whelgar","whelgars mål","whelgars avsikt"}},["3a0c9faf"]={q="Varför är Prospector Whelgar här i Wetlands?",a="Han reste till Wetlands för att leda utgrävningar bland regionens forntida ruiner. Här anlade han en utgrävningsplats för att hitta lämningar från dvärgarnas forntid, men expeditionen har drabbats hårt av våldsam fauna och faror i området.",al={"varför är whelgar i wetlands","syftet med whelgars utgrävning"}},bbf3af84={q="Vilka band har Prospector Whelgar?",a="Whelgar har anknytning till de arkeologiska satsningarna från Ironforge och arbetar med andra dvärgprospektörer och forskare. Tillsammans undersöker de titanernas ruiner och forntida ruiner byggda av titanerna i hela Khaz Modan och bortom det.",al={"whelgars organisation","whelgars tillhörighet","vem rapporterar whelgar till"}}},fp="18,181,17.441.0,26.172.0,36.153.0,46.178.0,23.227.0"}
P.entries["npc:quartermaster-lewis"] = {n="Quartermaster Lewis",s="På Sentinel Hill i Westfall ser Quartermaster Lewis till att förnödenheter når People's Militia. Han hjälper lokala försvarare och resenärer som håller gränsen mot Defias Brotherhood.",h="På Sentinel Hill i Westfall ser Quartermaster Lewis till att förnödenheter når People's Militia.",kw={"lewis","peoples militia","quartermaster lewis","sentinel hill","sentinel tower","handlare","westfall"},ang={["class:Hunter"]="Som Hunter kan du hämta förnödenheter för fältbruk hos Lewis i centrala Westfall, däribland ammunition och pilar för försvar på avstånd.",["faction:Alliance"]="Som rekryt i Alliance i Westfall kan du fylla på förråden hos Lewis i fientligt land där kronans resurser är knappa."},sec={{t="Väktare av tornets förråd",b="Quartermaster Lewis håller ordning på milisens förnödenheter i Sentinel Tower. Stormwinds kungliga ledare ger Westfall, som är fattigt, föga hjälp, så Sentinel Hill är beroende av lokala frivilliga och de förnödenheter de kan samla ihop. Lewis delar ut sådant som behövs i fält, däribland torrproviant, färskt vatten, pilar, ammunition och kastknivar. Kämparna som håller vakt behöver dessa grundläggande förnödenheter för att uthärda Defias räder."}},faq={{q="Vem är Quartermaster Lewis?",a="Quartermaster Lewis tjänstgör i Sentinel Tower i Westfall. Han sköter vardagliga förnödenheter, matransoner och vapen åt People's Militia och äventyrare som hjälper till att försvara regionen.",al={"quartermaster lewis historia","vem är lewis","kvartermästare på sentinel hill"}},{q="Vad säljer Quartermaster Lewis?",a="Quartermaster Lewis säljer grundläggande överlevnadsvaror, däribland bröd, mjölk, vatten, väskor, flinta, pilar, kulor och kastdolkar.",al={"vad säljer lewis","lewis varulager","varor hos handlare i westfall"}},{q="Vilken roll har han i uppdrag i regionen?",a="Eftersom Stormwind hjälper föga skickar Lewis äventyrare via Thor, gryphonmästaren, för att lämna ett meddelande till Osric Strang, hans rustningsleverantör i Stormwinds Old Town, och hämta Osric's Crate med rustningar till Sentinel Hill.",al={"lewis uppdrag","ett snabbt meddelande","återvänd till lewis"}},{q="Tillhör Lewis Stormwinds armé?",a="Lewis tjänar People's Militia, liksom de flesta försvarare i Sentinel Hill, snarare än en officiell styrka utsänd av Stormwinds krona. Westfall har i stort sett lämnats att försvara sig självt mot Defias Brotherhood.",al={"tillhör lewis armén","stormwind-vakten lewis","peoples militia lewis"}}},fx={f4ce3c2d={q="Varför är Quartermaster Lewis stationerad här?",a="Quartermaster Lewis är stationerad vid Sentinel Hill i Westfall för att förse People's Militia och Alliansens resande äventyrare med förnödenheter. Westfall har till stor del övergivits av kronan och översvämmats av Defias Brotherhood, så försvararna vid tornet förlitar sig på Lewis för att få viktiga förnödenheter, ammunition och överlevnadsutrustning.",al={"varför är lewis här","varför är quartermaster lewis i westfall","varför är quartermaster lewis vid sentinel tower"}}},fp="19,187,28.366.0,27.176.0,35.133.0,36.225.0,36.212.0"}
P.entries["npc:quinn-yorick"] = {n="Quinn Yorick",s="Quinn Yorick är en sårad Forsaken-spejare som söker skydd på övervåningen i en förfallen bondgård på The Ivar Patch. Efter att nätt och jämnt ha överlevt ett möte med en ghoul vid namn Ivar the Foul är han nu beroende av förbipasserande allierade för att överleva.",h="Quinn Yorick är en sårad Forsaken-spejare som söker skydd på övervåningen i en förfallen bondgård på The Ivar...",kw={"forsaken-spejare","ghoul","the ivar patch","ivar the foul","quinn yorick","silverpine forest"},ang={["race:Undead"]="Quinns belägenhet visar den ständiga fara som regionens ghouls och bestar utgör för Forsaken-styrkorna när de försöker säkra norra Silverpine."},sec={{t="Ett osäkert skydd",b="Undangömd i ett övergivet hus på The Ivar Patch ligger Quinn Yorick svårt skadad på övervåningen. Hans tillstånd beror på en våldsam strid med Ivar the Foul, en ghoul som lurar i gårdens lada i de norra delarna av Silverpine Forest. Quinn skickades med sin syster Rane för att spana i Silverpine och rapportera till High Executor Hadrec. Han kan varken slutföra sitt uppdrag eller tryggt ta sig därifrån på egen hand, så han håller sig gömd medan resenärer i Forsakens tjänst hjälper honom att läka och tar hand om varelsen som nästan slet honom i stycken."}},faq={{q="Var finns Quinn Yorick?",a="Quinn Yorick gömmer sig på övervåningen i en förfallen bondgård på The Ivar Patch, i Silverpine Forest norr om The Sepulcher.",al={"quinn yoricks plats","var är quinn","quinn yoricks hus"}},{q="Vem skadade Quinn Yorick?",a="Han skadades svårt av Ivar the Foul, en våldsam ghoul som lurar i gårdens lada.",al={"vem attackerade quinn","vad hände med quinn yorick","quinn skadad"}},{q="Vilken roll har Quinn för Hordens äventyrare?",a="Quinns syster, Deathstalker Rane Yorick, skickar äventyrare för att ge honom en läkande dryck. När han har druckit den ber hon dem döda Ivar the Foul, så att Quinn får tid att återhämta sig.",al={"quinn yorick-uppdrag","quinn uppdragsgivare"}}},fx={["63631c13"]={q="Vem är Quinn Yorick?",a="Quinn Yorick är en Forsaken Deathstalker som gömmer sig på övervåningen i en förfallen bondgård i The Ivar Patch. Han skadades svårt av ghulen Ivar the Foul när han spanade i Silverpine Forest med sin syster Rane. Nu håller han sig i skuggorna och förlitar sig på resande från Horde för att få hjälp medan han återhämtar sig.",al={"vem är quinn","quinn yoricks bakgrund","vem är quinn yorick"}},f58f2509={q="På vems sida står Quinn Yorick?",a="Quinn är lojal mot Lady Sylvanas Windrunner och Forsaken och därmed Horde. Han välkomnar Horde-hjältar som kommer till den avlägsna gården och söker deras hjälp mot de vilda hoten som lurar strax utanför hans gömställe.",al={"quinn yoricks fraktion","tillhör quinn yorick horde","quinn yoricks lojalitet"}},cd20af14={q="Varför är Quinn Yorick här?",a="Quinn och hans syster Rane skickades för att spana i Silverpine Forest och rapportera till High Executor Hadrec. Men på gården anfölls de av Ivar the Foul, som lemlästade Quinn svårt. Eftersom han inte kunde fly eller fortsätta på egen hand tog han skydd på andra våningen i den övergivna bondgården för att överleva.",al={"varför är quinn yorick i the ivar patch","quinn yoricks syfte här","varför är quinn på övervåningen"}},e4d12614={q="Vad vill Quinn Yorick?",a="Quinn är fast med att vårda sina svåra sår och vill få tid att läka så att han kan resa igen. En läkande dryck som äventyrare kommer med sätter hans återhämtning i gång, och hans syster Rane ber dem döda Ivar the Foul innan ghulen kan återvända efter honom.",al={"vad vill quinn","quinn yoricks mål","quinn yoricks avsikter"}}},fp="12,165,19.489.0,30.123.0,25.83.0,49.179.0"}
P.entries["npc:raene-wolfrunner"] = {n="Raene Wolfrunner",s="Raene Wolfrunner är en erfaren Sentinel-officer och jägare stationerad mitt i Astranaar i Ashenvale. Med sina trogna följeslagare, en varg och en sabelkatt, samordnar hon försvaret av skogen mot Horde-styrkor som tränger fram och fördärvade furbolg-stammar. Hon är ett viktigt stöd för Alliance-hjältar som strävar efter att skydda den heliga vildmarken.",h="Raene Wolfrunner är en erfaren Sentinel-officer och jägare stationerad mitt i Astranaar i Ashenvale.",kw={"ashenvale","astranaar","dagri","dartol","korra","raene","sentinels","teronis","thistlefur","wolfrunner"},ang={["class:Hunter"]="Som en erfaren jägare som leder både en varg och en sabelkatt står Raene för den vildmarkskunskap och samhörighet med djur som hennes klass värdesätter.",["faction:Alliance"]="För Alliance-resande som anländer från Darkshore är Raene den främsta officeren som samordnar Ashenvales militära försvar och skyddet av dess natur.",["race:NightElf"]="Raene förkroppsligar Sentinels hängivenhet till Elune och Kalimdors vildmark. Hon tänker inte låta Ashenvales skogssanctuarier skövlas."},sec={{t="Astranaars försvarare",b="Raene Wolfrunner håller vaksamt uppsikt i Astranaar tillsammans med sin pålitliga sabelkatt Korra och vargen Dagri. Som officer bland Sentinels övervakar hon patrullerna i Ashenvale och samordnar underrättelser från områden bortom dess gränser. Hon skickar ut spejare som Kaela Shadowspear till närliggande områden som Stonetalon Mountains."},{t="Att hejda skogens fördärv",b="Utöver spänningarna med Horde är Raene djupt engagerad i att bekämpa den mörka smitta som plågar Ashenvales invånare. Hon leder kampanjer mot fientliga furbolg-stammar, bland annat aggressiva anfall mot Foulweald-lägren som trakasserar resande och riktade utrensningar av Thistlefurs växande ledarskikt. Hennes underställda spejare håller noga uppsikt över furbolgernas förändrade beteende. De förlitar sig på Raenes stadiga ledning för att skydda lokala bosättningar och vägfarande från samordnade bakhåll."},{t="Dartol's Rod",b="Raenes mest personliga korståg gäller Dartol's Rod, en uråldrig relik med koppling till furbolgernas rening. Hennes mångårige vän Teronis dödades när han sökte efter stavens försvunna ädelsten. Därför beordrade Raene att hans kropp skulle återföras och lovade att slutföra hans forskning. Tillsammans med dryaden Shael'dryn hjälper hon hjältar att sätta ihop reliken. Den gör det till slut möjligt för en äventyrare att anta furbolgskepnad, tala med hövdingen Krolg och besegra den fördärvade ledaren Ran Bloodtooth för att rensa bort hotet i området."}},faq={{q="Var hittar man Raene Wolfrunner?",a="Raene är stationerad i Astranaar, den centrala Night Elf-staden i Ashenvale. Hon står redo utomhus med sina två djurföljeslagare vid sin sida.",al={"raene wolfrunner plats","var finns raene","raene plats i astranaar"}},{q="Vilka djur står bredvid Raene?",a="De är hennes tränade jaktkamrater: en sabelkatt vid namn Korra och en varg vid namn Dagri. De håller sig vid hennes sida i Astranaar.",al={"raene wolfrunner husdjur","raenes varg och katt","raenes följeslagare"}},{q="Vilken roll har Raene bland Sentinels?",a="Hon är en högt uppsatt Sentinel-officer i centrala Ashenvale. Hon ger order till spejare, sköter utposter och samordnar taktiska insatser mot lokala hot.",al={"raenes grad","är raene officer","raenes roll som sentinel"}},{q="Vad hände med Raenes vän Teronis?",a="Teronis hjälpte Sentinels genom att söka efter en ädelsten som behövdes till Dartol's Rod. Han dödades ute i fält, och Raene såg till att hans kvarlevor återfördes och att hans uppdrag slutfördes.",al={"vem är teronis","raenes vän teronis","teronis död"}},{q="Varför fokuserar Raene så mycket på furbolgerna?",a="Fördärvade stammar som Foulweald och Thistlefur har blivit allt aggressivare. De överfaller resande på skogsvägarna och hotar Astranaars stabilitet.",al={"raene furbolg-uppdrag","varför slåss mot thistlefur","foulwealds problem i ashenvale"}},{q="Vad har Dartol's Rod för syfte i hennes uppdrag?",a="Den återuppbyggda staven låter en äventyrare tillfälligt anta en furbolgs skepnad. Det öppnar för samtal med Krolg, så att den fördärvade hövdingen Ran Bloodtooth kan pekas ut och besegras.",al={"dartol's rods syfte","vad gör dartol's rod","raenes reningsstav"}}},fx={["0f58d83b"]={q="På vems sida står Raene Wolfrunner?",a="Raene försvarar nattalverna och Alliansen troget. Som officer bland Sentinels samordnar hon patruller och försvar från Astranaar och ägnar sig helt åt att skydda sitt folk och driva bort hoten som tränger in i de forntida skogarna.",al={"raene wolfrunners fraktion","är raene med i alliansen","vem strider raene för"}},c8e1b22c={q="Vad vill Raene Wolfrunner?",a="Raene vill rena Ashenvale från fördärv och skydda Astranaar mot hoten i området. Hon är fast besluten att slutföra arbetet efter sin fallne kamrat Teronis, rensa ut fientliga furbolgstammar som Foulweald och Thistlefur och värna vildmarkens helgd mot vanhelgande.",al={"raene wolfrunners mål","vad försöker raene göra","raene wolfrunners syfte"}},eb1515b1={q="Varför är Raene Wolfrunner här i Ashenvale?",a="Raene är stationerad i Astranaar, där hon hoppas kunna lindra det fördärv som fått fäste i den forntida skogen. Hon står Ashenvales väl nära, leder Sentinel-spejare, slår tillbaka angripande furbolg som drabbats av fördärv och övervakar regionens insatser mot de växande hoten i vildmarken.",al={"varför är raene i astranaar","varför kom raene till ashenvale","raene wolfrunners bakgrund"}},["86b9293d"]={q="Vilka band har Raene Wolfrunner?",a="Raene leder lokala Sentinels och spejare, däribland Kaela Shadowspear och Selarin. Hon stod den avlidne Teronis nära och hyser vänskaplig respekt för dryaden Shael'dryn.",al={"raene wolfrunners allierade","raenes vänner","vem känner raene"}}},fp="16,178,21.305.0,32.400.0,12.452.1,36.123.0,43.98.0,42.154.0,40.152.1,49.165.0,53.142.1"}
P.entries["npc:ragnar-thunderbrew"] = {n="Ragnar Thunderbrew",s="Ragnar Thunderbrew är en dvärgisk bryggare och delägare i det välkända Thunderbrew Distillery i Kharanos. I hela Dun Morogh är han känd för att servera familjens signaturrätt Boar Ribs, och han arbetar ständigt för att hålla den välbesökta tavernan välförsedd och gästerna nöjda.",h="Ragnar Thunderbrew är en dvärgisk bryggare och delägare i det välkända Thunderbrew Distillery i Kharanos.",kw={"öl","ölbakade vildsvinsrevben","dun morogh","dvärg","grimbooze thunderbrew","kharanos","ragnar thunderbrew","thunderbrew distillery"},ang={["profession:Cooking"]="Ragnar är känd för familjen Thunderbrews recept på ölbakade Boar Ribs, så han är en värdefull kontakt för blivande kockar som vill lära sig laga mustiga dvärgiska pubrätter.",["race:Dwarf"]="För dvärgar som passerar genom Dun Morogh är Ragnars taverna ett hem hemifrån, där klanen visar upp sin finaste öl och ribbrätter."},sec={{t="Kharanos gästfrihet",b="Inne på Thunderbrew Distillery i Kharanos sköter Ragnar Thunderbrew ställets kulinariska rykte vid sidan av familjens bryggeriverksamhet. Destilleriet är en central samlingsplats för lokala bergsvandrare, resande äventyrare och gnomflyktingar från Gnomeregan. En av hans främsta uppgifter är att tillaga familjens berömda Boar Ribs, en mättande specialitet från Dun Morogh som lagas med mustig dvärgöl. Men det har blivit svårt att hålla lagren fyllda. Hans vanliga köttleverantör tog värvning i kungens armé, så Ragnar är beroende av kringströvande bergsvandrare och jägare för att få in färska flanker från klippvildsvin till köket."},{t="Thunderbrew-arvet",b="Namnet Thunderbrew är synonymt med dvärgisk alkohol och pubkultur i hela Ironforge-området. Ragnar har hållit familjens destilleri i gång sedan hans äldre bror, Grimbooze Thunderbrew, försvann i ett rus för några skördar sedan. Han försvarar familjens strängt bevakade bryggartradition mot tjuvar som Dark Iron-dvärgarna, som stal receptet till Thunderbrew Lager. Mellan rastlösa gäster, bristande leveranser och stojiga tavernabråk håller Ragnar ett stadigt grepp om kranarna. Han ser till att ingen resenär lämnar Kharanos med en tom mugg eller tom mage."}},faq={{q="Vem är Ragnar Thunderbrew?",a="Ragnar Thunderbrew är en dvärgisk bryggare och delägare i Thunderbrew Distillery i Kharanos. Han sköter tavernan och tillagar klanens berömda ölbakade Boar Ribs.",al={"vem är ragnar","ragnars roll","ragnar i kharanos"}},{q="Varför letar Ragnar efter vildsvinskött?",a="Ragnars vanliga köttleverantör tog värvning i kung Magni Bronzebeards armé, så köket har ont om råvaror. För att mätta hungriga gäster köper han färska flanker av jägare och resande som passerar.",al={"varför behövs vildsvinskött","uppdrag med ölbakade revben","tillgång på vildsvinsrevben"}},{q="Hur är Ragnar släkt med Grimbooze Thunderbrew?",a="Grimbooze är Ragnars äldre bror. Deras far, Arkilus, grundade Thunderbrew Distillery, och Ragnar har hållit det i gång sedan Grimbooze försvann i ett rus för några skördar sedan.",al={"ragnar och grimbooze","släktskap med grimbooze thunderbrew"}},{q="Var finns Ragnar Thunderbrew?",a="Ragnar finns inne på Thunderbrew Distillery i byn Kharanos, bland de snötäckta kullarna mitt i Dun Morogh.",al={"ragnars plats","var hittar man ragnar thunderbrew"}}},fx={a4e8a35c={q="På vems sida står Ragnar Thunderbrew?",a="Ragnar står helhjärtat på Ironforges och Grand Alliances sida. Från Kharanos betjänar han stolt dvärgresenärer, bergsklättrare och lokala patruller som ofta besöker destilleriet.",al={"ragnar thunderbrews fraktion","ragnar och alliansen","är ragnar vänligt inställd till alliansen"}},["6e9b3705"]={q="Varför är Ragnar Thunderbrew här i Kharanos?",a="Ragnar är i Kharanos för att driva Thunderbrew Distillery. Som delägare arbetar han från det lokala värdshuset med att brygga dvärgår, laga rejäla måltider och sköta familjens livliga handel i Dun Morogh.",al={"varför är ragnar i kharanos","ragnar thunderbrews plats och motiv","vad gör ragnar i kharanos"}},["6804fc69"]={q="Varför är Ragnar Thunderbrew berömd?",a="Ragnar är känd för att bevara familjens hemliga recept på Beer Basted Boar Ribs, en av Dun Moroghs mest berömda och uppskattade dvärgtraditioner inom matlagning.",al={"vad är ragnar berömd för","ragnar thunderbrews berömmelse","varför är thunderbrew berömd"}}},fp="18,202,32.449.0,22.503.0,26.145.0,36.189.0,47.188.0,36.101.0"}
P.entries["npc:rahauro"] = {n="Rahauro",s="Rahauro är en tauren som tjänar Magatha Grimtotem på Elder Rise i Thunder Bluff. På hennes uppdrag rekryterar han modiga äventyrare till Ragefire Chasm under Orgrimmar. Han samordnar vedergällningen mot de fientliga troggarna och försöker återta sin härskarinnas fallna agenters försvunna tillhörigheter.",h="Rahauro är en tauren som tjänar Magatha Grimtotem på Elder Rise i Thunder Bluff.",kw={"elder rise","grimtotem","magatha","maur","ragefire chasm","rahauro","väska","thunder bluff","troggar"},ang={["faction:Horde"]="Rahauro ger Horde-medlemmar i Thunder Bluff tidiga uppdrag i grottor och förenar taurenledarnas intressen med försvaret av orkernas huvudstad Orgrimmar.",["race:Tauren"]="För taurer som vandrar på Thunder Bluffs terrasser visar Rahauro hur långt Elder Rises inflytande sträcker sig och ger en inblick i Magathas innersta krets diskreta intriger."},sec={{t="Den äldre kröningens röst",b="Rahauro står troget nära Magatha Grimtotem på Elder Rises höga terrass och agerar som hennes direkta mellanhand. Magatha anlitar ofta betrodda underhuggare i stället för att själv ägna sig åt offentlig rekrytering. När rapporter kommer om vilda varelser som svärmar under orkernas huvudstad är det Rahauro som sköter logistiken och skickar ut Hordens legosoldater för att slå ned upproret."},{t="Problem i Ragefire Chasm",b="Troggarna som angripit de underjordiska grottorna i Ragefire Chasm tog inte väl emot diplomatiska försök. Magatha skickade först sändebud för att försöka sluta fred med de primitiva bestarna, men troggarna gick till våldsamt angrepp och slaktade dem. Rahauro ser dem som ett oacceptabelt hot mot Horden och skickar mästare ner i grottorna för att decimera troggarna och bedöma deras verkliga styrka."},{t="Det fallna sändebudets väska",b="Bland troggarnas offer fanns Maur Grimtotem, en av Magathas betrodda tjänare. Före sin död i de brinnande djupen hade Maur upptäckt något som väckte hans intresse och som han desperat ville visa sin härskarinna. Rahauro ber upptäcktsresande genomsöka de vulkaniska gångarna och hitta Maurs försvunna väska. Han hoppas säkra de känsliga fynd som det fallna sändebudet lämnade efter sig."}},faq={{q="Vem är Rahauro?",a="Rahauro är en tauren som finns på Elder Rise i Thunder Bluff. Han hjälper Magatha Grimtotem och skickar resenärer på uppdrag för sin härskarinna och Horden.",al={"vem är rahauro","raha uro i bakgrundshistorien","vem är den här taurenen"}},{q="Var hittar jag Rahauro?",a="Du hittar Rahauro på Elder Rise i Thunder Bluff, nära Grimtotemklanens matriark Magatha Grimtotem.",al={"raha uros plats","var finns rahauro","hitta rahauro"}},{q="Varför vill Rahauro att äventyrare beger sig till Ragefire Chasm?",a="Magatha Grimtotem försökte skicka sändebud för att förhandla med troggarna som kom fram under Orgrimmar, men bestarna dödade dem. Rahauro rekryterar äventyrare för att minska antalet troggar och få slut på hotet de utgör mot Horden.",al={"rahauro ragefire","varför skicka till ragefire","raha uros trogguppdrag"}},{q="Vem var Maur Grimtotem?",a="Maur Grimtotem var en tjänare som Magatha skickade ner i Ragefire Chasm. Han upptäckte något anmärkningsvärt i grottorna, men dödades av troggarna där innan han hann överlämna sina fynd.",al={"maur grimtotem","vem är maur","personen med den försvunna väskan"}},{q="Vad finns i väskan som Rahauro letar efter?",a="Väskan innehåller ett märkligt fynd som Maur Grimtotem gjorde före sin död. Rahauro ber äventyrare att hämta den från de troggfyllda grottorna och återföra den säkert till Thunder Bluff.",al={"innehållet i den försvunna väskan","vad finns i väskan","maurs väska"}},{q="Tillhör Rahauro Grimtotemklanen?",a="Han tjänar Magatha Grimtotem direkt på Elder Rise och sköter ärenden som rör Grimtotem-agenter som Maur. Därmed står han nära Magathas följe i Thunder Bluff.",al={"är rahauro grimtotem","raha uros stam","raha uros fraktion"}}},fx={["7ce6993c"]={q="Varför är Rahauro på Elder Rise?",a="Rahauro stannar kvar på Elder Rises höjder för att personligen ta hand om sin härskarinna, Magatha Grimtotem. Från denna utsiktspunkt i Thunder Bluff bevakar han hennes lokala intressen och rekryterar dugliga äventyrare från Horde för att hantera avlägsna faror, som det framväxande hotet från troggs djupt under Orgrimmar i Ragefire Chasm.",al={"varför är rahauro här","rahaus uppgift på elder rise","vad gör rahauro i thunder bluff"}},ba00cb60={q="Vem står Rahauro i förbindelse med?",a="Rahauro är en tjänare åt Elder Crone Magatha Grimtotem på Thunder Bluffs Elder Rise. Han sköter hennes angelägenheter, samordnar arbetet kring hennes fallna tjänare som Maur Grimtotem och företräder hennes intressen inom den större Horde genom att skicka ut förkämpar för att hantera hot mot deras gemensamma säkerhet.",al={"rahaus lojalitet","vem arbetar rahauro för","rahaus förbindelser"}}},fp="7,229,24.287.0,25.313.0,26.273.1,15.125.0,25.76.0,58.200.0,23.171.0,46.170.0,43.167.0"}
P.entries["npc:raleigh-andrean"] = {n="Raleigh Andrean",s="Raleigh Andrean är en Förfallen invånare i Undercity. Hans uppdrag visar hur likgiltig han är inför sitt tidigare människoliv och dem han en gång kände.",h="Raleigh Andrean är en Förfallen invånare i Undercity.",kw={"en makes hämnd","deliah","de förfallna","raleigh andrean","föraktets ring","trade quarter","undercity","valdred moray"},ang={["race:Undead"]="Raleighs sätt att behandla sina tidigare mänskliga band ger ett oroande exempel på hur en av de Förfallna reagerar på att bli odöd."},sec={{t="Ett bittert efterliv",b="Innan det tredje kriget ödelade Lordaeron levde Raleigh Andrean ett vanligt människoliv. Han var gift med en kvinna vid namn Deliah och umgicks med sin vän Valdred Moray. Liksom otaliga andra föll han när Scourge drog fram genom kungariket, men återuppväcktes som en viljelös träl i Lich Kings tjänst. Han återfick sin fria vilja när Ner'zhuls grepp bröts och Sylvanas Windrunner gjorde uppror. Då tog han sin plats bland de Förfallna i Undercity."},{t="Hämnd framför sorg",b="När Raleigh får se sin avlidna hustrus vigselring visar han den känslomässiga förhärdelse som följer med att vara odöd. Han känner ingen sorg eller kvarvarande kärlek till Deliah och avfärdar kallt hennes död. I stället riktar han all sin uppmärksamhet mot hämndbegär: han kräver Valdred Morays avhuggna händer. Hans före detta vän mördade Deliah. Raleigh behåller de makabra troféerna inte av kärlek till Deliah, utan som ett evigt minne av sveket. Den som hjälper honom belönas med en ring smidd av rent förakt."}},faq={{q="Var finns Raleigh Andrean?",a="Raleigh Andrean bor i det livliga Trade Quarter i Undercity, bland invånarna i den underjordiska stadens förfallna befolkning.",al={"raleigh andrean plats","var finns raleigh","hitta raleigh andrean"}},{q="Vem var Raleigh när han levde?",a="I livet var Raleigh en dödlig invånare i kungariket Lordaeron. Han var gift med en kvinna vid namn Deliah och var vän med en man vid namn Valdred Moray innan Scourge svepte fram genom riket.",al={"raleighs bakgrund","vem var raleigh","raleigh andrean bakgrund"}},{q="Varför vill Raleigh hämnas på Valdred Moray?",a="Raleigh söker hämnd på någon från sitt tidigare liv. Vigselringen som lämnas till honom leder vidare till detaljerna kring oförrätten.",al={"varför döda valdred","raleighs hustru","valdred morays mord"}},{q="Hur blev Raleigh fri från Scourge?",a="Raleigh dödades och gjordes till en tjänare åt Scourge under det tredje kriget. När Lich Kings kontroll försvagades efter attackerna mot Frozen Throne ledde Sylvanas Windrunner ett uppror. Det befriade Raleigh och många andra, som bildade de Förfallna.",al={"hur blev raleigh en av de förfallna","raleighs frihet från scourge"}}},fx={["1c49ed7c"]={q="Vem är Raleigh Andrean?",a="Raleigh Andrean är en Forsaken-medborgare som bor i Trade Quarter i Undercity. I livet var han medborgare i Lordaeron, mördades under Scourge-invasionen och återuppväcktes som odöd. Efter att ha slitit sig fri från Lich Kings grepp tillsammans med Sylvanas Windrunner svor han trohet till Forsaken. Han dröjer sig kvar i huvudstaden, uppslukad av bitterhet och en kall törst efter hämnd mot dem som förrådde honom i hans tidigare liv.",al={"vem är raleigh andrean","vem är raleigh","raleigh andreans identitet"}},c1a05a30={q="På vems sida står Raleigh Andrean?",a="Raleigh är fullständigt lojal mot drottning Sylvanas Windrunner och Forsaken, och därmed även Horde. När han befriats från Scourges kontroll efter Dark Ladys uppror fann han en fristad under Lordaerons ruiner. Även om han främst är uppslukad av personliga agg står han stadigt bland sina odöda fränder i Undercity.",al={"raleigh andreans fraktion","tillhör raleigh horde","på vems sida står raleigh"}},["49f29ff4"]={q="Vad vill Raleigh Andrean?",a="Raleigh söker hämnd på sin tidigare vän, Valdred Moray. Han känner ingenting inför sin avlidna hustru Deliahs död, men en kall hämndlystnad brinner fortfarande i hans döda hjärta. Han vill att Valdred jagas upp och att hans händer förs tillbaka som en bister trofé.",al={"vad vill raleigh","raleigh andreans mål","raleigh andreans hämnd"}},["5288ca4a"]={q="Varför är Raleigh Andrean i Undercity?",a="Precis som många tidigare medborgare i Lordaeron som återfick sin fria vilja sökte Raleigh skydd i Undercity efter att ha brutit sig loss från Lich Kings herravälde. Nu dröjer han sig kvar i Trade Quarter, grubblar över gamla oförrätter och söker förbipasserande äventyrare som kan hjälpa honom att hämnas på sina levande fiender.",al={"varför är raleigh här","varför är raleigh i undercity","raleigh andrean i trade quarter"}},["396cb243"]={q="Vem står Raleigh Andrean i förbindelse med?",a="I livet var Raleigh gift med en kvinna vid namn Deliah och nära vän med Valdred Moray. Den vänskapen har sedan dess förvandlats till ett bittert, orubbligt hat som sträcker sig bortom själva döden.",al={"raleigh andreans hustru","raleigh andreans förbindelser","raleigh, valdred och deliah"}}},fp="15,145,18.405.0,20.423.1,33.80.0,34.136.0,47.122.1,45.211.0"}
P.entries["npc:randis"] = {n="Randis",s="På Cathedral Square väntar Randis på en chans att se världen bortom Stormwind. Under Children's Week följer han ivrigt med äventyrslystna äventyrare genom Alliance-länderna.",h="På Cathedral Square väntar Randis på en chans att se världen bortom Stormwind.",kw={"cathedral square","children's week","människobarn","matron nightingale","randis","stormwind"},ang={["faction:Alliance"]="Som Alliance-mästare blir du påmind när du tar hand om Randis under Children's Week om att dina strider skyddar nästa generation civila och drömmare."},sec={{t="Ett av Stormwinds föräldralösa barn",b="Randis bor på barnhemmet nära Stormwinds Cathedral of Light, ett av många barn som lämnats utan familj av rikets konflikter. Varje år när Children's Week kommer ger Orphan Matron Nightingale medkännande hjältar en visselpipa och anförtror dem ansvaret för honom. Randis är nyfiken och full av frågor, drömmer om äventyr, ställer gåtor och säger att han vill bli kung av Stormwind när han blir stor."},{t="Blicken mot världen",b="För Randis, som tillbringar de flesta dagarna på Cathedral Square, är det ett stort äventyr att lämna huvudstaden. Han säger att platser som Ironforge luktar konstigt, och hans förundran visar vad Alliance-hjältar kämpar för att skydda."}},faq={{q="Vem är Randis?",a="Randis är ett människobarn som bor på Stormwind Orphanage i Cathedral Square. Under Children's Week kan äventyrslystna äventyrare ta hand om honom och ta med honom genom Alliance-länderna.",al={"randis npc","vem är det människobarnet","människobarn stormwind"}},{q="Hur träffar du Randis?",a="Under Children's Week ger Orphan Matron Nightingale äventyrare en föräldralösvisselpipa i Cathedral Square. Blås i den, så följer Randis med på dina resor.",al={"hur får man randis","kalla på randis","barnhemsvisselpipa stormwind"}},{q="Vilka platser vill Randis besöka?",a="Randis vill besöka allt bortom Stormwinds murar tillsammans med hjälten som tar med honom. Han har besökt Ironforge och säger att det luktar konstigt där.",al={"randis platser","randis sevärdheter","platser för människobarn under children's week"}},{q="Varför bor Randis på ett barnhem?",a="Randis förlorade sina föräldrar i de ständiga krig, invasioner och svårigheter som drabbat Stormwind och Azeroths vidsträckta länder. Många barn som står under Matron Nightingales omsorg har upplevt samma förlust.",al={"randis föräldrar","varför är randis föräldralös","stormwind barnhem lore"}}},fx={["5920bd8f"]={q="På vems sida står Randis?",a="Randis är en ung människopojke som vuxit upp i Stormwind City, och hans lojalitet ligger helt hos Alliance. Han har tillbringat sin barndom under stadens barnhems omsorg, ser upp till Alliance stora hjältar och ledare och drömmer till och med om att en dag bli kung av Stormwind.",al={"randis och alliance","tillhör randis alliance","randis fraktion"}},ece316b6={q="Varför är Randis i Stormwind?",a="Randis bor i Stormwind City eftersom han är föräldralös och står under Orphan Matron Nightingales omsorg på det lokala barnhemmet i Cathedral Square. Under det årliga firandet av Children's Week väntar han ivrigt på resande äventyrare som svarar på föreståndarinnans uppmaning att ta med honom ut ur staden och visa honom den vida världens underverk.",al={"varför är randis här","varför är randis i stormwind","randis plats i stormwind"}},["33179f48"]={q="Vem står Randis i förbindelse med?",a="Randis tas om hand av Orphan Matron Nightingale, som har ansvar för de mänskliga föräldralösa barnen i Stormwinds Cathedral Square. Under Children's Week förlitar han sig på omtänksamma äventyrare från Alliance som tar med honom på resor utanför stadsmurarna.",al={"vem tar hand om randis","randis förbindelser","vem är randis knuten till"}}},fp="6,159,19.395.0,17.202.0,14.170.0,23.155.0,38.147.0,37.189.0"}
P.entries["npc:ranger-glynda-nal-shea"] = {n="Ranger Glynda Nal'Shea",s="Sentinel Glynda Nal'Shea är en erfaren nattalvsvakt i kuststaden Auberdine. Från sin post nära stadsvakten leder hon det lokala försvaret i Darkshore, skickar resenärer för att undanröja hot som lurar och undersöka märkliga fenomen längs kusten.",h="Sentinel Glynda Nal'Shea är en erfaren nattalvsvakt i kuststaden Auberdine.",kw={"auberdine","darkshore","glynda","murkdeep","nal'shea","night elf","ranger","röd kristall","sentinel"},ang={["class:Hunter"]="Andra skogvaktare och spårare känner igen sig i Glyndas skarpa instinkter och raka sätt att undanröja vilda bestar och rovdjur längs stranden.",["faction:Alliance"]="Glynda ger alliansresenärer som anländer med båt från Teldrassil eller Eastern Kingdoms viktiga efterlysningar för att säkra Darkshores gränser.",["race:NightElf"]="För nattalver står Glynda Nal'Shea för den ständiga vaksamhet som krävs för att skydda Kalimdors heliga stränder från aggressiva bestar och uråldrigt fördärv."},sec={{t="Auberdines väktare",b="Medan Darkshore kämpar mot tilltagande fördärv och fientliga intrång samordnar Sentinel Glynda Nal'Shea viktigt spaningsarbete från Auberdine. Hon håller uppsikt över vildmarken runtomkring och förlitar sig på dugliga äventyrare för att bevaka gränsen och skydda nattalvernas besittningar längs den dimhöljda kusten."},{t="Hot längs kusten",b="Glynda riktar särskilt sin uppmärksamhet mot farorna som växer och tränger in mot stränderna, framför allt de allt djärvare murlocerna som samlas söder om staden. Hon övervakar efterlysningar på ökända hot som Murkdeep och ger spejare i uppdrag att undersöka märkliga föremål, däribland en mystisk karmosinröd kristall som rapporterats vid Darkshores östra bergskedja."}},faq={{q="Vem är Ranger Glynda Nal'Shea?",a="Hon är en nattalvssentinell i Auberdine som organiserar spaningspatruller och försvarsuppdrag i Darkshore.",al={"glynda nal'shea","vem är glynda","ranger glynda"}},{q="Var finns Glynda Nal'Shea?",a="Hon finns i Auberdine, den främsta alliansbosättningen i Darkshore, vanligtvis nära sentinellernas vaktpost och stadens ingångar.",al={"glyndas plats","var är glynda","var hittar man glynda"}},{q="Vilka uppdrag erbjuder Ranger Glynda Nal'Shea?",a="Hon erbjuder uppdrag som rör faror i regionen, däribland efterlysningar som WANTED: Murkdeep! och undersökningar av den mystiska röda kristallen längs klipporna i Darkshore.",al={"glyndas uppdrag","vad ger glynda"}},{q="Varför oroar sig Glynda för Murkdeep?",a="Murkdeep är en våldsam murloc-hövding som ligger bakom angrepp på nattalvernas utposter och resenärer längs sydkusten, och utgör ett ständigt hot mot Auberdines säkerhet.",al={"vem är murkdeep","varför döda murkdeep"}},{q="Vad är uppdragskedjan Red Crystal?",a="Det är en serie spaningsuppdrag som Glynda inleder och där äventyrare ska klättra uppför Darkshores östra klippor för att undersöka en märklig, pulserande kristall och hämta fragment för studier.",al={"röd kristall darkshore","uppdraget red crystal"}},{q="Vilken fraktion tjänar Glynda Nal'Shea?",a="Hon tjänar nattalverna i Darnassus och är befälhavare för en militär utpost åt Alliansen i Darkshore.",al={"glyndas fraktion","vem arbetar glynda för"}}},fx={["83e5dc60"]={q="Varför är Ranger Glynda Nal'Shea här i Darkshore?",a="Sentinel Glynda Nal'Shea är stationerad i Auberdine och hjälper till att försvara Darkshore mot de otaliga faror som hotar nattalvernas bosättning. Mellan murlocs som tränger fram längs kusten och märkliga reliker som den röda kristallen på klipporna håller hon uppsikt över lokala hot och skickar dugliga äventyrare för att undanröja dem innan Auberdine överväldigas.",al={"varför är glynda här","ranger glyndas uppgift i darkshore","varför är glynda i auberdine"}},["0a51f57f"]={q="Vad vill Ranger Glynda Nal'Shea att du ska göra?",a="Glynda vill trygga Darkshore och reda ut de onaturliga störningar som plågar regionen. Hon ber dig hjälpa till att jaga farliga hot som den ökända murlocen Murkdeep och undersöka mystiska reliker som den stora röda kristallen på bergssidan.",al={"vad vill glynda","glynda nal'sheas uppgifter","ranger glyndas mål"}}},fp="22,189,21.262.0,23.269.0,30.128.0,35.124.0,46.141.0,39.142.0,35.165.0,40.107.0"}
P.entries["npc:rau-cliffrunner"] = {n="Rau Cliffrunner",s="Rau Cliffrunner är en tauren-spejare och lärd som är stationerad högt uppe på Freewind Post i Thousand Needles. Han har vigt sig åt att skydda sitt folk från hot i regionen och studerar de fientliga Galak-centaurernas historia och ursprung genom deras forntida reliker. Tillsammans med sina bundsförvanter i Thunder Bluff samordnar Rau expeditioner in i farliga fiendefästen på andra sidan ravinen.",h="Rau Cliffrunner är en tauren-spejare och lärd som är stationerad högt uppe på Freewind Post i Thousand...",kw={"cloven hoof","freewind post","galak","rau cliffrunner","helig låga","splithoof crag","splithoof hold","thousand needles","zangen stonehoof"},ang={["faction:Horde"]="Raus insatser bidrar till att säkra Freewind Post, ett isolerat Horde-fäste som är avgörande för att upprätthålla försörjningslinjerna mellan The Barrens och Tanaris.",["race:Tauren"]="För taurerna handlar förståelsen av centaurerna om kulturell överlevnad. Raus studier av centaurernas ursprung söker insikt i den förfäderskonflikt som nästan drev Shu'halo till utrotning."},sec={{t="Ravinklyftornas väktare",b="Rau Cliffrunner håller vakt från de farliga klipporna vid Freewind Post och blickar ut över Thousand Needles vidsträckta, solstekta landskap. Taurernas utpost är en viktig tillflykt för Horden i ett annars fientligt område, fullt av vildsinta rovdjur, quilboar och aggressiva centaurstammar. Rau organiserar utposten och bedriver noggranna undersökningar, fast besluten att hejda nya hot innan de kan övermanna de utsatta bosättningarna på platåerna."},{t="Galakfolkets hemligheter",b="Raus främsta intresse är centaurernas forntida ursprung, eftersom de har fört ett brutalt krig mot taurerna i generationer. När han upptäckte att den lokala Galak-stammen vaktade en helig relik från deras folks gryning sökte Rau ett sätt att kringgå relikens mystiska skydd. I samarbete med Zangen Stonehoof i Thunder Bluff fick Rau heligt månkällvatten från Ashenvale för att släcka den eviga lågan vid Splithoof Hold. Då kunde äventyrare hämta den gåtfulla Cloven Hoof åt honom för hans studier."}},faq={{q="Var hittar jag Rau Cliffrunner?",a="Rau Cliffrunner finns högst upp på Freewind Post, den framträdande utposten på en platå mitt i Thousand Needles.",al={"rau cliffrunner plats","var är rau","var är rau cliffrunner"}},{q="Vad undersöker Rau Cliffrunner?",a="Rau undersöker centaurernas ursprung och mystiska traditioner. Han söker Cloven Hoof, en forntida stamrelik som Galak-centaurerna håller i Splithoof Crag. Han hoppas att dess märkliga krafter ska kasta ljus över taურernas historiska fiender.",al={"rau cliffrunners syfte","vad vill rau","varför vill rau ha hoven"}},{q="Varför behöver Rau månkällvatten?",a="Galak-centaurerna förvarar sin forntida relik bakom en evig, mystisk eld. Rau fick veta att rent vatten från en nattalvs månkällbrunn i Ashenvale har den heliga kraft som krävs för att släcka eldfatets låga och bryta igenom dess skydd.",al={"rau månkällvatten","helig låga månkällvatten","varför månkällvatten"}},{q="Vem samarbetar med Rau Cliffrunner i Thunder Bluff?",a="Zangen Stonehoof, som är stationerad på High Rise i Thunder Bluff, arbetar direkt med Rau. Zangen samordnar hämtningen av månkällvattnet från Ashenvale och skickar sedan betrodda Horde-resenärer till Rau på Freewind Post.",al={"raus bundsförvant","zangen och rau","vem skickade mig till rau"}},{q="Vad är Cloven Hoof?",a="Cloven Hoof är en uråldrig centaurartefakt som Galak-stammen bevarar i Splithoof Hold. Den härrör från centaurernas skapelse och utstrålar en ovanlig energi som Rau tänker tyda.",al={"cloven hoof-relik","vad är hoven","centaurrelik thousand needles"}},{q="Tillhör Rau Cliffrunner en särskild taurenstam?",a="Ingen särskild stam anges för Rau. Han är en taurenkrigare från Thunder Bluff, stationerad på Freewind Post, och inget knyter hans efternamn till någon namngiven stam.",al={"rau cliffrunner stam","vilken stam tillhör rau"}}},fx={c4ebc959={q="Vem är Rau Cliffrunner?",a="Rau Cliffrunner är en taurenlärd och spejare stationerad vid Freewind Post, högt ovanför botten av Thousand Needles kanjon. Han är djupt engagerad i att reda ut de lokala Galak-centaurernas historia och arbetar tillsammans med andra forskare i Thunder Bluff för att återfinna och studera forntida föremål med koppling till centaurstammarnas ursprung i Kalimdor.",al={"vem är rau cliffrunner","rau cliffrunners bakgrund"}},dfeb320c={q="På vems sida står Rau Cliffrunner?",a="Rau står stadigt på taurenfolkets och Hordes sida i Thunder Bluff. Han är stationerad vid Freewind Post och samordnar arbetet med resande från Horde för att skydda platån och säkra reliker som kan avslöja viktig kunskap om Hordes bittra fiender, centaurerna.",al={"rau cliffrunners fraktion","tillhör rau horde","rau cliffrunners lojalitet"}},["3af393e1"]={q="Vad vill Rau Cliffrunner?",a="Rau vill låsa upp hemligheterna bakom en forntida centaurrelik som kallas Cloven Hoof, bevarad sedan rasens skapelse. För att få tag på den behöver han vatten från en månkällare för att släcka den heliga låga som vaktar den i Splithoof Hold. Han hoppas att dess märkliga energier ska ge djup insikt i centaurernas historia.",al={"rau cliffrunners mål","vad vill rau","raus motiv"}},["66929801"]={q="Varför är Rau Cliffrunner vid Freewind Post?",a="Freewind Post är Hordes främsta fäste i Thousand Needles. Det reser sig direkt ovanför kanjonen och ligger intill Galak-centaurernas bosättningar. Rau stannar här för att övervaka undersökningarna av Splithoof Crag och tyda mysterierna kring de forntida reliker som göms i klipporna.",al={"varför är rau cliffrunner här","varför är rau i thousand needles","varför är rau vid freewind post"}}},fp="15,375,22.478.0,20.529.1,33.113.0,38.254.0,33.239.0,53.223.0,24.201.0,55.153.0"}
P.entries["npc:razzle-sprysprocket"] = {n="Razzle Sprysprocket",s="Razzle Sprysprocket är en gnomisk ingenjör som bor i Kharanos i Dun Morogh. Han är känd för sitt tekniska pillande tillsammans med Ozzie Togglevolt och ber resenärer hjälpa till att bärga skadade gnomiska maskiner och delar bland de snötäckta kullarna.",h="Razzle Sprysprocket är en gnomisk ingenjör som bor i Kharanos i Dun Morogh.",kw={"dun morogh","ingenjör","kharanos","ozzie togglevolt","razzle","recombobulation","sprysprocket"},ang={["profession:Engineering"]="Ingenjörer känner igen en själsfrände i Razzle, vars projekt visar hur hårfin gränsen är mellan lysande gnomiska uppfinningar och explosiva felbedömningar.",["race:Gnome"]="För landsförvisade gnomer på genomresa i Dun Morogh står Razzle för den okuvliga uppfinningsrikedomen och beslutsamheten att bygga upp allt igen och återfinna det som gått förlorat efter Gnomeregans fall."},sec={{t="Mekande i Kharanos",b="Efter tragedin i Gnomeregan fann Razzle Sprysprocket en fristad bland snödrivorna i Dun Morogh och inrättade sin verkstad i Kharanos. Razzle är skicklig på ömtåliga mekaniska delar och arbetar tillsammans med ingenjörskollegan Ozzie Togglevolt. Deras arbete går ofta ut på att återfinna gyromekanismer och kugghjulssamlingar som försvann eller plockades isär under flykten från deras bestrålade hemland."},{t="Verkstaden måste försvaras",b="Livet i Dun Morogh är långt ifrån fridfullt för en gnomisk uppfinnare. Mellan de vilda djuren på de frusna bergsryggarna och räder från de lokala Frostmane-trollen är Razzles arbete aldrig helt tryggt. Trots farorna är han fast besluten att hålla gnomiska uppfinningar i funktionsdugligt skick och återfinna Gnomeregans förlorade underverk."}},faq={{q="Vem är Razzle Sprysprocket?",a="Razzle Sprysprocket är en excentrisk gnomisk uppfinnare som håller till i Kharanos i Dun Morogh och arbetar tillsammans med Ozzie Togglevolt.",al={"razzle sprysprocket","vem är razzle","razzle kharanos"}},{q="Vad behöver Razzle Sprysprocket hjälp med?",a="Razzle behöver ofta äventyrare som ger sig ut i Dun Morogh för att samla in borttappade mojänger, kugghjulssamlingar och delar som behövs för att få gnomiska ingenjörsprojekt att fungera igen.",al={"razzle uppdrag","hjälp med operation recombobulation","vad vill razzle"}},{q="Var hittar jag Razzle Sprysprocket?",a="Han arbetar utomhus nära tinkerns post i Kharanos, strax utanför värdshuset och smedjan i centrala Dun Morogh.",al={"razzles plats","var finns razzle","razzle sprysprocket karta"}},{q="Är Razzle Sprysprocket släkt med andra Sprysprockets?",a="Ingen av Razzles släktingar nämns vid namn. Han har samma efternamn som Rizzle Sprysprocket, men de är tydligen inte släkt.",al={"sprysprocket-familjen","razzles släktingar"}}},fx={b527298b={q="På vems sida står Razzle Sprysprocket?",a="Razzle Sprysprocket står på Gnomeregan Exiles och Alliances sida. Han är stationerad i Kharanos tillsammans med sina andra flyktingar och arbetar nära andra gnomiska uppfinnare som Ozzie Togglevolt för att hjälpa sitt fördrivna folk i Dun Morogh.",al={"razzle sprysprockets fraktion","tillhör razzle alliance","razzle sprysprockets lojalitet"}},fcfe3829={q="Varför är Razzle Sprysprocket i Kharanos?",a="Precis som många andra gnomer sökte Razzle Sprysprocket skydd i Kharanos efter Gnomeregans tragiska fall. Han har öppnat en verkstad i den snöiga staden, fortsätter med sina uppfinningar och söker material som kan stödja gnomernas pågående återhämtning.",al={"varför är razzle här","varför är razzle sprysprocket i kharanos","vad förde razzle till kharanos"}}},fp="19,172,21.298.0,23.228.0,27.80.0,45.120.0,37.111.0,54.111.0"}
P.entries["npc:red-jack-flint"] = {n="Red Jack Flint",s="Red Jack Flint är en erfaren mänsklig sjöfarare stationerad i Menethil Keep i Menethil Harbor. Han tillhör besättningen på fartyget Maiden's Virtue och hjälper resenärer som söker en överfart eller kontakter över havet mot Kalimdor.",h="Red Jack Flint är en erfaren mänsklig sjöfarare stationerad i Menethil Keep i Menethil Harbor.",kw={"fiora longears","maidens virtue","menethil harbor","menethil keep","red jack flint","wetlands"},ang={["faction:Alliance"]="För alliansresenärer som lägger kurs över havet från Khaz Modan är sjömän som Red Jack Flint en viktig länk till utposterna längs Kalimdors norra kust."},sec={{t="En sjöman i Menethil Keep",b="Inne bakom Menethil Keeps stenmurar finns Red Jack Flint, en erfaren sjöfarare med anknytning till hamnens sjöfartshandel. Som en del av besättningen på Maiden's Virtue färdas han längs de farliga sjölederna mellan Khaz Modans träskmarker och avlägsna stränder. Flint håller sig inte till sjömanslivets rutiner, utan visar skickliga äventyrare vägen till allierade på andra sidan Stora havet, bland annat kontakter i Kalimdor som Fiora Longears."}},faq={{q="Vem är Red Jack Flint?",a="Red Jack Flint är en mänsklig sjöman och medlem av besättningen på Maiden's Virtue. Han är stationerad i Menethil Keep i Menethil Harbor och förmedlar kontakter mellan Eastern Kingdoms och Kalimdor.",al={"vem är flint","red jack flints bakgrund","vad gör flint"}},{q="Var hittar man Red Jack Flint?",a="Du hittar honom inne i Menethil Keep, den främsta stenfästningen som försvarar Menethil Harbor i Wetlands.",al={"red jack flints plats","var är flint","hitta red jack flint"}},{q="Vilket skepp seglar Red Jack Flint på?",a="Han tjänstgör ombord på Maiden's Virtue, ett handelsfartyg som utgår från Menethil Harbor.",al={"flints skepp","vilket skepp är red jack på","maidens virtue"}},{q="Vem skickar Red Jack Flint resenärer till?",a="Han hänvisar resenärer till Fiora Longears, sin partner på andra sidan havet i hamnstaden Theramore.",al={"flints uppdrag","fiora longears koppling","vart skickar flint dig"}}},fx={["1faeb3cc"]={q="På vems sida står Red Jack Flint?",a="Red Jack Flint står på Alliances sida. Han är stationerad bland vakterna och sjömännen i Menethil Harbor och erbjuder vägledning och kontakter åt resande från Alliance mellan Eastern Kingdoms och Kalimdors kuster.",al={"red jack flints fraktion","tillhör red jack flint alliance","red jack flints lojalitet"}}},fp="14,218,25.250.0,22.182.0,34.111.0,38.97.0,46.104.0"}
P.entries["npc:rejold-barleybrew"] = {n="Rejold Barleybrew",s="Rejold Barleybrew är en mästerbryggare bland dvärgarna, stationerad i sjöbosättningen Brewnall Village i västra Dun Morogh. Han ägnar sig åt att fullända mustiga bergsspritsorter och anlitar regelbundet resenärer för att samla regionala ingredienser och prova hans kraftfulla recept i den snöiga dalen.",h="Rejold Barleybrew är en mästerbryggare bland dvärgarna, stationerad i sjöbosättningen Brewnall Village i...",kw={"öl","barleybrew","bryggare","brewnall","dun morogh","rejold","shimmer stout","porter"},ang={["faction:Alliance"]="Rejolds förråd av porter hjälper till att hålla Alliansens mod uppe i Dun Morogh och stärker vakter och resenärer som trotsar trogganfall och hårda snöstormar.",["profession:Cooking"]="Matlagningsintresserade äventyrare uppskattar Rejolds jakt på förstklassiga ingredienser och precisa recept. För honom är bryggningen en exakt och vördnadsvärd konst.",["race:Dwarf"]="För dvärgar står Rejold för den stolta bergstraditionen att brygga starkt öl som ger värme och styrka mot Khaz Modans bittra vinterkyla."},sec={{t="En mästare i sitt hantverk",b="I Dun Morogh ses bryggning inte bara som ett yrke, utan som en konstform som definierar dvärgarna. Rejold Barleybrew förkroppsligar traditionen i Brewnall Village, en utpost nära den frusna sjön vid Iceflow River. I stället för att nöja sig med vanligt värdshusöl förfinar Rejold ständigt sina blandningar och söker efter sällsynt humle, mineraler från bergen och rent isvatten. Målet är att brygga porter som kan värma även de tåligaste dvärgkrigarna."},{t="Jakten på den perfekta portern",b="Rejold ger sig inte i jakten på den perfekta smaken. Han skickar äventyrslystna resenärer genom Dun Morogh för att samla viktiga ingredienser till drycker som Shimmer Stout. Han byter tjänster med belägringspiloterna vid Steelgrill's Depot och ordnar leveranser till törstiga kunder. Tack vare hans arbete blir de kalla, troggdrabbade vägarna i Dun Morogh lättare att uthärda med ett stadigt förråd av mustigt öl."}},faq={{q="Vem är Rejold Barleybrew?",a="Rejold Barleybrew är en dvärgbryggmästare som bor i Brewnall Village i Dun Morogh. Han ägnar sig åt att skapa legendariskt dvärgär och ber äventyrare på genomresa att hämta ingredienser och leverera experimentbrygder.",al={"rejold","vem är rejold","rejold barleybrew information"}},{q="Var hittar man Rejold Barleybrew?",a="Rejold finns i Brewnall Village, i västra Dun Morogh, intill Iceflow Basins frusna vatten.",al={"rejolds plats","var finns rejold barleybrew","rejold barleybrew brewnall"}},{q="Vad arbetar Rejold med?",a="Rejold arbetar med att fullända kraftfulla bergsrecept, däribland sin signaturdryck Shimmer Stout och nya experimentella ölsorter. Till dem behöver han köldhärdiga bergsväxter och särskilda bryggingredienser som finns bland de snöiga kullarna.",al={"rejold uppdrag","uppdrag om perfekt porter","vad brygger rejold"}},{q="Varför skickar Rejold resenärer till gnomer?",a="Hans ärenden för honom egentligen till andra dvärgar, inte till gnomer: Pilot Bellowfiz vid Steelgrill's Depot skickar resenärer till Rejold för att hämta en sats Evershine, och Rejolds Shimmer Stout går vidare till hans bror, Mountaineer Barleybrew.",al={"rejold gnomer","rejold evershine","bellowfiz rejold"}},{q="Vad är Shimmer Stout?",a="Shimmer Stout är en välkänd, kraftfull dvärgadrink som bryggs av Rejold Barleybrew. Den görs med unika ingredienser från bergen som ger den en särskild styrka i vinterns iskalla klimat.",al={"vad är shimmer stout","shimmer stout historia"}}},fx={["86e90b5e"]={q="På vems sida står Rejold Barleybrew?",a="Rejold är en stolt dvärg från Ironforge som helhjärtat står på Alliansens sida. Liksom många av sina fränder i Dun Morogh ägnar han dagarna åt att förfina dvärgarnas hantverk och betjäna resande som passerar genom Brewnall Village. Han håller god kontakt med andra dvärgar, som Pilot Bellowfiz från Steelgrill's Depot.",al={"rejolds fraktion","rejold alliansen eller horden","är rejold barleybrew med i alliansen"}},ede674a2={q="Varför är Rejold Barleybrew här i Brewnall Village?",a="Rejold är stationerad i Brewnall Village och ägnar sig åt sin livs passion: att brygga de finaste ölen i Khaz Modan. Brewnall Village ger honom tillgång till friskt bergsvatten och lokala ingredienser till hans ambitiösa brygder.",al={"varför är rejold här","varför är rejold i brewnall village","vad förde rejold till brewnall"}}},fp="17,158,21.287.0,32.302.0,25.167.0,37.120.0,26.179.0,41.212.0,22.148.0"}
P.entries["npc:rema-schneider"] = {n="Rema Schneider",s="I Stormwind City arbetar Rema Schneider i Canal Tailor and Fit Shop. Hon är en mänsklig invånare som ofta hjälper lokala butiksägare och hantverkare med handelsleveranser.",h="I Stormwind City arbetar Rema Schneider i Canal Tailor and Fit Shop.",kw={"canal tailor","harlan behöver nya varor","paket till thurman","rema schneider","stormwinds kanaler"},ang={["faction:Alliance"]="Som resenär eller ny rekryt i Stormwind kan du utföra enkla budärenden åt Rema medan du lär känna huvudstaden.",["profession:Tailoring"]="Rema arbetar i Canal Tailor and Fit Shop, en vanlig del av Stormwinds tygindustri."},sec={{t="Kanalernas butiksägare",b="Rema Schneider sköter den dagliga handeln från Canal Tailor and Fit Shop. Butiken ligger strax väster om stenbron till Cathedral Square, längs Stormwinds kanaler. Tyg och färdigsydda kläder transporteras mellan lokala hantverkare, och Rema förlitar sig på hjälpsamma bud som bär förnödenheter mellan verkstäderna."}},faq={{q="Var finns Rema Schneider?",a="Rema Schneider arbetar i Canal Tailor and Fit Shop i Stormwind City. Den ligger längs kanalerna, strax väster om bron till Cathedral Square.",al={"rema schneiders plats","var finns rema","hitta rema schneider"}},{q="Vilken roll har Rema i Stormwind?",a="Rema samordnar lokala ärenden inom handeln, paket med förnödenheter och beställningar av nya varor mellan stadens köpmän och hantverkare.",al={"vem är rema schneider","vad gör rema","remas uppgift"}},{q="Lär Rema ut skrädderi?",a="Nej. Rema arbetar i Canal Tailor and Fit Shop och hanterar leveranser av skrädderivaror, men hon är varken yrkesinstruktör eller huvudsaklig försäljare.",al={"är rema skrädderiinstruktör","rema skrädderiutbildning"}}},fx={["080a82f0"]={q="Vem är Rema Schneider?",a="Rema Schneider är en mänsklig invånare och skräddare i Stormwind City. Du hittar henne när hon sköter sina ärenden i Canal Tailor and Fit Shop, längs kanalerna strax väster om bron mot Cathedral Square.",al={"vem är rema schneider","rema schneiders identitet","rema schneider"}},["37d985b5"]={q="På vems sida står Rema Schneider?",a="Rema Schneider är en lojal undersåte i kungariket Stormwind och står helhjärtat på Grand Alliances sida. Hon bedriver sin skräddarverksamhet i huvudstaden och hjälper kurirer och köpmän runt om i kungariket.",al={"rema schneiders fraktion","är rema schneider med i alliansen","rema schneiders lojalitet"}},c7f62ca5={q="Vad vill Rema Schneider?",a="Rema fokuserar på att driva sin skräddarverksamhet och upprätthålla handelskontakter i hela riket. Hon förlitar sig på förbipasserande kurirer och äventyrare som kan bära paket och fylla på förråden hos lokala hantverkare som behöver hennes material.",al={"vad vill rema","rema schneiders mål","rema schneiders uppdrag"}},d4111a95={q="Varför är Rema Schneider här?",a="Rema arbetar som bofast skräddare på Canal Tailor and Fit Shop. Kanalerna är en livlig handelsled mellan Stormwinds distrikt, vilket gör platsen idealisk för att hantera hennes varor och leveranser.",al={"varför är rema i stormwind","varför är rema schneider här","rema schneider canal tailor"}}},fp="14,169,24.299.0,32.149.0,38.127.0,26.146.0"}
P.entries["npc:remulos"] = {n="Remulos",s="Väktaren Remulos är en halvgudason till Cenarius och Moonglades vördnadsvärde beskyddare. Tillsammans med ärkedruiden Fandral Staghelm och Hamuul Runetotem hjälper han till att vägleda Cenarion Circle när hans fallne far och den sovande Malfurion Stormrage saknas. Till skillnad från Staghelm sätter Remulos naturens övergripande balans framför nattalvernas isolationism.",h="Väktaren Remulos är en halvgudason till Cenarius och Moonglades vördnadsvärde beskyddare.",kw={"cenarion circle","cenarius","fandral staghelm","lund","hamuul runetotem","moonglade","remulos","zaetar"},ang={["class:Druid"]="Alla druider, vare sig de är nattalver eller taurener, reser till Moonglade för att samtala med väktaren Remulos och få vägledning i att bemästra djurformer och heliga prövningar.",["race:Tauren"]="Taurendruider vördar Remulos för att han trotsade Fandral Staghelm och gav deras folk tillträde till Cenarion Circle och fullständig undervisning där."},sec={{t="Den heliga lundens herre",b="Väktaren Remulos är en odödlig lundväktare med en stor hjorts underkropp och en forntida dryadfaders behornade överkropp. Han vakar över Moonglade, Azeroths heliga fristad för druider, belägen norr om Mount Hyjal. Medan Malfurion Stormrage fortfarande är fångad i The Emerald Dream ger Remulos gudomlig auktoritet och råd till Cenarion Circles dödliga medlemmar. Han är djupt engagerad i att läka Azeroths ärr och hjälper druider som utför sina heliga riter kring Lake Elune'ara."},{t="En spricka i kretsen",b="Remulos hamnar ofta i ideologisk konflikt med ärkedruiden Fandral Staghelm. Staghelm förespråkar nattalvernas överhöghet och försökte återställa deras förlorade odödlighet genom Teldrassil, medan Remulos kraftfullt motsatte sig planteringen av det nya världsträdet, som en handling av hybris. I trots mot Staghelms isolationistiska falang välkomnade Remulos Hamuul Runetotem och taurenerna till Cenarion Circle och delade naturens noggrant bevarade hemligheter med deras schamaner, som blivit druider, för att återställa landet tillsammans."}},faq={{q="Vem är väktaren Remulos?",a="Han är en odödlig son till Cenarius och bror till den fallne Zaetar. Remulos bor i Shrine of Remulos i Moonglade och tjänar som lundens väktare och en senior ledare för Cenarion Circle.",al={"remulos bakgrund","vem är remulos","väktaren remulos bakgrund"}},{q="Varför stöder Remulos taurendruiderna?",a="Remulos anser att naturens balans överskrider dödligas rasmotsättningar. Eftersom han erkänner taurenfolkets djupa band till Jordmodern åsidosatte Remulos ärkedruiden Fandral Staghelms invändningar och välkomnade ärkedruiden Hamuul Runetotem och hans folk till Cenarion Circle.",al={"remulos tauren","varför har taurener druider","remulos hamuul"}},{q="Vad tycker Remulos om Teldrassil?",a="Remulos motsatte sig kraftfullt skapandet av Teldrassil. Han såg planteringen av det nya världsträdet som ett själviskt försök av nattalverna att återta sin förlorade odödlighet, snarare än en handling för att verkligen läka Azeroth.",al={"remulos världsträd","remulos fandral träd"}},{q="Vilken koppling har Remulos till Maraudon?",a="Hans bror Zaetar begav sig till Desolace och fick barn med prinsessan Theradras. Han blev därmed kentaurernas far innan han dog. Remulos varnade Zaetar för den föreningen, och Maraudon rymmer arvet efter hans bror och kentaurerna.",al={"remulos zaetar","remulos theradras","remulos bror"}}},fp="7,351,24.516.0,20.506.0,22.203.0,43.265.0,40.231.0,44.233.1"}
P.entries["npc:remy-two-times"] = {n="Remy \"Two Times\"",s="I Goldshire handlar Remy \"Two Times\" med varor och betalar för råmaterial. Han kom från Redridge Mountains och upprepar slutet av sina meningar.",h="I Goldshire handlar Remy \"Two Times\" med varor och betalar för råmaterial.",kw={"elwynn","gold dust","goldshire","köpman","murloc","redridge","remy","two times"},ang={["faction:Alliance"]="Som rekryt i Alliansen som anländer till Goldshire kan du ta dig an Remys enkla uppdrag för att hjälpa till att röja undan lokala hot och tjäna snabba pengar.",["profession:Mining"]="Om du arbetar i Fargodeep- eller Jasperlode-gruvorna kan du träffa Remy, som köper gulddamm som samlats in från kobolder där."},sec={{t="En köpman med en märklig vana",b="Remy \"Two Times\" bedriver handel i Goldshire, där han gör affärer med resenärer. Han kom västerut från Redridge Mountains. När han talar upprepar han oftast de sista orden i varje mening två gånger. Den märkliga vanan gav honom hans smeknamn, men hindrar honom inte från att söka vinst i det oroliga Elwynn Forest."},{t="Affärer i oroliga vatten",b="Kobolder har tagit över de lokala guldgruvorna, och aggressiva murlocer hemsöker flodbankarna och stör handeln i Elwynn. Remy vänder sig till resenärer för att få hjälp. Han betalar för påsar med gulddamm som samlats in från kobolder i gruvorna och håller utkik efter misstänkta rörelser bland murlocer nära Crystal Lake."}},faq={{q="Varför kallas han \"Two Times\"?",a="Remy fick sitt smeknamn eftersom han av vana upprepar de sista orden i sina meningar två gånger när han talar.",al={"namnet remy two times","varför upprepar remy ord","betydelsen av two times"}},{q="Var kommer Remy ursprungligen ifrån?",a="Remy kom till Goldshire från Redridge Mountains för att bedriva handel i Elwynn Forest.",al={"remys ursprung","varifrån kommer remy"}},{q="Vad gör Remy med allt gulddamm han köper?",a="Remy samlar in gulddamm från kobolder i de lokala gruvorna för att smälta det, handla med det eller sälja det vidare med vinst.",al={"varför vill remy ha gulddamm","gulddamm och handel i berättelsen"}},{q="Var hittar man Remy i Goldshire?",a="Remy finns utomhus i Goldshire, nära Lion's Pride Inn, redo att köpslå med förbipasserande resenärer.",al={"var finns remy two times","remys plats i goldshire"}}},fx={["99a83a18"]={q="Vem är Remy \"Two Times\"?",a="Remy \"Two Times\" är en mänsklig köpman som har öppnat en butik i Goldshire. Han kommer ursprungligen från Redridge Mountains och är känd i Elwynn Forest för sin säregna talvana: han upprepar de sista orden i sina meningar två gånger.",al={"vem är remy","remy two times identitet","vem är remy two times"}},e326d54d={q="På vems sida står Remy \"Two Times\"?",a="Remy är lojal mot Grand Alliance och kungariket Stormwind. Han bedriver sin handel öppet i Goldshire och har fredliga relationer med de lokala myndigheterna, stadsborna och förbipasserande äventyrare.",al={"remy two times fraktion","är remy med i alliansen","vem arbetar remy för"}},["85133ed8"]={q="Vad vill Remy \"Two Times\"?",a="Som en företagsam köpman vill Remy ha lönsamma varor och trygghet i trakten. Han handlar gärna med resande som har gulddamm från närliggande gruvor och vill gärna undanröja faror som hotar handeln i Goldshire.",al={"vad vill remy","remy two times mål","varför behöver remy äventyrare"}},["7f55543c"]={q="Varför är Remy \"Two Times\" i Goldshire?",a="Remy reste från sitt hem i Redridge Mountains och slog sig ner i Goldshire för att bedriva handel. Den livliga byn vid vägkorsningen lockar gott om gruvarbetare, resande och äventyrare som vill köpa, sälja och uträtta ärenden.",al={"varför är remy i goldshire","varför lämnade remy redridge","varför är remy two times här"}}},fp="16,170,28.203.0,27.253.0,29.103.0,37.77.0,49.99.0,37.106.0"}
P.entries["npc:renato-gallina"] = {n="Renato Gallina",s="I Stormwinds Trade District ropar Renato Gallina till sig resenärer för familjens vingård.",h="I Stormwinds Trade District ropar Renato Gallina till sig resenärer för familjens vingård.",kw={"canals","gallina-vingården","renato gallina","vin från stormwind","trade district","reklam för vinbutik"},ang={["faction:Alliance"]="Som alliansresenär på väg in i huvudstaden kan du se Renato arbeta med att göra reklam för Stormwinds lokala handel och hantverk."},sec={{t="Gallina-vingårdens röst",b="Renato Gallina ropar till förbipasserande bland stånden i Trade District och utropar familjens viner till de finaste i Stormwind. Familjen Gallina driver en vingård längs Canals, och Renato gör reklam för den med flygblad. Resenärer kan ta med ett till hans syster Suzetta i butiken och få en gratis flaska vin."}},faq={{q="Vem är Renato Gallina?",a="Renato Gallina är en mänsklig utropare i Trade District i Stormwind City. Han tillhör familjen Gallina och gör reklam för deras vingård för lokalbefolkningen och besökande resenärer.",al={"renato gallina","vem är renato","vinutropare i stormwind"}},{q="Var ligger Gallina-vingården?",a="Gallina-vingården ligger längs Canals i Stormwind City, strax intill de främsta handelsdistrikten.",al={"var ligger gallina-vingården","vinbutikens läge i stormwind","gallina-vingården"}},{q="Vad ber Renato äventyrare att göra?",a="Renato ger resenärer ett flygblad för familjens vinbutik och ber dem ta med det till sin syster, Suzetta Gallina, vid vingården längs Canals. Med flygbladet får de en gratis flaska vin.",al={"renato gallina-uppdrag","reklamuppdrag för vinbutik","vad vill renato"}}},fx={fce75f2a={q="På vems sida står Renato Gallina?",a="Renato är en lojal invånare i Stormwind och medlem av Alliansen. Hans hjärta tillhör staden, handeln och framför allt framgången för familjen Gallinas kommersiella ambitioner.",al={"renato gallinas fraktion","renato gallinas lojalitet","är renato med i alliansen"}},c03f1140={q="Varför är Renato Gallina i Trade District?",a="Renato står på det livliga torget i Trade District för att skaffa kunder åt familjens vinhandel. I stället för att sitta bakom en disk tillbringar han dagarna med att göra reklam för Gallina Winery direkt till resande och stadsbor som passerar genom Stormwind.",al={"varför är renato här","renato gallina i trade district","vad gör renato här"}},["9e1708f4"]={q="Vilka band har Renato Gallina?",a="Renato är nära knuten till familjen Gallina, som äger Gallina Winery längs kanalerna i Stormwind. Hela hans vardag går åt till att marknadsföra deras årgångsviner och utöka kundkretsen i staden.",al={"renato gallinas band","renato gallinas familj","vem arbetar renato med"}}},fp="14,85,27.303.0,22.126.0,36.93.0,39.197.0"}
P.entries["npc:renee-lauer"] = {n="Innkeeper Renee",s="Innkeeper Renee driver Gallows' End Tavern i Brill och erbjuder skydd, mat och dryck åt Forsaken och Horde-resenärer på väg genom Tirisfal Glades.",h="Innkeeper Renee driver Gallows' End Tavern i Brill och erbjuder skydd, mat och dryck åt Forsaken och...",kw={"brill","gallows' end tavern","innkeeper renee","värdshusvärd renee","scarlet crusade","tirisfal glades"},ang={["race:Undead"]="Renees värdshus bevarar en av de levandes gamla bekvämligheter för Forsaken i Tirisfal: en härd, en måltid och en plats att vila på."},sec={{t="Värdshusvärd på Gallows' End",b="Renee sköter Gallows' End Tavern, värdshuset mitt i Brill. Bakom disken säljer hon mat, dryck och diverse varor, och hon välkomnar trötta nykomlingar att vila benen. Hon påpekar att Forsaken verkligen har en enorm aptit. För de odöda i Tirisfal är hennes värdshus en mysig liten plats där pestens offer försöker hitta sin plats i världen."},{t="Brev och fångar",b="Renees värdshus är ofta en nykomlings första anhalt i Brill. Calvin Montague från Deathknell skickar nya äventyrare till henne med ett obemärkt brev, ett meddelande hon ivrigt har väntat på. I källaren under golvbrädorna finns också en tillfångatagen fanatiker från Scarlet Crusade."}},faq={{q="Vem är Innkeeper Renee?",a="Innkeeper Renee är Forsaken-värdshusvärd på Gallows' End Tavern i Brill. Hon säljer mat, dryck och förnödenheter till resenärer i Tirisfal Glades.",al={"värdshusvärd renee","värdshusvärd i brill","vem är värdshusvärden i brill"}},{q="Vad har Renee för koppling till Calvin Montague?",a="I uppdraget 'A Rogue's Deal' skickas äventyrare som uträttar ärenden åt Calvin Montague för att lämna ett brev direkt till Renee på Gallows' End Tavern.",al={"a rogue's deal renee","calvin montagues brev"}}},fx={["63a8965f"]={q="På vems sida står Innkeeper Renee?",a="Renee är lojal mot Forsaken och Horden. Hon sköter Gallows' End Tavern i Brill för de odöda i Tirisfal och resande från Horden som passerar där.",al={"renee lauers fraktion","vem tjänar renee lauer","är renee med i horden"}},f2640528={q="Varför är Innkeeper Renee i Brill?",a="Renee sköter Gallows' End Tavern i Brill och erbjuder tak över huvudet, förnödenheter och en plats att vila för Forsaken och resande genom Tirisfal Glades.",al={"varför är renee lauer här","varför är renee i brill","renee lauer gallows' end"}}},fp="15,97,22.315.0,20.264.0,23.157.0,46.152.0"}
P.entries["npc:renzik-the-shiv"] = {n="Renzik \"The Shiv\"",s="Renzik \"The Shiv\" är en goblinagent och SI:7:s betrodda andreman, stationerad vid deras högkvarter i Stormwind Citys Old Town. Han tjänar spionmästaren Mathias Shaw troget och leder de nya skurkrekryter som skickas till honom från hela Alliansen.",h="Renzik \"The Shiv\" är en goblinagent och SI:7:s betrodda andreman, stationerad vid deras högkvarter i...",kw={"goblin","lucius","mathias shaw","old town","renzik","skurk","si:7","stormwind","the shiv"},ang={["class:Rogue"]="För en skurk i Alliansen är Renzik din väg från gatunivåns knivarbete in i SI:7:s högrisknätverk av underrättelseagenter. Han sållar bort de vårdslösa innan han skickar dig till Lucius i Redridge.",["faction:Alliance"]="Trots att Renzik är en goblin är han en av Stormwinds skickligaste underrättelseofficerare, näst efter Mathias Shaw inom SI:7.",["race:Human"]="Vid spionmästare Shaw i Old Town är Renzik en ovanlig goblin i kungarikets militära elit. Han visar att lojalitet och skicklighet väger tyngre än ras i skuggkrigen."},sec={{t="En goblin i SI:7",b="Renzik håller berättelsen om sitt förflutna för sig själv. I Stormwind vet man att den här goblinen hittade till SI:7 och nu är Mathias Shaws andreman. Han har ont om tålamod och artighetsfraser och hälsar nya rekryter genom att fråga om de är redo att sätta igång eller behöver ta en tupplur först."},{t="Mathias Shaws högra hand",b="Renzik är numera stationerad i SI:7:s hemlighetsfulla fästning i Old Town och tjänar som Mathias Shaws andreman. Skurkmentorer över hela Alliansen, från Ironforge till Darnassus, skickar sina mest lovande agenter till Renzik. I stället för att skicka dem rakt i döden vidarebefordrar Renzik dem till fältinstruktörer som Lucius i Redridge, så att de kan vässa sina överlevnadskunskaper."}},faq={{q="Varför arbetar en goblin för Stormwinds SI:7?",a="Renzik håller berättelsen om hur han kom till Stormwind för sig själv. Det enda man vet är att goblinen har stigit i graderna och blivit Mathias Shaws andreman i SI:7.",al={"varför är renzik med i alliansen","goblin i stormwind","varför finns det en goblin i si:7"}},{q="Varför kallas han \"The Shiv\"?",a="Renzik har aldrig berättat för Stormwind hur han fick sitt namn. I Old Town är smeknamnet allt man får veta, och för en spion kan det vara själva poängen.",al={"varför the shiv","renziks smeknamn","vad betyder renzik the shiv"}},{q="Vad gör Renzik för spelarskurkar?",a="När skurkar från Alliansen visar vad de går för skickar deras tränare dem till Renzik i Stormwind. Han tar emot SI:7:s rekryter och skickar dem vidare till specialiserade tränare som Lucius i Redridge Mountains, för att se till att de kan överleva ute på fältet.",al={"renziks skurkquest","vad ger renzik","prata med renzik the shiv"}},{q="Var brukar Renzik hålla till?",a="Han är stationerad vid SI:7:s högkvarter i Old Town i Stormwind City, dit Alliansens skurkrekryter kommer för att träffa honom.",al={"renziks plats","var hittar man renzik","var är renzik"}},{q="Har Renzik kontakter utanför Stormwind?",a="Ja. Skurktränare i Ironforge och Darnassus skickar sina lovande elever till honom, och han skickar rekryter vidare till Lucius, en SI:7-medarbetare i Lakeshire i Redridge Mountains.",al={"renziks nätverk","renziks kontakter","renziks allierade"}}},fx={["4d248edd"]={q="Vem är Renzik \"The Shiv\"?",a="Renzik \"The Shiv\" är en goblinagent och andreman i Stormwinds underrättelsetjänst SI:7, där han tjänstgör direkt under Master Mathias Shaw. Han håller sin bakgrund för sig själv. Stormwind vet att han granskar lovande skurkar som skickas till honom från hela Alliansen och skickar dem vidare till fältträning.",al={"vem är the shiv","vem är renzik the shiv","vem är renzik"}},["68226031"]={q="Vad vill Renzik \"The Shiv\"?",a="Renzik vill ha rekryter som kan arbeta och överleva. Som Mathias Shaws andreman i SI:7 bedömer han skurkarna som skickas till honom och skickar de lovande vidare till Lucius i Lakeshire för fältträning, i stället för att skicka dem i döden.",al={"renziks mål","vad vill renzik","renziks drivkraft"}},["0d7f210c"]={q="Varför är Renzik \"The Shiv\" här?",a="Renzik har sin bas i SI:7:s högkvarter i Stormwinds Old Town, men hans underrättelseuppdrag kräver fungerande kontakter med agenter i hela Alliansen, även de dunkla skurkgrupperna i Darnassus och Ironforges Hidden Circle. Han håller kontakt mellan avlägsna celler så att hemlig kommunikation och spionkonst samordnas noggrant.",al={"varför är renzik här","varför är renzik i darnassus","renziks skäl att vara i darnassus"}},["0f5f7694"]={q="Varför är Renzik \"The Shiv\" berömd eller fruktad?",a="Renzik är känd som Mathias Shaws andreman i SI:7 och som en sällsynt goblin i kungarikets tjänst. Han håller historien bakom sitt smeknamn för sig själv.",al={"varför fruktas renzik","varför är renzik berömd","renzik the shivs rykte"}}},fp="17,201,16.269.0,26.324.0,45.135.0,28.135.0,38.234.0,34.118.0,44.173.0"}
P.entries["npc:rethiel-the-greenwarden"] = {n="Rethiel the Greenwarden",s="Rethiel the Greenwarden är en gåtfull gestalt som håller till djupt inne i The Green Belt i Wetlands. Han är knuten till träskets sköra balans och ber resande ta itu med hoten som rubbar den.",h="Rethiel the Greenwarden är en gåtfull gestalt som håller till djupt inne i The Green Belt i Wetlands.",kw={"bog beast","greenwarden","mosshide","natur","rethiel","wetlands"},ang={["class:Druid"]="Rethiel är ett ovanligt uttryck för Azeroths vilda balans och talar direkt för ett sårat ekosystem, likt de uråldriga beskyddarna av Kalimdor.",["class:Shaman"]="Rethiel är lyhörd för träskets elementära och fysiska disharmoni och återspeglar landets egen nöd när det stönar under föroreningar och eld."},sec={{t="Att vårda såren",b="Rethiel vill lindra lidandet i Wetlands genom att skicka medkännande äventyrare mot träskets värsta plågoandar. Han uppmanar besökare att jaga de förödande Mosshide-gnollerna som härjar bland djurlivet, ta ifrån dem de grova flintorna som de använder för att bränna träskets levande träd och decimera de sjuka fen creepers som frodas i träskvattnen. Genom dessa utrensningar hoppas han återställa friden i den sargade jorden."},{t="Träskets väktare",b="Bland de fuktiga snåren i The Green Belt reser sig Rethiel, en väldig varelse av mossa, torv och ursprungligt växtliv. Medan många bog beasts i träskmarkerna vandrar planlöst omkring som aggressiva rovdjur, har Rethiel ett sällsynt medvetande och en sorgsen röst. Han ser våtmarkerna inte bara som en dyig terräng, utan som ett levande ekosystem som nu ropar under tyngden av främmande rovdjur och fördärv."}},faq={{q="Vem är Rethiel the Greenwarden?",a="Rethiel är ett kännande bog beast som håller till vid The Green Belt i Wetlands. Till skillnad från de tanklösa varelserna av hans slag kan han tala med dödliga och agerar som träskets beskyddare.",al={"vem är rethiel","rethiels historia","bog beast-npc i wetlands"}},{q="Var hittar jag Rethiel?",a="Han finns i The Green Belt i östra Wetlands, nordost om Dun Algaz.",al={"rethiels plats","var finns rethiel"}},{q="Varför vill Rethiel att resande ska hjälpa honom?",a="Rethiel känner att träsket lider. Han söker äventyrare som kan rensa bort de inkräktande hoten: de förödande Mosshide-gnollbanden, de grova flintorna som de använder för att sätta träskets träd i brand och de sjuka fen creepers. På så vis kan landet få lindring.",al={"varför ger rethiel uppdrag","rethiels mål","vad vill rethiel"}},{q="Är alla bog beasts lika kännande som Rethiel?",a="De flesta bog beasts som man möter på Azeroth styrs av råa, fientliga instinkter och saknar högre intellekt. Rethiel är en ovanlig varelse vars djupa samhörighet med naturen ger honom förnuft och talförmåga.",al={"kan bog beasts tala","intelligenta bog beasts","varför kan rethiel tala"}},{q="Vilka hot riktar Rethiel in sig på?",a="Han fokuserar på att hejda de aggressiva Mosshide-gnollerna, ta ifrån dem de grova flintorna som de använder för att bränna levande trä och rensa bort de sjuka fen creepers som frodas i träsket.",al={"rethiels uppdrag","rethiels fiender","hot mot wetlands rethiel"}},{q="Tillhör Rethiel Alliansen eller Horden?",a="Rethiel är vänligt inställd till Alliansen och fientlig mot Horden. Han bryr sig om landets väl och vädjar till resande från Alliansen som vill läka träsket.",al={"tillhör rethiel alliansen","rethiels fraktion","kan horden prata med rethiel"}}},fx={["1fcd3a41"]={q="Varför är Rethiel the Greenwarden här i Wetlands?",a="Rethiel bor vid Green Belt eftersom de omgivande träskmarkerna plågas. Som en varelse djupt sammanflätad med naturen känner han själv markens nöd och sörjer att den ropar efter nåd. Han stannar här för att vaka över de besudlade träskmarkerna och söker hjälp från förbipasserande vandrare med att tränga tillbaka korrumperande krafter, hejda brännande hot och lindra jordens lidande.",al={"varför är rethiel här","varför är rethiel i wetlands","varför är rethiel greenwarden i sin lund"}}},fp="23,146,18.371.0,21.345.1,31.156.1,25.83.0,44.241.0,41.164.1,35.169.0,50.142.0"}
P.entries["npc:rezlak"] = {n="Rezlak",s="Längs vägarna i Durotar söder om Orgrimmar väntar Rezlak på hjälp med sina försörjningslinjer. Goblinentreprenören tillhör Tinkers' Union och anlitar resenärer för att återfinna försvunna förnödenheter och driva bort harpyor.",h="Längs vägarna i Durotar söder om Orgrimmar väntar Rezlak på hjälp med sina försörjningslinjer.",kw={"durotar","dustwind-harpior","rezlak","securing the lines","tinkers' union","winds in the desert"},ang={["faction:Horde"]="Som medlem av Horde träffar du Rezlak strax utanför Orgrimmar, där hans förehavanden speglar de transaktionsbaserade banden mellan neutrala goblinskrån och den gryende Horde.",["profession:Engineering"]="Som ingenjör kan du förstå varför Rezlak värdesätter mekanisk effektivitet, användbara verktyg och återvunna komponenter."},sec={{t="En pragmatisk agent för Tinkers' Union",b="Rezlak väntar vid ravinvägen mellan Razor Hill och Orgrimmar. Han företräder Tinkers' Union, ett goblinsyndikat inriktat på ingenjörskonst, försörjningslinjer och praktiska affärer. Kalimdors fraktionsspänningar betyder föga för honom så länge handeln flyter smidigt. Dustwind-harpyor har plundrat hans lastkaravaner och gjort vägarna osäkra. Rezlak stannar på sin post och anlitar förbipasserande som vill tjäna pengar på att återfinna förnödenheter och ta itu med harpyorna."}},faq={{q="Vem är Rezlak?",a="Rezlak är en goblinköpman och ingenjör i Tinkers' Union. Som en av Gazlowes män skickades han för att hjälpa orcherna i Durotar. Han väntar längs den norra huvudvägen på hjälp med att säkra försörjningslinjerna och återta utrustning från traktens skadedjur.",al={"rezlak bakgrund","vem är rezlak","rezlak durotar"}},{q="Vad gör Rezlak i Durotar?",a="Rezlak arbetar längs handelsvägarna mellan de centrala slätterna och ravinpasset till Orgrimmar. Dustwind-harpyor överföll hans karavaner, spred lasten över de torra ravinerna och gjorde vägarna osäkra.",al={"varför är rezlak i durotar","rezlaks syfte","rezlaks uppdrag"}},{q="Vilka uppdrag erbjuder Rezlak?",a="Rezlak erbjuder två uppdrag: ”Winds in the Desert” ber dig återfinna säckar med försvunna förnödenheter som ligger utspridda på ravinens botten, och ”Securing the Lines” ber dig minska antalet Dustwind-harpyor i närheten.",al={"rezlaks uppdrag","vilka uppdrag ger rezlak"}},{q="Vad är Tinkers' Union?",a="Tinkers' Union är en goblinhandelsorganisation för mekaniker, uppfinnare och logistikarbete. Liksom andra goblinkarteller och skrån sätter dess medlemmar lönsam handel och praktiska lösningar främst, före politisk lojalitet.",al={"tinkers' union","rezlaks fraktion"}}},fx={["910e2401"]={q="Vems sida står Rezlak på?",a="Rezlak företräder goblinernas kommersiella verksamhet snarare än någon politisk lojalitet. Även om han är stationerad längs en viktig väg i Durotar, djupt inne på Hordens territorium, och är knuten till Tinkers' Union, håller han sig till den pragmatiska neutralitet som är typisk för hans folk. Han prioriterar ingenjörskontrakt och bärgad utrustning framför fraktionspolitik.",al={"rezlak fraktion","är rezlak med horden","rezlak horde eller alliansen"}},dba9f262={q="Vad vill Rezlak?",a="Rezlak behöver hålla sina karavaner säkra. Harpyorna från Razorwind Canyon stal hans senaste last, så han anlitar dugliga äventyrare för att återta de förlorade säckarna med förnödenheter och decimera harpyorna i Drygulch Ravine så att vägarna blir säkra igen.",al={"vad behöver rezlak","rezlaks mål","rezlak uppdrag motiv"}}},fp="6,211,32.468.0,14.235.0,32.207.0,31.195.0,27.219.0"}
P.entries["npc:rhahk-zor"] = {n="Rhahk'Zor",s="Rhahk'Zor är en väldig ogre som arbetar som förman i The Deadmines. Han övervakar Edwin VanCleefs underjordiska byggprojekt och håller Defias-arbetarna och gruvarbetarna i schack med råstyrka och hård disciplin.",h="Rhahk'Zor är en väldig ogre som arbetar som förman i The Deadmines.",kw={"the deadmines","defias","förman","hammare","ogre","rhahk'zor","rhahkzor","vancleef"},ang={["class:Warrior"]="Striden mot Rhahk'Zor prövar din uthållighet i frontlinjen. Du ställs mot en väldig ogre som svingar en slägga som krossar både sten och ben.",["faction:Alliance"]="För alliansens äventyrare som tar sig in i Moonbrook är Rhahk'Zor det första dystra beviset på att Defias Brotherhood har vuxit långt bortom småskaligt landsvägsröveri och blivit en tungt befäst armé.",["profession:Mining"]="Rhahk'Zor driver gruvarbetarna med rå brutalitet och visar ingen respekt för guldfyndigheterna. Han förvandlar Westfalls anrika gamla gruvor till en hastigt uppbyggd industriell krigsmaskin."},sec={{t="Förmannen i djupet",b="Djupt under Westfalls böljande kullar har Defias Brotherhood förvandlat Moonbrooks övergivna guldgruvor till en underjordisk fästning. Det krävs hård disciplin för att samordna det omfattande bygget, och ogren Rhahk'Zor har fått den uppgiften. Som utsedd huvudförman övervakar han grävarna och arbetarna och driver dem framåt när de gräver tunnlar och bygger VanCleefs hemliga projekt."},{t="Råstyrka som motivation",b="Rhahk'Zor upprätthåller ordningen med obeveklig råstyrka snarare än genom noggrant ingenjörsarbete. Han är beväpnad med en väldig hammare med stenhuvud, och hans sätt att övervaka arbetet är rakt på sak och skoningslöst. Defias-grävare och gobliningenjörer håller sig på tå runt honom. De vet att den som sackar efter eller sätter sig upp får ett förkrossande slag av den reslige arbetsledaren."}},faq={{q="Vem är Rhahk'Zor?",a="Rhahk'Zor är en ogre som fungerar som huvudförman och ordningsvakt åt Defias Brotherhood i The Deadmines. Han håller vakt över de första utgrävningstunnlarna och ser till att arbetarna fortsätter gräva och håller sig i ledet.",al={"rhahkzor","vem är ogre-bossen i deadmines","första bossen i deadmines"}},{q="Varför arbetar en ogre åt Defias Brotherhood?",a="Edwin VanCleefs uppror förlitar sig på den muskelkraft och de legosoldater de kan få tag på. En ogre inger oöverträffad fysisk skräck, vilket gör Rhahk'Zor till en idealisk arbetsledare för det slitsamma arbetet med att gräva ut gruvorna.",al={"varför finns det en ogre i deadmines","rhahkzor defias"}},{q="Vad gör Rhahk'Zor i gruvorna?",a="Han arbetar som huvudförman för bygget. Rhahk'Zor övervakar gruvarbetarna, gobliner och Defias-byggare när de gräver ut grottorna, underhåller utrustningen och bygger befästningar åt Brotherhood.",al={"vad gör rhahkzor","rhahkzors roll"}},{q="Var i The Deadmines finns Rhahk'Zor?",a="Rhahk'Zor vaktar de första stenbrottskamrarna i The Deadmines. Han står bortom de första gruvarbetartunnlarna, framför den första tunga dörren som leder längre in i gruvan.",al={"rhahkzors plats","var finns rhahkzor"}},{q="Har Rhahk'Zor någon koppling till ogres från första kriget?",a="Ogres levde en gång i The Deadmines under första kriget, innan Blackhands Horde utplånade dem. Det är obekräftat om Rhahk'Zor är en kvarleva från de tidigare klanerna eller bara en råskinnstyp som VanCleef har lejt.",al={"ogres i deadmines under första kriget","ogreberättelser deadmines"}},{q="Vad händer när Rhahk'Zor besegras?",a="När Rhahk'Zor besegras bryts Defias kontroll över det yttre stenbrottet. Vägen genom den förstärkta sprängdörren han vaktar är fri, så inkräktare kan ta sig längre in till de hemliga skeppsvarven och verkstäderna.",al={"rhahkzors dörr","efter rhahkzor"}}},fx={["77e4622d"]={q="Vems sida står Rhahk'Zor på?",a="Rhahk'Zor tjänar Defias Brotherhood under Edwin VanCleef. Trots att han är en ogre bland främst mänskliga skurkar och laglösa har han en maktposition som förman och övervakar brödraskapets underjordiska utgrävningar och byggprojekt.",al={"vem arbetar rhahk'zor för","rhahk'zor fraktion","rhahk'zor alliansen"}},ff75ed44={q="Vem är Rhahk'Zor knuten till?",a="Rhahk'Zor lyder direkt under Edwin VanCleef, hjärnan bakom Defias Brotherhood. I sin tur befaller Rhahk'Zor Defias-gruvarbetarna, arbetarna och vakterna som är stationerade i de övre grottorna i The Deadmines.",al={"rhahk'zors kontakter","vem leder rhahk'zor","rhahk'zor edwin vancleef"}}},fp="9,183,23.263.0,16.204.0,17.178.0,50.193.0,37.190.0,44.145.0,67.193.0,40.195.0"}
P.entries["npc:rhinag"] = {n="Rhinag",s="Bland klipporna nära Durotars nordvästra gräns väntar Rhinag, försvagad av skorpiders gift. Darkspear-trollet är beroende av förbipasserande resenärer för att hitta ett botemedel i tid.",h="Bland klipporna nära Durotars nordvästra gräns väntar Rhinag, försvagad av skorpiders gift.",kw={"motgift","durotar","behov av ett botemedel","rhinag","venomtail scorpid"},ang={["race:Troll"]="Som troll kan du se en frände slås ned av Durotars inhemska djurliv. Darkspear-stammen ställs inför många prövningar medan den skapar sig ett hem sida vid sida med Horde."},sec={{t="Ett giftigt hot",b="Rhinag söker skydd bland klipporna nära Durotars nordvästra gräns efter att en Venomtail Scorpid stuckit honom. Giftet har gjort Darkspear-trollet svagt och isolerat. Han behöver ett Venomtail Antidote, och hans överlevnad beror på om en förbipasserande resenär kan hitta ett innan gifterna tar ut sin rätt."}},faq={{q="Vem är Rhinag?",a="Rhinag är en resande Darkspear-djungeltroll, strandsatt och försvagad nära Durotars nordvästra gräns efter ett skorpionsstick.",al={"vem är rhinag","rhinags bakgrund","troll vid rocktusk"}},{q="Var finns Rhinag?",a="Rhinag vilar bland klipporna nära Durotars nordvästra gräns.",al={"rhinags plats","var finns rhinag","troll vid rocktusk farm"}},{q="Vad hände med honom?",a="En Venomtail Scorpid stack Rhinag medan han färdades genom Durotar. Dess gift gjorde honom oförmögen att röra sig, och han behöver ett motgift innan giftet blir dödligt.",al={"varför är rhinag sjuk","vad förgiftade rhinag","bakgrund till behovet av ett botemedel"}}},fx={["37e11902"]={q="Vems sida står Rhinag på?",a="Rhinag är allierad med Horden. Han är en Darkspear-troll som ligger skadad nära Durotars nordvästra gräns och förlitar sig på förbipasserande resenärer och hjältar från Horden för att få hjälp i sin nöd.",al={"rhinag fraktion","är rhinag med horden","rhinags lojalitet"}},cc642833={q="Vad vill Rhinag?",a="Rhinag behöver desperat ett motgift. Han har blivit stungen av en lokal venomtail scorpid och behöver snabbt ett botemedel innan giftet får full verkan i kroppen.",al={"rhinag uppdrag","vad behöver rhinag","hjälp rhinag"}},ffa3558a={q="Varför är Rhinag här?",a="Rhinag har sökt skydd bland klipporna nära Durotars nordvästra gräns efter att ha blivit stungen av en venomtail scorpid. Där väntar han på hjälp innan giftet övermannar honom helt.",al={"varför är rhinag här","var är rhinag","vad förde rhinag hit"}}},fp="6,173,16.296.0,14.127.0,26.64.0,21.142.0"}
P.entries["npc:ringo"] = {n="Ringo",s="Ringo är en olycksdrabbad goblinutforskare som tog sig uppför de brännande höjderna på Fire Plume Ridge i Un'Goro Crater. Överväldigad av vulkanens kvävande hetta och giftiga ångor kollapsade han i en grotta, desperat efter hjälp att ta sig ner igen. Hans nära vän Spraggle Frock är utom sig av oro vid Marshal's Refuge.",h="Ringo är en olycksdrabbad goblinutforskare som tog sig uppför de brännande höjderna på Fire Plume Ridge i...",kw={"fire plume ridge","goblin","värmeutmattning","marshal's refuge","ringo","spraggle frock","un'goro crater"},sec={{t="Alltför nära lågorna",b="Goblins är kända för att trotsa farliga miljöer i jakten på rikedomar eller märkliga föremål, men Fire Plume Ridge är hård även med deras mått mätt. Den aktiva vulkanen reser sig mitt i Un'Goro Crater och spyr ut aska, magma och kokande ånga. Ringo klättrade ungefär halvvägs uppför den södra sidan innan den kvävande hettan blev honom övermäktig. Han lämnade sina tillhörigheter utspridda precis utanför och kröp in i en grotta för att söka skydd från den tryckande värmen, helt utslagen av värmeslag."},{t="En mödosam färd nerför sluttningen",b="Att få ner Ringo från berget är en prövning i sig. Goblinen är så försvagad av uttorkning och värmeslag att han gång på gång svimmar under nedstigningen. För att hålla honom på benen krävs generösa skvättar ur en fältflaska – eller ibland en rask örfil för att få honom vid medvetande. Att eskortera honom förbi bergets oberäkneliga elementandar och rovdjur hela vägen tillbaka till tryggheten vid Marshal's Refuge kräver ständig vaksamhet, tills han kan återförenas med sin vän Spraggle."}},faq={{q="Vem är Ringo?",a="Ringo är en goblinutforskare i Un'Goro Crater som klättrade uppför de vulkaniska sluttningarna på Fire Plume Ridge, men dukade under för extrem värmeutmattning i en grotta.",al={"ringo","vem är ringo","ringo goblin"}},{q="Var finns Ringo?",a="Han finns i en grotta som vetter mot söder, ungefär halvvägs uppför sluttningarna på Fire Plume Ridge, mitt i Un'Goro Crater.",al={"ringos plats","var är ringo","hitta ringo"}},{q="Vem letar efter Ringo?",a="Hans gode vän Spraggle Frock, som håller till vid Marshal's Refuge i norra Un'Goro, är djupt oroad över att Ringo har försvunnit.",al={"vem är spraggle","ringos vän","spraggle frock"}},{q="Varför svimmar han på vägen ner?",a="Ringo lider av svår värmeutmattning och uttorkning på grund av hettan och ångorna från den aktiva vulkanen Fire Plume Ridge. Spraggles fältflaska behövs för att väcka honom varje gång han svimmar.",al={"varför svimmar ringo","ringo svimmar","ringo kollapsar"}},{q="Vad är Ringo's Sack?",a="Det är Ringos personliga packning, som han tappade precis utanför grottöppningen när han kollapsade av hettan, innan han drog sig in.",al={"ringos säck","ringos väska","ringos borttappade väska"}},{q="Vart måste Ringo ta sig?",a="Han behöver eskorteras tryggt ner från vulkanen och över kraterbottnen till Marshal's Refuge, där hans vän Spraggle Frock väntar.",al={"vart ska jag ta ringo","ringos destination","slutet på ringos eskort"}}},fp="5,332,32.512.0,31.488.1,13.158.0,23.134.0,25.138.0,35.196.0,21.138.0,28.131.0"}
P.entries["npc:rivern-frostwind"] = {n="Rivern Frostwind",s="Rivern Frostwind är en nattalv och ridinstruktör som håller till högt uppe på Frostsaber Rock i norra Winterspring. Tillsammans med sin frosttiger Glacier vakar han över de inhemska wintersaberkatterna och tränar ryttare som orden anser värdiga. Bara Alliansens mest hängivna hjältar får äran att rida en av hans dyrbara riddjur.",h="Rivern Frostwind är en nattalv och ridinstruktör som håller till högt uppe på Frostsaber Rock i norra...",kw={"frostsaber rock","glacier","ridtränare","rivern frostwind","wintersaber trainers","wintersprings frostsaberkatt"},ang={["faction:Alliance"]="För Alliansen är Rivern Frostwind den enda som erbjuder den sällsynta frostsaberkatten från Winterspring. Han ger ryttare utanför Darnassus chansen att tämja ett av Kalimdors vildaste bestar genom ren uthållighet.",["race:NightElf"]="Nightsaberkatter är nära knutna till Elunes prästerskap och Kalimdors väktare, medan Riverns frostsaberkatter tillhör en anpassad, ensam släktlinje som avlats fram särskilt för Wintersprings hårda snölandskap."},sec={{t="Wintersaberkatternas mästare",b="Rivern Frostwind sitter på den isiga udden Frostsaber Rock och ansvarar för aveln och skötseln av den legendariska frostsaberkatten från Winterspring. Medan nightsaberkatter strövar i Teldrassils och Ashenvales lummiga skogar föds deras släktingar från det subarktiska klimatet upp för att uthärda norra Kalimdors bitande kyla. Rivern vaktar dessa majestätiska rovdjur. Han kräver att främlingar visar att de tänker värna bestarna. De måste samla färskt kött från tundran, rensa bort Winterfall-furbolger och driva tillbaka härjande frostjättar innan han ens överväger att anförtro dem en av saberkatterna."}},faq={{q="Vem är Rivern Frostwind?",a="Rivern Frostwind är en nattalv och ridmästare, och tar hand om fraktionen Wintersaber Trainers vid Frostsaber Rock i norra Winterspring. Tillsammans med sin trogna tiger Glacier ser han till att regionens kraftfulla, inhemska stora kattdjur skyddas och föds upp på rätt sätt.",al={"rivern frostwind bakgrund","frostsaberkattens tränare","vem är rivern"}},{q="Varför är han i Winterspring?",a="Han bor vid Frostsaber Rock för att träna och skydda regionens sällsynta vita frostsaberkatter. Rovdjuren hotas ständigt av aggressiva Winterfall-furbolger, framryckande jättar och hårda förhållanden, så Rivern upprätthåller ordningen och ser efter deras välbefinnande.",al={"varför är rivern här","frostsaber rocks syfte"}},{q="Kan hordespelare samarbeta med Rivern?",a="Nej. Rivern Frostwind är obrottsligt lojal mot nattalverna och Alliansen. Horderesande som närmar sig Frostsaber Rock kommer att märka att han inte alls vill ha med dem att göra. Han ger bara Alliansens hjältar sitt förtroende och lär dem rida.",al={"kan horden få en wintersaberkatt","är rivern vänligt inställd till horden"}},{q="Vem är tigern vid hans sida?",a="Frosttigern som vilar vid Riverns sida heter Glacier. Han är Riverns följeslagare och ett praktexemplar av de härdiga kattdjur som hör hemma på Wintersprings tundra.",al={"vem är glacier","rivern frostwinds tiger"}}},fp="16,355,25.612.0,24.265.0,26.262.0,35.248.0,28.150.0"}
P.entries["npc:roetten-stonehammer"] = {n="Roetten Stonehammer",s="Roetten Stonehammer är en företagsam dvärg som vandrar omkring i biblioteket i Ironforges Hall of Explorers. Han företräder Reclaimers Inc. och organiserar expeditioner samt rekryterar äventyrare för att utföra bärgningsuppdrag i avlägsna länder som Desolace.",h="Roetten Stonehammer är en företagsam dvärg som vandrar omkring i biblioteket i Ironforges Hall of Explorers.",kw={"desolace","hall of explorers","ironforge","bibliotek","reclaimers inc","roetten stonehammer","bärgning"},ang={["faction:Alliance"]="Roetten är en viktig kontakt för Alliansen i Ironforge och hjälper expeditioner att korsa havet till de omstridda, karga vildmarkerna i Kalimdors Desolace.",["race:Dwarf"]="För dvärgar som bläddrar bland Ironforges storslagna arkiv visar Roetten att arkeologisk nyfikenhet ofta går hand i hand med smart kommersiell bärgning."},sec={{t="Affärer i biblioteket",b="Bland de uråldriga böckerna och dammet i Hall of Explorers bibliotek håller Roetten Stonehammer ett öga på praktiska bärgningsärenden. På uppdrag av Reclaimers Inc. förmedlar Roetten kontakter mellan djärva legoknektar och lukrativa bärgningskontrakt runtom i Kalimdor. Hans medarbetare gräver inte bara av historisk nyfikenhet, utan försöker återta värdefull last, vrakdelar och sällsynta reagenser från farliga utmarker som Desolaces karga ödemarker."}},faq={{q="Vem är Roetten Stonehammer?",a="Roetten Stonehammer är en dvärg som ger uppdrag och håller till i biblioteket i Hall of Explorers i Ironforge. Han samordnar verksamheten och söker efter skickliga personer åt Reclaimers Inc. samt skickar äventyrare på riskfyllda bärgningsuppdrag i främmande länder.",al={"vem är roetten","vem är roetten stonehammer","roetten stonehammers bakgrund"}},{q="Vad är Reclaimers Inc.?",a="Reclaimers Inc. är ett företag som ägnar sig åt att bärga förlorade försändelser, samla sällsynta reagenser och undersöka värdefulla vrak i farliga, otämjda områden som Desolaces stränder och ruiner.",al={"vad är reclaimers inc","reclaimers inc","reclaimers affärer"}},{q="Vart skickar Roetten äventyrare?",a="Roetten skickar dugliga resenärer över havet till Desolace i västra Kalimdor. Där undersöker hans partner bärgning av skeppsvrak och insamling av reagenser längs den karga kusten och i den ödsliga vildmarken.",al={"roetten stonehammers uppdrag","vart skickar roetten dig","reclaimers affärer i desolace"}}},fx={c52b1d4d={q="Vems sida står Roetten Stonehammer på?",a="Roetten Stonehammer är allierad med Ironforge och Alliansen och verkar öppet i Hall of Explorers. Hans affärsverksamhet, särskilt för Reclaimers Inc., tjänar Alliansens intressen genom att anlita pålitliga resenärer för att återfinna förlorade tillgångar och förnödenheter i avlägsna, farliga trakter.",al={"roetten stonehammer alliansen eller horden","vem tjänar roetten stonehammer","roetten stonehammer fraktion"}},["4b23d3f4"]={q="Vad vill Roetten Stonehammer?",a="Roetten söker dugliga äventyrare som kan hjälpa till med bärgning och återhämtning av förlorat gods utomlands åt Reclaimers Inc. Han skickar ut lejd hjälp till farliga vildmarker som Desolaces karga stränder för att bärga gods från förlorade laster och samla exotiska reagenser som hans medarbetare behöver i sitt arbete.",al={"vad letar roetten stonehammer efter","roetten stonehammer motiv","varför behöver roetten stonehammer hjälp"}},f41f4afa={q="Varför är Roetten Stonehammer här?",a="Du kan hitta Roetten vandrande i det storslagna biblioteket i Ironforges Hall of Explorers. Han har sin bas här för att rådfråga gamla arkiv, hålla nära kontakt med andra lärda och prospektörer och rekrytera djärva upptäcktsresande som passerar genom dvärgarnas huvudstad.",al={"varför är roetten i ironforge","vad gör roetten i hall of explorers","roetten stonehammer bibliotek"}}},fp="19,170,23.264.0,27.167.0,24.133.0,36.166.0"}
P.entries["npc:rorian-the-dayseeker"] = {n="Rorian the Dayseeker",s="Rorian the Dayseeker är en äldre Skyborne-gestalt i Thendal Village på Zephras Isle. Han leder de unga Skyborne genom deras invigning, när de upptäcker sin kallelse, blir vuxna och stämmer sig efter hemlandets naturliga element. Under hans vakande ledning lär sig nykomlingarna grunderna i överlevnad, tradition och tjänst för samhället.",h="Rorian the Dayseeker är en äldre Skyborne-gestalt i Thendal Village på Zephras Isle.",kw={"dayseeker","ung skyborne","mentor","rorian","skyborne","thendal","zephras"},ang={["class:Mage"]="Nybörjare inom magi finner en förstående vägledare i Rorian, som hänvisar blivande lärda inom det arkaniska till lärare som kan förädla deras råa magiska begåvning.",["class:Shaman"]="Rorian lägger stor vikt vid öns harmoni och skickar ut unga Skyborne för att lugna upprörda elementaler och knyta an till uråldriga traditioner.",["class:Warrior"]="Rorian ser den fysiska hängivenheten hos blivande kämpar och hänvisar dem som vill bli krigare till mentorer som lär ut disciplin på slagfältet.",["race:Skyborne"]="För varje ung Skyborne är Rorian the Dayseeker den första tröskeln till plikt och tradition. I Thendal Village vägleder han dig på vägen mot vuxenlivet."},sec={{t="Äldste i Thendal Village",b="I den fridfulla Thendal Village på Zephras Isle är Rorian the Dayseeker en av de främsta mentorerna för de unga Skyborne. Rorian är vördad för sin erfarenhet och sitt lugna förstånd och vägleder ungdomarna under deras avgörande övergång till vuxenlivet. Under hans ledning genomgår de invigda sin traditionella övergångsrit, som visar att de är redo att försvara och stödja sitt öhem."},{t="Vägledning till nya kallelser",b="Utöver grundläggande prövningar visar Rorian lovande invigda vägen mot särskilda inriktningar som passar deras talanger. Oavsett om någon vill bli krigare, jägare, lönnmördare, magiker, shaman eller druid hänvisar Rorian de unga till särskilda tränare runt om på ön. Han varnar dem också för elementära störningar som rubbar öns harmoni och ingjuter en varaktig pliktkänsla att bevara balansen bland de vindpinade höjderna."}},faq={{q="Vem är Rorian the Dayseeker?",a="Rorian the Dayseeker är en äldre Skyborne-ledare i Thendal Village på Zephras Isle. Han är den främsta mentorn för nybörjaräventyrare och unga Skyborne som ger sig ut på sina första prövningar.",al={"vem är rorian","rorian roll","vad gör rorian"}},{q="Var hittar man Rorian the Dayseeker?",a="Han finns i Thendal Village, Skybornes startby på Zephras Isle.",al={"var finns rorian","rorian plats","hitta rorian"}},{q="Vilken roll har Rorian i Skybornes övergång till vuxenlivet?",a="Rorian leder de första övergångsriterna som markerar en ung Skybornes övergång till vuxenlivet. Han prövar deras mod och förmåga att anpassa sig till livet på ön innan han skickar ut dem för att tjäna den större bosättningen.",al={"rorian övergång till vuxenlivet","skyborne mentor för prövningar"}},{q="Hur vägleder Rorian nya lärlingar till deras klasser?",a="När en nybörjare har visat vad hen går för berättar Rorian var hen kan fortsätta sin avancerade träning och vägleder hen mot vägarna som krigare, jägare, lönnmördare, magiker, shaman eller druid.",al={"klassuppdrag rorian","välja klass med rorian"}},{q="Varför skickar Rorian äventyrare för att ta itu med elementaler?",a="Den naturliga balansen kring Zephras Isle är sårbar för störningar. Rorian ger dugliga invigda i uppdrag att undersöka och lugna elementär oro, så att Thendal Village och vildmarken omkring förblir i harmoni.",al={"elementär oro rorian","varför bekämpa elementaler på zephras"}},{q="Vem är Aetheen of the Gales?",a="Aetheen of the Gales är en person på Zephras Isle som Rorian hänvisar unga Skyborne till när de tar sig an öns uppgifter och träning.",al={"aetheen rorian","aetheen of the gales"}}},fx={["60e564c2"]={q="Vems sida står Rorian the Dayseeker på?",a="Rorian tjänar sitt eget folk, Skyborne från Zephras Isle. Han är stationerad i Thendal Village och är trogen öns samhälle, samtidigt som han förbereder nästa generation Skyborne-ungdomar på att ge sig ut i världen och möta alla hot mot deras hemland.",al={"rorian fraktion","vem tjänar rorian","rorians lojalitet"}},ec1df735={q="Vad vill Rorian the Dayseeker?",a="Rorian har åtagit sig att vägleda unga Skyborne genom deras traditionella övergångsriter. Han vill att varje ung lärling ska bejaka sin kallelse, vare sig den är krigisk, magisk eller naturbunden, samtidigt som byn skyddas från farliga elementära oroligheter.",al={"rorians mål","vad försöker rorian göra","rorian the dayseeker syfte"}},c3a8f075={q="Varför är Rorian the Dayseeker i Thendal Village?",a="Rorian stannar i Thendal Village för att övervaka Skyborne-lärlingarnas övergångsprov till vuxenlivet. Härifrån håller han uppsikt över öns angelägenheter, visar nybörjare till specialiserade tränare och skickar ut dugliga personer för att återställa balansen när elementära oroligheter bryter ut i närheten.",al={"varför är rorian här","varför är rorian i thendal village","rorians plats varför"}}},fp="20,375,24.414.0,24.408.0,28.201.0,40.91.0,52.208.0,55.181.0,57.219.0,28.156.0"}
P.entries["npc:royal-historian-archesonus"] = {n="Royal Historian Archesonus",s="Royal Historian Archesonus är en dvärgisk lärd som tjänar King Magni Bronzebeard i Ironforges High Seat. Hon är känd för sina verk om de senaste katastroferna i de norra människorikena och leder även forskning om forntida dvärgiska tragedier, särskilt resterna av det förkolnade Dark Iron-riket.",h="Royal Historian Archesonus är en dvärgisk lärd som tjänar King Magni Bronzebeard i Ironforges High Seat.",kw={"archesonus","high seat","historiker","ironforge","lordaeron","royal historian archesonus","thaurissan"},ang={["faction:Alliance"]="Hennes akademiska verk bevarar den dystra vittnesbörden om Lorderaons fall, så att de sydliga allierade förstår farsotens natur och krafterna som krossade människornas nordliga riken.",["race:Dwarf"]="Archesonus vårdar ditt folks officiella minne och bevarar smärtsamma lärdomar från War of the Three Hammers, så att Bronzebeard-klanen inte upprepar Dark Irons övermod."},sec={{t="Krönikör över katastrofer",b="Royal Historian Archesonus har sin plats några steg från King Magni Bronzebeards tron i High Seat och för historiska register åt Ironforges krona. Hennes akademiska blick sträcker sig långt bortom bergen i Khaz Modan. Hon skrev ”The Fall of Lordaeron and the Scouring of the Eastweald” och ”On Plagues, Curses, and Blights” om hur Scourge förvandlade mänsklighetens norra rike till ruiner. Archesonus flyr inte mörk historia. Hon närmar sig katastrofer metodiskt och söker dokumentera sanningen om förödande magi och politisk kollaps."},{t="Thaurissans aska",b="Förutom sina texter om Lordaeron leder Archesonus undersökningar av War of the Three Hammers och den katastrofala förstörelsen av staden Thaurissan. Hon söker återfunna reliker och förkolnade stentavlor från Burning Steppes och anlitar äventyrare för att leta i Smoldering Ruins of Thaurissan. För Archesonus är det avgörande för statskonsten att förstå katastrofen som förbrände Burning Steppes och band Dark Iron-klanen till Firelord. Då kan Bronzebeard-riket minnas precis vad trolldom och desperation kan släppa lös."}},faq={{q="Var hittar jag Royal Historian Archesonus?",a="Royal Historian Archesonus finns i High Seat i Ironforge, nära King Magni Bronzebeards tronrum.",al={"archesonus plats","var finns royal historian archesonus","archesonus ironforge"}},{q="Vilka böcker skrev Royal Historian Archesonus?",a="Hon skrev ”The Fall of Lordaeron and the Scouring of the Eastweald” och ”On Plagues, Curses, and Blights”, där hon skildrar människornas nordliga rikes fall och de nekrotiska farsoter som Scourge spred.",al={"archesonus böcker","vad skrev archesonus","archesonus historieböcker"}},{q="Varför är Archesonus intresserad av Ruins of Thaurissan?",a="Hon studerar forntida dvärghistoria och skickar spejare till Burning Steppes för att återfinna förlorade reliker från Ruins of Thaurissan. På så vis lägger hon pusslet kring katastrofen som förstörde Dark Irons forntida huvudstad.",al={"archesonus thaurissan uppdrag","varför vill hon ha ruins of thaurissan","smoldering ruins of thaurissan"}},{q="Vilken roll har hon i Ironforge?",a="Som officiell Royal Historian är hon King Magni Bronzebeards främsta krönikör och arkivarie. Hon sammanställer uppteckningar om både dvärgarnas forntid och världshändelser som hotar Alliance.",al={"archesonus titel","vad gör en royal historian","vem är archesonus"}}},fx={d5335835={q="Vems sida står Royal Historian Archesonus på?",a="Royal Historian Archesonus tjänar King Magni Bronzebeard och kungariket Ironforge och står därmed stadigt på Alliansens sida. Hon är stationerad i High Seat, där hennes forskning och arkivstudier hjälper det kungliga hovet att förstå dvärgarnas forntida historia, grannländerna och de hot som fortfarande vilar över riket.",al={"archesonus fraktion","vem tjänar archesonus","är archesonus med alliansen"}},["48b31094"]={q="Varför är Royal Historian Archesonus i High Seat?",a="Archesonus stannar i High Seat eftersom det är Ironforges regeringssäte och King Magni Bronzebeards säte. Som kunglig historiker bedriver hon sina arkivstudier nära dvärgarnas ledare, där hon kan ge råd åt tronen och ge äventyrare i uppdrag att finna reliker och glömda historier.",al={"varför är archesonus i high seat","archesonus plats varför","varför är royal historian archesonus här"}},["3b340abe"]={q="Vem är Royal Historian Archesonus knuten till?",a="Archesonus är direkt knuten till King Magni Bronzebeards kungliga hov i Ironforge. Hennes ställning som lärd placerar henne bland monarkens betrodda rådgivare och arkivförare. Hon dokumenterar stora katastrofer i Eastern Kingdoms och söker fysiska bevis från forntida ruiner, som de som Dark Iron-klanen lämnade efter sig.",al={"archesonus band","vem arbetar archesonus för","archesonus kontakter"}}},fp="26,303,25.415.0,23.362.0,44.107.0,48.230.0,56.243.0,30.214.0"}
P.entries["npc:ruga-ragetotem"] = {n="Ruga Ragetotem",s="Vid Camp Taurajo tränar Ruga Ragetotem krigare för Horde. Han prövar dem mot silithiderna i södra Barrens innan han skickar de beprövade vidare för att få skräddarsydd rustning.",h="Vid Camp Taurajo tränar Ruga Ragetotem krigare för Horde.",kw={"camp taurajo","field of giants","ruga ragetotem","silithid","taurajo","thun'grim firegaze","krigarprövning"},ang={["class:Warrior"]="Som krigare möter du silithiderna för att bevisa din skicklighet innan Ruga skickar dig till Thun'grim Firegaze för att få en rustning smidd.",["race:Tauren"]="Som tauren finner du Ruga Ragetotem vid Camp Taurajo, där han vakar över de södra trakterna med Jordmoderns barns styrka och vaksamhet."},sec={{t="En mentor i Camp Taurajo",b="Vid Camp Taurajo tränar Ruga Ragetotem krigare som vill bevisa sin styrka i Kalimdor. Silithider har plötsligt dykt upp i söder och gräver kupor i Field of Giants. Ruga skickar unga kämpar för att jaga insekterna och skära av deras antenner. De som uthärdar prövningen vinner hans respekt och en rekommendation till Thun'grim Firegaze, en berömd rustningssmed."}},faq={{q="Vem är Ruga Ragetotem?",a="Ruga Ragetotem tränar krigare vid Camp Taurajo i södra Barrens. Han prövar kämpar som hoppas kunna bevisa sig för Horde.",al={"vem är ruga","ruga ragetotem berättelse","ruga taurajo"}},{q="Vilken prövning ger Ruga krigarna?",a="Ruga skickar krigare söderut till Field of Giants för att strida mot de nyligen uppdykta silithiderna. De måste döda de aggressiva insekterna och ta med sig deras antenner tillbaka för att bevisa sitt mod och sin stridsförmåga.",al={"rugas prövning","prövning vid field of giants","vad vill ruga"}},{q="Vem skickar Ruga dig till efter prövningen?",a="När en krigare har bevisat sig mot silithiderna skickar Ruga dem norrut till Thun'grim Firegaze, en orcisk rustningssmed som smider specialrustningar åt värdiga kämpar.",al={"vart efter ruga","rugas nästa uppdrag","thun'grim ruga"}},{q="Varför intresserar sig Ruga för Field of Giants?",a="Silithider har nyligen invaderat Field of Giants och gräver kupor i jorden. Ruga använder det närliggande hotet för att pröva krigare som kan komma att försvara Horde.",al={"varför field of giants","ruga insekter","silithid taurajo"}}},fx={["561e0961"]={q="Vems sida står Ruga Ragetotem på?",a="Ruga Ragetotem står stadigt med Horden och sina taurenfränder. Han är stationerad i Camp Taurajo i södra Barrens och hjälper unga krigare att bevisa sitt mod för Hordens sak genom att låta dem möta nya hot i Kalimdor.",al={"ruga ragetotem fraktion","vem slåss ruga för","är ruga med horden"}},["97d42651"]={q="Varför är Ruga Ragetotem här i Camp Taurajo?",a="Ruga har sitt läger i Taurajo för att hålla uppsikt över södra Barrens och pröva lovande krigare från Horden. Härifrån bevakar han farliga intrång, som silithiderna som svärmar nära Field of Giants, och skickar beprövade kämpar att möta hotet innan de får gå vidare.",al={"varför är ruga i camp taurajo","ruga ragetotem plats varför","varför är ruga i the barrens"}}},fp="14,168,24.367.0,22.132.0,38.200.0,42.168.0,46.152.0"}
P.entries["npc:rutgar-glyphshaper"] = {n="Rutgar Glyphshaper",s="Rutgar Glyphshaper är en dvärgarkeolog som är stationerad vid Bronzebeard Encampment i södra Silithus. Som medlem av Brann Bronzebeards expedition studerar han forntida silithidreliker och runor i hopp om att avslöja mysteriet med kuporna, även efter att Brann gett sig av ut i öknen.",h="Rutgar Glyphshaper är en dvärgarkeolog som är stationerad vid Bronzebeard Encampment i södra Silithus.",kw={"brann","bronzebeard","kristall","runor","glyphshaper","maralith","regal","rutgar","silithus"},ang={["faction:Alliance"]="Alliansens äventyrare hittar en sällsynt utpost med vänliga ansikten i den ogästvänliga södra öknen, men Rutgars besättning får inget officiellt stöd från Ironforges krona.",["race:Dwarf"]="Dvärgar känner igen Rutgars orubbliga hängivenhet till Explorer's League. Han riskerar liv och lem djupt inne i fientliga insektkupor för att vinna forntida kunskap."},sec={{t="Bronzebeardexpeditionen",b="Rutgar Glyphshaper reste till Silithus under Brann Bronzebeards ledning för att undersöka de väldiga silithidkuporna och gräva fram förlorade reliker som begravts under öknens vidder. Rutgar och hans följeslagare upprättade sin bas vid Bronzebeard Encampment söder om Cenarion Hold och gav sig ofta direkt in i insektkuporna för att samla in ristade stenar och runföremål. De samarbetade ofta med Cenarion Hold-forskare av Night Elf-folket."},{t="Problem i kuporna",b="Under en expedition in i Hive'Regal tillsammans med Night Elf-prästinnan Natalia Mar'alith upptäckte gruppen en märklig, runristad kristall. Reliken försatte Natalia i ett transliknande tillstånd, så dvärgarna fick bära ut henne och föra henne till Cenarion Hold för vård. När hon senare återvände till dvärgarnas läger i vilt raseri och krävde att få återvända till kupan, tvingades Rutgar och expeditionen slåss mot henne i en desperat kamp innan hon flydde tillbaka ut bland sanddynerna."},{t="Att tyda silithiderna",b="Brann Bronzebeard har försvunnit ut i ödemarken, som han brukar göra, och Rutgar stannar kvar i lägret för att fortsätta deras forskning. Han samlar främst in avtryck av kristaller och försöker tyda insekternas runor som finns utspridda i silithidkuporna. Han försöker pussla ihop kupornas historia och spåra var Brann kan ha försvunnit."}},faq={{q="Vem är Rutgar Glyphshaper?",a="Han är en upptäcktsresande och lärd som följde med Brann Bronzebeard på en arkeologisk expedition till Silithus. För närvarande har han sin bas vid Bronzebeard Encampment.",al={"rutgar","vem är rutgar","information om rutgar glyphshaper"}},{q="Var är Brann Bronzebeard?",a="Brann gav sig ensam av ut i Silithus ödemarker på en av sina vanliga spaningsturer, och lämnade Rutgar och resten av besättningen att sköta lägret och forska om kuporna.",al={"var är brann","vart tog brann vägen","brann försvunnen"}},{q="Vad hände med Natalia Mar'alith vid lägret?",a="Efter att ha påverkats av en forntida kristall i Hive'Regal återvände Natalia Mar'alith till Bronzebeard Encampment i våldsamt raseri. Hon angrep Rutgar, Brann och besättningen innan hon försvann tillbaka ut i öknen.",al={"vad hände med natalia","natalias attack","prästinnan angrep lägret"}},{q="Varför studerar Rutgar silithidkristallerna?",a="Rutgar försöker översätta de forntida runorna som ristats in i kristallerna i kuporna. Han vill förstå silithidernas ursprung och hitta ledtrådar om var Brann befinner sig.",al={"varför runor","vad studerar rutgar","runristade kristaller"}},{q="Har Ironforge skickat hjälp till expeditionen?",a="Nej. Expeditionen begärde militärt stöd från Ironforge, men dvärgriket avböjde och hävdade att dess styrkor redan var hårt ansträngda med att försvara riket.",al={"förstärkningar från ironforge","ironforges armé i silithus"}},{q="Var ligger Bronzebeard Encampment?",a="Det ligger i södra Silithus, i ökensanden söder om Cenarion Hold och strax väster om Hive'Regal.",al={"var ligger bronzebeard encampment","lägrets plats"}}},fp="18,306,26.434.0,20.478.1,24.352.1,26.155.0,27.186.0,47.223.1,45.186.0,41.167.0,44.116.0"}
P.entries["npc:ruul-eagletalon"] = {n="Ruul Eagletalon",s="Ruul Eagletalon är en tauren som bor i Bloodhoof Village i Mulgore. Han är posterad nära bosättningens utkant och håller ett vaksamt öga på det lokala djurlivet, särskilt de aggressiva Windfury-harpiorna som tränger in på tauren-mark.",h="Ruul Eagletalon är en tauren som bor i Bloodhoof Village i Mulgore.",kw={"bloodhoof","eagletalon","harpyor","mulgore","ruul","windfury"},ang={["race:Tauren"]="Ruul står för den praktiska vaksamhet som Shu'halo behöver för att hålla Mulgore, deras nyfunna fristad, säker från territoriella rovdjur och bevingade plundrare."},sec={{t="Bloodhoofs väktare",b="Ruul Eagletalon står vakt i Bloodhoof Village och ser till bosättningens säkerhet medan unga braves anländer från Camp Narache. Mulgore är ett fridfullt hemland jämfört med The Barrens torra ödemarker, men territoriella rovdjur och fientliga varelser pressar ständigt mot betesmarkerna. Ruul bekymrar sig över hot som strövar på de närliggande slätterna och skickar särskilt dugliga resenärer att konfrontera de vilda Windfury-harpiorna, som jagar ovetande nomader och villebråd."}},faq={{q="Vem är Ruul Eagletalon?",a="Ruul Eagletalon är en tauren som är posterad i Bloodhoof Village och hjälper till att skydda bosättningen genom att skicka äventyrare mot lokala hot i Mulgore.",al={"vem är ruul","ruul eagletalon npc","ruul i bloodhoof"}},{q="Vilket hot ber Ruul Eagletalon resenärer att ta itu med?",a="Ruul varnar för de fientliga Windfury-harpiorna som häckar i Mulgore och ger dugliga braves i uppdrag att minska deras antal innan de skadar byn.",al={"ruul uppdrag","windfurys faror","harpiuppdrag i mulgore"}},{q="Var kan Ruul Eagletalon hittas?",a="Han kan hittas stående på Bloodhoof Villages område, vid stranden av Stonebull Lake i centrala Mulgore.",al={"ruul eagletalon plats","hitta ruul","var är ruul"}}},fx={["17869be4"]={q="Vems sida står Ruul Eagletalon på?",a="Ruul Eagletalon står stadigt med Bloodhoof-tauren och Horden. Han är stationerad i Bloodhoof Village och är trogen sitt folk och skyddet av deras förfäders betesmarker i Mulgore.",al={"ruul eagletalon fraktion","är ruul med horden","ruul eagletalons lojalitet"}},["5abfc287"]={q="Varför är Ruul Eagletalon i Bloodhoof Village?",a="Ruul stannar i Bloodhoof Village för att skydda bosättningen och de närliggande slätterna från hot i trakten. Han anlitar dugliga resenärer för att minska antalet aggressiva Windfury-harpyor som tränger in på taurenfolkets marker.",al={"varför är ruul här","ruul eagletalon syfte","vad gör ruul i bloodhoof village"}}},fp="15,185,20.400.0,23.100.0,60.143.0,35.117.0"}
P.entries["npc:ruul-snowhoof"] = {n="Ruul Snowhoof",s="Ruul Snowhoof är en tauren-druid som hålls fången i Thistlefur Hold i norra Ashenvale. Instängd i björngestalt i en grov bur är han beroende av hordens äventyrare för att bli fri och föras i säkerhet.",h="Ruul Snowhoof är en tauren-druid som hålls fången i Thistlefur Hold i norra Ashenvale.",kw={"björngestalt","frihet åt ruul","ruul snowhoof","splintertree post","thistlefur-furbolgerna","thistlefur hold","yama snowhoof"},ang={["class:Druid"]="Att hitta en broder på cenarievägen som hålls fången i djurgestalt av korrumperade furbolger visar hur fördärvet sprider sig bland Ashenvales vilda djur och primitiva stammar.",["race:Tauren"]="Ruul tillhör den respekterade familjen Snowhoof. När du räddar honom får en av dina egna återvända levande till sin syster Yama vid Splintertree Post."},sec={{t="En björn i en bur",b="Ruul Snowhoof gav sig in i norra Ashenvale, men hamnade i klorna på de korrumperade Thistlefur-furbolgerna. När han blev tillfångatagen antog han formen av en mäktig björn, en förklädnad som fångvaktarna helt misstog för ett vilt djur. I stället för att döda honom på stället låste furbolgerna in honom i en träbur djupt inne i Thistlefur Hold och lät honom långsamt svälta. Försvagad och oförmögen att tryggt lämna sin form eller kämpa sig ut på egen hand väntar Ruul på att horden ska hjälpa honom att ta sig ut, besegra fångvaktarna och röja en väg genom hålan så att han kan återvända till sin syster, Yama Snowhoof, vid Splintertree Post."}},faq={{q="Varför är Ruul Snowhoof en björn i en bur?",a="Ruul är en tauren-druid som antog björngestalt när han ställdes inför Thistlefur-furbolgerna. Fångvaktarna trodde att han var ett riktigt vilt djur, inte en förvandlad druid, och låste in honom i en bur djupt inne i deras fäste.",al={"varför är ruul en björn","ruul snowhoof björngestalt","varför är han fången"}},{q="Varför dödar inte furbolgerna Ruul?",a="De korrumperade Thistlefur-furbolgerna valde att hålla Ruul fången i hans djurgestalt och låter honom av sin egen grymhet eller illvilja långsamt svälta i buren i stället för att döda honom genast.",al={"varför svälter ruul","vad vill furbolgerna med ruul"}},{q="Vart tar Ruul vägen efter att ha flytt från Thistlefur Hold?",a="När han har eskorterats förbi furbolgpatrullerna till säkerheten utanför Thistlefur Hold ber Ruul sina räddare att meddela hans syster, Yama Snowhoof, som är stationerad vid Splintertree Post, att han överlevt.",al={"vart tar ruul vägen","ruul snowhoofs destination"}},{q="Kan alliansspelare interagera med Ruul Snowhoof?",a="Nej. Ruul Snowhoof är lojal mot horden och erbjuder bara hordens äventyrare som hittar hans bur ett flyktuppdrag och hjälp.",al={"är ruul bara för horden","alliansen ruul snowhoof"}}},fx={["6802c209"]={q="Vem är Ruul Snowhoof?",a="Ruul Snowhoof är en tauren-druid som hålls fången djupt inne i Thistlefur Hold i Ashenvale. Han tillfångatogs av de fientliga furbolgerna i Thistlefur medan han var i björnform och har överlevt genom att dölja sin sanna natur för sina fångvaktare, som tror att han är ett vanligt djur. Trots sin dystra belägenhet håller han ut och förlitar sig på sin träning och inre styrka tills vänligt sinnade resenärer kan befria honom.",al={"vem är ruul","ruul snowhoof bakgrund","vem är björnen i thistlefur hold"}},f3e5b1ed={q="Vem är Ruul Snowhoof lojal mot?",a="Ruul är lojal mot Horde och delar taurenfolkets djupa kulturella och druidiska band. När han sitter fången i Thistlefur Hold litar han helt på Hordes hjältar, som ska öppna hans bur och eskortera honom förbi furbolgernas patruller till friheten. Ävent äventyrare från Alliance märker att han ignorerar dem och inte tar emot dem.",al={"är ruul lojal mot horde eller alliance","ruuls fraktion","ruul snowhoofs lojalitet"}},["503a6073"]={q="Vad vill Ruul Snowhoof?",a="Ruul vill inget hellre än att fly från sin bur och överleva furbolgernas långsamma svältande av honom. När han väl har befriats från sitt fängelse är hans omedelbara mål att kämpa sig ut ur hålan och meddela sina fränder att han överlevt. Han ber dem som hjälper honom att föra de goda nyheterna till hans familj i närheten.",al={"vad vill ruul","ruul snowhoofs mål","varför hjälpa ruul"}},ebe6887d={q="Vilka band har Ruul Snowhoof?",a="Ruul är bror till Yama Snowhoof, som för närvarande är stationerad vid Splintertree Post i Ashenvale. När han når säkerheten utanför Thistlefur Hold är hans främsta tanke att stilla hennes oro genom att skicka sina räddare för att berätta att han har undkommit sina fångvaktare med livet i behåll.",al={"ruul snowhoofs familj","ruuls syster","vem är ruul släkt med"}}},fp="13,206,16.511.0,38.169.0,38.151.0,50.138.0,49.109.0"}
P.entries["npc:rwag"] = {n="Rwag",s="I The Den lär Rwag ut de första stegen i en skurks hantverk. Orchen tränar nyanlända orcher och troll i smygande, list och fulspel i Durotars Valley of Trials, under Hordens uppsikt.",h="I The Den lär Rwag ut de första stegen i en skurks hantverk.",kw={"durotar","nartok","tjuv","rwag","the den","tränare","valley of trials"},ang={["class:Rogue"]="Som ung orc eller troll som är skurk i Valley of Trials möter du Rwag, din första mentor i skumraskaffärer. Han lär dig grundläggande anfallstekniker och hur du tyder hemliga chiffer.",["race:Orc"]="Som orc ser du i Rwag överlevnadens praktiska sida. Även i Thralls hedervärda nya Hord fortsätter skuggor och kallt stål att vara livsviktiga."},sec={{t="Dalens skuggor",b="Djupt inne i The Den tränar Rwag blivande skurkar, ficktjuvar och tjuvar innan de ger sig ut ur grottan och vidare in i Durotar. Den nya Horden hyllar krigisk heder och tapperhet på slagfältet, men Rwag vet att finkänslighet, gifter och en välplacerad dolk fortfarande är verktyg för att överleva i den obarmhärtiga öknen. Han håller ett öga på verksamheten i dalen och misstror de mörka utövarna som har sin tillflykt i grottan, särskilt häxmästaren Nartok."}},faq={{q="Vem är Rwag?",a="Rwag tränar orcher och troll som är skurkar inne i The Den i Valley of Trials. Han undervisar dem när de påbörjar sin träning i Durotar.",al={"vem är rwag","rwag valley of trials","orchtränare i tjuvkonst"}},{q="Var hittar jag Rwag?",a="Rwag finns djupt inne i The Den, en grotta uthuggen i de klippiga branterna i Durotars Valley of Trials. Där finns också flera andra klassinstruktörer.",al={"rwag plats","var finns rwag","hitta rwag"}},{q="Vad tycker Rwag om warlocksen i The Den?",a="Rwag misstror häxmästarna som delar The Den med honom, särskilt Nartok. Han håller noga uppsikt över häxmästaren.",al={"rwag nartok","varför misstror rwag warlocks","rwag encrypted parchment"}},{q="Vilka klasser tränar Rwag?",a="Rwag tränar skurkar i grundläggande tekniker som Eviscerate. På Shattered Hands begäran håller han ögonen på nya rekryter och vidarebefordrar allt som Handen kan behöva veta om dem.",al={"vad lär rwag ut","kan rwag träna mig"}}},fx={["864b6a89"]={q="Vem är Rwag lojal mot?",a="Rwag tjänar Horde och är stationerad i Valley of Trials, där han undervisar blivande orcher och troll i ficktjuveri. Hans djupare lojalitet ligger hos Shattered Hand, som han tror ska återföra Horde till dess forna glans, obehindrat av det han kallar krigshövdingens vekhet.",al={"rwags fraktion","är rwag lojal mot horde","vem tjänar rwag"}},c0621c2a={q="Vad vill Rwag?",a="Rwag strävar efter att vässa smygförmågan, slugheten och stridskonsten hos blivande skurkar som just har börjat sin bana i Valley of Trials. Han förväntar sig att hans elever ska bemästra ljudlösa steg, precisa slag och skarp vaksamhet, samtidigt som de håller ett vaksamt öga på opålitliga personer i närheten.",al={"vad vill rwag","rwags mål","rwags motiv"}},["4b9fa3b0"]={q="Varför är Rwag här?",a="Rwag har sin post i The Den så att han kan bedöma och undervisa nya rekryter som vill följa skuggornas väg. Durotar behöver spejare och diskreta klingor lika mycket som frontkrigare, och han ser till att de som har fallenhet för stöld och svek får ordentlig disciplin.",al={"varför är rwag i the den","rwags roll i valley of trials","varför är rwag i durotar"}},["0a3d842f"]={q="Vilka band har Rwag?",a="Rwag arbetar tillsammans med de andra klassmentorerna i Valley of Trials, men håller sig misstänksamt på avstånd från häxmästaren Nartok, som han öppet misstror. Hans band finns hos Hordes nätverk av skurktränare och de unga spejare som han skickar ut över Durotar.",al={"rwags kontakter","vem känner rwag","rwag och nartok"}}},fp="4,204,21.427.0,12.129.0,22.148.0,48.97.0,30.181.0"}
P.entries["npc:saelienne"] = {n="Saelienne",s="Innkeeper Saelienne sköter värdshuset på Craftsmen's Terrace i Darnassus. Hon erbjuder trötta resenärer och lokala hantverkare mat, dryck och en rofylld tillflykt med härdsten i hjärtat av nattalvernas huvudstad.",h="Innkeeper Saelienne sköter värdshuset på Craftsmen's Terrace i Darnassus.",kw={"craftsmen's terrace","darnassus","hallow's end","hearthstone","värdshusvärd","saelienne","teldrassil"},ang={["faction:Alliance"]="Alliance-sändebud och hantverkare som reser till Teldrassils avlägsna trädkrona förlitar sig på Saelienne för mat, dryck och en varm fristad med härdsten.",["race:NightElf"]="För nattalvernas äventyrare som återvänder från Teldrassils vilda utmarker erbjuder Saeliennes värdshus en välbekant härd bland hantverkarna i Darnassus."},sec={{t="Gästfrihet på terrassen",b="Mitt bland de livliga verkstäderna och handelsstånden på Craftsmen's Terrace erbjuder Innkeeper Saelienne en lugn viloplats för både invånare och besökare i Darnassus. Som härdens väktare tar hon hand om äventyrare från hela Kalimdor och bortom, och serverar nattalvernas vanliga förfriskningar tillsammans med varor som förts in till stadens hamn. Hennes värdshus är en viktig samlingsplats för hantverkare som söker vila efter långa timmar vid smedjan eller vävstolen."}},faq={{q="Var hittar jag Innkeeper Saelienne?",a="Saelienne finns på Craftsmen's Terrace i Darnassus, där hon driver det lokala värdshuset bland handelsinstruktörerna och hantverksbutikerna.",al={"saeliennes plats","var finns saelienne","darnassus värdshusvärd plats","värdshus på craftsmens terrace"}},{q="Vilka tjänster erbjuder Saelienne?",a="Hon arbetar som värdshusvärd och låter spelare binda sin Hearthstone till Darnassus. Hon säljer också olika sorters mat och dryck som återställer hälsa och mana.",al={"vad gör saelienne","saelienne försäljare","binda härdsten till darnassus"}},{q="Erbjuder Saelienne några säsongsuppdrag?",a="Under Hallow's End-festligheterna deltar Saelienne i högtidsfirandet och erbjuder Alliance-äventyrare uppdraget Dancing for Marzipan i utbyte mot högtidsgodis.",al={"saeliannes uppdrag","hallow's end saelienne","dancing for marzipan"}}},fx={["023ad64a"]={q="Vem är Saelienne?",a="Saelienne är en nattalvsvärdshusvärdinna som bor i Craftsmen's Terrace i Darnassus. Hon tar hand om resenärer och lokalbor och erbjuder mat, uppfriskande dryck och en rofylld plats där du kan binda din hearthstone under Teldrassils grenar.",al={"vem är saelienne","saeliennes identitet","innkeeper saelienne"}},bc46f8f9={q="Vem är Saelienne lojal mot?",a="Hon står stadigt på Darnassus och den större Alliance sida. Som värdshusvärdinna i hjärtat av nattalvernas huvudstad välkomnar hon alla allierade äventyrare som kommer till världsträdet och behöver vila och förnödenheter.",al={"saeliennes fraktion","är saelienne lojal mot alliance","saeliennes lojalitet"}},a41cab7b={q="Vad vill Saelienne?",a="Saelienne vill inget hellre än att sköta sitt värdshus och se till att resenärer som besöker Craftsmen's Terrace får tak över huvudet, mat och en bekväm säng. Utöver att erbjuda gästfrihet och handel håller hon sig borta från politik och konflikter.",al={"vad vill saelienne","saeliennes motiv","saeliennes mål"}},["28654c22"]={q="Varför är Saelienne i Darnassus?",a="Hon försörjer sig på att driva värdshuset i Craftsmen's Terrace och ta hand om hantverkarna, köpmännen och resenärerna som passerar genom området. Hennes post placerar henne mitt i hjärtat av Teldrassils livliga vardagshandel.",al={"varför är saelienne här","saelienne i craftsmen's terrace","varför är saelienne i darnassus"}}},fp="9,177,26.332.0,37.108.0,37.81.0,40.111.0"}
P.entries["npc:sally-whitemane"] = {n="High Inquisitor Whitemane",s="Whitemane är Scarlet Crusades High Inquisitor och leder verksamheten i Scarlet Monasterys katedral. Som mäktig prästinna av det heliga ljuset drivs hon av ett allt uppslukande hat mot de odöda, vilket ger korståget dess kompromisslösa fanatism. Tillsammans med Scarlet Commander Renault Mograine styr hon ordens militära och ideologiska kampanjer genom Lordaeron.",h="Whitemane är Scarlet Crusades High Inquisitor och leder verksamheten i Scarlet Monasterys katedral.",kw={"katedral","high inquisitor","raleigh the devout","renault mograine","sally whitemane","scarlet crusade","scarlet monastery","whitemane"},ang={["class:Paladin"]="För Silver Hands paladiner visar Whitemanes ledarskap den tragiska förvanskningen av Lorderaons försvarare, som övergav barmhärtighet och rättvisa till förmån för urskillningslösa utrensningar.",["class:Priest"]="Whitemane visar hur skrämmande mäktigt det heliga ljuset kan bli när det förenas med oböjlig fanatism. Hon är ett varnande exempel på hur övertygelse kan övergå i fanatisk hänsynslöshet.",["faction:Alliance"]="Whitemane var en gång medborgare i Alliansens Lordaeron, men hennes korståg angriper nu alla främlingar som närmar sig deras land. Det tvingar Southshores lojala invånare att konfrontera monstren som deras forna fränder har blivit.",["race:Undead"]="För Forsakna står Whitemane för Scarlet Crusades vägran att skilja mellan den viljelösa Scourge och odöda med fri vilja. Därför är hennes död avgörande för Undercitys överlevnad."},sec={{t="Korstågets High Inquisitor",b="Whitemane steg snabbt i Scarlet Crusades hierarki, blev dess High Inquisitor och tog befälet över Scarlet Monasterys storslagna katedral. Hon är känd för sitt skräckinjagande herravälde över helig magi och har blivit en av korstågets främsta symboler genom sin orubbliga övertygelse. Hon brukar det heliga ljuset som ett skoningslöst vapen mot alla som anses orena."},{t="Mål i katedralen",b="År 25 efter den tredje invasionen har Whitemanes fanatism skaffat henne fiender bland båda fraktionerna. I Southshore anser Raleigh the Devout att korståget har sjunkit så djupt i korruption och vansinne att det inte går att rädda, och kräver att Whitemane och Mograine undanröjs för att återupprätta ordens ursprungliga ideal. Samtidigt iscensätter dreadlord Varimathras i Undercity angrepp mot klostret för att krossa fanatikerna som verkar alldeles intill Forsaknas tröskel."}},faq={{q="Vem är High Inquisitor Whitemane?",a="Whitemane är Scarlet Crusades High Inquisitor. Från katedralen i Scarlet Monastery i Tirisfal Glades leder hon ordens andliga och inkvisitoriska verksamhet och strider sida vid sida med Commander Renault Mograine.",al={"whitemanes historia","vem är high inquisitor whitemane","scarlet monastery-boss"}},{q="Varför hatar Whitemane de odöda så mycket?",a="Hennes hat speglar Scarlet Crusades egen lära. Orden växte fram bland dem som överlevde Lorderaons fall för farsoten och de odöda, och betraktar varje odöd, vare sig den saknar medvetande eller har fri vilja, som en styggelse som måste utrotas. Whitemane brukar det heliga ljuset som ordens mest skoningslösa vapen i det kriget.",al={"varför hatar whitemane scourge","whitemanes bakgrund","whitemanes familj"}},{q="Varför vill Alliansen se Whitemane död?",a="Raleigh the Devout, en före detta korsfarare i Southshore, anser att Scarlet Crusade har förfallit till paranoia och vansinne. Han ber Alliansens hjältar att undanröja Whitemane och Mograine, så att orden kanske kan återgå till sitt hedervärda ursprung.",al={"raleigh the devout whitemane","varför ska alliansen döda whitemane","uppdraget in the name of the light"}},{q="Varför vill Horden se Whitemane död?",a="Varimathras och de Forsakna i Undercity ser Scarlet Crusade som en aktiv och fientlig närvaro alldeles utanför deras huvudstad. Dreadlorden beordrar att hon ska dö för att krossa klostrets ledarskap och undanröja ett omedelbart hot mot Forsaknas rike.",al={"varimathras whitemane-uppdrag","in i scarlet monastery","varför dödar horden whitemane"}},{q="Vilken relation har Whitemane till Renault Mograine?",a="Whitemane och Renault Mograine är de två ledarna för Scarlet Monastery. De strider sida vid sida i katedralen och delar ett nära band och en stark hängivenhet till korstågets kamp mot de odöda.",al={"whitemane och mograine","commander mograine och whitemane"}}},fx={f63bdc05={q="Vem är High Inquisitor Whitemane lojal mot?",a="Whitemane är en fanatisk ledare för Scarlet Crusade och tjänstgör som dess höginkvisitor. Hon svär ingen trohet till Alliance eller Horde och betraktar utomstående med extrem misstänksamhet och fanatism. Whitemane är djupt lojal mot korstågets dogmer och strider sida vid sida med Commander Renault Mograine för att rensa bort alla som står i deras väg.",al={"whitemanes fraktion","vem strider whitemane för","whitemanes lojalitet"}},["89d62c4b"]={q="Vad vill High Inquisitor Whitemane?",a="Whitemane vill utrota de odöda fullständigt. Precis som resten av Scarlet Crusade ser hon varje odöd varelse, vare sig det är en viljelös Scourge eller en självständig Forsaken, som en styggelse. Hon finner sitt enda syfte i att rensa bort Scourge och alla hon anser vara besmittade av odödheten.",al={"whitemanes mål","vad vill whitemane","whitemanes drivkraft"}},["04c4cc89"]={q="Varför är High Inquisitor Whitemane här?",a="Som höginkvisitor leder Whitemane Scarlet Crusades verksamhet från djupet av katedralen i Scarlet Monastery. Där övervakar hon försvaret av deras nordliga fristad i Lordaeron, samlar korsfararna och rensar bort alla som inkräktar på deras heliga fäste.",al={"varför är whitemane i klostret","varför är whitemane i katedralen","varför är whitemane här"}},["7daae460"]={q="Varför är High Inquisitor Whitemane berömd eller fruktad?",a="Whitemane är fruktad för sin obevekliga, fanatiska iver och sin mäktiga behärskning av helig magi. Som Scarlet Crusades höginkvisitor har hon fått ett skräckinjagande rykte för att skoningslöst rensa bort misstänkt korruption och återuppväcka fallna allierade, däribland Commander Mograine, mitt i striden.",al={"varför är whitemane fruktad","whitemanes rykte","varför är whitemane berömd"}}},fp="25,360,30.360.0,24.444.1,33.232.0,43.291.0,42.246.0,39.253.0,55.207.0"}
P.entries["npc:salma-saldean"] = {n="Salma Saldean",s="På Saldean's Farm håller Salma Saldean ett välkomnande ställe öppet för resenärer. Hon och hennes make, Farmer Saldean, sköter gården i Westfall, där banditer hotar gårdarna och Stormwind har övergett regionen. Hon erbjuder måltider i utbyte mot hjälp på gården.",h="På Saldean's Farm håller Salma Saldean ett välkomnande ställe öppet för resenärer.",kw={"farmer saldean","goretusk liver pie","saldean's farm","salma saldean","gryta","westfall","westfall stew"},ang={["faction:Alliance"]="Salma visar den trotsiga beslutsamhet som präglar alliansens gårdsägare, som håller fast vid sin försörjning trots kronans försummelse.",["profession:Cooking"]="Salma Saldean erbjuder kockar som reser genom Westfall praktiska recept, däribland Westfall Stew och Goretusk Liver Pie, tillagade med lokala djur.",["race:Human"]="Som mänsklig resenär får du på Salmas gård en inblick i de umbäranden som Stormwinds vanliga folk möter bortom huvudstadens befästa murar."},sec={{t="Gästfrihet i ett hårt land",b="Salma Saldean välkomnar resenärer till en gård som stått kvar medan grannarnas gårdar har brunnit eller fallit för Defias Brotherhood. En mustig gryta står på spisen, och hon söker dugliga händer som kan hjälpa till på gården."},{t="Mat på bordet",b="Salma ger sin familj och sina besökare mat av det som Westfall erbjuder. Hon lär resenärer att laga Goretusk Liver Pie och Westfall Stew med vildsvin, gamar, murlocer och vild okra."}},faq={{q="Vem är Salma Saldean?",a="Salma Saldean driver jordbruk på Saldean's Farm i centrala Westfall tillsammans med sin make. Hon ger resenärer mat och tröst samtidigt som hon försöker hålla gården igång medan regionen faller samman.",al={"vem är salma","salma saldeans bakgrund","saldean gårdsfru"}},{q="Var finns Salma Saldean?",a="Salma finns utanför sitt boningshus på Saldean's Farm, längs vägen i centrala Westfall, strax norr om vägkorsningen mot Sentinel Hill.",al={"salmas plats","var finns salma saldean","var finns saldean's farm"}},{q="Vilka recept lär Salma Saldean ut?",a="Salma lär resenärer att laga Goretusk Liver Pie och Westfall Stew med ingredienser från Westfalls djurliv.",al={"recept på westfall stew","salmas mat","goretusk liver pie"}},{q="Varför är det så svårt för familjen Saldean att hitta hjälp?",a="Det är svårt att hitta hjälp eftersom bönder och arbetare har flytt undan plundrande banditer, lössläppta skördegolemer och Stormwinds frånvarande kungliga armé. De få gårdsägare som är kvar har ont om folk.",al={"varför övergiven gård","varför behövs hjälp på saldeans gård","övergiven gård i westfall"}},{q="Hur överlever familjen Saldean Defias Brotherhood?",a="Familjen Saldean förlitar sig på förbipasserande äventyrare och sin egen uthållighet för att försvara sin egendom. Faran omger dem, men de vägrar lämna sin mark och sitt hem.",al={"saldean defias","varför har gården inte brunnit ner"}},{q="Vem är Salmas make?",a="Salma är gift med Farmer Saldean, som arbetar tillsammans med henne för att hantera felande skördeväktare och lössläppta bestar.",al={"salmas make","farmer saldean"}}},fx={["4311c40a"]={q="Vem är Salma Saldean lojal mot?",a="Salma står stadigt på Westfalls hederliga folk och kämpande bönders sida. Även om hon i grunden är lojal mot Alliance har hon och hennes make lämnats att klara sig själva utan hjälp från Stormwind. De sätter allt sitt hopp till att grannarna på gårdarna ställer upp för varandra.",al={"salma saldeans fraktion","vem stöder salma","vilken sida står salma saldean på"}},["31948cda"]={q="Vad vill Salma Saldean?",a="Salma vill hålla familjens gård i gång och se till att alla som passerar får en varm måltid och någon som lyssnar. Eftersom motgångar och banditer har drivit bort de flesta arbetsföra är hon angelägen om hjälp med att samla ingredienser som goretusk-lever, så att hon kan försörja dem som håller ut i Westfall.",al={"vad vill salma","salma saldeans mål","vad behöver salma"}},f65c3c8f={q="Varför är Salma Saldean här?",a="Salma stannar på Saldean's Farm eftersom det är hennes hem. Trots att grannarnas nybyggare flydde den tilltagande oron och laglösheten i området vägrade hon och hennes make att överge sin mark. De är fast beslutna att bruka jorden och erbjuda trygghet åt alla som behöver tak över huvudet.",al={"varför är salma i westfall","varför stanna på saldean's farm","varför är salma saldean här"}}},fp="13,229,26.225.0,25.182.0,21.174.0,31.146.0,38.111.0,48.185.0,51.163.0,23.117.0"}
P.entries["npc:sara-balloo"] = {n="Sara Balloo",s="Sara Balloo är en sörjande dvärgänka som bor i Military Ward i Ironforge. Hon tillbringar dagarna med att sörja sin bortgångne make, Sully Balloo, och klamrar sig fast vid varje minne eller meddelande från hans sista dagar i tjänst.",h="Sara Balloo är en sörjande dvärgänka som bor i Military Ward i Ironforge.",kw={"dun morogh","ironforge","magni bronzebeard","military ward","sara balloo","sully balloo","änka"},ang={["faction:Alliance"]="När Sara får besked får familjen till en Alliance-soldat ett avslut, och de tragiska familjeförhållandena bakom striderna över Azeroth blir tydliga.",["race:Dwarf"]="För dvärgar som passerar genom Military Ward är Sara Balloo en gripande påminnelse om den personliga börda som vilar på familjer vars anhöriga ger sig av för att försvara Khaz Modan."},sec={{t="En änkas vaka",b="Mitt i det livliga Military Ward i Ironforge är Sara Balloo en sorgsen kontrast till vapenskrammel och militärövningar. Hennes make, Sully Balloo, stupade i strid långt hemifrån och lämnade henne ensam med minnen och en kvarhängande sorg. För Sara kommer avslutet först när ord återfinns: ett sista brev som förmedlar Sullys kärlek över bergen från platsen där han dog."},{t="En vädjan om att bli ihågkommen",b="Sara vill inte låta sin makes offer tyst falla i glömska och söker mer än tröst. Med innerliga vädjanden ber hon King Magni Bronzebeard se till att Sully och fallna soldater som han hedras officiellt och blir ihågkomna av tronen, så att vanliga dvärgfamiljers uppoffringar aldrig glöms."}},faq={{q="Vem är Sara Balloo?",a="Sara Balloo är en dvärgkvinna som bor i Military Ward i Ironforge. Hon är änka efter Sully Balloo, en stupad dvärgsoldat.",al={"sara balloo","vem är sara balloo","sara balloo ironforge"}},{q="Var hittar jag Sara Balloo?",a="Hon finns i Military Ward i bergsstaden Ironforge, nära övningsplatserna och kasernerna.",al={"var finns sara balloo","sara balloos plats","hitta sara balloo"}},{q="Vad hände med hennes make?",a="Hennes make, Sully Balloo, dog under sin militärtjänst. Hans tillhörigheter och ett sista, vattenskadat brev var förlorade tills en äventyrare återfann dem.",al={"sara balloos make","vem är sully balloo","vad hände med sully"}},{q="Vad gör Sara med Sullys brev?",a="Efter att ha läst sin bortgångne makes innerliga ord skriver Sara en vädjan till King Magni Bronzebeard och ber om att Sullys offer ska erkännas och ihågkommas på rätt sätt.",al={"sully balloos brev","sara balloos vädjan","vad vill sara balloo"}}},fx={["736253da"]={q="Vem är Sara Balloo lojal mot?",a="Sara Balloo är en lojal medborgare i Ironforge och anhängare av Alliance. Hennes avlidne make, Sully Balloo, dog i dvärgkungadömets tjänst medan hans enhet bevakade Thandol Span. Hon stannar bland sitt folk under King Magni Bronzebeards styre.",al={"sara balloos fraktion","är sara balloo lojal mot alliance","vem tjänar sara balloo"}},["658d468d"]={q="Varför är Sara Balloo i Military Ward?",a="Sara bor i Military Ward i Ironforge, bland rikets soldater och veteraner. Efter att ha förlorat sin make Sully i kriget håller hon sig nära bergsstadens civila och militära hjärta, där minnet av dem som föll för att försvara riket hedras.",al={"varför är sara balloo i ironforge","varför är sara balloo här","sara balloo military ward"}}},fp="11,98,15.322.0,21.219.1,19.119.0,29.94.0,29.138.1,38.134.1"}
P.entries["npc:sara-timberlain"] = {n="Sara Timberlain",s="På Eastvale Logging Camp syr Sara Timberlain utrustning åt Stormwind Army. Hon tillverkar användbar krigsmateriel av återvunnet tyg och läder.",h="På Eastvale Logging Camp syr Sara Timberlain utrustning åt Stormwind Army.",kw={"eastvale","linne","avverkningsläger","sara timberlain","sömmerska","stormwind army","skräddare"},ang={["faction:Alliance"]="Avlägsna bosättningar som Eastvale hjälper till att försvara riket, eftersom lokala hantverkare förser den underbemannade Stormwind Army med enkel rustning.",["profession:Tailoring"]="Sara visar hur skräddare vid gränsen tillverkar användbara plagg av grovt linnetyg och banditkläder åt militären."},sec={{t="Nål och tråd vid gränsen",b="Sara Timberlain arbetar med nål och tråd utanför en liten stuga på västra kanten av Eastvale Logging Camp. Yxor ljuder genom lägret när arbetarna fäller träd. Eastvale ligger långt från bebodda trakter, men vargar och murlocer stryker omkring i närheten, och Sara erbjuder fortfarande resande gästfrihet. Hon förvandlar linnetygsrester och tillvaratagna bandanor till slitstark utrustning. Hennes skicklighet har gett henne officiellt erkännande och uppdrag att leverera tyg- och läderutrustning till Stormwinds militärstyrkor."}},faq={{q="Vem är Sara Timberlain?",a="Sara Timberlain är en skicklig sömmerska vid Eastvale Logging Camp i Elwynn Forest. Hon tillverkar praktisk utrustning av återbrukade tyger och har kontrakt på att leverera till Stormwind Army.",al={"vem är sara timberlain","sara timberlain","skräddare i eastvale"}},{q="Var hittar jag Sara Timberlain?",a="Sara Timberlain sitter utanför ett hus på västra sidan av Eastvale Logging Camp, i östra Elwynn Forest längs vägen till Redridge.",al={"sara timberlains plats","var finns sara timberlain","timberlains hus"}},{q="Varför samlar Sara tyg åt armén?",a="Stormwind Army förlitar sig på lokala hantverkare för att underhålla sina utrustningsförråd. Sara använder återvunnet tyg, bland annat linne som äventyrare samlar in, för att tillverka slitstarka plagg och rustningsfoder åt rikets soldater.",al={"varför behöver sara linne","stormwind armys rustning","uppdrag med tyg- och läderrustning"}}},fx={["693a4fc8"]={q="Vilken sida står Sara Timberlain på?",a="Sara är lojal mot kungariket Stormwind och Alliansen. Hon är stationerad vid Eastvale Logging Camp och arbetar direkt för rikets försvar genom att utföra skräddarbeställningar åt Stormwind Army, så att soldaterna får slitstark rustning.",al={"sara timberlains fraktion","vem tjänar sara timberlain","sara timberlain alliance"}},["94680b13"]={q="Vad vill Sara Timberlain ha?",a="Sara behöver råmaterial för hantverk, särskilt linnetyg i tygstycken som hon kan återvinna från lokala banditer, för att fortsätta sitt skrädderi. Genom att förvandla återvunnet tyg till sydda varor och rustningar hjälper hon till att förse rikets stridande styrkor och belönar resande som kommer med material.",al={"vad behöver sara timberlain","sara timberlains material","varför vill sara ha linne"}},["414da08e"]={q="Varför är Sara Timberlain vid lägret?",a="Sara bor på den västra sidan av Eastvale Logging Camp, där hon utövar sitt hantverk långt från Stormwind Citys trånga gator. Utposten vid gränsen ger henne en lugn plats att arbeta med nål och tråd, samtidigt som hon har nära till resande och lokala leverantörer som samlar in materialet hon behöver.",al={"varför är sara i eastvale","sara timberlain eastvale logging camp","varför är sara timberlain här"}},["59756f86"]={q="Vilka band har Sara Timberlain?",a="Sara har nära band till Stormwind Army, som officiellt har gett henne i uppdrag att tillverka både tyg- och läderrustningar åt sina trupper. Hon arbetar också tillsammans med de lokala skogsarbetarna och timmerhuggarna vid Eastvale Logging Camp.",al={"sara timberlains kontakter","vem arbetar sara timberlain åt","sara timberlain stormwind army"}},["42dfe0df"]={q="Varför är Sara Timberlain berömd?",a="Sara är känd i hela trakten för sin enastående skicklighet som skräddare, särskilt sin ovanliga förmåga att förvandla grova, återvunna tygrester till välgjorda kläder och pålitlig rustning värdig rikets stående armé.",al={"sara timberlains rykte","är sara timberlain välkänd","vad är sara timberlain känd för"}}},fp="15,137,26.462.0,23.178.0,33.149.0,41.212.0"}
P.entries["npc:scarlet-commander-mograine"] = {n="Scarlet Commander Mograine",s="Scarlet Commander Mograine leder styrkorna som är förlagda i katedralen i Scarlet Monastery. Som en fanatisk paladin i Scarlet Crusade försvarar han kapellet tillsammans med High Inquisitor Whitemane. Både Horde och Alliance riktar in sig på honom för att störa fanatikerna som hotar Tirisfal Glades och de omgivande länderna.",h="Scarlet Commander Mograine leder styrkorna som är förlagda i katedralen i Scarlet Monastery.",kw={"katedral","crusader's chapel","mograine","paladin","scarlet commander mograine","scarlet crusade","scarlet monastery","whitemane"},ang={["class:Paladin"]="Mograine förkroppsligar den tragiska förvanskningen av paladinens kall: han vrider heliga löften om beskydd och rättfärdighet till hänsynslös, obeveklig fanatism.",["faction:Alliance"]="Även om Scarlet Crusade en gång hade gemensamma intressen med Alliance inser ledare i Southshore och Stormwind att fanatiska befälhavare som Mograine har sjunkit ner i våldsamt vansinne.",["race:Undead"]="För Forsaken är Commander Mograine Scarlet Crusades vassaste klinga. Hans styrkor finns alldeles intill Undercity och hotar deras överlevnad i Tirisfal."},sec={{t="Kapellets försvarare",b="Scarlet Commander Mograine är stationerad i det storslagna Crusader's Chapel, i hjärtat av Scarlet Monastery, och för befäl över Scarlet Crusades permanenta garnison. Han brukar en paladins heliga krafter med våldsam hängivenhet och förlitar sig på vedergällning, gudomliga sköldar och bedövande slag för att krossa alla som Crusade anser vara fördärvade eller orena."},{t="Ett mirakulöst band",b="Mograines försvar av kapellet hänger oupplösligt samman med High Inquisitor Whitemane. Om en anfallande styrka får befälhavaren på knä träder Whitemane fram från det bakre helgedomsrummet för att vända striden. Hon åkallar det heliga ljuset, oskadliggör inkräktarna på ett ögonblick och återuppväcker Mograine från de döda, så att fienderna tvingas möta båda befälhavarna i en desperat, samtidig strid."}},faq={{q="Var hittar man Scarlet Commander Mograine?",a="Han finns i katedralflygeln i Scarlet Monastery, i nordöstra Tirisfal Glades. Du hittar honom framför altaret i Crusader's Chapel.",al={"mograines plats","var finns mograine","mograines rum i scarlet monastery"}},{q="Vilken roll har Mograine i Scarlet Crusade?",a="Han är militär befälhavare över Scarlet Crusades styrkor i klostrets garnison och leder dess paladiner och soldater tillsammans med High Inquisitor Whitemane.",al={"vem är commander mograine","mograines grad","vad gör mograine"}},{q="Hur slåss han?",a="Mograine slåss som en tung närstridspaladin. Han bedövar motståndarna med Hammer of Justice, utför Crusader Strikes, skyddar sig med Retribution Aura och förlitar sig på Divine Shield när han pressas till bristningsgränsen.",al={"mograines förmågor","mograines strid","hur man slåss mot mograine"}},{q="Varför återupplivar High Inquisitor Whitemane honom?",a="Whitemane och Mograine har ett starkt band och slåss tillsammans som klostrets ledare. När Mograine faller i strid ingriper Whitemane, söver angriparna med sin magi och återuppväcker Mograine med full styrka.",al={"whitemane återupplivar mograine","återuppväcks mograine","återuppväcka mograine"}},{q="Varför slåss Alliance och Horde mot honom?",a="Scarlet Crusade ser alla utomstående, levande som odöda, som bärare av fördärv. Både Alliance och Forsaken skickar mästare för att anfalla katedralen och avrätta dess ledare, så att Crusades fanatiska närvaro i Lordaeron kan oskadliggöras.",al={"varför döda mograine","scarlet commander-uppdrag","i ljusets namn"}},{q="Läker Mograine sig själv under striden?",a="Ja, när det verkligen behövs. Förutom Divine Shield och sina närstridsattacker kan han använda Lay on Hands för att återställa sin hälsa helt, och High Inquisitor Whitemane ger ytterligare läkande när hon går in i striden.",al={"kan mograine läka","mograines läkande"}}},fx={a3e1ab86={q="Vilken sida står Scarlet Commander Mograine på?",a="Commander Mograine strider enbart för Scarlet Crusade. Orden bestod en gång av överlevande försvarare från Lordaeron och riddare från Silver Hand, men står nu helt isolerad. Under Mograines militära befäl betraktar de alla utomstående, både Horde och Alliance, som pestsmittat avskum och fiender till det heliga ljuset.",al={"vem strider mograine för","scarlet commander mograines fraktion","är mograine alliance"}},["741d495f"]={q="Varför är Scarlet Commander Mograine vid klostret?",a="Scarlet Monastery är ett av Scarlet Crusades främsta fästen i Tirisfal Glades. Mograine håller till i Crusader's Chapel i katedralen, där han leder garnisonens försvar tillsammans med High Inquisitor Whitemane och vaktar hjärtat av deras heliga fästning.",al={"varför är mograine i scarlet monastery","varför är mograine där","vad gör mograine här"}}},fp="26,332,22.349.0,17.393.1,46.170.0,47.169.0,18.212.0,46.244.0,44.249.0,48.203.0"}
P.entries["npc:scooty"] = {n="Scooty",s="Scooty är en gobliningenjör verksam i den livliga pirathamnen Booty Bay. Han utropar sig själv till mästare på ingenjörskonst och sköter en känslig transponderanordning som är direkt kopplad till en experimentell teleporter i den fallna staden Gnomeregan. Hans konstruktioner ger Hordens agenter en direkt, om än farlig, teknisk genväg rakt in i hjärtat av Dun Morogh.",h="Scooty är en gobliningenjör verksam i den livliga pirathamnen Booty Bay.",kw={"booty bay","gnomeregan","goblin","scooty","stranglethorn","teleporter","transponder"},ang={["faction:Horde"]="Scooty ger Horden en oumbärlig genväg till Gnomeregan och låter dina anfallstrupper kringgå Alliances järnhårda försvar i Dun Morogh.",["profession:Engineering"]="Andra uppfinnare kommer att uppskatta Scootys djärva tillämpning av transponderfysik, även om gobliners vanliga nonchalans inför grundläggande säkerhetsrutiner gör varje aktivering till en chansning."},sec={{t="Booty Bays teleporteringsexpert",b="Mitt bland kajerna och verkstäderna i Booty Bay håller Scooty hov som en av Steamwheedle Cartels mest ambitiösa uppfinnare. Medan vanliga gobliner är besatta av krut och sprängämnen riktade Scooty sin uppmärksamhet mot omedelbar molekyltransport. Genom att kalibrera komplicerade transpondersystem upprätthåller han en direkt fungerande länk till en teleporteringsplatta inne i Gnomeregan. Hordens styrkor förlitar sig tungt på Scootys uppfinningar när de vill ta sig in i gnomernas underjordiska fäste och helt kringgå Alliance farliga territorium."},{t="Gnomiska manicker och goblinrisker",b="Att underhålla experimentella goblinteleportörer är sällan långtråkigt. Scooty och hans partner Sovik byggde Transpolyporter 6000 efter att ha hört talas om en ny gnomisk anordning i Gnomeregan, och enligt Scootys eget glada erkännande har den bara exploderat ett dussintal gånger eller så. Trots de uppenbara fysiska farorna med att dematerialiseras tvärs över kontinenter förblir Scooty helt övertygad om sitt geni. Han avfärdar varje katastrofalt mekaniskt fel som ett mindre hinder på vägen mot sann innovation."}},faq={{q="Vem är Scooty?",a="Scooty är en gobliningenjör i Booty Bay som gör anspråk på titeln mästeringenjör. Han underhåller och kalibrerar Goblin Transponder-nätverket, som kopplar Booty Bay direkt till en experimentell teleporteringsplatta djupt inne i Gnomeregan.",al={"vem är scooty","scootys historia","scooty npc","scooty i booty bay"}},{q="Varför har Scooty en teleporter till Gnomeregan?",a="Scooty upprättade en länk till en experimentell teleporteringsplatta i Gnomeregan för att möjliggöra direkt färd till gnomernas stad. För Horden erbjuder hans anordning en viktig bakväg in i Dun Morogh, så att de slipper strida sig igenom Alliances tungt befästa hemländer.",al={"varför teleporter till gnomeregan","hur fungerar scootys teleporter","scootys portal till gnomer"}},{q="Var finns Scooty?",a="Scooty finns i Booty Bay, den neutrala goblinhamnstaden vid den södra spetsen av Stranglethorn Vale, där han arbetar.",al={"var finns scooty","scootys plats","hitta scooty"}},{q="Är det säkert att använda Scootys teleporter?",a="Gobliningenjörskonst är ökänd för oförutsägbara fel, och Scootys teleporter är inget undantag. Den skickar äventyrare till Gnomeregan, men mekaniska missöden och felkalibrerade transpondrar utgör en ständig fara när man litar på hans instabila teknik.",al={"är scooty säker","säker teleporter","teleporterrisker"}}},fx={["6ce6cf89"]={q="Vilken sida står Scooty på?",a="Scooty verkar från Booty Bay som en del av den neutrala goblinverksamheten. Han erbjuder sina ingenjörstjänster och sin experimentella transportanordning till alla resande som vill göra affärer, oavsett fraktionstillhörighet.",al={"scootys fraktion","är scooty horde eller alliance","scootys lojalitet"}},["04182db4"]={q="Varför är Scooty i Booty Bay?",a="Från Booty Bay får Scooty tillgång till oberoende handelsnätverk och nyfikna äventyrare, långt från fastlandets myndigheters inblandning. Här kan han sköta sitt transpondernätverk och experimentera med långdistans-teleportering i goblinstil i sin egen takt.",al={"varför är scooty här","varför är scooty i booty bay","vad förde scooty hit"}}},fp="6,264,32.405.0,31.423.0,14.224.0,48.245.0,24.93.0,34.174.0"}
P.entries["npc:scout-riell"] = {n="Scout Riell",s="Vid Sentinel Hill håller Scout Riell uppsikt över Westfall från vakttornets tak. Hon tjänar Folkets milis, spårar Defias Brotherhood och ber resande att ta med banditernas röda sidenscarfar tillbaka.",h="Vid Sentinel Hill håller Scout Riell uppsikt över Westfall från vakttornets tak.",kw={"defias brotherhood","folkets milis","röda sidenscarfar","riell","scout riell","sentinel hill","torn","westfall"},ang={["faction:Alliance"]="För Alliansens hjältar visar Scout Riell Westfalls dystra verklighet: dess övergivna folk måste anlita legosoldater för att bekämpa det växande hotet från Defias Brotherhood.",["profession:Tailoring"]="Skräddare kan känna igen att Defias karakteristiska röda masker är gjorda av äkta siden, ett dyrt tyg för vanliga stråtrövare på landsbygden."},sec={{t="Ögon över Westfall",b="Scout Riell håller uppsikt över slätterna från stentornet vid Sentinel Hill, där banditväsen och skördegolemer hotar Westfall. Stormwinds kungliga armé är frånvarande, och kronan vägrar hjälp, så Folkets milis får försvara regionen. Från tornets tak följer Riell Defias Brotherhoods rörelser och samlar bevis för deras brott. Hon ber förbipasserande resande att ta röda sidenscarfar från banditerna."}},faq={{q="Var hittar jag Scout Riell?",a="Scout Riell håller uppsikt från taket på stenvakttornet vid Sentinel Hill i Westfall. Gå uppför trapporna för att nå henne.",al={"riells plats","var finns scout riell","hitta riell"}},{q="Vad ber Scout Riell äventyrare att göra?",a="Riell ber resande att samla in röda sidenscarfar från Defias ficktjuvar, stråtrövare och smugglare i Westfall och The Deadmines. Scarfarna bevisar att laglösa har dödats.",al={"riells uppdrag","vilket uppdrag ger riell","uppdrag med röda sidenscarfar"}},{q="Varför samlar Riell in röda sidenscarfar?",a="Den röda sidenscarfen kännetecknar en medlem av Defias Brotherhood. När de samlas in blir det bevis för att banditerna som terroriserar Westfalls gårdar blir färre, samtidigt som deras enande symbol tas ifrån dem.",al={"varför scarfar","varför röda sidenscarfar","defiasmasker"}},{q="Vem arbetar Scout Riell för?",a="Riell tjänar Folkets milis, en frivillig försvarsstyrka som Gryan Stoutmantle bildade för att skydda Westfall efter att Stormwinds adelshus blundat för provinsens nöd.",al={"riells fraktion","tillhör riell stormwinds armé","vem tjänar riell"}}},fx={c25141c7={q="Vem är Scout Riell?",a="Scout Riell är en mänsklig spejare som tjänar Sentinel Hill och Westfalls försvar. Hon är stationerad högt uppe i tornet med utsikt över trakten och håller vakt över landsbygden. Hon bevakar Defias Brotherhoods rörelser och samordnar sig med lokala försvarare för att slå tillbaka mot de laglösa som hotar jordbruken.",al={"vem är riell","scout riells bakgrund","vem är scout riell"}},["2f6a5f48"]={q="Varför är Scout Riell stationerad här?",a="Riell håller till högst upp i Sentinel Hills torn för att spana över Westfall. Från sin upphöjda utsiktspunkt kan hon söka av slätterna efter banditverksamhet, följa Defias Brotherhoods utbredning och värva förbipasserande äventyrare till att ta striden direkt till tjuvarna som plågar provinsen.",al={"varför är scout riell här","varför är riell i westfall","syftet med riells plats"}},f57d6b81={q="Vilka band har Scout Riell?",a="Riell tjänstgör tillsammans med Gryan Stoutmantle och People's Militia, som är stationerad vid Sentinel Hill. Tillsammans med sina spejarkamrater och vaktposter ingår hon i Westfalls hårt ansatta lokala försvar. De förlitar sig på frivilliga milismän och modiga äventyrare för att skydda rikets gränser när kungliga trupper saknas.",al={"vilka känner scout riell","riells fraktionsband","riells allierade"}}},fp="11,215,18.247.0,29.118.0,44.177.1,41.185.0,30.206.0"}
P.entries["npc:scout-thaelrid"] = {n="Argent Guard Thaelrid",s="Argent Guard Thaelrid är en sårad nattalvsspejare som Argent Dawn skickade till de översvämmade ruinerna i Blackfathom Deeps. Han är fångad nära Pool of Ask'ar och bevittnar den mörka alliansen mellan naga och kulten Twilight's Hammer.",h="Argent Guard Thaelrid är en sårad nattalvsspejare som Argent Dawn skickade till de översvämmade ruinerna i...",kw={"aku'mai","argent dawn","ashenvale","blackfathom deeps","pool of ask'ar","spejaren thaelrid","thaelrid","twilight lord kelris"},ang={["faction:Alliance"]="Alliansens spejare som skickats till Ashenvale följer upp Thaelrids försvinnande. De vill skydda The Zoram Strand och stödja Argent Dawns neutrala arbete.",["faction:Horde"]="Trots att Thaelrid är en nattalv är han lojal mot Argent Dawn. Alla äventyrare som är villiga att slå till mot Twilight's Hammer och rena grottan kan därför hjälpa honom.",["race:NightElf"]="För nattalverna är det en bitter skymf att se heliga, uråldriga tempelområden som Blackfathom vanhelgas av naga och domedagskulter. Thaelrid står för sitt folks vaka över Kalimdors djupaste sår."},sec={{t="Argent Dawns ögon",b="När märkliga rapporter började sippra ut från The Zoram Strand om vidriga riter djupt under havet väcktes Argent Dawns intresse. Orden vakar över Azeroth efter växande ondska och onaturlig fördärvning och skickade spejaren Thaelrid för att ta sig in i Blackfathom Deeps. Hans uppdrag var enkelt: bedöma hotets omfattning, hålla uppsikt över rörelserna i det översvämmade templet och rapportera tillbaka, så att Argent Dawn kunde avgöra var hjälpen behövdes som mest."},{t="Ett greppande mörker",b="Thaelrid upptäckte snabbt att ryktena inte kom i närheten av den fasansfulla verkligheten. Ruinerna under jord hyser en ohelig pakt mellan vilda naga och domedagsfanatikerna i Twilight's Hammer. Djupt inne i salarna utför kultister under Twilight Lord Kelris befäl blodsoffer för att föda hydran Aku'mai och förhandlar med uråldriga fasor om mörk kraft. Innan Thaelrid hann föra varningen till ytan blev han svårt sårad och avskuren från omvärlden, strandsatt nära Pool of Ask'ar."}},faq={{q="Vem är Argent Guard Thaelrid?",a="Han är en nattalvsagent i Argent Dawn. Han fick i uppdrag att infiltrera Blackfathom Deeps längs Ashenvales kust och samla information om de lömska krafter som samlas där nere.",al={"vem är thaelrid","thaelrids historia","thaelrids bakgrund"}},{q="Varför är Thaelrid fångad i Blackfathom Deeps?",a="När Thaelrid rekognoscerade det väldiga grottemplet blev han upptäckt och svårt sårad av dem som bor där. Oförmögen att ensam kämpa sig tillbaka till ytan sökte han skydd nära Pool of Ask'ar.",al={"varför är han fast","hur blev han sårad","varför håller thaelrid på att dö"}},{q="Vad upptäckte Thaelrid i djupet?",a="Thaelrid undersöker Twilight's Hammers verksamhet i Blackfathom Deeps, där kultens närvaro hotar det uråldriga templet och dem som tar sig in.",al={"vad hittade thaelrid","vad gör kultisterna","blackfathoms hemligheter"}},{q="Vem arbetar Thaelrid för?",a="Han tillhör Argent Dawn, den neutrala organisation som bekämpar fördärv, ondska och apokalyptiska hot i hela Azeroth, oavsett fraktionsgränser.",al={"thaelrids fraktion","tillhör thaelrid argent dawn","tillhör thaelrid alliansen"}},{q="Vad ber Thaelrid äventyrare att göra?",a="Thaelrid kan inte lämna sitt gömställe och ber därför modiga äventyrare att sätta stopp för slakten genom att döda Twilight Lord Kelris och hämta kultledarens huvud som bevis på att hotet är undanröjt.",al={"thaelrids uppdrag","blackfathom-uppdrag om skurkstreck","vad vill han"}},{q="Var hittar man Thaelrid?",a="Han ligger skadad i en avskild nisch nära Pool of Ask'ar, strax bortom de översvämmade yttre grottorna i Blackfathom Deeps.",al={"var finns thaelrid","thaelrids plats","spejare vid pool of ask'ar"}}},fx={["879268fe"]={q="Vilka band har Argent Guard Thaelrid?",a="Argent Guard Thaelrid lyder direkt under Argent Dawn. Orden gav honom i uppdrag att hålla utkik efter hotande ondska över hela Azeroth, och skickade honom till det översvämmade templet Blackfathom Deeps för att kontrollera oroväckande rapporter om kulten Twilight's Hammer och dess nyfunna naga-allierade.",al={"thaelrids band","vem lyder thaelrid under","scout thaelrid argent dawn"}}},fp="21,196,23.335.0,19.448.1,29.163.0,49.186.0,41.193.0,27.146.0,41.149.0,28.127.0"}
P.entries["npc:searn-firewarder"] = {n="Searn Firewarder",s="I Grommash Hold vägleder Searn Firewarder hordens shamaner mot elementen.",h="I Grommash Hold vägleder Searn Firewarder hordens shamaner mot elementen.",kw={"call of air","call of fire","call of water","darkspear","grommash hold","orgrimmar","searn firewarder","schamantränare"},ang={["class:Shaman"]="Som shaman kan du vända dig till Searn för vägledning till mästarna och prövningarna som krävs för att binda elementen till din totem.",["race:Troll"]="Som Darkspear-troll kan du se hos Searn hur dina andliga traditioner står sida vid sida med dina orch- och taurenallierades."},sec={{t="En vägvisare bland elementen",b="Inne i Grommash Hold vägleder Searn Firewarder shamaner som söker elementen. Många Darkspear-troll kommunicerar med andar genom häxdoktorer och voodooritualer. Searn vägleder noviser mot avlägsna mentorer och riter för Call of Fire, Call of Water och Call of Air, som lär dem att kommunicera med eldelementens, vattnets och luftens andar. Han tillhör hordens högsta ledning i Orgrimmar."}},faq={{q="Vem är Searn Firewarder?",a="Searn Firewarder tränar djungeltrollens shamaner inne i Grommash Hold i Orgrimmar. Han vägleder shamaner under utbildning från hela horden genom deras andliga resor.",al={"searn firewarders historia","vem är searn","searn orgrimmar"}},{q="Vilka uppdrag erbjuder Searn Firewarder?",a="Searn vägleder shamaner genom Call of Fire, Call of Water och Call of Air och hänvisar dem till avlägsna helgedomar och andliga lärare på kontinenterna.",al={"searns uppdrag","searn firewarders uppdragskedja"}},{q="Varför är en trollschaman stationerad i Grommash Hold?",a="Grommash Hold är hjärtat i Orgrimmars ledning, där krigshövding Thrall och framstående representanter för de allierade raserna samlas. Searns närvaro speglar den nära enheten mellan orcherna och Darkspear-stammen, och schamanismens centrala plats i den nya horden.",al={"varför är searn i grommash hold","searn grommash hold"}}},fx={["9fd5962f"]={q="Vilken sida står Searn Firewarder på?",a="Searn Firewarder är lojal mot Horde och står stolt tillsammans med Darkspear Trolls. Han är stationerad inne i Grommash Hold, nära warchief Thrall, och tjänar den nya Hordes shamanistiska traditioner genom att vägleda lärlingar som följer elementens väg i sitt folks tjänst.",al={"searn firewarders fraktion","vem tjänar searn","searn firewarders lojalitet"}},["7c90517e"]={q="Vad vill Searn Firewarder ha?",a="Searn Firewarder vill pröva och undervisa blivande shamaner inom Horde. Han leder utövarna genom elementprövningar, som Call of Fire, Water och Air, för att se till att de som samtalar med andarna visar styrka, hängivenhet och balans innan de får använda större krafter.",al={"vad vill searn ha","searn firewarders syfte","varför prata med searn firewarder"}}},fp="16,76,23.405.0,24.159.0,40.161.0,53.265.0"}
P.entries["npc:seer-graytongue"] = {n="Seer Graytongue",s="Seer Graytongue är en vördad taurenäldste och andlig vägledare som bor på Red Cloud Mesa i Mulgore. Nära Camp Narache prövar han unga krigare som genomgår sina första stamprov. Genom ritualer som Rite of Strength ser han till att ungdomarna vördar Earthmother innan de ger sig ut i den större världen.",h="Seer Graytongue är en vördad taurenäldste och andlig vägledare som bor på Red Cloud Mesa i Mulgore.",kw={"camp narache","graytongue","mulgore","red cloud mesa","rite of strength","rites of the earthmother","seer graytongue"},ang={["class:Shaman"]="Andliga lärjungar vänder sig till äldste som Graytongue för att lära sig hur heliga ritualer och prövningar förenar en krigares fysiska styrka med vägledning från förfäderna.",["race:Tauren"]="För taurenungdomar markerar besöket hos Seer Graytongue en helig övergångsrit som knyter samman den egna styrkan med Earthmothers eviga välsignelser."},sec={{t="En vägledare på platån",b="Seer Graytongue bor högst upp på Red Cloud Mesa och vägleder blivande taurenkrigare och besvärjare. När unga äventyrare ger sig av från Camp Narache övervakar Graytongue viktiga steg i deras heliga övergångsriter, däribland Rites of the Earthmother. Genom att pröva deras beslutsamhet mot Mulgore slätter och farliga bestar lär han dem heder, tålamod och vördnad, dygder som varje sann tauren måste bära med sig in i vuxenlivet."}},faq={{q="Vem är Seer Graytongue?",a="Seer Graytongue är en äldre tauren siare som bor i en hydda högst upp på Red Cloud Mesa i Mulgore. Han leder unga hjältar genom traditionella ceremonier där de får visa att de förtjänar sin plats i stammen.",al={"graytongue","seer graytongues roll","vem är siaren på red cloud mesa"}},{q="Vilka prövningar övervakar Seer Graytongue?",a="Han har i uppgift att vägleda ungdomar genom delar av Rites of the Earthmother, däribland Rite of Strength. Ritualerna prövar en krigares styrka och respekt för slätternas naturliga balans.",al={"graytongues uppdrag","vad vill graytongue","rites of the earthmother graytongue"}},{q="Var hittar jag Seer Graytongue?",a="Han bor i en enkel läderhydda vid utkanten av Red Cloud Mesa, strax utanför den livliga mitten av Camp Narache i Mulgore.",al={"seer graytongues plats","var finns graytongue","graytongues hydda"}}},fx={ef1aa2b1={q="Vilken sida står Seer Graytongue på?",a="Seer Graytongue är lojal mot taurenstammarna och Horde. Som andlig äldste i hjärtat av Camp Narache vårdar han sitt folks heliga seder och samarbetar med hövdingarna för att fostra nästa generation taurenmästare.",al={"seer graytongues fraktion","är seer graytongue horde","seer graytongues lojalitet"}},["9354d517"]={q="Vad vill Seer Graytongue ha?",a="Seer Graytongue vill vägleda unga tauren längs Earthmothers heliga väg. Genom att leda unga krigare genom andliga och fysiska riter ser han till att de bevisar sin beslutsamhet, hedrar andarna och blir värdiga försvarare av stammen.",al={"vad vill graytongue ha","graytongues mål","seer graytongues syfte"}},ec4e7fed={q="Varför är Seer Graytongue här?",a="Seer Graytongue bor på Red Cloud Mesa och vägleder ungdomar som ska bli vuxna. Camp Narache är platsen där unga tauren tar sina första steg ut i den större världen, och Graytongue är stationerad här för att vaka över deras traditionella övergångsriter.",al={"varför är seer graytongue på red cloud mesa","varför är seer graytongue där","varför är graytongue här"}}},fp="15,195,19.389.0,23.183.0,41.202.0,33.112.0"}
P.entries["npc:seer-ravenfeather"] = {n="Seer Ravenfeather",s="Seer Ravenfeather är en tauren-schamaninstruktör som håller till i Camp Narache på Red Cloud Mesa. Hon vägleder unga andesökare genom deras första prövningar och hjälper dem att lyssna till andarnas röster och Mulgore.",h="Seer Ravenfeather är en tauren-schamaninstruktör som håller till i Camp Narache på Red Cloud Mesa.",kw={"call of earth","camp narache","jordens sapta","mulgore","ravenfeather","red cloud mesa","seer ravenfeather","schaman"},ang={["class:Shaman"]="För unga tauren-schamaner är Seer Ravenfeather den allra första vägvisaren på den långa resan mot att lära sig tala med elementen och binda jordens krafter.",["race:Tauren"]="Som sierska i Camp Narache står hon för den djupa andliga tradition som förankrar tauren-samhället när de slår sig ned i sitt förfädershem."},sec={{t="En vägvisare på mesan",b="I Camp Naraches stilla skydd är Seer Ravenfeather en tålmodig lärare för unga taurer som kallats att följa schamanens väg. Red Cloud Mesa är en helig prövningsplats, och Ravenfeather ser till att nybörjarna förstår sina plikter innan de ger sig ut i Mulgore. Hon lär dem grundritualerna för att tala med elementens krafter och vörda jordmodern."},{t="Elementens kallelse",b="Ravenfeathers främsta uppgift är att leda de blivande schamanernas första andliga steg och visa dem den traditionella ritualen Call of Earth. Med hennes vägledning förbereder de invigda ceremoniella saptor och söker kontakt med jordandarna som vilar bland mesans klippformationer. Därigenom knyter de ett band som förankrar deras elementmagi."}},faq={{q="Vem är Seer Ravenfeather?",a="Seer Ravenfeather är en andlig vägledare som bor i Camp Narache på Red Cloud Mesa. Hon tränar unga tauren-schamaner som tar sina första steg i världen.",al={"seer ravenfeather berättelse","vem är ravenfeather","seer i camp narache"}},{q="Vilken roll har hon i schamanträningen?",a="Hon vägleder nybörjarschamaner genom deras första ritualer, framför allt uppdragskedjan där de söker kontakt med landets andar och besvarar Call of Earth.",al={"ravenfeathers schamanuppdrag","call of earth tränare","vad lär ravenfeather ut"}},{q="Var hittar jag Seer Ravenfeather?",a="Du hittar henne bland tälten och hyddorna i Camp Narache, på den avskilda Red Cloud Mesa i sydvästra Mulgore.",al={"ravenfeathers plats","var finns ravenfeather","camp naraches plats"}}},fx={["56dac3cc"]={q="Vilken sida står Seer Ravenfeather på?",a="Seer Ravenfeather är lojal mot taurenstammarna och Horde. Hon är stationerad i Camp Narache och tjänar sitt folk genom att vägleda unga tauren som kallas att följa shamanismens andliga vägar och samtala med landets andar.",al={"seer ravenfeathers fraktion","är seer ravenfeather horde","ravenfeathers lojalitet"}},d16cefae={q="Vad vill Seer Ravenfeather?",a="Hennes mål är att undervisa och förbereda blivande andliga sökare i Camp Narache. Hon vägleder unga invigda genom heliga riter, framför allt mötet med jordens andar, och hjälper dem att förtjäna sina totem och bevara harmonin mellan stammen och landet.",al={"seer ravenfeathers mål","vad vill ravenfeather","seer ravenfeathers syfte"}},f326607e={q="Varför är Seer Ravenfeather här i Camp Narache?",a="Camp Narache är samlingsplatsen där unga tauren från Red Cloud Mesa börjar sina resor. Seer Ravenfeather stannar här för att vaka över spirande mystiker och se till att varje invigd från första början lär sig de uråldriga traditionerna och riterna, liksom att vördnadsfullt knyta an till elementen.",al={"varför är seer ravenfeather i camp narache","seer ravenfeather och red cloud mesa","varför är ravenfeather här"}}},fp="17,123,19.321.0,24.296.0,25.84.0,43.126.0,35.111.0"}
P.entries["npc:seereth-stonebreak"] = {n="Seereth Stonebreak",s="Nära Greatwood Vale vakar Seereth Stonebreak över oron i landet. Schamanen från orcherna slår läger vid gränsen mellan Stonetalon Mountains och The Barrens och vägleder resenärer mot miljöförstörelse, lössläppta maskiner och växande spänningar i Kalimdor.",h="Nära Greatwood Vale vakar Seereth Stonebreak över oron i landet.",kw={"kröna","gobliner","seereth","schaman","skördemaskiner","andar","stonebreak","stonetalon"},ang={["class:Shaman"]="Som schaman delar du Seereths plikt att hela Stonetalon Mountains miljömässiga sår och lugna dess upprörda andar.",["faction:Horde"]="Som medlem av horden hjälper du till att skydda viktiga landvägar och resurser från alliansens styrkor och hänsynslösa goblinföretag.",["race:Orc"]="Som ork delar du Seereths återgång till schamanismen och vördnad för naturen, i opposition mot meningslös förstörelse."},sec={{t="En vaksam schaman",b="Seereth Stonebreak vakar över hordens land från sitt läger nära Greatwood Vale. Hon är schaman från orcherna och följer elementens harmoni för att skydda hordens områden. Landets andar ropade ut mot goblinernas plundring, och horden skickade henne till Stonetalon. Där håller hon uppsikt över landskapet och vägleder resenärer genom faror som hotar den vilda gränsbygden."},{t="Oro i Stonetalon",b="Seereth Stonebreak oroar sig över oron i hela Stonetalon Mountains. Hänsynslösa goblinföretag och mekaniska skogshuggare som skär genom urgamla skogar har rubbat bergens andliga balans svårt. Hon skickar hordens sändebud för att konfrontera inkräktarna och söka råd hos äldre kunskapsväktare, i hopp om att lindra landets plågor."}},faq={{q="Vem är Seereth Stonebreak?",a="Seereth Stonebreak är en schaman från orcherna som tjänar horden. Hon vägleder resenärer på väg mot Stonetalon Mountains genom hot mot landet och hordens närvaro.",al={"seereth","vem är seereth","seereth stonebreaks bakgrund"}},{q="Varför oroar sig Seereth för Stonetalon Mountains?",a="Stonetalon Mountains lider av omfattande skogsskövling, aggressiva goblinmaskiner för skogsavverkning och ökande konflikter. Seereth känner de lokala andarnas oro och arbetar för att hejda förödelsen.",al={"varför stonetalon","seereths problem","oroligheter i stonetalon"}},{q="Vad hände med hennes ursprungliga postering?",a="Seereths ursprungliga postering ligger kvar nära Greatwood Vale, vid gränsen mellan Stonetalon Mountains och The Barrens. Horden skickade henne till Stonetalon, och lägret ligger längs vägen väster om The Crossroads.",al={"seereths förflutna","honors stand seereth","varför flyttade seereth"}},{q="Vilka uppgifter ger Seereth äventyrare?",a="Seereth skickar hordens äventyrare till Stonetalon för att konfrontera gobliner från Venture Company, montera ned de förödande skogshuggarna, kommunicera med de oroliga andarna och rådfråga respekterade äldre som Magatha Grimtotem.",al={"seereths uppdrag","vad vill seereth","seereth stonebreaks uppdrag"}},{q="Vem är den äldre kröna hon nämner?",a="Den äldre kruttanten är Magatha Grimtotem, en mäktig och inflytelserik äldre tauren som bor på Elder Rise i Thunder Bluff. Seereth rådfrågar henne om vägledning vid djupa andliga störningar.",al={"den äldre krönan","vem är den äldre krönan","krönans uppdrag"}},{q="Varför oroar hon sig över goblinernas verksamhet?",a="Seereth oroar sig eftersom goblinernas skogsavverkning använder mekaniska skogshuggare för att skövla heliga skogar, förorena vattendrag och reta upp naturandarna som hon har svurit att blidka.",al={"seereths gobliner","goblininkräktare","varför hata gobliner"}}},fx={b2feb188={q="På vems sida står Seereth Stonebreak?",a="Seereth Stonebreak står stadigt på Hordens sida. Som orc-schaman är hon lojal mot sitt folk och dess allierade och söker Hordens hjältar som kan hjälpa till att försvara landet och driva tillbaka fienderna.",al={"seereth stonebreaks fraktion","vem tjänar seereth","tillhör seereth horden"}},["8beca421"]={q="Vad vill Seereth Stonebreak?",a="Seereth vill skydda landet och ta itu med oron som hotar regionen. Hon har slagit läger vid gränsen till Stonetalon Mountains och söker dugliga äventyrare som lyssnar till andarna och motverkar de destruktiva krafter som hotar Hordens intressen.",al={"seereth stonebreaks mål","vad vill seereth","seereth stonebreaks motiv"}},da23e0a9={q="Varför är Seereth Stonebreak här?",a="Horden skickade Seereth för att hålla uppsikt över de oroliga Stonetalon Mountains. Hon har sitt läger nära Greatwood Vale, vid gränsen mellan Stonetalon och The Barrens. Där ropar andarna ut mot goblinernas plundring, och hon samlar Hordens äventyrare för att besvara deras rop.",al={"varför är seereth här","varför kom seereth hit","varför är seereth stonebreak på den här platsen"}},["7cf30712"]={q="Vilka har Seereth Stonebreak band till?",a="Seereth är en orc-schaman som står på Hordens sida och har band till Kalimdors andliga gestalter. Hon hänvisar särskilt resenärer till den vise tauren-ledaren som kallas Elder Crone.",al={"seereth stonebreaks allierade","vilka band har seereth","seereth stonebreaks kontakter"}}},fp="18,247,17.368.0,21.338.0,26.172.0,56.200.0,35.202.0,45.213.0,36.189.0,44.185.0"}
P.entries["npc:senani-thunderheart"] = {n="Senani Thunderheart",s="Senani Thunderheart är en taurenjägarinna stationerad vid Splintertree Post i Ashenvale, strax norr om The Barrens. Hon tjänar Horden och prövar förbipasserande resenärers mod genom att utmana dem att jaga de vilda rovdjur som strövar i den uråldriga skogen. Genom hennes prövningar visar jägare sin skicklighet och minskar samtidigt antalet livsfarliga bestar som stryker omkring nära Hordens område.",h="Senani Thunderheart är en taurenjägarinna stationerad vid Splintertree Post i Ashenvale, strax norr om The...",kw={"ashenvale","ashenvale-jakten","mystral lake","senani","shadumbra","sharptalon","thunderheart","ursangous"},ang={["class:Hunter"]="Senani förkroppsligar den klassiska jägarandan och prövar din spårningsförmåga mot Ashenvales svårfångade bestar: Ursangous, Shadumbra och Sharptalon.",["faction:Horde"]="Splintertree Post är Hordens fäste i Ashenvale, där Senani hjälper Hordens spejare att visa vad de går för och säkra vildmarken.",["race:Tauren"]="För taurenresenärer påminner mötet med Senani om Jordmoderns prövningar och hedrar den uråldriga balansen mellan jägare och byte, långt från Mulgore."},sec={{t="Jaktens mästare",b="Senani Thunderheart håller läger vid Splintertree Post och förkroppsligar taurenfolkets jakttraditioner bland Ashenvales skuggiga dungar. Långt från Mulgore öppna slätter uppmanar hon Hordens äventyrare att pröva sin spårningsförmåga och strids skicklighet mot skogens främsta bestar. Hon ser jakten både som en hedervärd utmaning och som en nödvändig ritual för att överleva i ett otämjt och omstritt land."},{t="Ashenvales bestar",b="Senani leder Ashenvales traditionella jaktprov och visar jägarna vägen till tre ökända rovdjur: björnen Ursangous, katten Shadumbra och hippogryfen Sharptalon. Att hämta deras troféer, en tass, ett huvud och en klo, är en övergångsrit som visar jägarens respekt för landet och herravälde över dess våldsammaste invånare."}},faq={{q="Vem är Senani Thunderheart?",a="Senani Thunderheart är en taurenjägarinna och uppdragsgivare vid Splintertree Post i Ashenvale. Hon tjänar Horden genom att skicka äventyrare på jakt efter skogens farligaste vilda djur.",al={"vem är senani","senani thunderheart bakgrund","uppdragsgivare silverwind refuge"}},{q="Var hittar jag Senani Thunderheart?",a="Senani är stationerad vid Splintertree Post, Hordens utpost i Ashenvale, strax norr om The Barrens.",al={"senanis plats","var är senani","var ligger silverwind refuge"}},{q="Vad är Ashenvale-jakten?",a="Ashenvale-jakten består av en rad jaktutmaningar från Senani. Jägarna ska spåra upp och döda tre legendariska rovdjur i skogen: björnen Ursangous, nattsebern Shadumbra och hippogryfen Sharptalon.",al={"ashenvale-jakten","vad vill senani ha","jaktuppdrag i ashenvale"}},{q="Vilka jakttroféer vill Senani ha?",a="Hon ber jägarna återvända med Ursangous's Paw, Shadumbra's Head och Sharptalon's Claw som bevis på att alla tre mäktiga bestarna har besegrats.",al={"jakttroféer","ashenvale-jaktens föremål","vad behöver senani"}},{q="Har Senani någon koppling till områdets furbolger?",a="Inte i sina egna uppdrag. Senanis uppdrag är Ashenvale-jakten; Foulweald och de andra furbolgstammarna är bara några av de många faror en jägare möter i skogen.",al={"foulweald-uppdrag","foulwealds kung","senani och furbolger"}},{q="Är Senani knuten till Cenarion Circle?",a="Nej, Senani står direkt på Hordens och taurenstammarnas sida. Hon närmar sig skogen som en traditionell jägare, inte som en cenarisk druidisk väktare.",al={"är senani en druid","senani cenarion circle"}}},fx={cd4c9488={q="Varför är Senani Thunderheart här vid Splintertree Post?",a="Senani Thunderheart har slagit läger vid Splintertree Post för att övervaka de stora jakterna i Ashenvale. Som tauren-jägare prövar hon Hordens hjältars skicklighet mot de uråldriga och svårfångade bestarna i den djupa skogen, som Ursangous, Shadumbra och Sharptalon.",al={"varför är senani thunderheart i ashenvale","senani thunderhearts syfte vid silverwind refuge","varför är senani här"}},["13e7db62"]={q="Vad vill Senani Thunderheart att du ska göra?",a="Senani utmanar Hordens jägare att bevisa sin skicklighet i spårning och strid i de uråldriga skogarna. Hon ber dig spåra upp och döda Ashenvales listigaste rovdjur, Ursangous, Shadumbra och Sharptalon, och ta med deras värdefulla troféer tillbaka.",al={"vad vill senani","senani thunderhearts uppdrag","vad ber senani om"}}},fp="19,229,22.328.0,23.275.0,27.161.0,37.103.0,27.186.0,48.140.0,60.158.0,46.152.0"}
P.entries["npc:senator-mehr-stonehallow"] = {n="Senator Mehr Stonehallow",s="Senator Mehr Stonehallow är politiker i Ironforge och medlem av Explorers' League, stationerad vid Gol'Bolar Quarry i Dun Morogh. I stället för att debattera politik i huvudstaden har han rest till frontlinjen för att själv övervaka bekämpningen av den lokala trogginvasionen. Han värvar ivriga äventyrare för att decimera bestarna innan de tar över hela gruvan.",h="Senator Mehr Stonehallow är politiker i Ironforge och medlem av Explorers' League, stationerad vid Gol'Bolar...",kw={"dun morogh","explorers' league","gol'bolar","ironforges senat","mehr","gruva","rockjaw","senator","stonehallow","trogg"},ang={["faction:Alliance"]="Stonehallow ger en tidig inblick i hur dvärgarnas ledare arbetar och erbjuder unga hjältar i Alliansen en konkret samhällsplikt: att dräpa monster för att skydda arbetande medborgare.",["race:Dwarf"]="För dvärgar är det välkommet att se en folkvald senator stå knädjupt i gruvlera i stället för att smutta på öl i High Seat i Ironforge. Det visar prov på äkta dvärgisk tåga."},sec={{t="Politiker i gruvhålet",b="Medan de flesta i Ironforges senat tillbringar dagarna tryggt avskilda i huvudstadens stora stensalar föredrar Senator Mehr Stonehallow att handla direkt. Som dvärg hängiven både styret och Explorers' Leagues historiska utforskningar förstår han de praktiska faror som riket står inför. När våldsamma Rockjaw-troggar började klösa sig ut ur djupberget i Gol'Bolar Quarry gav sig Stonehallow själv av till gruvan. Övertygad om att byråkratiskt poserande inte räddar arbetarna erbjuder han belöningar till dugliga resenärer som utrotar de aggressiva troggarna och återtar gruvan."}},faq={{q="Vem är Senator Mehr Stonehallow?",a="Senator Mehr Stonehallow är en dvärgisk statsman i Ironforges senat. Till skillnad från många av sina lagstiftande kollegor engagerar han sig aktivt i frågor vid rikets utkanter och tillhör Explorers' League. Just nu kan du hitta honom vid Gol'Bolar Quarry, där han håller vakt och organiserar försvaret.",al={"stonehallows roll","vem är senatorn","mehr stonehallow"}},{q="Varför är en senator stationerad vid Gol'Bolar Quarry?",a="Stonehallow reste ner i gruvan för att själv ta ledningen under krisen där. Gruvan invaderades plötsligt av Rockjaw-troggar som grävde sig upp underifrån och hotade både dvärgarbetarna och värdefulla utgrävningar. Stonehallow vägrade låta problemet förvärras medan man väntade på avlägsna byråkrater.",al={"varför är stonehallow här","varför är han vid gruvan","senator i dun morogh"}},{q="Vad vill Senator Stonehallow att äventyrare ska göra?",a="Han anlitar nyanlända äventyrare för att decimera Rockjaw-troggarna i och omkring Gol'Bolar Quarry. Genom att utrota troggarna som hemsöker de lägre nivåerna hjälper rekryterna till att säkra utgrävningsplatsen och skydda de gruvarbetare som är kvar.",al={"uppdraget den offentliga tjänaren","stonehallows uppgift","gruvuppdrag"}},{q="Vilken organisation tillhör Stonehallow utöver senaten?",a="Utöver sina lagstiftande uppgifter i senaten är Mehr Stonehallow medlem av Explorers' League. Den bakgrunden väcker hans intresse för underjordiska utgrävningar och förklarar varför han gärna ger sig långt bortom huvudstadens bekvämligheter.",al={"stonehallows fraktion","tillhör stonehallow explorers' league","stonehallows tillhörighet"}}},fx={["67284ec7"]={q="På vems sida står Senator Mehr Stonehallow?",a="Senator Mehr Stonehallow står stadigt på Kingdom of Ironforges och Grand Alliances sida. Som sittande medlem av Ironforges senat och aktivt knuten till Explorers' League är han direkt lojal mot King Magni Bronzebeard och det dvärgiska hemlandets säkerhet.",al={"senator stonehallows fraktion","vem tjänar stonehallow","tillhör stonehallow alliansen"}}},fp="24,266,24.449.0,32.148.0,47.275.0,53.204.0,64.173.0"}
P.entries["npc:senior-surveyor-fizzledowser"] = {n="Senior Surveyor Fizzledowser",s="Senior Surveyor Fizzledowser är en goblinforskare som arbetar från Gadgetzan i Tanaris. Han undersöker störningar i den lokala vattenförsörjningen och skickar äventyrare för att utreda Scrimshanks försvinnande.",h="Senior Surveyor Fizzledowser är en goblinforskare som arbetar från Gadgetzan i Tanaris.",kw={"slagrutepryl","fizzledowser","gadgetzan","the gaping chasm","pestlezugg","scrimshank","silithider","tanaris","vattenbolag"},ang={["profession:Engineering"]="Fizzledowser använder specialbyggda goblinprylar för slagruta för att hitta dolda vattenkällor under den skiftande sanden."},sec={{t="Ett sökande efter vatten som går snett",b="Senior Surveyor Fizzledowser utgår från Gadgetzan och ägnar sig främst åt att lösa ökenstadens kroniska resursproblem. Lokala brunnar och vattenhål tas ständigt över av fientliga Wastewander-banditer, så Gadgetzan Water Company måste söka längre bort efter outnyttjade vattenreserver. Därför skickar Fizzledowser ut spanare med slagruteprylar över sanddynerna, bland annat mot Sandsorrow Watch. Men i stället för att hitta rena källor träffar hans sonder gång på gång underjordiska insektsbon, och en logistisk kris byts mot en nära förestående ekologisk katastrof."},{t="Silithiderna avslöjas",b="När hans lantmätarlag började utsättas för förödande bakhåll av bepansrade, grävande insekter slog Fizzledowser sig ihop med Alchemist Pestlezugg för att undersöka exemplaren. Fler tragedier, däribland Junior Surveyor Scrimshanks försvinnande inne i The Gaping Chasm, visade att det inte rörde sig om vanliga ökenplågor, utan om samordnade förtrupper kända som silithiderna. Fizzledowser oroas av fynd som pekar på ett hot kapabelt att övermanna södra Kalimdor. Han ser då bortom goblinernas neutralitet och skickar bud till lärda inom både Horde och Alliance."}},faq={{q="Vem är Senior Surveyor Fizzledowser?",a="Han är ingenjör och fältledare för Gadgetzan Water Company. Hans uppgift är att leta efter användbara vattenbrunnar i Tanaris öken för att hålla Gadgetzan försörjt.",al={"vem är fizzledowser","fizzledowser tanaris","lantmätare i gadgetzan"}},{q="Vad är Gadgetzan Water Company?",a="Det är ett företag med verksamhet i Gadgetzan som ansvarar för att säkra, behandla och distribuera vatten i Tanaris torra öken, där fukt är den mest värdefulla varan.",al={"gadgetzan water company","vem arbetar fizzledowser för"}},{q="Vad hände med Junior Surveyor Scrimshank?",a="Scrimshank är en försvunnen prospektör vars försvinnande Fizzledowser ber äventyrare att utreda.",al={"var är scrimshank","scrimshanks upprättelse","vad hände med scrimshank"}},{q="Varför oroar sig Fizzledowser för öknens insekter?",a="Hans utredning börjar med oroande insektsaktivitet och störningar i Gadgetzans vattenförsörjning, vilket får honom att samla bevis för vidare studier.",al={"varför undersöka insekter","utredning i the noxious lair","silithidhotet i tanaris"}}},fp="28,212,29.591.1,23.561.1,36.168.0,36.195.0,44.100.1,55.152.0"}
P.entries["npc:senir-whitebeard"] = {n="Senir Whitebeard",s="Senir Whitebeard är en dvärgisk dignitär och fältagent stationerad utanför Thunderbrew Distillery i Kharanos. Som särskilt sändebud från Ironforges senat har han i uppdrag att bevaka de växande hoten runt Dun Morogh. Hans uppdrag går ut på att bedöma Frostmane-trollens offensiv och rapportera deras rörelser direkt till dvärgarnas ledning.",h="Senir Whitebeard är en dvärgisk dignitär och fältagent stationerad utanför Thunderbrew Distillery i Kharanos.",kw={"dun morogh","frostmane","ironforge","kharanos","rapporter","senat","senir","whitebeard"},ang={["faction:Alliance"]="Alliansens rekryter som färdas genom Dun Morogh hjälper Senir att skydda Ironforges hjärtland från att isoleras av inhemska trolluppror.",["race:Dwarf"]="För dvärgarna står Senir för den byråkratiska men nödvändiga förbindelsen mellan gränsförsvararna och den styrande makten i Ironforge."},sec={{t="Senatens sändebud",b="De flesta resenärer besöker Kharanos för det livliga värdshuset och det berömda ölet, men Senir Whitebeard är här i officiella ärenden. Som representant utsänd direkt av Ironforges senat visar hans närvaro hur allvarligt de höga salarna ser på den växande oron i Dun Morogh. Han är en viktig länk mellan de lokala spejarna som möter faror vid den snöiga gränsen och lagstiftarna som diskuterar politik bakom stadens stenmurar."},{t="Ögon på Frostmane",b="Senirs främsta oro gäller Frostmane-trollens tilltagande aggressivitet. Trollens folk har tvingats på flykt och drivits till desperation bland de frusna klipporna, och de har börjat tränga farligt nära dvärgarnas bosättningar och vägar. Den vördnadsvärde utsände rusar inte själv in i strid, utan samlar in underrättelser om trollens positioner, särskilt kring deras fäste, och sammanställer noggranna rapporter så att Ironforges befälhavare kan slå till beslutsamt."}},faq={{q="Vem är Senir Whitebeard?",a="Senir Whitebeard är ett sändebud som Ironforges senat skickat till Dun Morogh. Han står utanför Kharanos och samlar in uppgifter om hot i området, särskilt de lokala Frostmane-trollstammarna.",al={"vem är den här dvärgen","senir whitebeards bakgrund","vem är senir"}},{q="Vad gör Senir i Kharanos?",a="Senir är stationerad i Kharanos för att bevaka trollens aktivitet och samordna spejarnas rapporter. Eftersom Kharanos ligger vid vägskälet i Dun Morogh är platsen en perfekt knutpunkt för att ta emot underrättelser från fältet innan de vidarebefordras till senaten i Ironforge.",al={"varför är senir här","senirs roll i kharanos","vad gör senir"}},{q="Varför behöver Ironforges senat ett sändebud här?",a="Ironforges senat behöver tillförlitliga uppgifter direkt från fältet för att fördela resurser och styra vakterna. Senir är en opartisk ämbetsman som bedömer om hotet från Frostmane kräver en omedelbar militär upptrappning från huvudstaden.",al={"varför ett sändebud","ironforges senat kharanos","senatens ärenden"}},{q="Vad oroar Senir mest i Dun Morogh?",a="Hans främsta fokus är Frostmane-trollens intrång. Trollens har aggressivt trängt ut från sina läger in på dvärgarnas territorium, och utgör nu direkta hot mot närliggande bosättningar som Kharanos.",al={"senirs största problem","vilket hot bevakar senir","senir och trollen"}},{q="Bekämpar Senir trollen själv?",a="Nej, Senir arbetar som administratör och underrättelseinhämtare. Han förlitar sig på lokala spejare, bergsmän och äventyrare på genomresa för att ta sig in på fientliga platser som Frostmane Hold och hämta viktiga underrättelser åt honom.",al={"strider senir","är senir en krigare","senir i strid"}},{q="Vart skickas Senirs rapporter?",a="När Senir har sammanställt fältanteckningar om trollens positioner och styrka skickas de färdiga rapporterna direkt uppför bergsvägen till senaten och ledningen i Ironforge.",al={"vart skickas rapporterna","vart senirs rapporter skickas","vem får rapporterna"}}},fx={["40f66e19"]={q="På vems sida står Senir Whitebeard?",a="Senir Whitebeard tjänar Kingdom of Ironforge och Grand Alliance. Han verkar som officiellt sändebud under direkt befäl av Ironforges senat och är helt lojal mot dvärgarnas styre och rikets kärnland.",al={"senir whitebeards lojalitet","vem tjänar senir","senirs fraktion"}}},fp="16,238,19.232.0,22.327.0,24.167.0,32.206.0,52.190.0,46.183.0,36.174.0,28.127.0"}
P.entries["npc:sentinel-arynia-cloudsbreak"] = {n="Sentinel Arynia Cloudsbreak",s="Sentinel Arynia Cloudsbreak är en nattalvsväktare som är stationerad i The Oracle Glades fridfulla lundar på Teldrassil. Hon har i uppdrag att vaka över den heliga balansen i de norra grenarna och håller ett vaksamt öga på lundens förtrollade vatten och skogens djurliv.",h="Sentinel Arynia Cloudsbreak är en nattalvsväktare som är stationerad i The Oracle Glades fridfulla lundar på...",kw={"arynia cloudsbreak","förtrollad lund","kaldorei","dimma","night elf","the oracle glade","sentinel","teldrassil"},ang={["faction:Alliance"]="Arynia förkroppsligar Kaldorei-sentinels vaksamhet och försvarar Alliansens viktiga skogsfäste i Kalimdor.",["race:NightElf"]="För unga nattalver som blir vuxna på Teldrassil ger det praktisk erfarenhet av att skydda hemlandets naturliga balans att hjälpa Sentinel Cloudsbreak."},sec={{t="Väktare i The Oracle Glade",b="Arynia Cloudsbreak tjänar Sentinel-armén i en av Teldrassils mest avskilda och mystiska trakter: The Oracle Glade. Bland uråldriga träd och eteriska källor håller hon vakt långt från Darnassus livliga gator och ser till att vildmarkens helgd förblir ostörd."},{t="Oro i lunden",b="Trots Teldrassils heliga födelse har en smygande disharmoni börjat oroa dess varelser. Arynia förlitar sig på förbipasserande äventyrare och unga nattalver för att undersöka lokala störningar, som märkliga beteenden hos lundens djurliv och mystiska fenomen kring de förtrollade källorna."}},faq={{q="Vem är Sentinel Arynia Cloudsbreak?",a="Hon är en nattalvssentinel som står vakt i The Oracle Glade, djupt inne i norra Teldrassil. Hon vakar över den mystiska lunden och rekryterar resenärer som kan hjälpa till att bevara dess naturliga harmoni.",al={"arynia cloudsbreak","vem är arynia","sentinel arynia"}},{q="Var kan Arynia Cloudsbreak hittas?",a="Arynia är stationerad utomhus i The Oracle Glade, i den nordvästra delen av Teldrassil, norr om Dolanaar.",al={"arynias plats","var finns arynia","arynia cloudsbreak karta"}},{q="Vilka uppgifter har hon bland sentinels?",a="Som sentinel stationerad i vildmarken patrullerar hon skogens avlägsna grenar och håller uppsikt över lokala andar, djurliv och naturfenomen för att upptäcka tecken på fördärv eller obalans.",al={"arynias roll","vad gör arynia"}},{q="Är hon släkt med någon annan på Teldrassil?",a="Hon har samma efternamn som Mavoris Cloudsbreak, vilket antyder ett familjeband mellan nattalverna som bor i världsträdet.",al={"arynias familj","mavoris cloudsbreak"}},{q="Vilka uppdrag ger hon äventyrare?",a="Hon erbjuder uppgifter som går ut på att undersöka den förtrollade lunden, ta hand om mystiska störningar och kringströvande bestar i närheten samt hjälpa varelser i nöd.",al={"arynias uppdrag","uppdrag i the oracle glade"}},{q="Varför är The Oracle Glade betydelsefull för nattalverna?",a="The Oracle Glade är en helig fristad i Teldrassil, känd för sina stilla dammar och sin andliga vördnad. Druider och sentinels vakar över den och söker vägledning och omen från naturen.",al={"varför the oracle glade","historien om the oracle glade"}}},fx={["8186bb8d"]={q="På vems sida står Sentinel Arynia Cloudsbreak?",a="Arynia tjänar Sentinels, nattalvernas välkända stridsstyrka, och är trogen ledningen i Darnassus och den större alliansen. Hon är stationerad bland Teldrassils fridfulla lundar. Hennes uppgift är att skydda sitt hemland och se till att kaldoreiernas andliga helgedomar förblir ostörda av korruption och yttre hot.",al={"arynia cloudsbreaks fraktion","tillhör arynia cloudsbreak alliansen","vem tjänar arynia"}},d0964425={q="Varför är Sentinel Arynia Cloudsbreak i Oracle Glade?",a="Arynia är stationerad i Oracle Glade för att hålla uppsikt över de fridfulla norra delarna av Teldrassil. Gläntan har helig betydelse för nattalverna. Som Sentinel håller hon vakt, ser till det lokala djurlivet och tar hand om störningar som hotar de förtrollade skogarnas helgd.",al={"varför är arynia cloudsbreak här","arynia cloudsbreak och oracle glade","varför är sentinel arynia i oracle glade"}}},fp="27,147,27.232.0,20.231.0,35.181.0,38.106.0,46.138.0,44.139.0,40.149.0,55.167.0"}
P.entries["npc:sentinel-aynasha"] = {n="Sentinel Aynasha",s="Sentinel Aynasha är en agent bland nattalvernas Sentinels och tjänstgör vid Darkshores vilda gränstrakter. Hon spanar efter fiendens rörelser och bär viktig underrättelse, och möter regelbundet faror från fientliga styrkor som hotar norra Kalimdor.",h="Sentinel Aynasha är en agent bland nattalvernas Sentinels och tjänstgör vid Darkshores vilda gränstrakter.",kw={"bågskytt","aynasha","darkshore","kaldorei","night elf","spanare","sentinel"},ang={["faction:Alliance"]="För Alliansens resenärer i Kalimdor är Sentinel-spanare som Aynasha viktiga kontaktpersoner längs de farliga vildmarksvägarna.",["race:NightElf"]="Aynasha står som en vaksam förtrupp inom Kaldoreis militär och försvarar de uråldriga skogarna mot främmande makter som tränger sig på och vildmarkens fördärv."},sec={{t="Vid frontlinjen",b="Som spanare och bågskytt för Sentinels skickas Aynasha till farliga gränstrakter där nattalvernas marker möter fientliga intrång. Hon utför smyguppdrag och för brådskande meddelanden genom oländig terräng. För att undvika fiendepatruller och överleva djupt inne i omstritt område förlitar hon sig på sin pricksäkerhet och överlevnadsinstinkt."}},faq={{q="Vem är Sentinel Aynasha?",a="Aynasha är en aktiv spanare och bågskytt bland nattalvernas Sentinels, den främsta militära styrkan som försvarar norra Kalimdor och dess gränser.",al={"vem är aynasha","aynashas roll","sentinel aynashas historia"}},{q="Vilka hot håller hon uppsikt över i Darkshore?",a="Längs Darkshores utkanter håller hon vakt över fientliga läger, kringströvande furbolgstammar och främmande intrång som hotar nattalvernas vildmark.",al={"aynashas fiender","hot i darkshore","vem slåss hon mot"}},{q="Varför är hon ofta ensam på vägen?",a="Sentinels färdas ofta ensamma eller i små spanarpar för att föra brådskande underrättelser mellan utposter utan att dra onödig uppmärksamhet till sig från fientliga styrkor.",al={"varför är hon ensam","aynashas solouppdrag","sentinel-spanarens uppgifter"}}},fp="16,181,18.266.0,24.125.0,43.149.0,38.173.0"}
P.entries["npc:sentinel-elissa-starbreeze"] = {n="Sentinel Elissa Starbreeze",s="Sentinel Elissa Starbreeze är en Night Elf-väktare som är stationerad i Auberdine vid Darkshores dimhöljda kust. Från övervåningen i en byggnad på andra sidan bron håller hon uppsikt över växande hot i området och visar resenärer vart de bör bege sig i vildmarken.",h="Sentinel Elissa Starbreeze är en Night Elf-väktare som är stationerad i Auberdine vid Darkshores dimhöljda...",kw={"althalaxx","auberdine","darkshore","elissa starbreeze","night elf","sentinel"},ang={["faction:Alliance"]="För Alliance-resenärer som anländer från Teldrassil är Starbreeze en av de första personerna som hänvisar hjälp längre in i Darkshores hemsökta ödemarker.",["race:NightElf"]="Sentinel Starbreeze står för det vaksamma och disciplinerade skydd som Sentinels ger Kalimdors nordliga utposter, som Auberdine."},sec={{t="Ett vakande öga i Auberdine",b="Medan många Sentinels patrullerar den dimmiga kusten och skogarna håller Elissa Starbreeze samman försvaret från Auberdine. Hon är stationerad på byggnadens övre våning, strax nordost om stadens värdshus på andra sidan bron, och håller utkik efter ovanliga oroligheter i Darkshore. Hennes uppgifter leder ofta äventyrare till avlägsna platser av intresse, däribland det gåtfulla Tower of Althalaxx som reser sig långt i norr, så att skuggvarelser inte kan överraska kustbosättningen."}},faq={{q="Var hittar jag Sentinel Elissa Starbreeze?",a="Hon finns i Auberdine i Darkshore. Gå över den lilla bron nordost om stadens värdshus och gå upp till byggnadens andra våning för att hitta henne i tjänst.",al={"elissa starbreeze plats","var finns elissa starbreeze","auberdine starbreeze"}},{q="Vad har hon för uppgift i Darkshore?",a="Som medlem av Night Elf Sentinels hjälper hon till att skydda Auberdine genom att hålla koll på möjliga faror i Darkshore. Hon skickar skickliga spejare och äventyrare för att undersöka avlägsna utposter och märkliga hot, som Tower of Althalaxx.",al={"vad gör elissa","elissa starbreeze roll"}},{q="Har hon familj bland night elves?",a="Inget är nedtecknat om hennes släkt. Hon är endast känd för sin tjänst som Sentinel i Auberdine, där hon vakar över staden och skickar resenärer mot Tower of Althalaxx.",al={"starbreeze familj","vem är elissa släkt med"}}},fx={eef8e9fa={q="Vem är Sentinel Elissa Starbreeze?",a="Sentinel Elissa Starbreeze är en nattalvsvakt som tjänar Sentinels i kusthamnen Auberdine. Hon är stationerad i Darkshore, där hon håller uppsikt över bosättningen och visar dugliga resenärer mot akuta problem i vildmarken runt omkring, bland annat undersökningar nära det gåtfulla Tower of Althalaxx.",al={"vem är elissa starbreeze","elissa starbreeze nattalv","sentinel starbreezes identitet"}},["73c7acf2"]={q="På vems sida står Sentinel Elissa Starbreeze?",a="Hon är helt lojal mot Sentinels, nattalverna i Darnassus och den större alliansen. Från sin post i Auberdine arbetar hon för att skydda nattalvernas bosättningar och intressen längs Kalimdors kuster.",al={"vilken fraktion tillhör elissa starbreeze","tillhör elissa starbreeze alliansen","elissa starbreezes lojalitet"}},["650c6447"]={q="Varför är Sentinel Elissa Starbreeze här i Auberdine?",a="Elissa är stationerad i Darkshore som en del av den regionala Sentinel-styrka som vaktar Auberdine. Från sin utpost ovanför byn samordnar hon spejare och rekryterar äventyrare för att hålla uppsikt över ondskefulla aktiviteter längs kusten och i ruinerna inåt land.",al={"varför är elissa starbreeze i auberdine","elissa starbreezes plats i darkshore","vad förde elissa starbreeze hit"}}},fp="26,217,27.437.0,44.159.0,30.196.0,43.150.0"}
P.entries["npc:sentinel-farsong"] = {n="Sentinel Farsong",s="Sentinel Farsong är en nattalvsvakt stationerad vid Silverwing Grove i Ashenvale. Som viktig kontakt för Silverwing Sentinels samordnar hon underrättelser och stridsinsatser mot de framryckande Warsong Outriders i Warsong Gulch.",h="Sentinel Farsong är en nattalvsvakt stationerad vid Silverwing Grove i Ashenvale.",kw={"ashenvale","sentinel farsong","silverwing grove","silverwing sentinels","warsong gulch","warsong outriders"},ang={["faction:Alliance"]="Sentinel Farsong står för Alliansens mobilisering vid frontlinjen i Ashenvale och skickar frivilliga rakt in i striden mot Warsong-klanen.",["race:NightElf"]="Som beskyddare av Elunes heliga skogar förkroppsligar Farsong kaldoreiernas beslutsamhet att driva bort alla som skändar de uråldriga lundarna."},sec={{t="Silverwing Groves väktare",b="Sentinel Farsong håller vakt i Silverwing Grove och är djupt engagerad i försvaret av Ashenvales södra gräns. Warsong-klanen avverkar ständigt timmer och tränger allt djupare in i nattalvernas förfäders territorier. Därför mobiliserar hon Alliansens hjältar för att slå till mot Warsong Outriders och ser till att fältrapporter når Silverwing-kommandot. Hennes uppgifter går ut på att samla frivilliga för att hejda Hordens territoriella expansion och bevara de heliga skogarna."}},faq={{q="Vem är Sentinel Farsong?",a="Sentinel Farsong är en nattalvsvakt knuten till Silverwing Sentinels i Ashenvale. Hon är stationerad vid Silverwing Grove nära ingången till Warsong Gulch, där hon rekryterar äventyrare från Alliansen och samlar in viktig stridsinformation.",al={"farsong","sentinel farsongs bakgrund","vem är farsong"}},{q="Var hittar man henne?",a="Hon finns vid Silverwing Grove i sydöstra Ashenvale, där Alliansen samlar sina styrkor inför de pågående militära insatserna i Warsong Gulch.",al={"sentinel farsongs plats","var finns farsong","farsong på kartan över ashenvale"}},{q="Varför strider hon mot Warsong Outriders?",a="Warsong Outriders avverkar timmer och vanhelgar Ashenvales heliga skogar. Farsong samordnar försvaret för att stoppa deras verksamhet och återta territorium som Horden har gjort anspråk på.",al={"varför strida mot warsong outriders","farsongs motiv","konflikten i ashenvale"}}},fx={e9cb1820={q="På vems sida står Sentinel Farsong?",a="Sentinel Farsong tjänar Darnassus Sentinels och Silverwing Sentinels och strider för alliansen. Hon är stationerad vid Silverwing Grove i Ashenvale och står orubbligt emot Hordens intrång. Hon samlar nattalver och deras allierade för att bevara sina förfäders skogar.",al={"farsongs fraktion","vem tjänar farsong","tillhör sentinel farsong alliansen"}},a1fa54ea={q="Vad vill Sentinel Farsong?",a="Sentinel Farsong vill få bort Warsong Outriders och Hordens inkräktare helt från Ashenvale. Hon sammanställer militära rapporter från frontlinjerna, samlar resurser och kallar på alliansens hjältar för att besegra styrkorna som invaderar den heliga skogen.",al={"vad behöver farsong","farsongs mål","sentinel farsongs uppdrag"}},ffcf1925={q="Varför är Sentinel Farsong här?",a="Sentinel Farsong är stationerad vid Silverwing Grove för att övervaka verksamheten längs Warsong Gulchs norra gränser. Horden belägrar Ashenvale ständigt, och hon spelar en central roll i att samordna trupper och spaning mot den framryckande timmerverksamheten.",al={"varför är farsong i ashenvale","farsong vid silverwing grove","varför är sentinel farsong här"}},["31bb4497"]={q="Vilka har Sentinel Farsong band till?",a="Sentinel Farsong är knuten till Silverwing Sentinels och den större nattalvsmilitären under Darnassus. Hon samarbetar med alliansens försvarare vid Silverwing Grove och håller direkt kontakt med befälhavarna som organiserar försvaret mot Warsong-klanen.",al={"farsongs allierade","sentinel farsongs kontakter","vem rapporterar farsong till"}}},fp="16,151,28.290.0,24.230.0,23.132.0,42.170.0"}
P.entries["npc:sentinel-onaeya"] = {n="Sentinel Onaeya",s="Sentinel Onaeya är en nattalvsväktare stationerad vid Maestra's Post i nordvästra Ashenvale, nära gränsen till Darkshore. Hon har fått i uppdrag att hålla stånd mot hot som tränger sig på och samlar dugliga äventyrare från Alliansen för att skydda skogen och hjälpa sina medvaktare.",h="Sentinel Onaeya är en nattalvsväktare stationerad vid Maestra's Post i nordvästra Ashenvale, nära gränsen...",kw={"ashenvale","darkshore","maestra's post","night elf","onaeya","väktare"},ang={["faction:Alliance"]="Onaeya samordnar viktiga försvarsuppgifter för Alliansens resande som lämnar kustens vildmarker och färdas in i Ashenvales omstridda skogar.",["faction:Horde"]="Som hängiven väktare vid Maestra's Post är Onaeya en aktiv fiendesoldat som bevakar de norra vägarna in i Ashenvale.",["race:NightElf"]="För nattalver som färdas söderut från Darkshore står Onaeya i frontlinjen och försvarar Ashenvales heliga skogsmark mot yttre hot."},sec={{t="En väktare vid gränsen",b="Maestra's Post är en viktig vägpost längs vägen från Darkshore in i Ashenvales täta, omstridda trädkronor. Sentinel Onaeya står vakt utanför bosättningens huvudbyggnad och håller uppsikt över resande medan hon samordnar försvaret. Med fientligt djurliv, fördärvande krafter och spänningar vid gränsen utgör väktare som Onaeya den första försvarslinjen för nattalvernas bosättningar i regionen."},{t="Försvara utposten",b="Onaeya får höra att Sentinel Aynasha har attackerats av furbolgs medan hon bar ett viktigt meddelande genom Darkshore. Hon belönar äventyrare som skyddar den förgiftade väktaren tills motgiftet verkar."}},faq={{q="Vem är Sentinel Onaeya?",a="Sentinel Onaeya är en nattalvsväktare stationerad vid Maestra's Post i nordvästra Ashenvale. Hon delar ut uppdrag och försvarar frontlinjen genom att visa resande hur de kan hjälpa utposten.",al={"onaeya","sentinel onaeya","vem är onaeya"}},{q="Var finns Sentinel Onaeya?",a="Hon står precis utanför huvudbyggnaden vid Maestra's Post, längs den norra vägen i Ashenvale, strax nedanför gränsen till Darkshore.",al={"onaeyas plats","var finns sentinel onaeya","hitta onaeya"}},{q="Vilken fraktion tillhör Sentinel Onaeya?",a="Hon tillhör Night Elf Sentinels och är lojal mot Alliansen. Äventyrare från Horde möts av fientlighet vid första ögonkastet.",al={"onaeyas fraktion","tillhör onaeya alliansen","är onaeya vänligt inställd till horde"}},{q="Hur är Onaeya kopplad till Sentinel Aynasha?",a="Sentinel Aynasha ber äventyrarna att rapportera till Onaeya vid Maestra's Post efter att de skyddat henne mot anfallande furbolgs. Onaeya belönar deras mod och blir glad över att höra att Aynasha överlevde.",al={"onaeya aynasha","belöning från sentinel aynasha"}},{q="Vilka uppgifter ger Sentinel Onaeya?",a="Onaeya belönar äventyrare som skyddar Sentinel Aynasha mot anfallande furbolgs i Darkshore och för med sig besked till Maestra's Post om att hon är i säkerhet.",al={"onaeyas uppdrag","vilka uppdrag har onaeya"}},{q="Varför är Maestra's Post viktig för väktarna?",a="Maestra's Post är en viktig kontrollpost som förbinder Darkshores försörjningsleder med Ashenvales hjärta. Genom att hålla utposten hindrar man fiender från att skära av nattalver som färdas söderut.",al={"varför maestras post","maestras posts betydelse"}}},fx={e1ad0868={q="Varför är Sentinel Onaeya stationerad vid Maestra's Post?",a="Sentinel Onaeya håller vakt strax utanför huvudskyddet vid Maestra's Post i nordvästra Ashenvale. Som nattalvssentinel vid gränsen hjälper hon till att skydda utposten mot hoten i omgivningen och tar emot rapporter från resenärer som hjälper andra sentinels, däribland Aynasha.",al={"varför är onaeya här","varför är sentinel onaeya på den här platsen","varför är onaeya vid maestra's post"}}},fp="15,173,23.266.0,16.211.0,23.134.0,33.142.0,44.125.0,44.170.0,45.130.0,49.172.0"}
P.entries["npc:sentinel-selarin"] = {n="Sentinel Selarin",s="Sentinel Selarin är en nattalvsspejare som skickats till kustbosättningen Auberdine. Som sändebud för Ashenvales försvarare söker hon förstärkningar som kan hejda de växande farorna som hotar den uråldriga skogen.",h="Sentinel Selarin är en nattalvsspejare som skickats till kustbosättningen Auberdine.",kw={"ashenvale","auberdine","darkshore","raene wolfrunner","selarin","sentinel selarin","sentinels","terenthis"},ang={["faction:Alliance"]="Selarin fungerar som en viktig länk för Alliance-hjältar som färdas söderut från Darkshore in i Ashenvales omstridda vildmark.",["race:NightElf"]="Som medlem av Sentinels står Selarin för den vaksamhet och sammanhållning som krävs för att försvara kaldoreiernas förfäders gränser."},sec={{t="En vädjan om förstärkningar",b="När spänningarna och de mörka hoten växer i Ashenvale har garnisonens resurser tänjts till bristningsgränsen. På Raene Wolfrunners uppdrag färdades Sentinel Selarin norrut längs skogsvägen till Darkshore. Hennes uppdrag var enkelt: söka upp Terenthis i Auberdine och be om hjälp från väktarna och spejarna som är stationerade vid kusten."},{t="Samla vägfararna",b="När Selarin kom fram till Auberdine fann hon Terenthis helt uppslukad av lokala uppgifter och oförmögen att själv hörsamma vädjan. I stället för att återvända tomhänt bestämde sig Selarin för att stanna i staden och värva dugliga resenärer på genomresa i Darkshore. Hon skickar beprövade äventyrare söderut mot Astranaar och uppmanar dem att låna ut sina svärd och besvärjelser till Raene Wolfrunners hårt ansatta styrkor."}},faq={{q="Vem är Sentinel Selarin?",a="Sentinel Selarin är en nattalvskrigare bland Sentinels. Hon tjänstgör som kurir och kontaktperson och har skickats från Ashenvale för att be bosättningen Auberdine i Darkshore om hjälp.",al={"selarins bakgrund","vem är selarin","sentinel selarin"}},{q="Varför kom Selarin till Auberdine?",a="Raene Wolfrunner beordrade henne att söka upp Terenthis i Auberdine och skaffa förstärkningar för att bekämpa de växande farorna som hotar Ashenvales vildmark.",al={"varför är selarin i darkshore","selarins uppdrag","vad gör selarin"}},{q="Varför följde inte Terenthis med henne till Ashenvale?",a="Terenthis var upptagen med att hantera viktiga angelägenheter och undersöka hoten i själva Darkshore. Därför bestämde sig Selarin för att rekrytera självständiga resenärer från Alliance som kunde färdas söderut i stället.",al={"varför hjälper inte terenthis","terenthis och selarin","terenthis är upptagen"}},{q="Vart skickar hon äventyrare?",a="Hon skickar äventyrare söderut över gränsen till Ashenvale för att rapportera direkt till Raene Wolfrunner i Astranaar.",al={"vart skickar selarin mig","selarins uppdragsmål","efter selarin"}}},fx={["5ef6a9e4"]={q="Vems sida står Sentinel Selarin på?",a="Sentinel Selarin är en lojal soldat i Night Elf-sentinelerna, tjänar Alliansen och lyder direkt under befälhavare i Ashenvales försvarsstyrkor, som Raene Wolfrunner.",al={"selarins fraktion","är sentinel selarin med i alliansen","vem tjänar selarin"}},bee3573a={q="Vad vill Sentinel Selarin?",a="Selarin söker förstärkningar för de tilltagande problemen i Ashenvale. Först kom hon för att kalla på Terenthis, men när hon insåg hur viktiga hans egna plikter i Darkshore är, försöker hon i stället samla dugliga äventyrare som kan resa söderut och hjälpa Raene Wolfrunner.",al={"selarins mål","vad behöver selarin","vad försöker selarin göra"}},["8a8a2168"]={q="Vem har Sentinel Selarin band till?",a="Selarin tjänar under Raene Wolfrunner, som stationerade henne i Ashenvale och skickade henne på uppdraget. Hon känner också Terenthis i Auberdine väl och samordnar med honom för att säkra hjälp och skicka lovande rekryter till frontlinjen.",al={"vem arbetar selarin för","selarins kontakter","selarin raene wolfrunner"}}},fp="16,164,25.299.0,22.263.0,24.143.0,34.129.0,46.146.0,32.109.0"}
P.entries["npc:sentinel-thenysil"] = {n="Sentinel Thenysil",s="Sentinel Tara Thenysil är en Night Elf-vaktpost stationerad i Astranaar, i Ashenvales uråldriga skog. Hon vakar över vildmarken omkring sig, håller noga uppsikt över militära operationer i området och samordnar spejare som bevakar grannområdena. Särskilt uppmärksam är hon på allierade styrkor som tränger söderut in i det omstridda Stonetalon Mountains.",h="Sentinel Tara Thenysil är en Night Elf-vaktpost stationerad i Astranaar, i Ashenvales uråldriga skog.",kw={"ashenvale","astranaar","kaela shadowspear","sentinels","stonetalon","tara thenysil","thenysil","tyrande whisperwind"},ang={["faction:Alliance"]="Thenysil fungerar som en tidig länk mellan Ashenvale och Stonetalon Mountains och ger Alliance-äventyrare möjlighet att vinna ledningens personliga gunst i Darnassus.",["race:Gnome"]="Thenysil tycker att det är ovanligt och oroväckande att en gnommagiker från Alliance skickats till Stonetalon, vilket visar hur märkliga Night Elf fortfarande tycker att deras småväxta allierade är.",["race:NightElf"]="Thenysil står för Sentinels plikttrogna vaksamhet. Hon arbetar outtröttligt för att skydda Kalimdors heliga lundar och hålla allierade agenter säkra längs gränstrakterna."},sec={{t="Bevakning av gränserna",b="Från sin post i den befästa bosättningen Astranaar hjälper Sentinel Thenysil till att skydda Ashenvale mot den växande fientligheten. Night Elf-bosättningar i hela området utsätts för oupphörliga intrång, vilket gör kommunikationen mellan avlägsna utposter livsviktig. Medan större delen av den lokala garnisonen främst försvarar skogsvägen leder Thenysil Alliance-frivilliga bortom Ashenvales gränser för att se till att avlägsna allierade får stöd."},{t="Band till Stonetalon",b="Thenysil har en nära personlig och militär vänskap med Kaela Shadowspear, en agent som skickats söderut till Stonetalon Mountains klippiga höjder. När hon får veta att Kaela skickats dit tillsammans med en excentrisk gnommagiker ser Thenysil den okonventionella kombinationen som ett tydligt tecken på att allvarliga problem tornar upp sig bland bergen. Orolig för vilka faror hennes kamrat kan möta rekryterar hon dugliga äventyrare som ska resa söderut, föra med sig stöd och rapportera om uppdragets utveckling."},{t="Möte i trädkronorna",b="När spejare återvänder från Stonetalon med nyheter om framgångsrika angrepp mot det skändliga Venture Company ser Thenysil till att deras insatser uppmärksammas. Hon inser att ett stopp för den mekaniserade exploateringen i bergen skyddar alla grannområdens vildmark och ger pålitliga hjältar ett formellt erkännande. I stället för att behålla äran i Astranaar skickar hon dem till Temple of the Moon i Darnassus, där de får träffa översteprästinnan Tyrande Whisperwind personligen."}},faq={{q="Var hittar man Sentinel Thenysil?",a="Sentinel Thenysil är stationerad i Astranaar, den främsta Night Elf-befästningen längs huvudvägen genom centrala Ashenvale.",al={"thenysils plats","var finns sentinel thenysil","thenysil astranaar"}},{q="Varför skickar Thenysil resenärer till Stonetalon Mountains?",a="Hennes vän Kaela Shadowspear skickades till Stonetalon tillsammans med en gnommagiker. Thenysil ser det ovanliga uppdraget som ett tecken på farliga problem och skickar därför pålitliga äventyrare för att förstärka Kaelas uppdrag.",al={"varför stonetalon","thenysils uppdrag stonetalon","varför bevaka stonetalon"}},{q="Vem är Kaela Shadowspear?",a="Kaela Shadowspear är en Night Elf-spejare och nära vän till Sentinel Thenysil. Hon är stationerad i Stonetalon Mountains, där hon undersöker hot mot landet.",al={"vem är kaela","kaela shadowspears relation","thenysils vän"}},{q="Vilka hot bekämpas i Stonetalon?",a="Utöver skärmytslingar med lokala motståndare har Venture Company etablerat påträngande och destruktiva industriella verksamheter i Stonetalon Mountains, där de kalbryter marken och skövlar skogen.",al={"hot i stonetalon","vad händer i stonetalon","venture company stonetalon"}},{q="Varför skickar Thenysil äventyrare till Tyrande Whisperwind?",a="När äventyrarna har hjälpt Kaela Shadowspear att stoppa Venture Companys planer i Stonetalon skickar Thenysil dem till Darnassus, så att översteprästinnan Tyrande Whisperwind personligen kan erkänna deras tjänster för Night Elf-folket.",al={"mottagande av tyrande","varför träffa tyrande","thenysils hänvisning till darnassus"}},{q="Vilken roll har Sentinel Thenysil i Astranaar?",a="Hon samordnar Sentinel-styrkorna i Astranaar och hjälper till att organisera underrättelser från regionen, bevaka gränserna och skicka ut pålitliga Alliance-rekryter för att stödja avlägsna garnisoner.",al={"thenysils rang","vad gör thenysil","sentinel thenysils uppgifter"}}},fx={cd8ae8e6={q="Vems sida står Sentinel Thenysil på?",a="Sentinel Thenysil är hängiven nattalverna och Alliansen. Som aktiv soldat i sentinelerna i Astranaar bevakar hon Ashenvales gränser och samordnar stöd till nattalvernas utposter och insatser i Kalimdor.",al={"sentinel thenysils fraktion","vem tjänar thenysil","är thenysil med i alliansen"}},ad790eb1={q="Varför är Sentinel Thenysil i Astranaar?",a="Astranaar är nattalvernas främsta knutpunkt i Ashenvale och fungerar som ledningspost vid skogens försvar. Sentinel Thenysil är stationerad där för att hålla vakt över området, bevaka handelsvägar och rekrytera dugliga resenärer när grannländer behöver akut förstärkning.",al={"varför är thenysil i astranaar","thenysils postering i ashenvale","varför är sentinel thenysil här"}}},fp="17,222,20.310.0,18.393.0,22.376.1,37.108.0,57.223.0,25.144.0,44.133.0,58.207.1,46.137.0"}
P.entries["npc:sentinel-tysha-moonblade"] = {n="Sentinel Tysha Moonblade",s="Sentinel Tysha Moonblade är en nattalvsspejare stationerad längs huvudvägen i Darkshore, strax väster om de uråldriga ruinerna av Ameth'Aran. Hon har fått i uppdrag att patrullera den oroliga kustvildmarken, vägleda resenärer och rekrytera hjälp för att undersöka de rastlösa andar som hemsöker de närliggande, sönderslagna alvbosättningarna.",h="Sentinel Tysha Moonblade är en nattalvsspejare stationerad längs huvudvägen i Darkshore, strax väster om de...",kw={"ameth'aran","auberdine","darkshore","highborne","night elf","sentinel","tysha moonblade"},ang={["faction:Alliance"]="För Alliansens resenärer på väg söderut från Auberdine mot Ashenvale är Tysha en av få vänligt sinnade utposter längs en annars farofylld väg full av monster.",["race:NightElf"]="Tysha står för de vaksamma Sentinels som försöker bevara freden i länder som fortfarande bär ärr efter den uråldriga Sundering. Hon ber sina nattalvskamrater att låta sina förbannade förfäder få ro."},sec={{t="Vakt längs vägen",b="Tysha Moonblade står vakt längs Darkshores igenvuxna landsväg och håller noggrann uppsikt över ett allt mer instabilt land. Rakt österut ligger de hemsökta resterna av Ameth'Aran, där förbannade Highborne-spöken och illvilliga banshees dröjer sig kvar bland uråldriga stenpelare. Eftersom Auberdines begränsade försvar är hårt ansatta av hot längs kusten ber Tysha äventyrare på genomresa att avslöja historien bakom Ameth'Arans tragiska fall och driva bort de rastlösa döda."}},faq={{q="Vem är Sentinel Tysha Moonblade?",a="Sentinel Tysha Moonblade är en nattalvsväktare som patrullerar huvudvägen i centrala Darkshore, stationerad strax väster om ruinerna av Ameth'Aran. Hon håller vägen under uppsikt och skyddar den mot kringströvande bestar och rastlösa vålnader.",al={"vem är tysha","tysha moonblades bakgrund","sentinel tysha"}},{q="Var hittar jag Sentinel Tysha Moonblade?",a="Hon är stationerad längs vägen som löper från norr till söder i Darkshore, rakt väster om den uråldriga ruinstaden Ameth'Aran.",al={"tysha moonblades plats","var är tysha","var är sentinel tysha"}},{q="Vilka uppgifter ger hon äventyrare?",a="Tysha skickar resenärer till de närliggande ruinerna av Ameth'Aran för att undersöka tragedin som ödelade den uråldriga nattalvsbosättningen och hjälpa till att stilla de plågade spöken som hemsöker dess rasade pelare.",al={"tysha moonblades uppdrag","uppdragsgivare för ameth'arans fall","vad vill tysha"}},{q="Är hon släkt med någon annan i Darkshore?",a="Inga släktingar till henne är kända. Tysha håller ensam sin post på vägen väster om Ameth'Aran och vakar över de hemsökta ruinerna.",al={"tysha moonblades familj"}}},fx={["73e42ede"]={q="Vems sida står Sentinel Tysha Moonblade på?",a="Sentinel Tysha Moonblade tjänar nattalvernas sentineler och står stadigt på Alliansens sida. Som väktare av Kalimdors heliga vildmark håller hon uppsikt över stigarna i Darkshore för att skydda sitt folk och deras forntida marker från annalkande faror.",al={"tysha moonblades fraktion","vem tjänar tysha moonblade","är tysha moonblade med i alliansen"}},d8373493={q="Varför är Sentinel Tysha Moonblade här?",a="Sentinel Moonblade är stationerad längs vägen strax väster om de hemsökta ruinerna av Ameth'Aran och patrullerar sträckan för att hålla uppsikt över de närliggande fornlämningarna. Darkshore vimlar av upprörda andar och fiender på lur, så vaksamhet krävs för att skydda förbipasserande resenärer och närliggande alvboplatser.",al={"varför är tysha moonblade i darkshore","tysha moonblades postering","varför är tysha nära ameth'aran"}},d2f2f0b1={q="Vad vill Sentinel Tysha Moonblade?",a="Moonblade söker kompetenta äventyrare från Alliansen som kan avslöja den tragiska historia som hemsöker ruinerna av Ameth'Aran. Genom att leda sina allierade till att undersöka de krossade relikerna och forntida berättelserna om stadens fall hoppas hon bringa klarhet och ro åt de rastlösa andar som dröjer kvar i vildmarken.",al={"vad behöver tysha moonblade","tysha moonblades uppdrag","varför behöver tysha hjälp"}}},fp="24,211,19.367.0,32.162.0,42.102.0,40.164.0,43.125.0"}
P.entries["npc:sentinel-velene-starstrike"] = {n="Sentinel Velene Starstrike",s="Sentinel Velene Starstrike är en nattalvsväktare stationerad vid Silverwind Refuge i centrala Ashenvale. Hon har i uppdrag att skydda fristaden och vattnen runt den, och tar sig an onaturliga hot som lössläppta elementarer och onda trollkarlar. Hennes vaksamhet hjälper till att skydda den uråldriga skogen från fördärvande magisk påverkan.",h="Sentinel Velene Starstrike är en nattalvsväktare stationerad vid Silverwind Refuge i centrala Ashenvale.",kw={"ashenvale","elementararmskenor","magiker som åkallar","mystral lake","väktare","silverwind refuge","starstrike","velene"},ang={["class:Mage"]="Velene har föga tålamod med oansvariga magiker vars vårdslösa besvärjelser hetsar upp områdets elementarer och förorenar naturliga vatten.",["faction:Alliance"]="Silverwind Refuge erbjuder trygghet längs en farlig väg, och Sentinel Velene samordnar de lokala insatserna för att hålla centrala Ashenvale säkert.",["race:NightElf"]="Sentinel Velene förkroppsligar väktarnas outtröttliga hängivenhet. Hon står som ett bålverk mot magisk vårdslöshet för att bevara Ashenvales naturliga harmoni."},sec={{t="Silverwinds väktare",b="Sentinel Velene Starstrike håller vakt från Silverwind Refuge, intill Mystral Lakes klara vatten. Liksom många andra nattalvsväktare utposterade i Ashenvale är hennes främsta uppgift att bevara skogens balans och slå tillbaka hot mot nattalvernas fristäder. Den fridfulla lunden är en viktig rastplats för resande genom de centrala skogarna, så hennes närvaro är avgörande för områdets säkerhet."},{t="Störningar vid Mystral Lake",b="Freden runt Silverwind Refuge är skör. Velene håller Mystral Lake under noggrann uppsikt, där oberäkneliga elementandar och ansvarslösa magiker som åkallar dem stör vildmarkens naturliga rytm. På hennes uppdrag skickas hjältar ut för att kuva lössläppta vattenelementarer och sätta stopp för de vårdslösa utövare som stör landets andar."}},faq={{q="Var finns Sentinel Velene Starstrike?",a="Sentinel Velene Starstrike är stationerad vid Silverwind Refuge, en utpost för Alliansen i centrala Ashenvale, nära Mystral Lakes sydöstra strand.",al={"velene starstrikes plats","var finns velene","uppdragsgivare i silverwind refuge"}},{q="Vilka uppdrag ger Sentinel Velene?",a="Velene ber äventyrare ta itu med de störda andarna och utövarna runt Mystral Lake. Hon skickar dem för att samla armskenor från oroliga elementarer och oskadliggöra de lössläppta åkallarna som rör upp vattnet.",al={"velene starstrikes uppdrag","vilka uppdrag ger velene"}},{q="Vilket hot finns vid Mystral Lake?",a="Mystral Lakes vatten har plågats av aggressiva vattenelementarer, som bringats i uppror och utnyttjas av dödliga magiker som åkallar dem utan hänsyn till skogens ömtåliga harmoni.",al={"problemet vid mystral lake","varför finns elementarer vid mystral lake"}},{q="Är Velene släkt med någon annan i Kalimdor?",a="Hon delar efternamnet Starstrike med Layo Starstrike, en nattalv stationerad långt söderut i Silithus karga ödemarker. Det antyder att de tillhör samma släkt eller hus.",al={"starstrike-släkten","släkting till layo starstrike"}},{q="Vad är Silverwind Refuge?",a="Silverwind Refuge är en fridfull tillflyktsort för nattalver, inbäddad längs stränderna vid Mystral Lake i Ashenvale. Den tjänar som en rofylld fristad och taktisk utpost för väktare och allierade resande som tar sig genom skogens vilda inre.",al={"vad är silverwind refuge","silverwind refuge i berättelsen"}},{q="Varför bryr sig väktarna om elementaraktivitet?",a="Nattalver ser vildmarken som ett heligt, levande ekosystem. Våldsamma eller fördärvade elementarer stör den inhemska faunan och förorenar de naturliga vattendragen, vilket tvingar väktarna att ingripa och återställa balansen.",al={"varför slåss nattalver mot elementarer","väktare och elementarer"}}},fx={["8f53b9bb"]={q="Vem är Sentinel Velene Starstrike?",a="Sentinel Velene Starstrike är en nattalvsväktare bland sentinelerna, stationerad vid Silverwind Refuge i Ashenvale. Liksom sina vapenbröder är hon hängiven åt att försvara Kalimdors heliga skogar mot fördärv och fientliga inkräktare, och vakar noga över närliggande områden som Mystral Lake.",al={"vem är velene","velene starstrikes bakgrund","vem är sentinel velene starstrike"}},["2ad68975"]={q="Vems sida står Sentinel Velene Starstrike på?",a="Sentinel Velene Starstrike är lojal mot nattalvernas sentineler och står stadigt på Alliansens sida. Hon erbjuder hjälp, vägledning och uppdrag åt resenärer som tjänar Alliansen och vill bidra till att skydda Ashenvale.",al={"velene starstrikes fraktion","sentinel velene och alliansen","velene starstrikes lojalitet"}},["33a0de05"]={q="Varför är Sentinel Velene Starstrike här?",a="Velene är posterad vid Silverwind Refuge för att bevaka vildmarken och samordna sentinelernas insatser i centrala Ashenvale. Området hotas allt mer av aggressiva vilda djur, oregerliga elementarvarelser kring Mystral Lake och främmande intrång som hotar skogsmarkernas helgd.",al={"varför är velene vid silverwind refuge","velene starstrikes syfte","varför är velene starstrike i ashenvale"}},["9d94d468"]={q="Vad vill Sentinel Velene Starstrike?",a="Velene vill återställa harmoni och trygghet i den omgivande vildmarken. Hon rekryterar dugliga mästare från Alliansen för att undersöka den oroande elementaroron vid Mystral Lake, motverka magiska hot och driva tillbaka fientliga styrkor som närmar sig tillflyktsorten.",al={"vad vill velene","velene starstrikes mål","vad försöker velene göra"}}},fp="26,219,22.294.0,28.285.0,44.127.0,39.148.0,35.153.0,45.156.0,26.197.0,51.175.0"}
P.entries["npc:serge-hinott"] = {n="Serge Hinott",s="I Tarren Mill brygger Serge Hinott blandningar åt de Fördömdas krigsinsats. Den Fördömdas alkemist arbetar tillsammans med Apothecary Lydon och förbereder brygder, motgifter och reagenser åt Royal Apothecary Society.",h="I Tarren Mill brygger Serge Hinott blandningar åt de Fördömdas krigsinsats.",kw={"apothecary lydon","hillsbrad foothills","hinott","royal apothecary society","serge hinott","tarren mill"},ang={["class:Rogue"]="Som Rogue kan du söka upp Hinott för att få bot mot det våldsamma Touch of Zanzil. Han tillverkar motgiftet när vanliga läkemedel inte hjälper.",["race:Undead"]="Som Undead får du se Royal Apothecary Societys praktiska arbete i Hillsbrad: kemiska blandningar och stöd åt de Fördömdas styrkor vid frontlinjen."},sec={{t="Apothecary Lydons medhjälpare i Tarren Mill",b="Serge Hinott brygger läkemedel och andra blandningar åt de Fördömda i Tarren Mill. Han arbetar sida vid sida med Apothecary Lydon, vars arbete omfattar kemisk utveckling och pestforskning riktad mot närliggande mänskliga bosättningar som Southshore. Hinott sköter specialiserad bryggning, bland annat läkande salvor och motgifter åt fältagenter och spejare som utsätts för gifter eller andra giftiga olyckor."}},faq={{q="Var hittar du Serge Hinott?",a="Serge Hinott arbetar utomhus i Tarren Mill, i centrala norra Hillsbrad Foothills. Han befinner sig nära Apothecary Lydon, bland bryggningsförråd och alkemisk utrustning.",al={"serge hinotts plats","var finns hinott","hitta serge hinott"}},{q="Vilken roll har Serge Hinott?",a="Serge Hinott tjänar de Fördömda som alkemist i Tarren Mill. Han tillreder lokala brygder och behandlingar samt gör specialblandningar åt fältoperatörer och kurirer som ber om dem.",al={"vad gör hinott","serge hinotts roll"}},{q="Vilken koppling har Hinott till Apothecary Lydon?",a="Serge Hinott arbetar sida vid sida med Apothecary Lydon i Tarren Mill. När besökare stör honom säger Hinott åt dem att gå och besvära ”Mr. High-And-Mighty” i stället.",al={"hinott och lydon","vem arbetar hinott med"}}},fx={ed373d2b={q="Vem är Serge Hinott?",a="Serge Hinott är en alkemist bland de Förfallna, stationerad vid Tarren Mill i Hillsbrad Foothills. Han arbetar nära Apothecary Lydon och bidrar med sin kunskap om brygder och läkemedel till de Förfallnas sak. Han hjälper också resenärer med sitt hantverkskunnande inom alkemi.",al={"vem är hinott","serge hinotts bakgrund","vem är serge"}},d070d0a8={q="Vems sida står Serge Hinott på?",a="Serge Hinott är lojal mot de Förfallna och Horden. Hans alkemiska arbete, stationerad vid den omstridda gränsen i Hillsbrad Foothills, stöder Hordens närvaro och överlevnad mot närliggande hot.",al={"hinotts fraktion","är serge hinott med i horden","vem tjänar hinott"}},["080bb72f"]={q="Vad vill Serge Hinott?",a="Hinott fokuserar på att fullända sitt hantverk, brygga kraftfulla drycker och bidra med sin alkemi till dem som hjälper de Förfallna. Han hjälper allierade som behöver särskilda läkemedel och blandningar för att motverka gift och sjukdom i regionen.",al={"hinotts mål","vad gör hinott","hinotts syfte"}},["10d74ddb"]={q="Varför är Serge Hinott i Hillsbrad Foothills?",a="Hinott har sin bas i Tarren Mill för att stödja de Förfallnas främsta utpost i Hillsbrad Foothills. Tillsammans med Apothecary Lydon hjälper han Hordens mästare som verkar i skuggan av Hillsbrads hårda gränskonflikter.",al={"varför är hinott i tarren mill","varför är serge här","orsak till hinotts plats"}}},fp="12,210,32.375.0,32.166.0,34.187.0,48.153.0"}
P.entries["npc:shadow-priest-allister"] = {n="Shadow Priest Allister",s="Shadow Priest Allister är en präst av de Bortfördöda som är stationerad i The Sepulcher i Silverpine Forest. Han övervakar underrättelsearbete och taktiska insatser i regionen, samordnar operationer för att bevaka Dalarans magiker och säkra Lordaerons gränser åt den Mörka Damen.",h="Shadow Priest Allister är en präst av de Bortfördöda som är stationerad i The Sepulcher i Silverpine Forest.",kw={"allister","ambermill","dalaran","de bortfördömda","holy bologna","the sepulcher","skuggpräst","silverpine"},ang={["class:Priest"]="Som författare till ”Holy Bologna” står Allister för de Bortfördöda prästernas desillusion inför Ljuset.",["faction:Horde"]="Allister arbetar för att säkra Silverpine Forest och se till att Hordens allierade tryggt kan färdas mellan Tirisfal Glades och länderna i söder.",["race:Undead"]="Allister är ett exempel på de Bortfördödas skoningslösa pragmatism. Han vänder ryggen åt forna heliga dogmer för att skydda sitt folk mot levande fiender."},sec={{t="Väktare i The Sepulcher",b="Shadow Priest Allister leder de Bortfördödas spaning i Silverpine Forest från The Sepulcher. Från denna centrala kryptbosättning håller han uppsikt över närliggande hot, från upproriska människor och anfall från bestar till de arkaniska intriger som pågår kring Dalaran."},{t="Ögon på Ambermill och Dalaran",b="Allisters främsta oro gäller Dalarans överlevande magiker, särskilt dem som håller till i Ambermill och spanar över gränserna. Han tänker inte låta Kirin Tor befästa sin ställning i de Bortfördödas land. Därför skickar han ut agenter för att genskjuta Dalarans budbärare, tyda arkaniska runor och ta reda på magikernas långsiktiga ambitioner."},{t="Kätterska funderingar",b="Utöver sina uppgifter som fältstrateg är Allister en cynisk skuggfilosof. Han har skrivit ”Holy Bologna: What the Light Won't Tell You”, en skoningslös avhandling som kritiserar traditionella heliga läror. Texten utforskar odödlighetens hårda verklighet och hur det Heliga Ljuset sviker dem som livet förkastat. På något sätt har verket spridits ända till ruinerna av Dire Maul i Kalimdor."}},faq={{q="Vem är Shadow Priest Allister?",a="Han är en skuggpräst av de Bortfördöda, stationerad i The Sepulcher i Silverpine Forest. Där samordnar han övervakning och anfall mot närliggande hot, särskilt Dalarans styrkor.",al={"allister","shadow priest allister","vem är allister i silverpine"}},{q="Var hittar jag Shadow Priest Allister?",a="Han håller till i The Sepulcher, den främsta bosättningen för de Bortfördöda, längs huvudvägen genom Silverpine Forest.",al={"allisters plats","var finns shadow priest allister","hitta allister"}},{q="Varför fokuserar Allister på Dalaran och Ambermill?",a="Kirin Tors magiker i Ambermill utgör ett ständigt hot mot de Bortfördödas territorium. Allister försöker dechiffrera deras meddelanden, avslöja deras avsikter och hålla deras inflytande i schack.",al={"allister dalaran","varför anfalla ambermill","dalarans hot mot silverpine"}},{q="Vilken bok skrev Allister?",a="Allister skrev ”Holy Bologna: What the Light Won't Tell You”, en respektlös och kritisk uppgörelse med det Heliga Ljuset som nådde över havet till de uråldriga biblioteken i Dire Maul.",al={"allisters bok","holy bologna","vad ljuset inte berättar"}},{q="Vilka uppdrag erbjuder Allister?",a="Han erbjuder flera uppdrag för att samla underrättelser i Silverpine Forest, bland annat Border Crossings, Maps and Runes, Ambermill Investigations och uppgifter där du konfronterar Dalarans agenter.",al={"allisters uppdrag","skuggprästens uppdrag i the sepulcher"}},{q="Varför utövar Allister skuggmagi i stället för det Heliga Ljuset?",a="Liksom många präster bland de Bortfördöda kände Allister sig övergiven av det Heliga Ljuset efter sin död. Han vände sig till skuggorna och fann kraft och beslutsamhet i en lära som bejakar deras odöda tillvaro.",al={"varför skuggpräst","de bortfördödas skuggmagi allister"}}},fx={bfa3e4a4={q="Vems sida står Shadow Priest Allister på?",a="Allister är fullständigt lojal mot de Förfallna och den Mörka Damen. Han är stationerad i Sepulchers kryptor och använder helt sina mörka konster och sitt beräknande intellekt för att säkra Lordaeron åt de odöda och oskadliggöra regionala hot mot deras bräckliga nya domän.",al={"allisters fraktion","vem tjänar shadow priest allister","är allister en av de förfallna"}},["9415cd7f"]={q="Varför är Shadow Priest Allister här i Silverpine Forest?",a="Allister verkar från Sepulcher och håller ett vakande öga på fientliga enklaver längs de södra gränserna. Dalarans överlevande trollkarlar har förskansat sig i Ambermill, och märklig magi rör sig i närheten. Hans uppgift är att leda de Förfallnas agenter till att undersöka fiendens försvar och avslöja deras verkliga avsikter.",al={"varför är allister vid sepulcher","allisters syfte i silverpine forest","varför är shadow priest allister här"}}},fp="22,173,24.193.0,29.278.0,17.352.0,30.175.0,40.121.0,49.163.0,29.160.0,32.180.0,66.169.0"}
P.entries["npc:shadow-priest-sarvis"] = {n="Shadow Priest Sarvis",s="Shadow Priest Sarvis står i det förfallna kapellet i Deathknell och är en av de viktigaste vägvisarna för nyväckta Forsaken. Han visar de nyuppståndna deras dystra verklighet och skickar dem för att göra sig av med tanklösa odöda och samla information om lokala hot. Under Lady Sylvanas fana arbetar Sarvis outtröttligt för att forma förvirrade odöda till disciplinerade tjänare åt Forsaken.",h="Shadow Priest Sarvis står i det förfallna kapellet i Deathknell och är en av de viktigaste vägvisarna för...",kw={"deathknell","forsaken","novice elreth","sarvis","shadow priest sarvis","tirisfal glades"},ang={["class:Priest"]="Sarvis förkroppsligar Forsakens omfamning av skuggmagi och fungerar som en mörk mentor i ett kapell som berövats det heliga ljuset.",["race:Undead"]="Sarvis är en av de allra första rösterna du hör efter att ha vaknat ur graven. Han visar dig vägen mot att tjäna den mörka damen."},sec={{t="Vägvisare för de nyväckta",b="I det skuggiga kapellet i Deathknell väntar Shadow Priest Sarvis på dem som just har klöst sig upp ur graven. En Forsakens uppvaknande är omtumlande och fasansfullt, och många förlorar genast förståndet i ett tanklöst raseri eller en djup uppgivenhet. Sarvis blir ett ankare och ger de nyuppståndna ett mål. Han ger nya rekryter i uppdrag att slå ner de hasande, tanklösa lik som strövar omkring på kyrkogården och leder dem till att säkra Deathknells gränser mot den annalkande Scourge."},{t="Försvara Deathknell",b="Utöver att hjälpa nya rekryter att vänja sig vid sin tillvaro övervakar Sarvis viktiga lokala försvar mot kvarvarande hot i Tirisfal Glades. Han samordnar begränsningen av Scourge-styrkor som sonderar Deathknells utkanter. Genom att skicka noviser på uppdrag för att samla viktig information och genomgå stridsprov ser Sarvis till att staden förblir en befäst bastion för Forsaken."}},faq={{q="Vem är Shadow Priest Sarvis?",a="Sarvis är en Forsaken-skuggpräst stationerad i Deathknell. Han vägleder nyväckta odöda, ger dem deras första order och hjälper till att försvara staden mot Scourge.",al={"sarvis","vem är sarvis","deathknell präst"}},{q="Var hittar jag Shadow Priest Sarvis?",a="Han finns i den förfallna kyrkan mitt i Deathknell, Forsakens startområde i Tirisfal Glades.",al={"sarvis plats","var är sarvis","hitta sarvis"}},{q="Varför låter Sarvis spelare döda tanklösa zombier?",a="Alla lik som återuppstår behåller inte sin fria vilja och sitt förstånd. De som dukar under för vansinnet ses som en fara för bosättningen och måste förstöras innan de hotar de levande döda.",al={"varför döda de tanklösa","de tanklösa"}}},fp="20,169,30.343.0,19.269.0,28.164.0,38.100.0,51.178.0"}
P.entries["npc:shael-dryn"] = {n="Shael'dryn",s="Shael'dryn är en nyfiken dryad som bor vid Moonwell of Purity, öster om Iris Lake i Ashenvale. Hon är en viktig kontakt för nattalvsspejare som undersöker skogens fördärv. Hon spelar en avgörande roll när hon hjälper Astranaars väktare med renande reliker för att bekämpa demoniska och onda krafter som sprider sig i vildmarken.",h="Shael'dryn är en nyfiken dryad som bor vid Moonwell of Purity, öster om Iris Lake i Ashenvale.",kw={"ashenvale","cenarius","rening","dryad","illiyana","raene","raynewood","shael'dryn","shaeldryn"},ang={["class:Druid"]="Druider uppskattar hennes naturliga band till Kalimdors andar och hennes kunskap om hur man återställer växter och djur som förvridits av mörka krafter.",["faction:Alliance"]="Moonwell of Purity är en fristad i Ashenvale, där Shael'dryn hjälper Alliansens styrkor att stå emot fördärv och fientliga intrång.",["race:NightElf"]="För Kaldorei är Shael'dryn en välkommen skogssyster vars naturliga band till Cenarius gör henne oumbärlig när besudlade skogsreliker ska renas."},sec={{t="Månbrunnens väktare",b="Shael'dryn håller till vid Moonwell of Purity och vakar tillsammans med nattalvernas väktare över skogens östra tillfartsvägar. När fördärv drabbar traktens djurliv eller besudlade reliker hotar landets harmoni, kan hennes djupa förståelse för naturen vägleda äventyrare genom stegen som krävs för att återställa den andliga balansen."},{t="Renande av skogen",b="Shael'dryn samarbetar nära med Raene Wolfrunner i Astranaar. När väktarna hittar besudlade föremål, som fördärvade lysande ädelstenar och de förlorade delarna av Dartol's Rod, känner Shael'dryn till de dunkla ritualer, månbrunnsvatten och naturföremål som behövs för att rena dem. På så sätt förvandlar hon mörka kuriositeter till kraftfulla reningsredskap för Alliansen."}},faq={{q="Vem är Shael'dryn?",a="Shael'dryn är en dryad som finns vid Moonwell of Purity i Ashenvale. Hon hjälper Alliansens äventyrare med skogskunskap och naturmagi, samtidigt som hon gärna bjuder på ordvitsar och skämt.",al={"vem är hon","shael dryn bakgrund","shaeldryn identitet"}},{q="Var hittar jag Shael'dryn?",a="Hon finns vid Moonwell of Purity, öster om Iris Lake i Ashenvale.",al={"shaeldryn plats","var finns shael'dryn","raynewood-dryad"}},{q="Vad har Shael'dryn för koppling till Raene Wolfrunner?",a="Raene Wolfrunner hänvisar äventyrare till Shael'dryn eftersom dryaden har de andliga kunskaper som krävs för att undersöka och rena fördärvade ädelstenar och reliker som hittats i skogen.",al={"raene och shaeldryn","raenes renande dryad","varför hänvisas jag till shaeldryn"}},{q="Vad är unikt med Shael'dryns utseende?",a="Shael'dryn och hennes dryadsyster Illiyana har en ovanlig färgteckning som skiljer deras modeller från de flesta andra dryader på Kalimdor.",al={"dryadmodell","unik hudfärg","shaeldryns färg"}},{q="Är Shael'dryn vänligt inställd till Horden?",a="Nej. Shael'dryn håller till vid Moonwell of Purity och är nära allierad med Astranaars väktare. Hon är fientligt inställd till Hordens medlemmar.",al={"kan horden prata med shaeldryn","hordens rykte","är shaeldryn bara för alliansen"}}},fx={["70f31310"]={q="Vad vill Shael'dryn?",a="Shael'dryn arbetar för att skydda och rena de omgivande skogarna i Ashenvale. Hon hjälper allierade som Raene Wolfrunner genom att leda resenärer till att undersöka hot, samla forntida skogsreliker och återställa balansen i fördärvade marker.",al={"shael'dryns mål","vad gör shael'dryn","shael dryns syfte"}},["3c3b07cb"]={q="Varför är Shael'dryn vid renhetens månskälla?",a="Som en dotter till Cenarius håller Shael'dryn uppsikt över östra Ashenvale från renhetens månskälla öster om Iris Lake. Därifrån bevakar hon hur fördärvet tränger in i skogen och hjälper nattalverna som försvarar sina heliga lundar.",al={"varför är shael dryn här","varför är shael'dryn i ashenvale","shael'dryn raynewood"}}},fp="10,209,24.296.0,25.312.1,18.162.0,28.79.0,52.172.0,45.142.0,36.147.0"}
P.entries["npc:shanda"] = {n="Shanda",s="Shanda är en prästinna bland nattalverna och mentor i den ihåliga stammen på Aldrassil i Shadowglen. Som medlem av The Sisterhood of Elune lär hon nyblivna präster bland nattalverna månens gudinnas grundläggande böner, skyddsbesvärjelser och riter. Hennes vägledning hjälper de unga akolyterna att förena Elunes ljus med sina plikter att försvara Teldrassil.",h="Shanda är en prästinna bland nattalverna och mentor i den ihåliga stammen på Aldrassil i Shadowglen.",kw={"aldrassil","elune","night elf","prästtränare","shadowglen","shanda","the sisterhood of elune","teldrassil"},ang={["class:Priest"]="För präster bland nattalverna som inleder sin resa i Shadowglen är Shanda den första mentorn som erbjuder heliga ord och vägledning i Elunes nåd.",["race:NightElf"]="Shanda för vidare den bestående traditionen inom The Sisterhood of Elune och värnar om den unga Kaldoreis andliga välmående när de tar sina första steg på Teldrassil."},sec={{t="Akolyt under modergudinnan",b="I Aldrassils fridfulla helgedom är Shanda en av de första andliga vägledarna för unga nattalver som vigt sig åt Elune. Medan druiderna vårdar Teldrassils vaknande rötter och grenar ser prästinnor som Shanda till att Kaldoreis andliga hjärta förblir knutet till den Vita Damen. Hon lär nya invigda att kanalisera månens nåd för att hela och skapa skyddande besvärjelser, så att de är redo att möta fördärvet som sprider sig bland världsträdets grenar."},{t="Vägledning för nya invigda",b="När unga präster upptäcker sitt kall i Shadowglen skickas de till Shanda för att visa sin hängivenhet och lära sig sina första böner. Genom riter som In Favor of Elune prövar hon deras beslutsamhet och ger dem välsignade kläder och grundläggande besvärjelser. Under hennes ledning lär sig eleverna att en prästinna bland Kaldorei måste vara både en varsam hand för de sårade och en orubblig sköld mot skuggorna."}},faq={{q="Vem är Shanda?",a="Shanda är en prästtränare bland nattalverna, inne i Aldrassil, det centrala trädsamhället i Shadowglen på Teldrassil. Hon lär nyvaknade präster bland nattalverna The Sisterhood of Elunes läror.",al={"vem är den här npc:n","shandas bakgrund","prästtränare aldrassil"}},{q="Vilken roll har Shanda för nya präster?",a="Hon lär nyblivna präster grundläggande böner, läkande besvärjelser och skyddsmagi från Elune. Nya präster tar med sig sitt Hallowed Sigil till henne, och hon skickar dem vidare till nästa steg i träningen genom In Favor of Elune.",al={"prästtränarens roll","vad lär shanda ut","vad gör shanda"}},{q="Var hittar jag Shanda?",a="Shanda finns på markplanet inne i den ihåliga stammen på Aldrassil, det väldiga trädet som fungerar som startområde i Shadowglen på Teldrassil.",al={"var finns shanda","shandas plats","hur hittar man shanda"}},{q="Vilken organisation tillhör Shanda?",a="Shanda är medlem av The Sisterhood of Elune, den urgamla religiösa orden av prästinnor bland nattalverna som har väglett Kaldoreis andliga och kulturella liv i tusentals år.",al={"shandas fraktion","the sisterhood of elune","är shanda en månprästinna"}}},fx={["35bebf44"]={q="Vad vill Shanda?",a="Shanda ägnar sig åt att förbereda nästa generation nattalvprästinnor för att tjäna mångudinnan och skydda sitt folk. Hon vill vägleda unga noviser i att kanalisera Elunes gudomliga nåd och lära dem att läka skador, skydda sina allierade och slå ner den växande korruptionen som kryper in i Shadowglen.",al={"shandas mål","shandas motiv","vad vill prästtränaren shanda"}},["44a52b27"]={q="Varför är Shanda i Aldrassil?",a="När nyvaknade försvarare samlas i Aldrassils heliga tillflykt behövs erfarna mentorer som kan slipa deras råa talanger. Shanda stannar vid foten av det stora trädet i Shadowglen för att vaka över nya prästnoviser och se till att de lär sig Elunes riter och krafter innan de beger sig djupare in i Teldrassil.",al={"varför är shanda här","varför är shanda i shadowglen","varför shanda är här"}}},fp="6,204,26.338.0,21.345.0,14.185.0,43.222.0,24.88.0,40.162.0"}
P.entries["npc:shandris-feathermoon"] = {n="Shandris Feathermoon",s="Shandris Feathermoon är Sentinel-arméns general och har i tiotusen år varit Tyrande Whisperwinds högra hand. Nu leder hon nattalvernas militära styrkor i Kalimdor från Feathermoon Stronghold på Sardor Isle utanför Feralas kust.",h="Shandris Feathermoon är Sentinel-arméns general och har i tiotusen år varit Tyrande Whisperwinds högra hand.",kw={"feathermoon","feralas","general","kaldorei","sardor isle","sentinels","shandris","tyrande"},ang={["class:Hunter"]="Jägare och skogsvaktare vördar Shandris som en av Sentinels skickligaste skyttar, en general som har hållit vakt över nattalverna i tiotusen år.",["faction:Alliance"]="För Alliansens styrkor som ger sig in i södra Kalimdor erbjuder General Feathermoon en oumbärlig flottbas, strategiskt ledarskap och en välbefäst fristad på Sardor Isle.",["faction:Horde"]="Horden ser General Feathermoon som en farlig och listig militärstrateg vars fästning utanför Feralas kust hotar deras expansion i regionen.",["race:NightElf"]="För Kaldorei står General Feathermoon för Sentinels disciplin och plikt i dess högsta form. Hon har skyddat folket sedan den långa vakten började."},sec={{t="Tyrandes högra hand",b="Shandris Feathermoon är en av nattalvernas äldsta försvarare. I tiotusen år har hon stått vid Tyrande Whisperwinds sida som översteprästinnans högra hand bland Sentinels, genom den långa vakten efter Sundringen."},{t="Sentinels uppkomst",b="Efter den stora Sundringen och grundandet av Sentinels blev Shandris en oumbärlig befälhavare inom nattalvernas militär."},{t="Feralas bastion",b="I dag tjänstgör General Feathermoon som Sentinel-arméns högsta fältbefälhavare. Från Sardor Isle övervakar hon Feathermoon Stronghold, en imponerande alvisk fästning som håller vakt över Feralas urskogar. Från denna utpost på ön bevakar hon hoten från vilda gnoller, kvarvarande Gordunni-ogrer, hatdrivna satyrer och Hordens växande makt i södra Kalimdor."}},faq={{q="Vem är Shandris Feathermoon?",a="Shandris Feathermoon är Sentinels general, nattalvernas stående militära styrka. Hon är en uråldrig nattalv och har i tiotusen år varit översteprästinnan Tyrande Whisperwinds högra hand. Hon leder Sentinels från Feathermoon Stronghold i Feralas.",al={"vem är shandris","shandris bakgrund","vem är nattalvgeneralen i feralas"}},{q="Var finns Shandris Feathermoon?",a="Hon leder från Feathermoon Stronghold, som ligger på Sardor Isle utanför Feralas västkust i södra Kalimdor.",al={"shandris plats","var finns shandris feathermoon","feathermoon strongholds ledare"}},{q="Vilken relation har Shandris till Tyrande Whisperwind?",a="Shandris har varit Tyrande Whisperwinds högra hand i Sentinels i tiotusen år. Tyrande leder nattalverna från Darnassus, medan Shandris leder Sentinel-armén i fält från Feathermoon Stronghold.",al={"är shandris tyrandes dotter","tyrande och shandris","tyrandes adoptivbarn"}},{q="Kämpade Shandris mot Burning Legion?",a="Ingen strid där hon mötte Legion finns nedtecknad i de historier som berättas här. Det man vet är att hon i tiotusen år har tjänat vid Tyrande Whisperwinds sida bland Sentinels och nu leder Sentinel-armén från Feathermoon Stronghold.",al={"de äldstes krig shandris","kämpade shandris mot archimonde"}},{q="Varför är hon stationerad i Feralas i stället för på Teldrassil?",a="Som Sentinel-general måste Shandris leda militära operationer vid fronten i hela Kalimdor. Feathermoon Stronghold är Alliansens främsta samlingsplats och försvarsvärn i de vilda skogarna i söder, där fientliga ogres, satyrer och Hordens verksamhet hålls under uppsikt.",al={"varför är shandris i feralas","varför finns feathermoon stronghold"}}},fp="20,251,20.247.0,21.138.0,22.413.0,28.279.0,40.120.0,55.221.0,46.250.0,54.269.0"}
P.entries["npc:shari-stilwell"] = {n="Shari Stilwell",s="Shari Stilwell är en paladintränare bland de Fördömda, stationerad i bosättningen Brill i Tirisfal Glades. Hon bär samma efternamn som framstående personer i Eastern Kingdoms och lär Fördömda att axla rollen som heliga krigare. Hennes närvaro vittnar om en sällsynt och okonventionell disciplin bland de odöda under Banshee Queen.",h="Shari Stilwell är en paladintränare bland de Fördömda, stationerad i bosättningen Brill i Tirisfal Glades.",kw={"brill","fördömda","ljus","paladin","shari","stilwell","tirisfal","tränare"},ang={["class:Paladin"]="För Fördömda paladiner som påbörjar sin resa i Tirisfal Glades är Shari Stilwell den främsta tränaren och mentorn i Brill.",["race:Undead"]="Shari Stilwell speglar hur familjer tragiskt splittrades under Tredje kriget. Hon står som odöd mentor medan möjliga släktingar lever långt söderut."},sec={{t="Ett ljus i Brill",b="Bland Brills pestsmittade byggnader framträder Shari Stilwell som mentor för Fördömda heliga krigare. Det heliga Ljuset orsakar outhärdlig smärta hos de odöda, men Shari vägleder nybörjare bland de Fördömda som uthärdar den plågsamma vägen. Hon hjälper nykomlingar att hitta sin plats i Tirisfal Glades genom deras första träningspass och anpassning, och vägleder dem som vill säkra en plats i de Fördömdas kungarike."},{t="Stilwellska släktband",b="Shari delar sitt efternamn med flera levande personer utspridda över de södra kungadömena, däribland Daphne, Merissa och den berömda smeden Jordan Stilwell. Om hon skildes från dessa släktingar när Lordaeron föll eller bara har avlägsna släktband till dem förblir en outsagd tragedi efter plågans härjningar."}},faq={{q="Vem är Shari Stilwell?",a="Shari Stilwell är en odöd paladintränare stationerad i Brill i Tirisfal Glades. Hon hjälper Fördömda paladiner med deras första strids- och heliga undervisning medan de lär sig att överleva i Lordaeron.",al={"vem är shari stilwell","shari stilwells historia","paladintränare i brill"}},{q="Var hittar man Shari Stilwell?",a="Hon finns i staden Brill, strax norr om ruinerna av Capital City och Undercity i Tirisfal Glades.",al={"shari stilwells plats","var finns shari stilwell","hitta shari stilwell"}},{q="Är Shari släkt med Jordan Stilwell?",a="Hon delar efternamn med Jordan Stilwell, den berömde mänsklige smeden, liksom med Daphne och Merissa Stilwell. Deras exakta släktförhållande är obekräftat, men det bröts troligen av pesten som ödelade Lordaeron.",al={"släkt med jordan stilwell","stilwells släktband","shari stilwells släktingar"}},{q="Kan Fördömda använda Ljuset som paladiner?",a="Att kanalisera det heliga Ljuset är djupt smärtsamt för odöda och orsakar intensiv plåga och brännande känslor. Tränare som Shari Stilwell vägleder dock beslutsamma Fördömda genom den mentala styrka och hängivenhet som krävs för att använda både stridskonst och helig kraft.",al={"fördömda paladiner","hur kan odöda vara paladiner","odöda paladiner i historien"}}},fx={["1254553f"]={q="Vilken sida står Shari Stilwell på?",a="Shari Stilwell står orubbligt på de Förvärrades och Hordens sida. Hon håller till i Brill och tjänar Lady Sylvanas Windrunners rike genom att undervisa och vägleda Förvärrade som vandrar paladinens krävande och paradoxala väg i odöden.",al={"shari stilwells fraktion","vem tjänar shari","tillhör shari stilwell horden"}},e32993c8={q="Varför är Shari Stilwell i Brill?",a="Shari Stilwell är stationerad i Brill som paladintränare åt de nyvaknade odöda i Tirisfal Glades. När unga odöda lämnar Deathknell och söker en fristad eller ett syfte i ett andra hem ser hon till att de som dras till paladinens kall får rätt disciplin och träning.",al={"varför är shari i brill","shari stilwells syfte","vad gör shari stilwell här"}}},fp="14,180,17.345.0,25.277.0,22.181.0,34.115.0,36.212.0,41.191.0"}
P.entries["npc:shelene-rhobart"] = {n="Shelene Rhobart",s="Shelene Rhobart är tränare i läderarbete för Forsaken och håller till längs vägen i Tirisfal Glades. Från en Deathguard-utpost förser hon Forsaken med garvade hudar och utbildning i läderhantverk, till stöd för deras militära och logistiska insatser i de fördärvade länderna.",h="Shelene Rhobart är tränare i läderarbete för Forsaken och håller till längs vägen i Tirisfal Glades.",kw={"brill","hides for the forsaken","läderarbete","shelene rhobart","tirisfal glades"},ang={["race:Undead"]="Shelene står för den praktiska grunden i Forsakens industri och ser till att de lokala försvararna får rätt utrustning trots förfallet och ödeläggelsen i Tirisfal."},sec={{t="Hantverk för Forsaken",b="Shelene Rhobart utövar sitt hantverk vid en Deathguard-utpost, en förläggning sydost om Brill längs huvudvägen mot ruinerna av Lordaeron. Även efter döden är praktiska hantverk viktiga för överlevnad och krig. Shelene arbetar med djurhudar från bestarna som stryker omkring i Tirisfal och förädlar tåliga hudar till rustningar, remmar och fältutrustning åt lokala Forsaken-patruller som kämpar mot både Scourge och Scarlet Crusade."}},faq={{q="Var hittar jag Shelene Rhobart?",a="Shelene Rhobart håller till vid en liten Forsaken-utpost sydost om Brill i Tirisfal Glades, längs vägen mot Undercity.",al={"shelene rhobart plats","var finns shelene rhobart","shelene rhobart karta"}},{q="Vilken uppgift har Shelene Rhobart?",a="Hon är en skicklig tränare i läderarbete. Hon lär blivande läderarbetare grunderna i att garva hudar, sy klädesplagg och sätta ihop skyddande läderutrustning åt Forsaken.",al={"vad gör shelene rhobart","shelene rhobart tränare","shelene yrke"}},{q="Varför behöver hon djurhudar?",a="Odöd hud läker inte, så när Forsaken skadas måste de laga sig med djurhudar. Shelenes förråd börjar sina, och hon vill ha Duskbat Wing-membran, Darkhound-hudar och hud från Vile Fin-murlocer, eftersom olika tjocklekar passar olika delar av kroppen.",al={"hudar åt forsaken-uppdraget","varför samla hudar i tirisfal"}}},fx={["383979a9"]={q="Vem är Shelene Rhobart?",a="Shelene Rhobart är en odöd läderarbetare som tjänar de Förvärrade i Tirisfal Glades. Liksom många av sina fränder behöll hon hantverket och färdigheterna hon utövade i livet. Nu delar hon med sig av sin expertis för att lära upp blivande läderarbetare och tillverka viktiga förnödenheter åt sitt folk.",al={"shelene rhobarts bakgrund","vem är shelene","information om shelene rhobart"}},ffb69fef={q="Vilken sida står Shelene Rhobart på?",a="Hon är orubbligt lojal mot de Förvärrade och Lady Sylvanas Windrunner, liksom mot den bredare Horden. Hon arbetar direkt för att stödja Tirsifals försvarare och handelsfolk när de säkrar sitt hemland.",al={"shelene rhobarts fraktion","vem tjänar shelene rhobart","shelene rhobarts lojalitet"}},d546cfcf={q="Vad vill Shelene Rhobart?",a="Shelene vill förse de Förvärrades krigsinsats och stödja resande genom Tirisfal Glades. Hon söker tåliga djurhudar från traktens vilda djur för att tillverka rustningar, utrustning och förnödenheter som behövs för att överleva rikets fiender.",al={"vad vill shelene","shelene rhobarts mål","shelene rhobarts syfte"}},e156f5b6={q="Varför är Shelene Rhobart här?",a="Shelene är stationerad vid en Deathguard-utpost sydost om Brill för att hålla en förpost längs den viktiga vägen genom Tirisfal Glades. Härifrån hjälper hon spejare på patrull och delar med sig av sina kunskaper i läderarbete till resande som passerar genom gläntorna.",al={"varför är shelene vid deaths watch","varför är shelene rhobart här"}}},fp="15,217,25.342.0,33.117.0,37.131.0,30.266.0"}
P.entries["npc:shenthul"] = {n="Shenthul",s="I Orgrimmars Cleft of Shadow tränar Shenthul skurkar och tjänar Shattered Hand. Han leder hemliga uppdrag över Kalimdor och tar in lovande skurkar i dess led.",h="I Orgrimmars Cleft of Shadow tränar Shenthul skurkar och tjänar Shattered Hand.",kw={"cleft of shadow","djungeltroll","orgrimmar","tränare för rövare","shattered hand","shenthul","venture company","windshear crag"},ang={["class:Rogue"]="Som skurk i Orgrimmar kan du lära dig av Shenthul, klara invigningsprövningar och ta dig an hemliga uppdrag.",["faction:Horde"]="Under Orgrimmar leder Shenthul Hordens hemliga underrättelsearbete mot hot inom och utanför dess led.",["race:Troll"]="Som troll kan du se hur Shenthul, ett djungeltroll, har anslutit sig till Shattered Hand, som en gång var en orcisk klan."},sec={{t="Ögon i klyftan",b="Shenthul tränar skurkar i Orgrimmars Cleft of Shadow. Medan krigare och schamaner marscherar öppet genom Durotar lär han ut smygande, bakhåll och list. Hans elever lär sig fältkunskap och dödliga konster för uppdrag i Kalimdors hårda vildmark och skoningslösa politik."},{t="Shattered Hand",b="Shenthul talar för Shattered Hand, en gång en orcisk klan och nu Hordens underrättelsenätverk och hemliga tjänst. Han beskriver den som en vaksam närvaro över Kalimdor, som undersöker, dömer och verkställer sina egna straff. Shenthul är pragmatisk och oberoende av skiftande politik, och påminner utomstående om att Shattered Hand fanns innan krigshövding Thrall tog makten och kommer att finnas kvar efter honom."},{t="Hemligt fältarbete",b="Shenthul leder hemliga uppdrag i omstridda områden. Han skickar agenter för att infiltrera fientliga intressen och öva på att dyrka upp Venture Companys låsta förrådslådor runt Windshear Crag. Rekryterna ställs inför krävande prövningar, och när hans fältagenter drabbas av gift ser Shenthul till att de hittar botemedel innan gifterna blir dödliga."}},faq={{q="Vem är Shenthul?",a="Shenthul tränar djungeltrollens skurkar i Cleft of Shadow under Orgrimmar och arbetar för Shattered Hand.",al={"shenthuls roll","vem är shenthul","tränare för trollrövare orgrimmar"}},{q="Var hittar jag Shenthul?",a="Shenthul finns i Cleft of Shadow, ett grottkomplex som nås genom Orgrimmars mörkare tunnlar.",al={"shenthuls plats","var finns shenthul","shenthul cleft of shadow"}},{q="Vilken koppling har Shenthul till Shattered Hand?",a="Shenthul arbetar för Shattered Hand, Hordens hemliga underrättelsetjänst och lönnmördarklan, och rekryterar skurkar till dess led.",al={"shattered hand shenthul","är shenthul med i shattered hand","vilken fraktion tillhör shenthul"}},{q="Vad tycker Shenthul om Warchief Thrall?",a="Shenthul säger att Shattered Hand fanns innan Thrall tog makten och kommer att finnas kvar efter honom. Han sätter klanens arbete och Hordens säkerhet före skiftande politik.",al={"shenthul om thrall","gillar shenthul thrall","shenthuls lojalitet"}},{q="Vilka uppdrag ger Shenthul rövare?",a="Shenthul vägleder skurkar genom invigningsprövningar och hemliga infiltrationsuppdrag. Han ger dem också i uppdrag att öva på att dyrka upp Venture Companys låsta förrådslådor runt Windshear Crag i Stonetalon Mountains.",al={"shenthuls uppdrag","rövaruppdrag shenthul"}},{q="Hjälper Shenthul till med gifter för rövare?",a="Ja. När fältagenter drabbas av dödliga gifter hänvisar Shenthul dem till Hinott för botemedel.",al={"shenthuls giftuppdrag","shenthul hjälp hinott"}}},fx={["1496428e"]={q="Vilken sida står Shenthul på?",a="Shenthul tjänar Shattered Hand framför allt annat. Orden verkar inom Orgrimmar under Hordens baner, men han gör klart att gillet lyder under sin egen auktoritet. Som han säger till besökare fanns Shattered Hand långt före Warchief Thrall och kommer att bestå långt efter honom.",al={"shenthuls lojalitet","vem tjänar shenthul","är shenthul lojal mot thrall"}},["6d75b5d2"]={q="Vad vill Shenthul?",a="Shenthul vill utöka Shattered Hands räckvidd över Kalimdor. Han föreställer sig att orden verkar som en allseende slöja och tjänar som beskyddare, polis, domare, jury och bödel i skuggorna. För att åstadkomma detta tränar han lovande skurkar, prövar deras list och disciplin och skickar ut dem på viktiga hemliga uppdrag.",al={"vad är shenthuls mål","shenthuls motiv","vad vill shenthul"}},f56d6f2e={q="Varför är Shenthul här?",a="Shenthul har sitt hem i de dunkla grottorna i Cleft of Shadow, där han rekryterar och undervisar nya skurkar som ska tjäna Shattered Hand. Avskild från den övre stadens nyfikna blickar övervakar han hemliga operationer och prövar blivande agenter i den smygkonst och det bedrägeri som krävs för att tjäna orden.",al={"varför är shenthul i orgrimmar","varför är shenthul i cleft of shadow","vad gör shenthul här"}}},fp="8,168,17.266.0,18.404.0,16.343.1,16.110.0,26.106.0,52.126.0,44.167.0,44.215.0,40.89.0"}
P.entries["npc:shindrell-swiftfire"] = {n="Shindrell Swiftfire",s="Shindrell Swiftfire är en nattalvsvakt och spejare stationerad i Astranaar, hjärtat för nattalvernas verksamhet i Ashenvale. Hon är väl medveten om de skiftande farorna längs Kalimdors västra utmarker och leder skickliga alliansäventyrare mot hot som samlas vid kusten och de närliggande bergspassen. Hennes uppgifter gör henne till en oumbärlig samordnare av det lokala försvaret mot nya hot från havet och vildmarken.",h="Shindrell Swiftfire är en nattalvsvakt och spejare stationerad i Astranaar, hjärtat för nattalvernas...",kw={"ashenvale","astranaar","naga","pridewings","väktare","shindrell","stonetalon","swiftfire","the zoram strand"},ang={["class:Hunter"]="Hennes uppdrag att spåra pridewings och undersöka otämjda kuststräckor passar spejare och jägare som är skickliga på att överleva i vildmarken.",["faction:Alliance"]="Shindrell fungerar som en länk i Astranaar och vägleder nyanlända från Alliansen djupare in i centrala Kalimdors omstridda och farliga terräng.",["race:NightElf"]="För nattalverna står Shindrell för de vaksamma väktare som försvarar Ashenvales utkanter mot uråldriga fiender som naga, medan huvuddelen av styrkorna möter Horden."},sec={{t="Vakande öga i Astranaar",b="Från Astranaars slingrande gångvägar håller Shindrell Swiftfire uppsikt över Ashenvales vidsträckta gränstrakter. Medan skogens väktare ständigt pressas av Hordens skogsavverkningståg från öster och söder riktar Shindrell blicken mot faror bortom skogsbrynet. Hon är en viktig kontakt för resenärer från Darkshore eller dem som beger sig mot Stonetalon Mountains taggiga höjder, och ser till att Astranaar inte överraskas av hot från sidan."},{t="Hotet vid kusten",b="Ett av Shindrells främsta bekymmer är den oroliga Zoram Strand vid Ashenvales nordvästra kust. De fientliga naga som plötsligt kravlat upp ur havsdjupen utgör ett allvarligt mysterium och ett direkt hot mot kaldoreiernas bosättningar. Genom att skicka erfarna kämpar att undersöka kusten och samverka med spejare närmare händelserna försöker Shindrell hejda de slingrande inkräktarna innan de får ett permanent fäste i nattalvernas uråldriga marker."}},faq={{q="Var hittar jag Shindrell Swiftfire?",a="Shindrell Swiftfire är stationerad i Astranaar, den centrala nattalvsstaden i Ashenvale. Du hittar henne bland bosättningens träspångar, där hon samordnar spaningsuppdrag och tar emot resenärer.",al={"shindrell swiftfires plats","var finns shindrell","hitta shindrell swiftfire"}},{q="Vilken roll har Shindrell i Astranaar?",a="Hon samordnar spejare och ger uppdrag åt Alliansen. Hon leder äventyrare mot yttre hot mot Ashenvale, som naga på västkusten och vilddjur i de närliggande bergstrakterna.",al={"vad gör shindrell","vem är shindrell swiftfire","shindrells uppgift"}},{q="Varför skickar hon spejare till Zoram Strand?",a="Fientliga naga har strömmat upp på Ashenvales västra stränder, lagt beslag på ruiner och hotar nattalvernas gränser. Shindrell skickar äventyrare att spana på stränderna och hjälpa väktarna i fält att hejda ormarna.",al={"varför zoram strand","shindrells naga-uppdrag","uppdrag vid zoram strand"}},{q="Vad har Shindrell med Stonetalon Mountains att göra?",a="Hemliga källor i Theramore rapporterar att orciska lönnmördare samlar gift från pridewings nära Mirkfallon Lake i Stonetalon Mountains för sina hemliga räder mot Alliansen. Shindrell skickar äventyrare att samla giftsäckarna och neka Horden tillgång till giftet.",al={"uppdrag i stonetalon","pridewings-uppdrag","varför stonetalon"}},{q="Har Shindrell någon koppling till Blackfathom Deeps?",a="Inte direkt. Hennes uppdrag riktar äventyrare mot Wrathtail-nagorna vid Zoram Strand, samma nordvästra kust där Blackfathom Deeps ligger, men hon skickar ingen in i själva djupet.",al={"shindrell och blackfathom","koppling till blackfathom deeps","shindrell och bfd"}},{q="Vem är Kayneth Stillwind, och varför nämner Shindrell honom?",a="Kayneth Stillwind är en druid vid Forest Songs helgedom i östra Ashenvale. Han befarar att en fördärvelse sprider sig genom skogen och bad Shindrell rapportera om vad som händer längs kusten och kring Astranaar. Hon skickar äventyrare med rapporten till honom.",al={"vem är kayneth","kayneth stillwinds uppdrag","kayneths koppling"}}},fx={["2412c5d9"]={q="Vem är Shindrell Swiftfire?",a="Shindrell Swiftfire är en nattalv stationerad i Astranaar, där hon samordnar försvaret av Ashenvale med vaksamhet. Från bosättningens hjärta håller hon uppsikt över växande hot längs skogens gränser och samlar Alliansens äventyrare för att möta fientliga varelser, mörka kulter och invaderande styrkor som hotar nattalvernas länder.",al={"vem är shindrell","shindrell swiftfires bakgrund","vem är shindrell swiftfire"}},["1fb1d96b"]={q="Vilken sida står Shindrell Swiftfire på?",a="Shindrell står orubbligt med nattalvernas Sentinels och Alliansen. Hon är stationerad i Astranaars fristad och är helt och hållet trogen försvaret av Kalimdors heliga skogar och tryggheten för sitt folk.",al={"shindrells fraktion","tillhör shindrell alliansen","vilken fraktion tillhör shindrell swiftfire"}},["00b2b10b"]={q="Vad vill Shindrell Swiftfire?",a="Shindrell vill säkra Ashenvale och områdena runt omkring mot växande faror. Hon skickar resande för att driva tillbaka naga från The Zoram Strand, neka orcherna pridewinggiftet från Stonetalon Mountains och föra hennes rapporter till druiden Kayneth Stillwind i Forest Song.",al={"vad vill shindrell","shindrell swiftfires mål","shindrells motivation"}},["4632c876"]={q="Varför är Shindrell Swiftfire här?",a="Astranaar är nattalvernas främsta försvarscentrum i Ashenvale. Shindrell stannar här för att organisera spaning, samla rapporter från avlägsna utposter och rekrytera dugliga resande längs huvudvägen som kan hjälpa till att skydda skogens gränser.",al={"varför är shindrell i astranaar","varför är shindrell swiftfire här","shindrells syfte i astranaar"}}},fp="19,412,27.382.0,23.416.0,37.163.0,38.199.0,45.211.0,48.256.0,46.205.0,61.230.0"}
P.entries["npc:shoni-the-shilent"] = {n="Shoni the Shilent",s="Shoni the Shilent är en flitig gnomingenjör stationerad i det livliga Dwarven District i Stormwind City. Som befälhavare för Gnomeregans underjordiska anfallstrupp leder hon Alliansens äventyrare till Deadmines för att bärga kraftaggregatet från en goblinsköldpadda, bränsle till maskinerna som hon hoppas ska bana väg tillbaka till Gnomeregan.",h="Shoni the Shilent är en flitig gnomingenjör stationerad i det livliga Dwarven District i Stormwind City.",kw={"the deadmines","dwarven district","grävmaskiner","gnom","gyrodrillmatic","shilent","shoni","stormwind"},ang={["profession:Engineering"]="Ingenjörer kan uppskatta den enorma mekaniska komplexiteten hos gyrodrillmatic excavationators, som Shoni hoppas kunna driva med en bärgad sköldpaddas hjärta från trakten under Moonbrook.",["race:Gnome"]="För gnomiska hjältar innebär hjälp till Shoni att deras folk kommer ett steg närmare att bryta sig in i Gnomeregan igen och återta sitt fallna hem."},sec={{t="Djupets befälhavare",b="Från de rökiga verkstäderna i Dwarven District företräder Shoni gnomernas strategiska uppfinningsrikedom långt från Gnomeregans förlorade salar. Hennes ingenjörsplaner är djärva. Gnomeregan är i troggarnas händer, och Shoni organiserar ett underjordiskt anfall för att återta staden. Hon skickar agenter till de underjordiska tunnlarna under Westfall för att hämta delarna hennes besättning behöver."},{t="Återerövring under jord",b="Shonis plan bygger på gnomernas egna gyrodrillmatic excavationators, tunga borrmaskiner avsedda att bryta igenom de klippiga underjordiska gränserna kring Gnomeregan och öppna vägen för ett gnomiskt anfall. De saknar kraft nog att göra det, så hon vill ha det intakta kraftaggregatet, Gnoam Sprecklesprocket, från en fungerande goblinsköldpadda djupt inne i Deadmines. Senare skickar hon också äventyrare till Gnomeregan för att plocka isär robotar och samla reservdelar till reparation av sin flotta."}},faq={{q="Vem är Shoni the Shilent?",a="Shoni the Shilent är en gnomisk uppdragsgivare i Dwarven District i Stormwind. Hon är befälhavare för Gnomeregans underjordiska anfallstrupp och samordnar uppdrag för återerövring under jord.",al={"vem är shoni","shonis historia","shoni the shilent npc"}},{q="Var hittar jag Shoni?",a="Hon är stationerad bland städen och verkstäderna i Dwarven District i Stormwind City, nära smedjan och ingenjörsområdet.",al={"var finns shoni","shonis plats","hitta shoni"}},{q="Varför är Shoni intresserad av Deadmines?",a="En fungerande goblinsköldpadda finns djupt inne i Deadmines. Shoni ber äventyrare hämta dess intakta kraftaggregat, Gnoam Sprecklesprocket, så att hennes gyrodrillmatic excavationators kan bryta igenom Gnomeregans underjordiska gränser.",al={"shoni deadmines","varför skicka till deadmines","gyrodrillmatic-uppdrag"}},{q="Varför kallas hon ”the Shilent”?",a="Ursprunget till Shonis tillnamn är okänt. Hon är känd för att leda Gnomeregans underjordiska anfallstrupp.",al={"shonis smeknamn","varför shilent","tyst gnom"}}},fx={["3c03f847"]={q="Vilken sida står Shoni the Shilent på?",a="Shoni är lojal mot Gnomeregan och Grand Alliance. Från Dwarven District i Stormwind City leder hon Gnomeregans underjordiska anfallstrupp och samordnar specialiserade tekniska insatser för sitt fördrivna folk.",al={"shonis fraktion","vem arbetar shoni för","shoni the shilent och alliansen"}},["0ba3c461"]={q="Varför är Shoni the Shilent här i Stormwind?",a="Efter Gnomeregans fall slog sig Shoni ner bland uppfinnarna och hantverkarna i Stormwinds Dwarven District. Härifrån leder hon det underjordiska anfallslaget och samlar in de mekaniska delar och vapen som behövs för att stödja pågående gnomoperationer.",al={"varför är shoni i stormwind","vad gör shoni här","shonis syfte"}},["076c3e36"]={q="Vilka har Shoni the Shilent band till?",a="Shoni leder Gnomeregans underjordiska anfallstrupp och har nära band till gnomernas militära och tekniska led. Stationerad i Stormwind City samarbetar hon nära med Alliansens ingenjörer och soldater som försöker återta sitt teknologiska arv.",al={"shonis kopplingar","vem befaller shoni","shonis allierade"}}},fp="17,209,21.231.0,24.405.0,25.145.0,23.135.0,41.197.0,32.99.0"}
P.entries["npc:sicco-thermaplugg"] = {n="Mekgineer Thermaplugg",s="Mekgineer Thermaplugg är den självutnämnde härskaren över det förstörda Gnomeregan och den största förrädaren i gnomernas historia. Han var en gång betrodd chefsrådgivare åt överingenjör Gelbin Mekkatorque, men låg bakom stadens katastrofala bestrålning i ett förvridet försök att ta makten. Nu är han fullständigt vansinnig och förvandlad till en spetälsk gnom. Från en väldig mekanisk stridsrustning styr han över de bestrålade salarna.",h="Mekgineer Thermaplugg är den självutnämnde härskaren över det förstörda Gnomeregan och den största förrädaren...",kw={"crowd pummeler","gnomeregan","spetälsk gnom","mekkatorque","sicco","thermaplugg","tinkers hov","trogg"},ang={["faction:Alliance"]="Thermapluggs förräderi gjorde att Gnomeregan inte kunde hörsamma vapenropet under det tredje kriget. Det förlamade Alliansens försörjningslinjer och tekniska stöd under mänsklighetens mörkaste stund.",["profession:Engineering"]="Thermaplugg visar hur farliga slarviga formler och principlös konstruktion är. Han använder farliga gående krigsmaskiner och giftiga bombautomater mot alla som går in i hans verkstad.",["race:Dwarf"]="Ditt folk i Ironforge gav skydd åt de trasiga överlevande som flydde från Thermapluggs gift, och vakterna vid Ironforge håller noga uppsikt över Dun Moroghs portar för att hålla hans bestrålade vandrare borta.",["race:Gnome"]="Thermaplugg förkroppsligar allt ditt folk sörjer och avskyr. Hans fåfänga och förräderi kostade er ert hemland och förvandlade dina fränder till sjuka fasor."},sec={{t="Giftiga ambitioner",b="Mekgineer Thermaplugg tjänade i många år som chefsrådgivare åt överingenjör Gelbin Mekkatorque, som litade fullständigt på honom. Samtidigt eftertraktade Thermaplugg i hemlighet posten som överingenjör. Inte ens Mekkatorque kan säga vad som till slut fick honom att svika förtroendet, makt eller rikedom. Överingenjören kan bara konstatera att Thermaplugg med tiden skulle ha fått båda delarna."},{t="Gnomeregans förgiftning",b="När underjordiska troggar svärmade in i Gnomeregan under det tredje kriget bekämpade gnomerna dem i det underjordiska mörkret. För att hitta ett sätt att bryta belägringen vände sig Gelbin till Thermaplugg för råd. Thermaplugg föreslog att staden skulle fyllas med radioaktiv gas och lovade att den skulle förgöra troggarna men skona gnomerna. I själva verket tänkte Thermaplugg utnyttja krisen för att störta Mekkatorque och själv ta makten."},{t="Ruinhärskaren",b="Thermapluggs chansning fick katastrofala följder. Radioaktivt nedfall spred sig okontrollerat genom stadens alla nivåer, dödade åttio procent av befolkningen och förvandlade många överlevande till vilda, sjuka spetälska gnomer. I stället för att bestiga tronen i en blomstrande metropol förvreds Thermaplugg själv av nedfallet. Strålningen drev honom fullständigt till vansinne. Han krönte sig till gnomernas kung och styr nu över ett gravhus fyllt av bestrålade maskiner och muterade trälar. Han utkämpar ett evigt krig mot invaderande troggar och ytliga gnomer som försöker återta sitt förlorade hem."}},faq={{q="Vem är Mekgineer Thermaplugg?",a="Han är den tidigare chefsrådgivaren åt överingenjör Gelbin Mekkatorque, som förrådde sitt folk under troggarnas invasion. Han ville tillskansa sig makten och övertalade Mekkatorque att släppa ut radioaktiv gas i Gnomeregan. Det ledde nästan till att deras folk utrotades och lämnade honom som härskare över de bestrålade ruinerna, en galen kung.",al={"vem är thermaplugg","therapluggs historia","vem är bossen i gnomeregan","therapluggs bakgrund"}},{q="Varför förrådde Thermaplugg Gelbin Mekkatorque?",a="Inte ens Mekkatorque kan säga säkert. Överingenjören litade på honom och undrar om det handlade om makt eller rikedom, sådant Thermaplugg ändå skulle ha fått med tiden. Det man vet är att Thermaplugg länge i hemlighet eftertraktade posten som överingenjör och utnyttjade troggkrisen för att själv ta över Gnomeregan.",al={"varför förrådde han gnomeregan","therapluggs motiv","varför hatar sicco gelbin"}},{q="Orsakade Thermaplugg troggarnas invasion?",a="Troggarna bröt sig ursprungligen in i Gnomeregans nedre nivåer efter att ha grävts fram ur den forntida titankryptan i Uldaman. Rykten går om att Thermaplugg kände till det underjordiska genombrottet i förväg eller till och med hjälpte till att framkalla en kris. Mekkatorque har dock aldrig kunnat bekräfta om Thermaplugg inledde invasionen eller bara utnyttjade den.",al={"kallade han på troggarna","förde sicco dit troggarna","trogginvasionens ursprung i gnomeregan"}},{q="Vad hände med Thermaplugg efter att gasen släpptes ut?",a="Precis som tusentals andra gnomer som drabbades av katastrofen utsattes Thermaplugg för dödliga strålningsnivåer. Nedfallet fick hans kött att tyna bort, färgade huden sjukligt grön och splittrade hans sinne. I stället för att fly med de överlevande till Ironforge stannade han kvar för att härska över ruinerna som gnomernas självutnämnde kung.",al={"är thermaplugg en spetälsk gnom","hur blev han en spetälsk gnom","varför är thermaplugg grön"}},{q="Vad är Crowd Pummeler 9-60?",a="Crowd Pummeler 9-60 är en väldig gnomisk krigsmaskin som fortfarande klampar genom Gnomeregans Engineering Labs. Den är en av många mekaniska väktare som försvarar Thermapluggs bestrålade rike.",al={"crowd pummelers ursprung"}},{q="Vad vill överingenjör Mekkatorque göra med Thermaplugg?",a="Mekkatorque betraktar Thermaplugg som sitt största misslyckande och sitt folks största förrädare. Från sitt tillfälliga hov i Ironforges Tinker Town ger Mekkatorque modiga äventyrare från Alliansen uppdrag att ta sig ner i Gnomeregans bestrålade djup och avrätta Thermaplugg för att skipa rättvisa åt de fallna.",al={"gelbins uppdrag för thermaplugg","uppdrag att döda thermaplugg","vill mekkatorque ha honom död"}}},fx={["7e175e39"]={q="Varför är Mekgineer Thermaplugg här?",a="Thermaplugg håller till djupt inne i Gnomeregans ingenjörskvarter eftersom han tog över den fallna staden under katastrofen. I stället för att fly till Ironforge med de överlevande gnomerna stannade han kvar för att göra anspråk på de tomma salarna och härska över de muterade spetälskegnomer som förvandlades tillsammans med honom. Från Tinkers' Court fortsätter han att leda sitt försvar, sina maskiner och sina förvridna anhängare från själva hjärtat av katastrofen som drabbade staden.",al={"varför är thermaplugg i gnomeregan","varför stannade thermaplugg","varför är thermaplugg där"}},cac8a4d9={q="Varför är Mekgineer Thermaplugg berömd eller fruktad?",a="Thermaplugg är ökänd som den största förrädaren i gnomernas historia. Han hyllades en gång som High Tinker Mekkatorques främste rådgivare, men hans förräderi ledde direkt till bestrålningen av Gnomeregan och förlusten av den överväldigande majoriteten av dess befolkning. Gnomerna ser på hans förräderi med djup fasa och fruktar både de dödliga maskiner han styr och det totala vansinne som nu vägleder hans despotiska styre.",al={"varför är thermaplugg fruktad","therapluggs rykte","varför hatar gnomer thermaplugg"}},["83ef33e1"]={q="Vilken sida står Mekgineer Thermaplugg på?",a="Thermaplugg tjänar bara sig själv och sina förvridna ambitioner. Han förrådde Alliansen och sitt eget folk när han fyllde Gnomeregan med radioaktiv gas och drev de överlevande i landsflykt. Avskuren från omvärlden och helt fördärvad av strålningen befaller han nu de spetälska gnomer som finns kvar i den förstörda staden. Han härskar över dem som en galen despot och strider samtidigt mot både de invaderande troggarna och alla utomstående som vågar tränga in på hans område.",al={"thermapluggs fraktion","vem tjänar thermaplugg","sicco thermapluggs lojalitet"}},["4bd94cd3"]={q="Vad vill Mekgineer Thermaplugg?",a="Thermaplugg vill behålla kronan han lade beslag på. Han har utropat sig till gnomernas kung och härskar från den förstörda huvudstadens djup. Han befaller de spetälska gnomer och maskiner som finns kvar och vägrar ge upp makten, trots att Mekkatorque kallar honom kung över ingenting.",al={"thermapluggs mål","vad planerar thermaplugg","sicco thermapluggs motiv"}}},fp="21,290,16.343.0,27.366.1,17.460.1,29.333.0,46.288.0,41.306.0,56.295.0,32.199.0,61.289.0"}
P.entries["npc:sida"] = {n="Sida",s="Sida är en dvärg som bor i Menethil Harbor i Wetlands. Hon är känd för sitt trassliga äktenskap med Einar Stonegrip och tillbringar dagarna i hamnstaden, medan hon råkar ut för personliga missöden i de omgivande träskmarkerna.",h="Sida är en dvärg som bor i Menethil Harbor i Wetlands.",kw={"einar stonegrip","ironbeard's tomb","menethil harbor","slem","sida","wetlands"},ang={["faction:Alliance"]="För alliansresenärer som anländer till bryggorna i Menethil Harbor erbjuder Sida lokala ärenden som tar äventyrarna inåt land mot Ironbeard's Tomb.",["race:Dwarf"]="Sida gestaltar dvärgarnas vardagsliv i Menethil Harbor, fångad mellan familjekonflikter och den förrädiska vildmarken strax bortom stadens portar."},sec={{t="En invånare i hamnen",b="Sida bor i den livliga allianshamnen Menethil Harbor, åtskild från sin make Einar Stonegrip. Deras förhållande är så ansträngt att Einar blankt vägrar att resa till Menethil så länge Sida bor där. Trots att hon håller sig till kustbosättningen ger sig Sida ibland ut bland farorna i Wetlands. Nyligen råkade hon ut för den olyckliga förlusten av sin personliga väska under en expedition mot Ironbeard's Tomb."}},faq={{q="Vem är Sida?",a="Sida är en dvärgkvinna som bor i Menethil Harbor i Wetlands. Hon ger uppdrag åt äventyrare som passerar genom hamnen.",al={"vem är sida","sida npc","sida wetlands"}},{q="Vad hände med Sidas väska?",a="Sida tappade sin väska när hon besökte Ironbeard's Tomb, en forntida gravplats i Wetlands. Sedan dess har området översvämmats av otäcka slem som slukade hennes tillhörigheter.",al={"var är sidas väska","förlorad väska","ironbeard's tomb väska"}},{q="Varför tänker Einar Stonegrip inte besöka Menethil Harbor?",a="Einar Stonegrip är Sidas frånskilde make. På grund av det onda blodet mellan dem undviker Einar Menethil Harbor helt så länge Sida fortfarande bor där.",al={"einar och sida","sidas make","einar stonegrip drama"}},{q="Var kan man hitta Sida?",a="Sida kan hittas när hon strosar längs bryggorna och vägarna i Menethil Harbor på Wetlands västkust.",al={"sidas plats","var är sida"}}},fx={["46b5f80b"]={q="Vems sida står Sida på?",a="Sida är en dvärg från Ironforge som är lojal mot Alliansen. Liksom många av sina släktingar som bor i hamnstaden Menethil Harbor vänder hon sig till resenärer och andra allianshjältar för att få hjälp när problem uppstår i de farliga kärrmarkerna runt omkring.",al={"sidas fraktion","är sida med alliansen","vem lyder sida under"}},["62842a43"]={q="Varför är Sida i Menethil Harbor?",a="Sida bor i Menethil Harbor, men hon gjorde nyligen en utflykt österut till kärrmarkerna för att besöka Ironbeard's Tomb. Efter den katastrofala utflykten, då lokala slemvarelser slukade hennes tillhörigheter, har hon stannat i staden i hopp om att en äventyrare ska ge sig ut i träsket och hämta hennes förlorade väska.",al={"varför är sida här","varför är sida i våtmarkerna","varför är sida i menethil harbor"}}},fp="4,218,17.334.0,12.123.0,28.153.0,48.127.0,24.95.0"}
P.entries["npc:sirra-von-indi"] = {n="Sirra Von'Indi",s="Sirra Von'Indi är Darkshires bofasta historiker och arbetar i stadshuset bland högar av bortglömda handlingar. Han behärskar forntida språk och lokalhistoria och hjälper invånarna att tyda gåtfulla dokument och avslöja Duskwoods mörka förflutna.",h="Sirra Von'Indi är Darkshires bofasta historiker och arbetar i stadshuset bland högar av bortglömda handlingar.",kw={"abercrombie","darkshire","duskwood","historiker","morgan ladimore","sirra","stadshus","översättning","von'indi","weathered grave"},ang={["class:Mage"]="Magiker som besöker Darkshire uppskattar ofta Sirras akademiska noggrannhet. Hans fokus på forntida språk och historiska studier påminner om arkivforskningen inom Kirin Tor.",["faction:Alliance"]="Sirra står för den samhällsinstitution i Darkshire som ännu består och hjälper till att bevara Stormwinds kungarikes arv i en provins som annars slukas av mörker."},sec={{t="Stadens historiker",b="Sirra Von'Indi är Darkshires främste lärde och vakar över bosättningens arkiv i Darkshire Town Hall. Medan stadsvakten fokuserar på de omedelbara hoten i skogen ägnar Sirra sig åt det skrivna ordet. Han översätter kryptiska texter och bevarar Grand Hamlets bleknande historia från tiden innan skuggorna föll över trakten."},{t="Att tyda eremitens ord",b="När stadens ledning börjar misstänka eremiten Abercrombie, som bor ute i Duskwoods ödsliga kullar, får Sirra i uppdrag att översätta eremitens gåtfulla anteckningar. Hans språkkunskaper hjälper rådet att läsa mellan raderna i till synes harmlösa önskemål och reda ut de besynnerliga förfrågningar som kommer från den hemsökta skogen."},{t="Det förflutnas tragedier",b="Utöver vanliga översättningar spelar Sirra en viktig roll i att kasta ljus över Duskwoods sorgliga historia. De som vill förstå den mystiska, väderbitna graven på stadens kyrkogård upptäcker att Sirra är en av få som minns paladinen Morgan Ladimores tragiska fall. Han ger resande den bakgrund de behöver för att ge rastlösa andar ro."}},faq={{q="Vem är Sirra Von'Indi?",a="Sirra Von'Indi är en lärd människa och Darkshires officiella historiker. Han tillbringar dagarna i Darkshire Town Hall med att studera forntida skrifter, översätta dunkla språk och bevara stadens historiska handlingar.",al={"vem är sirra","sirra von'indis historia","historiker i darkshire"}},{q="Var hittar man Sirra Von'Indi?",a="Han finns i Darkshire Town Hall i bosättningen Darkshire, mitt i Duskwood. Vanligtvis står han bland skrivbord och bokhyllor och studerar historiska texter.",al={"var finns sirra","sirra von'indis plats","hitta sirra i darkshire"}},{q="Vilken roll har han med Abercrombies anteckning?",a="När en märklig anteckning från eremiten Abercrombie når Lord Ello Ebonlocke och ingen i stadshuset kan läsa den, översätter Sirra den med sina språkkunskaper. På så sätt hjälper han rådet att förstå Abercrombies underliga krav.",al={"abercrombies brevöversättare","översätt abercrombies anteckning","sirras översättning av anteckningen"}},{q="Vad vet Sirra om Morgan Ladimore?",a="Sirra är en av få invånare i Darkshire som känner till hela historien om Morgan Ladimore, den fallne paladinen som ligger begravd i Weathered Grave. Han hjälper till att berätta om Ladimores väg mot vansinne och tragedi efter det tredje kriget.",al={"sirra och weathered grave","sirra om morgan ladimore","historien om weathered grave"}},{q="Varför får resande vänta medan Sirra översätter?",a="Det krävs noggrant arbete för att tyda dunkla dialekter och ålderdomlig handstil. Sirra ber ofta resande att ge honom tid medan han jämför källor och färdigställer en tillförlitlig översättning.",al={"varför är sirra upptagen","vänta tills sirra är klar","vänta på sirras översättning"}}},fp="14,186,18.226.0,30.254.1,21.243.1,22.181.0,34.140.0,47.211.0,43.184.0,53.203.0"}
P.entries["npc:sister-aquinne"] = {n="Sister Aquinne",s="Sister Aquinne är en akolyt åt Elune som bor i de fridfulla Temple Gardens i Darnassus. Hon är en novisprästinna och studerar hos Elunes prästerskap vid Temple of the Moon.",h="Sister Aquinne är en akolyt åt Elune som bor i de fridfulla Temple Gardens i Darnassus.",kw={"aquinne","darnassus","sister aquinne","the temple gardens","temple of the moon"},ang={["class:Priest"]="Andra tjänare åt Ljuset och Elune kan uppskatta Aquinnes hängivenhet medan hon genomgår den grundläggande utbildning som krävs av alla akolyter vid Temple of the Moon.",["race:NightElf"]="För nattalver som anländer till Darnassus är Sister Aquinne ett välkomnande ansikte i Temple Gardens och en första länk till templets storslagna prästerskap."},sec={{t="Akolyt i Darnassus",b="Sister Aquinne har vigt sig åt Elunes prästerskap i nattalvernas huvudstad. Hon är stationerad i de fridfulla Temple Gardens, i skuggan av Temple of the Moon, och fortsätter sina studier under översteprästinnans och de äldre systrarnas ledning. När en en gång mäktig varelse i skogen behövde hjälp skickade Aquinne villiga resenärer till Priestess A'moora inne i templet för att få veta vad som behövde göras."}},faq={{q="Var kan Sister Aquinne hittas?",a="Sister Aquinne står i Temple Gardens i Darnassus, strax utanför det storslagna Temple of the Moon.",al={"aquinne plats","var är sister aquinne","sister aquinne koordinater"}},{q="Vilken bakgrund har Sister Aquinne?",a="Hon är en novisprästinna åt Elune och studerar vid Temple of the Moon i Darnassus. Lite är känt om hennes liv innan hon började tjäna templet.",al={"aquinne bakgrund","vem är sister aquinne","aquinne historia"}}},fx={f961feee={q="Vems sida står Sister Aquinne på?",a="Sister Aquinne tjänar The Sisterhood of Elune och står helhjärtat med nattalverna i Darnassus och den bredare Alliansen. Hon är hängiven mångudinnan och studerar i lugn och ro i The Temple Gardens under de höga prästinnornas ledning. Hon svär ingen annan trohet än till sin heliga orden och sitt folk.",al={"aquinnes fraktion","är sister aquinne med alliansen","vem tjänar sister aquinne"}},["5bcdc1db"]={q="Vad vill Sister Aquinne?",a="Sister Aquinne ägnar sig åt sin andliga träning som novisprästinna i Temple of the Moon. När en skogens en gång så mäktiga varelse behöver hjälp skickar hon villiga resenärer till Priestess A'moora inne i templet.",al={"sister aquinnes mål","vad vill aquinne","aquinnes drivkraft"}},["119c78e2"]={q="Varför är Sister Aquinne i Darnassus?",a="Aquinne kom till huvudstaden för att följa sitt kall inom The Sisterhood of Elune. Hon bor vid de fridfulla dammarna i The Temple Gardens, där noviser och prästinnor mediterar och studerar Elunes läror.",al={"varför är sister aquinne här","varför är aquinne i darnassus","varför kom aquinne till darnassus"}}},fp="14,144,20.355.0,34.100.0,36.164.0"}
P.entries["npc:skorn-whitecloud"] = {n="Skorn Whitecloud",s="Skorn Whitecloud är en åldrande taurenjägare som bor i Bloodhoof Village på Mulgore slättmarker. Han vägleder unga jägare i deras förhållande till landets rovdjur och hjälper resenärer som stöter på Mulgore lurande faror.",h="Skorn Whitecloud är en åldrande taurenjägare som bor i Bloodhoof Village på Mulgore slättmarker.",kw={"bloodhoof village","flatland prowler","mulgore","skorn","tauren","the hunter's way","whitecloud"},ang={["class:Hunter"]="För unga taurenjägare erbjuder Skorn Whitecloud tidig vägledning i att smyga sig på snabba rovdjur som flatland prowler, och betonar jaktens andliga harmoni.",["race:Tauren"]="Skorn är ett exempel på taurenäldste som för vidare jaktens heder och den praktiska visdomen från ett långt liv på slätterna till Mulgore unga."},sec={{t="En vägvisare på The Golden Plains",b="Skorn Whitecloud bor i Bloodhoof Village i Mulgore. Han är en gammal jägare som nu lär ut jaktens vägar. Framför allt lär han ut respekt för slätternas vilda varelser. Han prövar blivande jägare genom att skicka dem efter klorna från Mulgore listiga flatland prowlers. De ska visas upp för Melor Stonehoof i Thunder Bluff. På så vis ser han till att de som tar till båge eller spjut förstår balansen mellan rovdjur och byte."},{t="Vaksamhet mot det onaturliga",b="Utöver sina vanliga jaktuppgifter håller Skorn uppsikt efter märkliga störningar över savannen. När onaturliga hot visar sig, som tecken på demonisk korruption bland slätternas vilda djur och bestar, hjälper Skorn till att klarlägga vad som hänt. Han ser till att Mulgore stammar håller sig vaksamma mot illvilliga krafter som tränger in i deras förfäders hem."}},faq={{q="Var finns Skorn Whitecloud?",a="Skorn Whitecloud finns i Bloodhoof Village, taurenbosättningen i Mulgore södra gräsmarker.",al={"skorn whitecloud plats","var finns skorn","skorn whitecloud karta"}},{q="Vilken roll har Skorn för unga jägare?",a="Skorn lär ut jaktens grundprinciper genom riten som kallas The Hunter's Way. Han låter blivande jägare bevisa sin förmåga att spåra och strida mot slättens listiga flatland prowlers, och skickar dem sedan till Melor Stonehoof i Thunder Bluff.",al={"vad gör skorn","skorn jägaruppdrag","the hunters way"}},{q="Vilka varor säljer Skorn?",a="Hans mest värdefulla varor är hans egna vapen. Han har slutat jaga och erbjuder därför ett av sina vapen, Skorn's Hammer eller Skorn's Rifle, till jägaren som kommer med bevis på att den stora vargen Ghost Howl har fallit.",al={"skorn försäljare","vad säljer skorn","skorns vapen"}},{q="Är Skorn Whitecloud släkt med någon annan tauren i Mulgore?",a="Inga släktingar till Skorn nämns i Mulgore. Han är bara känd som en gammal jägare från Bloodhoof Village, vars jaktdagar är över.",al={"whitecloud-familjen","skorns släktingar"}}},fx={c8bc2edc={q="Vem är Skorn Whitecloud?",a="Skorn Whitecloud är en åldrande taurenjägare som bor i Bloodhoof Village på Mulgore slätter. Han är en respekterad äldre jägare i sin stam och handleder blivande krigare i spårning och jakt samt i att hedra jakttraditionerna i taurenfolkets länder.",al={"vem är skorn","skorn whiteclouds historia","vem är skorn whitecloud"}},["3da50b72"]={q="Vems sida står Skorn Whitecloud på?",a="Skorn är lojal mot taurerna i Thunder Bluff och står helhjärtat med Horden. Han välkomnar resenärer från Horden till Bloodhoof Village och delar med sig av sin visdom till dem som följer jägarens väg i Mulgore.",al={"skorn whiteclouds fraktion","är skorn whitecloud med alliansen eller horden","vilken sida står skorn på"}},c55728a0={q="Vad vill Skorn Whitecloud?",a="Skorn vill vägleda unga taurener längs jägarens väg och pröva deras skicklighet mot rovdjuren i Mulgore. Han ger lovande jägare i uppgift att spåra farligt villebråd, däribland de listiga slättströvarna, för att se till att de lär sig att klara sig själva och vörda djuren de jagar.",al={"vad vill skorn","skorn whiteclouds uppdragsmotiv","skorn whiteclouds syfte"}},["5990a9e1"]={q="Varför är Skorn Whitecloud här?",a="Skorn bor i Bloodhoof Village, mitt i Mulgore. Hans jaktdagar är över, men han håller sig nära den öppna prärien där det finns gott om villebråd och unga spårare kommer för att förtjäna sin plats bland sitt folk.",al={"varför är skorn i camp sungraze","varför är skorn whitecloud här","varför är skorn whitecloud på den här platsen"}}},fp="16,126,28.385.0,31.292.1,36.109.0,44.237.0,27.158.0,59.139.0"}
P.entries["npc:skuerto"] = {n="Skuerto",s="Skuerto är en dvärgspanare stationerad vid Refuge Pointe i Arathi Highlands. Archmage Malin skickade dit honom tillsammans med Apprentice Kryten. Han hjälper Alliansen ute i fält och säkrar magiska reliker åt Malin.",h="Skuerto är en dvärgspanare stationerad vid Refuge Pointe i Arathi Highlands.",kw={"arathi highlands","archmage malin","ironforge","refuge pointe","spanare","skuerto","trelane"},ang={["race:Dwarf"]="Skuerto förkroppsligar dvärgarnas uthållighet vid Alliansens vilda gränstrakter, men hans stolthet som spanare är lätt att såra."},sec={{t="En spanare i höglandet",b="Skuerto, en dvärg från Ironforge, arbetar som spanare i det farliga Arathi Highlands. Han är stationerad vid Refuge Pointe tillsammans med Apprentice Kryten och arbetar under Archmage Malins ledning. De ska hämta arkaniska reagenser och kraftfulla magiska artefakter som en gång tillhörde Malins tidigare mästare, Archmage Trelane."},{t="Stolthet och fara",b="Trots de hårda förhållandena i höglandet är Skuerto mycket stolt över sitt spaningsarbete i vildmarken och reagerar illa när någon ifrågasätter hans kompetens. Hans arbete för honom regelbundet nära farorna i trakten, från det fientliga Syndicate och Boulderfist-ogrerna till farliga forntida väsen knutna till landet."}},faq={{q="Varför är Skuerto stationerad i Arathi i stället för i Ironforge?",a="Archmage Malin skickade honom. Skuerto och Apprentice Kryten sändes till Refuge Pointe för att samla reagenser och hämta föremålen som lämnats kvar av Malins tidigare mästare, Archmage Trelane, som flydde från Stromgarde när staden belägrades.",al={"varför är skuerto här","skuertos bakgrund"}},{q="Vad är Skuertos uppdrag vid Refuge Pointe?",a="Archmage Malin skickade Skuerto och Apprentice Kryten till Arathi Highlands för att samla arkaniska reagenser och hämta kraftfulla magiska artefakter som en gång ägdes av Malins tidigare mästare, Archmage Trelane.",al={"skuertos syfte","vad gör skuerto","skuerto malin"}},{q="Vilka är Skuertos allierade i trakten?",a="Han arbetar direkt med Apprentice Kryten, sin partner på Archmage Malins uppdrag, och med Alliansens försvarare som håller Refuge Pointe.",al={"skuertos vänner"}}},fx={["9a7bedf3"]={q="Vem är Skuerto?",a="Skuerto är en dvärg från Ironforge som tjänstgör som spanare vid Refuge Pointe i Arathi Highlands. Han är stolt över sin förmåga att spana och ovanligt känslig för kritik. Han verkar ute i fält tillsammans med Apprentice Kryten på Alliansens uppdrag.",al={"vem är skuerto","skuertos identitet","vem är dvärgen skuerto"}},["1cc8a254"]={q="Vems sida står Skuerto på?",a="Skuerto är helhjärtat lojal mot Alliansen och Ironforge. Från Alliansens läger vid Refuge Pointe samarbetar han med magiker från Dalaran och lokala alliansstyrkor mot hoten som tornar upp sig över Arathi Highlands.",al={"skuertos fraktion","är skuerto med alliansen","skuertos lojaliteter"}},["5f13d7e3"]={q="Vad vill Skuerto?",a="Skuerto vill utföra uppdraget Archmage Malin gav honom: att säkra magiska reagenser och återta kraftfulla, förlorade artefakter som en gång tillhörde Malins tidigare mästare, Archmage Trelane. Samtidigt vill han försvara sitt rykte som en skicklig spanare.",al={"vad vill skuerto","skuertos mål","skuertos motiv"}},["44066d31"]={q="Vilka band har Skuerto?",a="Förutom att arbeta under Archmage Malin och tillsammans med Apprentice Kryten står Skuerto med de alliansförsvarare som håller Refuge Pointe i Arathi Highlands.",al={"skuertos band","skuertos kontakter","vem känner skuerto"}}},fp="7,220,24.301.0,15.314.0,56.227.0,43.194.0,39.136.0"}
P.entries["npc:smith-argus"] = {n="Smith Argus",s="Smith Argus är smeden och tränaren i hjärtat av Goldshire i Elwynn Forest. Vid sin öppna smedja nära Lion's Pride Inn lagar han resenärers utrustning, lär nybörjare grunderna i smide och samordnar arbetet med hantverkare i södra Azeroth. Hans nätverk knyter Goldshires lokala handel direkt till knutpunkter som Stormwind och avlägsna gränstrakter som Redridge.",h="Smith Argus är smeden och tränaren i hjärtat av Goldshire i Elwynn Forest.",kw={"smed","elwynn forest","smedja","goldshire","hästskor","lion's pride","smith argus","tränare","verner osgood"},ang={["profession:Blacksmithing"]="För allianskaraktärer som börjar i Elwynn är Argus ofta den allra första smedjeläraren. Han ger dem de första recepten för enkel kopparutrustning och viktiga nyttoföremål.",["profession:Mining"]="Gruvarbetare tar metall till smedjan i Goldshire, där Argus lär blivande smeder att forma den till användbara redskap.",["race:Human"]="Argus står för de hårt arbetande hantverkarna som håller Elwynn igång, trots kungarikets större politiska försummelse och oroligheter med banditer."},sec={{t="Städet i Goldshire",b="Smith Argus håller till strax utanför Lion's Pride Inn och sköter ett av de mest välbesökta städena i Elwynn Forest. Medan Goldshire hotas allt mer av gnoller, kobolder och Defias-banditer i närheten ser Argus till att den lokala milisen och förbipasserande äventyrare har rätt utrustning. Han lagar buckliga rustningar och smider rejäla redskap, och som smedjetränare lär han blivande hantverkare grunderna i att arbeta med koppar och brons."},{t="Handel och behov mellan byar",b="Argus är mer än en bysmed; hans verkstad är en viktig länk i Stormwinds regionala försörjningskedja. När hantverkare i närliggande bosättningar behöver särskild utrustning eller råmaterial vänder de sig till Goldshires centrala läge. Verner Osgood, hovslagare i Redridge, är beroende av leveranser från Argus av smidda hästskor så att packdjur och kavalleri kan fortsätta röra sig. Metallarbetare i Stormwinds Dwarven District samordnar också regelbundet leveranser genom honom."}},faq={{q="Var hittar jag Smith Argus?",a="Smith Argus finns i Goldshire, mitt i Elwynn Forest. Du hittar honom vid städet och smedjan utomhus bakom rustningsbutiken, nära Lion's Pride Inn.",al={"argus plats","var finns smith argus","smith argus elwynn"}},{q="Vilka tjänster erbjuder Smith Argus?",a="Argus lär nybörjare grunderna i smide. Hans titel i Classic är Journeyman Blacksmith.",al={"vad lär argus ut","argus tränare","smedjetränare i goldshire"}},{q="Varför skickar en smed i Redridge mig till Smith Argus?",a="Verner Osgood, en hantverkare i Lakeshire, behöver stora mängder hästskor för att hålla försörjningsvagnar och riddjur i rörelse mot hotet från svartbergsorcherna. Han anlitar Argus i Goldshire för att smida och leverera de järnskor som behövs.",al={"the price of shoes-uppdraget","verners hästskor","varför argus hästskor"}},{q="Vilken koppling har Argus till Stormwind City?",a="Argus samordnar leveranser med dvärgsmeder i Stormwind City, till exempel Grimand Elmore i Dwarven District.",al={"elmore's task","stormwind-griffon argus"}},{q="Kan Smith Argus träna mig i avancerat smide eller expertsmide?",a="Argus lär ut de första stegen i smide. Avancerade tekniker kräver mer erfarna mästare i större bosättningar.",al={"argus expertsmed","hur långt kan argus träna"}},{q="Tillhör Smith Argus något särskilt skrå?",a="Argus är en trogen undersåte till Stormwinds kungarike och tillhör det lokala hantverkarsamhället som tjänar Alliansen i Elwynn Forest.",al={"argus fraktion","argus skrå"}}},fx={["07d5dba5"]={q="Vem är Smith Argus?",a="Smith Argus är smed och tjänar Stormwinds kungarike från smedjan i Goldshire. Han är ett pålitligt inslag i Elwynn Forest och smider järn och stål åt lokala försvarare, samtidigt som han utbildar blivande hantverkare och håller försörjningslinjerna öppna med andra smeder i människornas länder.",al={"vem är argus","smith argus historia","vem är smith argus"}},["79448098"]={q="Vems sida står Smith Argus på?",a="Smith Argus är lojal mot Stormwinds kungarike och Alliansen. Han är stationerad vid det livliga vägskälet i Goldshire och samarbetar med hantverkare i trakten för att förse Stormwinds avlägsna bosättningar och befästa dem mot hoten som växer sig allt starkare.",al={"smith argus fraktion","är argus med alliansen eller horden","vem tjänar argus"}},bbf4c38d={q="Varför är Smith Argus här?",a="Argus driver den viktiga smedjan i Goldshire, som ligger direkt längs handelsvägen mellan Stormwind City, Redridge och Westfall. Härifrån kan han enkelt förse utposterna i trakten, sko hästar och utbilda nya smeder som är oumbärliga för rikets försvar.",al={"varför är argus i goldshire","vad förde smith argus hit"}},d8765a7e={q="Vad vill Smith Argus?",a="Smith Argus vill hålla sin smedja i gott skick och upprätthålla handeln med kollegor på avlägsna platser, som Verner Osgood i Redridge. Han utför specialbeställningar på hästskor och utbyter tekniska försändelser för att se till att rikets bosättningar har all utrustning de behöver.",al={"argus drivkraft","vad behöver argus","smith argus mål"}}},fp="11,191,22.306.0,28.355.0,29.136.0,39.91.0,57.189.0,45.118.0,55.124.0,48.136.0"}
P.entries["npc:sneed"] = {n="Sneed",s="Sneed är Defias Brotherhoods goblinske timmermästare och håller till djupt inne i The Deadmines. Från timmerkammaren som kallas Mast Room styr han en tung flismaskin av egen konstruktion för att bearbeta virke till Edwin VanCleefs hemliga jätteskepp.",h="Sneed är Defias Brotherhoods goblinske timmermästare och håller till djupt inne i The Deadmines.",kw={"the deadmines","edwin vancleef","goblin","jätteskepp","timmermästare","mast room","flismaskin","sneed","sneed's shredder"},ang={["faction:Alliance"]="När Sneed fälls stryps virkesleveranserna till Ironclad Cove, vilket blir ett hårt slag mot Defias Brotherhoods skeppsbygge.",["profession:Engineering"]="Sneeds specialbyggda flismaskin visar upp klassiskt goblinhantverk: förödande effektiv, tungt beväpnad och pressad långt bortom normala säkerhetsgränser för att maximera produktionstakten.",["race:Gnome"]="Gnomiska besökare i Mast Room känner igen Sneeds maskin som ett typiskt exempel på goblinuppfinningsrikedom: högljudd, farlig och byggd utan hänsyn till förarens bekvämlighet eller konstruktionens hållbarhet."},sec={{t="Defias timmermästare",b="Defias Brotherhood hämtar sina kärnmedlemmar bland missnöjda mänskliga stenhuggare och vanliga arbetare, men ett bepansrat krigsskepp kräver specialister. Edwin VanCleef rekryterade Sneed särskilt för hans ingenjörskunskaper och skoningslösa goblineffektivitet. I Mast Room, intill det underjordiska järnvägsnätet, övervakar Sneed den snabba fällningen, kapningen och formningen av virket till VanCleefs väldiga skräckskepp."},{t="Industriell brutalitet",b="Sneeds främsta mål är att skära ner på kostnaderna och klara tidsfristerna, oavsett följderna. För att skynda på arbetet leder han från en specialbyggd flismaskin med överdimensionerade surrande sågblad. Den dödliga maskinen förvandlar råa trädstammar till skeppsvirke på några sekunder. Om inkräktare tränger in honom förlitar sig Sneed på maskinens pansar för att mala ner dem, men han tvekar inte att klättra ur vraket och slåss med bara händerna om hans konstruktion går sönder."}},faq={{q="Vem är Sneed?",a="Sneed är en gobliningenjör och timmermästare som arbetar för Edwin VanCleef. Han har i uppgift att övervaka bearbetningen av timmer inne i The Deadmines för bygget av Defias jätteskepp.",al={"vem är sneed","sneeds bakgrund","vad är sneed"}},{q="Var hittar man Sneed?",a="Sneed finns i Mast Room, en industriell timmersal längs gruvspåren inne i The Deadmines, under Moonbrook.",al={"sneeds plats","var finns sneed","sneeds rum"}},{q="Varför arbetar en goblin för Defias Brotherhood?",a="Edwin VanCleef behövde specialiserad industrikunskap och snabba resultat för att bygga sitt hemliga krigsskepp. Han anställde legogobliner som Sneed, som bryr sig föga om politik eller etik så länge betalningen är god.",al={"varför är sneed med defias","goblin i deadmines","varför anlitar defias gobliner"}},{q="Vad styr Sneed i strid?",a="Sneed styr Sneed's Shredder, en tung, tvåbent mekanisk skördare med sågblad som han byggt själv för att skörda och såga timmer i skrämmande hastighet.",al={"sneeds robot","sneeds mekaniska maskin","sneed's shredder"}},{q="Vad händer när hans flismaskin förstörs?",a="Att förstöra flismaskinen avslutar inte striden. Sneed kastar sig ut ur maskinens rykande rester och fortsätter att slåss direkt mot inkräktarna till fots.",al={"sneeds fas två","sneed utanför flismaskinen","dör sneed när flismaskinen förstörs"}},{q="Vad ska Sneed använda virket till?",a="Virket som sågas i Sneeds kammare transporteras nedströms till Ironclad Cove, där Brotherhood bygger ett massivt krigsskepp för att slå tillbaka mot Stormwind.",al={"varför sågar sneed trä","mast rooms syfte","trä i deadmines"}}},fx={a403ba53={q="Vems sida arbetar Sneed för?",a="Sneed arbetar helt och hållet för Edwin VanCleef och Defias Brotherhood. Gobliner brukar vara neutrala handelsmän som bara drivs av vinst, men Sneed tjänar VanCleef som deras hängivna timmermästare. Han övervakar brödraskapets hemliga industriella skogsavverkning djupt inne i The Deadmines och bidrar med sin ingenjörsskicklighet och skoningslösa effektivitet till deras kamp mot Stormwind.",al={"sneeds fraktion","vem arbetar sneed för","är sneed med defias"}},["9b5b74a3"]={q="Vad vill Sneed?",a="Sneeds mål är enkelt: att bygga Defias juggernaut så billigt och snabbt som möjligt. Han anlitades för sin hänsynslösa effektivitet och driver sina avverkningsarbeten dygnet runt. Med sin specialbyggda skogshuggare fäller han timmer så att byggandet av Brotherhoods hemliga krigsfartyg kan fortsätta utan dröjsmål eller onödigt slöseri.",al={"sneeds mål","vad försöker sneed göra","sneeds motiv"}},e888ebfc={q="Varför är Sneed här i The Deadmines?",a="Sneed är stationerad i Mast Room i The Deadmines för att leverera det grova timmer som Defias Brotherhoods väldiga örlogsfartyg kräver. Från den underjordiska avverkningsplatsen styr han sin skogshuggare för att röja, såga och förbereda de väldiga träbalkar som ska utgöra juggernautens ryggrad.",al={"varför är sneed i the deadmines","sneeds syfte i the deadmines","varför är sneed i mast room"}},["5de8a7f0"]={q="Vem står Sneed i förbund med?",a="Sneed rapporterar direkt till Edwin VanCleef, Defias Brotherhoods överordnade ledare. VanCleef anlitade gobliningenjören för att övervaka timmerhanteringen i grottsystemet och införlivade Sneed och hans maskiner i Defias övergripande befälsordning, där även personer som Rhahk'Zor och Gilnid ingår.",al={"vem rapporterar sneed till","sneed edwin vancleef","sneeds koppling till defias"}}},fp="5,197,23.385.0,20.365.0,13.143.0,25.111.0,51.197.0,33.123.0,44.116.0,34.136.0"}
P.entries["npc:sneed-s-shredder"] = {n="Sneed's Shredder",s="Sneed's Shredder är en imponerande mekanisk timmermaskin som står djupt inne i The Deadmines. Den styrs av goblinernas arbetsledare Sneed och fungerar både som tung industriutrustning åt Edwin VanCleefs skeppsbyggare och som ett skräckinjagande försvar mot inkräktare.",h="Sneed's Shredder är en imponerande mekanisk timmermaskin som står djupt inne i The Deadmines.",kw={"cirkelsåg","the deadmines","defias","goblin","timmer","fjärrkontroll","flismaskin","sneed","vancleef"},ang={["faction:Alliance"]="När Sneed och hans maskin röjs ur vägen lamslås timmerarbetet som försörjer Edwin VanCleefs hemliga krigsflotta.",["profession:Engineering"]="Flismaskinen är ett klassiskt exempel på goblinernas mekaniska ingenjörskonst, men den kan fortfarande påverkas av en Gnomish Universal Remote.",["race:Gnome"]="Shoni the Shilent i Gnomeregans underjordiska anfallstrupp vill åt kraftkällan i detta goblinbyggda vidunder, så att hon kan driva borrarna som kan öppna vägen till Gnomeregan igen."},sec={{t="Industriell skräck",b="I The Deadmines goblinstyrda gjuteri har de mekaniska flismaskinerna två syften: att bearbeta stora mängder timmer åt Edwin VanCleefs dolda jätteskepp och att användas som bepansrade chockmaskiner mot inkräktare. Sneed, som övervakar timmerarbetet, styr själv detta modifierade mekaniska vidunder och gör den överdimensionerade cirkelsågen till ett försvarsvapen."},{t="En dödlig förarhytt",b="Hotet är inte över när maskinen besegras. Sneed sitter i en öppen förarhytt ovanför de snurrande klingorna och förlitar sig på tjocka järnplåtar och ett skräckinjagande oväsen för att skingra sina fiender. Även när maskineriet går sönder och flismaskinen kollapsar i en dusch av gnistor, hoppar Sneed ut ur det rykande vraket och slåss till sista blodsdroppen."}},faq={{q="Vad används Sneed's Shredder till i The Deadmines?",a="Defias Brotherhood förlitar sig i hög grad på goblinmaskiner för att bryta sig genom underjordisk sten och bearbeta de enorma mängder timmer som behövs för att bygga deras hemliga jätteskepp. Sneed använder flismaskinen för att såga virke och brutalt upprätthålla ordningen i de underjordiska arbetsområdena.",al={"varför finns det en flismaskin i the deadmines","flismaskinens syfte i the deadmines"}},{q="Vad händer när flismaskinen förstörs?",a="När flismaskinen drabbas av ett kritiskt maskinfel överlever Sneed själv kraschen. Goblinpiloten kliver direkt ut ur det förstörda fordonet, viftar med sina egna vapen och går till angrepp mot inkräktarna med stor beslutsamhet.",al={"dör sneed med flismaskinen","sneed's shredder fas två"}},{q="Varför har Defias Brotherhood goblinteknik?",a="Edwin VanCleef anställde gobliningenjörer, hantverkare och legosoldater för att sköta den komplicerade mekaniska verksamheten under Westfall, däribland ångdrivna smedjor, vapenfabriker och sågverk.",al={"defias och gobliner","varför finns gobliner i the deadmines"}},{q="Kan ingenjörer hacka eller styra flismaskinen?",a="Påhittiga uppfinnare med en Gnomish Universal Remote kan kortvarigt kringgå flismaskinens styrsystem och tillfälligt ta kontroll över maskinen från Sneed.",al={"styra sneed's shredder","gnomish universal remote sneed"}},{q="Har Sneed's Shredder något värdefullt?",a="Ja. Dess intakta kraftkälla, Gnoam Sprecklesprocket, eftersöks av Shoni the Shilent i Stormwind. Hon behöver den för att driva gnomernas gyrodrillmatic excavationators inför ett anfall mot Gnomeregan.",al={"uppdragsföremål från sneed's shredder","vad släpper sneed's shredder"}},{q="Vem styr flismaskinen?",a="Maskinen styrs av Sneed, en erfaren goblinförman som leder avverknings- och snickeriarbetet djupt inne i The Deadmines.",al={"vem kör sneed's shredder","sneeds pilot"}}},fx={a3f5b00d={q="Vilken sida slåss Sneed's Shredder för?",a="Den mekaniska besten slåss under Defias Brotherhoods fana. Gobliningenjörer arbetar ofta som neutrala legosoldater för den som betalar bäst, men Sneed och hans bepansrade timmerskärare är helt hängivna Edwin VanCleefs verksamhet djupt under Moonbrook.",al={"sneed's shredder fraktion","vem tjänar sneed","är sneed's shredder defias"}},b57110af={q="Vad vill Sneed med sin skogshuggare?",a="Sneed styr ett gående sågverk fullt av snurrande sågblad och tänker förvandla alla inkräktare till fina träplankor. Utöver att bearbeta timmer och försvara de underjordiska anläggningarna vill han inte mycket mer än att göra dig till färskt sågspån för att du stör Defias område.",al={"sneeds mål","vad vill sneed","sneed's shredders syfte"}},faf23f8c={q="Varför är Sneed's Shredder i The Deadmines?",a="Att bygga ett underjordiskt imperium kräver enormt mycket ingenjörskunskap, timmer och tungt försvar. Sneed's Shredder står i The Deadmines timmerfyllda grottor för att avverka till Brotherhoods hemliga projekt och mala varje inträngande Alliance-agent till flis.",al={"varför är sneed's shredder här","varför är sneed i the deadmines","sneed's shredders plats i the deadmines"}},["0d282aa3"]={q="Varför fruktar man Sneed's Shredder så mycket?",a="Utöver sina väldiga, surrande sågblad sprider den mekaniska skräcken rå panik bland inkräktarna. Sneed släpper regelbundet lös skräckinjagande skurar av skrammel och skärande metalljud som skrämmer äventyrare på flykten, rakt i famnen på väntande Defias-goblins.",al={"varför är sneed's shredder skrämmande","sneed's shredders rykte","skrämma sneed's shredders fiender"}}},fp="16,188,17.267.0,16.234.0,51.184.0,44.142.0,53.176.0,54.101.0,46.197.0,24.103.0"}
P.entries["npc:solm-hargrin"] = {n="Solm Hargrin",s="Solm Hargrin är skurkarnas tränare i Anvilmar i Coldridge Valley. Han är en pragmatisk dvärg som värdesätter heder bland tjuvar och lär unga dvärgiska och gnomiska skurkar konsten att agera i det fördolda. Han är övertygad om att hemliga agenter kommer att visa sig oumbärliga när de geopolitiska spänningarna växer i Azeroth.",h="Solm Hargrin är skurkarnas tränare i Anvilmar i Coldridge Valley.",kw={"anvilmar","coldridge valley","dun morogh","encrypted memorandum","encrypted rune","skurkarnas tränare","solm hargrin"},ang={["class:Rogue"]="För dvärgar och gnomer som tar sina första steg in i skuggorna ger Solm Hargrin grundläggande träning och tyder dina allra första gillesorder.",["race:Dwarf"]="Solm visar en mindre traditionell väg för dvärgar och bevisar att smygande, list och tyst stål har lika stor plats i Dun Morogh som tung rustning och yxor."},sec={{t="En mentor i skuggorna",b="I dvärgarnas fäste Anvilmar håller Solm Hargrin ett vakande och beräknande öga på de snötäckta passen i Coldridge Valley. Ironforge förlitar sig till stor del på bergsfolkets och krigarnas råstyrka, men Hargrin vet att vissa hot kräver en tystare och skarpare hand. Han välkomnar blivande skurkar av både dvärgisk och gnomisk härkomst, hjälper dem att tyda kodade meddelanden och drillar dem i viktiga tekniker som Eviscerate. Framför allt står Hargrin för en yrkesmässig lojalitet och heder bland tjuvar. Han förbereder sina elever för en allt mer instabil värld där tysta knivar ofta formar nationernas öde."}},faq={{q="Vem är Solm Hargrin?",a="Solm Hargrin är en dvärgisk skurkarnas tränare i Anvilmar, utposten där äventyrare börjar i Coldridge Valley i Dun Morogh. Han lär unga dvärgar och gnomer tjuveriets, smygandets och klingornas fördolda konster.",al={"vem är solm","solm hargrins bakgrund","skurkarnas tränare i anvilmar"}},{q="Vilken filosofi har Solm Hargrin om skurkarnas arbete?",a="Hargrin tror starkt på ”heder bland tjuvar”. Han lär sina rekryter att även om deras metoder kan vara ljusskygga, är lojalitet till yrket och varandra avgörande, särskilt när den sköra freden mellan rivaliserande makter hotar att brista.",al={"solms övertygelser","heder bland tjuvar","solms synsätt"}},{q="Vilka uppdrag ger eller tar Solm Hargrin emot?",a="Unga dvärgiska skurkar hänvisas till honom med en Encrypted Rune, medan nya gnomiska skurkar överlämnar en Encrypted Memorandum. När han har tytt dessa inledande order ger han sina elever i uppgift att bemästra offensiva manövrer ute på fältet.",al={"solms uppdrag","encrypted rune solm","encrypted memorandum solm"}},{q="Tränar Solm Hargrin andra raser än dvärgar?",a="Ja. Efter Gnomeregans fall delar gnomiska flyktingar startområdet i Coldridge Valley med dvärgarna. Solm tar gärna gnomiska agenter under sina vingar, tillsammans med sina dvärgiska fränder.",al={"kan gnomer träna med solm","gnomisk skurkarnas tränare anvilmar"}}},fx={["3b6a2fc5"]={q="Vilken sida står Solm Hargrin på?",a="Solm Hargrin är lojal mot Ironforge och Alliance. Han är stationerad i Coldridge Valley och förbereder nya agenter för att försvara dvärgarnas land. Han är övertygad om att skuggkonster är nödvändiga verktyg för att säkra riket medan den politiska oron växer.",al={"solm hargrins fraktion","solm hargrins lojalitet","är solm hargrin med i alliance"}},["7da5d6e5"]={q="Vad vill Solm Hargrin?",a="Hargrin vill lära lovande nya rogues grunderna i smygande, precision och personlig heder. När han ser spänningarna tillta runt om i världen tror han att de som utövar den subtila konsten snart får en viktig roll, och han vill att hans elever ska vara vältränade och disciplinerade.",al={"solm hargrins mål","vad vill solm hargrin","solm hargrins motiv"}},d84d95b0={q="Varför är Solm Hargrin i Coldridge Valley?",a="Han är stationerad i Anvilmar för att handleda nyanlända äventyrare som vandrar skuggornas väg. Som tränare granskar han krypterade meddelanden från hemliga kontakter och inviger unga dvärgar och gnomer i den tysta stridens konst.",al={"varför är solm hargrin här","solm hargrins syfte i anvilmar","varför är solm hargrin i anvilmar"}}},fp="12,182,23.291.0,20.131.0,48.143.0,49.208.0,49.70.0"}
P.entries["npc:sprite-darter"] = {n="Sprite Darter",s="Sprite Darters är små, skimrande älvdrakar som hör hemma i Feralas frodiga trädkronor. De vördas för sina medfödda andliga och magiska egenskaper och fladdrar graciöst bland de uråldriga träden. På senare tid har dessa sällsynta varelser blivit måltavlor för lokala Grimtotem-tauren, som vill fånga och utnyttja dem.",h="Sprite Darters är små, skimrande älvdrakar som hör hemma i Feralas frodiga trädkronor.",kw={"darter-ägg","älvdrake","feralas","grimtotem","kindal moonweaver","muisek","sprite darter","witch doctor uzer'i"},ang={["class:Druid"]="Druider håller älvdrakar högt som naturandarnas fränder och ser hur råbarkade tjuvjägare fångar dem som ett allvarligt störande av skogens balans.",["faction:Alliance"]="Kindal Moonweavers allierade samlas till de fångade ungarnas hjälp i Feralas och hejdar den fientliga Grimtotem-stammens framryckning.",["faction:Horde"]="Trollandliga vägledare som Witch Doctor Uzer'i från Camp Mojache ser Sprite Darters som ypperliga ämnen för att utvinna andlig muisek och ta till vara på Feralas uråldriga essens.",["race:NightElf"]="Nattalver vördar de heliga älvdrakarna som skogens naturliga väktare, så att befria fångade Sprite Darters från Grimtotem är en fråga om att värna ekosystemet."},sec={{t="Vildmarkens älvdrakar",b="Sprite Darters är skygga, bevingade skogsdjur som hör hemma i Feralas uråldriga skogar. Med sina skimrande, iriserande vingar och sin mystiska andliga essens förkroppsligar de Kalimdors djupa skogars nyckfulla men vilda magiska ekologi. De är i regel fredliga och blyga, men deras medfödda motståndskraft mot magiska krafter och deras naturliga styrka gör dem betydelsefulla för dem som står vildmarken nära."},{t="Fångenskap hos Grimtotem",b="På senare tid har de tillbakadragna Sprite Darters ställts inför ett hot utan motstycke. Den aggressiva Grimtotem-taurenklanen som lever i Feralas har börjat samla in och sätta stora mängder av dessa sällsynta varelser i burar, av dunkla skäl. Bekymrade nattalver som Kindal Moonweaver rekryterar aktivt allierade för att slå sönder burarna och befria de fångade ungarna innan Grimtotem böjer dem efter sin vilja."},{t="Andligt intresse",b="Utöver nattalvernas försök att skydda dem har Sprite Darters väckt intresse hos utomstående som studerar urkraft. Witch Doctor Uzer'i, en trollandlig vägledare verksam från Camp Mojache, intresserar sig särskilt för de naturliga energierna och muisek som finns i Sprite Darters och söker deras essens för att förstå den unika magi som frodas i Feralas."}},faq={{q="Vad är Sprite Darters?",a="Sprite Darters är små älvdrakar som lever i vildmarken i Feralas. De är kända för sina skimrande vingar, sin koppling till naturen och sitt svårfångade magiska beteende.",al={"information om sprite darter","vad är en sprite darter","är sprite darters drakar"}},{q="Varför fångar Grimtotem-tauren dem?",a="De exakta skälen är höljda i dunkel, men Grimtotem-klanen fångar och sätter Sprite Darters i burar i stora mängder ute i skogarna, troligen för att utnyttja deras sällsynta andliga och magiska egenskaper.",al={"varför grimtotem sätter dem i burar","grimtotem och sprite darters","varför hålls darters i burar"}},{q="Vem försöker skydda Sprite Darters?",a="Kindal Moonweaver, en alv som bor i Feralas, arbetar aktivt för att skydda dem genom att skicka välvilliga äventyrare att slå sönder Grimtotem-burarna och rädda fångade Sprite Darters.",al={"vem skyddar sprite darters","kindal moonweaver och sprite darters","alliansens uppdrag med sprite darter"}},{q="Varför är Witch Doctor Uzer'i intresserad av Sprite Darters?",a="Witch Doctor Uzer'i studerar Feralas uråldriga andliga krafter. Han söker Sprite Darters essens, eller muisek, för att lära sig mer om regionens inneboende magiska djurliv.",al={"witch doctor uzeri och sprite darter","uzeris uppdrag med darters"}},{q="Kan du föda upp en Sprite Darter?",a="De som hjälper Kindal Moonweaver att befria de fångade ungarna och försvara deras bon kan så småningom anförtros ett sällsynt Sprite Darter Egg att föda upp och skydda.",al={"sprite darter egg","sprite darter som husdjur","kan jag få en sprite darter"}},{q="Är Sprite Darters fientliga?",a="Vilda Sprite Darters är i regel skygga och fredliga mot resenärer, men liksom alla vilda varelser försvarar de sig med utbrott av naturmagi om de hotas eller provoceras.",al={"är sprite darters farliga","anfaller sprite darters"}}},fp="13,309,26.410.0,19.404.0,18.365.0,24.182.0,44.209.0,44.169.0,56.188.0,30.170.1,27.185.0"}
P.entries["npc:sprite-jumpsprocket"] = {n="Sprite Jumpsprocket",s="I Stormwinds Dwarven District arbetar Sprite Jumpsprocket bland gnomiska och dvärgiska hantverkare. Liksom många gnomer som sökte skydd efter Gnomeregans fall ägnar hon sig åt ingenjörskonst tillsammans med andra mekaniker.",h="I Stormwinds Dwarven District arbetar Sprite Jumpsprocket bland gnomiska och dvärgiska hantverkare.",kw={"lärling","dwarven district","ingenjör","gnom","jumpsprocket","sprite jumpsprocket","stormwind","mekaniker"},ang={["faction:Alliance"]="Som medlem av Alliansen kan du se det vardagliga samarbetet mellan människor, dvärgar och gnomer i Sprites arbete i Dwarven District. Det samarbetet håller huvudstadens infrastruktur igång.",["profession:Engineering"]="Som ingenjör kan du se Sprite Jumpsprocket som en medstudent i kugghjul, kopparrör och flyktiga blandningar i Stormwinds mest industriella kvarter.",["race:Gnome"]="Som gnom kan du se Gnomeregans landsflyktiga i Sprite. De håller fast vid sin kärlek till hantverk och mekanisk skicklighet långt från sitt förlorade hemland."},sec={{t="En mekaniker i Stormwind",b="Sprite Jumpsprocket arbetar som ingenjörslärling i Stormwinds Dwarven District, där gnomer och dvärgar smider metall och utformar invecklade apparater sida vid sida. Hon har funnit sin plats i kungarikets huvudstad, där lärlingar i mekanik finslipar sitt hantverk under erfarna mästare. Deras uppfinningsrika sinnen hjälper till att underhålla Alliansens vardagliga mekanismer och underverk."},{t="Gnomisk uppfinningsrikedom i exil",b="Efter Gnomeregans fall spreds de fördrivna gnomerna över Alliansens länder och tog med sig sina färdigheter inom mekanik, kemi och ingenjörskonst. I Stormwind fann de en välkomnande fristad i Dwarven District, med dess masugnar och arbetsbänkar. Sprite Jumpsprocket står för deras beslutsamhet att bemästra ingenjörskonsten trots de svårigheter hennes folk har mött."}},faq={{q="Vem är Sprite Jumpsprocket?",a="Sprite Jumpsprocket är en kvinnlig gnom och ingenjörslärling som bor och arbetar i Stormwind Citys Dwarven District.",al={"sprite jumpsprocket","vem är sprite","sprite jumpsprocket bakgrund"}},{q="Var hittar jag Sprite Jumpsprocket?",a="Du hittar Sprite Jumpsprocket i Stormwind Citys Dwarven District, bland dess verkstäder, städ och andra entusiaster inom ingenjörskonst.",al={"sprite jumpsprocket plats","var finns sprite","hitta sprite jumpsprocket"}},{q="Vilken roll har hon i Stormwind?",a="Sprite Jumpsprocket är ingenjörslärling. Hon representerar gnomiska mekaniker som finslipar sina uppfinningsrika färdigheter i Alliansens huvudstad.",al={"sprite jumpsprockets roll","vad gör hon","sprite jumpsprockets funktion"}},{q="Varför bor gnomer som Sprite i Stormwind?",a="Efter Gnomeregans fall sökte många gnomer skydd hos sina dvärgiska kusiner i Ironforge och runtom i människornas länder, särskilt i Stormwind City, där deras industriella uppfinningsrikedom är mycket efterfrågad.",al={"varför gnomer i stormwind","gnomer i dwarven district","gnomiska flyktingar"}},{q="Är Sprite Jumpsprocket knuten till några betydande uppdrag?",a="Sprite Jumpsprocket har en mindre roll i Dwarven Districts lokala kvarter som del av dess ingenjörsgemenskаp.",al={"sprite jumpsprocket uppdrag","uppdrag för sprite"}},{q="Har hon någon koppling till Westfall?",a="Sprite Jumpsprocket förekommer ibland i register som rör de omgivande södra kungarikena, men hon är stationerad i Stormwind Citys Dwarven District. Ingenjörskonstruktioner i hela regionen bygger ofta på gnomiska konstruktioner.",al={"sprite jumpsprocket westfall","ingenjör i westfall"}}},fx={b9758f03={q="Vilken sida står Sprite Jumpsprocket på?",a="Sprite Jumpsprocket står stadigt på Alliance och Gnomeregan Exiles sida. Liksom många fördrivna gnomer som sökte skydd hos sina dvärgsläktingar och mänskliga allierade efter Gnomeregans fall, arbetar hon i det livliga Dwarven District i Stormwind City. Där erbjuder hon sina ingenjörskunskaper till rikets och sina Alliance-medborgares tjänst.",al={"sprite jumpsprockets fraktion","sprite jumpsprocket alliance eller horde","vem tjänar sprite jumpsprocket"}}},fp="19,198,21.331.0,26.338.0,27.115.0,37.135.0,38.146.0,47.192.0,50.76.0,32.139.0"}
P.entries["npc:sputtervalve"] = {n="Sputtervalve",s="Under press i Ratchet skyndar Sputtervalve på med att slutföra strimlarforskningen åt Tinkers' Union. Director Riddlevox håller honom till stenhårda tidsfrister, och han anlitar äventyrare för att stjäla ritningar från rivalen Venture Company.",h="Under press i Ratchet skyndar Sputtervalve på med att slutföra strimlarforskningen åt Tinkers' Union.",kw={"ratchet","riddlevox","samophlange","skördare","the sludge fen","sputtervalve","tinkers' union","venture company","wizzlecrank"},ang={["faction:Horde"]="Ratchet är neutralt, men Sputtervalve är beroende av att Horde-resenärer som korsar The Barrens stör Venture Companys verksamhet och smugglar maskindelar.",["profession:Engineering"]="Sputtervalve visar den hänsynslösa sidan av goblinteknik: när uppfinningsarbetet kör fast stjäl man ritningarna från en rival."},sec={{t="Industriell press",b="I Ratchet lyder Sputtervalve under Director Riddlevox i Tinkers' Union. Den goblinska ingenjören leder utvecklingen av strimlare och har upptäckt att arbetet är brutalt. Modern mekanisering går snabbt framåt, Venture Company pressar hårt och hans egna prototyper är få. När tidsfristen närmar sig fruktar Sputtervalve att erkänna sitt misslyckande inför Union. Han tar till en välbekant goblinmetod: att stjäla bättre konstruktioner från dem som byggde dem först."},{t="Ögonen på Venture Company",b="Venture Companys borrningsverksamhet vid The Sludge Fen i nordväst är Sputtervalves främsta mål. Deras senaste strimlare har utbytbara händer, förfinade styrgrepp och avancerade inre mekanismer, däribland den svårfunna samophlange. Sputtervalve skickade sin medarbetare Wizzlecrank till Fen för fältforskning, men Wizzlecrank blev fångad. Nu anlitar Sputtervalve kringvandrande legosoldater för att återta den stulna tekniken och rädda sin partner."},{t="En fixare i Ratchet",b="Sputtervalve hjälper också till med märkliga kuriositeter som passerar genom The Barrens. Äventyrare kommer ibland med bisarra artefakter genomsyrade av korruption från Wailing Caverns, till exempel en Glowing Shard. Han känner det lokala landskapet väl nog för att hänvisa dem bort från maskineriet och till de isolerade druiderna som slagit läger ovanför grottorna."}},faq={{q="Vem är Sputtervalve?",a="Sputtervalve är en gobliningenjör i Ratchet och medlem av Tinkers' Union. Director Riddlevox gav honom ansvaret för forskning och utveckling av strimlare, och han kämpar för att klara de strikta tidsfristerna.",al={"vem är sputtervalve","sputtervalve ratchet","sputtervalves bakgrund"}},{q="Varför riktar Sputtervalve in sig på Venture Company?",a="Venture Company bygger avancerade strimlare vid The Sludge Fen, med utbytbara händer och förfinade styrgrepp. Eftersom Sputtervalve inte kan mäta sig med deras konstruktioner tar han till industrispionage för att stjäla deras ritningar och maskiner.",al={"varför angripa venture company","sputtervalve sludge fen","sputtervalve venture company"}},{q="Vad är en samophlange?",a="En samophlange är en avancerad mekanism som finns inuti Venture Companys strimlare. Sputtervalve anlitar äventyrare för att hämta och undersöka en, så att han kan lära sig deras teknik.",al={"vad är en samophlange","samophlange-uppdrag","vad gör en samophlange"}},{q="Vem är Wizzlecrank?",a="Wizzlecrank är Sputtervalves medarbetare och fältagent. Wizzlecrank skickades till The Sludge Fen för fältforskning men blev fångad, så Sputtervalve anlitar hjälp för att rädda honom och återta den stulna tekniken.",al={"wizzlecrank","vem är wizzlecrank","sputtervalves partner"}},{q="Varför bryr sig Sputtervalve om Glowing Shard?",a="Sputtervalve studerar inte organiska kuriositeter, men han känner The Barrens väl. När han får se skärvan som hämtats från Wailing Caverns hänvisar han äventyrarna till druiderna som slagit läger ovanför grottorna.",al={"glowing shard sputtervalve","glowing shard wailing caverns","skärvuppdrag ratchet"}},{q="Vem är Director Riddlevox?",a="Director Riddlevox leder Tinkers' Union. Han gav Sputtervalve ansvaret för utvecklingen av strimlare och håller honom till strikta produktionsfrister.",al={"riddlevox","director riddlevox","chef för tinkers' union"}}},fx={["8cc08011"]={q="Vilken sida står Sputtervalve på?",a="Sputtervalve lyder under Tinkers' Union och håller till i den neutrala goblinhamnen Ratchet. Han är neutral mot resenärer av alla slag, men hans främsta lojalitet och affärsintressen är knutna till goblinernas företagande och hans överordnade i Union, inte till Horde eller Alliance.",al={"sputtervalves fraktion","vem arbetar sputtervalve för","är sputtervalve med i horde"}},a7196ac5={q="Vad vill Sputtervalve?",a="Sputtervalve måste desperat hinna klart med ett ingenjörsprojekt före en snäv deadline som Director Riddlevox har satt. Hans egna konstruktioner av skogshuggare har kört fast, så han vill stjäla ritningar och delar, särskilt från Venture Companys överlägsna modeller i The Sludge Fen, för att rädda sin forskning och behålla jobbet.",al={"vad försöker sputtervalve göra","sputtervalves mål","sputtervalves planer för skogshuggaren"}},a4a50e43={q="Varför är Sputtervalve i Ratchet?",a="Sputtervalve är stationerad i Ratchet för att övervaka utvecklingen och forskningen kring skogshuggare åt Tinkers' Union. Hamnens närhet till The Sludge Fen ger honom en utmärkt utsiktspunkt för att hålla koll på rivaliserande ingenjörer och skicka ut agenter som kan stjäla industrihemligheter från Venture Companys verksamhet i närheten.",al={"varför är sputtervalve här","varför är sputtervalve i the barrens","sputtervalves plats i ratchet"}},dc6c348a={q="Vem står Sputtervalve i förbund med?",a="Sputtervalve rapporterar direkt till Director Riddlevox i Tinkers' Union. I fält samarbetar han nära med sin partner Wizzlecrank, som han skickade till The Sludge Fen för att stjäla Venture Company-prototyper. Han förlitar sig också på villiga äventyrare för att få kontakt med lokala informatörer runt om i The Barrens.",al={"sputtervalves kontakter","vilka känner sputtervalve","sputtervalves partner"}}},fp="12,223,19.435.0,27.456.0,18.338.0,20.202.0,50.222.0,22.171.0,19.196.1,51.199.0,26.143.0"}
P.entries["npc:sten-stoutarm"] = {n="Sten Stoutarm",s="Sten Stoutarm är en praktisk dvärgisk utrustningshandlare och kurir som är stationerad utanför Anvilmar i Coldridge Valley. Han ansvarar för att förse nya rekryter med utrustning och sköta lokala försändelser, och ser till att nybörjare i bergen håller sig varma, mätta och informerade trots de hårda bergsförhållandena.",h="Sten Stoutarm är en praktisk dvärgisk utrustningshandlare och kurir som är stationerad utanför Anvilmar i...",kw={"anvilmar","coldridge","dun morogh","post","utrustningshandlare","sten","stoutarm","trogg"},ang={["faction:Alliance"]="Det är avgörande för Ironforges träningsplatser att hålla kommunikationen genom Coldridge Pass igång, och Stens postnätverk håller dalen i kontakt med den större Alliansen.",["race:Dwarf"]="Sten förkroppsligar Dun Moroghs rättframma gästfrihet och ser till att hans folk är klädda i tjockt läder och mätta innan han skickar ut dem i snön.",["race:Gnome"]="När gnomiska flyktingar tränar tillsammans med dvärgar i Anvilmar behandlar Sten dem med samma praktiska förväntningar, skickar iväg dem med post och utrustar dem för vädret."},sec={{t="En hjälpande hand i snön",b="Sten Stoutarm befinner sig nära hjärtat av Coldridge Valley och är ett av de första vänliga ansikten som nya dvärgiska och gnomiska rekryter möter utanför Anvilmars värdshus. Eftersom dalen är isolerad av vinterstormar och hot som närmar sig, ser Sten till att förse gröna lärlingar med slitstark utrustning innan de fryser eller ger sig ut i snödrivorna oförberedda."},{t="Hålla förbindelserna öppna",b="Utöver att sätta ihop vinterutrustning av lokala vargskinn fungerar Sten som en informell postmästare i Coldridge Valley. Han hanterar meddelanden som färdas genom det förrädiska Coldridge Pass och delar ut officiella runor, promemorior och order till klassinstruktörer runt om i dalen, så att nybörjare bland krigare, präster och magiker får sina instruktioner trots att fientliga trogg blockerar tunnlarna."}},faq={{q="Vem är Sten Stoutarm?",a="Sten Stoutarm är en dvärgisk utrustningshandlare och budbärare som är stationerad utanför Anvilmar i Coldridge Valley. Han hjälper nya rekryter genom att förse dem med varma kläder och delegera lokala postleveranser.",al={"sten stoutarm","vem är sten","postbud i anvilmar"}},{q="Vilken roll har han i Coldridge Valley?",a="Sten fungerar både som kvartermästare och kurirkontakt för Anvilmar. Han samlar in lokala resurser som vargkött och skinn för att tillverka skyddande utrustning åt lärlingar, samtidigt som han förmedlar korrespondens och träningspromemorior genom dalen.",al={"stens arbete","vad gör sten","stens roll"}},{q="Varför behöver Sten få posten levererad?",a="Eftersom trogg och vinterväder gör Coldridge Pass farligt har post och förnödenheter svårt att ta sig in i dalen. När meddelandena väl kommer fram förlitar sig Sten på pålitliga nybörjare som kan leverera paket och brev till invånare som Talin Keeneye.",al={"varför postleverans i coldridge","stens post","postleverans i coldridge valley"}},{q="Vad tycker Sten om trogg i dalen?",a="Sten ser trött och föga imponerad på skadedjuren som hemsöker de omkringliggande kullarna. Han är känd för att säga att när man har sett en trogg har man sett dem alla.",al={"sten och trogg","trogg-citat","stens syn på trogg"}},{q="Varför ber han om vargkött?",a="Sten byter till sig tåliga, varma handskar från äventyrare på genomresa i utbyte mot segt vargkött. På så vis hjälper han dalens försvarare att få mat och utrustar dem mot den bitande kylan i Dun Morogh.",al={"uppdrag hos dvärgisk utrustningshandlare","uppdrag med vargkött","stens vargkött"}},{q="Vad är runorna och promemoriorna som Sten ger till nya äventyrare?",a="Det är förseglade brev och träningsbrickor som skickats från överordnade runt om i Ironforge och Dun Morogh. De instruerar unga lärlingar att anmäla sig hos sina respektive klassinstruktörer inne i Anvilmar.",al={"consecrated rune","simple memorandum","stens anteckningar"}}},fx={be997a27={q="Vilken sida står Sten Stoutarm på?",a="Sten Stoutarm är en lojal dvärg från Ironforge och står stadigt på Alliance sida. Han är stationerad i Anvilmar i Coldridge Valley, där han stöder den lokala träningsplatsen och ser till att nyanlända dvärg- och gnomrekryter får förnödenheterna och orderna de behöver för att försvara dalen.",al={"sten stoutarms fraktion","vem tjänar sten stoutarm","sten stoutarm alliance"}},["9084afa8"]={q="Vad vill Sten Stoutarm?",a="Sten vill se till att logistiken fungerar smidigt i Coldridge Valley trots farorna runtomkring. Dalen är trängd av troggs och vilddjur, så han söker dugliga nya rekryter som kan dela ut viktig post från passet, samla vargkött till slitstarka handskar för fältutrustare och bära skriftliga order till deras respektive klasstränare.",al={"vad vill sten","sten stoutarms mål","varför behöver sten hjälp"}},d8d60996={q="Varför är Sten Stoutarm här i Coldridge Valley?",a="Sten är stationerad i Anvilmar och fungerar som en viktig samordnare och brevbärare i Coldridge Valley. Passet som förbinder dalen med resten av Dun Morogh är farligt och fullt av fiender. Därför behövs någon på plats som kan styra trafiken, utrusta oerfarna försvarare och vidarebefordra meddelanden till instruktörerna i Anvilmar.",al={"varför är sten här","varför är sten stoutarm i coldridge valley","orsaken till sten stoutarms placering"}}},fp="13,206,26.232.0,22.326.0,21.156.0,43.180.0,34.226.0,52.120.0,30.146.0,63.194.0"}
P.entries["npc:stitches"] = {n="Stitches",s="Stitches är ett kolossalt, hopfogat odött vidunder som terroriserar Duskwood. Det dyker upp i zonens västra delar och marscherar obevekligt längs huvudvägen mot Darkshire, där det slaktar intet ont anande resenärer och övermannar Night Watchs vägspärrar.",h="Stitches är ett kolossalt, hopfogat odött vidunder som terroriserar Duskwood.",kw={"vidunder","darkshire","ello ebonlocke","night watch","raven hill","stitches"},ang={["class:Paladin"]="Stitches är en grotesk skapelse av nekromanti och vanhelgande köttslöjd och står för allt som det Heliga Ljuset ska rena bort.",["faction:Alliance"]="Stitches utgör ett katastrofalt hot mot Darkshires hårt prövade invånare och förvandlar Duskwoods huvudväg till en dödlig prövning för nya rekryter i Alliansen."},sec={{t="Skräcken på huvudvägen",b="Stitches är ett odött vidunder som satts samman av likdelar och ohelig trolldom. Det visar sig nära Abercrombies skjul nordost om Raven Hill Cemetery och beger sig genast österut längs vägen mot Darkshire. Stitches är välsignad med enorm fysisk styrka och obeveklig illvilja och sliter sig igenom alla Night Watchs vägspärrar längs vägen, däribland försvarslägret mitt emot Vul'Gol Ogre Mound och utposten utanför The Rotting Orchard. Där slaktar det både intet ont anande resenärer och stadens försvarare."},{t="Balsamerarens förvridna hämnd",b="Stitches dök inte upp i Duskwood av en slump; han skapades medvetet som ett redskap för hämnd. Abercrombie, som förbipasserande bara kände som en harmlös eremit, bar på ett djupt agg mot Lord Ello Ebonlocke, borgmästaren i Darkshire. Genom att låta intet ont anande äventyrare samla ockulta reagenser, verktyg och material under oskyldiga förevändningar kunde Abercrombie färdigställa sin fasansfulla skapelse. Han skickade Stitches som en hånfull ”gåva” till Darkshire, fast besluten att bryta stadens försvar och straffa Lord Ebonlocke."}},faq={{q="Vem skapade Stitches?",a="Stitches är en skapelse av nekromanti, hopsatt i Duskwood. Att ta reda på vem som skapade honom är en del av mysteriet kring de odöda nära Raven Hill.",al={"stitches skapare","vem skapade stitches","abercrombie stitches"}},{q="Varför marscherar Stitches mot Darkshire?",a="Stitches rycker fram längs Duskwoods huvudväg mot staden och angriper Night Watch och alla andra i sin väg. Orsaken bakom attacken avslöjas under den lokala undersökningen.",al={"varför stitches darkshire","stitches attackmål","vart går stitches"}},{q="Kan Night Watch stoppa Stitches på egen hand?",a="Nej. Om ingen ingriper övermannar och krossar Stitches lätt Night Watchs vägspärrar utanför Vul'Gol Ogre Mound och The Rotting Orchard innan han når Darkshires portar. Det krävs ett samlat försvar från milisen och äventyrare på genomresa för att fälla honom.",al={"vakter mot stitches","night watch besegra stitches","kan darkshires vakter döda stitches"}},{q="Var dyker Stitches upp?",a="Stitches dyker upp bakom Abercrombies skjul, som ligger längs vägen nordost om Raven Hill Cemetery, innan han inleder sin långa, dödliga marsch österut genom Duskwood.",al={"var dyker stitches upp","stitches plats","stitches startplats"}}},fx={["66b85146"]={q="Vem är Stitches?",a="Stitches är ett väldig, fruktansvärt odött monster som satts samman av räddade kroppsdelar av eremitnekromantikern Abercrombie the Embalmer. Han syddes ihop i hemlighet nära Raven Hill och skapades som ett hämndredskap, avsett att marschera rakt nerför vägen och ödelägga Darkshire.",al={"vem är stitches","vad är stitches","stitches historia"}},["74b258bc"]={q="Vilken sida står Stitches på?",a="Stitches tjänar endast sin skapare, Abercrombie the Embalmer. Han är inte allierad med Scourge eller någon större fraktion, utan fungerar helt och hållet som den galne eremitens personliga vapen mot Lord Ello Ebonlocke och folket i Darkshire.",al={"stitches fraktion","är stitches med i scourge","vem tjänar stitches"}},c18e0cb4={q="Vad vill Stitches?",a="Som en tanklös odöd konstruktion har Stitches inga egna, komplexa önskningar. Han lyder ordern som Abercrombie präntade in i hans återupplivade kropp: att marschera obevekligt mot Darkshire, slakta alla som står i vägen och utkräva blodig hämnd på staden.",al={"vad vill stitches","stitches mål","stitches syfte"}},["3c61022e"]={q="Vem är Stitches knuten till?",a="Stitches är nära knuten till Abercrombie the Embalmer, som satte ihop honom, och till borgmästaren Lord Ello Ebonlocke, åt vilken monstret skapades som en illvillig ”gåva”. Även äventyrarna som ovetande hjälpte Abercrombie med till synes harmlösa ärenden i Duskwood bidrog ovetande till hans skapelse.",al={"stitches band","vem är stitches knuten till","stitches och abercrombie"}},f85c8148={q="Varför är Stitches så fruktad?",a="Stitches är ett skräckinjagande hot tack vare sin enorma råstyrka. Han tornar upp sig över vanliga människor och är mycket starkare än vilddjuren och de mindre odöda som stryker omkring i Duskwood. Han mejjar lätt ner Night Watch-patrullerna som skickas för att stoppa honom på huvudvägen.",al={"varför fruktas stitches","är stitches farlig","varför är stitches berömd"}}},fp="8,124,27.421.0,30.396.1,21.135.2,42.182.2,47.250.0,26.150.1"}
P.entries["npc:strahad-farsan"] = {n="Strahad Farsan",s="Ovanför Ratchet lär Strahad Farsan häxmästare att binda demoner. Den mänsklige häxmästaren bor i ett stentorn i The Barrens, utom räckhåll för Alliansens och Hordens vanliga politik. Elever i felmagi kommer från Stormwind, Orgrimmar och Undercity för att lära sig av honom.",h="Ovanför Ratchet lär Strahad Farsan häxmästare att binda demoner.",kw={"the barrens","kabal","farsan","felhunter","gakin","ratchet","strahad","besvärjare","häxmästare"},ang={["class:Warlock"]="Som häxmästare kan du lära dig av Strahad hur man binder felhunters och frammanar springare från Nether.",["faction:Alliance"]="Gakin the Darkbinder skickar Alliansens häxmästare från Slaughtered Lambs kryptor till Kalimdor för att studera under Strahad.",["faction:Horde"]="Trots att Strahad föddes in i Alliansen samarbetar han med Hordens utövare i det neutrala Ratchet.",["race:Human"]="Som människa visar Strahad att mästare i mörka konster söker större makt bortom Stormwind."},sec={{t="Tornet ovanför Ratchet",b="Strahad Farsan håller till i ett stentorn på klipporna ovanför Ratchet. Den neutrala goblinhamnen låter honom utföra farliga besvärjelser utan att störas av Alliansens domare eller Hordens schamaner. Hans lärjungar samlas kring honom medan han studerar den virvlande Nether, avskild från striderna om områdena nedanför."},{t="Mästare på demonisk bindning",b="Strahad lärde sig på egen hand hur farligt det är att binda demoner. Hans första försök att binda en felhunter höll nästan på att kosta honom livet och gjorde honom försiktig och noggrann. Trots att han är människa har han vunnit respekt hos Gakin the Darkbinder i Stormwind och demonforskare i Undercity och Orgrimmar. Häxmästare från båda fraktionerna som vill befalla felhunters eller eldiga springare skickas till hans torn."}},faq={{q="Vem är Strahad Farsan?",a="Strahad Farsan undervisar häxmästare i ett stentorn ovanför Ratchet. Han ingår i Gakin the Darkbinders innersta krets i Stormwind, och häxmästare från båda fraktionerna söker hans skicklighet i demonbesvärjelser.",al={"strahads bakgrund","vem är strahad","information om strahad farsan"}},{q="Varför bor en mänsklig häxmästare i The Barrens?",a="Strahad bor ovanför Ratchet, en neutral hamn som drivs av Steamwheedle Cartel. Klipporna låter honom utföra farliga besvärjelser utanför Alliansens lagar och Hordens bevakning.",al={"varför är strahad i ratchet","människa i the barrens","strahads plats"}},{q="Varför besöker häxmästare från Horden Strahad?",a="Strahads skicklighet med demoner lockar häxmästare från Horden. Mentorer i Orgrimmar och Undercity erkänner hans kunskap om att binda demoner som felhunters och skickar lovande elever över havet för att studera hos honom.",al={"horden besöker strahad","kan horden prata med strahad","varför går orcher till strahad"}},{q="Vad hände med Strahad när han åkallade sin första felhunter?",a="Strahads första försök att binda en felhunter höll nästan på att kosta honom livet. Han överlevde nätt och jämnt, och prövningen lärde honom vilken precision som krävs för att kuva sådana magiätande rovdjur.",al={"strahads möte med felhunter","strahads bakgrund och felhunter"}},{q="Är Strahad släkt med Godrick Farsan?",a="Strahad och Godrick Farsan delar det ovanliga efternamnet Farsan, vilket antyder en familjeband. Strahad säger inget om sin familj och förblir hängiven sin mörka konst.",al={"koppling till godrick farsan","godrick farsans släkting","är strahad släkt med godrick"}},{q="Vilka är akolyterna vid hans torn?",a="Bland Strahads lärjungar finns Magaz, Fenrick och Wytula. De hjälper till att underhålla skyddande runor, förbereda besvärjelsecirklar och sköta tornets ritualer.",al={"strahads akolyter","akolyter i tornet i ratchet"}}},fx={b2638750={q="Vem står Strahad Farsan på?",a="Strahad förblir strikt neutral och håller sig utanför Alliansens och Hordens politiska gräl. Han bor ovanför goblinernas hamn Ratchet och behandlar utövare från båda fraktionerna lika. Hans lojalitet ligger hos mörk magi och hans medutövare, snarare än hos Stormwinds eller Orgrimmars fanor.",al={"strahad farsans fraktion","är strahad med alliansen eller horden","strahads lojalitet"}},["62896d38"]={q="Vad vill Strahad Farsan?",a="Strahad vill tänja på gränserna för demonframkallning och pröva sina medutövares förmåga. Han testar och vägleder ambitiösa häxmästare som vill bemästra mäktiga varelser som felhunters. Han ser till att de har viljestyrkan och kunskapen att binda varelser som en gång nästan tog hans eget liv.",al={"vad vill strahad","strahad farsans mål","strahads motiv"}},a370ddda={q="Vem är Strahad Farsan knuten till?",a="Strahad är en framstående medlem av Gakin the Darkbinders innersta krets och står nära andra mästare av skuggorna runt om i världen. I sitt torn ovanför Ratchet vakar han över sina egna akolyter, Magaz, Fenrick och Wytula, och tränar lovande demonframkallare som skickats till honom av mentorer från Ironforge, Stormwind, Orgrimmar och Undercity.",al={"strahad farsans kontakter","vem arbetar strahad med","strahads allierade"}}},fp="14,268,23.301.0,25.388.0,22.199.0,45.190.0,36.218.0,62.178.0,37.170.0,38.151.0"}
P.entries["npc:supervisor-raelen"] = {n="Supervisor Raelen",s="På Eastvale Logging Camp ser Supervisor Raelen till att timret förs vidare mot Stormwind. Hon leder arbetarna, följer de dagliga kvoterna och övervakar timmerförsörjningen.",h="På Eastvale Logging Camp ser Supervisor Raelen till att timret förs vidare mot Stormwind.",kw={"a bundle of trouble","eastvale","eastvale logging camp","elwynn forest","timmer","raelen","supervisor raelen","timmerkvoter"},ang={["faction:Alliance"]="Stormwind behöver timmer till sitt försvar och sina byggnader, så Raelens timmerkvanter är viktiga för kungarikets krigsinsats."},sec={{t="Hålla lägret i tid",b="Supervisor Raelen leder skogshuggarna vid Eastvale Logging Camp, nära Marshal Patterson och lägrets vagnar. Lägret ligger vid östra Elwynns utkant, nära Redridge Mountains, där arbetet för med sig en del problem. Raelen samordnar arbetslagen och håller dem fokuserade på sina kvoter trots farorna i skogarna runt omkring. Hon ser till att det insamlade timret bearbetas, buntas ihop och skickas vidare mot Stormwind."}},faq={{q="Vem är Supervisor Raelen?",a="Supervisor Raelen övervakar skogsarbetarna vid Eastvale Logging Camp i östra Elwynn Forest. Hon leder deras arbete och ser till att timmerkvoterna hålls enligt tidsplanen.",al={"vem är raelen","raelen i elwynn","eastvales arbetsledare"}},{q="Var hittar jag Supervisor Raelen?",a="Supervisor Raelen finns i mitten av Eastvale Logging Camp, nära de lastade timmervagnarna och Marshal Patterson.",al={"var finns raelen","supervisor raelens plats","hitta raelen"}},{q="Varför behöver Supervisor Raelen hjälp av äventyrare?",a="Det kan vara farligt att samla timmer vid skogsbrynet. När vilda djur eller andra störningar plågar arbetarna kan avverkade timmerbuntar bli övergivna eller spridas bland träden.",al={"raelen uppdrag","uppdraget a bundle of trouble","varför hjälpa raelen"}},{q="Vilken roll spelar Eastvale Logging Camp i Elwynn Forest?",a="Eastvale Logging Camp är den största skogsavverkningen i östra Elwynn Forest. Timret därifrån bidrar till återuppbyggnad och underhåll i Stormwind och närliggande bosättningar.",al={"vad är eastvale","eastvales roll inom skogsavverkning","varför är eastvale viktigt"}}},fx={["5e9ae7c9"]={q="Vem står Supervisor Raelen på?",a="Supervisor Raelen är lojal mot kungariket Stormwind och Alliansen. Hon sköter kungarikets timmerverksamhet vid Eastvale Logging Camp och arbetar direkt med Stormwinds vakter och arbetare för att hålla huvudstaden försedd med timmer.",al={"raelens fraktion","vem tjänar supervisor raelen","är raelen med alliansen"}},["93ff040d"]={q="Varför är Supervisor Raelen här i Eastvale?",a="Raelen övervakar det dagliga skogsarbetet vid Eastvale Logging Camp. Hon leder de lokala arbetarna, håller uppsikt över timmervagnarna och ser till att trädfällningen uppfyller Stormwinds kvoter. På så sätt håller hon verksamheten igång trots farorna i vildmarken runt omkring.",al={"varför är supervisor raelen här","raelens syfte i eastvale","vad gör raelen här"}},e5fd1368={q="Vem är Supervisor Raelen knuten till?",a="Raelen arbetar nära Stormwinds lokala myndigheter vid Eastvale, särskilt Marshal Patterson, som ansvarar för lägrets försvar. Hon leder också lägrets arbetsstyrka av lokala bönder och skogshuggare.",al={"raelens kontakter","vem arbetar raelen med","supervisor raelens allierade"}}},fp="17,170,28.407.0,25.161.0,35.111.0,54.181.0,63.161.0"}
P.entries["npc:suzetta-gallina"] = {n="Suzetta Gallina",s="På Gallina Winery i Stormwind City sköter Suzetta Gallina familjens vinverksamhet.",h="På Gallina Winery i Stormwind City sköter Suzetta Gallina familjens vinverksamhet.",kw={"gallina winery","stormwinds kanaler","stormwindvin","suzetta gallina","reklam för vinbutik"},ang={["faction:Alliance"]="Som en alliansresenär som återvänder från farorna i Elwynn eller Westfall påminner ett besök i Suzettas butik om ett fredligt liv i huvudstaden."},sec={{t="En smak av kanalerna",b="Suzetta Gallina hjälper till att driva Gallina Winery längs Stormwinds kanaler. Butiken erbjuder viner som importeras från hela kungariket eller tillverkas där. Hennes familj förser tavernor, adelsfolk och vanligt folk med vin. Suzetta har ingen roll i den höga politiken, men hennes arbete håller huvudstadens handel i gång genom oroliga tider."}},faq={{q="Vem är Suzetta Gallina?",a="Suzetta Gallina tillhör familjen som driver Gallina Winery längs kanalerna i Stormwind City.",al={"suzetta gallina","vem är suzetta","kvinna på gallina winery"}},{q="Var hittar jag Suzetta Gallina?",a="Hitta Suzetta inne på Gallina Winery, längs kanalerna mellan Trade District och Cathedral Square i Stormwind City.",al={"suzetta gallinas plats","var är suzetta","gallina winery plats"}},{q="Har Suzetta något arbete åt resande?",a="Suzetta erbjuder inget arbete direkt. Hennes bror Renato delar ut Wine Tickets. Ta med en till henne på Gallina Winery för att få en flaska av familjens särskilda pinot noir utan kostnad.",al={"suzettas uppdrag","gallina vinuppdrag","reklam för vinbutik"}}},fx={f0d37e75={q="Vem står Suzetta Gallina på?",a="Suzetta Gallina är en lojal medborgare i Alliansen. Hon och hennes familj bor och arbetar i lugn och ro mitt i Stormwind City, där de förser huvudstadens värdshusvärdar, adelsfolk och vanligt folk med sina varor.",al={"suzetta gallinas fraktion","är suzetta gallina med alliansen","vem tjänar suzetta"}},["44c42184"]={q="Vad vill Suzetta Gallina?",a="Suzetta vill att familjens vinhandel ska blomstra. Tillsammans med sin släkt sköter hon Gallina Winery och ser till att deras fat och flaskor hittar ivriga köpare runt om i staden. Hon sprider också ryktet om deras årgångsviner bland törstiga resenärer.",al={"suzetta gallinas mål","vad vill suzetta","vad gör suzetta gallina"}},["290e58c2"]={q="Varför är Suzetta Gallina här i Stormwind?",a="Suzetta håller till i Canal District eftersom Gallina Winery, centrum för familjens handel, ligger där. Härifrån hjälper hon till att sköta verksamheten och har nära till Stormwinds livliga värdshus och handelsleder.",al={"varför är suzetta gallina här","varför är suzetta i kanalerna","suzetta gallinas plats i berättelsen"}},c1c3d801={q="Vem är Suzetta Gallina knuten till?",a="Suzetta tillhör familjen Gallina, som säljer vin. Tillsammans med sin släkt arbetar hon i familjens butik med att framställa och sälja årgångsviner i hela Stormwind City.",al={"suzetta gallinas familj","vem är suzetta släkt med","gallina winerys familj"}}},fp="15,87,21.268.0,23.97.0,33.123.0,42.189.0"}
P.entries["npc:sven-yorgen"] = {n="Sven Yorgen",s="Sven Yorgen är en sörjande bonde som slagit läger vid norra kanten av The Hushed Bank i västra Duskwood, tillsammans med sin följeslagare Lars. Han överlevde den brutala massakern på sin familj vid The Yorgen Farmstead och drivs nu obevekligt av viljan att ta reda på vem som ödelade hans hem och utkräva hämnd.",h="Sven Yorgen är en sörjande bonde som slagit läger vid norra kanten av The Hushed Bank i västra Duskwood...",kw={"dark riders","duskwood","the hushed bank","jitters","lars","morbent fel","scythe of elune","sven yorgen","the yorgen farmstead"},ang={["class:Paladin"]="Svens sorg och törst efter rättvisa ger paladiner en tydlig uppgift: att hämnas oskyldigt blod och rena marken där hans familj levde från de odöda som fortfarande hemsöker den.",["faction:Alliance"]="Sven visar den tragiska kollapsen av landsbygdslivet i kungarikets gränstrakter, där vanliga undersåtar lämnas utan skydd mot mörk magi och skuggornas fasor."},sec={{t="Ett liv i spillror",b="Sven föddes före det första kriget och minns tiden innan regionen sveptes in i mörker efter Medivhs fall. I åratal brukade han jorden vid The Yorgen Farmstead i södra Duskwood tillsammans med sin fru och sina barn. Det stillsamma livet tog plötsligt slut när mystiska Dark Riders anföll gården medan han var borta, slaktade hans familj och förvandlade gården till en gravplats."},{t="Hämnd från The Hushed Bank",b="Sven kunde inte återvända till ruinerna av sitt hem och slog sig därför ner i ett avskilt gömställe vid The Hushed Bank tillsammans med sin vän Lars. Han litar inte på främlingar och kräver att resande bevisar sin lojalitet innan han berättar om sin börda. Sven såg en skuggande gestalt nära den ödelagda gården och blev övertygad om att inkräktaren antingen låg bakom massakern eller hade band till de ondskefulla ryttarna som slog hans värld i spillror."},{t="Sanningen kommer fram",b="Den skuggiga gestalten som smyger omkring på Svens ägor visar sig vara Jitters, en kringströvande luffare vars klantighet oavsiktligt ledde Dark Riders till Duskwood när de sökte efter Scythe of Elune. Jitters utdelade inte de dödande huggen, men hans handlingar släppte lös mardrömmen som utplånade familjen Yorgen och riktade Svens vrede mot de mörka krafter som hemsöker Raven Hill och nekromantikern Morbent Fel."}},faq={{q="Vem är Sven Yorgen?",a="Sven Yorgen är en mänsklig bonde som bor i ett litet läger vid norra kanten av The Hushed Bank i Duskwood. Efter att hans familj massakrerades på gården ägnade han sitt liv åt att söka hämnd på de skyldiga.",al={"sven yorgen","vem är sven","sven berättelse"}},{q="Vad hände med Svens familj?",a="Medan Sven var hemifrån kom skräckinjagande svartklädda gestalter, kända som Dark Riders, till The Yorgen Farmstead. De letade efter en mäktig artefakt och slaktade skoningslöst Svens fru och barn. Sedan lämnade de marken besmittad av odöda.",al={"tragedin vid yorgen farmstead","sven familj död","vad hände med svens gård"}},{q="Varför gömmer sig Sven vid The Hushed Bank?",a="Efter massakern övergav Sven den förstörda gården. Han slog upp ett tillfälligt läger vid flodstranden tillsammans med Lars för att hålla sig gömd för de odöda som strövar omkring i västra Duskwood, samtidigt som han planerar sin hämnd.",al={"var finns sven","svens läger","varför har sven slagit läger"}},{q="Vem är den skuggiga gestalten Sven såg?",a="Sven vet inte. Han såg en skuggande gestalt nära ruinerna av sitt hem och ber pålitliga resande hjälpa honom ta reda på vem det var och om gestalten bidrog till familjens död.",al={"skuggig gestalt sven","vem var vid yorgen farmstead","skuggig gestalt duskwood"}},{q="Varför anföll Dark Riders Svens gård?",a="Dark Riders sökte efter Scythe of Elune i Duskwood, en uråldrig artefakt med enorm kraft. Jakten på reliken förde dem rakt över Svens ägor och lämnade död i deras spår.",al={"varför anfaller dark riders","vad letade dark riders efter","scythe of elune sven"}},{q="Hur länge har Sven bott i Duskwood?",a="Sven är gammal nog att minnas Duskwood innan landet föll i mörker. Det betyder att han bodde i området före det första kriget, när skogen fortfarande var ljus och fridfull och Darkshire kallades Grand Hamlet.",al={"svens ålder","hur gammal är sven","sven före mörkret"}}},fx={be3c9ddb={q="Vem står Sven Yorgen på?",a="Sven är lojal mot Alliansen, även om sorgen och vreden driver honom långt mer än någon ed till Stormwind. Han har förlorat sitt hem och sin familj till fasorna som härjar i Duskwood. Därför samarbetar han med alla pålitliga äventyrare från Alliansen som är villiga att ta till vapen mot de mörka krafter som hemsöker skogen.",al={"sven yorgens fraktion","är sven med alliansen","vem kämpar sven för"}},d6fc644e={q="Vad vill Sven Yorgen?",a="Sven vill ha hämnd. Efter att de mystiska Dark Riders slaktat hans hustru och barn vid The Yorgen Farmstead svor han att hämnas på de skyldiga. Han söker identiteten på en skuggfigur som setts dröja sig kvar nära hans förstörda hem och kräver att de nekromantiska hot som fördärvar landet, som Morbent Fel, ska förgöras.",al={"vad vill sven","sven yorgens mål","varför behöver sven hjälp"}},["0ba4293f"]={q="Vem är Sven Yorgen knuten till?",a="Sven delar läger med Lars, en trofast följeslagare som hjälper honom ute i vildmarken. Hans jakt på hämnd knyter honom också till Jitters tragiska mysterium, eftersom Sven såg Jitters smyga omkring vid hans gård. Den ställer honom dessutom direkt mot nekromantikern Morbent Fel och de gåtfulla Dark Riders från Deadwind Pass.",al={"sven yorgens allierade","vem känner sven","svens kontakter"}}},fp="11,208,16.362.0,30.392.0,20.380.1,19.208.0,31.209.0,38.184.0,35.208.1,43.177.1,36.176.0"}
P.entries["npc:sylvanas-windrunner"] = {n="Sylvanas Windrunner",s="Lady Sylvanas Windrunner är Banshee Queen och de Fördömdas högsta härskare. Hon håller hov i Undercity, under ruinerna av Lordaeron. En gång var hon Silvermoons tappra Ranger-General. Arthas Menethil dödade henne och väckte henne till odödligt liv, men hon bröt sig fri från Lich Kings grepp. Nu är hon allierad med Thralls Horde för att överleva. Hon kämpar hängivet för en framtid åt sina viljestarka odöda och för att hämnas på Scourge.",h="Lady Sylvanas Windrunner är Banshee Queen och de Fördömdas högsta härskare.",kw={"arthas","banshee queen","dark lady","de fördömda","lordaeron","ranger-general","sylvanas","undercity","windrunner"},ang={["faction:Horde"]="Archdruid Hamuul Runetotems stöd och Thralls medkänsla gjorde att de Fördömda togs upp i Horde. Många orcher och troll betraktar ändå Sylvanas och hennes hov med fortsatt misstänksamhet.",["race:Undead"]="För de Fördömda är Dark Lady en befriare och beskyddare. Tack vare henne har de fri vilja och ett befäst hem i stället för att tanklöst tjäna Scourge."},sec={{t="Ranger-Generals fall",b="I livet var Lady Sylvanas Silvermoons hyllade Ranger-General och ledde försvaret av Quel'Thalas under Tredje kriget. När prins Arthas Menethil förde in Scourge i högälvernas kungarike för att nå Sunwell kämpade Sylvanas hårt för att hejda hans framfart. Hennes motstånd gjorde Arthas rasande, och han mördade henne utan att ge henne en värdig död. Han slet själen ur hennes kropp och förvandlade henne till en hämndlysten banshee. Hon tvingades tjäna Scourge och hjälpa till att slakta sitt eget folk."},{t="De Fördömdas uppgång",b="När Lich Kings magiska grepp försvagades efter Tredje kriget bröt Sylvanas sig fri från hans välde och återtog sin bevarade kropp. Hon samlade andra odöda som hade återfått sin fria vilja och störtade dreadlords som ockuperade ruinerna av Lordaeron. Hon kallade sitt folk de Fördömda och grundade Undercity under jord. Hennes folk levde isolerat och utsatt för hot från resterna av Scourge, fanatiska Scarlet Crusade och misstänksamma människokungadömen. Därför slöt hon en osäker allians av nödvändighet med krigshövding Thrall och Horde."}},faq={{q="Vem är Sylvanas Windrunner?",a="Hon är de Fördömdas härskarinna och håller hov i Royal Quarter i Undercity. I livet var hon Quel'Thalas alviska Ranger-General. Efter att Arthas Menethil dödat henne och väckt henne till odödligt liv bröt hon sig loss från Scourge och ledde de odöda som återfått sin fria vilja.",al={"banshee queen","vem är dark lady","lady sylvanas","undercitys ledare"}},{q="Varför knöt Sylvanas de Fördömda till Horde?",a="Alliansens levande folk föraktar de Fördömda och ser dem bara som monster. Sylvanas behövde starka bundsförvanter för att säkra den unga nationens överlevnad. Scourge och Scarlet Crusade omringade dem i Lordaeron. Därför bad hon krigshövding Thrall om att få ansluta sig till Horde.",al={"varför är odöda med i horde","de fördömdas allians med horde","sylvanas och thralls pakt"}},{q="Hur bröt Sylvanas sig fri från Lich King?",a="Efter Tredje kriget började Lich Kings psykiska kraft sina, och hans järngrepp om Scourge bröts upp. Sylvanas var en av de första mäktiga andarna som återfick sin självständighet. Hon återtog genast sina dödliga kvarlevor och vände sin vrede mot Arthas.",al={"hur flydde sylvanas från arthas","sylvanas fria vilja","lich kings kontroll"}},{q="Vad är Sylvanas främsta mål?",a="Framför allt vill Sylvanas hämnas grundligt på Arthas Menethil och Scourge för att de förstörde hennes hemland och förslavade hennes själ. Samtidigt strävar hon efter att stärka Undercity och skapa en trygg, permanent fristad åt de Fördömda i Lordaeron.",al={"vad vill sylvanas","sylvanas drivkraft","dark ladys mål"}}},fx={["830cd396"]={q="Varför är Sylvanas Windrunner i Undercity?",a="Sylvanas styr Forsaken från Royal Quarter, djupt inne i Undercity, den underjordiska labyrint som grävts ut under ruinerna av Lordaerons huvudstad. Efter att ha erövrat huvudstaden från Scourge och Dreadlords gjorde hon den till fäste för sina viljestarka odöda. Härifrån leder hon försvaret av Tirisfal Glades mot Scarlet Crusade och resterna av Scourge, samtidigt som hon arbetar för en trygg framtid för sitt folk i Eastern Kingdoms.",al={"varför är sylvanas här","varför är sylvanas i undercity","varför befinner sig sylvanas där"}},de176d94={q="Vilka är Sylvanas Windrunner allierad med?",a="Sylvanas är Forsakens högsta ledare och leder dem i en allians av bekvämlighet med Warchief Thralls Horde. Vid sitt hov bevakas och rådges hon av personer som dreadlorden Varimathras, som svor henne trohet efter Lordaerons fall. Utanför sitt odöda rike har hon ansträngda politiska band till orcherna och taurerna, som släppte in hennes folk i Horden trots kvarvarande ömsesidig misstänksamhet.",al={"sylvanas allierade","vem är sylvanas knuten till","sylvanas windrunners kontakter"}},aee4c591={q="Varför är Sylvanas Windrunner berömd?",a="Före sin död var Sylvanas vördad som Silvermoons Ranger-General och hyllad för sitt modiga försvar av Quel'Thalas mot Scourge. I dag fruktas hon i hela Azeroth som Banshee Queen. Efter att ha utstått avrättning och bansheeplågor under Prince Arthas hand återtog hon sin dödliga kropp och ryckte en hel fraktion odöda ur Lich Kings psykiska grepp. Hennes dödliga bågskytte, bansheeskrik och hänsynslösa list får både levande och döda att akta sig för henne.",al={"varför fruktas sylvanas","banshee queens berömmelse","varför är sylvanas berömd"}}},fp="19,308,26.420.0,20.497.0,27.240.0,51.280.0,47.248.0,32.216.0"}
P.entries["npc:syral-bladeleaf"] = {n="Syral Bladeleaf",s="Syral Bladeleaf är en nattalv i Dolanaar på Teldrassil och tjänstgör som kontaktperson för Council of the Forest. Hon vägleder unga äventyrare från Shadowglen till lokala vårdare, örtkunniga och äldste som vakar över kronans sköra grenar.",h="Syral Bladeleaf är en nattalv i Dolanaar på Teldrassil och tjänstgör som kontaktperson för Council of the...",kw={"bladeleaf","council of the forest","denalan","dolanaar","äldste bladeleaf","syral","teldrassil"},ang={["profession:Herbalism"]="Syral samarbetar nära med lokala naturkunniga och leverantörer av örter. Hon skickar resenärer för att bistå med botanisk forskning vid Lake Al'Ameth och se till att färska elixir når de äldste.",["race:NightElf"]="För unga nattalver som lämnar Shadowglens avskilda gravhögar är Syral Bladeleaf en av de första rösterna från Dolanaars lokala och naturvårdande ledarskap."},sec={{t="En röst i Dolanaar",b="Syral Bladeleaf står nära Dolanaars hjärta och hjälper till att samordna byns angelägenheter i skuggan av Teldrassils krona. På uppdrag av Council of the Forest visar hon nyanlända nattalver till ledare och örtkunniga i byn och den närliggande vildmarken. Med hennes hjälp får resenärer kontakt med botanisten Denalan vid Lake Al'Ameth och fyller på förråden åt byns äldste."},{t="Band till byn",b="Syral arbetar på uppdrag av Council of the Forest i Dolanaar. Hennes ansvar är inriktat på byns välmående: läkande elixir ska nå dem som behöver dem, och störningar i det lokala ekosystemet ska få snabb uppmärksamhet."}},faq={{q="Vem är Syral Bladeleaf?",a="Syral Bladeleaf är en nattalv i Dolanaar som förmedlar Council of the Forests direktiv och hjälper nyanlända äventyrare att bistå skogssamhällena i trakten.",al={"vem är syral","syral bladeleaf historia","syral dolanaar"}},{q="Var hittar man Syral Bladeleaf?",a="Hon finns i Dolanaar, Teldrassils centrala bosättning strax sydväst om Shadowglen, längs huvudvägen.",al={"syral bladeleaf plats","var är syral","syral karta"}},{q="Vilka uppgifter ger hon äventyrare?",a="Syral skickar resenärer för att hjälpa botanisten Denalan vid Lake Al'Ameth, ordnar leveranser av örtelixir till de äldste och visar äventyrare uppgifter som värnar Teldrassils naturliga balans.",al={"syral bladeleaf uppdrag","vad vill syral","syrals uppgifter"}}},fx={["39456ef3"]={q="Vem står Syral Bladeleaf på?",a="Syral tjänar Darnassus och Alliansen. Hon är stationerad i Dolanaar och arbetar direkt på uppdrag av Council of the Forest. Hon hjälper till att skydda den lokala vildmarken och dess väktare mot Teldrassils växande problem.",al={"syral bladeleafs fraktion","vem tjänar syral bladeleaf","syral bladeleafs lojalitet"}},["47edbb6a"]={q="Vad vill Syral Bladeleaf?",a="Syral vill se att Skogsrådets vilja blir verklighet. Hon förmedlar deras direktiv till dugliga äventyrare, söker hjälp åt närliggande allierade som Denalan och arbetar för att hålla den växande korruptionen i Teldrassil under kontroll.",al={"vad vill syral bladeleaf","syral bladeleafs mål","syral bladeleafs motiv"}},["7fd35b53"]={q="Varför är Syral Bladeleaf i Dolanaar?",a="Syral är stationerad i Dolanaar för att fungera som en viktig kontakt för Skogsrådet. Från den centrala bosättningen kan hon enkelt rekrytera förbipasserande resenärer och unga night elves för att ta hand om trädgrenarnas behov och stödja de lokala vårdarna.",al={"varför är syral bladeleaf här","varför är syral bladeleaf i dolanaar","varför är syral i dolanaar"}}},fp="15,239,19.351.0,19.206.0,23.142.0,35.124.0,42.146.0"}
P.entries["npc:syurna"] = {n="Syurna",s="Syurna är en Night Elf-tränare för rogues, som håller till bland lövverket i Cenarion Enclave i Darnassus. Hon vägleder blivande spejare, spioner och hemliga agenter bland kaldorei och skickar nytränade rogues på uppdrag som prövar deras smygförmåga och list.",h="Syurna är en Night Elf-tränare för rogues, som håller till bland lövverket i Cenarion Enclave i Darnassus.",kw={"cenarion enclave","darnassus","destiny calls","kaldorei","rogue-tränare","syurna","teldrassil"},ang={["class:Rogue"]="Som Night Elf-rogue har du Syurna som en av dina främsta lärare i Darnassus. Hon lär dig grunderna i smygande, gifter och stridsprecision medan du får mer erfarenhet.",["race:NightElf"]="Syurna förkroppsligar kaldoreis spejartradition: tyst och rovdjurslik skyddar den deras skogshem från skuggorna i stället för genom öppen strid."},sec={{t="En spejare bland träden",b="Medan Darnassus hyllar Sentinels öppna krigiska styrka och The Sisterhood of Elunes andliga visdom har kaldorei alltid förlitat sig på skuggor och smygande. I Cenarion Enclave tränar och vägleder Syurna dem som går en osedd väg. Hon lär rogues konsten att undvika upptäckt, dyrka upp lås och utdela dödliga slag, så att Darnassus har skarpa ögon och ljudlösa klingor till Teldrassils försvar."},{t="Listens prövningar",b="Syurna ger inte bara teoretiska råd i tryggheten vid enklaven, utan prövar också unga agenters beredskap. Genom uppgifter som att skicka lovande nykomlingar på mer krävande fältarbete testar hon om en agent har de instinkter som krävs för att överleva utanför världsträdets grenar och tjäna Alliansen i farliga gränstrakter."}},faq={{q="Vem är Syurna?",a="Syurna är en Night Elf-tränare för rogues, stationerad i Cenarion Enclave i Darnassus. Hon erbjuder stridsträning, förmågor och vägledning åt rogueäventyrare som tjänar Alliansen.",al={"syurna darnassus","vem är syurna","night elf-tränare för rogues"}},{q="Var hittar jag Syurna i Darnassus?",a="Hon finns i Cenarion Enclave, bland träden och paviljongerna tillsammans med andra mentorer som verkar i skuggorna.",al={"var finns syurna","syurnas plats","plats för rogue-tränare i darnassus"}},{q="Varför finns en rogue-tränare i Cenarion Enclave?",a="Även om Cenarion Enclave främst förknippas med druidism och natur tränar Night Elf-spejare och hemliga stigfinnare ofta i tysthet längs dess skogskanter, avskilda från Temple of Elunes och Warrior's Terraces offentliga prakt.",al={"varför finns en rogue-tränare i enklaven","rogue i cenarion enclave"}},{q="Vilka uppdrag erbjuder Syurna?",a="Syurna medverkar i rogues tidiga utveckling och skickar nybörjare som visat vad de går för i Shadowglen ut i den större världen för att vässa sina färdigheter, bland annat genom uppdrag som Destiny Calls.",al={"syurnas uppdrag","uppdraget destiny calls"}}},fx={["4fb7093b"]={q="På vilken sida står Syurna?",a="Syurna står stadigt på Darnassus och Alliansens sida. Som en night elf-rövare verksam i huvudstaden erbjuder hon sin expertis till dem som är lojala mot Kaldoreis sak och vägleder blivande spejare, tjuvar och lönnmördare i att finslipa sitt diskreta hantverk.",al={"syurnas fraktion","vem tjänar syurna","syurna och alliansen"}},d409bc2a={q="Vad vill Syurna?",a="Syurnas uppgift är att undervisa och vägleda lovande rövare som kommer till Darnassus. Hon håller utkik efter dem med skarpa instinkter och god smygförmåga och leder dem genom träning och uppdrag så att Kalimdors skuggor kan skydda night elves.",al={"syurnas mål","vad försöker syurna göra","syurnas syfte"}}},fp="6,183,23.367.0,16.257.0,14.134.0,45.113.0,47.217.0,30.152.0"}
P.entries["npc:tabetha"] = {n="Tabetha",s="Tabetha är en tillbakadragen och mäktig mänsklig magiker som bor djupt inne i Dustwallow Marsh, på en avskild gård i The Quagmire. Långt från Dalarans och Theramores politik undervisar hon blivande besvärjare och hjälper dem som vill bemästra kraftfulla arkaniska och ockulta reliker.",h="Tabetha är en tillbakadragen och mäktig mänsklig magiker som bor djupt inne i Dustwallow Marsh, på en avskild...",kw={"dustwallow marsh","magikeruppdrag","menara voidrender","orb of orahil","the quagmire","tabetha","tabetha's farm"},ang={["class:Mage"]="Tabetha är en viktig mentor för magiker på mellannivå. Hon prövar dina kunskaper i arkaniska ritualer och skickar dig till farliga platser som Uldaman för att vässa ditt hantverk.",["class:Warlock"]="Tabetha utövar arkana konster, men hennes djupa förståelse för magiska reliker gör henne till en oumbärlig vägvisare när du hanterar farliga föremål som Infernal Orb och Orb of Orahil."},sec={{t="Eremit i The Quagmire",b="Undangömd i det regnvåta landskapet i Dustwallow Marsh, norr om Stonemaul Ruins, bor Tabetha i en avskild koja tillsammans med sina lärlingar. Omgiven av alkemiska flaskor och gamla böcker har hon medvetet valt ensamheten framför Eastern Kingdoms akademiska hierarkier. Trots sitt avlägsna läge är hennes mästerskap inom arkana konster så välkänt att besvärjare från hela Kalimdor trotsar både bestar och träsk för att söka hennes vägledning."},{t="En neutral mentor",b="Tabetha står tydligt utanför fraktionskonflikterna. Trots att hon föddes som människa avvisar hon varken lärlingar från alliansen eller horden som visar viljan att lära sig. Hon undervisar magiker och hjälper häxmästare med farliga bindningar, som Orb of Orahil. Hennes förflutna knyter henne till personer som Menara Voidrender och visar på en lång historia av esoterisk magi som sträcker sig bortom enkel fraktionstillhörighet."}},faq={{q="Var hittar jag Tabetha?",a="Tabetha bor i en avskild koja på Tabetha's Farm, djupt inne i The Quagmire i västra Dustwallow Marsh, strax norr om Stonemaul Ruins.",al={"tabethas plats","var finns tabetha","tabethas gård karta"}},{q="Är Tabetha fientlig mot spelare i horden?",a="Nej. Trots att Tabetha är människa är hon neutral. Hon undervisar lärlingar och hjälper besvärjare från både horden och alliansen utan åtskillnad.",al={"är tabetha endast för alliansen","kan horden prata med tabetha","tabethas fraktion"}},{q="Varför söker magiker och häxmästare upp henne?",a="Tabetha har sällsynt kunskap om arkaniska ritualer, magiska fokus och bindningsriter. Magiker rådfrågar henne för att bemästra hantverket och klara kraftprov, medan häxmästare söker hennes expertis för att rena eller binda kraftfulla föremål som Orb of Orahil.",al={"varför besöka tabetha","tabethas klassuppdrag","orb of orahil tabetha"}},{q="Vilken koppling har hon till Menara Voidrender?",a="Tabetha har en lång gemensam historia med Menara Voidrender. Deras vägar har skilts åt, men deras gemensamma förståelse för mäktiga reliker och bindningsmagi förenar dem trots att de lever i varsin avskild boning.",al={"tabetha och menara","menara voidrender historia"}}},fp="7,275,22.455.0,16.418.0,25.150.0,36.149.0,39.239.0,44.205.0"}
P.entries["npc:tai-jin"] = {n="Tai'jin",s="I Razor Hill Barracks vägleder Tai'jin unga Darkspear-präster i sina andliga traditioner. Hon lär ut balansen mellan ljus och skugga och riter som Hex of Weakness.",h="I Razor Hill Barracks vägleder Tai'jin unga Darkspear-präster i sina andliga traditioner.",kw={"darkspear","durotar","hex of weakness","prästtränare","razor hill","tai'jin"},ang={["class:Priest"]="Som Horde-präst under utbildning i Durotar lär du dig av Tai'jin innan du beger dig till Orgrimmars ståtliga salar.",["race:Troll"]="Som ung Darkspear-troll kan du lära dig särskilda besvärjelser av Tai'jin, däribland Hex of Weakness."},sec={{t="Prästinna i Razor Hill",b="Tai'jin vägleder unga präster från Razor Hill Barracks när de ger sig ut i Durotar. Här vänder sig orcher främst till shamanism eller häxmästeri, medan Darkspear-troll för med sig sin gemenskap med andar och loa till Horde. Tai'jin lär ut prästerskapets grunder, balansen mellan ljus och skugga och trollkulturens andliga arv."}},faq={{q="Var hittar jag Tai'jin?",a="Tai'jin finns på bottenvåningen i Razor Hill Barracks, i centrala Durotar, intill andra klasstränare.",al={"tai'jins plats","var finns tai'jin","tai'jin razor hill"}},{q="Vad lär Tai'jin ut?",a="Tai'jin lär nya präster besvärjelser, grader och förmågor allt eftersom de får erfarenhet, däribland grundläggande undervisning för trollaspiranter.",al={"tai'jin tränare","vad tränar tai'jin","prästbesvärjelser razor hill"}},{q="Varför finns en trollpräst i en orchbosättning?",a="Razor Hill utbildar unga Horde-äventyrare som lämnar Valley of Trials och Sen'jin Village. Eftersom orcher inte utövar prästerskapets konster för Tai'jin Darkspears andliga traditioner till bosättningen.",al={"varför är tai'jin i razor hill","troll i razor hill barracks"}},{q="Vilka särskilda riter lär Tai'jin trollpräster?",a="Tai'jin vägleder Darkspear-präster genom inledande andliga riter, däribland Hex of Weakness, som kanaliserar förfäders förbannelser.",al={"hex of weakness-uppdrag","tai'jins uppdrag"}}},fx={["5b5c447a"]={q="Vem är Tai'jin?",a="Tai'jin är en prästtränare bland Darkspear-djungeltrollen, stationerad i barackerna i Razor Hill. Hon ägnar sig åt att vägleda dem som kanaliserar andliga och gudomliga krafter och undervisar Hordens unga akolyter, särskilt troll- och odöda präster, i andliga konster, böner och traditionella trollriter.",al={"taijins identitet","vem är taijin","taijins bakgrund"}},["1746c020"]={q="På vilken sida står Tai'jin?",a="Tai'jin är lojal mot Darkspear-stammen och Horden. Stationerad i Durotar tillsammans med orc-krigare och schamaner tjänar hon Högste hövding Thralls förenade styrkor och ser till att andliga utövare är redo att försvara Hordens territorium.",al={"taijins fraktion","vem tjänar taijin","taijins lojalitet"}},dfe85d14={q="Vad vill Tai'jin?",a="Tai'jin vill vägleda novispräster i att förstå sina andliga gåvor och fördjupa sin hängivenhet. Hon ger blivande akolyter i uppgift att visa sin disciplin, meditation och gemenskap med andliga krafter, så att de kan stödja sina allierade i Durotar och bortom på rätt sätt.",al={"vad vill taijin","taijins mål","taijins syfte"}},ab897349={q="Vilka band har Tai'jin?",a="Som andlig mentor i Razor Hill har Tai'jin nära band till Darkspear-trollen, som leds av Sen'jins arv, och till den lokala Hordegarnisonen under Orgrimmars befäl. Hon arbetar tillsammans med andra tränare och försvarare i Durotar för att fostra starka och trofasta akolyter.",al={"taijins band","taijins kontakter","vilka är taijins allierade"}}},fp="7,180,23.351.0,25.110.0,24.130.0,53.202.0,58.134.0"}
P.entries["npc:taiga-wisemane"] = {n="Taiga Wisemane",s="Taiga Wisemane är en taurenäldste som bor i Shadowprey Village vid Desolaces karga västkust. Han håller uppsikt över demoniska intriger i ödemarken och försöker stoppa Burning Blade-kulten som slagit sig ned i området. Han skickar Horde-hjältar för att störa demoniska ritualer och försegla öppna portaler innan Burning Legion vinner mark.",h="Taiga Wisemane är en taurenäldste som bor i Shadowprey Village vid Desolaces karga västkust.",kw={"burning blade","demon box","desolace","hand of iruxos","mannoroc coven","shadowprey village","taiga wisemane","thunder axe fortress"},ang={["class:Warlock"]="Häxmästare kan finna Taigas förståelse av Hand of Iruxos anmärkningsvärd. Han använder den mörka relikens egen resonans för att få demoniska portaler att kollapsa, i stället för att driva bort dem med heliga riter.",["faction:Horde"]="Taiga ger viktig vägledning åt Horde-hjältar som färdas genom Desolace och ser till att Shadowprey Village förblir skyddad från demonernas intrång.",["race:Tauren"]="För taurenresenärer står Taiga för plikten att läka och skydda Kalimdor från onaturlig demonisk pest. Han kämpar mot det mörka arvet som har satt sina spår i Desolace."},sec={{t="Ett vakande öga i Shadowprey",b="Shadowprey Village är främst en Darkspear-trollby där invånarna fiskar, undangömd intill havet. Men Taiga Wisemane har slagit sig ned där för att bevaka de mörka besvärjelser som rör sig genom Desolace. Han är väl medveten om den andliga förruttnelse som tränger ned i jorden och håller blicken fäst österut, där skuggkulter och demoniska rester frodas bland forntida ruiner."},{t="Att hejda den demoniska flodvågen",b="Burning Blade-kulten är aktiv i Thunder Axe Fortress och experimenterar med mörka artefakter för att utöka sitt inflytande. Taiga inser faran för alla som bor i Desolace och skickar dugliga äventyrare att infiltrera fästningen och hämta Demon Box, en ockult kista som innehåller Hand of Iruxos. Med detta hårda slag vill han beröva kulten dess främsta verktyg för att slita upp slöjan mellan världarna."},{t="Att försegla Coven-portalerna",b="Att säkra Hand of Iruxos är bara första steget i Taigas plan. Längre söderut, vid Mannoroc Coven, har Burning Blade redan slitit upp aktiva demoniska revor. Taiga vänder den mörka kraften mot dess skapare och skickar betrodda hjältar att leda artefaktens energi rakt in i portalerna. På så vis stängs förbindelserna innan Burning Legion kan skicka förstärkningar till hjärtat av Kalimdor."}},faq={{q="Vem är Taiga Wisemane?",a="Taiga Wisemane är en taurenäldste som vistas i Shadowprey Village på Desolaces västkust. Han är rådgivare och uppdragsgivare, och ägnar sig åt att spåra och motverka demoniska ritualer som Burning Blade-kulten utför i området.",al={"vem är taiga","taiga wisemane historia","taiga shadowprey"}},{q="Varför bor en tauren i Shadowprey Village?",a="Shadowprey är främst en trollby, men också Hordes viktigaste utpost längs Desolaces kust. Taiga stannar där för att hålla vakt över den ödsliga ödemarken och värva Horde-resenärer på genomresa för att oskadliggöra närliggande demoniska hot.",al={"varför är taiga i shadowprey","taiga trollby","tauren i trollstad"}},{q="Vad gör Burning Blade i Desolace?",a="Från Thunder Axe Fortress och Mannoroc Coven öppnar Burning Blade-kulten demoniska portaler för att kalla in styrkor från Burning Legion till Kalimdor. Taiga försöker omintetgöra deras planer innan ödemarken blir helt översvämmad av demoner.",al={"burning blade desolace","vad gör kultisterna","kultister i thunder axe fortress"}},{q="Vad är Hand of Iruxos?",a="Hand of Iruxos är en demonisk artefakt som är inlåst i en Demon Box i Thunder Axe Fortress. Burning Blade vill använda dess vidriga krafter för att slita upp portaler till Nether, men Taiga har kommit på ett sätt att vända handens magi mot revorna och försegla dem.",al={"hand of iruxos","vad är demon box","demon box relik"}},{q="Vad händer vid Mannoroc Coven?",a="Mannoroc Coven är en vanhelgad plats i södra Desolace där Burning Blade har lyckats öppna demoniska portaler. På Taiga Wisemanes uppmaning tar äventyrare Hand of Iruxos till platsen för att med våld stänga portalerna.",al={"mannoroc coven-portaler","vad är mannoroc coven","desolace-portaler"}},{q="Tillhör Taiga en särskild taurenstam?",a="Taiga bär efternamnet Wisemane, vilket speglar hans roll som en äldste med djup oro för den andliga balansen och demonisk förruttnelse. Han tjänar dock den större Horde, som samlar de förenade stammarna under sin fana.",al={"taigas stam","wisemane-stammen","är taiga bloodhoof"}}},fp="14,140,28.324.0,25.372.1,27.364.1,22.184.0,45.208.0,44.145.0,27.166.0,31.142.0,45.172.0"}
P.entries["npc:takar-the-seer"] = {n="Takar the Seer",s="Öster om Camp Taurajo håller Takar the Seer ett ensligt läger i The Barrens. Trots att han omges av hordens områden är han fortfarande lojal mot Alliansen och delar ockult kunskap med vissa resande.",h="Öster om Camp Taurajo håller Takar the Seer ett ensligt läger i The Barrens.",kw={"eremit i the barrens","camp taurajo","själarnas slukare","heartswood","succubus-uppdrag","takar the seer"},ang={["class:Warlock"]="Som häxmästare i Alliansen kan du vända dig till Takar i Kalimdor för vägledning genom de farliga riter som frammanar en succubus och binder henne till din tjänst.",["faction:Alliance"]="Som resande i Alliansen kan du hitta en vänligt sinnad människa långt inne på hordens territorium, även om Takar håller sig till sitt ensliga läger i centrala Kalimdor."},sec={{t="En enstöring på savannen",b="Takar the Seer bor ensam under ett enkelt tält öster om Camp Taurajo. Taurenkrigare och orcpatruller håller uppsikt över The Barrens omkring honom, men låter hans avlägsna glänta vara i fred. Han misstror nyfikna besökare från horden men börjar sällan bråk, utan håller vakt vid horisonten och håller sig för sig själv. Hans läger ligger långt från Stormwinds politik."},{t="Ockulta råd",b="Takar the Seer delar sin kunskap med några få besökare som kommer utifrån. Alliansens häxmästare som kommer från Eastern Kingdoms söker hans gåtfulla råd när de försöker binda farliga varelser från bortom denna värld. Hans förståelse för dolda krafter och själarnas hantverk lockar dessa utövare till hans avlägsna, farofyllda läger."}},faq={{q="Varför bor en mänsklig siare ensam i The Barrens?",a="Takar har aldrig berättat varför han lever ensam. Hans läger ligger öster om Camp Taurajo, långt från varje utpost för Alliansen, och häxmästare besöker honom för hans kunskaper om demoner, inte för hans historia.",al={"varför är takar i the barrens","vad gör takar här","takars bakgrund"}},{q="Är Takar fientligt inställd till spelare från Horde?",a="Ja. Takar står på Alliansens sida, så äventyrare från horden uppfattas som fiender av honom. Han anfaller sällan om han inte blir provocerad eller om någon kommer för nära.",al={"är takar vänligt inställd","kan horde prata med takar","takars reaktion på horde"}},{q="Vad för Alliance-äventyrare till hans läger?",a="De som söker Alliansens hjälp, särskilt häxmästare, kommer till Takar för vägledning i att binda mäktiga demoner som Succubus. Han erbjuder gåtfulla instruktioner och insikter om de reagenser som behövs för att frammana och betvinga dem.",al={"takars uppdrag","varför besöka takar","vem pratar med takar"}}},fx={e39a8e5b={q="Vem är Takar the Seer?",a="Takar the Seer är en ensam mänsklig mystiker som bor långt från mänskliga bosättningar i hjärtat av Kalimdor. Han har slagit läger i den torra vildmarken öster om Camp Taurajo och vakar stilla i The Barrens, trots att han är omgiven av länder som görs anspråk på av Horden och de inhemska stammarna.",al={"vem är takar","vem är takar the seer","takars identitet"}},bed67aa2={q="På vilken sida står Takar the Seer?",a="Takar är fortfarande lojal mot Alliansen. Trots att han bor långt från vänligt sinnade utposter och djupt inne på Hordens territorium välkomnar han alliansresenärer som söker upp honom, men bemöter förbipasserande hjältar från Horden med kylig fientlighet.",al={"tillhör takar alliansen","takar, alliansen eller horden","takars fraktion"}}},fp="14,189,25.327.0,14.332.0,48.177.0,34.140.0,45.211.0"}
P.entries["npc:takata-steelblade"] = {n="Takata Steelblade",s="Takata Steelblade är en orcisk krigare stationerad vid Ghost Walker Post i Desolace. Keldran skickade honom från Orgrimmar tillsammans med Maurin Bonesplitter. Han leder Horde:s lokala kampanj mot demonisk korruption. Hans främsta mål är att utrota områdets satyrer, som är knutna till det ondskefulla Burning Blade.",h="Takata Steelblade är en orcisk krigare stationerad vid Ghost Walker Post i Desolace.",kw={"bonesplitter","burning blade","desolace","ghost walker post","keldran","maurin","satyr","steelblade","takata"},ang={["class:Warrior"]="Takata är en mästersvärdsman. Hans kampanj bygger på beslutsam militär styrka för att fälla demoniska infiltratörer.",["faction:Horde"]="Takata samordnar Hordes regionala försvar i Desolace och utgår från Ghost Walker Post för att rensa ut demoniska infiltratörer.",["race:Orc"]="Takata följer order från Orgrimmars ledning och förkroppsligar orcernas plikt att utplåna varje spår av demoniskt slaveri."},sec={{t="Skickad till Desolace",b="Takata Steelblade skickades från huvudstaden till Desolace på direkt order av Keldran, en inflytelserik person i Orgrimmar som är fast besluten att avslöja och rensa ut demonisk infiltration. Takata verkar från det avlägsna taurenlägret Ghost Walker Post. Där samordnar han militära insatser mot de Legion-allierade styrkor som hemsöker de karga ödemarkerna."},{t="Satyrernas bane",b="Medan hans följeslagare Maurin Bonesplitter försöker spåra upp och slå ut Burning Blade:s hemliga kultister direkt, riktar Takata in sig på deras demoniska allierade: satyrerna. Takata har lett våldsamma anfall mot Desolace:s korrumperade satyrer. Han har decimerat deras led för att bryta kultens lokala maktstruktur och hejda deras spridande fördärv."}},faq={{q="Vem är Takata Steelblade?",a="Takata Steelblade är en erfaren orcisk krigare stationerad vid Ghost Walker Post i Desolace. Han leder operationer mot demoniska styrkor och satyrer som är allierade med Burning Blade.",al={"takata","takatas bakgrund","vem är takata"}},{q="Vem skickade Takata till Desolace?",a="Keldran skickade honom från Orgrimmar för att undanröja hotet från Burning Blade och dess demoniska allierade i hela området.",al={"vem skickade takata","keldrans koppling","takatas order"}},{q="Hur hänger Takata och Maurin Bonesplitter ihop?",a="Keldran skickade iväg dem tillsammans. Maurin försöker bekämpa Burning Blade:s kultister direkt, medan Takata riktar sina militära anfall mot satyrerna som är allierade med dem.",al={"takata och maurin","maurin bonesplitter"}},{q="Varför jagar Takata satyrer?",a="Satyrerna i Desolace är aktivt allierade med Burning Blade-kulten. De sprider demoniskt fördärv och hotar Hordes fäste i hela området.",al={"varför döda satyrer","takata satyr","besudlad av satyrer"}},{q="Var hittar man Takata Steelblade?",a="Han finns vid Ghost Walker Post, ett Horde-läger i norra centrala Desolace.",al={"takatas plats","var finns takata steelblade"}}},fx={a8c99361={q="På vilken sida står Takata Steelblade?",a="Takata Steelblade är lojal mot Horden och lyder under Keldran i Orgrimmar. Han arbetar för att säkra Hordens intressen i Desolace genom att rensa bort de demoniska krafter som hotar Kalimdor, särskilt de onda kulter och demoner som står mot hans folk.",al={"takata steelblades fraktion","takatas lojalitet","tillhör takata horden"}},["683721f0"]={q="Varför är Takata Steelblade här?",a="Takata har tagit post vid Ghost Walker Post på Keldrans order för att leda den lokala offensiven mot demonisk korruption. Hans kamrat Maurin Bonesplitter fokuserar enbart på Burning Blade-kulten, medan Takata riktar sin vrede mot regionens satyrer och för en skoningslös kampanj för att utrota dem helt.",al={"varför är takata i desolace","takata steelblades syfte","vad gör takata här"}},a7138bd5={q="Varför är Takata Steelblade berömd eller fruktad?",a="Takata är ökänd bland Desolaces vidriga invånare för sin förödande och systematiska massaker på den lokala satyrbefolkningen. Han har fått ett fruktansvärt rykte genom att skoningslöst fälla varje satyr med anknytning till Burning Blade i de öde vidderna.",al={"takatas rykte","varför är takata fruktad","takatas berömmelse"}}},fp="17,323,16.348.0,21.349.0,25.173.0,28.136.0,64.179.0,29.151.0,37.75.0"}
P.entries["npc:tal"] = {n="Tal",s="Tal är Thunder Bluffs främsta vindryttarmästare och sköter stadens luftburna rastplats högt ovanför Mulgore-slätterna. Han förser Horde-resenärer med erfarna wyverner som vill ta sig genom Kalimdors vidsträckta områden.",h="Tal är Thunder Bluffs främsta vindryttarmästare och sköter stadens luftburna rastplats högt ovanför...",kw={"flygmästare","mulgore","rastplats","tal","thunder bluff","vindryttarmästare","wyvern"},ang={["faction:Horde"]="Tal sköter en av Hordes viktigaste knutpunkter för resor i Kalimdor och förbinder taurenhuvudstaden direkt med The Crossroads och Orgrimmar.",["race:Tauren"]="För taurer som färdas bortom sina förfäders betesmarker erbjuder Tal den snabbaste och säkraste vägen från de höga klipporna ut i den större världen."},sec={{t="Väktare av den höga rastplatsen",b="Tal sitter på Thunder Bluffs centrala platå och sköter den viktiga luftvägen som förbinder taurenhuvudstaden med resten av Horde. Från sin plats tar han hand om de trogna vindryttarna, eller wyvernerna, och ser till att de är friska, välnärda och redo för långa resor över Kalimdors karga landskap. Oavsett om han skickar budbärare till Camp Taurajo eller sänder spejare genom The Barrens till Orgrimmar, upprätthåller Tal en oumbärlig livlina som håller staden på den höga platån i ständig kontakt med sina allierade."}},faq={{q="Vilken roll har Tal i Thunder Bluff?",a="Tal är Thunder Bluffs vindryttarmästare. Han sköter rastplatsen högst uppe på klipporna, tar hand om de bevingade bestarna och ordnar flygresor över Kalimdor för Horde-medlemmar.",al={"vem är tal","tal flygmästare","vad gör tal"}},{q="Vart skickar Tal resenärer?",a="Tal förbinder Thunder Bluff med platser i centrala och södra Kalimdor, bland annat Camp Taurajo, The Crossroads, Orgrimmar och avlägsna utposter i vildmarken.",al={"vart kan tal flyga","tals destinationer","flygrutter från thunder bluff"}},{q="Varför används vindryttare i stället för vanliga riddjur?",a="Thunder Bluffs lodräta klippväggar och höga läge gör resor till fots långsamma och krokiga. Flygande riddjur som vindryttare erbjuder snabba, direkta resor till och från staden på den höga platån, utan att man behöver ta sig via hissarna.",al={"varför wyverner","thunder bluffs flygande bestar"}}},fx={["704cf2c5"]={q="Vem är Tal?",a="Tal är taurenmästare för vindryttarna, stationerad högt uppe på Thunder Bluffs centrala viloplats. Som flygmästare ansvarar han för skötseln, aveln och utsändningen av stadens bevingade wyverner och erbjuder livsviktiga flygresor för resenärer genom Kalimdor.",al={"vem är tal","tals identitet","tal, icke-spelarkaraktär"}},a57be0bc={q="På vilken sida står Tal?",a="Tal är trofast lojal mot Thunder Bluff och Horden. Han erbjuder sina vindryttare enbart till Hordens medlemmar och deras allierade och ser till att de snabbt kan färdas mellan Mulgore, The Barrens och utposter runt Kalimdor, samtidigt som han nekar Alliansen tillträde.",al={"tals fraktion","tillhör tal horden","tals lojaliteter"}},e868146f={q="Vad vill Tal?",a="Tal vill upprätthålla Thunder Bluffs viktiga luftförbindelser. Hans främsta mål är att hålla vindryttarna mätta, lugna och redo att flyga, samtidigt som han ser till att Hordens kurirer, spejare och äventyrare kan färdas snabbt och säkert genom Kalimdors karga vidder.",al={"vad vill tal","tals motiv","tals mål"}},dfa35811={q="Varför är Tal här?",a="Tal sköter viloplatsen högt uppe på Thunder Bluff eftersom stadens höga platåberg lämpar sig väl för starter och landningar. Från denna centrala höjd kan vindryttarna fånga de höga uppvindarna och föra passagerare över Mulgore-slätterna och vidare.",al={"varför är tal i thunder bluff","tals viloplats","varför här"}}},fp="3,153,24.397.0,41.172.0,30.170.0,55.226.0"}
P.entries["npc:talen"] = {n="Talen",s="Talen är en nattalv och amatörarkeolog som slagit läger nära The Zoram Strand i nordvästra Ashenvale. Trots den ständiga faran från närliggande naga och Hordens utposter ägnar han sig åt att återfinna gamla kaldorei-reliker begravda längs kusten.",h="Talen är en nattalv och amatörarkeolog som slagit läger nära The Zoram Strand i nordvästra Ashenvale.",kw={"ancient statuette","arkeolog","ashenvale","ruuzel","talen","the zoram strand"},ang={["faction:Alliance"]="Talen är en värdefull kontakt ute i fält för alliansens resande i Ashenvales omstridda norra delar, inte långt från Maestra's Post.",["race:NightElf"]="För kaldorei är The Zoram Strand en tragisk påminnelse om Sundringen. Talen står för viljan att bevara och återfinna arvet som gick förlorat när gamla kustgods sjönk ner i Stora havet."},sec={{t="Lärd vid kusten",b="Från sitt lilla läger vid kanten av The Zoram Strand ägnar Talen dagarna åt historiska märkvärdigheter i stället för krig. Ashenvales vildmark präglas av territoriella strider och fientliga invånare längs kusten, men Talen är fokuserad på att samla sedan länge försvunna skatter från ruinerna under vågorna och sanden. Han förlitar sig i hög grad på förbipasserande äventyrare som vågar möta de vilda Wrathtail-naga och hämta svårfunna artefakter, däribland välbevarade statyetter och Ring of Zoram som naga-ledaren Ruuzel har."}},faq={{q="Vem är Talen?",a="Talen är en nattalvslärd och amatörarkeolog som bor i ett litet läger nära The Zoram Strand i Ashenvale. I stället för att tjänstgöra som väktare eller soldat studerar han de gamla reliker som ligger begravda längs havsstranden.",al={"vem är den här nattalven","talen ashenvale","talen the zoram strand"}},{q="Varför har Talen slagit läger nära The Zoram Strand?",a="Han undersöker de sjunkna ruinerna och stränderna vid The Zoram Strand för att återfinna gamla kaldorei-artefakter. Eftersom stranden kryllar av våldsamma naga och ligger nära Hordens utpost Zoram'gar håller han till på en liten lägerplats en bit från stranden.",al={"varför är talen här","talens syfte"}},{q="Vilka artefakter vill Talen ha?",a="Talen ber resande leta längs kusten efter gamla statyetter som spolats i land. Han ger dem också i uppdrag att söka upp den mäktiga naga Ruuzel på en närliggande ö ute till havs och hämta Ring of Zoram, nyckeln till låset på den gamla statyetten.",al={"talens uppdrag","vad behöver talen","ruuzels uppdrag"}},{q="Är Talen fientligt inställd till Horden?",a="Talen är allierad med nattalverna, men han är främst en lärd och angriper inte Hordens resande om de inte provocerar eller angriper honom först.",al={"angriper talen horden","är talen vänligt inställd till horden"}}},fx={["76deb443"]={q="På vilken sida står Talen?",a="Talen står på Alliansens sida som en night elf med läger i Ashenvale. Han ägnar sig främst åt arkeologiska studier snarare än militära kampanjer, men hans lojalitet ligger hos hans folk och deras allierade. Horderesenärer märker att han försvarar sig om han blir hotad, men hans verkliga intresse är relikerna begravda i den omgivande sanden snarare än öppet krig.",al={"talens fraktion","tillhör talen alliansen","talens lojalitet"}}},fp="5,140,20.377.0,13.176.0,43.240.0,31.201.0,30.134.0"}
P.entries["npc:tallonkai-swiftroot"] = {n="Tallonkai Swiftroot",s="Tallonkai Swiftroot är en Night Elf som bor i Dolanaar på Teldrassil. Han oroar sig över den växande fördärvskorruptionen i de stora grenarna och skickar unga äventyrare för att hämta förtrollade reliker och hejda de onda krafter som plågar skogen.",h="Tallonkai Swiftroot är en Night Elf som bor i Dolanaar på Teldrassil.",kw={"dolanaar","drömfångare","ferocitas","tallonkai swiftroot","teldrassil","twisted hatred"},ang={["class:Druid"]="Tallonkai oroar sig främst för reliker som tryggt förankrar sinnen i The Emerald Dream, vilket gör hans önskemål djupt förankrade i druidernas andliga traditioner.",["race:NightElf"]="Tallonkai Swiftroot står för den vaksamhet som krävs för att skydda Teldrassil under dess sårbara första år. Han ber unga Kaldorei att rensa bort korruptionen som slår rot i deras nya hem."},sec={{t="En vaktpost i Dolanaar",b="Tallonkai Swiftroot bor i trädtoppsbyn Dolanaar och håller noga uppsikt över de omgivande skogarna. Liksom många Night Elves som lever under grenarna på det nyvuxna världsträdet oroar han sig över vilda djurs onaturliga oro och de obehagliga skuggor som samlas vid utkanten av deras bosättningar."},{t="Hot i trädkronorna",b="Tallonkai skickar äventyrare för att konfrontera onda väsen som stör friden på Teldrassil. Han oroar sig bland annat för korrumperade drömfångare som skapats för att skydda sovande druider, våldsamma gnarlpine-furbolgs som faller offer för en mörk sjukdom och de korrumperade Gnarlpine-mystikerna under ledning av Ferocitas the Dream Eater. För Tallonkai är det avgörande att rena dessa platser från oron för att försvara Kaldoreis bräckliga hem."}},faq={{q="Vem är Tallonkai Swiftroot?",a="Tallonkai Swiftroot är en uppdragsgivare av folket Night Elf i Dolanaar, bland grenarna på Teldrassil. Han vaktar bosättningen mot lokala hot.",al={"vem är tallonkai","tallonkai swiftroot","uppdragsgivare i dolanaar"}},{q="Var hittar jag Tallonkai Swiftroot?",a="Han finns i byn Dolanaar, den centrala Night Elf-byn strax utanför Shadowglen på Teldrassil.",al={"tallonkai plats","var finns tallonkai","hitta tallonkai swiftroot"}},{q="Vilka uppgifter ger Tallonkai?",a="Han ber resenärer att hämta Emerald Dreamcatcher från gnarlpine-furbolgs, besegra Gnarlpine-furbolgen Ferocitas the Dream Eater och döda satyren Lord Melenas i hans grotta vid Fel Rock i Twisted Hatred.",al={"tallonkai uppdrag","vad vill tallonkai"}},{q="Varför oroar han sig för drömfångarna?",a="Drömfångare är heliga Night Elf-amulletter knutna till The Emerald Dream. De används för att skydda mot mardrömmar och mörka syner. När fientliga varelser stjäl och korrumperar dem utsätts de lokala druiderna och invånarna på Teldrassil för en andlig fara.",al={"emerald dreamcatcher bakgrund","varför drömfångare"}},{q="Vem är Ferocitas the Dream Eater?",a="Ferocitas the Dream Eater leder en grupp korrumperade Gnarlpine-mystiker norr om Starbreeze. Han stal smaragden från Tallonkais drömfångare och bär den i ett halsband som lyser grönt om natten.",al={"vem är ferocitas","ferocitas bakgrund"}},{q="Vad orsakar oron som Tallonkai bekämpar?",a="En växande sjukdom och onaturlig korruption har trängt in i Teldrassil och driver tidigare fredliga varelser som gnarlpine-furbolgs till våldsamt vansinne.",al={"varför är furbolgs galna","twisted hatred bakgrund"}}},fx={cb092b62={q="På vilken sida står Tallonkai Swiftroot?",a="Tallonkai står stadigt med night elves i Darnassus och Alliansen. Stationerad i Dolanaar arbetar han för att skydda Teldrassils växande bosättningar från korruption och de vilddjur som störts bland trädgrenarna.",al={"tallonkai swiftroots fraktion","vem tjänar tallonkai","tallonkai swiftroots lojalitet"}},ea33b78b={q="Vad vill Tallonkai Swiftroot?",a="Tallonkai vill skydda Dolanaar och lugna Teldrassils korrumperade djurliv. Han vill återfå heliga drömfångare från Smaragddrömmen som stulits av besudlade gnarlpine-furbolger och kräver att vidriga hot som Ferocitas the Dream Eater och de korrumperade satyrer vars hat förgiftar skogarna utplånas.",al={"vad vill tallonkai","tallonkais mål","tallonkais motiv"}},bffc0ef8={q="Varför är Tallonkai Swiftroot i Dolanaar?",a="Tallonkai är stationerad i Dolanaar för att hålla uppsikt över oron som växer i vildmarken runt omkring. När fördärvade furbolger och vidriga bestar hotar vägarna och bosättningarna på Teldrassil stannar han i staden för att rekrytera dugliga äventyrare som kan slå tillbaka mot plågorna i skogen.",al={"varför är tallonkai här","varför är tallonkai swiftroot i dolanaar","vad förde tallonkai till dolanaar"}}},fp="19,206,22.253.0,21.349.0,27.158.0,37.104.0,31.189.0,44.209.0,33.187.0,52.167.0"}
P.entries["npc:tallow"] = {n="Tallow",s="Tallow är en Forsaken-krigare som är stationerad i den befästa bosättningen Tarren Mill i Hillsbrad Foothills. Han tjänar Dark Lady och Horde och vakar över de omstridda frontlinjerna, där han hjälper till att organisera anfall mot lokala Alliance-hot.",h="Tallow är en Forsaken-krigare som är stationerad i den befästa bosättningen Tarren Mill i Hillsbrad Foothills.",kw={"forsaken","hillsbrad foothills","horde-krigare","tallow","tarren mill","the hammer may fall"},ang={["faction:Horde"]="Tallow tilldelar Horde-mästare viktiga uppdrag vid frontlinjen för att försvaga människornas närvaro i Hillsbrad Foothills.",["race:Undead"]="Liksom många andra Forsaken i Tarren Mill kämpar Tallow för att utöka Undercitys herravälde söder om Alterac Mountains."},sec={{t="Ett blad i Tarren Mill",b="Mitt i Tarren Mill står Tallow bland Forsaken- och Horde-styrkorna som håller linjen i Hillsbrad Foothills. Regionen är en krutdurk av konflikter, klämd mellan människorna i närbelägna Southshore, kringströvande laglösa från Syndicate och fientliga vilda djur. Tallow hjälper till att skicka dugliga äventyrare ut i fält och prövar deras styrka mot Boulderfist-ogrerna i Arathi Highlands innan han skickar dem vidare för att hjälpa den belägrade utposten Hammerfall."}},faq={{q="Vem är Tallow?",a="Tallow är en Forsaken-krigare med bas i Tarren Mill i Hillsbrad Foothills. Han organiserar uppdrag åt Horde-mästare som strider i området.",al={"vem är tallow","tallows bakgrund","tallow tarren mill"}},{q="Var hittar jag Tallow?",a="Han står i staden Tarren Mill, som hålls av Forsaken och ligger i den norra delen av Hillsbrad Foothills.",al={"var finns tallow","tallows plats","hitta tallow"}},{q="Vilka uppdrag erbjuder Tallow?",a="Tallow är känd för att leda Horde-äventyrare på uppdraget ”The Hammer May Fall”. Han skickar krigare för att bevisa sig mot Boulderfist-ogrerna i Arathi Highlands innan de rapporterar till Drum Fel vid den belägrade utposten Hammerfall.",al={"tallows uppdrag","uppdraget the hammer may fall"}},{q="Vilken roll spelar Tarren Mill i konflikten?",a="Tarren Mill är Hordes främsta fäste i norra Hillsbrad Foothills, där staden ständigt möter skärmytslingar och öppet krig mot människornas bastion Southshore i söder.",al={"varför är tarren mill viktigt","tarren mills roll"}}},fx={df176dd7={q="Vems sida står Tallow på?",a="Tallow tjänar Forsaken och den större Horde. Han är stationerad i Tarren Mill och står med de odöda försvararna som håller stånd i Hillsbrad mot Southshores fientliga människor och hoten i området som pressar mot Hordes södra gränser.",al={"tallows fraktion","är tallow horde","tallows lojalitet"}},cc135250={q="Vad vill Tallow?",a="Som krigare stationerad vid frontlinjen i Tarren Mill vill Tallow säkra Forsakens bosättning och försvaga deras fiender i Hillsbrad. Han ger dugliga Horde-mästare i uppdrag att slå till mot hot som tornar upp sig, bland annat genom att skicka äventyrare på farliga uppdrag som ”The Hammer May Fall” för att underminera rivaliserande styrkor.",al={"tallows mål","vad gör tallow","tallows motiv"}},b53e5a72={q="Varför är Tallow i Tarren Mill?",a="Tarren Mill är Forsakens främsta fäste i Hillsbrad Foothills och utsätts ständigt för tryck från Alliance i Southshore och andra fientliga fraktioner. Tallow är stationerad här som krigare för att försvara staden, samordna militära angrepp och värva förbipasserande Horde-krigare som kan förstärka frontlinjerna.",al={"varför är tallow här","tallow i tarren mill","tallows syfte i hillsbrad"}}},fp="6,186,22.406.0,14.95.0,24.87.0,30.153.0,43.165.0"}
P.entries["npc:talvash-del-kissel"] = {n="Talvash del Kissel",s="Talvash del Kissel är en utfattig gnomjuvelerare som flydde Gnomeregan när staden föll och nu bor i Ironforges Mystic Ward. Efter att ha förlorat sitt hem plågas han av skulder och envisa rykten. Han söker dugliga äventyrare som kan hjälpa honom att återfinna förlorade skatter och återställa krossade reliker. Hans skarpa blick för ädelstenar och forntida prydnader gör honom till en värdefull kontakt för dem som utforskar djupen i Uldaman.",h="Talvash del Kissel är en utfattig gnomjuvelerare som flydde Gnomeregan när staden föll och nu bor i...",kw={"del kissel","gnomeregan","ironforge","juvelerare","mystic ward","krossat halsband","talvash","uldaman"},ang={["faction:Alliance"]="Alliansens äventyrare som utforskar Uldaman eller ruinerna av Gnomeregan har stor nytta av Talvash när de ska återställa forntida smycken och återfinna förlorade gnomiska arvegods.",["race:Gnome"]="Talvash påminner om hur Gnomeregans fall krossade vanliga invånares liv och drev skickliga hantverkare på flykt, utfattiga och tvungna att klara sig i Ironforge."},sec={{t="Från hantverkare till skuldsatt flykting",b="Talvash var en gång en respekterad juvelerare i Gnomeregans teknologiska hjärta. När troggarna vällde in över den underjordiska staden förstördes hans hem och levebröd. Han flydde tillsammans med de överlevande flyktingarna till dvärgarnas huvudstad Ironforge och slog sig ner i Mystic Ward. Tyvärr gick flytten honom illa. Rykten om tvivelaktiga affärer och obetalda skulder hopade sig snabbt och försatte hantverkaren i djup ekonomisk nöd. Talvash kunde inte återuppta sitt yrke på vanligt sätt och förlitar sig därför på frilansande äventyrare som kan hämta förlorade tillgångar och rädda hans förstörda anseende."},{t="Reliker från Uldaman och gnomiskt hantverk",b="Trots sina motgångar har Talvash inte förlorat sin precision när han slipar ädelstenar eller sin skicklighet i att värdera dem. När upptäcktsresande i Badlands hittar ett forntida, krossat halsband djupt inne i Uldamans titanhägn visar sig Talvash vara en av få hantverkare i Eastern Kingdoms som kan förstå dess intrikata förtrollningar. Att återställa dess kraft kräver sällsynta komponenter och mödosamt arbete, men Talvash vill gärna utöva sitt yrke, både för att betala sina skulder och bevisa att hans skicklighet består."}},faq={{q="Vem är Talvash del Kissel?",a="Talvash är en gnomjuvelerare i landsflykt som bor i Ironforges Mystic Ward. Efter att ha tvingats lämna Gnomeregan när staden föll kämpar han nu med väldiga skulder och envisa rykten. Han anlitar äventyrare som kan hjälpa honom att reparera föremål och betala sina skulder.",al={"vem är talvash","talvash del kissel","talvash"}},{q="Var hittar jag Talvash?",a="Talvash finns i Ironforges Mystic Ward, nära dammen och de magiinriktade butikerna i dvärgarnas huvudstad.",al={"talvashs plats","var finns talvash","hitta talvash del kissel"}},{q="Vad hände med hans verksamhet i Gnomeregan?",a="Talvash drev en juvelerarverksamhet i Gnomeregan innan staden föll. När troggarna invaderade och staden gick under förlorade han allt. Senare rykten och motgångar gjorde honom djupt skuldsatt i Ironforge.",al={"varför är talvash utfattig","talvashs skulder","vad hände med talvash"}},{q="Hur är Talvash knuten till Uldaman?",a="Upptäcktsresande som hittar en krossad kraftkälla i den forntida utgrävningen Uldaman hänvisas till Talvash. Hans kunskaper om ädelstenar och förtrollning låter honom återskapa det krossade halsbandet åt äventyrare som kan samla in de saknade delarna.",al={"talvash uldaman","uldaman halsband","uppdraget med det krossade halsbandet"}},{q="Har Talvash något med uppdrag i Gnomeregan att göra?",a="Ja. Han hjälper till att återfinna personliga tillhörigheter som gått förlorade i den förstörda staden, däribland ringar och apparater som lämnades kvar när Gnomeregan evakuerades.",al={"talvash gnomeregan","uppdraget återlämna ringen"}},{q="Varifrån kommer hans namn?",a="Talvash del Kissel var karaktärsnamnet på en gnommagiker som spelades av Shawn Carnes, en ledande uppdragsskapare på Blizzard, under hans tid som EverQuest-spelare innan han började arbeta med World of Warcraft.",al={"kuriosa om talvash","talvashs namns ursprung","shawn carnes"}}},fx={["4febcc43"]={q="Vems sida står Talvash del Kissel på?",a="Talvash står stadigt på Alliances sida och med sina fördrivna gnomiska fränder. Trots att han har hamnat i ekonomiska svårigheter och verkar självständigt från Ironforge förblir hans affärer och lojaliteter helt och hållet hos Alliance.",al={"talvash del kissels fraktion","är talvash alliance","talvash lojalitet"}},["3a8c1c09"]={q="Vad vill Talvash del Kissel?",a="Talvash är desperat att betala av sina stora skulder och återupprätta sitt rykte. Efter Gnomeregans fall och ihärdiga rykten om att hans verksamhet gått under handlar han nu med sällsynta smycken, forntida reliker och lärdomar för att återvinna sin förlorade förmögenhet.",al={"vad vill talvash","talvash del kissels mål","talvash motiv"}},["762fb8e0"]={q="Varför är Talvash del Kissel i Ironforge?",a="Precis som så många andra gnomer flydde Talvash sitt hem när Gnomeregan föll för troggerna och strålningen. Han sökte skydd i Ironforges Mystic Ward, där han arbetar bland lärda och besvärjare och försöker sälja sitt hantverk och sina arkaniska kunskaper medan han håller sig undan sina fordringsägare.",al={"varför är talvash här","varför är talvash i mystic ward","varför lämnade talvash gnomeregan"}}},fp="18,412,29.611.0,35.495.0,26.241.0,25.123.0,44.202.0,40.250.0,56.157.0,31.175.0"}
P.entries["npc:tammra-windfield"] = {n="Tammra Windfield",s="Tammra Windfield är en tauren som bor i Sun Rock Retreat, högt uppe i Stonetalon Mountains. Hon känner djupt för landets balans och vägleder Horde-resenärer i att hedra naturens kretslopp och hålla hoppet vid liv bland bergen. Hon värnar både om den otämjda vildmarkens hälsa och sina fränders trygghet.",h="Tammra Windfield är en tauren som bor i Sun Rock Retreat, högt uppe i Stonetalon Mountains.",kw={"cycle of rebirth","kaya","new life","stonetalon","sun rock retreat","tammra","tauren","windfield"},ang={["class:Druid"]="Hennes fokus på återfödelsens kretslopp och på att odla nytt liv återspeglar druidismens grundläggande principer, vilket gör hennes önskemål särskilt betydelsefulla för vildmarkens vårdare.",["faction:Horde"]="I det omstridda området Stonetalon hjälper Tammra till att hålla Sun Rock Retreat som ett tryggt och varaktigt fäste för Hordes resenärer.",["race:Tauren"]="Tammra visar hur taurenfolket hängivet hedrar Jordmodern och hur andlig vördnad leder till konkret återställning, även långt från Mulgore."},sec={{t="Sun Rocks väktare",b="Sun Rock Retreat är en viktig fristad för Horde bland Stonetalon Mountains klippiga toppar, omgiven av fientliga harpyor, skogshuggare från Venture Company och rovdjur på lur. Tammra Windfield hör till bosättningens beskyddare och håller ett vakande öga på både bergsvildmarken och resenärer som passerar dess gräns. Hennes milda sätt döljer den beslutsamhet som krävs för att hålla ett hem vid liv i så karg terräng."},{t="Att vårda landet",b="Liksom många av sitt folk hedrar Tammra Jordmodern genom att följa naturens ständiga rytm av tillväxt och förfall. Genom uppgifter hon anförtror åt resenärer, som att vårda återfödelsens kretslopp och ge nytt liv, motverkar hon skadorna som konflikter och rovdrift orsakar i Stonetalon. För Tammra kräver skyddet av landet aktiv läkning, så att livet frodas även i sargad bergsjord."},{t="Frändskap och vaksamhet",b="Utöver sina andliga plikter mot den omgivande vildmarken oroar sig Tammra djupt för följeslagare och fränder som trotsar Stonetalon Mountains förrädiska stigar. När ryktet sprids att resenärer eller familjemedlemmar har försvunnit bland klipporna är hon en av de första att söka tillförlitlig hjälp. För Tammra beror Sun Rock Retreats uthållighet lika mycket på ömsesidigt beskydd och lojalitet som på harmoni med naturen."}},faq={{q="Vem är Tammra Windfield?",a="Tammra Windfield är en tauren och uppdragsgivare som bor i Sun Rock Retreat i Stonetalon Mountains. Hon värnar om bosättningens välmående, bergslandskapets naturliga kretslopp och sina medresenärers överlevnad.",al={"vem är tammra","tammra windfield","tammra i sun rock retreat"}},{q="Var hittar jag Tammra Windfield?",a="Hon finns i Sun Rock Retreat, Hordes läger högt uppe i västra Stonetalon Mountains. Du tar dig dit via en bergsstig som går av från dalens huvudväg.",al={"tammra windfields plats","var finns tammra","hitta tammra windfield"}},{q="Vilka uppdrag erbjuder Tammra?",a="Tammra är inblandad i uppgifter som handlar om förnyelse och hennes fränders välmående, däribland 'Cycle of Rebirth' och 'New Life'. Hon tar också emot resenärer som rapporterar om fränders överlevnad i 'Kaya's Alive'.",al={"tammras uppdrag","tammra windfields uppdragslista"}},{q="Vilken roll har Tammra i Sun Rock Retreat?",a="Tammra är ett fast stöd i samhället och en andlig vårdare. Hon vägleder äventyrare som ska återställa livskraften i den omgivande vildmarken och vårdar banden som håller den avlägsna utposten trygg.",al={"vad gör tammra","tammras roll"}},{q="Varför bryr sig Tammra om naturens kretslopp?",a="I taurenkulturen kräver balans att man vårdar Jordmoderns kretslopp av död och återfödelse. Yttre krafter och bergens bestar hotar området, så Tammra vill odla nytt liv för att läka den sargade vildmarken.",al={"berättelsen om cycle of rebirth","varför återfödelse i stonetalon"}},{q="Är Tammra vänligt inställd till Alliance-spelare?",a="Nej. Sun Rock Retreat är en renodlad Horde-utpost, och Tammra står på Thunder Bluff och Hordes sida. Därför är hon fientlig mot inkräktare från Alliance.",al={"är tammra fientlig","kan alliance prata med tammra"}}},fx={["590ef84e"]={q="Varför är Tammra Windfield i Sun Rock Retreat?",a="Tammra bor i Sun Rock Retreat för att vårda landets andar och iaktta livets naturliga kretslopp i Stonetalon Mountains. Från denna höga fristad vakar hon över de oroliga klipporna och söker upp resenärer som kan hjälpa till att främja förnyelse mitt i regionens svårigheter.",al={"varför är tammra här","varför är tammra windfield i sun rock retreat","varför är tammra i stonetalon mountains"}}},fp="16,186,20.311.0,18.328.0,21.322.0,24.188.0,34.177.0,30.168.0,42.184.0,45.214.0,39.134.0"}
P.entries["npc:tannok-frosthammer"] = {n="Tannok Frosthammer",s="Tannok Frosthammer är en dvärg som bor vid Thunderbrew Distillery utanför Kharanos i Dun Morogh. Han tar emot varor med oro och bekymrar sig djupt över hur troggattacker har stängt vägarna till Anvilmar.",h="Tannok Frosthammer är en dvärg som bor vid Thunderbrew Distillery utanför Kharanos i Dun Morogh.",kw={"anvilmar","coldridge","destilleri","frosthammer","kharanos","tannok","thunderbrew","troggar"},ang={["faction:Alliance"]="Tannoks strandsatta leveranser visar hur även bosättningar i hjärtat av landet, som Kharanos, känner av det växande trycket från troggarnas intrång.",["race:Dwarf"]="För dvärgar som lämnar Anvilmar för den större världen är leveranser till Tannok vid Thunderbrew Distillery ett av de allra första stegen in i hjärtat av Dun Morogh."},sec={{t="En bruten försörjningslinje",b="Tannok Frosthammer håller uppsikt över inkommande leveranser och lokala nyheter vid Thunderbrew Distillery i Kharanos. Plötsligt har horder av troggar i Coldridge Pass skurit av den vanliga trafiken från Coldridge Valley, och Tannok har förlorat den regelbundna kontakten med bosättningen Anvilmar. Han förlitar sig på kurirer som gnommekanikern Hands Springsprocket, som förmedlar viktiga förnödenheter och nyheter genom det farliga, snöiga bergspasset. Tannok ger uttryck för den stilla oro som många Bronzebeards känner när hot underifrån kryper allt närmare deras hem."}},faq={{q="Var finns Tannok Frosthammer?",a="Tannok Frosthammer finns utanför Thunderbrew Distillery, strax öster om huvudkorsningen i Kharanos i Dun Morogh.",al={"tannoks plats","var finns tannok","hitta tannok frosthammer"}},{q="Varför oroar sig Tannok för Coldridge Valley?",a="Tannok oroar sig djupt över trogginvasionen som blockerar Coldridge Pass. Den övertagna vägen har brutit den regelbundna kontakten och handeln mellan bosättningen Anvilmar i dalen och resten av Dun Morogh.",al={"tannoks bekymmer","varför oroar sig tannok","troggar i coldridge pass"}},{q="Vem samarbetar Tannok med i Coldridge Valley?",a="Tannok tar emot leveranser från Hands Springsprocket, en gnomisk leverantör som håller till nere i Coldridge Valley och ber förbipasserande resenärer att transportera varor genom det farliga passet.",al={"tannoks leverantör","hands springsprockets leverans","vem förser tannok med varor"}}},fx={["22aa1045"]={q="Vem är Tannok Frosthammer?",a="Tannok Frosthammer är en dvärg från Ironforge som bor i Kharanos och är stationerad vid Thunderbrew Distillery. Han hjälper till att övervaka flödet av lokala varor och förnödenheter genom Dun Morogh och upprätthåller viktiga försörjningsförbindelser mellan centralorterna och mer avlägsna utposter som Coldridge Valley.",al={"vem är tannok","tannok frosthammer bakgrund","tannoks identitet"}},["93f9fc20"]={q="Vems sida står Tannok Frosthammer på?",a="Tannok är en lojal undersåte till Ironforge och en trofast medlem av Alliance. Hans främsta angelägenhet är Dun Moroghs invånares säkerhet och välbefinnande, samt att se till att handelsvägarna förblir framkomliga trots de växande hoten i snön.",al={"tannoks fraktion","är tannok med i alliance","tannok frosthammers lojalitet"}},eebd916b={q="Varför är Tannok Frosthammer här?",a="Tannok bedriver sin verksamhet från Thunderbrew Distillery i Kharanos. Han stannar här för att ta emot viktiga leveranser och hålla kontakten med avlägsna leverantörer, men de senaste störningarna i Coldridge Pass har stoppat leveranserna och lämnat honom oroligt väntande på besked.",al={"varför är tannok i kharanos","varför är tannok här","tannok frosthammers syfte"}}},fp="18,150,21.437.0,36.111.0,45.124.0,46.165.0"}
P.entries["npc:taragaman-the-hungerer"] = {n="Taragaman the Hungerer",s="Under Orgrimmar strövar Taragaman the Hungerer omkring i Ragefire Chasms smälta grottor. Horden försöker döda den väldige felguarden, som fruktas vara den demoniske mästaren bakom sekten Searing Blade, och få slut på den demoniska smittan under staden.",h="Under Orgrimmar strövar Taragaman the Hungerer omkring i Ragefire Chasms smälta grottor.",kw={"bazzalan","demon","felguard","hungerer","jergosh","orgrimmar","ragefire chasm","searing blade","taragaman"},ang={["class:Warlock"]="Som häxmästare utövar du mörka konster ovanför i Cleft of Shadow, medan en vild och fientlig felguard som Taragaman hotar din konsts hemlighet och säkerhet.",["class:Warrior"]="Som krigare måste du stå stadigt mot Taragamans krossande slag och undvika att kastas ner i lavan av hans brutala uppercuts.",["faction:Horde"]="För unga krigare och besvärjare i Horden är det ett prov på deras duglighet att döda Taragaman under Orgrimmar, och det hjälper till att skydda huvudstaden från demoniskt fördärv."},sec={{t="Odjuret där nere",b="Taragaman the Hungerer strövar omkring bland magmapölarna i Ragefire Chasm och hotar Orgrimmar ovanför. Spejare och unga krigare som skickas in i de mörka grottorna ser den demoniske felguarden som ledare för sekten Searing Blade. Med infernalisk styrka böjer han de viljesvaga och fördärvar gångarna under Thralls fäste."},{t="Dödlig lockfågel",b="Taragaman the Hungerer styr sektens skräck, men dess verkliga ledare är satyren Bazzalan och häxmästaren Jergosh the Invoker. Ränksmidarna använder den väldige felguarden som förbrukbart lockbete, en monstruös avledning som drar hordens försvarare ner i de brännande vulkaniska djupen, där de kan slaktas."}},faq={{q="Vad är Taragaman the Hungerer för slags demon?",a="Taragaman är en felguard, en brutal demonisk stormtruppssoldat i Burning Legion. Han använder tunga närstridsattacker och eldmagi mot inkräktare i Ragefire Chasms magmagrottor.",al={"vilken ras är taragaman","taragamans demonart","är taragaman en demon"}},{q="Är Taragaman the Hungerer ledare för Searing Blade-kulten?",a="Det är allmänt trott att Taragaman leder Searing Blade. Han är den mest fruktansvärda demoniska kraften i Ragefire Chasm, och unga försvarare från Horden skickas för att döda honom som sektens mästare. Klyftan kan rymma fler hemligheter än en enda felguard.",al={"vem leder searing blade","bestämmer taragaman","taragaman kultledare"}},{q="Varför vill Horden döda Taragaman?",a="Horden vill ha Taragaman död eftersom en aktiv demonisk närvaro frodas under dess huvudstad. Hans infernaliska fördärv hotar Orgrimmar inifrån, och att döda honom är avgörande för att säkra grottgångarna under gatorna.",al={"varför döda taragaman","uppdragslore om att döda odjuret","taragaman hot mot orgrimmar"}},{q="Var kan man hitta Taragaman?",a="Taragaman håller till djupt inne i Ragefire Chasm, i underjordiska vulkantunnlar som nås från Cleft of Shadow i Orgrimmar.",al={"taragamans plats","var finns taragaman","taragaman ragefire chasm"}},{q="Vad händer med Taragamans hjärta?",a="Segrande äventyrare skär ut Taragaman the Hungerer's Heart som bevis på bestens död och för att slutföra arbetet med att rensa den demoniska förtruppen under Orgrimmar.",al={"taragamans hjärta","hjärtat i uppdraget att döda odjuret","döda besten och ta dess hjärta"}},{q="Hur slåss Taragaman?",a="Taragaman anfaller med krossande fysiska slag, en kraftfull uppercut som slungar fiender genom luften och enstaka utbrott av Fire Nova som bränner dem i närheten.",al={"taragamans förmågor","bossstriden mot taragaman","taragamans stridsmekanik"}}},fx={["512c0cfb"]={q="Vems sida står Taragaman the Hungerer på?",a="Taragaman är allierad med Searing Blades kultister, som lurar under Orgrimmar och hotar Horde inifrån.",al={"taragamans fraktion","vem tjänar taragaman","tillhör taragaman searing blade"}},["1dbae35b"]={q="Varför är Taragaman the Hungerer i Ragefire Chasm?",a="Taragaman håller till i Ragefire Chasms brinnande djup och sprider demoniskt fördärv under Orgrimmar.",al={"varför är taragaman här","vad gör taragaman i ragefire","varför är taragaman i orgrimmar"}},["376a0125"]={q="Vem har Taragaman the Hungerer band till?",a="Taragaman är knuten till Searing Blade-kulten i Ragefire Chasm. För att upptäcka vem som styr dess planer måste du undersöka klyftan.",al={"vilka samarbetar taragaman med","taragamans allierade","taragaman bazzalan"}},["5af082b3"]={q="Varför fruktas Taragaman the Hungerer?",a="Taragaman fruktas som ett resligt demoniskt skräckväsen som lurar direkt under Hordes huvudstad. Hans demoniska inflytande hotar att fördärva Orgrimmars invånare, och hans brutala fysiska styrka har gjort honom ökänd bland de unga försvarare som skickas in i klyftan för att döda honom.",al={"varför är taragaman berömd","är taragaman farlig","varför fruktas taragaman"}}},fp="22,239,15.310.0,12.304.1,45.175.0,63.237.0,39.229.0,29.129.0,34.170.0,35.161.0"}
P.entries["npc:targorr-the-dread"] = {n="Targorr the Dread",s="Targorr the Dread är en ökänd bödel från Blackrock, inspärrad djupt inne i Stormwind Stockade. Han är känd för sin brutala tortyr av tillfångatagna soldater från Stormwind, men hans avrättning sköts upp på obestämd tid på grund av byråkratisk inkompetens och korruption. När The Stockade gjorde uppror under Defias Brotherhoods ledning bröt sig Targorr fri och slöt sig till de upproriska fångarna.",h="Targorr the Dread är en ökänd bödel från Blackrock, inspärrad djupt inne i Stormwind Stockade.",kw={"berton","blackrock","fruktad","bödel","gath'ilzogg","lakeshire","stockade","targorr"},ang={["faction:Alliance"]="När du oskadliggör Targorr i det upproriska The Stockade skipar du äntligen rättvisa åt Lakeshires fallna försvarare och hjälper till att hejda kaoset under huvudstaden.",["race:Human"]="För människorna i Stormwind, särskilt dem som har anknytning till Redridge, förkroppsligar Targorr det fruktansvärda priset för rikets byråkratiska misslyckanden och det fortsatta hotet från orkerna i Blackrock."},sec={{t="Redridges slaktare",b="Innan han tillfångatogs tjänstgjorde Targorr the Dread som den främste bödeln i Blackrock-klanen under krigsherren Gath'Ilzogg. Han verkade från de ockuperade ruinerna i Redridge, och hans grymhet var exceptionellt brutal även med Dark Hordes våldsamma mått mätt. Stormwind-vakter och milismän som kämpade för att försvara gränslandet utsattes för plågsam tortyr och en långsam död under hans hand, vilket gjorde honom till en av rikets mest hatade."},{t="Rättvisa som uteblev",b="När Alliansens styrkor till slut lyckades tillfångata Targorr levande fördes han i kedjor till huvudstaden och låstes in i den hårdbevakade Stockade i väntan på avrättning. Men förruttnelsen i Stormwinds rättsliga och politiska byråkrati satte käppar i hjulen. Förlamade av mutor, ändlösa pappershögar och försummelse misslyckades domstolarna med att utdöma det dödsstraff han förtjänat. En blodtörstig krigsförbrytare blev kvar i en cell under stadens hjärta."},{t="Uppror i cellerna",b="När Defias Brotherhood genomförde sin våldsamma fängelserymning såg Targorr sin chans. Han bröt sig ut ur sin cell och anslöt sig till Defias upprorsmakare, och förvandlade sitt cellblock till ett slakthus. Warden Thelwater har helt förlorat kontrollen över fängelset. I städer som Lakeshire, där försvararna fortfarande bär på de bittra såren efter Targorrs illdåd, söker man äventyrare som vågar ge sig in i upploppet och återvända med slaktarens huvud."}},faq={{q="Vem är Targorr the Dread?",a="Targorr the Dread är en ork från Blackrock som tjänstgjorde som främste bödel under krigsherren Gath'Ilzogg. Han är ökänd för att ha torterat tillfångatagna soldater från Stormwind och greps och fängslades i Stormwind Stockade.",al={"vem är targorr","targorrs historia","orkboss i stockade"}},{q="Varför avrättades inte Targorr när han tillfångatogs?",a="Targorr tillfångatogs och skulle ställas inför rätta, men Stormwinds ineffektiva, överdimensionerade och korrupta rättsväsende drog ut på processen. Hans avrättning försenades av ändlös byråkrati tills fängelseupploppen bröt ut.",al={"varför dödades han inte","varför lever targorr","korruption i stormwind"}},{q="Varför samarbetar en ork med Defias Brotherhood?",a="Targorr delar inte Defias Brotherhoods politiska missnöje, men under kaoset i fängelseupproret förenades fångar av alla slag mot sina fångvaktare. Han slöt sig till upprorsmakarna enbart för att säkra sin frihet och slakta vakter och äventyrare som kommer i hans väg.",al={"varför samarbetar defias med orker","targorr defias allierad","orker i stockade"}},{q="Vem vill se Targorr död nu?",a="Guard Berton, som är stationerad i Lakeshire i Redridge, erbjuder en belöning för Targorrs avhuggna huvud. Lakeshires invånare har lidit svårt av Targorrs grymhet och vill se honom avrättad, vilket Stormwinds domstolar misslyckades med.",al={"vem ger uppdraget om targorr","guard berton targorr","belöning för targorr"}},{q="Var hittar man Targorr?",a="Targorr finns i instansen Stormwind Stockade, där han barrikaderat sig i ett av de bakre cellblocken tillsammans med andra upproriska fångar.",al={"var finns targorr","targorrs plats","rum i stockade"}},{q="Vilken klan tillhör Targorr?",a="Targorr tillhör orkerna från Blackrock, en del av de förrymda resterna av Dark Horde som verkar från Redridge Mountains och Blackrock Spire, och inte den Nya Horden som leds av Thrall.",al={"targorrs klan","tillhör targorr horden","blackrock targorr"}}},fx={eed5e381={q="Varför är Targorr the Dread så fruktad?",a="Targorr fick sitt skräckinjagande rykte som den främste bödeln åt Blackrock-orcherna under general Gath'Ilzogg. Hans grymhet var ökänd även med klanens brutala mått mätt. I stället för att ge besegrade fiender en hedervärd död utsatte han tillfångatagna försvarare från Stormwind för hänsynslös tortyr på nyck, vilket gjorde honom ökänd bland folket i Redridge och i hela kungariket.",al={"varför fruktas targorr","targorr the dreads rykte","varför är targorr berömd"}}},fp="17,189,23.377.0,14.388.0,21.375.0,25.213.0,49.191.0,49.197.0,27.198.0,27.89.0,33.183.0"}
P.entries["npc:tarindrella"] = {n="Tarindrella",s="Tarindrella är en dryad som vakar över Shadowglens skyddade skogar på Teldrassil. Som dotter till Cenarius samarbetar hon nära med Night Elf-beskyddare för att undersöka den onaturliga fördärvelse som drabbat världsträdets djurliv.",h="Tarindrella är en dryad som vakar över Shadowglens skyddade skogar på Teldrassil.",kw={"aldrassil","dryad","shadowglen","shadowthread","tarindrella","teldrassil","webwood"},ang={["class:Druid"]="Druider håller dryader högt som vildmarkens besläktade andar, vilket gör Tarindrellas vägledning om Teldrassils sjukdom till en brådskande uppmaning att bevara balansen.",["race:NightElf"]="För unga Night Elves som börjar sin färd i Shadowglen är Tarindrella en av de första dryader de möter. Hon förkroppsligar den uråldriga överenskommelsen mellan Kaldorei och Cenarius barn."},sec={{t="En dotter till Cenarius i Shadowglen",b="Dryader är naturens stridslystna väktare, födda ur halvguden Cenarius. Många håller till djupt inne i Kalimdors uråldriga skogar, som Ashenvale, men Tarindrella bor i Shadowglens skyddade glänta bland Teldrassils grenar. Hon fungerar som en viktig länk mellan vildmarkens andar och unga Night Elf-försvarare som tar sina första steg utanför Aldrassil. Hennes främsta bekymmer är den kvardröjande smitta som sprider sig i skogen. Hon ger pålitliga äventyrare i uppdrag att driva bort skadedjur i trakten och samla ledtrådar om sjukdomens ursprung."},{t="Undersöker Teldrassils sjukdom",b="Trots Teldrassils storslagenhet som Night Elf-folkets nya krona döljer dess orörda lundar en oväntad sjukdom. De en gång fridsamma furbolgerna har lämnat sina hem och samlats i Gnarlpine-stammen, medan grells och grellkin som smittats av ondskefull Fel Moss härjar i kullarna kring Shadowglen. Tarindrella misstänker att Fel Moss ligger bakom förändringarna. Hon skickar initiater att möta grells och ta med prover tillbaka för att hejda fördärvelsen innan den kan ta över den unga lundens fristad."}},faq={{q="Vem är Tarindrella?",a="Tarindrella är en dryad som bor i Shadowglen bland Teldrassils grenar. Hon hjälper lokala Night Elves att hålla uppsikt över vildmarken och leder unga försvarare i kampen mot den märkliga sjukdom som hotar världsträdets grenar.",al={"tarindrella: berättelse","vem är tarindrella","dryad shadowglen"}},{q="Vad är en dryad?",a="Dryader är förtrollade skogsväsen och döttrar till halvguden Cenarius. De har en Night Elfs överkropp och en fawns underkropp och tjänar som hängivna väktare av Kalimdors heliga lundar och balans.",al={"dryad: berättelse","vad är dryader","cenarius döttrar"}},{q="Varför oroar sig Tarindrella för Shadowglen?",a="Även i Teldrassils trygga hjärta har en onaturlig fördärvelse börjat förvrida varelser i trakten. Den har drivit furbolgerna att samlas i den fientliga Gnarlpine-stammen och fyllt kullarna med grells som smittats av Fel Moss. Tarindrella vill rena området från smittan och skydda den unga lunden från fördärvelsens spridning.",al={"fördärvelse i shadowglen","tarindrellas uppdrag","vad är fel med shadowglen"}},{q="Vilka hot skickar hon äventyrare att möta?",a="Tarindrella ber om hjälp med att möta grells och grellkin som härjar i Shadowglen och samla in den ondskefulla Fel Moss de bär på, för att bekräfta om den ligger bakom fördärvelsen.",al={"tarindrella spindlar","shadowthread cave-uppdrag"}}},fx={af6c0001={q="Vems sida står Tarindrella på?",a="Tarindrella står med kaldorei och Cenarion Circle och skyddar naturen tillsammans med nattalverna. Som Cenarius dotter tjänar hon naturens balans och hjälper unga nattalvsäventyrare som ger sig ut för att försvara Teldrassil mot skada.",al={"tarindrellas fraktion","vem tjänar tarindrella","tarindrella alliance eller horde"}},d6824959={q="Vad vill Tarindrella?",a="Tarindrella vill hitta och rena det onaturliga fördärv som drabbar Teldrassils grenar. Hon ber dig undersöka det besmittade djurlivet i Shadowglen och bekämpa den mörka farsot som sprider sig genom skogens gläntor och lyor.",al={"vad vill tarindrella","tarindrellas mål","tarindrellas syfte"}},["05d535f9"]={q="Vem har Tarindrella band till?",a="Som dryad är Tarindrella dotter till halvguden Cenarius och släkt med lundens väktare och andra skogsandar på Kalimdor. Hennes band knyter henne djupt till nattalverna och druiderna som vördar hennes fars läror.",al={"tarindrellas familj","tarindrellas band","vem är tarindrella släkt med"}}},fp="11,170,36.496.0,37.457.0,19.185.0,16.176.0,46.228.0,47.176.0"}
P.entries["npc:tarrel-rockweaver"] = {n="Tarrel Rockweaver",s="Tarrel Rockweaver är en orolig dvärgmake som står på bron in mot Menethil Harbor. Han är djupt bekymrad för sin hustru Merrin, en arkeolog som gav sig inåt land med Whelgar's utgrävningsteam, och spanar längs vägen i hopp om nyheter om att hon är i säkerhet.",h="Tarrel Rockweaver är en orolig dvärgmake som står på bron in mot Menethil Harbor.",kw={"dvärg","utgrävningsteam","menethil harbor","merrin rockweaver","tarrel rockweaver","wetlands"},ang={["faction:Alliance"]="För resenärer som anländer till Menethils hamn erbjuder Tarrel en omedelbar inblick i de prövningar som möter alliansens invånare utposterade längs de otämjda träsken.",["race:Dwarf"]="Tarrels oro visar vilket farligt pris Explorer's Leagues obevekliga strävan att gräva fram dvärgarnas ursprung kräver vid Khaz Modans vilda gränstrakter."},sec={{t="Vakt på bron",b="Medan handel och militära leveranser passerar genom Menethil Harbor håller Tarrel Rockweaver orolig vakt vid bron i stadens utkant. Hans hustru, Merrin Rockweaver, följde med Prospector Whelgars ansedda arkeologiska expedition längre in i Wetlands. När våldsamma rovfåglar översvämmade utgrävningsplatsen och bröt den vanliga kommunikationen blev Tarrel kvar i staden. Han ber förbipasserande resenärer att undersöka området österut, mot Whelgar's Excavation Site, för att försäkra sig om att hon överlevde katastrofen."}},faq={{q="Vem är Tarrel Rockweaver?",a="Tarrel är en dvärg från Ironforge som nu dröjer sig kvar nära ingångsbron till Menethil Harbor. Han väntar desperat på besked om sin hustru Merrin, som gav sig av på en utgrävning inåt land.",al={"tarrel rockweaver","vem är den här dvärgen","dvärg vid menethil-bron"}},{q="Varför ber Tarrel resenärer om hjälp?",a="Han tappade kontakten med sin hustru Merrin efter att hennes arkeologiska team råkade ut för faror vid utgrävningsplatsen. Eftersom han inte kan lämna sin post ber han äventyrare på genomresa att bege sig österut, mot Whelgar's Excavation Site, och leta efter henne.",al={"tarrels uppdrag","på jakt efter utgrävningsteamet","tarrel rockweavers uppdrag"}},{q="Vem är Merrin Rockweaver?",a="Merrin Rockweaver är Tarrels hustru och arkeolog i Prospector Whelgars utgrävningsteam. Hon överlevde ett angrepp på lägret och tog skydd tillsammans med de överlevande i en grotta med utsikt över utgrävningsplatsen.",al={"merrin rockweaver","tarrels hustru","vem är merrin"}},{q="Vart begav sig Tarrels hustru?",a="Merrin reste österut in i Wetlands för att studera uråldriga titanreliker och dvärgreliker. Efter att deras huvudsakliga utgrävningsplats attackerats tog hon och de överlevande utgrävarna skydd i en grotta med utsikt över den förstörda utgrävningen.",al={"var är merrin","utgrävningsteamets plats","whelgars gömställe"}}},fx={["89989482"]={q="Varför är Tarrel Rockweaver här i Menethil Harbor?",a="Tarrel väntar på bron som leder in till Menethil Harbor för att hejda förbipasserande äventyrare. Vilda rovfåglar, mörka järndvärgar och fientliga troggar härjar i våtmarkerna, så han håller sig nära hamnen och hoppas kunna värva modiga resenärer som kan undersöka vad som hänt hans försvunna hustru.",al={"varför är tarrel rockweaver här","varför är tarrel på bron"}},["017f26af"]={q="Vems sida står Tarrel Rockweaver på?",a="Tarrel är en lojal dvärgmedborgare i Ironforge och står stadigt med Alliance. Han håller till strax utanför Menethil Harbor och förlitar sig på förbipasserande Alliance-resenärer för att hålla uppsikt över hans fränder bland träskets faror.",al={"tarrel rockweavers fraktion","är tarrel rockweaver med i alliance"}}},fp="17,179,21.421.0,25.159.0,40.198.0,25.217.1,27.203.1"}
P.entries["npc:tatternack-steelforge"] = {n="Tatternack Steelforge",s="Vid gränsen till The Barrens erbjuder Tatternack Steelforge arbete åt resenärer som kan hantera rå metall och farliga vilda djur. Orcsmeden studerar lokala malmer och försöker beväpna Hordens styrkor mot hoten över slätterna.",h="Vid gränsen till The Barrens erbjuder Tatternack Steelforge arbete åt resenärer som kan hantera rå metall och...",kw={"the barrens","smed","camp taurajo","crossroads","malm","steelforge","tatternack"},ang={["faction:Horde"]="Tatternack hjälper till att hålla Hordens styrkor beväpnade och försedda med utrustning mot hot som quilboar och centaur.",["profession:Blacksmithing"]="För smeder som färdas genom The Barrens förstår Tatternack behovet av god malm och kvalitetsstål i ett laglöst gränsland."},sec={{t="En orc vid smedjan",b="Över hela The Barrens behöver Hordens utposter vapen för att möta vilda bestar, centaurplundrare och fientliga quilboar. Tatternack Steelforge för sitt folks kunskaper i metallarbete till gränslandet. Han söker praktiska vapen och ovanliga geologiska prover för att stärka Hordens fotfäste mot dessa hot."}},faq={{q="Vem är Tatternack Steelforge?",a="Tatternack Steelforge är en orcisk vapensmed stationerad i The Barrens. Han hjälper till att förse Hordens försvarare genom att undersöka mineraler, studera lokala malmer och se till att närliggande krigare får pålitliga vapen.",al={"vem är tatternack","tatternack steelforge bakgrund","vad gör tatternack"}},{q="Var finns Tatternack Steelforge?",a="Tatternack verkar i The Barrens och bor bland Hordens läger längs savannens centrala stigar.",al={"var finns tatternack","tatternack steelforge plats","tatternack koordinater"}},{q="Vilka slags uppgifter erbjuder Tatternack?",a="Tatternack ber resenärer att återvinna vapen och ta med färska malmprover från trakten kring The Barrens till hans smidesarbete.",al={"tatternacks uppdrag","uppdragsgivare för vapen efter eget val","uppdrag med malmprov"}}},fp="21,218,19.307.0,29.204.0,41.96.0,41.122.0"}
P.entries["npc:tavernkeep-smitts"] = {n="Tavernkeep Smitts",s="Tavernkeep Smitts är bartender på Scarlet Raven Tavern i Darkshire. Som verksam i Duskwoods sociala centrum har Smitts encyklopediska kunskaper om stadens skvaller och olösta lokala tragedier. Hans långa minne och skarpa blick gör honom till en ovärderlig kontakt för alla som undersöker regionens mörka historia.",h="Tavernkeep Smitts är bartender på Scarlet Raven Tavern i Darkshire.",kw={"darkshire","duskwood","haggard","jitters","scarlet raven","smitts","stalvan","värdshusvärd","zombie juice"},ang={["class:Rogue"]="Rogues som undersöker gamla fall och skuggfigurer får en idealisk informatör i Smitts. Han lägger märke till vad gästerna skriver, när de grips av panik och vad de lämnar efter sig.",["faction:Alliance"]="För Alliance-resenärer som kommer ut ur de skuggiga skogarna erbjuder Smitts inte bara skydd och dryck, utan också viktig lokal information om hoten som hemsöker Duskwood."},sec={{t="Darkshires hjärta",b="Bakom bardisken på Scarlet Raven Tavern erbjuder Tavernkeep Smitts en varm brasa och dryck åt trötta resenärer, lokalbefolkningen och nervösa vakter ur Night Watch som trotsar Duskwoods faror. Som ett av stadens mest långvariga offentliga ansikten hör Smitts varje rykte som sipprar genom dunklet. Medan andra stadsbor hukar bakom låsta fönsterluckor håller Smitts ett pragmatiskt, uppmärksamt öga på alla som passerar hans dörr och lägger märke till ovanligt beteende, brådskande avfärder och märkliga gäster."},{t="Stalvans minne",b="Smitts har i åratal i tysthet följt legenden om Stalvan Mistmantle. När en besökande familj av adelsfolk från Stormwind slaktades för många år sedan följde Smitts med Marshal Haggard för att undersöka platsen för blodbadet. Smitts hittade sönderrivna, leriga dagbokssidor bland förödelsen, men utredarna kunde då aldrig formellt knyta handstilen till Stalvan. Smitts behöll de bleknade fragmenten i åratal, övertygad om att den dystra sanningen till slut skulle komma fram."},{t="Den skuggfulle gästen",b="Smitts uppmärksamhet sträcker sig även till dagens hot. När den skräckslagne eremiten Jitters tog sin tillflykt till Scarlet Raven såg Smitts hur han febrilt klottrade i en personlig dagbok innan han flydde från värdshuset i blind panik. När en utredare hittar den övergivna dagboken känner Smitts genast igen boken och visar spåraren mot Raven Hill, vilket hjälper till att nysta upp de förbannade händelser som hemsöker skogen."}},faq={{q="Var hittar jag Tavernkeep Smitts?",a="Smitts står bakom disken på bottenvåningen i Scarlet Raven Tavern, det centrala värdshuset på torget i Darkshire.",al={"smitts plats","var finns tavernkeep smitts","scarlet raven bartender"}},{q="Vad vet Smitts om Stalvan Mistmantle?",a="För många år sedan följde Smitts med Marshal Haggard för att utreda slakten av besökande adelsfolk. Smitts hittade leriga, sönderrivna sidor på platsen och sparade dem. Om du visar nya bevis som knyter Stalvan till brottet lämnar Smitts över de leriga dagbokssidorna så att de kan överlämnas till Commander Althea Ebonlocke.",al={"smitts stalvan","stalvans legend smitts","leriga sidor stalvan"}},{q="Vad vet Smitts om Jitters?",a="Jitters bodde en tid på Scarlet Raven Tavern, där Smitts såg honom skriva frenetiskt i en dagbok innan han flydde i skräck. När du tar med Jitters dagbok tillbaka till värdshuset känner Smitts igen den och visar dig västerut mot Raven Hill för att spåra upp honom.",al={"smitts jitters","jitters dagbok smitts","fråga efter smitts på värdshuset"}},{q="Vilka drycker brygger eller efterfrågar Smitts?",a="Smitts hjälper till att skaffa ingredienser till lokala brygder, bland annat genom att skicka äventyrare in i de förbannade vildmarkerna efter Rot Blossoms för att brygga en stark lokal blandning som i folkmun kallas Zombie Juice.",al={"zombie juice","smitts rot blossoms","smitts brygd"}},{q="Vem är Marshal Haggard, och hur känner Smitts honom?",a="Marshal Haggard är en gammal veteran från Stormwind Guard som bor i en avskild stuga i bergen. Han och Smitts arbetade tillsammans för många år sedan med att utreda de grymma morden på adelsfolk och knöt band genom det olösta fallet.",al={"smitts haggard","kopplingen till haggard"}},{q="Har Smitts någon känd familj i Darkshire?",a="Ingen som någon talar om. Smitts sköter Scarlet Raven på egen hand, och inga släktingar till honom är kända i Darkshire.",al={"smitts släktingar","mary smitts"}}},fx={["9f4b5837"]={q="Vem är Tavernkeep Smitts?",a="Tavernkeep Smitts driver Scarlet Raven Tavern i Darkshire. Förutom att hälla upp drycker och servera gäster som söker skydd undan Duskwoods dunkel fungerar han som en informell historiker för staden. Efter att ha iakttagit både resenärer och invånare i åratal håller Smitts öronen öppna för lokalt skvaller, mörk folktro och gamla tragedier som fortfarande hemsöker trakten.",al={"vem är smitts","tavernkeep smitts","värdshusvärd i darkshire"}},["657fa8c4"]={q="Vilken sida står Tavernkeep Smitts på?",a="Smitts står stadigt på Darkshires och Alliansens sida. Han samarbetar nära med lokala försvarare som Marshal Haggard och hänvisar äventyrare till Commander Althea Ebonlocke och Night Watch när hot dyker upp. Han gör vad han kan för att skydda sitt hårt prövade samhälle från de många fasor som smyger genom skogarna runt omkring.",al={"smitts fraktion","smitts lojalitet","är smitts med i alliansen"}},["32ff845a"]={q="Varför är Tavernkeep Smitts här?",a="Smitts försörjer sig på att driva Scarlet Raven Tavern, den centrala samlingsplatsen för Darkshires utmattade invånare och förbiresande. Tavernan placerar honom mitt i flödet av lokala rykten, så han får följa mysterierna och tragedierna som plågar Duskwood på nära håll.",al={"varför är smitts i darkshire","varför är smitts på värdshuset"}}},fp="17,211,18.466.0,21.362.1,18.355.1,35.109.0,47.279.1,36.248.1,40.166.0,53.203.0,47.122.0"}
P.entries["npc:telf-joolam"] = {n="Telf Joolam",s="Vid Shrine of the Dormant Flame leder Telf Joolam Hordens adepter genom eldens prövningar. Darkspear-shamanen lär dem att stå i förbindelse med och befalla över det oberäkneliga elementet.",h="Vid Shrine of the Dormant Flame leder Telf Joolam Hordens adepter genom eldens prövningar.",kw={"the barrens","call of fire","darkspear","durotar","fire sapta","schaman","shrine of the dormant flame","telf joolam"},ang={["class:Shaman"]="Som shaman följer du Telf Joolams vägledning genom Fire Sapta-prövningarna och lär dig att bemästra din Fire Totem.",["faction:Horde"]="Som medlem av Horden ser du hur äldste som Telf skyddar heliga elementhelgedomar över hela gränslandet och stärker Hordens andliga rötter.",["race:Troll"]="Som troll ser du en Darkspear-äldste vägleda adepter i shamanismens seder, som delas av hela Horden."},sec={{t="Flammans väktare",b="Telf Joolam vårdar Shrine of the Dormant Flame bland klipporna med utsikt över gränslandet. Eldandar kräver sträng disciplin och orubbligt fokus, till skillnad från jordens lugna visshet eller vattnets tålmodiga djup. Telf förbereder unga shamaner för prövningar som sätter deras värde på prov innan de vilda glöden slukar dem."},{t="Eldens väg",b="Under Telfs ledning brygger och dricker adepterna en rituell Fire Sapta, som öppnar deras dödliga ögon för de osynliga elementplanen. Han skickar upp dem till de klippiga topparna för att möta brinnande andar. De som förtjänar elden måste respektera dess glupska hunger och stå emot vårdslös stolthet."}},faq={{q="Vem är Telf Joolam?",a="Telf Joolam är en Darkspear-trollshaman som vårdar Shrine of the Dormant Flame. Han vägleder unga shamaner som söker stå i förbindelse med elden.",al={"telf joolam","vem är telf","troll vid shrine of the dormant flame"}},{q="Var finns Telf Joolam?",a="Telf Joolam finns vid Shrine of the Dormant Flame, högt uppe längs den klippiga åsen mellan Durotar och The Barrens.",al={"telf joolam plats","var finns telf","hitta telf joolam"}},{q="Vad ska Fire Sapta han ber om användas till?",a="Fire Sapta öppnar adeptens andliga syn och låter dem uppfatta och tala med elementandar av eld, som är osynliga för dödliga sinnen.",al={"vad är fire sapta","fire sapta användning","varför dricka sapta"}},{q="Vilket element lär Telf Joolam ut?",a="Telf Joolam lär ut eldens element och prövar shamanernas styrka och vilja att kontrollera lågan utan att ge efter för dess destruktiva natur.",al={"vilket element lär telf ut","telf joolams element","uppdragsgivare för fire totem"}},{q="Varför vakar en troll över schamanriter här?",a="Sedan de anslöt sig till Thralls Horde har många Darkspear-troll börjat utöva shamanism tillsammans med orcher och taurer. Erfarna shamaner som Telf vägleder nästa generation.",al={"varför trollschaman","darkspears schamanism"}},{q="Vad händer när du har slutfört Telf Joolams uppgifter?",a="När adepterna har bevisat att de behärskar eldandarna på den närliggande toppen får de kunskapen och välsignelsen som krävs för att smida sin permanenta Fire Totem.",al={"belöning från call of fire","vad ger telf dig"}}},fx={["6bc0eb27"]={q="Vilken sida står Telf Joolam på?",a="Telf Joolam står stolt med Horden och Darkspear-stammen. Som vördad shamanvårdare är han trogen Thralls nya shamantraditioner och vägleder orc- och trolladepter som följer elementens väg.",al={"telf joolams fraktion","tillhör telf joolam horden","telf joolams lojalitet"}},["6f75c3b9"]={q="Vad vill Telf Joolam?",a="Telf Joolam vill pröva blivande shamaner som söker gemenskap med elden. Han ger adepterna i uppdrag att samla ingredienser till en Fire Sapta och kräver bevis på beslutsamhet och harmoni innan han låter dem få kontakt med den slumrande elementarelden.",al={"telf joolams mål","vad vill telf","varför prata med telf joolam"}},b42da7bb={q="Vilka har Telf Joolam band till?",a="Telf Joolam samarbetar med shamantränarna i Durotar och The Barrens och spelar en viktig roll i Call of Fire-prövningarna. Genom sina heliga plikter vid helgedomen tjänar han Hordens större andliga pånyttfödelse.",al={"telf joolams kontakter","vilka samarbetar telf med","telf joolams allierade"}}},fp="11,182,19.317.0,16.272.0,19.137.0,31.120.0,50.140.0,36.135.0,46.159.0,50.150.0"}
P.entries["npc:tenaron-stormgrip"] = {n="Tenaron Stormgrip",s="Tenaron Stormgrip är en Night Elf-guide högt uppe i Aldrassil, Shadowglens centrala träd. Han lär unga kaldorei om folkets närhistoria och ber dem samtidigt hämta vatten från en månskälla.",h="Tenaron Stormgrip är en Night Elf-guide högt uppe i Aldrassil, Shadowglens centrala träd.",kw={"aldrassil","cenarion circle","crown of the earth","månskälla","shadowglen","stormgrip","teldrassil","tenaron"},ang={["class:Druid"]="Tenarons uppgifter visar vilket druidiskt förvaltarskap som krävs för att hålla uppsikt över Teldrassils exempellösa tillväxt och skydda det mot subtilt fördärv.",["race:NightElf"]="För unga Night Elves är Tenaron Stormgrip en av de allra första som introducerar dem till de gemensamma och andliga plikter som krävs för att hålla Teldrassil vid liv och rent."},sec={{t="Aldrassils väktare",b="Tenaron Stormgrip sitter på Aldrassils slingrande träplattformar och är en av de första mentorerna för unga Night Elves som lämnar Shadowglens grenar. Från sin utsiktsplats håller han uppsikt över skogens hälsa och de livsviktiga månskällor som håller den vid liv. Hans uppgift är att lära nykomlingar att förstå deras djupa andliga band till Världsträdet."},{t="Crown of the Earth",b="Tenaron inleder färden som kallas Crown of the Earth. Han skickar noviser för att hämta en flaska vatten från månskällan norr om Aldrassil och lär dem vad som följde efter slaget vid Mount Hyjal. Färden fortsätter genom Teldrassil och vidare till Darnassus."}},faq={{q="Var finns Tenaron Stormgrip?",a="Tenaron Stormgrip står högst upp på Aldrassils träbyggda ramper, i det väldiga centrala trädet i hjärtat av Shadowglen på Teldrassil.",al={"tenarons plats","var är tenaron","tenaron stormgrips plats"}},{q="Vilken roll har Tenaron Stormgrip i Shadowglen?",a="Han vägleder unga Night Elves och berättar om följderna av slaget vid Mount Hyjal genom färden Crown of the Earth.",al={"vad gör tenaron","tenaron stormgrips uppgift","vem är tenaron"}},{q="Vad är uppdraget Crown of the Earth?",a="Tenaron ber noviser hämta vatten från en månskälla i en flaska och återvända med den. Färden lär dem om Night Elves närhistoria och fortsätter över Teldrassil.",al={"crown of the earth bakgrund","varför bära vatten från månskällan"}},{q="Varför oroar sig Tenaron för Teldrassils vatten?",a="Månskällorna är viktiga kärl för Elunes nåd och naturens renhet. Eftersom Teldrassil är ungt och saknar Aspekternas fulla välsignelse håller förvaltare som Tenaron noga uppsikt över varje vattenkälla för att upptäcka tecken på fördärv eller orenhet.",al={"varför är vattnet värdefullt","teldrassils vattenproblem"}},{q="Skickar Tenaron äventyrare bortom Shadowglen?",a="Ja. När en novis visar vördnad och skicklighet i hanteringen av det heliga vattnet skickar Tenaron dem vidare ut i det större Teldrassil, ned till Dolanaar, för att fortsätta tjäna kaldorei.",al={"tenarons nästa uppdrag","vart skickar tenaron dig"}},{q="Är Tenaron druide eller präst?",a="Hans klass fastställs inte av källorna. Han undervisar om Night Elves närhistoria och förklarar månskällornas betydelse.",al={"tenaron stormgrips klass","är tenaron druide"}}},fx={["594d14e3"]={q="Vilken sida står Tenaron Stormgrip på?",a="Tenaron är helt hängiven nattalverna i Darnassus och Teldrassils väl. Han arbetar tillsammans med druiderna och prästerna som vårdar det stora trädet och vägleder unga försvarare som träder fram ur Aldrassil för att skydda sitt hemland och tjäna Alliansen.",al={"tenarons fraktion","är tenaron med i alliansen","vem tjänar tenaron"}},["4431413b"]={q="Vad vill Tenaron Stormgrip?",a="Tenaron vill vårda och skydda Teldrassil från fördärvet som sprider sig bland dess grenar. Han vakar över Shadowglens vatten och ber lovande äventyrare samla månbrunnsvatten medan de lär sig sitt folks senaste historia, så att det stora trädet kan frodas.",al={"vad vill tenaron","tenarons mål","tenaron stormgrips uppdrag"}},["62d582e4"]={q="Varför är Tenaron Stormgrip här?",a="Tenaron är stationerad högt uppe i det stora trädet Aldrassil och vakar över hjärtat av Shadowglen. Han stannar här för att bedöma nya nattalvsadepter, övervaka det heliga vatten som ger trädets grenar näring och samordna de första stegen för att bevara Teldrassils spirande tillväxt.",al={"varför är tenaron i aldrassil","varför är tenaron här","tenarons roll i shadowglen"}}},fp="17,151,20.238.0,18.224.0,35.113.0,47.123.0,37.142.0,51.238.0,48.105.0,31.115.0"}
P.entries["npc:terenthis"] = {n="Terenthis",s="Terenthis är en Night Elf-druid som är stationerad i kustbosättningen Auberdine. Som representant för Cenarion Circle undersöker han den alarmerande korruption som sprider sig genom Darkshore och Teldrassil. Han tar hjälp av dugliga resenärer för att bedöma de växande hoten längs kusten och bistå lokala allierade som fastnat bland korrumperade vilda djur.",h="Terenthis är en Night Elf-druid som är stationerad i kustbosättningen Auberdine.",kw={"auberdine","cenarion circle","darkshore","fel moss","furbolg","grimclaw","terenthis","volcor"},ang={["class:Druid"]="Som broder i Cenarion Circle står Terenthis i frontlinjen mot den onaturliga korruption som sprider sig från Teldrassil till fastlandet.",["race:NightElf"]="Terenthis visar kaldoreiernas engagemang för att rena sina heliga marker från kvardröjande fördärv och skydda oskyldigt skogsliv."},sec={{t="Undersöker fördärvet",b="Terenthis skickades till Auberdine av Cenarion Circle och fokuserar på att spåra hur Fel Moss och andra korrumperande krafter sipprar in i Darkshore från Teldrassil. Night Elves ser med stor oro på denna krypande farsot och fruktar att den vilda balansen i norra Kalimdor kan rubbas helt om den inte hejdas. Terenthis försöker hitta orsakerna till förruttnelsen och komma på sätt att stoppa den innan den slukar skogarna."},{t="En vädjan från Grimclaw",b="Terenthis fungerar också som kontaktperson vid akuta nödlägen ute i fält. När den trogna björnen Grimclaw kommer skadad och ensam till Auberdine inser Terenthis att björnens ägare, druiden Volcor, har råkat illa ut. Eftersom han inte kan lämna sin post skickar Terenthis förbipasserande äventyrare ut i vildmarken för att hitta Volcor, som har överfallits och hålls fast av aggressiva furbolgstammar."}},faq={{q="Vem är Terenthis?",a="Terenthis är en Night Elf-druid som tillhör Cenarion Circle och för närvarande bor i hamnstaden Auberdine i Darkshore.",al={"terenthis historia","vem är terenthis","terenthis auberdine"}},{q="Varför är Terenthis i Auberdine?",a="Han skickades dit för att undersöka hur långt Fel Moss och magisk korruption har spridit sig från Teldrassil till Darkshore och hitta ett sätt att sätta stopp för farsoten.",al={"vad gör terenthis","terenthis uppgift","varför är terenthis här"}},{q="Vad gör björnen bredvid Terenthis där?",a="Björnen Grimclaw sökte upp Terenthis i Auberdine för att få hjälp efter att hans ägare, druiden Volcor, hade attackerats och skadats av fientliga furbolger.",al={"terenthis björn","grimclaw","varför finns det en björn i auberdine"}},{q="Vilken organisation tillhör Terenthis?",a="Terenthis är medlem i Cenarion Circle, en druideorden som har som uppgift att bevara balansen och skydda naturen i Kalimdor.",al={"terenthis fraktion","tillhör terenthis cenarion circle"}},{q="Vilka hot oroar Terenthis mest?",a="Han oroar sig främst för korruptionen från Fel Moss som drabbar traktens vilda djur, liksom för de lokala furbolgstammarnas växande fientlighet, som hotar både resenärer och druider.",al={"korruption i darkshore","hotet från fel moss","terenthis oro"}},{q="Ger Terenthis äventyrare några uppdrag?",a="Ja. Han skickar äventyrare för att bedöma hoten längs kusten, samarbeta med andra druider som Thundris Windweaver och rädda Volcor.",al={"terenthis uppdrag","vad vill terenthis"}}},fx={ba1c722a={q="Vad vill Terenthis?",a="Terenthis vill fastställa hur omfattande Fel Moss-fördärvet som sprider sig i Darkshore är och ta reda på varför Teldrassil och vildmarken runt omkring drabbas av smitta. I slutändan vill han rena bort den krypande pesten och återställa balansen i skogen innan fördärvet slår rot för gott.",al={"terenthis mål","vad försöker terenthis göra","terenthis motiv"}}},fp="9,209,23.310.0,20.296.1,17.89.0,30.166.0,46.146.0,43.124.0,46.131.0,46.99.0"}
P.entries["npc:teronis-corpse"] = {n="Teronis' Corpse",s="Teronis' Corpse ligger på en avskild ö i Lake Falathim i västra Ashenvale. Före sin alltför tidiga död skickades denna Night Elf-spejare från Astranaar på ett viktigt uppdrag för att återfinna Dartol's Rod och hjälpa till att rena skogen.",h="Teronis' Corpse ligger på en avskild ö i Lake Falathim i västra Ashenvale.",kw={"ashenvale","astranaar","dartol's rod","lake falathim","murloc","raene wolfrunner","teronis","teronis' corpse"},ang={["faction:Alliance"]="Att hedra Astranaars spejares offer innebär att fortsätta deras oavslutade arbete med att rena landet från det annalkande fördärvet.",["race:NightElf"]="Att hitta Teronis fallen i vildmarken är en dyster påminnelse om hur farligt Ashenvale har blivit, även för erfarna vaktposter och spejare."},sec={{t="En spejares dystra öde",b="Teronis skickades ut av Raene Wolfrunner från bosättningen Astranaar med uppdraget att återfinna Dartols förlorade stav, en uråldrig Night Elf-relik som kunde rena korrumperad skogsmagi. Hans sökande förde honom djupt ut i Lake Falathims vatten, men färden blev dödlig när fientliga murlocs svärmade över ön. Teronis stupade i strid och lämnade sin dagbok efter sig, medan sjöns aggressiva groddjur plundrade stavens strålande ädelsten."}},faq={{q="Vem var Teronis?",a="Teronis var en Night Elf-spejare som skickades ut från Astranaar av vaktposten Raene Wolfrunner. Han fick i uppdrag att hämta Dartol's Rod, en gammal artefakt som behövdes för att rena Ashenvales jord och vatten från demonisk fördärvning.",al={"vem är teronis","teronis bakgrund","teronis identitet"}},{q="Hur dog Teronis?",a="Teronis överfölls och dödades av de aggressiva murlocs som hemsöker stränderna och vattnen i Lake Falathim när han försökte säkra stavens delar.",al={"vem dödade teronis","teronis dödsorsak","hur dog han"}},{q="Var finns hans förlorade ädelsten?",a="Efter att Teronis dödats tog de lokala murlocs som håller till kring Lake Falathim den lysande ädelsten som satt högst upp på Dartol's Rod.",al={"var finns ädelstenen","förlorad ädelsten","teronis ädelsten"}},{q="Varför är det så viktigt för Astranaar att återuppta hans uppdrag?",a="Ashenvales djurliv och skogstjärnar drabbas allt hårdare av vidrig demonisk och felbesmittelse. Dartol's Rod har en inneboende renande kraft som vaktposterna hoppas ska kunna hejda eller vända denna ihållande förruttnelse.",al={"varför hjälpa raene","dartols stav syfte"}}},fx={["6a989bf2"]={q="Vilken sida stod Teronis på?",a="Teronis tjänade Ashenvales nattalver och Alliansen. Raene Wolfrunner skickade honom från Astranaar, och hans lojalitet låg hos försvaret och reningen av hans folks heliga skog.",al={"teronis fraktion","teronis liks sida","är teronis med i alliansen"}},["7cdf0db0"]={q="Vad ville Teronis innan han dog?",a="Teronis sökte efter de förlorade delarna av Dartol's Rod, särskilt en ädelsten som gömts i Lake Falathim. Han hoppades att dess magi kunde hjälpa hans folk att rena bort det mörka fördärv som spred sig över Ashenvale.",al={"teronis uppdrag","teronis mål","vad gjorde teronis"}},["7065b032"]={q="Varför ligger Teronis lik vid Lake Falathim?",a="Sökandet efter Dartol's Rod förde honom till ön i Lake Falathim, där han trodde att en viktig ädelsten fanns. De fientliga murlocerna i vattnet övermannade och dödade honom innan han hann återvända till Astranaar.",al={"varför är teronis här","varför ligger hans kropp vid sjön","teronis och lake falathim"}},["2ab2ec0c"]={q="Vilka hade Teronis band till?",a="Teronis rapporterade direkt till Raene Wolfrunner i Astranaar. Det var Raene som skickade honom till Lake Falathim för att återfinna Dartol's Rod, och hennes kvarvarande oro får resenärer att söka efter hans kvarlevor.",al={"vem skickade teronis","teronis och raene wolfrunner","vem arbetar teronis för"}}},fp="15,158,19.360.0,16.187.0,20.107.0,27.117.0,56.159.0"}
P.entries["npc:thadius-grimshade"] = {n="Thadius Grimshade",s="Thadius Grimshade är en Wildhammer-dvärg och spåman som bor i magikertornet i Nethergarde Keep i Blasted Lands. Han lämnade Aerie Peak för länge sedan för att studera esoterisk och mörkare magisk konst, men i hjärtat är han fortfarande lojal mot sitt folk.",h="Thadius Grimshade är en Wildhammer-dvärg och spåman som bor i magikertornet i Nethergarde Keep i Blasted...",kw={"blasted lands","spåman","nekrum gutchewer","nethergarde keep","sharpbeak","thadius grimshade","wildhammer"},ang={["class:Mage"]="Magiker som besöker Nethergarde känner igen Thadius som utövare av sällsynta, esoteriska spådomsmetoder, villig att undersöka trollreliker för att bemästra magi som ger lång livslängd.",["race:Dwarf"]="Andra dvärgar tycker att Thadius är en märklig syn bland Wildhammers. I stället för att sväva fram på gryfoner tillbringar han sina år försjunken i arkanisk forskning i en människofästning."},sec={{t="En Wildhammer i ödemarken",b="Till skillnad från de flesta Wildhammer-dvärgar, som föredrar The Hinterlands öppna himmel och dånande vindar, har Thadius Grimshade sitt hem innanför Nethergarde Keeps murar. Törsten efter arkansk spådomskonst och mörkare mystisk kunskap drev honom till utkanten av de besudlade Blasted Lands för att ägna sig åt sina esoteriska studier. Trots sin grubblande disciplin och avskildhet från klanen hyser han fortfarande stor kärlek till sitt hemland och gryfonerna, och erbjuder sina sällsynta skådarkrafter till dem som söker hjälp för Aerie Peaks räkning."},{t="Spådomens pris",b="När Gryphon Master Talonaxe försöker hitta den tillfångatagna gryfonen Sharpbeak får Thadius utföra en spådomsritual med en av besten fjädrar. Hans magiska insikt kommer med ett pris: Thadius kräver medallionen som bärs av trollnekromantikern Nekrum Gutchewer. Han vill avslöja dess hemlighet bakom onaturligt lång livslängd utan att drabbas av dess skadliga fördärvande krafter. I utbyte mot artefakten genomborrar han slöjan kring Jintha'Alor och avslöjar var Sharpbeak hålls fången."}},faq={{q="Vem är Thadius Grimshade?",a="Han är en excentrisk Wildhammer-dvärgmagiker och spåman som är stationerad i Nethergarde Keep. Han lämnade sitt hem i bergen för att ägna sig åt mörkare, okonventionell magisk konst långt i söder.",al={"thadius grimshade","vem är thadius","thadius npc"}},{q="Var hittar man Thadius Grimshade?",a="Han bor i det höga trollkarlstornet i Nethergarde Keep, ett fäste för Alliansen i norra delen av Blasted Lands.",al={"thadius plats","var finns thadius grimshade","thadius blasted lands"}},{q="Varför vill han ha Nekrum's Medallion?",a="Thadius vill studera medallionen som Nekrum Gutchewer bär för att förstå hur dess magiska kraft skänker ett långt liv. Han hoppas kunna få samma livslängd utan att drabbas av dess olycksbådande bieffekter.",al={"nekrums medallion thadius","varför thadius vill ha medallionen","nekrum gutchewers medallion"}},{q="Hur hjälper han till att hitta Sharpbeak?",a="Med en fjäder från den försvunna gryfonen och kraften från Nekrum's Medallion utför Thadius en skådningsritual som avslöjar att Sharpbeak hålls fången på höjderna i Jintha'Alor i The Hinterlands.",al={"thadius sharpbeak","spå sharpbeak","uppdraget hitta sharpbeak"}}},fp="17,248,26.515.0,23.495.1,25.169.0,37.138.0,36.197.0,32.205.1"}
P.entries["npc:thalia-amberhide"] = {n="Thalia Amberhide",s="Thalia Amberhide är en tauren som bor vid Freewind Post i den karga ravinen Thousand Needles. Hon är lojal mot sitt folk och väntar alltmer oroligt på att Lakota Windsong ska återvända oskadd från Grimtotem-klanens klor.",h="Thalia Amberhide är en tauren som bor vid Freewind Post i den karga ravinen Thousand Needles.",kw={"arnak grimtotem","freewind post","grimtotem","lakota windsong","thalia amberhide","thousand needles"},ang={["faction:Horde"]="Freewind Post är en viktig Horde-utpost i Thousand Needles, och genom att hjälpa Thalia skyddar du bosättningen mot Grimtotem-klanens angrepp.",["race:Tauren"]="För tauren-resenärer innebär hjälpen till Thalia och räddningen av Lakota ett direkt slag mot Grimtotem-stammens mörka förräderi och försvarar deras folk mot splittring inom klanen."},sec={{t="En vän vid utposten",b="Högt uppe på Freewind Posts mäktiga klippor finns Thalia Amberhide, en stillsam närvaro bland den livliga tauren-bosättningen. Hon oroar sig djupt för sin nära vän Lakota Windsong, som tillfångatogs av Arnak Grimtotem och hans förrädiska släkt. Thalia förlitar sig på förbipasserande äventyrare från Horde, som vågar sig ner i ravinens djup för att hitta Lakota, befria henne och tryggt leda henne uppför hissarna till mesans fristad."}},faq={{q="Vem är Thalia Amberhide?",a="Thalia Amberhide är en tauren som bor vid Freewind Post i Thousand Needles. Hon är en trogen vän till Lakota Windsong, en annan tauren som råkat i klorna på den förrädiska Grimtotem-klanen.",al={"thalia amberhide","vem är thalia"}},{q="Var kan Thalia Amberhide hittas?",a="Hon finns uppe på Freewind Posts höga mesa, mitt i Thousand Needles. Resenärer måste ta de väldiga trädrivna hissarna från ravinens botten för att nå bosättningen.",al={"thalias plats","var finns thalia amberhide"}},{q="Hur är Thalia släkt med Lakota Windsong?",a="Thalia är nära vän med Lakota Windsong. När Lakota tillfångatas av Arnak Grimtotem tar Thalia emot äventyraren vid Freewind Post efter att denne har hjälpt Lakota att fly från sina fångvaktare.",al={"thalia och lakota","vem är lakota windsong"}}},fx={["29deb6ad"]={q="Vilken sida står Thalia Amberhide på?",a="Thalia Amberhide är lojal mot Horden och sina taurenfränder. Hon bor vid Freewind Post i Thousand Needles, välkomnar Hordens äventyrare som färdas över de vindpinade platåerna och står fast mot fientliga fraktioner som hotar de lokala stammarna.",al={"thalia amberhides fraktion","tillhör thalia amberhide horden","thalia, horden eller alliansen"}},["80c269cc"]={q="Varför är Thalia Amberhide här?",a="Thalia bor på Freewind Post och lever stillsamt i taurenbosättningen på platån. Hon lever ett lugnt liv bland sitt folk, men oroar sig för hoten mot sina vänner i kanjonerna nedanför.",al={"varför är thalia vid freewind post","varför är thalia amberhide här","vad förde thalia till thousand needles"}},["211f0475"]={q="Vad vill Thalia Amberhide?",a="Thalia bryr sig djupt om sin nära vän Lakota Windsongs väl. Det viktigaste för henne är att skydda dem hon håller kära från aggressiva rivaliserande klaner som Grimtotem.",al={"vad vill thalia","thalia amberhides motiv","thalia amberhides mål"}}},fp="16,235,20.432.0,24.183.0,36.193.0,47.209.0"}
P.entries["npc:tharek-blackstone"] = {n="Tharek Blackstone",s="Tharek Blackstone är en hårt arbetande verktygssmed som bor i Kharanos, i Dun Moroghs snöiga hjärta. Han är känd för att förse lokala hantverkare med kraftig utrustning, och hans främsta kund är Beldin Steelgrill på Steelgrill's Depot. Även om han ständigt är upptagen med sitt hantverk är han också en pålitlig kontakt för resenärer som söker arbete i bosättningen.",h="Tharek Blackstone är en hårt arbetande verktygssmed som bor i Kharanos, i Dun Moroghs snöiga hjärta.",kw={"beldin","blackstone","dun morogh","kharanos","steelgrill","tharek","verktygssmed"},ang={["profession:Blacksmithing"]="För smeder på genomresa i Kharanos visar Tharek hur vardagen ser ut för en arbetande verktygssmed: han tillverkar slitstarka skiftnycklar och järnbeslag som håller dvärgarnas maskiner igång.",["race:Dwarf"]="Tharek förkroppsligar Dun Moroghs arbetarklassens robusta och självtillräckliga anda och hjälper den lokala industrin att fungera genom ren uthållighet vid städet."},sec={{t="En upptagen verktygssmed i Kharanos",b="Bland Kharanos kalla snödrivor arbetar Tharek Blackstone med att tillverka pålitliga dvärgverktyg. Han reparerar utrustning åt lokalbefolkningen och levererar till större verksamheter, så han får sällan en stunds vila. Hans största huvudvärk och mest pålitliga kund är Beldin Steelgrill, vars mekastridderdepå strax utanför staden behöver ett stadigt flöde av tunga skiftnycklar, kugghjul och reservverktyg. För att hålla smedjan igång utan att hamna efter med leveranserna anlitar Tharek ofta kringvandrande resenärer som kan frakta nyss färdigställda verktygslådor till depån."},{t="En välkänd person i samhället",b="Utöver sitt arbete vid städet åtnjuter Tharek stor respekt bland Dun Moroghs invånare. Han har ingen formell militär titel, men hans ställning i staden gör honom till en lättillgänglig kontakt för småjobb, leveranser och samordning av lokala insatser."}},faq={{q="Vem är Tharek Blackstone?",a="Tharek Blackstone är en dvärgisk verktygssmed i staden Kharanos i Dun Morogh. Han tillverkar och underhåller tunga verktyg åt lokala arbetare och anlitar ofta äventyrare på genomresa för att leverera förnödenheter runt dalen.",al={"tharek blackstone","vem är tharek","blackstone dun morogh"}},{q="Vilken relation har han till Beldin Steelgrill?",a="Beldin Steelgrill driver Steelgrill's Depot strax öster om Kharanos, där mekastridrar och belägringsmaskiner repareras. Beldin är Thareks främsta kund och beställer så mycket järnvaror att Tharek ofta förlitar sig på äventyrare för att leverera färdiga försändelser till depån.",al={"tharek och beldin","steelgrills verktyg","varför beldin"}},{q="Var hittar jag Tharek Blackstone?",a="Han står utomhus nära mitten av Kharanos i Dun Morogh, på bekvämt gångavstånd från det lokala värdshuset och smedjan.",al={"thareks plats","var finns tharek blackstone","tharek blackstone plats"}},{q="Har Tharek någon officiell rang i Ironforge?",a="Han har varken militär grad eller politiskt ämbete. Han är en upptagen, överarbetad verktygssmed som anlitar nykomlingar i behov av mynt för att bära förnödenheter åt honom.",al={"är tharek en ledare","thareks befogenhet","blackstones rang"}}},fx={cb940f84={q="Vilken sida står Tharek Blackstone på?",a="Tharek är en lojal dvärg från Ironforge och står stadigt med Alliansen. Han bor i Kharanos och tjänar sitt samhälle med hederligt arbete, utrustar lokala hantverkare och hjälper resenärer och grannar runt om i Dun Morogh när problem uppstår.",al={"tharek blackstones fraktion","vem tjänar tharek blackstone","tharek och alliansen"}},eaa270fb={q="Vad vill Tharek Blackstone?",a="Tharek vill mest hinna med sin outtröttliga arbetsbörda. Som hårt arbetande verktygssmed är han ständigt överhopad av beställningar, särskilt från krävande kunder som Beldin Steelgrill. Han söker pålitliga resenärer som kan leverera varor och ta sig an ströjobb, så att han kan hålla smedjan igång utan problem.",al={"vad vill tharek","tharek blackstones motiv","varför behöver tharek hjälp"}},fa8e7e80={q="Varför är Tharek Blackstone här i Kharanos?",a="Kharanos är navet för resenärer och handelsfolk i Dun Morogh, vilket gör det till en naturlig plats för Tharek att öppna butik. Härifrån kan han förse närliggande knutpunkter som Steelgrill's Depot med nödvändig utrustning.",al={"varför är tharek i kharanos","tharek blackstone kharanos"}}},fp="17,205,28.280.0,18.197.0,25.184.0,48.253.0,35.132.0,48.142.0"}
P.entries["npc:tharnariun-treetender"] = {n="Tharnariun Treetender",s="Tharnariun Treetender är en Night Elf-naturalist stationerad i kustbosättningen Auberdine i Darkshore. Han viger sig åt att skydda vildmarkens känsliga balans och håller uppsikt över den krypande fördärvelse som drabbar traktens växt- och djurliv. Resande som passerar hamnen ser honom ofta kalla på allierade för att hela sjuka djur och skydda naturen från ytterligare förfall.",h="Tharnariun Treetender är en Night Elf-naturalist stationerad i kustbosättningen Auberdine i Darkshore.",kw={"auberdine","rening","fördärvelse","darkshore","smittad","kaldorei","plagued lands","tharnariun","treetender"},ang={["class:Druid"]="Druider känner igen Tharnariuns oro för det fördärvade djurlivet som nära besläktad med deras egen heliga uppgift att återställa harmonin i fördärvade marker.",["faction:Alliance"]="Auberdine är Alliansens främsta kustport i norra Kalimdor. Därför är Tharnariuns försvar av de omgivande skogarna avgörande för utpostens säkerhet.",["race:NightElf"]="För kaldorei-folket väcker Tharnariuns varningar stark genklang i deras urgamla plikt att vaka över den naturliga balansen i norra Kalimdor."},sec={{t="En väktare i Auberdine",b="Hamnstaden Auberdine ligger vid Darkshores karga kust och hotas från flera håll, av allt från fientliga satyrer till fördärvade strandvrak. Tharnariun Treetender riktar sina ansträngningar mot den omgivande naturen. Han är övertygad om att försummelse av naturen leder till undergång. Därför ägnar han sin tid åt att observera hur de lokala skogarna förfaller och söka sätt att hejda sjukdomen som sprider sig över skogsmarken."},{t="Att hela de drabbade",b="En stor del av Darkshores djurliv har fallit offer för märkliga farsoter och fördärvande sjukdomar, som driver varelser till vansinne och förvandlar fridfulla djur till rabiata hot. Tharnariun vill hitta ett botemedel i stället för att bara slakta dem av rädsla. Med omsorgsfullt blandade reningsmedel och riktade försök att utrota den värsta smittan försöker han rädda det som återstår av vildmarken innan skogen förfaller helt."}},faq={{q="Vem är Tharnariun Treetender?",a="Tharnariun är en Night Elf-skötare stationerad i Auberdine vid Darkshores kust. Han viger sitt liv åt att vaka över skogen och ta reda på vad som orsakar de onaturliga sjukdomar som plågar traktens djurliv.",al={"vem är tharnariun","tharnariuns bakgrund","tharnariun treetender"}},{q="Var hittar jag Tharnariun Treetender?",a="Han finns i Night Elf-kustbyn Auberdine, vid den västra kanten av Darkshores vildmark.",al={"var finns tharnariun","tharnariun treetenders plats","tharnariun karta"}},{q="Vilka problem undersöker Tharnariun i Darkshore?",a="Han undersöker den fördärvelse och de hemska farsoter som sprider sig och smittar landet och dess djurliv. Han skickar ut äventyrare för att rena smittade djur och hejda sjukdomen.",al={"vad vill tharnariun","tharnariuns syfte","varför hjälpa tharnariun"}},{q="Varför bryr sig Tharnariun så mycket om sjuka djur?",a="Som vildmarkens beskyddare tror Tharnariun att Night Elf-folket inte kan försumma naturen utan att drabbas av följderna. Han arbetar för att rena de sjuka djuren i stället för att överge skogen åt fördärvelsen.",al={"varför rädda djuren","tharnariuns djuruppdrag"}},{q="Vilka uppdrag erbjuder Tharnariun Treetender?",a="Han leder äventyrare genom uppgifter som rör de fördärvade markerna och djurlivet, däribland 'Plagued Lands', 'Cleansing of the Infected' och 'Tharnariun's Hope'.",al={"tharnariuns uppdrag","tharnariun treetenders uppgifter"}},{q="Är Tharnariun en druid?",a="Källorna kallar honom aldrig uttryckligen druid. Han delar Cenarion Circles naturvårdande övertygelse om att bevara djur och växter, men verkar främst som en hängiven vårdare och skogsväktare i Darkshores vildmark.",al={"är tharnariun druid","tharnariuns klass"}}},fx={["8905307a"]={q="På vems sida står Tharnariun Treetender?",a="Tharnariun Treetender står fast på nattalvernas och Alliansens sida. Han är stationerad i Auberdine och är lojal mot Kalimdors naturarv och sina kaldorei-släktingar. Han välkomnar resenärer från Alliansen som är villiga att hjälpa till att skydda vildmarken från den annalkande pesten.",al={"tharnariun treetender fraktion","är tharnariun med i alliansen","vem tjänar tharnariun"}},["3ad5bd13"]={q="Vad vill Tharnariun Treetender?",a="Tharnariun vill skydda Darkshores känsliga ekosystem och rena det från korruption. Han oroas av märkliga plågor som förvrider den lokala faunan och ägnar sig åt att finna orsakerna till korruptionen och hitta botemedel. Han vill läka det infekterade djurlivet eller, som en barmhärtig utväg, avliva det innan naturen faller samman helt.",al={"tharnariuns mål","vad försöker tharnariun göra","tharnariun treetenders syfte"}}},fp="21,208,23.357.0,21.326.1,29.165.0,39.90.0,55.170.0,56.159.0,45.151.0,22.182.0"}
P.entries["npc:the-defias-traitor"] = {n="The Defias Traitor",s="Vid Sentinel Hill har The Defias Traitor avslöjat Brotherhoodens hemliga bas för att rädda sitt liv. Den tillfångatagna laglöse hålls under vakttornet efter att People's Militia ertappade honom med att stjäla Farmer Saldeans vagn.",h="Vid Sentinel Hill har The Defias Traitor avslöjat Brotherhoodens hemliga bas för att rädda sitt liv.",kw={"defias hideout","defias traitor","farmer saldean","moonbrook","peoples militia","sentinel hill","westfall"},ang={["class:Rogue"]="Som rogue vet du hur skör lojaliteten kan vara bland brottslingar. När lagen tränger in dem i ett hörn kan tjuvar och ficktjuvar förråda sina egna.",["faction:Alliance"]="För People's Militia och Westfalls försvarare markerar den här fången en vändpunkt i kampen mot de laglösa som terroriserar trakten."},sec={{t="Vägen till Moonbrook",b="Under bevakning vid Sentinel Hills vakttorn måste förrädaren leda Alliansens förkämpar genom fientligt territorium till den dolda ingången under det förstörda Moonbrook. Hans forna kamrater hatar honom, och hans fångvaktare föraktar honom. Ändå ger hans förräderi People's Militia den öppning de behöver för att slå till mot Brotherhoodens hjärta."},{t="En uppgörelse för överlevnad",b="Defias Brotherhood har inte alla medlemmars lojalitet till Edwin VanCleef. Gryan Stoutmantles milis grep den småaktige tjuven när han försökte stjäla Farmer Saldeans vagn. När han stod inför avrättning valde han att rädda sig själv. Han gav milisen den exakta platsen för Brotherhoodens hemliga bas i utbyte mot sitt liv."}},faq={{q="Vem är Defias Traitor?",a="Defias Traitor är en före detta medlem av Brotherhood, tillfångatagen av People's Militia när han försökte stjäla Farmer Saldeans vagn. För att slippa avrättning gick han med på att leda milisens allierade till Brotherhoodens gömställe.",al={"vem är den här personen","defias traitors identitet","vem är förrädaren i sentinel hill"}},{q="Varför står han utanför tornet i Sentinel Hill?",a="Gryan Stoutmantle och People's Militia håller honom utanför sitt fäste, under beväpnad bevakning. Han blir kvar där tills frivilliga ställer upp för att eskortera honom till Defias Hideout.",al={"förrädarens plats","varför är han i sentinel hill","var finns förrädaren"}},{q="Vart leder han dig?",a="Han leder resande sydväst över Westfalls slätter till den förfallna staden Moonbrook, där han visar den dolda ingången till Defias Hideout.",al={"vart går förrädaren","förrädarens eskortmål","var finns defias hideout"}},{q="Varför vände han sig mot Defias Brotherhood?",a="Han vände sig mot Brotherhood för att rädda sig själv. När han ertappades med att stjäla från Farmer Saldean och stod inför avrättning erbjöd han Brotherhoodens största hemlighet i utbyte mot sitt liv.",al={"varför förråda defias","förrädarens motiv","varför bytte han sida"}}},fx={ad165ef1={q="På vems sida står Defias Traitor?",a="Han står främst på sin egen sida. Han var en skurk som verkade inom Defias Brotherhood, men övergav sin lojalitet mot Edwin VanCleef efter att ha tillfångatagits av People's Militia. Nu samarbetar han under bevakning och hjälper dig och myndigheterna i Sentinel Hill enbart för att slippa galgen.",al={"defias traitors sida","vem tjänar förrädaren","är defias traitor med i alliansen"}},["9c073637"]={q="Vad vill Defias Traitor?",a="Han vill helt enkelt överleva. Efter att ha ertappats på bar gärning med att försöka stjäla Farmer Saldeans vagn slöt han en desperat överenskommelse med Gryan Stoutmantle och People's Militia: han får behålla livet och slipper avrättning i utbyte mot att leda dig direkt till Brotherhoods hemliga gömställe.",al={"vad vill förrädaren","defias traitors mål","varför hjälpa defias traitor"}},a1cd0f31={q="Vilka band har Defias Traitor?",a="Tidigare var han knuten till Edwin VanCleef och Defias Brotherhood och kände till alla detaljer i deras verksamhet i Westfall. Nu hålls han fången av Gryan Stoutmantle och People's Militia i Sentinel Hill, som förlitar sig på hans förstahandskunskap för att slå till mot tjuvarnas högkvarter.",al={"defias traitors förbindelser","vem känner förrädaren","defias traitors band"}}},fp="18,204,28.306.1,22.287.1,26.201.0,54.163.0,23.155.1,47.165.0"}
P.entries["npc:theldurin-the-lost"] = {n="Theldurin the Lost",s="Theldurin the Lost är en tillbakadragen, halvt vansinnig dvärg som strövar omkring i Badlands svedda vidder. Han tillhörde tidigare den lömska kulten Twilight's Hammer, men flydde med stulna heliga reliker när han insåg vidden av deras planer.",h="Theldurin the Lost är en tillbakadragen, halvt vansinnig dvärg som strövar omkring i Badlands svedda vidder.",kw={"badlands","sprängkrut","myzrael","ryun'eh","scroll of myzrael","theldurin","theldurin the lost","twilight's hammer"},ang={["profession:Engineering"]="Theldurin hotar främlingar som närmar sig med en säck full av sprängkrut och visar en oförutsägbar förkärlek för flyktiga sprängämnen.",["race:Dwarf"]="Det är sorgligt att se en av Ironforges söner reducerad till vanvettig paranoia i en ödemark, men hans vägran att böja sig för mörka kulter visar på en okuvlig dvärgisk envishet."},sec={{t="Ett sinne krossat av mörker",b="Theldurin klamrar sig fast vid sprängämnen i vild paranoia bland Badlands karga kullar, men är mycket mer än en enkel galen eremit. En gång var han en invigd i kulten Twilight's Hammer. När den ondskefulla sammanslutningen försökte väcka en uråldrig elementarkraft som var fångad under jorden, ryggade Theldurin tillbaka i skräck, förkastade deras vansinniga läror och flydde ut i öknen. Han tog med sig Scroll of Myzrael, desperat att hindra sina forna mästare från att släppa lös en uråldrig fasa över världen. Flyktens pris blev hans förstånd, men hans trots slog ett hårt slag mot kultens planer."},{t="En desperat motåtgärd",b="Överlevnaden i ödemarken blev en bitter prövning. Rasande jordelementärer överföll Theldurin och slet hans stulna skriftrulle i bitar, som spreds över dammet. Nu, belägrad av paranoia och hemsökt av syner av en annalkande undergång som slumrar under ytan, söker den vansinnige dvärgen efter uråldriga texter, Tablet of Ryun'eh och Yagyin's Digest, i hopp om att finna sedan länge begravd kunskap. I stället för att låta kulten befria elementarprinsessan Myzrael när hennes vrede når sin höjdpunkt, smider Theldurin planer på att framtvinga hennes förtida framkallning, så att hon kan besegras och bindas på nytt."}},faq={{q="Vem är Theldurin the Lost?",a="Theldurin är en vansinnig dvärgeremit som gömmer sig i Badlands. Han är en före detta medlem av kulten Twilight's Hammer, vars rituella hemligheter han stal innan han flydde ut i vildmarken för att hindra dem från att släppa lös en farlig kraft.",al={"vem är theldurin","theldurins historia","galen dvärg badlands"}},{q="Varför gömmer sig Theldurin i Badlands?",a="Han flyr från Twilight's Hammer. Efter att ha stulit Scroll of Myzrael från kulten tog han sin tillflykt till Badlands avlägsna, solstekta raviner för att undkomma kultisterna som jagar honom.",al={"varför är theldurin här","varför gömmer sig theldurin","theldurin badlands"}},{q="Vad är Scroll of Myzrael?",a="Det är ett magiskt pergament med den rituella kunskap som krävs för att befria Myzrael, en uråldrig, fördärvad elementarvarelse som är fångad djupt under Arathi. Theldurin stal det för att hindra Twilight's Hammer från att fullborda sin framkallning, men lokala elementärer slet senare sönder dokumentet.",al={"scroll of myzrael","vilken skriftrulle stal theldurin"}},{q="Vad vill Theldurin göra med Myzrael?",a="Theldurin vet att varelsens bojor försvagas och försöker därför framkalla Myzrael i förtid, innan hon samlar full styrka. Om han tvingar fram henne medan hon är försvagad kan äventyrare bannlysa henne och binda henne på nytt under jordskorpan, innan Twilight's Hammer kan bemästra hennes kraft.",al={"theldurins plan","varför framkalla myzrael","framkallningen av prinsessan"}}},fp="18,249,28.604.0,26.568.1,26.217.0,40.208.0,30.296.1,44.274.1"}
P.entries["npc:theocritus"] = {n="Theocritus",s="I Tower of Azora i östra Elwynn vakar Theocritus över kungariket och bekämpar Morganth. Den excentriske mänsklige ärkemagikern lever avskilt, omgiven av tjänare och magiska skådningsredskap.",h="I Tower of Azora i östra Elwynn vakar Theocritus över kungariket och bekämpar Morganth.",kw={"ärkemagiker","elwynn forest","eye of azora","morganth","morley eberlein","shadowhide","theocritus","tower of azora"},ang={["class:Mage"]="Theocritus visar hur en magiker kan arbeta ensam utan att tillhöra någon orden. Han har ett eget heligt rum och använder magi för att skåda över långa avstånd.",["faction:Alliance"]="Trots att Theocritus är excentrisk och reserverad använder han sin arkana syn och sina resurser för att försvara östra Elwynn och Redridge mot laglösa magiker.",["race:Human"]="Konflikten mellan Theocritus och Morganth speglar två vägar för mänsklig trolldomskonst: disciplinerade studier till försvar och fördärv drivet av mörka ambitioner."},sec={{t="Tornets mästare",b="Ärkemagikern Theocritus har ett eget fäste i kungariket Stormwind. Han bor i Tower of Azora, nära den östra vägen till Redridge. Han har excentriska vanor och lever bekvämt med en stor stab av tjänstefolk, däribland gnomiska uppassare och sin skräddare Morley Eberlein. Han håller sig undan bybornas vardagsbekymmer, men hans magi skyddar östra Elwynn."},{t="Kriget mot Morganth",b="Den fallne magikern Morganth är Theocritus största bekymmer. Morganth verkar från Tower of Ilgalar i närbelägna Redridge Mountains, och Theocritus ser honom både som en personlig fiende och som ett hot mot Stormwind. I flera månader har Theocritus använt arkan forskning för att underminera honom. Med skådningsredskap som Eye of Azora bevakar han Morganths handlingar och försöker utforska hans tankar. Han studerar också de magiska amuletter som Morganths Shadowhide-kobolder bär, i hopp om att vända deras herres skapelser mot honom med en arkan puls som kan lamslå hela flocken."}},faq={{q="Vem är Theocritus?",a="Ärkemagikern Theocritus bor på egen hand i Tower of Azora i östra Elwynn Forest. Han är excentrisk och något tillbakadragen, och använder sin magi för att skydda området mot mörka magiska hot.",al={"theocritus bakgrund","vem är magikern i tornet","magikern i tower of azora"}},{q="Varför bor Theocritus i Elwynn Forest?",a="Theocritus har sitt eget heliga rum i Tower of Azora i östra Elwynn. Hans hushåll passar upp på honom medan han bedriver sina studier och bevakar gränsen mot Redridge, där hans rival Morganth bor i Tower of Ilgalar.",al={"varför är theocritus i elwynn"}},{q="Vem strider Theocritus mot?",a="Theocritus främsta rival är Morganth, en fallen mänsklig magiker som utövar mörk magi i Tower of Ilgalar på andra sidan gränsen i Redridge. Theocritus betraktar Morganth som en personlig fiende och ett allvarligt hot mot Stormwind.",al={"theocritus fiende","vem är morganth","theocritus rival"}},{q="Vad är Eye of Azora?",a="Eye of Azora är ett skådningsredskap som finns högst upp i Theocritus torn. Han använder det för att spana in avlägsna länder, spåra hot och försöka läsa Morganths tankar.",al={"eye of azora bakgrund","hur spionerar theocritus","theocritus kristallkula"}},{q="Varför vill Theocritus ha Shadowhide-koboldernas amuletter?",a="Shadowhide-kobolderna tjänar Morganth och bär förtrollade amuletter som är knutna till honom. Theocritus studerar amuletterna för att förstå hur länken fungerar, i hopp om att sända en arkan attack genom den och förlama kobolderna i strid.",al={"koboldamuletter theocritus","theocritus återhämtning","varför samla koboldamuletter"}},{q="Vem tjänar Theocritus i hans torn?",a="Theocritus hushåll omfattar gnomiska tjänare som sköter hans dagliga sysslor och hans personliga skräddare Morley Eberlein, som tar hand om hans garderob.",al={"personalen i tower of azora","vem bor i tower of azora","theocritus tjänare"}}},fx={ffea707c={q="På vems sida står Theocritus?",a="Ärkemagikern Theocritus verkar självständigt och ägnar sig åt sina egna esoteriska studier. Han håller sig utanför Stormwinds och Alliansens dagliga politik, men anser fortfarande att det är hans plikt att försvara riket mot mörk magi. Han står bestämt emot den avfällige magikern Morganth och de mörka krafter som tränger in i Elwynn och Redridge.",al={"theocritus alliansen eller horden","vem tjänar theocritus","theocritus fraktion"}},["09c566f6"]={q="Vad vill Theocritus?",a="Theocritus använder sina väldiga magiska krafter för att bekämpa sin bittra rival, den fallne magikern Morganth. Med hjälp av den magiska skådningsapparaten Eye of Azora och återfunna Shadowhide-gnollhängen försöker han tränga in i Morganths sinne och bryta den mörke trollkarlens kontroll över gnollerna som terroriserar trakten.",al={"theocritus mål","vad försöker theocritus göra","theocritus syfte"}},a72df9dd={q="Varför är Theocritus i Elwynn Forest?",a="Theocritus slog sig ner i Tower of Azora i östra Elwynn Forest. Det avskilda tornet ger honom en lugn fristad där han kan bedriva forskning i ensamhet, omgiven av sina gnomiska tjänare, samtidigt som han håller uppsikt över den närliggande gränsen mot Redridge.",al={"varför är theocritus i elwynn","varför är theocritus här","varför theocritus i tower of azora"}},f1864285={q="Vilka band har Theocritus?",a="Theocritus är excentrisk och ensam, men i tornet har han en trogen stab av gnomiska tjänare och sin personlige skräddare Morley Eberlein. Samtidigt är han inblandad i en djup, personlig fiendskap med den avfällige magikern Morganth.",al={"theocritus förbindelser","theocritus vänner","theocritus allierade i dalaran"}}},fp="10,229,19.375.0,24.549.0,18.195.0,42.219.0,35.218.0,25.159.0,51.219.0,35.150.0"}
P.entries["npc:therylune"] = {n="Therylune",s="Therylune är en dryad som hålls fången vid The Master's Glaive i södra Darkshore. Hon har snärjts av de lömska kultisterna i Twilight's Hammer, som ockuperat den uråldriga platsen, och förlitar sig på modiga resenärer för att bli fri och undkomma deras klor.",h="Therylune är en dryad som hålls fången vid The Master's Glaive i södra Darkshore.",kw={"cenarius","darkshore","dryad","eskort","the master's glaive","therylune","therysil","twilight's hammer"},ang={["class:Druid"]="Som naturens förvaltare, knutna till Cenarius och hans släkte, känner druider en direkt samhörighet och ett trängande ansvar att rädda en dryad som tillfångatagits av illvilliga kultister.",["race:NightElf"]="Nattalver har heliga, uråldriga band till Cenarius döttrar, och Therylunes fångenskap hos Twilight's Hammer är en kränkning av Kalimdors balans."},sec={{t="Fånge hos kulten",b="Dryader är naturens väktare och Cenarius döttrar, och vandrar vanligtvis i de fridfulla skogarna i norra Kalimdor. Therylune vågade sig dock för nära den illavarslande utgrävningen vid The Master's Glaive i södra Darkshore, där kultister från Twilight's Hammer har samlats. Den mörka kulten överföll och fångade henne. Hon kan inte ensam kämpa sig ut genom svärmarna av kultister och behöver eskort till säkerhet."}},faq={{q="Vem är Therylune?",a="Therylune är en dryad, en av skogarnas döttrar till halvguden Cenarius. Hon har tillfångatagits av kultister från Twilight's Hammer som håller till vid The Master's Glaive i södra Darkshore.",al={"vem är therylune","therylunes historia","vad är therylune"}},{q="Varför hålls Therylune fången vid The Master's Glaive?",a="Therylune överfölls och hölls fast av kultisterna från Twilight's Hammer, som har slagit läger i mörker kring de jättelika förstenade lämningarna vid The Master's Glaive.",al={"varför är hon tillfångatagen","hur blev therylune fångad","kultister vid the master's glaive"}},{q="Har Therylune någon familj?",a="Ja, Therylune är syster till Therysil, en annan dryad som lever i skogarna i norra Kalimdor.",al={"therylunes syster","therysil therylune","therylunes familj"}},{q="Vad händer när du hjälper henne att fly?",a="När äventyrare röjer en väg genom de fientliga kultisterna flyr Therylune från The Master's Glaive och återvänder till tryggheten i den omgivande vildmarken.",al={"therylunes flykt","uppdrag 945","vad gör therylune"}}},fx={f442f40d={q="På vems sida står Therylune?",a="Therylune är en allierad till nattalverna och naturens krafter. Som dryad och dotter till Cenarius står hon fast emot mörka krafter som kultisterna i Twilight's Hammer, som har tillfångatagit henne. Hon välkomnar gärna hjälp från vänligt sinnade resenärer för att vinna sin frihet.",al={"therylunes fraktion","är therylune med i alliansen","är therylune vänligt sinnad"}},["7872ea33"]={q="Vad vill Therylune?",a="Therylune vill inget hellre än att komma loss ur klorna på kultisterna i Twilight's Hammer som håller henne fången. Hon behöver en skicklig beskyddare som kan eskortera henne i säkerhet bort från de korrumperade markerna vid The Master's Glaive, så att hon kan återvända till sina fränder.",al={"vad behöver therylune","therylunes mål"}}},fp="9,217,19.377.0,17.167.0,48.162.0,31.105.0,38.139.1"}
P.entries["npc:therysil"] = {n="Therysil",s="Therysil är en dryad som bor vid The Shrine of Aessina i centrala Ashenvale. Hon är djupt hängiven åt att bevara naturen och väntar oroligt på besked om sin syster Therylune, som hamnade i händerna på skändliga kultister.",h="Therysil är en dryad som bor vid The Shrine of Aessina i centrala Ashenvale.",kw={"ashenvale","cenarius","dryad","the shrine of aessina","therylune","therysil","twilight's hammer"},ang={["class:Druid"]="Som dotter till Cenarius står Therysil för det starka bandet mellan Cenarion Circle och Ashenvales naturandar, vilket gör hennes belägenhet särskilt brådskande för druider på besök.",["race:NightElf"]="Dryaderna har länge varit trogna allierade till kaldorei och hjälpt dem att skydda Ashenvales heliga lundar, som The Shrine of Aessina."},sec={{t="En väktares vaka",b="Therysil bor nära det stilla vattnet vid The Shrine of Aessina, en helig glänta i Ashenvales uråldriga skogar. Liksom alla dryader, Cenarius döttrar, är hon bunden till att försvara vildmarken och andarna som bor där. Men hennes tankar har lämnat den stilla omsorgen och fyllts av gnagande oro. Hennes syster Therylune tillfångatogs i närheten av den vansinniga kulten Twilight's Hammer, och Therysil är desperat efter hjälp från varje vandrare som kan bistå med att rädda systern."}},faq={{q="Vem är Therysil?",a="Therysil är en dryad som bor vid The Shrine of Aessina i Ashenvale. Hon är en dotter till Cenarius och Therylunes syster.",al={"vem är therysil","therysils bakgrund","dryad vid aessina"}},{q="Vad oroar Therysil sig för?",a="Hennes syster Therylune överfölls och tillfångatogs av kultister från Twilight's Hammer vid The Master's Glaive i södra Darkshore. Therysil väntar vid helgedomen och hoppas att en äventyrare kan föra systern tryggt hem.",al={"vad gör therysil","varför är therysil orolig","therysils uppdrag"}},{q="Vem är Therylune?",a="Therylune är Therysils syster och ännu en dryad från Ashenvale. Hon tillfångatogs av Twilight's Hammer och behöver eskort för att undkomma dem och återförenas med Therysil.",al={"therylune","therysils syster","vem är therylune"}},{q="Var hittar man Therysil?",a="Therysil står vid The Shrine of Aessina, en helig fristad i naturen längs vägen i centrala Ashenvale.",al={"therysils plats","var finns therysil","dryad vid aessinas helgedom"}}},fx={f765b898={q="På vems sida står Therysil?",a="Therysil är dotter till Cenarius och lever under nattalvernas och vildmarksandarnas beskydd. Liksom de flesta dryader står hon på Ashenvales och Alliansens sida i kampen för naturens ordning och bekämpar ursinnigt mörka inkräktare som kultisterna i Twilight's Hammer, vilka vanhelgar de uråldriga skogarna.",al={"therysils fraktion","är therysil med i alliansen","vem tjänar therysil"}},fc91e3f7={q="Varför är Therysil här vid The Shrine of Aessina?",a="Therysil vakar vid The Shrine of Aessina, en uråldrig, helig glänta tillägnad skogsanden. Förutom att sköta helgedomen väntar hon oroligt på bud om sin syster Therylune, som vandrade mot The Master's Glaive och hamnade i händerna på de illvilliga kultister som håller till där.",al={"varför är therysil här","varför är therysil vid the shrine of aessina","therysils syfte här"}}},fp="8,192,18.347.0,16.123.0,27.214.0,17.153.0,28.102.0"}
P.entries["npc:thor"] = {n="Thor",s="Vid Sentinel Hill håller Thor Westfall sammanlänkat med Stormwind genom gryfonflygningar. Hans tränade riddjur för resenärer och brådskande meddelanden ovanför de farliga vägarna.",h="Vid Sentinel Hill håller Thor Westfall sammanlänkat med Stormwind genom gryfonflygningar.",kw={"kurir","flygmästare","gryfon","folkets milis","sentinel hill","thor","westfall"},ang={["faction:Alliance"]="Som en hjälte i Alliansen som hjälper Folkets milis kan du ta Thors snabbaste väg tillbaka till huvudstaden för att leverera underrättelser från fältet och fylla på förråden."},sec={{t="Sentinel Hills örnnäste",b="Thor sköter gryfonnästet vid Sentinel Hill och knyter samman Westfalls försvarare med resten av kungariket. Folkets milis möter banditer, gnoller och felande skördegolemer på marken. Thors gryfoner flyger med resenärer och militära depescher ovanför de farliga vägarna. Rapporter från Gryan Stoutmantle och brådskande begäran om hjälp når hovet i Stormwind långt snabbare än med en budbärare till fots."}},faq={{q="Vem är Thor?",a="Thor är den mänskliga flygmästaren vid Sentinel Hill i Westfall. Han sköter tränade gryfoner som flyger med resenärer mellan Westfall och andra bosättningar i Alliansen, däribland Stormwind City.",al={"vem är den här personen","flygmästare vid sentinel hill","thor npc"}},{q="Vilken roll har han i Westfall?",a="Thor håller Sentinel Hill förbunden via luften. Han samordnar kurirer som för militära meddelanden mellan Folkets milis och Stormwinds högsta befäl, så att befälhavarna hålls informerade trots Defias verksamhet på vägarna.",al={"vad gör thor","thors uppgift"}},{q="Varför är gryfonresor viktiga här?",a="Gryfonflygningar erbjuder ett snabbt och säkert sätt att undvika de farliga vägarna mellan Westfall, Elwynn Forest och Duskwood. Defias-vägrövare, Riverpaw-gnoller och farligt djurliv hotar färdvägarna, medan gryfonerna håller förnödenheter och meddelanden i rörelse.",al={"varför flyga i westfall","flygrutt i westfall"}}},fx={["5cbb8458"]={q="På vems sida står Thor?",a="Thor är lojal mot Alliansen och står sida vid sida med People's Militia i Sentinel Hill. Han verkar under Stormwinds nätverk av gripmästare och tjänar kungariket genom att föra betrodda budbärare, soldater och äventyrare genom dess luftrum. På så sätt ser han till att Westfall håller viktig kontakt med huvudstaden.",al={"thors lojalitet","är thor med i alliansen","vem tjänar thor"}},a791490a={q="Vad vill Thor?",a="Thor vill hålla flygtrafiken mellan Sentinel Hill och vänligt sinnade utposter som Stormwind City i gång utan problem. Han fokuserar på att ta hand om sina gripar och hålla dem redo, så att brådskande rapporter och resenärer snabbt kan ta sig förbi banditerna och vilddjuren som stryker längs vägarna i Westfall.",al={"thors drivkraft","vad gör thor","thors syfte i westfall"}},f6f75bde={q="Varför är Thor stationerad i Sentinel Hill?",a="Sentinel Hill är People's Militia hårt ansatta fäste mot Defias Brotherhood. Thor är stationerad högst upp på befästningen eftersom färder landvägen genom Westfall kantas av bakhåll. Gripflygning är därför den snabbaste och säkraste livlinan tillbaka till Elwynn Forest och Stormwind.",al={"varför är thor i westfall","thors plats i sentinel hill","varför är thor här"}},["62307107"]={q="Vilka band har Thor?",a="Thor är knuten till Stormwinds gripvårdare och samarbetar nära med gripmästaren Dungar Longdrink i huvudstaden. Här på plats samarbetar han med Gryan Stoutmantle och försvararna i Sentinel Hill och ger dem viktiga transport- och spaningsförbindelser med omvärlden.",al={"thors förbindelser","vem samarbetar thor med","thors allierade"}}},fp="4,153,26.409.0,12.168.0,35.217.0,37.247.0"}
P.entries["npc:thorgas-grimson"] = {n="Thorgas Grimson",s="Thorgas Grimson är den bofaste tränaren för dvärgjägare i Anvilmar i Coldridge Valley. Som erfaren friluftsmänniska från Dun Morogh tror han bestämt att praktisk överlevnad i den iskalla vildmarken är den bästa lärare en nybörjarskytt kan ha.",h="Thorgas Grimson är den bofaste tränaren för dvärgjägare i Anvilmar i Coldridge Valley.",kw={"anvilmar","coldridge valley","dun morogh","dvärgjägare","jägartränare","thorgas grimson"},ang={["class:Hunter"]="För dvärgskyttar är Thorgas Grimson ofta den allra första mentor de möter. Han ger dem tidig vägledning i att spåra bestar och överleva i den iskalla dalen.",["race:Dwarf"]="Grimson förkroppsligar den hårdföra och självgående anda som kännetecknar Ironforges bergsklättrare, vilka patrullerar Dun Moroghs frusna toppar."},sec={{t="En guide i kylan",b="I Anvilmars stensalar välkomnar Thorgas Grimson nybörjare som vill bli bergsklättrare och spejare och som tar sina första steg ut i Coldridge Valleys hårda snödrivor. I stället för att tynga unga jägare med torra föreläsningar förespråkar Grimson en praktisk filosofi: verklig skicklighet formas ute i de iskalla vindarna, med båge eller gevär i hand och med Dun Moroghs härdiga bestar att spåra på nära håll."}},faq={{q="Vem är Thorgas Grimson?",a="Thorgas Grimson är en tränare för dvärgjägare i Anvilmar, Coldridge Valleys centrala utpost i Dun Morogh. Han ger nya jägare i Alliansen grundläggande vägledning och fältkunskaper när de ger sig ut på sina äventyr.",al={"thorgas grimson","vem är thorgas","jägartränare i anvilmar"}},{q="Vilken träning erbjuder Thorgas?",a="Han lär nybörjarjägare grundläggande vildmarkstekniker, som att spåra vilda bestar över den snöiga terrängen och vässa sina grundläggande färdigheter med avståndsvapen. Det hjälper dem att slå in på vägen mot att bli riktiga bergsklättrare.",al={"vad lär thorgas ut","jägarfärdigheter i anvilmar"}},{q="Vilken träningsfilosofi har han?",a="Thorgas anser att teoretiska övningar inte kan mäta sig med verklig erfarenhet. Han tror att det enda sättet att verkligen bemästra vildmarken är att ge sig ut i de iskalla drivorna och möta Dun Moroghs bestar direkt.",al={"thorgas personlighet","hur tränar thorgas"}},{q="Pratar Thorgas Grimson med andra än jägare?",a="Thorgas är artig nog, men säger uppriktigt till äventyrare med andra kall att han inte kan hjälpa dem med deras träning. Han råder dem att söka upp en mentor som passar deras egen väg.",al={"kan andra klasser prata med thorgas","thorgas skvaller"}}},fx={c3cc0970={q="På vems sida står Thorgas Grimson?",a="Thorgas står fast på Ironforge-dvärgarnas och den större Alliansens sida. Han är stationerad i Anvilmar i Coldridge Valley och använder sina färdigheter för att förbereda nybörjarjägare på att försvara riket och skydda dvärgarnas länder mot annalkande vilddjur och fiender.",al={"thorgas grimsons fraktion","thorgas grimsons lojalitet","vem tjänar thorgas grimson"}},["8eae34e9"]={q="Vad vill Thorgas Grimson?",a="Thorgas vill forma oerfarna rekryter till självständiga och skickliga skyttar. Han anser att verklig skicklighet inte kan läras ut genom prat allena. Därför vill han skicka ut nya jägare i den snöiga vildmarken, där praktisk erfarenhet kan vässa deras spårnings- och stridsinstinkter.",al={"thorgas grimsons mål","vad vill thorgas","thorgas grimsons syfte"}},d81e027b={q="Varför är Thorgas Grimson i Anvilmar?",a="Han är stationerad i Anvilmar för att vägleda nyrekryterade jägare som ger sig ut i Coldridge Valley. Dalen är avskuren av hårt väder och hotas av troggar och vilda djur, så erfarna spårare som Thorgas behövs för att se till att de nya rekryterna lär sig överleva och strida.",al={"varför är thorgas i anvilmar","varför är thorgas grimson här"}}},fp="15,181,19.220.0,23.180.0,33.178.0,32.139.0,44.134.0"}
P.entries["npc:thorgrum-borrelson"] = {n="Thorgrum Borrelson",s="Thorgrum Borrelson är dvärgarnas griphmästare, stationerad ovanför Thelsamar i Loch Modan. Från sin utsiktsplats med vy över bosättningen sköter han de flygande riddjuren som förbinder dalen med Ironforge och de omgivande bergspassen.",h="Thorgrum Borrelson är dvärgarnas griphmästare, stationerad ovanför Thelsamar i Loch Modan.",kw={"dun morogh","flygmästare","gripmästare","ironforge","loch modan","thelsamar","thorgrum borrelson"},ang={["faction:Alliance"]="Thorgrums flygroost fungerar som en viktig logistikknutpunkt som förbinder dvärgrikets hjärta med framskjutna positioner i Wetlands och Arathi Highlands.",["race:Dwarf"]="För bergsbestigare och Khaz Modans försvarare ser Thorgrum Borrelson till att en pålitlig flygförbindelse tillbaka till Ironforges höga salar finns."},sec={{t="Utsiktsplatsen ovanför Thelsamar",b="Thorgrum Borrelson sitter på klippan strax ovanför Thelsamar och sköter Alliansens flygtransporter över Loch Modan. Troggintrång och gnollflockar hotar färdvägarna på marken, så hans tränade gripar erbjuder en livsviktig väg över de karga bergskammarna. Han upprätthåller täta förbindelser genom South Gate Pass till Great Forge i Dun Morogh, samt rutter vidare mot Wetlands och bortom."}},faq={{q="Vem är Thorgrum Borrelson?",a="Thorgrum Borrelson är Alliansens flygmästare för gripar, stationerad i Thelsamar. Han ansvarar för flygresor till och från Loch Modan-regionen.",al={"thorgrum","flygmästare i thelsamar","vem är gripmästaren i thelsamar"}},{q="Vart kan Thorgrum skicka resenärer?",a="Thorgrum samordnar flygrutter som förbinder Thelsamar med viktiga knutpunkter, som dvärgarnas huvudstad Ironforge, Menethil Harbor i Wetlands, Refuge Pointe i Arathi Highlands, Farholde Keep i Riverglades och flera utposter i de närliggande områdena.",al={"flygrutter från thelsamar","vart kan jag flyga från loch modan"}},{q="Varför är gripresor viktiga i Loch Modan?",a="Resor på marken genom Loch Modan hotas ofta av fientliga troggkulor, gnoller och Dark Iron-spejare som kämpar om bergspassen. Gripar låter Alliansens budbärare, spejare och äventyrare snabbt ta sig förbi dessa faror.",al={"varför flyga i loch modan","transporter i loch modan"}}},fx={["30011ebf"]={q="Vem står Thorgrum Borrelson på?",a="Thorgrum är en trogen undersåte till Ironforge och tjänar Alliansen. Som lokal flygmästare, stationerad alldeles ovanför Thelsamar, sköter han nätverket för flygande kurirer och transporter som förbinder bergarikets huvudstad med de omgivande områdena. Han ser till att Alliansens budbärare och resenärer snabbt kan ta sig genom Khaz Modan.",al={"thorgrum borrelsons fraktion","vem tjänar thorgrum","thorgrum och alliansen"}},aebc9bb6={q="Vad vill Thorgrum Borrelson?",a="Thorgrum vill framför allt hålla luftrummet öppet och upprätthålla stadiga flygförbindelser mellan Loch Modan och Alliansens andra fästen. Han tar hand om griparna på bergsryggen ovanför Thelsamar och ser till att kurirer, äventyrare och försändelser når platser som Ironforge utan dröjsmål.",al={"vad vill thorgrum","thorgrum borrelsons mål","thorgrums uppgifter"}},db7b8a65={q="Varför är Thorgrum Borrelson här?",a="Thorgrum är stationerad på klipporna med utsikt över Thelsamar eftersom staden är Loch Modans hjärta. Markvägarna genom bergspassen hotas ofta av troggar, kobolder och fientliga vilddjur. En särskild griprastplats garanterar därför en obruten förbindelse mellan dalens bosättning och Great Forge.",al={"varför är thorgrum i loch modan","varför är thorgrum ovanför thelsamar","thorgrums syfte och plats"}}},fp="18,151,25.296.0,26.115.0,34.203.0,46.188.0"}
P.entries["npc:thork"] = {n="Thork",s="Vid The Crossroads håller Thork uppsikt över bosättningens försvar. Han skickar Hordens äventyrare mot plundrare och arbetar för att hålla försörjningslederna öppna.",h="Vid The Crossroads håller Thork uppsikt över bosättningens försvar.",kw={"the barrens","the crossroads","kadrak","mankrik","mor'shan","orc","förnödenheter","thork"},ang={["class:Warrior"]="Som krigare kan du uppskatta Thorks fokus på försörjningsleder, välplanerade patruller och att stoppa fysiska hot innan de når stadsmurarna.",["faction:Horde"]="Om du kommer från Durotar eller Mulgore som medlem av Horden är det ett viktigt steg för att bevisa att du kan skydda Kalimdor att rapportera till Thork.",["race:Orc"]="Som orc känner du till den hårda plikten att försvara Hordens nyligen erövrade länder i Kalimdor mot fientliga grannar."},sec={{t="Befälhavare vid The Crossroads",b="Thork leder försvaret vid The Crossroads, där vägar förbinder Durotar, Mulgore och länder längre bort. Staden hotas från alla håll. Quilboar-räder, centaurattacker och harpyor på jakt splittrar hans styrkor. Thork kallar på dugliga resenärer för att möta faror som hans vakter inte kan hantera på egen hand."},{t="Säkra gränserna",b="Thorks vakthållning sträcker sig bortom murarna vid The Crossroads. Han skickar spejare och budbärare norrut till Mor’shan Rampart, där de rapporterar till Kadrak. De norra och östra lederna för transporter genom The Barrens. Att hålla vägarna öppna upprätthåller Hordens närvaro över buskmarkerna."},{t="Hot inifrån och utifrån",b="Thork tackar resenärer som slår till mot ledarna bakom Razormane-räderna. Mangletooth, en tillfångatagen quilboar, förråder sin stam genom att hjälpa dem angripa dess ledare. När resenärer för Lok Orcbanes huvud till The Crossroads tackar Thork dem för att ha försvagat attackerna mot Hordens försörjningsleder."}},faq={{q="Vem är Thork?",a="Thork leder försvaret vid The Crossroads i The Barrens. Han organiserar stadens skydd och arbetar för att hålla försörjningskaravanerna säkra.",al={"thorks historia","vem är thork","thork the crossroads"}},{q="Var finns Thork?",a="Thork står utomhus nära centrum av The Crossroads, samordnar vakterna och ger försvarsorder.",al={"thorks plats","hitta thork","var står thork"}},{q="Varför är The Crossroads så sårbart för angrepp?",a="The Crossroads ligger vid en öppen knutpunkt för viktiga handelsleder i The Barrens och har få stenbefästningar. Fientliga Razormane-quilboar, Kolkar-centaurer och alliansspejare hotar dess gränser, så bosättningen behöver ständig bevakning.",al={"the crossroads under attack","varför the crossroads är farligt"}},{q="Vilken relation har Thork till Mankrik?",a="När Mankrik bad om soldater för att jaga quilboar och leta efter sin försvunna fru, vägrade Thork. Hans begränsade trupper måste vakta utposten och dess försörjningskaravaner.",al={"mankrik och thork","hjälpte thork mankrik"}},{q="Hur samordnar Thork sig med andra av Hordens utposter?",a="Thork skickar budbärare och soldater till Kadrak vid Mor’shan Rampart för att rapportera om den norra gränsen och hålla uppsikt över gränsen mot Ashenvale.",al={"thork och kadrak","thork the mor'shan rampart"}},{q="Vilka hot hanterar Thork?",a="Thork möter plundrande quilboar-krigsband som stör handeln och stjäl försörjningslådor. Han tackar också resenärer som besegrar ledarna bakom räderna.",al={"fiender vid the crossroads","information om thorks uppdrag"}}},fx={["3a5917fe"]={q="Vem står Thork på?",a="Thork är en orubblig officer i Thralls Horde. Han är stationerad i hjärtat av Kalimdor och leder The Crossroads lokala försvar för att säkra livsviktiga försörjningsvägar, skydda anländande resenärer och värna orkernas och taurenfolkets besittningar i norra Barrens.",al={"thorks fraktion","thork: horden eller alliansen","vem tjänar thork"}},["0b2cf0f5"]={q="Vad vill Thork?",a="Thork vill att The Crossroads ska vara tryggt. Han fokuserar på att upprätthålla ordningen, se till att försörjningskaravaner färdas säkert över de torra slätterna och slå tillbaka fientliga rövare som hotar bosättningens överlevnad.",al={"thorks mål","vad försöker thork göra","thorks uppgift"}},["56f2bf7a"]={q="Varför är Thork här?",a="The Crossroads är en viktig knutpunkt mellan Durotar, Mulgore och de norra gränstrakterna. Thork fick i uppdrag att leda försvaret av denna utsatta knutpunkt. Han samordnar patruller, tar emot anländande hjältar och ser till att den unga Hordens handelsvägar inte slås ut av ständiga räder från vildmarken.",al={"varför är thork vid the crossroads","thorks uppgift i barrens","varför placerades thork här"}}},fp="5,151,27.303.0,20.293.0,22.293.1,13.131.0,23.102.0,46.235.0,42.162.0,49.136.0,34.149.0"}
P.entries["npc:thorvald-deepforge"] = {n="Thorvald Deepforge",s="Thorvald Deepforge är en dvärgisk vapenhandlare stationerad nära gränspasset i Valley of Kings. Han hjälper till att beväpna resenärer och försvarare som säkrar den viktiga vägen mellan Dun Morogh och Loch Modan.",h="Thorvald Deepforge är en dvärgisk vapenhandlare stationerad nära gränspasset i Valley of Kings.",kw={"deepforge","dun morogh","loch modan","bergjägare","thorvald deepforge","valley of kings","vapensmed"},ang={["profession:Blacksmithing"]="Thorvald bär det berömda familjenamnet Deepforge och handlar med de praktiska, pålitliga järnvaror som dvärgiska smeder är kända för.",["race:Dwarf"]="Under Valley of Kings uråldriga monoliter står Thorvald som en symbol för det bestående hantverk och den försörjningslinje som håller Khaz Modans gränser säkra."},sec={{t="Att beväpna det östra passet",b="Thorvald Deepforge är placerad i det väldiga monumentet Valley of Kings och tjänar Alliansen som en pålitlig vapenhandlare. Bergspassen som förbinder Khaz Modans inre med de avlägsna områdena hemsöks av trogginfall och kringströvande vilda djur, så välsmitt stål är nödvändigt för varje bergsjägare eller rekryt på vägen. Thorvald ser till att de som kommer från Dun Morogh eller färdas djupare in i Loch Modan har klingorna och yxorna de behöver för att försvara dvärgarnas länder."}},faq={{q="Vem är Thorvald Deepforge?",a="Thorvald Deepforge är en dvärghandlare stationerad i Valley of Kings, där vägen går från Dun Morogh till Loch Modan. Han förser resenärer och försvarare längs gränsen med viktiga vapen.",al={"vem är thorvald","thorvald deepforge npc","deepforge loch modan"}},{q="Vilken roll har han i regionens försvar?",a="Han fungerar som en framskjuten kvartermästare och vapenhandlare för resenärer som färdas genom bergspassen och hjälper till att beväpna rekryter som skickas för att förstärka utposter i Loch Modan.",al={"vad gör thorvald","thorvalds uppgift","försörjning till fronten"}},{q="Är han släkt med de andra Deepforge i Khaz Modan?",a="Kanske. Flera dvärgar delar namnet Deepforge, däribland Murgot och Bengus Deepforge, men inga familjeband har bekräftats. Tormus Deepforge vid Great Forge kallar Thorvald sin kollega.",al={"deepforge-familjen","thorvald deepforges släktingar","murgot deepforge släkting"}}},fx={["7578ebb9"]={q="Vem står Thorvald Deepforge på?",a="Thorvald Deepforge är en trogen dvärg från Ironforge och står stadigt på Alliansens sida. Vid Valley of Kings hjälper han bergsvakterna och försvarar Khaz Modan genom att förse de lokala styrkorna med vapen och utrustning i kampen mot troggar och andra hot.",al={"thorvald deepforges fraktion","thorvald deepforge och alliansen","vem tjänar thorvald"}},["2f5ea740"]={q="Vad vill Thorvald Deepforge?",a="Thorvald ser till att Alliansens försvarare är välbeväpnade och redo. Från sin post i Loch Modans södra vakttorn förser han bergsvakterna som strider mot troggarna med vapen och rustning, och han välkomnar smeder som har med sig ny utrustning till trupperna.",al={"thorvald deepforges mål","vad behöver thorvald","thorvald deepforges motiv"}}},fp="18,158,23.298.0,26.159.0,47.143.0,52.217.0"}
P.entries["npc:thotar"] = {n="Thotar",s="I Razor Hill lär Thotar unga jägare i Horde att spåra och tämja bestar. Han tränar orcher och troll som har lämnat Valley of Trials för att möta Durotars vilda djur.",h="I Razor Hill lär Thotar unga jägare i Horde att spåra och tämja bestar.",kw={"durotar","jägare","jägartränare","kaplak","ork","razor hill","taming the beast","thotar"},ang={["class:Hunter"]="Som jägare i Horde lär du dig riterna för att tämja bestar och färdigheter för vildmarken efter att ha lämnat startdalarna.",["faction:Horde"]="Som medlem av Horde kan du lära dig av Thotar i Razor Hill att patrullera Durotars gränser med skarp blick och en stridsbest som du knutit starka band till.",["race:Orc"]="Som orch följer du Thotars traditionella jaktbruk och förfädernas vördnad för spårning och bestekamratskap.",["race:Troll"]="Som Darkspear-jägare som lämnar Sen’jin Village lär du dig överlevnadsfärdigheter inom Horde för Durotars faror."},sec={{t="En mentor i Razor Hill",b="I Razor Hill tränar Thotar jägare i Horde för Durotars vildmark. Nya rekryter lär sig grunderna i Valley of Trials och kommer sedan till honom när de möter farligare rovdjur. Han lär ut skytte och den respekt som krävs för att leva sida vid sida med och styra Kalimdors farligaste varelser, med traditioner som förts vidare genom generationer av orcher."},{t="Att tämja vildmarken",b="Thotar vägleder unga jägare i bestarnas uråldriga tämjandekonst. Han skickar ut dem i torra raviner för att lugna och knyta band till inhemska varelser, däribland giftiga skorpider, bepansrade vågkrypare och listiga vildsvin. Hans undervisning lär Horde-spårare att knyta band till naturen i stället för att förlita sig på våld."}},faq={{q="Vem är Thotar?",a="Thotar tränar jägare i Razor Hill och lär ut traditionell kunskap om vildmarken, skytte och att tämja bestar.",al={"vem är thotar","thotar i berättelsen","vad gör thotar"}},{q="Var hittar man Thotar?",a="Thotar finns i Razor Hill, Hordes bosättning i centrala Durotar, strax norr om Valley of Trials.",al={"thotars plats","var finns thotar","hitta thotar"}},{q="Vilka traditioner lär Thotar ut?",a="Thotar lär ut jakt- och spårningstraditioner som förts vidare genom generationer av orcher. Han betonar vapenskicklighet, överlevnad i vildmarken och att tålmodigt knyta band till djurkamrater.",al={"vad lär thotar ut","jägartraditioner","thotars träning"}},{q="Tränar Thotar bara orcher?",a="Thotar tränar jägare som tjänar Horde och kommer till Razor Hill. Han vägleder Darkspear Trolls och kringvandrande tauren som passerar genom Durotar.",al={"kan troll tränas av thotar","thotar och tauren","vilka tränar thotar"}},{q="Vilka uppgifter ger Thotar unga jägare?",a="Thotar skickar ut nybörjarjägare för att spåra Durotars inhemska vilda djur, däribland vildsvin, vågkrypare och skorpider. De använder en Taming Rod för att vinna bestarnas tillit och lydnad.",al={"thotars uppdrag","taming the beast med thotar","vad skickar thotar dig att göra"}},{q="Varför är det så viktigt att tämja bestar i träningen?",a="En bestekamrat kan hjälpa en jägare i Horde att överleva både strider och vildmarken. Thotar lär jägare att knyta band till sina bestar så att de blir lojala försvarare av Horde.",al={"varför tämja bestar","jägarens husdjursberättelser","syftet med att tämja bestar"}}},fx={["07bd0b61"]={q="Vem står Thotar på?",a="Thotar står stadigt på Hordens sida. I Razor Hill ägnar han sitt hantverk åt att stärka Hordens led genom att träna nyanlända orker, troll och tauren i att överleva i vildmarken och försvara sina marker.",al={"thotars fraktion","är thotar med horden","thotars lojalitet"}},["83013f85"]={q="Vad vill Thotar?",a="Thotar vill föra vidare förfädernas jakttraditioner till en ny generation. Han förväntar sig att blivande jägare visar respekt för vildmarken genom att behärska spårning, överlevnad och tämjning av bestar.",al={"vad vill thotar","thotars mål","thotars uppgift"}},["0fc388b7"]={q="Varför är Thotar i Razor Hill?",a="Razor Hill är den främsta samlingsplatsen för unga äventyrare som ger sig ut från Valley of Trials. Thotar stannar här med de andra tränarna för att förbereda blivande jägare innan de beger sig djupare in i farorna i Durotar och den vidare världen.",al={"varför är thotar här","varför är thotar i razor hill","thotar i razor hill"}}},fp="6,180,22.357.0,16.306.0,14.106.0,26.111.0,34.182.0,28.142.0,45.172.0,49.170.0"}
P.entries["npc:thrall"] = {n="Thrall",s="Thrall styr nu från Visdomens dal i Orgrimmar, hordens krigsöverhuvud och härskare över Durotar. Han var en gång en mänsklig slav som uppfostrades till arenakämpe. Han befriade sitt folk, återupprättade deras schamanistiska traditioner och ledde dem över det stora havet till ett nytt hemland.",h="Thrall styr nu från Visdomens dal i Orgrimmar, hordens krigsöverhuvud och härskare över Durotar.",kw={"blackmoore","doomhammer","durotar","go'el","orgrimmar","schaman","thrall","krigshövding"},ang={["class:Shaman"]="Thrall vördas som den första nya orciska schamanen på en generation. Han återupprättade sitt folks heliga gemenskap med elementandarna efter årtionden av demoniskt fördärv.",["faction:Alliance"]="Alliansens ledare ser Thrall som farlig men pragmatisk. Hans disciplinerade hord är vida att föredra framför de blodtörstiga erövrarna från det första och andra kriget.",["faction:Horde"]="Thrall är ditt krigsöverhuvud och högste befälhavare. Han ledde horden ut ur slaveri och ruin mot en hedervärd framtid i Kalimdor.",["race:Orc"]="För orcerna är Thrall en frälsare bland de levande. Han befriade dem från den mänskliga fångenskapens dvala och återgav dem deras förfäders heder."},sec={{t="Från slav till schaman",b="Thrall föddes som Go'el, son till Frostwolf-klanens hövding Durotan och Draka. Gul'dans lönnmördare mördade hans föräldrar när han var spädbarn, och den mänsklige befälhavaren Aedelas Blackmoore fann honom och gav honom namnet Thrall, som betyder slav. I Durnholde Keep uppfostrade Blackmoore honom till arenakämpe och lärde honom mänsklig taktik. Med hjälp av sin fostersyster Taretha Foxton flydde Thrall. Drek'Thar, en landsförvisad från Frostwolf, vägledde honom bort från demonisk fördärv och lärde honom att bemästra elementandarna. Thrall blev den första orciska schamanen i en ny generation."},{t="Krigshövdingens mantel",b="Efter det andra kriget anslöt sig Thrall till Orgrim Doomhammer för att befria orcerna som tynade bort i Alliansens fångläger. Doomhammer föll i strid och överlämnade sin svarta plåtrustning och mäktiga stridshammare till Thrall och utnämnde honom till krigsöverhuvud. Den gåtfulle profeten Medivh kom med profetiska syner, och Thrall ledde sitt folk ombord på erövrade människoskepp över det stora havet. De nådde Kalimdor och undkom undergången som drabbade Eastern Kingdoms."},{t="Den nya horden formas",b="I Kalimdor omformade Thrall horden från en krigshetsande styrka till en allians grundad på överlevnad och heder. Han räddade Vol'jins Darkspear Trolls och slöt förbund med Cairne Bloodhoofs taurer. Tillsammans med mänskliga och nattalviska styrkor besegrade koalitionen den brinnande legionen på toppen av Mount Hyjal. Därefter grundade Thrall Durotar och dess huvudstad, Orgrimmar, uppkallad efter hans far och mentor. Han upprätthåller en orolig fred med Jaina Proudmoores Theramore samtidigt som han försvarar sin sköra nation och överväger kontroversiella allianser, däribland med Lordaerons Forsaken."}},faq={{q="Vem är Thrall?",a="Thrall leder orcfolket som hordens krigsöverhuvud. Han föddes som Go'el i Frostwolf-klanen och uppfostrades av människor som förslavad gladiator. Sedan bröt han sig fri, lärde sig schamanismens vägar och ledde orcerna till Kalimdor, där de grundade Orgrimmar.",al={"vem är krigshövding","thralls bakgrund","vem är thrall"}},{q="Varifrån kommer Thralls namn?",a="Thrall föddes som Go'el, namnet hans föräldrar Durotan och Draka gav honom. Hans mänsklige fångvaktare Aedelas Blackmoore gav honom namnet Thrall, ett gammalt mänskligt ord som betyder slav. Thrall behöll det som en påminnelse om sitt förflutna och om förtrycket som hans folk svor att aldrig mer utstå.",al={"varför kallas han thrall","vad betyder thrall","thralls riktiga namn"}},{q="Varför bär Thrall svart rustning och en hammare?",a="Thrall bär svart plåtrustning och har med sig Doomhammer, som båda överlämnades till honom av den tidigare krigsöverhuvudet Orgrim Doomhammer. Orgrim blev dödligt sårad när han befriade orcerna från fånglägren. Med sitt sista andetag gav han Thrall vapnet och ämbetet som krigsöverhuvud.",al={"doomhammer","thralls vapen","svart rustning"}},{q="Var hittar jag Thrall i spelet?",a="Thrall bor i Visdomens dal i Orgrimmar, hordens huvudstad i Durotar. Han står inne i Grommash Hold med sina livvakter och rådgivare.",al={"var är thrall","thralls plats","thralls rum"}},{q="Hurdan är Thralls relation till Jaina Proudmoore?",a="Thrall och Lady Jaina Proudmoore vann varandras respekt och slöt en samarbetsöverenskommelse när de stred sida vid sida vid Mount Hyjal under det tredje kriget. Deras fraktioner misstror fortfarande varandra djupt, men de två ledarna arbetar för att bevara den sköra freden mellan Orgrimmar och Theramore.",al={"thrall och jaina","jaina och alliansen","fred med theramore"}},{q="Varför lät Thrall Forsaken gå med i horden?",a="Trots sin försiktighet inför de odöda insåg Thrall det desperata läget för Sylvanas Windrunners Forsaken, som hade befriat sig från Lich Kings kontroll. Taurerna vädjade diplomatiskt till honom, eftersom de trodde att Forsaken kunde finna försoning. Thrall släppte in dem i horden för att säkra ett strategiskt fotfäste i Eastern Kingdoms.",al={"varför finns odöda i horden","forsaken och alliansen","sylvanas inträde i horden"}}},fx={["6dbf9cfd"]={q="Vem står Thrall på?",a="Thrall leder Horden som dess överhövding. Han byggde upp fraktionen från fångar i spillror till en allians för överlevnad och förenade sina egna orker med Darkspear Trolls, Kalimdors taurenfolk och på senare tid Lordaerons Forsaken. Han är orubbligt lojal mot sitt folk, men strävar också efter en bräcklig fred med Alliansen.",al={"thralls fraktion","vem leder thrall","thrall: alliansen eller horden"}},["4a2053d7"]={q="Vad vill Thrall?",a="Thrall vill ge Horden en trygg och hedervärd framtid, långt från den demoniska fördärv och blodtörst som en gång ledde hans folk mot undergången. Han strävar efter att skapa ett permanent hem i Durotar, återknyta orkernas band till deras forntida shamantraditioner och bevara en bräcklig samexistens med grannarna i stället för att kasta Kalimdor in i ändlös blodsutgjutelse.",al={"vad är thralls mål","thralls drivkrafter","thralls mål"}},b797ddf7={q="Varför är Thrall i Orgrimmar?",a="Orgrimmar är fästningsstaden som Thrall grundade och namngav till minne av Orgrim Doomhammer. Från sin plats i Grommash Hold leder han försvaret och utvecklingen av Durotar, övervakar Hordens diplomati och samtalar med andarna som både överhövding och mästershaman.",al={"varför är thrall här","varför är thrall i valley of wisdom","vad gör thrall i orgrimmar"}},c1597526={q="Varför är Thrall så berömd i Azeroth?",a="Thrall blev berömd när han krossade Alliansens interneringsläger, befriade de håglösa orkerna och återupprättade deras förlorade andliga arv. Hans legend växte ytterligare under Tredje kriget, då han ledde sitt folk över Stora havet och stred tillsammans med människor och nattalver på Mount Hyjal för att besegra den brinnande legionen.",al={"varför fruktas thrall","är thrall berömd","thralls legend"}}},fp="6,257,20.551.0,26.435.0,21.542.0,14.240.0,35.271.0,52.267.0,36.147.0,52.276.0,49.324.0"}
P.entries["npc:thran-khorman"] = {n="Thran Khorman",s="Thran Khorman är krigarinstruktören för dvärgar i Anvilmar, som ligger inbäddat i det snöiga Coldridge Valley. Han leder grundläggande stridsövningar för nyblivna krigare som ger sig ut i Dun Morogh.",h="Thran Khorman är krigarinstruktören för dvärgar i Anvilmar, som ligger inbäddat i det snöiga Coldridge Valley.",kw={"anvilmar","coldridge pass","dun morogh","ironforge","thran khorman","krigarinstruktör"},ang={["class:Warrior"]="För dvärg- och gnomkrigare som vaknar upp i Coldridge Pass är Thran den allra första mästaren som prövar din tapperhet, ger dig dina första runor eller order och lär dig grunderna i stridskonsten för att överleva.",["race:Dwarf"]="Thran förkroppsligar Ironforges försvarares envisa, orubbliga beslutsamhet. Han håller dem redo även i fredstid, så att kungariket aldrig överrumplas."},sec={{t="Övningsmästare i Coldridge Valley",b="Thran Khorman står nära Anvilmars övningsfält och ska göra råa dvärgrekryter och besökande gnomer till disciplinerade kämpar. Han är kärv och kompromisslös mot alla som saknar mod för strid vid fronten. I hans ögon är freden bara en illusion, trots att det tredje kriget är över: troggar tränger in i Coldridge Pass, och bergen är fortfarande fulla av faror. Han kräver oupphörlig träning med yxa, stridsklubba och sköld, så att Ironforges försvarare aldrig tappar skärpan."}},faq={{q="Vem är Thran Khorman?",a="Thran Khorman är dvärgarnas krigarinstruktör i Anvilmar i Dun Morogh. Han ger nybörjare grundläggande stridsvägledning och undervisning när de inleder sina äventyr i Coldridge Valley.",al={"thran khormans roll","vem är thran","krigarinstruktör i anvilmar"}},{q="Vilken träning erbjuder han?",a="Han lär nybörjare de grundläggande disciplinerna inom stridskonst och hjälper dem att finslipa sin hållning, närstridsteknik och stridsvilja innan de ger sig av för att möta troggar och vilddjur i passet.",al={"vad lär thran ut","krigarfärdigheter hos thran"}},{q="Varför avfärdar han vissa resenärer eller är kort mot dem?",a="Thran lever för krigskonsten och har föga tålamod med dem som ägnar sig åt de mystiska, skuggornas eller subtila konsterna. Om du inte är krigare säger han rakt ut att du inte skulle överleva en enda dag under hans träningsregim.",al={"varför är thran otrevlig","skvaller om thran","thrans text för icke-krigare"}}},fx={["97dd6db6"]={q="Vem står Thran Khorman på?",a="Thran Khorman står stolt på Ironforges och Alliansens sida. Han är stationerad i Anvilmar i Coldridge Valley och ägnar sin styrka åt att träna nya dvärg- och gnomrekryter så att Dun Morogh kan försvaras mot alla hot.",al={"thran khormans lojalitet","thran khormans fraktion","vem tjänar thran"}},["1baa464c"]={q="Vad vill Thran Khorman?",a="Han vill att blivande kämpar tar stridsdisciplinen på allvar och håller sina färdigheter sylvassa. De stora krigen har visserligen upphört för stunden, men han tänker inte låta någon bli vek. Han kräver ett hängivet arbete av varje blivande krigare.",al={"thran khormans mål","vad bryr sig thran khorman om","thran khormans motiv"}},d4f40481={q="Varför är Thran Khorman här?",a="Thran är stationerad i Anvilmar för att forma oerfarna äventyrare till disciplinerade krigare. Coldridge Valley är prövningsplatsen för Ironforges nyaste försvarare, och han ser till att ingen ger sig ut i Dun Morogh utan att veta hur man svingar ett svärd och bär rustning.",al={"varför är thran khorman i anvilmar","vad för thran till coldridge valley","thran khormans uppgift"}}},fp="13,84,31.352.0,21.134.0,28.120.0,51.182.0"}
P.entries["npc:thunderaan"] = {n="Thunderaan",s="Prins Thunderaan är den uråldrige luftens prins, en kolossal elementarvarelse som föll och förråddes under de forntida krigen mellan eld och vind. Ragnaros eldherren slukade en del av honom, och hans återstående väsen förseglades i krossade bindningar som anförtroddes åt eldherrens löjtnanter. Äventyrare som återfinner dessa reliker kan söka upp Highlord Demitrian i Silithus och släppa honom fri igen.",h="Prins Thunderaan är den uråldrige luftens prins, en kolossal elementarvarelse som föll och förråddes under de...",kw={"bindningar","demitrian","garr","geddon","molten core","luftens prins","ragnaros","silithus","thunderaan","thunderfury","windseeker"},ang={["class:Rogue"]="Rogues som söker oöverträffad snabbhet och blixtsnabb strid åtrår luftens prins fallna väsen, bundet i den ikoniska klingan Thunderfury.",["class:Shaman"]="Som elementens andliga väktare känner shaman igen Thunderaan som en av Azeroths renaste och mest vredgade förkroppsliganden av luft och blixtar.",["class:Warrior"]="Warriors söker legenden om Thunderfury, det stormladdade svärdet som förknippas med luftens prins."},sec={{t="Elementarklyvningen",b="För länge sedan, under Elementarklyvningen – en femtusenårig strid mellan eldens och luftens krafter djupt inne i Azeroth – försökte Ragnaros förgöra och sluka Thunderaan. Prinsen överfölls och förråddes av Ragnaros mäktiga löjtnanter, Baron Geddon och Garr, innan eldherren slog ner honom med sin hammare, Sulfuras. Trots nederlaget var Thunderaans väsen för mäktigt för att Ragnaros skulle kunna absorbera det helt."},{t="Den krossade talismanen",b="Eftersom Ragnaros inte kunde sluka luftens prins helt förseglade han det lilla som återstod av Thunderaans väsen i en talisman för elementarbindning. För att hindra prinsen från att någonsin återbildas krossade eldherren talismanen i två felfria halvor. Han anförtrodde den ena delen åt Baron Geddon och den andra åt Garr, och gömde båda i Molten Cores vulkaniska djup under Blackrock Mountain."},{t="Återfödelse i Silithus",b="De som vågar invadera Molten Core kan slita åt sig båda bindningens halvor från Ragnaros löjtnanter. När fragmenten visas för Highlord Demitrian, en excentrisk eremit med band till Twilight's Hammer i Silithus torra sanddyner, inleds en ritual för att frambringa luftens prins. Den nyfödda elementarvarelsen visar sig dock inte tacksam, utan rasande som en cyklon, och tvingar besvärjarna att fälla honom för att ta hans legendariska klinga, Thunderfury, Blessed Blade of the Windseeker."}},faq={{q="Vem är Thunderaan?",a="Thunderaan är luftens prins, en ädel och förödande elementarherre som står på vindens sida. För länge sedan besegrades han av Ragnaros eldherren och förseglades i ett elementarfängelse.",al={"vem är prins thunderaan","luftens prins","thunderaans historia"}},{q="Hur besegrades Thunderaan ursprungligen?",a="Under Elementarklyvningen smidde Ragnaros planer med sina löjtnanter Baron Geddon och Garr för att förråda prinsen. Thunderaan krossades av Sulfuras, och medan Ragnaros festade på hans väsen kunde han inte smälta det helt. Därför tvingades han låsa in resten i en kluven talisman.",al={"hur dog thunderaan","ragnaros mot thunderaan","elementarklyvningen"}},{q="Var förvaras delarna av hans bindning?",a="Thunderaans bindningens två felfria halvor hålls av Garr och Baron Geddon, djupt inne i Molten Core under Blackrock Mountain.",al={"var finns bindings of the windseeker","var finns thunderaans bindningar","garrs och geddons bindningar"}},{q="Varför är Highlord Demitrian i Silithus inblandad?",a="Highlord Demitrian är en lärjunge till Twilight's Hammer som bor i Silithus. Han har de magiska och elementära kunskaper som krävs för att återskapa den krossade talismanen och kalla luftens prins till Azeroth.",al={"vem är demitrian","highlord demitrian och thunderaan","hur kallar man thunderaan"}},{q="Vad händer när Thunderaan kallas till Silithus?",a="Demitrian kan utföra en farlig ritual med de återfunna bindningarna. Vad som framträder får du veta när ritualen är fullbordad.",al={"thunderaans strid","vad händer efter kallelsen"}},{q="Vilket vapen är knutet till Thunderaan?",a="Thunderfury, Blessed Blade of the Windseeker, är det legendariska svärd som är knutet till luftens prins. Dess öde avslöjas genom Demitrians ritual.",al={"thunderfury","windseeker-svärdet","thunderaans svärd"}}},fp="10,386,23.429.0,22.398.0,19.488.1,18.188.0,39.286.0,41.136.0,47.216.0,53.127.1,34.145.1"}
P.entries["npc:thyn-tel-bladeweaver"] = {n="Thyn'tel Bladeweaver",s="Thyn'tel Bladeweaver är en nattalvssentinel stationerad på Warrior's Terrace i Darnassus. Hon är djupt bekymrad över Priestess Velinde Starsongs försvinnande och skickar betrodda äventyrare från Alliansen för att leta efter ledtrådar om var hon befinner sig. Genom sina efterforskningar försöker hon lägga pusslet bakom Scythe of Elune.",h="Thyn'tel Bladeweaver är en nattalvssentinel stationerad på Warrior's Terrace i Darnassus.",kw={"bladeweaver","darnassus","scythe of elune","sentinel","starsong","thyn'tel","velinde","warrior's terrace"},ang={["class:Warrior"]="Thyn'tel står mitt bland tränarna på Warrior's Terrace och är ett välbekant sentinelansikte för allianskrigare som passerar genom Darnassus.",["faction:Alliance"]="Allianshjältar som besöker Warrior's Terrace får Thyn'tels förtroende och skickas djupt in i neutrala och omstridda områden för att avslöja sanningen.",["race:NightElf"]="För nattalver ligger Thyn'tels uppdrag nära hjärtat och blottlägger den dolda tragedin bakom en vördad prästinna som föll offer för krafter bortom hennes kontroll."},sec={{t="En sentinels undersökning",b="Thyn'tel Bladeweaver vakar över Darnassus från Warrior's Terrace och företräder kaldoreis vaksamma militära gren. När Priestess Velinde Starsong försvann under mystiska omständigheter utan att lämna något meddelande vägrade Thyn'tel låta spåren kallna. Hon anar att mörka krafter ligger bakom och tar på sig att anlita äventyrare som är villiga att granska prästinnans personliga tillhörigheter och ta reda på vart hennes resa ledde."},{t="I Velindes fotspår",b="Thyn'tel ber utredarna undersöka Velindes kvarlämnade tillhörigheter i huvudstaden. Ledtrådarna avslöjar en dagbok som beskriver Velindes gemenskap med Elune och de skräckinjagande worgenbestar som kallades fram med Scythe of Elune. Med Thyn'tels vägledning följer resenärerna spåren söderut genom hamnstaden Ratchet och vidare in i The Barrens, i ett försök att ta reda på vart den desperata prästinnan seglade innan hon försvann helt."}},faq={{q="Vem är Thyn'tel Bladeweaver?",a="Thyn'tel Bladeweaver är en nattalvssentinel på Warrior's Terrace i Darnassus. Hon fungerar som uppdragsgivare och inleder undersökningen av Priestess Velinde Starsongs försvinnande.",al={"thyntel bladeweaver","vem är thyntel","thyn'tel information"}},{q="Var hittar jag Thyn'tel Bladeweaver?",a="Hon står i Darnassus, närmare bestämt på Warrior's Terrace bland kaldoreikrigarna och sentinelerna.",al={"thyn'tels plats","var finns thyn'tel bladeweaver","thyntel karta"}},{q="Vilka uppdrag erbjuder Thyn'tel Bladeweaver?",a="Hon är den främsta kontaktpersonen för uppdragskedjan som undersöker Velinde Starsong och erbjuder uppdrag som 'Velinde's Effects', 'The Barrens Port' och avslutningsvis 'Answered Questions'.",al={"thyntels uppdrag","vilket uppdrag ger hon"}},{q="Varför är hon intresserad av Velinde Starsong?",a="Velinde Starsong var en prästinna som tjänstgjorde i Ashenvale tills hon plötsligt försvann och lämnade sitt arbete ofärdigt. Thyn'tel vill ta reda på vad som hände henne och avslöja det mörka mysteriet kring hennes avfärd.",al={"varför utreda velinde","vad hände med velinde"}},{q="Vart leder hennes uppdragskedja?",a="När utredarna har granskat Velindes tillhörigheter i Darnassus skickar Thyn'tel dem söderut över havet till Ratchet i The Barrens för att leta efter frakthandlingar om Velindes resa.",al={"velindes uppdragsväg","vart leder uppdraget"}},{q="Är Thyn'tel Bladeweaver en kontakt enbart för Alliansen?",a="Ja. Thyn'tel Bladeweaver är stationerad i nattalvernas huvudstad Darnassus och erbjuder bara uppdrag till medlemmar i Alliansen.",al={"kan horden prata med thyntel","är hon med i alliansen"}}},fx={["294bf631"]={q="Vem står Thyn'tel Bladeweaver på?",a="Thyn'tel Bladeweaver står stadigt på nattalvernas sida i Darnassus och på den bredare Alliansens. Bland sitt eget folk tjänar hon försvaret och säkerheten för Kalimdors väktarbesittningar. Hon hjälper dem som är lojala mot Alliansen och söker svar om försvunna kamrater.",al={"thyn'tel bladeweavers fraktion","är thyn'tel med alliansen"}},["187a5321"]={q="Vad vill Thyn'tel Bladeweaver?",a="Thyn'tel söker sanningen bakom nattalvssentineln Velinde Starsongs försvinnande. Hon ger pålitliga äventyrare i uppdrag att ta reda på Velindes sista steg, återfinna hennes personliga tillhörigheter och följa det gåtfulla spår som lämnats efter henne genom The Barrens och bortom.",al={"vad vill thyn'tel","thyn'tels mål"}},["7964d285"]={q="Varför är Thyn'tel Bladeweaver här?",a="Thyn'tel är kvar på sin post för att samordna efterforskningar och stödja nattalvernas styrkor. Från sin utsiktspunkt fungerar hon som kontaktperson för utredningar långt utanför alvernas gränser och skickar betrodda spejare till avlägsna länder för att lösa olösta mysterier som hotar hennes folk.",al={"varför är thyn'tel här","thyn'tel bladeweavers syfte"}},["48b9097d"]={q="Vilka band har Thyn'tel Bladeweaver?",a="Thyn'tel har nära band till den försvunna sentineln Velinde Starsong, vars försvinnande hon aktivt utreder. Hennes uppdrag är direkt knutna till Velindes expeditions öde. Hon skickar budbärare över Kalimdor för att ta reda på vad som hände med sentineln och de mäktiga reliker hon bar med sig.",al={"thyn'tel bladeweavers band","thyn'tel och velinde starsong"}}},fp="20,224,20.329.0,23.395.1,28.159.0,38.114.0,44.173.0,42.165.0,32.138.0,49.99.0"}
P.entries["npc:tirion-fordring"] = {n="Tirion Fordring",s="Tirion Fordring är en legendarisk paladin och tidigare herre över Mardenholde Keep, som nu lever i stillsam exil i Eastern Plaguelands. Som paladin i Knights of the Silver Hand fråntogs han sin titel och sina landområden för att han hedrade en hedersskuld till en fiende, en orch. Från sin enkla stuga vid Thondroril River vakar han över tragedin som utspelar sig i Lordaeron och oroar sig för sin son.",h="Tirion Fordring är en legendarisk paladin och tidigare herre över Mardenholde Keep, som nu lever i stillsam...",kw={"alonsus faol","eitrigg","exil","fordring","hearthglen","mardenholde","silver hand","taelan","thondroril","tirion"},ang={["class:Paladin"]="Att stå framför Tirion är att stå inför din ordens levande gryning. Han är en riddare av Silver Hand från det andra kriget och en mästare på det heliga ljuset, som visade att sann rättfärdighet står över dödligas lagar.",["faction:Alliance"]="Tirion förkroppsligar idealen som Alliansen grundades på, trots att samma kungariken stämplade honom som förrädare för att han satte personlig heder framför rashat.",["race:Human"]="Tirion var en oöverträffad hjälte i Alliansen i Lordaeron och styrde Hearthglen rättvist, en smärtsam påminnelse om det ädla kungarike som föll samman i förruttnelse och vansinne.",["race:Orc"]="Tirion var en krigare i Alliansen som dödade många under det andra kriget, men gav upp allt — sitt land, sin familj och sitt namn — hellre än att bryta en hedersed han svurit till orchen Eitrigg."},sec={{t="En riddare av Knights of the Silver Hand",b="Innan Lordaeron ödelades var Tirion Fordring känd som en av kungarikets främsta riddare. Som paladin i Knights of the Silver Hand, orden som ärkebiskop Alonsus Faol grundade under det andra kriget, stred Tirion mot den gamla horden med plåtrustning, hammare och helig hängivenhet. Han vördnades som ett orubbligt föredöme för det heliga ljuset."},{t="En fråga om heder och exil",b="Efter det andra kriget styrde Tirion området Hearthglen från Mardenholde Keep tillsammans med sin hustru Karandra och sin unge son Taelan. Hans styre tog slut när han mötte en åldrad orchkrigare vid namn Eitrigg, som levde som eremit. Tirion insåg veteranens djupa hederskänsla och lovade att skydda honom. När Alliansens myndigheter upptäckte Eitrigg stred Tirion mot sina egna landsmän för att hålla sitt löfte. För detta förräderi mot Alliansen i Lordaeron fråntogs Tirion sin adelstitel, bannlystes från Silver Hand och dömdes till exil. Uther skonade hans hustru och son från straffet."},{t="En fars plåga",b="Hans familj skonades från hans exil och blev kvar i Hearthglen. Efter Lordaerons fall till Scourge under det tredje kriget växte Tirions son Taelan upp och anslöt sig till Scarlet Crusade. Så småningom blev han Highlord i Hearthglen. Tirion ser på håll hur korståget sjunker ner i vansinne och förtvivlar över att hans son blivit en fanatismens marionett. Eremiten vid Thondroril klamrar sig fast vid minnen av lyckligare tider, som familjens besök i Caer Darrow, och söker ett sätt att påminna sin pojke om sann heder."}},faq={{q="Vem är Tirion Fordring?",a="Tirion Fordring är paladin i Knights of the Silver Hand och tidigare ståthållare över Hearthglen. Hans jämlikar landsförvisade honom för att han försvarade en orch av hedersskäl. Nu lever han som eremit i en avskild stuga vid den västra gränsen av Eastern Plaguelands.",al={"tirions historia","vem är den gamle paladinen","vem är tirion","eremitpaladin"}},{q="Varför landsförvisades Tirion från Lordaeron?",a="Tirion upptäckte en gammal orchveteran vid namn Eitrigg och insåg att de delade en djupt rotad känsla för krigarheder. När Alliansens styrkor tillfångatog Eitrigg angrep Tirion sina egna kamrater för att hålla sitt löfte att försvara eremiten. Han betraktades som förrädare, fråntogs sina titlar och förvisades från kungariket.",al={"varför landsförvisades tirion","tirions förräderi","varför är tirion landsförvisad"}},{q="Vilken koppling har Tirion till Hearthglen?",a="Hearthglen var Tirions tidigare säte. Han styrde området från Mardenholde Keep fram till sin exil. I dag kontrolleras Hearthglen av Scarlet Crusade, som leds av hans son, Highlord Taelan Fordring.",al={"tirion hearthglen","tirion mardenholde keep","hearthglens herre"}},{q="Har Tirion fortfarande sina paladinkrafter?",a="Kyrkan och Silver Hand fråntog honom formellt hans rang och hävdade att de återkallade hans heliga krafter, men Tirions rena övertygelse gjorde att hans band till det heliga ljuset förblev obrutet. Ljuset svarade på hans vilja lika starkt som någonsin.",al={"förlorade tirion ljuset","är tirion fortfarande paladin","använder tirion ljuset"}},{q="Vad vill Tirion med Scarlet Crusade?",a="Tirion hyser ingen kärlek till Scarlet Crusades fanatiska iver, men hans son Taelan tjänstgör som en av dess högsta befälhavare i Hearthglen. Tirion hoppas väcka Taelans samvete och befria honom från korstågets fördärvade grepp innan hans själ går helt förlorad.",al={"tirion scarlet crusade","tirion och taelan","varför bryr sig tirion om korståget"}},{q="Vilka var de andra ursprungliga paladinerna?",a="Ärkebiskop Alonsus Faol grundade Knights of the Silver Hand under det andra kriget, med Uther the Lightbringer som dess första paladin. Bland Tirions riddarbröder fanns Turalyon och hans nära vän Saidan Dathrohan.",al={"första paladinerna","ursprungliga paladinerna i silver hand","alonsus faols paladiner"}}},fp="15,389,27.334.0,27.595.0,18.522.1,23.260.0,37.308.0,42.199.0,42.256.0,47.259.0,36.225.0"}
P.entries["npc:tiza-battleforge"] = {n="Tiza Battleforge",s="Tiza Battleforge är en erfaren dvärgpaladin i Silver Hand-riddarna, stationerad i Ironforges Hall of Mysteries. Hon är känd för sin orubbliga hängivenhet och insikt och vägleder unga dvärgpaladiner på dygdens, välgörenhetens och självuppoffringens väg. Genom studier av heliga texter och prövningar i fält testar hon om noviserna verkligen är redo att utöva Ljusets gåva att återuppväcka de döda.",h="Tiza Battleforge är en erfaren dvärgpaladin i Silver Hand-riddarna, stationerad i Ironforges Hall of...",kw={"dvärg","hall of mysteries","ironforge","muiredon battleforge","mystic ward","paladin","redemption","silver hand","tiza battleforge","tome of divinity"},ang={["class:Paladin"]="För dvärgpaladiner är Tiza Battleforge en viktig mentor som prövar om du är värdig genom Tome of Divinity och anförtror dig kraften att återuppväcka fallna allierade.",["faction:Alliance"]="Tiza samarbetar nära med mentorer från Stormwind till Kharanos för att Silver Hand ska upprätthålla gemensamma normer för dygd och stridsberedskap i alla Alliansens länder.",["race:Dwarf"]="Tiza står för det Heliga Ljusets djupa förankring i dvärgarnas kultur och Silver Hand och vägleder Khaz Modans försvarare mot hot som Dark Iron-klanen."},sec={{t="Mentor i Mystic Ward",b="I de fridfulla kamrarna i Ironforges Hall of Mysteries är Tiza Battleforge en av Silver Hand-riddarnas mest respekterade dvärgpaladiner. Noviser från hela Alliansen skickas till henne för att fördjupa sin andliga utbildning, på inrådan av lärare som Brandur Ironhammer i Ironforge, Azar Stronghammer i Dun Morogh och Lord Grayson Shadowbreaker i Stormwind. Tiza anser att det Heliga Ljuset kräver mer än stridskonst. Det kräver ödmjuk tjänst, medkänsla och orubblig styrka inför hoten från Scourge och andra faror."},{t="Gudomlighetens prövningar",b="När unga paladiner kommer för att söka djupare mysterier ger Tiza dem Tome of Divinity. Efter att de studerat texten skickar hon dem för att utföra konkreta, osjälviska välgärningar, med början i att hjälpa behövande som John Turner. Sedan utmanar hon noviserna att sätta sin tro och skicklighet på spel för att hjälpa hennes make, Muiredon Battleforge, mot det regionala hotet från Dark Iron-dvärgarna. De som klarar prövningarna och återupplivar fallna allierade med Symbol of Life anses av Tiza värdiga att utöva den heliga konsten att återuppväcka de döda."}},faq={{q="Vem är Tiza Battleforge?",a="Tiza Battleforge är en högt ansedd dvärgpaladin i Silver Hand-riddarna. I Hall of Mysteries i Ironforge prövar och vägleder hon dvärgpaladiner som vill fördjupa sitt band till det Heliga Ljuset.",al={"vem är tiza","tiza battleforge berättelse","paladintränaren tiza"}},{q="Var hittar jag Tiza Battleforge?",a="Hon finns i Hall of Mysteries, centrumet för andliga och mystiska studier i Ironforges Mystic Ward.",al={"tizas plats","var finns tiza battleforge","paladintränare i hall of mysteries"}},{q="Vad är Tome of Divinity, som hon ger paladiner?",a="Tome of Divinity är en helig lärobok som innehåller det Heliga Ljusets grundläggande dygder och läror. Tiza ger den till paladiner så att de kan studera dess lärdomar innan de ger sig ut på praktiska prövningar i välgörenhet, mod och barmhärtighet.",al={"tome of divinity tiza","tizas bokuppdrag","vad är tome of divinity"}},{q="Varför skickar Tiza paladiner för att hjälpa sin make Muiredon?",a="Hennes make, Muiredon Battleforge, möter fientliga hot från Dark Iron-dvärgarna medan han försöker hjälpa sin följeslagare Narm Faulk. Tiza använder krisen för att pröva novisens mod i strid och beredskap att använda Symbol of Life för att rädda fallna kamrater från dödens rand.",al={"tizas make uppdrag","muiredon battleforge koppling","varför hjälpa muiredon"}},{q="Vilken förmåga lär Tiza ut till värdiga paladiner?",a="När novisen har klarat hennes prövningar i välgörenhet och räddat Muiredons fallna följeslagare ger Tiza novisen kraften Redemption, paladinens heliga ritual för att återuppväcka de döda.",al={"tizas paladinförtrollning","vilken förmåga lär tiza ut","paladintränare för återuppväckning i ironforge"}},{q="Vilken koppling har hon till Brandur Ironhammer?",a="Brandur Ironhammer är en annan dvärgpaladin och tränare, stationerad tillsammans med henne i Ironforges Hall of Mysteries. Tiza påpekade en gång öppet för Brandur att hans svartsjuka var en andlig svaghet. Då lovade han henne att försöka övervinna den.",al={"tiza och brandur","brandur ironhammer tiza","brandurs svartsjuka"}}},fx={["28fe0e8a"]={q="Vilken sida står Tiza Battleforge på?",a="Tiza står stolt vid Alliansens, kungariket Ironforges och Silverhandens riddarordens sida. Som hängiven paladin svär hon ytterst sin trohet till det heliga ljuset och försvaret av Azeroth mot ondskor som Scourge och de förrädiska Dark Iron-dvärgarna.",al={"tiza battleforges fraktion","vem tjänar tiza","tiza battleforge och alliansen"}},["5d20b420"]={q="Vad vill Tiza Battleforge?",a="Tiza vill fostra sann dygd, givmildhet och orubblig tro hos nya paladiner. Förutom att pröva deras stridsförmåga och hängivenhet genom heliga prov samlar hon information om lokala faror, som Dark Iron-infall, för att varna stadsrådet och hålla Ironforge tryggt.",al={"tiza battleforges mål","vad vill tiza","tizas motiv"}},["075b45b0"]={q="Varför är Tiza Battleforge här i Hall of Mysteries?",a="Hon bor i Hall of Mysteries i Ironforges Mystic Ward och vägleder dvärgar som vill bli paladiner. I stadens heliga ordens hjärta handleder hon rekryter som Alliansens befälhavare skickat dit. Hon prövar deras osjälviskhet och hängivenhet till Silver Hand innan hon inviger dem i ljusets högre mysterier.",al={"varför är tiza i ironforge","varför befinner sig tiza battleforge här","varför är tiza här"}},["90c1fa9e"]={q="Varför är Tiza Battleforge respekterad bland dvärgarna?",a="Tiza är känd som en av Ironforges mest respekterade paladiner. Erfarna veteraner i hela Alliansen, från Lord Grayson Shadowbreaker i Stormwind till lokala paladintränare, värdesätter hennes visdom högt och litar fullständigt på hennes omdöme när hon prövar nya rekryters moraliska styrka.",al={"tiza battleforges rykte","är tiza battleforge berömd","respekt för tiza"}}},fp="16,206,25.451.0,22.429.1,24.170.0,34.109.0,51.167.0,57.228.0,45.150.0,45.180.0"}
P.entries["npc:tommy-joe-stonefield"] = {n="Tommy Joe Stonefield",s="Vid floden väster om The Stonefield Farm längtar Tommy Joe Stonefield efter Maybell Maclure. Familjerna har legat i fejd i åratal, så han förlitar sig på hemliga meddelanden och avskilda flodstränder för att hålla kärleken hemlig.",h="Vid floden väster om The Stonefield Farm längtar Tommy Joe Stonefield efter Maybell Maclure.",kw={"elwynn forest","gramma stonefield","maybell maclure","the stonefield farm","tommy joe stonefield","unga älskande"},ang={["faction:Alliance"]="Som Alliance-äventyrare i södra Elwynn kan du se Tommy Joes hemliga romans som en påminnelse om de stillsamma personliga liv som fortsätter mitt bland banditdåd och politisk oro."},sec={{t="En fejd full av hinder",b="Tommy Joe Stonefield väntar vid floden väster om The Stonefield Farm och ser mot Maclures gård på andra sidan vattnet. Stonefield- och Maclurefamiljerna har varit osams i åratal om mark, stolthet och gräl på gårdarna. De äldre håller fejden vid liv, men Tommy Joe har förälskat sig i Maybell Maclure. De kan inte träffas öppet utan att göra båda hushållen arga. Gramma Stonefield, Tommy Joes förstående farmor, hjälper dem att utbyta hemliga meddelanden och kärleksgåvor."}},faq={{q="Vem är Tommy Joe Stonefield?",a="Tommy Joe Stonefield är en ung människa som bor på The Stonefield Farm i Elwynn Forest. Han är i hemlighet förälskad i Maybell Maclure, dottern till sin familjs bittra rivaler.",al={"tommy joe","vem är tommy joe","stonefieldson"}},{q="Var hittar jag Tommy Joe Stonefield?",a="Tommy Joe Stonefield står på flodstranden väster om The Stonefield Farm och ser över vattnet mot Maclures gård, där Maybell bor.",al={"tommy joes plats","var är tommy joe","hitta tommy joe"}},{q="Varför strider Stonefield- och Maclurefamiljerna?",a="Ingen säger vad som startade fejden. Stonefield- och Maclurefamiljerna har upprätthållit sin bittra rivalitet i åratal, och ingen av familjerna vill att deras unga ska umgås med den andra.",al={"familjefejd","varför hatar de varandra","fejden mellan stonefield och maclure"}},{q="Vem hjälper Tommy Joe och Maybell att träffas?",a="Gramma Stonefield känner till deras kärlek och hjälper dem med deras hemliga uppvaktning. Hon låter resande bära diskreta meddelanden mellan Tommy Joe och Maybell.",al={"gramma stonefield hjälper","hjälp till hemliga älskande","vem hjälper de älskande"}}},fx={["3c95bb6e"]={q="Vilken sida står Tommy Joe Stonefield på?",a="Han tillhör familjen Stonefield, men hans hjärta är inte med i deras bittra fejd. Han bor på Stonefield Farm, men slits mellan sin familj och kärleken till Maybell Maclure, som tillhör familjens svurna rivaler.",al={"tommy joes lojalitet","tommy joes familj","stonefield eller maclure"}},["8a9aad66"]={q="Vad vill Tommy Joe Stonefield?",a="Tommy Joe önskar inget hellre än att vara med Maybell Maclure. Det långvariga hatet mellan familjerna Stonefield och Maclure håller dem isär, så han längtar efter ett sätt att träffa henne i hemlighet och hålla deras kärlek vid liv trots fejden.",al={"vad vill tommy joe","tommy joes mål","tommy joes önskan"}},["96565570"]={q="Varför är Tommy Joe Stonefield här?",a="Tommy Joe väntar tyst vid flodstranden nära familjens gård. Platsen ligger avskilt från nyfikna blickar, så han kan smita från sina sysslor och hoppas få träffa Maybell i hemlighet, långt från deras stridande familjer.",al={"varför är tommy joe vid floden","vad gör tommy joe här","varför är tommy joe stonefield här"}},b663afb0={q="Vilka band har Tommy Joe Stonefield?",a="Han tillhör klanen Stonefield och får mycket stöd av sin farmor, Gramma Stonefield. Hon hjälper honom aktivt. Hans viktigaste band är ändå till Maybell Maclure, dottern till hans familjs bittra rivaler, som han är djupt förälskad i.",al={"tommy joes band","tommy joes familj","vilka är släkt med tommy joe"}}},fp="20,201,19.473.0,28.171.0,38.144.0,46.174.0,37.153.0"}
P.entries["npc:tonga-runetotem"] = {n="Tonga Runetotem",s="Vid The Crossroads vakar Tonga Runetotem på hur The Barrens oaser blir sjuka. Taurendruiden har skickats från Thunder Bluff och undersöker en förorening som skadar traktens djurliv. Han söker dess källa innan det sköra ekosystemet kollapsar.",h="Vid The Crossroads vakar Tonga Runetotem på hur The Barrens oaser blir sjuka.",kw={"the barrens","the crossroads","druid","the forgotten pools","oaser","runetotem","the stagnant oasis","tonga","wailing caverns"},ang={["class:Druid"]="Som taurendruid under utbildning kan du se hur Cenarion Circles läror hjälper till att diagnostisera och rena fördärvade marker långt från Moonglade.",["faction:Horde"]="Som medlem av Horde är du beroende av Tongas undersökningar för att hålla The Barrens huvudväg beboelig och trygg från magiska hot under marken.",["race:Tauren"]="Som tauren delar du Tongas plikt gentemot Earth Mother när han arbetar för att skydda de knappa vatten som upprätthåller livet över de torra slätterna."},sec={{t="Väktare vid The Crossroads",b="Vid The Crossroads studerar Tonga Runetotem hur The Barrens landskap förändras. Hans äldste i Thunder Bluff skickade honom från Mulgore, och han känner den torra savannen väl. Där resenärer ser snår och rovdjur spanar Tonga efter tecken på hur landet mår. På sistone har tecknen blivit oroande. Han söker resenärer som kan hjälpa honom att undersöka de utspridda oaserna, savannens livsnerv."},{t="Förgiftat vatten och förvridna bestar",b="Vatten är en bristvara i The Barrens, och The Forgotten Pools och The Stagnant Oasis har blivit oberäkneliga. Märkliga magiska ångor bubblar upp, och varelser som dricker ur vattnen förändras till aggressiva, onaturliga former. Tonga samlar växt- och djurprover för att ta reda på om sjukdomen beror på naturligt förfall eller en yttre kraft. Hans fynd pekar mot djupa sprickor under marken, som förbinder de förgiftade pölarna med gångarna i Wailing Caverns."},{t="Runetotemsläktet",b="Tonga bär klannamnet Runetotem och det druidiska arv som Archdruid Hamuul Runetotem för vidare. Hamuul har band till Cenarion Circle och studerar i Moonglades heliga lundar, medan spanare som Tonga tjänstgör i gränslandet. Tonga använder Moonglades botaniska kunskap för att tillreda läkande salvor och motgifter. Hans arbete låter den unga taurernas druidtradition komma till användning inom den gryende Horde."}},faq={{q="Vem är Tonga Runetotem?",a="Tonga Runetotem är en taurendruid nära värdshuset vid The Crossroads i The Barrens. Hans äldste i Thunder Bluff skickade honom för att undersöka en märklig förorening som sprider sig över savannen.",al={"tonga runetotem","vem är tonga","druiden vid the crossroads"}},{q="Vad undersöker Tonga i The Barrens?",a="Tonga undersöker märkliga ångor, muterade bestar och förorenat vatten i The Barrens oaser, däribland The Forgotten Pools och The Stagnant Oasis.",al={"vad gör tonga","tongas uppdrag","varför undersöka oaser"}},{q="Var tror Tonga att fördärvelsen kommer ifrån?",a="Tonga tror att den magiska föroreningen kommer från djupt under jord i Wailing Caverns, efter att ha studerat förändrade varelser och vattensprickor.",al={"orsaken till oasernas fördärvelse","varifrån kommer smittan","kopplingen till wailing caverns"}},{q="Är Tonga släkt med Hamuul Runetotem?",a="Tonga och Hamuul Runetotem delar namnet Runetotem, men det är okänt om de är släkt. Tonga skickar bud om problemen i The Barrens till Archdruid Hamuul, den äldre druiden på Thunder Bluffs Elder Rise.",al={"är han släkt med hamuul","runetotemsläkten","släktskap med hamuul"}},{q="Vad gör Tonga för det förgiftade djurlivet?",a="Tonga använder lärdomar från Moonglade och lokala ingredienser för att tillreda salvor åt förgiftade gaseller och motverka gifter från platser som Dreadmist Peak.",al={"botemedel för gaseller","tonga botar sjuka","gift från dreadmist peak"}},{q="Varför håller Tonga till vid The Crossroads i stället för Camp Taurajo eller Thunder Bluff?",a="The Crossroads ligger vid det centrala navet i norra The Barrens, nära de drabbade oaserna. Därifrån kan Tonga nå resenärer som kan ge sig ut i farliga trakter åt honom.",al={"varför the crossroads","varför är tonga här"}}},fx={["5ac3f48e"]={q="Vilken sida står Tonga Runetotem på?",a="Tonga står fast vid Horden och sina taurenbröder och systrar i Thunder Bluff. Hans folks ledare har skickat honom för att läka landet och skydda resenärer som passerar The Crossroads. Han samarbetar nära med druider från Moonglade för att bevara naturens balans i Kalimdor.",al={"tonga runetotems fraktion","vem tjänar tonga","är tonga runetotem med i horden"}},["8af7bcfa"]={q="Vad vill Tonga Runetotem?",a="Tonga vill hitta och rensa bort den onaturliga smitta som sprider sig i The Barrens vattenkällor. Han tar hjälp av dugliga äventyrare för att undersöka oaserna i trakten, samla prover på muterad flora och fauna och ge förgiftade djur motmedel. Han försöker hejda fördärvet innan det ödelägger hela området.",al={"vad vill tonga","tonga runetotems mål","tonga runetotems syfte"}}},fp="15,222,25.395.0,32.462.1,21.409.0,23.182.0,43.146.0,55.144.1,37.203.0,45.150.0,82.172.0"}
P.entries["npc:tormus-deepforge"] = {n="Tormus Deepforge",s="Tormus Deepforge är en dvärgisk smed som arbetar mitt i Great Forge i Ironforge. Han är en pålitlig hantverkare och samordnar järnleveranser samt förser försvaret av Alliansen med vapen i Khaz Modan och längre bort.",h="Tormus Deepforge är en dvärgisk smed som arbetar mitt i Great Forge i Ironforge.",kw={"smed","deepforge","dvärg","great forge","ironforge","lochinver","tormus"},ang={["profession:Blacksmithing"]="För smederna som utövar sitt hantverk vid Great Forge är Tormus den oumbärliga länken mellan råa järnstänger och utrustningen vid fronten.",["race:Dwarf"]="Som en stolt hantverkare i bergariket visar Tormus att Ironforge är redo att smälta och leverera vapen närhelst allierade i Grand Alliance ber om hjälp."},sec={{t="Mästare vid Great Forge",b="Tormus Deepforge arbetar alldeles intill Great Forges dånande eldar och leder omfattande metallarbete för Bronzebeard-klanens räkning. Utöver att själv hamra stål sörjer Tormus sin mentor Sturgy Ironband, vars smedja söder om Helm's Bed Lake i östra Dun Morogh blev översvämmad av Dark Iron-dvärgar efter att en last märklig skymningsmalm anlänt dit."}},faq={{q="Var hittar jag Tormus Deepforge?",a="Tormus står på den cirkelformade gångvägen runt Great Forges lavapool, i Ironforges mittpunkt.",al={"tormus plats","var finns tormus","tormus deepforge karta"}},{q="Vilken roll spelar Tormus i Alliansens krigsinsats?",a="Tormus smider vapen åt unga krigare som skickas till honom vid Great Forge. I gengäld ber han dem hämnas hans mentor Sturgy Ironband genom att gå in i Ironband's Compound i Dun Morogh och återta skymningsmalmen som Dark Iron-dvärgarna dödade för. Sedan bearbetar han malmen till nya vapen av grått järn.",al={"vad gör tormus","tormus uppgift","varför prata med tormus"}},{q="Vilka är de andra Deepforge-dvärgarna?",a="Flera dvärgar bär namnet Deepforge, däribland Bengus, Murgot och Kaita Deepforge, liksom Tormus kollega Thorvald i Loch Modan. Det har dock aldrig bekräftats om de är släkt.",al={"deepforge-klanen","deepforge-familjen","är tormus släkt med murgot"}}},fx={["7c43f5fd"]={q="Vem är Tormus Deepforge?",a="Tormus Deepforge är en mästersmed bland dvärgarna och arbetar vid Great Forge i Ironforge. Han är känd för sin skicklighet med järn och stål och spelar en viktig roll i tillverkningen av utrustning och samordningen av vapentransporter till allierade styrkor i Eastern Kingdoms.",al={"vem är tormus","tormus deepforge i berättelsen","vem är deepforge"}},["43326af9"]={q="Vilken sida står Tormus Deepforge på?",a="Tormus är djupt lojal mot King Magni Bronzebeard och Alliansen. Från sin plats mitt i dvärgarnas huvudstad ägnar han sitt hantverk åt att se till att Alliansens soldater och avlägsna utposter får vapnen och förnödenheterna de behöver för att stå emot sina fiender.",al={"tormus deepforges fraktion","vem tjänar tormus","är tormus med i alliansen"}},["6189f272"]={q="Vad vill Tormus Deepforge?",a="Tormus vill smida fina vapen och hämnas sin mentor Sturgy Ironband. Dark Iron-dvärgarna dödade alla vid Ironband's Compound i Dun Morogh efter att en last märklig skuggskenande malm kommit dit. Tormus ber äventyrare slå tillbaka mot dem och hämta malmen åt honom så att han kan lära sig mer om dess egenskaper.",al={"vad vill tormus","tormus mål","tormus deepforges uppdrag"}},["14a6c7e2"]={q="Varför är Tormus Deepforge i Ironforge?",a="Han arbetar vid Great Forge, Khaz Modans industriella hjärta. Där styr han tillsammans med Ironforges främsta rustningsmakare och vapensmeder de väldiga eldarna och städen som krävs för att smida tunga vapen åt kungarikets krigsmakt.",al={"varför är tormus i ironforge","varför är tormus här","tormus vid great forge"}}},fp="16,164,25.322.0,34.85.0,54.290.0,29.191.0"}
P.entries["npc:torwa-pathfinder"] = {n="Torwa Pathfinder",s="Torwa Pathfinder är en ensam taurenjägare och spårare som slagit läger vid ingången till Un'Goro Crater, strax nedanför rampen från Tanaris. Han studerar bäckenets uråldriga djurliv och de farliga rovdjur som härskar på djungelns mark. Äventyrare som vill pröva sin förmåga mot kraterns legendariska bestar söker ofta hans råd.",h="Torwa Pathfinder är en ensam taurenjägare och spårare som slagit läger vid ingången till Un'Goro Crater...",kw={"bloodpetal","lar'korwi","spårare","rovfågel","tanaris","torwa","u'cha","ungoro"},ang={["class:Hunter"]="Torwa visar den skicklighet och det tålamod som krävs av en mästerspåraren. Han lär att ett topprovdjur bäst lockas fram genom förståelse för dess föda, doft och revirvanor, inte genom rå styrka.",["race:Tauren"]="För vandrande tauren är det betryggande att hitta Torwa vid kraterns kant. Han påminner om folkets vördnad för naturen, även mitt i Un'Goros förhistoriska kaos."},sec={{t="Väktare vid gränsen",b="Torwa Pathfinder har slagit läger vid kraterns östra fot, där Tanaris ökensand möter den fuktiga djungelhettan, och fungerar som en inofficiell väktare för nykomlingar. Han respekterar Un'Goro Craters vilda krafter och vet att oförsiktiga vandrare snabbt blir föda åt den lokala faunan. Hans läger erbjuder en sällsynt stunds vila innan resenärer ger sig ner i det heta djupet."},{t="Jakten på Lar'korwi",b="Mycket av Torwas uppmärksamhet går åt till Lar'korwi, en ökänd och listig rovfågel som strövar omkring i kraterns norra delar. Torwa vet att rå styrka inte räcker för att fälla ett sådant topprovdjur. I stället lär han jägare att studera dess matvanor och använda färskt kadaverkött och körtlar för att göra ett bete som lockar fram besten i det öppna."},{t="Uråldriga gifter och bestar",b="Utöver jakten på kraterns främsta rovfåglar är Torwa mycket nyfiken på de giftiga växterna och de aggressiva apkolonierna i bäckenet. Han ber resenärer samla gift från de oberäkneliga bloodpetals och studera styrkan hos dominerande bestar som den mäktiga gorillan U'cha. Han analyserar ständigt hur naturens dödligaste anpassningar fungerar i isolering."}},faq={{q="Var hittar jag Torwa Pathfinder?",a="Torwa har slagit läger nära den östra kanten av Un'Goro Crater, alldeles vid foten av den slingrande rampen som leder upp till Tanaris öken.",al={"torwas plats","var finns torwa","hitta torwa pathfinder"}},{q="Vad är Lar'korwi?",a="Lar'korwi är en legendarisk och svårfångad rovfågel som stryker omkring i Un'Goro Crater. Den är känd för sin våldsamhet och list, och går inte lätt att spåra på vanligt vis. Den måste lockas fram med särskilt bete.",al={"larkorwi","vem är larkorwi","vad är larkorwi"}},{q="Ger Torwa bara uppdrag till spelare i Horde?",a="Nej. Trots att han är tauren agerar Torwa Pathfinder självständigt i vildmarken. Han delar med sig av sina spårningskunskaper och jaktutmaningar till dugliga äventyrare från både Alliance och Horde.",al={"är torwa bara för horde","kan alliance prata med torwa","torwas fraktion"}},{q="Varför är Torwa intresserad av Bloodpetals?",a="Torwa fascineras av de inhemska växternas dödliga försvar i Un'Goro. Han ber äventyrare samla sekret från aggressiva bloodpetals för att förstå och pröva styrkan i deras naturliga gifter.",al={"bloodpetal-uppdrag","varför bloodpetals","torwas gift"}},{q="Vem är U'cha?",a="U'cha är en ovanligt kraftfull gorilla som håller till i grottorna och apornas områden i Un'Goro. Torwa utmanar jägare att besegra U'cha och bevisa sin skicklighet mot bäckenets starkaste bestar.",al={"mäktiga u'cha","gorillaboss i ungoro","ucha-uppdrag"}}},fp="16,349,24.386.0,22.382.0,25.370.0,34.139.0,18.197.0,46.194.0,39.200.0,13.198.0"}
P.entries["npc:treshala-fallowbrook"] = {n="Treshala Fallowbrook",s="Treshala Fallowbrook är en Night Elf som bor stillsamt på övre våningen av Tradesmen's Terrace i Darnassus. Hon är gift med Heralath Fallowbrook, vars arbete har fört honom långt hemifrån, in i de taggiga djupen av Razorfen Kraul i The Barrens.",h="Treshala Fallowbrook är en Night Elf som bor stillsamt på övre våningen av Tradesmen's Terrace i Darnassus.",kw={"darnassus","fallowbrook","dödlighetens avtagande","night elf","razorfen kraul","tradesmen's terrace","treshala"},ang={["faction:Alliance"]="Treshala fungerar som kontaktperson för Alliansen i Darnassus för hjältar som återvänder från plågsamma expeditioner mot quilboarernas tagghålor djupt inne i The Barrens.",["race:NightElf"]="För nattalver är Treshalas stilla väntan på sin make en påminnelse om att hennes folk inte längre har evigheten på sig att vänta sedan Mount Hyjal."},sec={{t="En väktare på terrassen",b="Treshala Fallowbrook håller stilla vakt på andra våningen i en verkstad på Tradesmen's Terrace i Darnassus. Hennes make Heralath reste till de snåriga djupen av Razorfen Kraul i The Barrens, och hon väntar hemma på nyheter om honom. De förenas av ett bindningshänge, ett minne av deras äktenskap som Heralath tog med sig in i quilboarernas hålor."}},faq={{q="Var hittar jag Treshala Fallowbrook?",a="Hon finns på andra våningen i en verkstad på Tradesmen's Terrace i Darnassus. Du når hennes rum genom att gå uppför den invändiga trärampen i vapenbyggnaden.",al={"treshalas plats","var finns fallowbrook","hur hittar man treshala"}},{q="Vad forskar Treshala om?",a="Hon är inte själv forskare. Arbetet tillhör hennes make Heralath Fallowbrook, vars resa förde honom till Razorfen Kraul. Treshala väntar i Darnassus på nyheter om honom och om sitt bindningshänge, som han tog med sig dit.",al={"treshala uppdrag","dödlighetens avtagande historia","vad vill treshala"}},{q="Varför bryr hon sig om Razorfen Kraul?",a="Hennes make Heralath gav sig in i Razorfen Kraul, quilboarernas taggiga fäste i The Barrens, och hon har inte fått några nyheter om honom sedan dess.",al={"varför razorfen kraul","fallowbrook razorfen","koppling till rfk"}},{q="Är hon köpman eller hantverkare?",a="Nej, Treshala är varken köpman eller hantverkare. Hon bor helt enkelt ovanför de livliga hantverksstånden på Tradesmen's Terrace.",al={"är treshala försäljare","vad säljer hon"}}},fx={["145b1f19"]={q="Vem är Treshala Fallowbrook?",a="Treshala Fallowbrook är en nattalv som bor i Tradesmen's Terrace i Darnassus. Hennes make, Heralath Fallowbrook, har rest till Razorfen Kraul, och hon väntar på nyheter om honom.",al={"vem är treshala","treshala fallowbrook i berättelsen","treshalas identitet"}},["308e08c8"]={q="Vilken sida står Treshala Fallowbrook på?",a="Treshala står på Darnassus och Alliansens sida. Hon bor i nattalvernas huvudstad medan hennes make, Heralath, är borta i Razorfen Kraul.",al={"treshala fallowbrooks fraktion","är treshala med i alliansen","treshalas lojaliteter"}},["5c8a152e"]={q="Vad vill Treshala Fallowbrook?",a="Treshala oroar sig för sin make, Heralath Fallowbrook, och bindningsamuletten han tog med sig till Razorfen Kraul. Det är till henne resenärer ska komma med nyheter om honom.",al={"vad vill treshala","treshala fallowbrooks uppdrag","varför vill treshala ha quilboar-föremål"}}},fp="20,149,24.298.0,38.162.0,29.176.0,41.165.0,37.117.0"}
P.entries["npc:tsunaman"] = {n="Tsunaman",s="Tsunaman är en tänkande vattenelemental som är stationerad vid Sun Rock Retreat i Stonetalon Mountains. Som agent för Tribunal of the Tides vakar han över Kalimdors elementarströmmar och samlar Horde-äventyrare för att möta korrumperande krafter.",h="Tsunaman är en tänkande vattenelemental som är stationerad vid Sun Rock Retreat i Stonetalon Mountains.",kw={"the charred vale","neptulon","stonetalon","sun rock retreat","tribunal of the tides","problem i djupet","tsunaman","vattenelemental"},ang={["class:Shaman"]="För schamaner som strävar efter att förstå och kommunicera med elementen erbjuder Tsunaman en sällsynt möjlighet att tala direkt med ett sändebud från Tidehunters hov.",["faction:Horde"]="Tsunaman ser Horde vid Sun Rock Retreat som lämpliga allierade mot elementär obalans och kultisters intrång i Kalimdors vatten."},sec={{t="Tidernas agent",b="Tsunaman bor nära stigen som leder från Sun Rock Retreat ner till The Charred Vale och tjänar Tribunal of the Tides, högt uppsatta tjänare i Tidehunter Neptulons tjänst. I stället för att visa tanklös fientlighet mot dödliga resenärer samarbetar han med Horde för att hålla uppsikt över elementaroroligheter i Kalimdor, särskilt störningarna som sprider sig från Blackfathom Deeps nedsänkta grottor."},{t="Hat mot eld",b="Tsunaman är trogen sin elementarnatur och hyser ett instinktivt, ursinnigt hat mot eld i alla former. Han rasar ständigt över de närliggande brinnande landskapen i The Charred Vale och elementära eldinkräktare. I lägret är hans agg så småaktigt och obevekligt att han regelbundet marscherar fram till närliggande matlagningseldar och lägereldar bara för att slå ut dem med en tung knytnäve av vatten."}},faq={{q="Vem är Tsunaman?",a="Tsunaman är en vattenelemental vid Sun Rock Retreat i Stonetalon Mountains. Han tjänar som sändebud för Tribunal of the Tides, håller uppsikt över elementarkonflikter i Kalimdor och söker hjälp mot onaturliga störningar.",al={"vem är tsunaman","tsunamans historia","vad är tsunaman"}},{q="Varför angriper Tsunaman lägerelden?",a="Tsunaman avskyr eldelementaler och själva tanken på eld. Drivna av elementär rivalitet brukar han då och då stampa fram till lägereldar som resenärer tänt vid Sun Rock Retreat och släcka dem med ett vattenfyllt slag.",al={"tsunaman slår till eld","varför slår tsunaman på eld","vattenelemental lägereld"}},{q="Vad är Tribunal of the Tides?",a="Tribunal of the Tides är en orden av mäktiga elementära befälhavare som tjänar Neptulon the Tidehunter, vattnets Elemental Lord. De vakar över de vattenrika domänerna och reagerar på störningar i världens vatten.",al={"tribunal of the tides","vem tjänar tsunaman"}},{q="Varför intresserar sig Tsunaman för Blackfathom Deeps?",a="Blackfathom Deeps har förorenats av skymningskultister och mörka krafter som korrumperar de inhemska vattenandarna. Tsunaman värvar Horde-äventyrare för att utforska det sjunkna templet och stilla kaoset som stör vattnen.",al={"tsunaman blackfathom","problem i djupet"}}},fx={["83418127"]={q="På vems sida står Tsunaman?",a="Tsunaman lyder varken Horde eller Alliances dödliga raser. Han tjänar vattnets elementarkrafter, särskilt Tribunal of the Tides, som är högt uppsatta löjtnanter under Neptulon the Tidehunter. Han tolererar besökare vid Sun Rock Retreat och värvar äventyrare mot gemensamma fiender, men hans verkliga lojalitet tillhör helt vattendjupen och hans elementarfränder.",al={"tsunamans fraktion","vem tjänar tsunaman","tsunamans lojalitet"}},d98f482b={q="Vad vill Tsunaman?",a="Tsunaman drivs av den uråldriga elementarkampen. Han vill utplåna rivaliserande eldelementarer och avskyr eld i alla former. Han ger sig regelbundet på till och med enkla lägereldar. Dessutom arbetar han för att främja Tribunal of the Tides intressen genom att rekrytera dugliga dödliga för att hantera mörka störningar i vattenhelgedomar som Blackfathom Deeps.",al={"tsunamans mål","vad försöker tsunaman göra","vad tsunaman vill"}},["37c31a70"]={q="Varför är Tsunaman här vid Sun Rock Retreat?",a="Tsunaman håller till längs stigen från Sun Rock Retreat mot de svedda markerna i The Charred Vale. Här håller han, på uppdrag av Tribunal of the Tides, uppsikt över de närliggande elementarkonflikterna i Stonetalon Mountains och söker upp äventyrare som passerar. De kan slå till mot de framryckande eldiga fienderna eller våga sig ner i oroliga underjordiska vatten.",al={"varför är tsunaman i stonetalon","varför är tsunaman vid sun rock retreat","varför kom tsunaman hit"}}},fp="8,148,18.323.0,15.243.0,16.204.0,38.164.0,34.217.0,48.208.0"}
P.entries["npc:turak-runetotem"] = {n="Turak Runetotem",s="Turak Runetotem är en vördad tränare för tauren-druider och bor i Hall of Elders på Elder Rise i Thunder Bluff. Som betrodd assistent åt ärkedruiden Hamuul Runetotem vägleder han unga tauren på naturens och balansens heliga stigar. Under Turaks ledning genomgår unga druider grundläggande prövningar för att nå andarna och bemästra djurens aspekter.",h="Turak Runetotem är en vördad tränare för tauren-druider och bor i Hall of Elders på Elder Rise i Thunder...",kw={"vattenform","björnform","dendrite starblaze","druid","elder rise","hall of elders","hamuul","lunaclaw","moonglade","runetotem","thunder bluff","turak"},ang={["class:Druid"]="För tauren-druider är Turak Runetotem en grundpelare i den tidiga träningen. Han ger dem förmågan att teleportera sig till Moonglade och prövar aspiranter tills de förtjänar sina björn- och vattenformer.",["faction:Horde"]="Turak spelar en avgörande roll i att förankra naturmagi inom Horden och tränar väktare som kan bekämpa plågor, miljöförstöring och de kvardröjande såren över Kalimdor.",["race:Tauren"]="Som medlem av Runetotem-stammen förkroppsligar Turak återupplivandet av taurenfolkets druidiska traditioner efter det tredje kriget och hjälper sitt folk att återfinna sin uråldriga harmoni med Jordmodern."},sec={{t="Jordmodern talar",b="I Hall of Elders fridfulla salar är Turak Runetotem en av Hordens främsta druida mentorer. Han är känd för sitt stora tålamod och sitt balanserade sinnelag och hjälper ärkedruiden Hamuul Runetotem att återuppliva taurenfolkets uråldriga druidkonster. Turak ser till att varje blivande druid vördar Jordmoderns vilja och lär dem att fysisk styrka alltid måste vila på andlig vördnad och harmoni med naturen."},{t="Kloens väg",b="När en ung druid är redo att anta djurformer leder Turak ut honom i den vida världen. Han inleder deras kontakt med Cenarion Circle och lär ut konsten att teleportera sig genom Kalimdor till den heliga fristaden Moonglade. Turak minns hur förbryllande och intensivt hans eget möte med den stora björnens ande var i ungdomen, och prövar elevernas mod genom att skicka dem att möta Lunaclaw och vinna den styrka i kropp och själ som krävs för att gå Kloens väg."},{t="Balansens väktare",b="Turaks vägledning sträcker sig bortom ursprungliga stridsformer till omsorg om miljön. Han skickar sina lärjungar tillbaka till Dendrite Starblaze för att lära sig om gifter, och Dendrite sänder dem till en rad djurförgiftningar nära The Crossroads, något som överraskar till och med Turak. Genom dessa prövningar och de mödosamma ritualerna under vattenytan för att väcka vattenformen formar Turak nybörjare till uthålliga beskyddare som kan läka Azeroths djupaste sår."}},faq={{q="Var hittar jag Turak Runetotem?",a="Turak Runetotem finns på Elder Rise i Thunder Bluff, i tältet vid Hall of Elders tillsammans med ärkedruiden Hamuul Runetotem.",al={"turaks plats","var finns turak runetotem","turak runetotem i thunder bluff"}},{q="Vilken roll har Turak för nya druider?",a="Han är den främsta uppdragsgivaren och instruktören för unga tauren-druider. Han lär dem att nå Moonglade, låser upp deras björn- och vattenformer genom heliga prövningar och lär dem att bota naturliga gifter.",al={"vad lär turak ut","turak druidtränare","turaks roll"}},{q="Vilken koppling har Turak till Moonglade?",a="Turak lär unga druider besvärjelsen som teleporterar dem direkt till Moonglades heliga lund och hänvisar dem till Cenarion Circles representant, Dendrite Starblaze, för djupare andlig vägledning.",al={"turak moonglade","hur känner turak dendrite","turak teleportering till moonglade"}},{q="Hur är Turak släkt med ärkedruiden Hamuul Runetotem?",a="Båda tillhör den vördnadsvärda Runetotem-stammen. Turak tjänar direkt under ärkedruiden Hamuul som en av hans mest betrodda assistenter och lärare i Hall of Elders.",al={"är turak släkt med hamuul","hamuul och turak"}},{q="Varför skickar Turak druider till The Crossroads?",a="Turak skickar elever till Dendrite Starblaze i Moonglade för att lära sig om gifter, och Dendrite sänder dem för att hjälpa till med en rad djurförgiftningar kring The Crossroads. När de återvänder belönar Turak dem med förmågan att bota gift för gott.",al={"turak the crossroads","turaks giftuppdrag","makt över gift"}},{q="Vilken egen erfarenhet har Turak av den stora björnens ande?",a="Turak berättar öppet att när han först gick vägen för att bli en Kloens druid var kontakten med den stora björnens ande förbryllande men oerhört intensiv, en upplevelse som fördjupade hans vördnad för formen.",al={"turak björnens ande","turak kloens väg"}}},fx={fcca94f0={q="Vem är Turak Runetotem?",a="Turak Runetotem är en vis och tålmodig taurendruidtränare som bor i Hall of Elders på Thunder Bluffs Elder Rise. Han är en betrodd assistent till Archdruid Hamuul Runetotem och vandrar i djup balans med naturen. Turak ägnar sig åt att vägleda unga druider i Horde genom deras första prövningar, hjälpa dem att stämma in med vildmarkens andar och bemästra Cenarion Circles uråldriga läror.",al={"vem är turak","turak runetotems historia","turaks identitet"}},d36f6346={q="På vems sida står Turak Runetotem?",a="Turak är hängiven både Thunder Bluffs taurer i Horde och Cenarion Circle. Han representerar det växande druidsambandet mellan taurer och nattalver och förenar Hordes traditionella lojaliteter med den heliga, partipolitiskt obundna plikten att läka och skydda Azeroths naturliga balans.",al={"turaks fraktion","vem tjänar turak","turaks lojalitet"}},b696f0bb={q="Vad vill Turak Runetotem?",a="Turak vill fostra nästa generation taurendruider och skydda landet från fördärv. Han vill att noviserna ska förstå naturens kraft i dess sanna form. Han uppmanar dem att tala med andar som Great Bear, klara prövningar för både kropp och själ och använda sina gåvor för att rena gifter och återställa harmonin i Kalimdor.",al={"turaks mål","vad är turaks syfte","turaks motiv"}},["83600788"]={q="Varför är Turak Runetotem här?",a="Turak är stationerad i Hall of Elders på Elder Rise, där han tjänstgör tillsammans med Archdruid Hamuul Runetotem. Hamuul leder alla taurers druidsamlingar, medan Turak är hans främsta lärare på de höga klipporna. Han förbereder personligen nya druider innan han skickar dem vidare till Moonglade och vidare uppdrag i The Barrens.",al={"varför är turak i thunder bluff","varför är turak på elder rise","turaks syfte i thunder bluff"}}},fp="15,239,24.347.0,20.423.0,20.421.0,33.112.0,41.163.0,40.143.0,51.132.0,45.218.0,64.203.0"}
P.entries["npc:twilight-lord-kelris"] = {n="Twilight Lord Kelris",s="Twilight Lord Kelris är en orchisk häxmästare och högt uppsatt ledare inom kulten Twilight's Hammer, som verkar djupt inne i Blackfathom Deeps. Från sin plats i Moonshrine Sanctum leder han mörka ritualer till ära för urhydran Aku'mai, i syfte att inleda en era av kosmiskt kaos.",h="Twilight Lord Kelris är en orchisk häxmästare och högt uppsatt ledare inom kulten Twilight's Hammer, som...",kw={"aku'mai","argent dawn","blackfathom deeps","kelris","moonshrine sanctum","gamla gudar","twilight lord","twilight's hammer"},ang={["class:Warlock"]="Vanliga häxmästare sluter avtal med demoner från Burning Legion, men Kelris visar upp mörk, transframkallad skuggmagi som föds när man ger efter för de gamla gudarnas viskningar.",["faction:Alliance"]="Argent Dawn, som verkar från Darnassus, vill sätta stopp för Kelris svårfångade verksamhet, där han hetsar mörka kulter och sprider skräck över norra Kalimdor.",["faction:Horde"]="Äldste och schamaner ser Kelris som ett avskräckande vidunder: en orch som övergav elementen och förfädernas andar för att kräla inför uråldriga kosmiska fasor.",["race:NightElf"]="Kelris hädiska ritualer skändar aktivt det heliga Moonshrine Sanctum, ett uråldrigt alviskt tempel helgat åt Elune."},sec={{t="Tomhetens härold",b="Twilight Lord Kelris leder kultisterna i Twilight's Hammer, som tog över de sjunkna ruinerna i Blackfathom Deeps. I åratal undkom Kelris de vaksamma ögonen i Darnassus, undvek Argent Dawn och fick ett dystert rykte: varje gång uråldrig ondska rörde sig över Kalimdor misstänktes Kelris ligga bakom. I stället för att tjäna krigsherrar eller klaner har den här orchen helt och hållet svurit sig åt de gamla gudarna. Han vill förgöra den dödligas civilisation och återföra Azeroth till ett tillstånd av fullständigt, ursprungligt kaos."},{t="Odjurets väktare",b="I Moonshrine Sanctum vakar Kelris över kultens dyrkan av Aku'mai, en grym trehövdad hydra och tjänare åt en gammal gud. Twilight's Hammer har tagit det översvämmade templet i besittning tillsammans med naga, och Kelris leder kultens riter där oskyldiga offras till Aku'mai i utbyte mot kraft."},{t="Mörk trans och slummer",b="Kelris behärskar mäktig skuggmagi som kan ta kontroll över sinnen och försänka inkräktare i en djup, onaturlig sömn. Han ber ständigt framför ett vanhelgat altare omgivet av ljus som kanaliserar mörka energier. Den som försöker fälla Kelris måste både besegra kultledaren och ta sig igenom de slumrande fasor som vaknar när hans rituella vaka bryts."}},faq={{q="Vem är Twilight Lord Kelris?",a="Twilight Lord Kelris är en orchisk trollkarl som leder Twilight's Hammer i Blackfathom Deeps. Han samordnar kultens verksamhet i det sjunkna templet och är djupt hängiven de gamla gudarna.",al={"kelris bakgrund","vem är kelris","kelris historia"}},{q="Varför jagar Argent Dawn Kelris?",a="Argent Dawn ser Kelris som en svårfångad uppviglare till ondska över hela Kalimdor. Han troddes en gång vara död eller försvunnen, men hans inblandning upptäcktes bakom många mörka komplotter på kontinenten. Därför är det en prioritet att röja honom ur vägen.",al={"argent dawn kelris","varför döda kelris","varför är blackfathom ondskefullt"}},{q="Vad gör Kelris med hydran Aku'mai?",a="Kelris och kultisterna i Twilight's Hammer dyrkar Aku'mai, en trehövdad hydra och tjänare åt en gammal gud, som håller till i den djupaste delen av det sjunkna templet.",al={"kelris och akumai","varför matar kelris akumai"}},{q="Vad händer när Kelris besegras?",a="Bakom Kelris står ett altare med fyra ceremoniella ljus. När du tänder dem upplöses helgedomens skyddande barriärer, vågor av Aku'mais tjänare kallas fram och den förseglade porten till odjurets håla öppnas.",al={"kelris ljus","kelris altare","moonshrine-ljus"}},{q="Vilka krafter använder Kelris i strid?",a="Kelris använder mäktiga skuggformler, mental dominans och magisk slummer som kan oskadliggöra hans fiender medan hans mörka riter fortsätter.",al={"kelris förmågor","kelris besvärjelser"}},{q="Vem är Bashana Runetotem?",a="Bashana Runetotem är en allierad som undersöker fördärvet i Blackfathom Deeps. Hon varnar äventyrare för Kelris besatthet av dyrkan av de gamla gudarna och hans önskan att kasta världen tillbaka i ursprungligt kaos.",al={"bashana runetotem kelris","taurenjägare kelris"}}},fx={e447f79b={q="På vems sida står Twilight Lord Kelris?",a="Kelris leder Twilight's Hammer-kultens lokala cell. Han tjänar varken Horde eller Alliance, utan ägnar sitt liv helt åt dyrkan och tjänandet av de uråldriga Old Gods och åt att återföra den ursprungliga kaosmakten till Azeroth.",al={"kelris fraktion","vem tjänar kelris","twilight lord kelris lojalitet"}},["710418bf"]={q="Varför är Twilight Lord Kelris här i Blackfathom Deeps?",a="Kelris leder Twilight's Hammer i de sjunkna ruinerna, där kulten samtalar med Old Gods och dyrkar hydran Aku'mai, en tjänare till en av Old Gods. Från Moonshrine Sanctum leder han deras riter, långt från nyfikna ögon.",al={"varför är kelris i bfd","kelris syfte i blackfathom","varför kom kelris hit"}},["7c0659ed"]={q="Vilka band har Twilight Lord Kelris?",a="Utöver att leda Twilight's Hammers kultister i grottan styr Kelris kultens dyrkan av den fruktade hydran Aku'mai. Han har också band till de Old Gods han dyrkar och utför deras mörka planer i Kalimdor.",al={"kelris allierade","vem arbetar kelris med","kelris kontakter"}}},fp="20,257,18.404.0,19.287.0,23.346.1,28.212.0,38.232.0,44.160.0,38.197.1,38.131.0,25.218.0"}
P.entries["npc:tyrande-whisperwind"] = {n="Tyrande Whisperwind",s="Tyrande Whisperwind är Elunes översteprästinna och nattalvernas högsta ledare. Tillsammans med sin älskade, ärkedruiden Malfurion Stormrage, ledde hon sitt folk genom det katastrofala War of the Ancients och tiotusen år av Long Vigil. Från Teldrassils heliga grenar styr hon nu och leder Sisterhood of Elune samt Sentinels armé i försvaret av Kalimdors heliga vildmark.",h="Tyrande Whisperwind är Elunes översteprästinna och nattalvernas högsta ledare.",kw={"darnassus","elune","kaldorei","malfurion","prästinna","sentinels","teldrassil","tyrande","whisperwind"},ang={["class:Druid"]="Medan Malfurion sover i The Emerald Dream samarbetar Tyrande nära med Cenarion Circle för att skydda heliga lundar och vårda Teldrassil.",["class:Priest"]="Som levande förkroppsligande av Elunes gudomliga nåd personifierar Tyrande kaldoreiprästerskapets höjdpunkt. Hon kallar ner månens stjärnor och läker sår med sin rena tro.",["faction:Alliance"]="Tyrande har historiskt varit tillbakadragen och starkt självständig, men leder nattalverna inom Alliance för att säkra ett gemensamt försvar mot Kalimdors växande faror.",["faction:Horde"]="För Horde är Tyrande en mäktig och kompromisslös motståndare. Hon har beordrat Sentinels att med våld stoppa resursutvinning i Ashenvale.",["race:NightElf"]="Tyrande är din högsta ledare och översteprästinna. I över tiotusen år har hon hållit vakt över ditt folk och fört Elunes ljus genom varje prövning."},sec={{t="Mångudinnans utvalda",b="Tyrande föddes i det forntida kaldoreiimperiet och växte upp tillsammans med tvillingbröderna Malfurion och Illidan Stormrage. Medan bröderna ägnade sig åt druidism och trolldom trädde Tyrande i Elunes tjänst som prästinna. När den demoniska Burning Legion först invaderade Azeroth under War of the Ancients stod hon emot den vid Malfurions sida. Mångudinnan skänkte henne sin särskilda nåd, och Tyrande förvandlade Sisterhood till en strålande stridsstyrka. Med både gudomlig läkekraft och brännande månraseri räddade hon sitt folk från total undergång."},{t="Long Vigil och Sentinels",b="Efter Great Sundering och förseglingen av Well of Eternity gick Malfurion och druiderna in i The Emerald Dream för en lång dvala. Tyrande tog på sig den ensamma bördan att försvara deras återhämtande rike. Hon organiserade Sentinels, en elitstyrka av krigarkvinnor som patrullerade Kalimdors skogar i tiotusen år. Under hela Long Vigil höll hon vakt mot forntida ondska och kvarvarande demoniska lämningar. Hon behöll sin orubbliga tro på Elune medan hon väntade i århundraden mellan de korta återseendena med Malfurion."},{t="Third War och en ny fristad",b="När Burning Legion återvände under Third War handlade Tyrande beslutsamt för att väcka de sovande druiderna och möta det katastrofala hotet. Hon övervann sin djupa misstro mot de nyanlända orcherna och människorna och bidrog till att skapa den desperata alliansen vid Mount Hyjal. Där offrade nattalverna sin odödlighet vid Nordrassil för att krossa Archimonde. Mount Hyjal var sargat, och Malfurion hade återigen fullt upp med att skydda The Emerald Dream. Tyrande styr nu kaldorei från det storslagna Temple of the Moon i Darnassus och håller ett vaksamt öga på både Hordes intrång och sitt folks nya plats i Alliance."}},faq={{q="Vem är Tyrande Whisperwind?",a="Tyrande Whisperwind är Elunes översteprästinna och nattalvernas främsta andliga och politiska ledare. Hon har lett sitt folk i över tiotusen år, från War of the Ancients till Third War, och leder nu kaldorei från Temple of the Moon i Darnassus.",al={"vem är tyrande","tyrande whisperwind bakgrund","nattalvernas ledare"}},{q="Var bor Tyrande just nu?",a="Tyrande bor i huvudstaden Darnassus, högt uppe bland grenarna på världsträdet Teldrassil. Hon har sitt säte i Temple of the Moons övre helgedom, omgiven av Elunes prästinnor och Sentinel-vakter.",al={"var är tyrande","tyrandes plats","var hittar man tyrande"}},{q="Vilken relation har Tyrande och Malfurion?",a="Tyrande och Malfurion Stormrage är livslånga partners som tillsammans har lett nattalvernas civilisation i tiotusen år. I sin ungdom sökte både Malfurion och hans tvillingbror Illidan hennes kärlek, men Tyrande valde Malfurion. Hans djupa hängivenhet åt balans och natur speglade hennes tro på Elune.",al={"tyrande malfurion","är tyrande gift","tyrande och illidan"}},{q="Vad är Sisterhood of Elune?",a="Sisterhood of Elune är en uråldrig religiös orden av nattalvsprästinnor som dyrkar Mångudinnan. Under Tyrandes ledning som översteprästinna tjänar systrarna inte bara som helare och andliga vägledare, utan också som stridsledare och krigare.",al={"sisterhood of elune","elunes prästinnor","tyrandes präster"}},{q="Vilken roll hade Tyrande under Long Vigil?",a="Under de tiotusen åren efter Sundering, medan Malfurion och de manliga druiderna sov i The Emerald Dream, grundade och ledde Tyrande Sentinels. Hon patrullerade Kalimdors vildmark, jagade kvarvarande satyrer och demoner och skyddade sitt folk i isolering.",al={"vad var long vigil","tyrande long vigil","sentinels ledare"}},{q="Varför är Tyrande på sin vakt mot Horde?",a="Under Third War kom orcherna in i Ashenvale och började kalhugga heliga skogar. Under demonblodets inflytande dödade de halvguden Cenarius. En skör vapenvila slöts vid Mount Hyjal, men Hordes fortsatta skogsavverkning i Ashenvale gör att Tyrande håller sina Sentinels i högsta beredskap.",al={"tyrande horde","varför hatar tyrande orcher","nattalver mot horde"}}},fx={["0754c2cc"]={q="På vems sida står Tyrande Whisperwind?",a="Tyrande är nattalvernas högsta ledare och en av Grand Alliances grundpelare. Hon leder The Sisterhood of Elune och vägleder sitt folk från Temple of the Moon i Darnassus. Hon är helt hängiven åt att skydda Kalimdor och sitt folk mot yttre hot.",al={"vilken fraktion tillhör tyrande","tillhör tyrande alliance","tyrandes lojalitet"}},["68f13d2e"]={q="Vad vill Tyrande Whisperwind?",a="Hennes främsta plikt är att skydda kaldorei och Kalimdors heliga skogar från fördärvande krafter, vare sig det är demoniska kvarlevor eller främmande inkräktare. Medan Malfurion sover i The Emerald Dream bär hon också ansvaret för att vägleda och försvara deras nygrundade hem på Teldrassil.",al={"tyrandes mål","tyrandes motivation","vad försöker tyrande göra"}},ade9ee47={q="Varför är Tyrande Whisperwind berömd?",a="Tyrande vördas som Elunes utvalda översteprästinna, som hjälpte till att besegra Burning Legion i War of the Ancients för tiotusen år sedan. Under Long Vigil ledde hon Sentinels i försvaret av Kalimdor i årtusenden. Senare stod hon stadigt tillsammans med de dödliga raserna i slaget vid Mount Hyjal.",al={"varför vördas tyrande","tyrandes legender","tyrandes rykte"}}},fp="19,361,26.500.0,32.517.0,29.569.0,27.293.0,36.182.0,55.289.0,32.217.0,45.272.0,33.290.0"}
P.entries["npc:tyrion"] = {n="Tyrion",s="I Stormwind Keep håller Tyrion uppsikt över hovet och hjälper till med hemliga uppdrag. Gnomensamarbetar med Elling Trias för att samla information och motverka planer mot kungariket.",h="I Stormwind Keep håller Tyrion uppsikt över hovet och hjälper till med hemliga uppdrag.",kw={"elling trias","gnom","infiltrating the castle","items of some consequence","spion","stormwind keep","the attack","tyrion"},ang={["class:Rogue"]="Som skurk med uppdrag åt Elling Trias kan du lita på Tyrion som allierad i Stormwind Keep.",["faction:Alliance"]="Tyrions underrättelsearbete hjälper till att skydda kronan mot hemliga hot i rikets huvudstad.",["race:Gnome"]="Som gnom visar Tyrion den finess och det intellekt som gnomer bidrar med till Alliansens spioneri, medan han arbetar obemärkt under människornas adel."},sec={{t="En stillsam närvaro i fästet",b="Tyrion håller sig i Stormwind Keeps salar, håller uppsikt över palatset och har kontakt med personer utanför den officiella övervakningen."},{t="Skuggor och spioneri",b="Elling Trias, en osthandlare i Trade District, anförtror Tyrion känsliga ärenden. Trias driver ett diskret underrättelsenätverk och skickar pålitliga agenter till Tyrion när House of Nobles byråkrati måste kringgås."},{t="Avslöja hotet",b="Tyrion hjälper utredare att ta sig in på bevakade platser och säkra känsliga varor i staden. Hans arbete avslöjar en fara i kungarikets hjärta, och han varnar sina allierade innan ett organiserat anfall kan hota Stormwinds ledare."}},faq={{q="Vem är Tyrion?",a="Tyrion är en gnomisk agent i Stormwind Keep. Han sköter hemliga uppdrag och samlar information utanför de vanliga kungliga kanalerna.",al={"vem är den här gnomen","tyrions identitet","vad gör tyrion"}},{q="Var hittar jag Tyrion?",a="Tyrion befinner sig i Stormwind Keep i Stormwind City och håller utkik efter agenter som skickas av hans betrodda kontakter.",al={"tyrions plats","var är tyrion","hitta tyrion"}},{q="Vilken koppling har han till Elling Trias?",a="Tyrion och Elling Trias är gamla vänner och samarbetspartner. Trias samlar rykten genom sina handelskontakter och skickar pålitliga äventyrare till Tyrion när hemliga uppdrag behövs i fästet.",al={"tyrion och elling trias","känner tyrion trias","trias koppling"}},{q="Vilka uppdrag erbjuder Tyrion?",a="Tyrion deltar i hemliga operationer, däribland ”Infiltrating the Castle” och ”Items of Some Consequence”, och varnar allierade under ”The Attack!”.",al={"tyrions uppdrag","vilka uppdrag ger han"}},{q="Varför sköter en gnom hemliga operationer vid människornas hov?",a="Gnomer är viktiga allierade till Alliansen. Tyrion bidrar med skarpt intellekt, smidighet och teknisk uppfinningsrikedom i det hemliga arbetet vid människornas hov.",al={"varför finns en gnom i stormwind keep","gnomisk agent i fästet"}},{q="Vad handlar konspirationen som Tyrion utreder om?",a="Tyrion spårar stulen information och dolda planer vid det kungliga hovet, vilket leder till ett väpnat bakhåll i staden.",al={"tyrions konspiration","vad utreder tyrion"}}},fx={f469be85={q="På vems sida står Tyrion?",a="Tyrion verkar i det tysta inifrån Stormwind Keep tillsammans med sin gamle vän Elling Trias, mästerlig osthandlare och informatör med band till skurkar. Han arbetar genom skuggor, viskningar och hemligt spioneri, men hans lojalitet ligger hos Stormwinds och Alliances integritet. I det tysta vakar han över rikets säkerhet mot osynliga inre hot.",al={"är tyrion lojal mot stormwind","tyrions fraktion","vem arbetar tyrion för"}}},fp="6,163,28.138.0,21.230.0,21.227.1,14.131.0,24.112.0,39.201.0,30.149.0,61.143.0,55.125.1"}
P.entries["npc:ukor"] = {n="Ukor",s="Nära den östra stigen utanför Valley of Trials vilar Ukor efter att ha burit förnödenheter från Razor Hill. Träningsplatsen hade redan gott om sådant, och han hoppas att förråden ändå kan hjälpa hans folk.",h="Nära den östra stigen utanför Valley of Trials vilar Ukor efter att ha burit förnödenheter från Razor Hill.",kw={"en peons börda","durotar","grosk","peon","razor hill","ukor","valley of trials"},ang={["faction:Horde"]="För nya rekryter som kommer ut ur sina prövningar är hjälpen till Ukor ett tidigt tillfälle att bidra till den dagliga transporten av förnödenheter mellan hordens bosättningar.",["race:Orc"]="Orc-peoner utför det tunga kroppsarbetet som hjälper till att bygga den nya horden. Ukor visar att även enkla arbetare vill stödja Durotars krigare."},sec={{t="En peons ärende",b="Ukor vilar vid östra vägen utanför Valley of Trials, trött efter att ha burit mat söderut från Razor Hill. Orc-peoner tillbringar ofta dagarna med att hugga timmer eller släpa sten under hårda arbetsledare. Ukor valde på eget initiativ att ta med förnödenheter till rekryterna. Han korsade Durotars röda slätter, där skorpider och vildsvin stryker omkring, bara för att upptäcka att träningsplatsen redan var välförsedd. Hans packning behövdes inte. Nu ber han unga äventyrare på väg förbi att bära förnödenheterna norrut igen till Innkeeper Grosk."}},faq={{q="Vem är Ukor?",a="Ukor vilar längs vägen som leder österut från Valley of Trials i södra Durotar. Han är en uppriktig orc-peon.",al={"ukors berättelse","vem är ukor","vad gör ukor"}},{q="Varför står Ukor vid vägen med en säck mat?",a="Ukor bar ransoner från Razor Hill för att mätta de unga krigare som tränar i Valley of Trials. När han kom fram fann han att det redan fanns gott om förnödenheter där, och säcken behövdes inte.",al={"varför är ukor här","varför har ukor ett uppdrag","ukors matpacke"}},{q="Vad ber Ukor förbipasserande resenärer att göra?",a="Ukor ber resenärer på väg norrut mot Razor Hill att lämna tillbaka packningen till Innkeeper Grosk. Han är för rädd för bestarna längs vägen för att bära tillbaka den själv.",al={"ukors uppgift","vad vill ukor","peonens börda uppdrag"}}},fx={["5f505ef5"]={q="På vems sida står Ukor?",a="Ukor är en lojal peon i Horde. Han är ödmjuk och plikttrogen och tjänar Durotar och sitt folk genom att frakta förnödenheter och uträtta ärenden mellan bosättningar som Razor Hill och Valley of Trials. Han trotsar vilda djur utan att klaga.",al={"ukors fraktion","tillhör ukor horde","vem tjänar ukor"}},["2e03bca7"]={q="Vilka band har Ukor?",a="Ukor lyder under Innkeeper Grosk i Razor Hill. På Grosks vägnar begav han sig till Valley of Trials för att leverera färska förnödenheter. Han förlitar sig på att äventyrare som passerar lämnar tillbaka överskottsvaror till värdshusvärden.",al={"ukors allierade","vem känner ukor","ukor och innkeeper grosk"}}},fp="4,199,15.509.0,12.112.0,53.188.0,43.164.0"}
P.entries["npc:ula-elek"] = {n="Ula'elek",s="I Sen'jin Village smider Ula'elek rustningar åt krigare i hela Horde. Darkspear-smeden samarbetar med Thun'grim Firegaze och formar specialutrustning av traditionellt trollhantverk och troféer från hela Kalimdor.",h="I Sen'jin Village smider Ula'elek rustningar åt krigare i hela Horde.",kw={"brutal gauntlets","darkspear","durotar","satyrhovar","sen'jin village","smed","thun'grim firegaze","ula'elek"},ang={["class:Warrior"]="Som krigare förlitar du dig på att Ula'elek sätter ihop ditt Brutal-rustningsset och formar hårt förvärvade satyrhovar till tåliga handskar på uppdrag av Thun'grim Firegaze.",["profession:Blacksmithing"]="Som smed ser du hur Horde-smeder använder troféer från bestar och demoner till praktisk krigarutrustning, utanför de traditionella smedjorna.",["race:Troll"]="Som troll ser du hur Darkspear-smeder hjälper till att utrusta unga Horde-krigare genom att smida frontutrustning på Sen'jin Villages öppna stränder."},sec={{t="Darkspears smed",b="Ula'elek är en skicklig rustningssmed som tjänar Darkspear i Sen'jin Village. Närliggande quilboar och havskrypare hotar kustbosättningen, så stammen behöver tåliga rustningar och fungerande klingor. Ula'eleks skicklighet lockar också härdade krigare från hela Horde."},{t="Smidet av den brutala rustningen",b="Unga krigare som besöker Thun'grim Firegaze vid hans utsiktsplats i The Barrens skickas söderut till Sen'jin Village. Veteranen litar på att Ula'elek smider Brutal Gauntlets åt stridsvana kämpar. För att tillverka dem ber Ula'elek om sällsynta material, särskilt svullna, osplittrade hovar från satyrerna som dränerar skogens magi i nordöstra Ashenvale."}},faq={{q="Vem är Ula'elek?",a="Ula'elek är en rustningssmed av trollfolket Darkspear i Sen'jin Village. Horde-veteraner litar på att han smider specialrustningar åt lovande frontkämpar.",al={"vem är ula'elek","ula'eleks historia","ula'eleks bakgrund"}},{q="Var finns Ula'elek?",a="Du hittar Ula'elek i Sen'jin Village, på Durotars sydöstra kust, söder om Razor Hill.",al={"ula'eleks plats","var finns ula'elek","hitta ula'elek"}},{q="Varför skickar Thun'grim Firegaze krigare till Ula'elek?",a="Thun'grim Firegaze skickar krigare till Ula'elek eftersom han litar på att trollsmiden tillverkar Brutal Gauntlets åt krigare som har vunnit veteranens respekt.",al={"thun'grim och ula'elek","varför gå till ula'elek"}},{q="Vilka material behöver Ula'elek för att tillverka handskarna?",a="Ula'elek kräver att krigare jagar satyrer i nordöstra Ashenvale och samlar in deras svullna, osplittrade hovar till Brutal Gauntlets.",al={"ula'eleks material","material till brutal gauntlets"}},{q="Vilken sorts utrustning tillverkar Ula'elek?",a="Ula'elek är specialiserad på tung stridsrustning. Han tillverkar Brutal Gauntlets, som ingår i rustningssetet Brutal Armor för lovande Horde-krigare.",al={"vad tillverkar ula'elek","ula'eleks belöningar"}},{q="Varför krävs satyrhovar till handskarna?",a="Satyrerna i nordöstra Ashenvale dränerar skogens magi, och de mäktigaste bland dem har svullna, osplittrade hovar. Ula'elek utvinner kraften ur hovarna och för över den till handskarna.",al={"varför satyrhovar","hovar till handskar"}}},fx={["3fd6027c"]={q="På vems sida står Ula'elek?",a="Ula'elek är en Darkspear-troll som är lojal mot Horde. Han utgår från Sen'jin Village vid Durotars kust och använder sitt hantverk för Hordes hjältar. Han samarbetar med orksmeder som Thun'grim Firegaze och smider slitstarka rustningar åt krigare som försvarar deras gemensamma marker.",al={"ula'eleks fraktion","tillhör ula'elek horde","ula'eleks lojalitet"}},c0ac20d7={q="Vad vill Ula'elek?",a="Ula'elek behöver dugliga material för att öva sitt hantverk och tillverka slitstarka rustningar. När Thun'grim kallar på honom låter han blivande krigare samla in sällsynta beståndsdelar, som satyrklövar, så att han kan smida brutala handskar värdiga beprövade kämpar.",al={"ula'eleks mål","vad behöver ula'elek","vad vill ula'elek"}},a7c1ab84={q="Varför är Ula'elek här i Sen'jin Village?",a="Ula'elek bor i Sen'jin Village och tjänar sin stam och Horde som rustningssmed. Han arbetar vid Durotars kust och håller sig nära sitt Darkspear-folk, samtidigt som han använder sin smedja för att träna och utrusta Hordes frontkrigare.",al={"varför är ula'elek i sen'jin","varför är ula'elek här"}},e890a681={q="Vilka band har Ula'elek?",a="Ula'elek är nära allierad med Thun'grim Firegaze, en skicklig orkrustningssmed stationerad i The Barrens. Thun'grim litar så mycket på Ula'eleks skicklighet att han skickar lovande krigare direkt till hans städ i Sen'jin Village för att få sina handskar smidda.",al={"ula'eleks kontakter","vem känner ula'elek","ula'eleks allierade"}}},fp="8,222,22.261.0,24.349.0,16.146.0,28.95.0,54.156.0,56.136.0,38.133.0,42.194.0"}
P.entries["npc:umpi"] = {n="Umpi",s="Umpi är en groda som bor i Tarren Mill och ovetande hjälper Apothecary Lydon i laboratoriet. Hon hålls i Royal Apothecary Societys verkstad och används återkommande som försöksdjur för experimentella gifter och pestbrygder.",h="Umpi är en groda som bor i Tarren Mill och ovetande hjälper Apothecary Lydon i laboratoriet.",kw={"apothecary lydon","elixir of agony","elixir of suffering","groda","hillsbrad foothills","tarren mill","umpi"},ang={["race:Undead"]="Umpi visar hur hänsynslöst och pragmatiskt Royal Apothecary Society bedriver sin forskning, där liv och död bara är variabler i arbetet med att fullända Forsakens vapenarsenal."},sec={{t="Ett liv av ständiga försök",b="I Tarren Mills mörka laboratorier arbetar Forsaken outtröttligt med att brygga död och plåga. För Apothecary Lydon kräver vetenskaplig noggrannhet att hans formler testas på levande kroppar, och Umpi får ta emot det mesta. Lydon prövar regelbundet dödliga brygder direkt på henne, som Elixir of Suffering och Elixir of Agony. När gifterna till slut tar ut sin rätt och dödar henne återupplivar alkemisten grodan, så att hon är redo att uthärda nästa dödliga dos i Royal Apothecary Societys tjänst."}},faq={{q="Vem är Umpi?",a="Umpi är en groda som Apothecary Lydon håller i Tarren Mill. Hon fungerar som assistent och främsta försöksdjur i Lydons giftiga alkemiska experiment.",al={"vem är umpi","vad är umpi","groda tarren mill"}},{q="Varför dödar Apothecary Lydon Umpi om och om igen?",a="Apothecary Lydon använder Umpi för att mäta styrkan hos sina nybryggda gifter. Efter att ha gett henne dödliga brygder som Elixir of Suffering återupplivar han henne, så att hon kan förgiftas igen i framtida försök.",al={"varför döda umpi","umpi förgiftad","lydons groda"}},{q="Är Umpi levande eller odöd?",a="Biologiskt befinner hon sig någonstans mittemellan. Även om hon tekniskt sett fungerar som ett djur erkänner Apothecary Lydon öppet att han återuppväcker henne efter varje dödlig förgiftningsprövning.",al={"är umpi odöd","umpi zombie","odöd groda"}},{q="Var finns Umpi?",a="Umpi finns i alkemistens verkstad i Tarren Mill, i Hillsbrad Foothills, alldeles intill Apothecary Lydons arbetsbänk.",al={"var finns umpi","umpis plats"}}},fx={["3625273f"]={q="På vems sida står Umpi?",a="Umpi är i praktiken Apothecary Lydons och Royal Apothecary Societys fångna assistent och försöksobjekt. Hon är inte politiskt lojal mot Forsaken eller Horde, utan uthärdar helt enkelt de brygder Lydon bestämmer sig för att hälla i henne.",al={"umpis fraktion","är umpi med i horde","vem tjänar umpi"}},d54b4816={q="Vem är Umpi knuten till?",a="Umpi är direkt knuten till Apothecary Lydon och tjänstgör som hans motvilliga laboratorieassistent i Tarren Mill. Hela hennes tillvaro kretsar kring att testa hans dödliga brygder, dö av deras giftiga verkningar och släpas tillbaka från döden för att genomgå processen igen.",al={"umpi apothecary lydon","vem äger umpi","umpis herre"}}},fp="4,167,27.337.0,12.142.0,44.176.0,24.131.0,24.126.0"}
P.entries["npc:undertaker-mordo"] = {n="Undertaker Mordo",s="Undertaker Mordo sköter kryptan i Deathknell och är det allra första ansikte som nyvakna Forsaken ser när de öppnar ögonen. Han berättar att de inte längre är Lich Kings slavar och skickar dem vidare till Forsaken-saken. Kropparna som aldrig vaknar går till elden.",h="Undertaker Mordo sköter kryptan i Deathknell och är det allra första ansikte som nyvakna Forsaken ser när de...",kw={"deathknell","bryskt uppvaknande","shadow grave","tirisfal glades","undertaker mordo"},ang={["race:Undead"]="Undertaker Mordo är den allra första person du talar med när du öppnar ögonen i döden, och han vägleder dina första trevande steg i drottning Sylvanas tjänst."},sec={{t="Uppvaknandet i Deathknell",b="Undertaker Mordo håller vakt över de döda i kryptan i Deathknell i Tirisfal Glades, medan lik bryter sig loss ur Scourges krossade grepp. För varje nybefriad Forsaken som vaknar i kryptans kyla visar Mordo vägen till ett första steg i ett andra liv de inte känner igen. Han bedömer om de är vid sina sinnens fulla bruk, berättar hur det ligger till och skickar dem genast i tjänst under drottning Sylvanas Windrunner."},{t="De som inte vaknar",b="Alla kroppar som förs till kryptan vaknar inte. Mordo väntar inte länge: liken som förblir orörliga kastas i elden, och de som rör på sig möts av torr otålighet och få ceremonier. Den som vaknar med förståndet i behåll skickas uppför trappan och längs vägen till Shadow Priest Sarvis i kapellet, som förklarar deras nya tillvaro. De tanklösa zombierna som härjar i byns norra del är Sarvis ansvar, inte Mordos; skuggprästen skickar de nyvakna för att förgöra dem."}},faq={{q="Vem är Undertaker Mordo?",a="Undertaker Mordo är Forsaken-folket kryptskötare i Deathknell i Tirisfal Glades. Han hälsar på nyuppvaknade odöda och leder dem in i tjänst.",al={"vem är mordo","undertaker mordo bakgrund","mordo deathknell"}},{q="Varför står han på en begravningsplats?",a="Mordo sköter kryptan i Deathknell, där nybefriade odöda vaknar efter att ha slitit sig loss från Lich Kings kontroll. Han vakar där för att hälsa dem så snart de rör på sig.",al={"varför är mordo vid gravarna","vad gör mordo","mordos arbete"}},{q="Vad händer med de odöda som förlorar förståndet när de vaknar?",a="Kroppar som aldrig vaknar kastas i elden. De tanklösa zombierna som stapplar runt i norra Deathknell är inte Mordos ansvar: Shadow Priest Sarvis skickar de nyvakna för att förgöra dem, vare sig de är deras tidigare bröder och systrar eller inte.",al={"de som inte kunde räddas","galna odöda deathknell","vilda odöda deathknell"}},{q="Vart skickar Mordo nyuppvaknade Forsaken?",a="När Mordo har försäkrat sig om att en nyvaken själ har förståndet i behåll skickar han ut dem ur kryptan och längs vägen till kapellet för att tala med Shadow Priest Sarvis, som förklarar vad det innebär att ansluta sig till Forsaken.",al={"vart går jag efter mordo","mordos uppdragsvägledning","nästa steg efter mordo"}}},fx={a2ca27d8={q="På vems sida står Undertaker Mordo?",a="Undertaker Mordo tjänar Forsaken och den mörka damen, Lady Sylvanas Windrunner. Han verkar vid frontlinjen bland nyväckta odöda i Deathknell och ser till att nyväckta kroppar som behållit förståndet tas upp i Forsakens led, i stället för att falla för Lich King eller en vettlös raseriattack.",al={"mordos fraktion","vem tjänar mordo","är mordo forsaken"}},b30fe27a={q="Vad vill Undertaker Mordo?",a="Mordos närmaste uppgift är att sköta gravplatserna i Deathknell. Han vill att nyuppståndna Forsaken ska återfå fattningen, rapportera till lokala ledare som Shadow Priest Sarvis och hjälpa till att göra sig av med vettlösa odöda som kravlat upp ur jorden utan att ha behållit sitt förstånd.",al={"vad försöker mordo göra","mordos mål","mordos syfte"}},["0fa90ad3"]={q="Vem är Undertaker Mordo knuten till?",a="Mordo sköter kryptan i Deathknell och samarbetar nära med Shadow Priest Sarvis i kapellet därunder. Till Sarvis skickar han alla nyväckta Forsaken, allt i Lady Sylvanas och Forsakens tjänst.",al={"mordos bundsförvanter","vem arbetar mordo med","mordos kontakter"}}},fp="16,211,27.281.0,21.420.0,24.128.0,34.140.0,60.220.0,43.181.0"}
P.entries["npc:ur-kyo"] = {n="Ur'kyo",s="I Valley of Spirits i Orgrimmar vägleder Ur'kyo präster i skuggans och ljusets vägar. Darkspear ser honom som sin andlige ledare och främste präst, och han undervisar om deras traditioner i Hordens huvudstad.",h="I Valley of Spirits i Orgrimmar vägleder Ur'kyo präster i skuggans och ljusets vägar.",kw={"darkspear","hex of weakness","orgrimmar","prästtränare","shadowguard","ur'kyo","urkyo","valley of spirits"},ang={["class:Priest"]="Som Horde-präst på resa genom Durotar kan du lära dig om tro, skuggriter och heliga skyddsmagier av Ur'kyo.",["faction:Horde"]="Som medlem av Horden hittar du Ur'kyo i Valley of Spirits i Orgrimmar, där han undervisar helare och skuggmagiker som förbereder sig på att försvara Horden.",["race:Troll"]="Som Darkspear-troll kan du se Ur'kyo som din främsta andliga vägledare i Orgrimmar. Han bevarar din stams voodoo och uråldriga magiska riter efter förlusten av Echo Isles."},sec={{t="Darkspears andlige mästare",b="Ur'kyo vägleder Darkspear-mystiker och tillresta utövare från Valley of Spirits i Orgrimmar. Efter att ha flytt från Echo Isles slog sig Darkspear ner i Durotar tillsammans med Thralls Horde. Deras heliga traditioner är fortfarande viktiga för stammen, och Ur'kyo håller de förfäders gamla sederna vid liv genom sin undervisning."},{t="Vägledning och forntida riter",b="Präster som kommer till Ur'kyo möter en tålmodig lärare i tro och gamla riter. Han lär ut Hex of Weakness och den defensiva skyddsmagin Shadowguard. Hordens präster vänder sig också till honom för att lära sig om koalitionens olika andliga vägar, från trollvoodoo och förfäders seder till främmande läror."}},faq={{q="Vem är Ur'kyo?",a="Ur'kyo tränar präster i Valley of Spirits i Orgrimmar. Darkspear ser honom som sin andlige ledare och främste präst.",al={"urkyo roll","ur'kyo identitet","vem är urkyo"}},{q="Var hittar jag Ur'kyo?",a="Ur'kyo finns i Valley of Spirits, trollernas stadsdel på Orgrimmars västra sida. Leta efter honom i träningshyddorna nära vattnet, tillsammans med andra andliga vägledare.",al={"ur'kyo plats","urkyo karta","hitta urkyo"}},{q="Vilka förmågor lär Ur'kyo ut?",a="Ur'kyo lär präster grundläggande besvärjelser inom skugga och ljus. Han vägleder också Darkspear-präster i Hex of Weakness och Shadowguard.",al={"urkyo besvärjelser","ur'kyo förmågor","trollprästers besvärjelser"}},{q="Varför verkar Ur'kyo i Orgrimmar i stället för på Echo Isles?",a="Efter Zalazanes förräderi och förlusten av Echo Isles slog sig Darkspear ner på nytt tillsammans med orcherna i Durotar. Ur'kyo lär ut stammens mystiska traditioner och tränar nya försvarare för Horden från Valley of Spirits.",al={"urkyo orgrimmars historia","varför är urkyo i orgrimmar"}},{q="Har Ur'kyo kontakt med präster som inte är troll?",a="Ja. Ur'kyo undervisar tillresta präster från Horden och delar Darkspears kunskap med andra medlemmar av Horden, däribland Forsaken.",al={"kan odöda tränas av urkyo","urkyo hordens tränare"}},{q="Vilken roll har Ur'kyo bland Darkspear-prästerna?",a="Darkspear erkänner Ur'kyo som sin främste präst och främsta andliga ledare. Han för vidare förfädernas seder, riter och voodoo till nästa generation.",al={"ur'kyos ställning","stammens främste präst"}}},fx={["77e8c5e8"]={q="På vems sida står Ur'kyo?",a="Ur'kyo står stadigt på Darkspear-stammens och Hordes sida. Han är stationerad i Valley of Spirits i Orgrimmar och tjänar som en viktig andlig vägledare för sitt folk under Chieftain Vol'jin och Warchief Thrall. Han är djupt rotad i djungeltrollens traditioner, men välkomnar Hordes präster som söker andlig vägledning och kunskap om gamla riter.",al={"ur'kyos fraktion","vem tjänar ur'kyo","är ur'kyo med i horde"}},a5f00a0b={q="Vad vill Ur'kyo?",a="Ur'kyo strävar efter att bevara Darkspear-stammens andliga traditioner och vägleda nya generationer av präster. Han arbetar för att hålla de gamla sederna vid liv, kanalisera andarnas uråldriga krafter och se till att de som följer prästernas väg har både beslutsamheten och kunskapen som krävs för att skydda sitt folk inom Horde.",al={"ur'kyos mål","vad försöker ur'kyo göra","ur'kyos syfte"}},fa6f514c={q="Varför är Ur'kyo känd bland Darkspear?",a="Ur'kyo vördas som Darkspear-stammens främsta präst. Han respekteras som en överordnad andlig ledare, och hans djupa kontakt med andarna och mästerskap i trollens heliga riter gör honom till den främsta auktoriteten inom andlig kraft och visdom bland Darkspear i Kalimdor.",al={"är ur'kyo berömd","varför respekteras ur'kyo","ur'kyos rykte"}}},fp="6,214,33.314.0,26.299.0,14.127.0,24.168.0,33.136.0,65.221.0,44.128.0,50.167.0"}
P.entries["npc:uzzek"] = {n="Uzzek",s="Uzzek vakar över östra The Barrens från en plats sydväst om Far Watch Post. Den stridsvana orchen har överlevt många skärmytslingar runt Kalimdor och prövar och tränar nu lovande krigare ur Horde som korsar slätterna.",h="Uzzek vakar över östra The Barrens från en plats sydväst om Far Watch Post.",kw={"the barrens","far watch post","path of defense","thun'grim firegaze","uzzek","krigartränare"},ang={["class:Warrior"]="Som krigare ställs du inför Uzzeks prövningar av uthållighet och försvarsskicklighet när du lämnar dina första träningsplatser för det vidsträckta The Barrens.",["faction:Horde"]="Som medlem i Horde hittar du Uzzek nära Far Watch Post, bland veteranerna som vakar över den sårbara gränsen mellan Durotar och den otämjda savannen."},sec={{t="Slätternas veteran",b="Uzzek tränar unga krigare sydväst om Far Watch Post, nära The Barrens östra kant. Han har uthärdat brutala strider i de senaste krigen och prövar nu dem som lär sig att försvara sig. För att bevisa sin skicklighet möter de det vilda djurlivet och de plundrare som hotar passagen."}},faq={{q="Vem är Uzzek?",a="Uzzek är en veteran bland orcherna, stationerad i östra The Barrens, strax sydväst om Far Watch Post. Han vägleder blivande krigare ur Horde som lär sig försvarsstrid.",al={"vem är uzzek","uzzek bakgrund","uzzek npc"}},{q="Var hittar jag Uzzek?",a="Du hittar Uzzek längs branterna sydväst om Far Watch Post, med utsikt över vägen från Durotar in i The Barrens.",al={"uzzek plats","var finns uzzek","hitta uzzek"}},{q="Vilken roll har Uzzek för Hordens krigare?",a="Uzzek prövar unga krigares uthållighet och beslutsamhet med utmaningar som Path of Defense. Sedan hänvisar han dem till erfarna mästare som Thun'grim Firegaze.",al={"krigaruppdrag uzzek","path of defense uzzek"}}},fx={a0e5656a={q="På vems sida står Uzzek?",a="Uzzek är lojal mot Horde. Som en orkveteran på vakt nära Far Watch Post, vid gränsen mellan The Barrens och Durotar, tjänar han den unga nation som grundades av Thrall. Han prövar och vägleder lovande krigare som vill försvara Hordes territorium.",al={"är uzzek med i horde","uzzeks fraktion","vem tjänar uzzek"}},["6cff12ed"]={q="Vad vill Uzzek?",a="Uzzek vill pröva blivande Horde-krigare i disciplinens och försvarets grunder. Efter att själv ha upplevt otaliga strider ser han till att unga kämpar förstår uthållighet, överlevnad och den taktiska skicklighet som krävs för att skydda Horde, innan han skickar dem vidare till fortsatt träning.",al={"vad behöver uzzek","uzzeks syfte","vad ber uzzek om"}},f99df2aa={q="Varför är Uzzek stationerad nära Far Watch Post?",a="Uzzek håller vakt i den karga terrängen strax sydväst om Far Watch Post, alldeles vid övergången mellan Durotar och The Barrens. Genom att hålla till nära gränsen kan han hejda och bedöma Horde-krigare som ger sig ut i den större världen och förbereda dem för de hårdare strider som väntar.",al={"varför är uzzek här","varför är uzzek i the barrens","varför är uzzek på den platsen"}}},fp="5,203,21.280.0,13.159.0,23.116.0,45.154.0"}
P.entries["npc:valstag-ironjaw"] = {n="Valstag Ironjaw",s="Valstag Ironjaw är en dvärgsoldat från Ironforge, stationerad i Menethil Keep vid Wetlands kustträsk. Han hjälper till att säkra handelsvägarna mellan Loch Modan och kusten och håller hamnens garnison underrättad om lokala hot.",h="Valstag Ironjaw är en dvärgsoldat från Ironforge, stationerad i Menethil Keep vid Wetlands kustträsk.",kw={"algaz gauntlet","captain stoutfist","loch modan","menethil harbor","menethil keep","valstag ironjaw","wetlands"},ang={["faction:Alliance"]="Valstag hjälper till att hålla den viktiga försörjningsleden öppen mellan Menethil Harbor och bergen i Khaz Modan, en förutsättning för alliansens handel och resor.",["race:Dwarf"]="För dvärgäventyrare på väg ner från Ironforge eller Loch Modan är Valstag en del av den främre garnison som håller den viktiga, regnpiskade västra kusten."},sec={{t="Tjänstgöring i borgen",b="Valstag Ironjaw finns i Menethil Keep i Menethil Harbor och tjänstgör i dvärggarnisonen som bevakar låglandet. Träskmarkerna runt omkring är fulla av faror, från fientliga Dragonmaw-orcher till glupska vilda djur, vilket gör det svårt att upprätthålla kommunikation och försörjningslinjer. Valstag hjälper till att samordna försvaret längs de viktigaste vägarna, särskilt den förrädiska passagen genom Dun Algaz mot Loch Modan."},{t="Säkra passet",b="Den förrädiska Algaz Gauntlet är full av fientliga styrkor, och resenärer och försörjningskaravaner mellan Menethil Harbor och Loch Modan hotas ständigt. Valstag skickar dugliga äventyrare för att ta itu med banditerna och orcherna som lurar i passen och förmedlar viktig militär underrättelse mellan spanare vid fronten och befälhavare som Captain Stoutfist."}},faq={{q="Var hittar jag Valstag Ironjaw?",a="Valstag Ironjaw finns inne i Menethil Keep, stenfästningen i Menethil Harbor i västra Wetlands.",al={"valstags plats","var finns valstag ironjaw","valstag ironjaw npc"}},{q="Vilken roll har Valstag i Wetlands?",a="Han är en dvärg från Ironforge, stationerad i borgen, som hjälper till med försvarsarbetet och hanterar hot längs bergsvägarna tillbaka till dvärgarnas hemländer.",al={"vad gör valstag","valstags roll"}},{q="Varför oroar passet till Loch Modan honom så mycket?",a="Algaz Gauntlet är den viktiga landförbindelsen mellan kusthamnen Menethil Harbor och Loch Modan och Ironforge. Fientliga styrkor som blockerar bergspasset hotar att stoppa mattransporter, truppförflyttningar och förnödenheter.",al={"varför algaz gauntlet","valstag loch modan"}},{q="Vem är Captain Stoutfist?",a="Captain Stoutfist är en högt uppsatt officer stationerad i Menethil Keep. Valstag samordnar med honom för att se till att militära rapporter och säkerhetsmeddelanden når garnisonens befäl.",al={"sambandet med captain stoutfist","vem är stoutfist"}}},fx={bcb025ae={q="Vem är Valstag Ironjaw?",a="Valstag Ironjaw är en kraftig dvärgisk försvarare stationerad i Menethil Keep i hamnstaden Menethil Harbor. Han tjänar Alliance och sina dvärgfränder och hjälper till att bevaka de farliga handelsvägarna och bergspassen mellan Wetlands kusthamn och högländerna i Loch Modan.",al={"vem är valstag","valstag ironjaws bakgrund","vem är valstag ironjaw"}},["3e0052ae"]={q="På vems sida står Valstag Ironjaw?",a="Valstag är lojal mot Ironforge och Grand Alliance. Bland försvararna i Menethil Harbor samarbetar han med dvärgiska militärbefäl, som Captain Stoutfist, för att skydda resenärer och hålla försörjningslinjerna öppna trots lokala hot.",al={"valstag ironjaws fraktion","vem tjänar valstag","är valstag med i alliance"}}},fp="15,148,16.286.0,17.302.0,33.113.0,44.125.0,53.150.0,25.156.0"}
P.entries["npc:vanndar-stormpike"] = {n="Vanndar Stormpike",s="Vanndar Stormpike är en stridslysten dvärgkung av bergen som leder Stormpike Expedition från den norra fästningen Dun Baldar. Han söker efter forntida reliker och naturtillgångar i Alterac Valleys frusna toppar och leder Alliansens obevekliga krig mot Frostwolf-orcherna.",h="Vanndar Stormpike är en stridslysten dvärgkung av bergen som leder Stormpike Expedition från den norra...",kw={"alterac","dun baldar","dvärg","frostwolf","bergskung","stormpike","vanndar"},ang={["faction:Alliance"]="Vanndar är den främste befälhavaren vid fronten i Alterac och håller de norra murarna medan han utvidgar alliansens territorium i de vilda bergen.",["race:Dwarf"]="För dvärgarna i Ironforge förkroppsligar Vanndar bergskungarnas okuvliga anda. Han kämpar för att göra anspråk på sitt forntida arv och hedra Explorer's Guild."},sec={{t="Herre över Dun Baldar",b="Vanndar Stormpike, en erfaren kung av bergen från Ironforge, går i spetsen för dvärgarnas utgrävningar i Alterac Valley. Efter det tredje kriget förde han Stormpike Guard till de norra bergen för att söka efter dolda mineralrikedomar och sedan länge förlorade titanartefakter. Vanndar slog sig ner i Dun Baldars befästa skans och ser dalen som en rätt han ärvt från sina förfäder och som rättmätigt alliansområde. Med obeveklig dvärgisk beslutsamhet styr han militärposteringar, försvarsbunkrar och offensiver vid fronten. Han tänker inte låta någon beordra reträtt under hans vakt."},{t="Kriget om det frusna passet",b="Vanddars obevekliga gruvdrift och prospektering trängde rakt in på Frostwolf-klanens hemmaplan och utlöste ett brutalt bergskrig. Trots orchernas krav på att dra sig tillbaka vägrar Vanndar att ge upp en tum mark och lovar att Alterac Valley ska tillhöra dvärgarna. Från sitt tronrum djupt inne i Dun Baldar, med sina marskalkar och livvakter vid sin sida, leder han personligen försvaret mot Frostwolfs intrång. Samtidigt skickar han ut alliansens hjältar för att bryta igenom fiendens linjer och ta dalen en gång för alla."}},faq={{q="Vem är Vanndar Stormpike?",a="Vanndar Stormpike är en dvärgkung av bergen och Stormpike Expeditions högste befälhavare. Från Dun Baldar leder han alliansens krigsinsats i Alterac Valley.",al={"vem är vanndar","vanndar stormpikes bakgrund","stormpikes ledare"}},{q="Varför strider Vanndar i Alterac Valley?",a="Vanndar ledde Stormpike Expedition till Alterac Valley för att hitta forntida reliker och utvinna naturtillgångar. Hans vägran att ge upp dessa anspråk ledde till en blodig konflikt mellan dvärgarna och de infödda Frostwolf-orcherna.",al={"varför är dvärgar i alterac","vanddars motiv","stormpikes syfte"}},{q="Var håller Vanndar till?",a="Han leder sina styrkor från Dun Baldar, en nordlig fästning i Alterac Valley som skyddas av dvärgbunkrar, marskalkar och elitvakter.",al={"var är vanndar","vanddars plats","dun baldars boss"}},{q="Vem är Vanddars främsta fiende?",a="Hans främsta motståndare är Drek'Thar, Frostwolf-klanens hövding och äldre schaman, som vill driva bort dvärgarnas inkräktare från klanens förfäders hemland.",al={"vanddars rival","vem strider vanndar mot","frostwolfs ledare"}}},fx={["3cffa9d0"]={q="På vems sida står Vanndar Stormpike?",a="Vanndar Stormpike är en stolt dvärgisk bergskung som strider hårt för Ironforge och Grand Alliance. Som högste befälhavare för Stormpike Guard och expeditionen till Alterac Valley leder han alla Alliances militära insatser och utgrävningar mot Frostwolf-orkerna och deras bundsförvanter i Horde.",al={"vanndar stormpikes fraktion","är vanndar med i alliance","för vem strider vanndar"}},["6ebb293f"]={q="Vad vill Vanndar Stormpike?",a="Vanndar vill att dvärgarna ska få fullständig kontroll över Alterac Valley. Hans expedition kom dit för att söka efter naturresurser, förfädernas historia och titanreliker begravda i bergen. Men Frostwolf-stammen gör anspråk på dalen, så hans mål är att driva bort orkerna helt och säkra hela dalen åt Alliance.",al={"vanndar stormpikes mål","vad vill vanndar","vanndar stormpikes syfte"}},["36b37a58"]={q="Vem är Vanndar Stormpike knuten till?",a="Vanndar leder Stormpike Expedition och befaller Stormpike Guard, en elitstyrka av dvärgar som är direkt knuten till King Magni Bronzebeard och kungariket Ironforge.",al={"vanndar stormpikes klan","vem är vanndar släkt med","vanndar stormpikes kontakter"}}},fp="17,213,18.519.0,23.446.0,25.146.0,42.218.0,24.143.0,28.175.0"}
P.entries["npc:varimathras"] = {n="Varimathras",s="Varimathras är en dreadlord av rasen nathrezim och tjänar Lady Sylvanas Windrunner som hennes främste löjtnant och militärrådgivare. Efter att ha besegrats i inbördeskriget om Lordaeron tvingades han svära trohet till Banshee Queen. Nu står han vid hennes sida i Royal Quarter i Undercity.",h="Varimathras är en dreadlord av rasen nathrezim och tjänar Lady Sylvanas Windrunner som hennes främste...",kw={"balnazzar","detheroc","dreadlord","nathrezim","royal quarter","sylvanas","undercity","varimathras"},ang={["class:Warlock"]="För dem som utövar demonmagi är det en imponerande, om än oroande, syn att se en högt uppsatt nathrezim tjäna en dödlig odöd drottning. Det vittnar om viljestyrka som tagits i bruk.",["faction:Horde"]="Dreadlordens närvaro i Undercity skapar starka spänningar med Orgrimmar. Horde ägnade årtionden åt att frigöra sig från just de demoniska herrar som Varimathras tjänade.",["race:Undead"]="Varimathras visar hur Forsaken pragmatiskt vänder sina förtryckares vapen mot dem. Han står kuvad vid sidan av Dark Lady, som befriade Lordaeron från hans grepp."},sec={{t="Lich Kings fångvaktare",b="Före det tredje kriget skickade Kil'jaeden Varimathras och hans dreadlordbröder till Azeroth som Lich Kings fångvaktare, för att se till att Ner'zhuls ande tjänade Legionens planer. Tillsammans med sina bröder Detheroc och Balnazzar övervakade han Scourge i Lordaeron medan Archimonde invaderade Kalimdor. När Legion föll vid Mount Hyjal höll triumviratet sig kvar bland ruinerna av Capital City. De visste inte att deras herre hade gått under förrän prins Arthas återvände och drev dem på flykt."},{t="En demon ger upp",b="När Lich Kings grepp om sina odöda styrkor bröts försökte Varimathras tvinga den nyligen befriade bansheen Sylvanas Windrunner att tjäna dreadlordernas nya styre. Sylvanas vägrade och samlade de befriade odöda för att krossa Varimathras utpost. Dreadlorden stod inför avrättning, föll på knä och bad för sitt liv. Han erbjöd taktiska hemligheter och kunskap om brödernas befästningar i utbyte mot att få leva. Sylvanas gick med på det och band honom till sin tjänst som ett levande vapen mot hans eget folk."},{t="Bror mot bror",b="För att vinna Sylvanas förtroende fick Varimathras order att döda sin dreadlordbror Balnazzar efter erövringen av Capital City. Han verkade lyda, men Balnazzar överlevde bedrägeriet. Därefter avrättade Varimathras den mänsklige krigsherren Grand Marshal Garithos på Sylvanas befallning. Nu står han vid Sylvanas tron och samordnar militära expeditioner genom Lordaeron. Många i Horde ser dock med stor oro på denna demoniska bundsförvant."}},faq={{q="Varför tjänar en demon Forsaken?",a="När Sylvanas Windrunner samlade sin armé av nyligen befriade odöda under inbördeskriget i Lordaeron besegrade hon Varimathras styrkor. Dreadlorden stod inför en nära förestående död och bad om nåd. Han erbjöd sin list, sin militära kunskap och sin tjänst i utbyte mot sitt liv. Sylvanas skonade honom för att använda honom som taktiker och maktutövare.",al={"varför är varimathras i undercity","varför är en dreadlord med sylvanas","varimathras lojalitet"}},{q="Vad är Varimathras för slags varelse?",a="Varimathras är en nathrezim, vanligen kallad dreadlord. Nathrezim är en intelligent och manipulativ demonras som tjänar Burning Legion. De är specialiserade på mental dominans, skuggmagi och att sprida pest och splittring.",al={"vilken ras är varimathras","är varimathras en vampyr","varimathras art"}},{q="Var står Varimathras i Undercity?",a="Du hittar honom stående på podiet i Royal Quarter i Undercity, alldeles intill Lady Sylvanas Windrunner och omgiven av Forsakens kungliga vakter.",al={"var finns varimathras","varimathras plats","hitta varimathras"}},{q="Vad hände mellan Varimathras och Balnazzar?",a="Efter erövringen av Capital City beordrade Sylvanas Varimathras att döda sin bror Balnazzar som ett lojalitetstest. Varimathras vände sig mot sin dreadlordbror på hennes befallning.",al={"dödade varimathras balnazzar","varimathras bror","dreadlord tabu"}},{q="Vilken roll hade Varimathras när Scourge skapades?",a="Efter att Kil'jaeden bundit orkschamanen Ner'zhuls ande i Frozen Throne och slungat den till Azeroth som Lich King skickade han Varimathras och hans dreadlordbröder för att agera fångvaktare och övervaka Scourges verk i Lordaeron.",al={"varimathras ner'zhul","varimathras och lich kings ursprung"}},{q="Litar de andra ledarna i Horde på Varimathras?",a="Inte alls. Orcs, trolls och tauren bär djupa ärr efter demonisk korrumpering och betraktar dreadlords som monstruösa manipulatörer. Även bland Forsaken ser många Varimathras som ett oroväckande vapen i mycket stram koppel, snarare än en sann stridsbroder.",al={"litar horde på varimathras","thrall varimathras","litar man på varimathras"}}},fx={b37d7c5f={q="På vems sida står Varimathras?",a="Utåt sett tjänar Varimathras Lady Sylvanas Windrunner och Forsaken. När Sylvanas besegrade hans styrkor efter Third War bad han för sitt liv och svor henne trohet. Han hjälpte henne till och med att störta sina bröder, skräckfurstarna. Men i grund och botten är han fortfarande en nathrezim från Burning Legion. Han tjänar som bansheedrottningens majordomus, men få i Horde tror att en demons lojalitet någonsin kan vara helt pålitlig.",al={"är varimathras lojal","varimathras trohet","vem tjänar varimathras"}},["3e1da8be"]={q="Vad vill Varimathras?",a="Framför allt vill Varimathras överleva och få inflytande. När Sylvanas hade honom i sitt våld förrådde han villigt sina skräckfurstebröder för att rädda sitt eget skinn. Genom att bli Sylvanas närmaste man i Undercity behåller han en enorm maktställning i Lordaeron och fortsätter att bidra till sina fienders undergång, främst Scourge och Scarlet Crusade.",al={"varimathras mål","vad vill varimathras","varimathras motiv"}},e0cdf0b9={q="Varför är Varimathras i Undercity?",a="Varimathras står vid Lady Sylvanas sida i Royal Quarter i Undercity, som hennes främste löjtnant och mästerstrateg. Efter att hon besegrat honom blev han bunden till hennes tjänst. Han hjälpte henne att erövra Lordaerons huvudstad och störta sina skräckfurstebröder Detheroc och Balnazzar. Nu samordnar han militära insatser, leder spioner och hjälper till att styra Forsakens rike under den mörka damens vakande öga.",al={"varför är varimathras här","varför är varimathras i undercity","vad gör varimathras här"}},["9df47492"]={q="Varför är Varimathras så fruktad?",a="Varimathras är en skräckfurste, en av de listiga nathrezim som Kil'jaeden skickade för att övervaka Lich King och Scourges förödelse av Azeroth. Han är känd för sin skickliga manipulation, sinneskontroll och hänsynslösa list. Tillsammans med sina bröder befäl han en gång över de odöda legionerna i Lordaeron. Att se en så mäktig demon bunden i tjänst är både ett skrämmande bevis på Sylvanas makt och ett oroande tecken för alla som går in i Undercity.",al={"varför är varimathras farlig","varimathras rykte","är varimathras fruktad"}}},fp="11,238,23.499.0,19.441.0,23.425.1,36.278.0,37.178.0,46.146.0,48.181.0,55.230.0,45.227.0"}
P.entries["npc:varok-saurfang"] = {n="Varok Saurfang",s="High Overlord Saurfang är en legendarisk orchkrigare och veteran från Old Hordes krig. Som Warchief Thralls betrodda militära befälhavare i Orgrimmar står han för den moderna Hordens stolta krigarkraft.",h="High Overlord Saurfang är en legendarisk orchkrigare och veteran från Old Hordes krig.",kw={"korkron","overlord","saurfang","thrall","varok","krigare"},ang={["class:Warrior"]="Krigare vördar Saurfang som en oöverträffad veteran. Hans yxteknik, taktiska briljans på slagfältet och orubbliga beslutsamhet visar vad en idealisk soldat är.",["race:Orc"]="För orcherna är High Overlord Saurfang både det främsta idealet för krigisk styrka och en allvarlig påminnelse om demonblodsförbannelsens andliga pris."},sec={{t="En levande krigslegend",b="Få levande krigare har en krigarbakgrund som kan mäta sig med Saurfangs. Han är veteran från Old Hordes krig och anses vara en ostoppbar kraft på slagfältet. I dag står han i Orgrimmar som High Overlord, ett värn för Thralls unga Horde."},{t="Blodets tyngd",b="Trots att han är Hordens främste förkämpe drivs Saurfang inte av vårdslös stridslust. Han försvarar Horde obevekligt och upprätthåller Thralls styre mot alla hot, men hyser ett djupt förakt för krigshets och strider enbart för heder och för att bevara."}},faq={{q="Vem är Varok Saurfang?",a="High Overlord Saurfang är en berömd orchkrigare och den främste militäre befälhavaren i Warchief Thralls Horde.",al={"varok saurfangs bakgrund","vem är saurfang","high overlord saurfang"}},{q="Vilka krig har Saurfang utkämpat?",a="Saurfang är veteran från Old Hordes krig mot Alliance. I dag strider han för Thralls Horde.",al={"saurfangs krigshistoria","stred saurfang i första kriget","saurfangs strider"}},{q="Hur ser Saurfang på Hordens förflutna?",a="Saurfang stred för Old Horde under demonblodsförbannelsens tid. I dag tjänar han Thralls Horde, som har vänt sig bort från den mörka vägen.",al={"saurfangs blodsförbannelse","varför ångrar saurfang det förflutna"}},{q="Vilken roll har Saurfang i dagens Horde?",a="Han tjänar som High Overlord över Thralls styrkor, övervakar den militära beredskapen, verkställer Warchiefens order och vägleder Hordens yngre krigare med sin erfarenhet.",al={"vad gör saurfang nu","saurfangs roll i orgrimmar"}}},fx={["30353091"]={q="På vems sida står Varok Saurfang?",a="Saurfang är djupt hängiven Thralls Horde. Han är veteran från Gamla Hordens krig och står i dag helhjärtat bakom den nya Horden. Han genomdriver krigshövdingens vilja och skyddar folket med fullständig hängivenhet.",al={"vilken fraktion tillhör saurfang","vem tjänar saurfang","saurfangs lojalitet"}},["275ad83b"]={q="Vad vill Varok Saurfang?",a="Saurfang önskar ära och stabilitet för sitt folk. Han försvarar Thralls Horde till sitt sista andetag och strävar efter att hindra orcherna från att falla tillbaka i Gamla Hordens mörka förflutna.",al={"vad vill saurfang","saurfangs mål","saurfangs motiv"}},d09cd640={q="Vilka band har Varok Saurfang?",a="Han är en av krigshövding Thralls mest betrodda befälhavare och tjänstgör som Hordens överste överherre i Orgrimmar.",al={"saurfangs familj","saurfangs bror","vem är saurfang släkt med"}},["593a9ba3"]={q="Varför är Varok Saurfang berömd?",a="Saurfang är legendarisk över hela Azeroth som en ostoppbar kraft på slagfältet. Han är veteran från Gamla Hordens krig, och hans oöverträffade stridskonst och skoningslösa taktik har gjort honom mäkta berömd och fruktad bland både fiender och allierade.",al={"varför är saurfang fruktad","är saurfang berömd","saurfangs rykte"}}},fp="14,170,27.224.0,23.194.0,22.113.0,32.101.0,40.140.0,45.156.0"}
P.entries["npc:velarok"] = {n="Velarok",s="Velarok Windblade är en ensam mänsklig svärdsman som slagit läger bland askan och slaggen i Searing Gorge, omgiven av lemlästade lik efter Dark Iron-dvärgar. Han söker hämnd på traktens Dark Irons för det brutala mordet på sin far och värvar resande för att smida ett hämndens vapen. Hans ensidiga hämndbegär driver allt han ber dem som hjälper honom att göra.",h="Velarok Windblade är en ensam mänsklig svärdsman som slagit läger bland askan och slaggen i Searing Gorge...",kw={"searing gorge","thorium point","torch of retribution","velarok","velarok windblade"},ang={["race:Dwarf"]="Dark Iron-dvärgar är fiender till Ironforge, och en främlings löfte om hämnd på dem kan lätt väcka sympati hos Bronzebeards. Men i Searing Gorge lurar ondskefullare och listigare hot än bara Dark Irons.",["race:Human"]="Velaroks berättelse om en mördad far och en sons hämnd spelar på idealen om plikt mot familjen och rättmätig vedergällning, som många människor håller kära."},sec={{t="En sons hämnd",b="Velarok Windblade finns sydost om Thorium Point och framställer sig som en sörjande mänsklig krigare strandsatt i Searing Gorges farliga ödemarker. Runt hans läger ligger blodiga, sargade lik efter Dark Iron-dvärgar som fallit för hans klinga. Enligt Velarok slaktade dessa klanmedlemmar hans far kallblodigt. Förtärd av hat värvar han resande för att samla material till Torch of Retribution, ett förtrollat vapen för hämnd på Dark Irons och Ragnaros undersåtar."},{t="Bedragaren avslöjas",b="Berättelsen om en mördad far är helt påhittad. När Torch of Retribution är färdigmonterad och laddad brister den mänskliga illusionen och avslöjar gestalten som Velarok the Deceiver, en listig drake ur den svarta drakflygeln. Efter att ha manipulerat dödliga till att underminera Dark Iron-dvärgarna för ynglets egna syften skonar Velarok sina användbara brickor för sitt nöjes skull. Han lämnar kvar några ynkliga prydnadssaker via sin tjänare och flyger sedan mot Blackrock Mountain."}},faq={{q="Vem är Velarok?",a="Velarok Windblade verkar först vara en hämndlysten mänsklig svärdsman som slagit läger sydost om Thorium Point i Searing Gorge och söker upprättelse från Dark Iron-klanen för sin fars död.",al={"vem är velarok windblade","velaroks identitet","velarok bakgrund"}},{q="Varför är Velarok omgiven av döda dvärgar?",a="De lemlästade kvarlevorna av Dark Iron-dvärgar som ligger utspridda runt hans läger är de dystra bevisen på blodshämnden han säger sig föra mot klanen för sin fars död.",al={"lemlästade dark iron-kvarlevor","döda dvärgar nära velarok","lik vid velaroks läger"}},{q="Vad är Torch of Retribution?",a="Det är en förtrollad fackla som satts samman av sällsynta material insamlade runtom i Searing Gorge i hämndens namn. Velarok låter sina medhjälpare samla delarna, sätter själv ihop och förtrollar dem och binder sedan den färdiga facklan till den som hjälpte honom.",al={"velaroks fackeluppdrag","vad är torch of retribution"}},{q="Varför förkläder Velarok sig till människa?",a="Genom att förklä sig till människa kan han värva äventyrare från både Alliansen och Horden utan att väcka misstankar. Svarta drakar antar ofta dödlig gestalt för att iscensätta attacker genom ombud mot sina fiender, som Ragnaros Dark Iron-tjänare.",al={"varför är velarok människa","varför bedra spelare","velarok the deceiver förklädnad"}},{q="Vart tar Velarok vägen när han avslöjar sig?",a="När han avslöjar sin sanna drakgestalt som Velarok the Deceiver lyfter han och styr mot Blackrock Mountain för att återförenas med sitt yngel. Han lämnar sin dödliga tjänare kvar för att belöna äventyrarna som hjälpte honom.",al={"vart flög velarok","velaroks slut","vad händer med velarok"}},{q="Går Velarok till attack när förklädnaden faller?",a="Nej. Velarok tycker att äventyrarnas ovetande tjänster är både roande och tillfredsställande. I stället för att döda dem skonar han deras liv och låter dem få mindre prydnadssaker av sin tjänare.",al={"slåss jag mot velarok","blir velarok fientlig"}}},fp="7,383,17.511.0,21.476.2,15.193.2,42.159.2,33.251.1,45.240.2,46.203.2,44.194.2"}
P.entries["npc:velora-nitely"] = {n="Velora Nitely",s="I Trade Quarter i Undercity arbetar Velora Nitely vid smedjan för Forsaken och Horde. Hon var en av Lordaerons främsta rustningssmeder, men drar nu torra skämt som sällan går hem.",h="I Trade Quarter i Undercity arbetar Velora Nitely vid smedjan för Forsaken och Horde.",kw={"pansarsmed","brutal legguards","dragonmaw-skenben","lordaeron","thun'grim firegaze","trade quarter","undercity","velora nitely"},ang={["class:Warrior"]="Som krigare i Horde på jakt efter den legendariska Brutal Armor skickas du norrut till Velora i Undercity. Hon smider tåliga benskenor av Dragonmaw-orchernas ben.",["profession:Blacksmithing"]="Som smed kan du se Lordaerons tradition av rustningssmide i Veloras precisa metallarbete, som består långt efter att hon blivit odöd."},sec={{t="En smed från Lordaeron",b="Velora Nitely arbetar nära städen i Trade Quarter i Undercity, där hon tillverkar rustningar åt Horde. Innan Tredje kriget ödelade norr hyllades hon i Lordaeron som en enastående rustningssmed. De odöda tog hennes liv och värme, men hennes tekniska skicklighet förblev orörd. Hon samarbetar med Hordes hantverkare över kontinenterna, däribland Thun'grim Firegaze i The Barrens. Hennes hantverk omfattar att förstärka tung stridsrustning och smida de imponerande Brutal Legguards av härdade material som Dragonmaw-skenben."},{t="Gravallvarlig humor",b="Velora Nitely försöker ständigt dra skämt vid smedjan, även om hennes humor sällan går hem. Många av hennes dystra Forsaken-fränder grubblar över sitt förbannade öde, men hon gör ändå plats för lite lättsamhet. Döden verkar ha förstört hennes komiska tajming: hennes repliker låter platta, morbida och fullständigt oskojiga för både levande och döda. Hon fortsätter obekymrat att dra dem."}},faq={{q="Vem är Velora Nitely?",a="Velora Nitely arbetar som rustningssmed bland Forsaken i Trade Quarter i Undercity. I livet var hon berömd i hela Lordaeron för sin enastående skicklighet i metallarbete.",al={"velora nitely historia","vem är velora","velora nitely npc"}},{q="Var hittar man Velora Nitely?",a="Velora Nitely arbetar nära smedjorna och rustningsställen i Trade Quarter i Undercity.",al={"velora nitely plats","var finns velora nitely","velora nitely karta"}},{q="Hur hänger hon ihop med Thun'grim Firegaze?",a="Velora Nitely är en smed i Horde som hjälper orchernas rustningssmed Thun'grim Firegaze i The Barrens. Hon tillverkar Brutal Legguards åt krigare som kommer med Dragonmaw-skenben.",al={"velora och thungrim","thungrim firegaze rustning","brutal armor uppdragskedja"}},{q="Varför är hennes skämt så dåliga?",a="Velora Nitely tycker om att försöka få folk att skratta, men döden har påverkat hennes framförande. Sedan hon steg upp som odöd har hennes skämt varit tafatta och gravallvarliga, och sällan roliga.",al={"veloras sinne för humor","veloras skämt","varför drar velora skämt"}}},fx={af55a704={q="På vems sida står Velora Nitely?",a="Velora är lojal mot Forsaken och Horden. Hon är stationerad i Undercity och använder sina enastående färdigheter inom metallarbete för att hjälpa Hordens krigare. Tillsammans med andra hantverkare i Horden på andra sidan haven smider hon mäktig utrustning åt dess mästare.",al={"velora nitelys fraktion","vem tjänar velora nitely","velora horde eller alliance"}},["71b2c071"]={q="Vad vill Velora Nitely?",a="Velora söker sällsynta material som motsvarar hennes hantverksskicklighet, särskilt dragonmaw-skenben från Wetlands, för att smida de väldiga Brutal Legguards. Hon tycker också om att försöka dra skämt för besökare, även om odöden har gjort hennes framförande ganska torrt och platt.",al={"vad vill velora","velora nitelys mål","vad behöver velora nitely"}},dd304cfc={q="Varför är Velora Nitely i Undercity?",a="Velora var tidigare medborgare i Lordaeron och väcktes till odöd efter sin död. Hon fann ett hem bland Sylvanas Windrunners Forsaken. Hon utövar sitt hantverk i Undercitys Trade Quarter, där hon kan smida rustningar och hjälpa resenärer som söker hennes legendariska smideskonst.",al={"varför är velora nitely här","varför är velora i undercity","velora nitely trade quarter"}},["97d7ef33"]={q="Varför är Velora Nitely berömd?",a="I livet var Velora känd som en av de främsta rustningssmederna i hela Lordaeron. Även som odöd har hon behållit sitt rykte om mästerligt tillverkade plåtrustningar, och smeder som Thun'grim Firegaze hänvisar lovande krigare till henne för att ta del av hennes legendariska hantverk.",al={"är velora berömd","velora nitelys rykte","varför är velora nitely välkänd"}}},fp="13,180,20.519.0,13.354.0,21.168.0,33.86.0,45.169.0,25.174.0"}
P.entries["npc:ventaari-brightwish"] = {n="Ventaari Brightwish",s="Ventaari Brightwish är en Skyborne-invånare i Thendal Village på Zephras Isle. Hon hälsar resenärer från hela Azeroth välkomna och erbjuder uppdraget The Gift of Skysight.",h="Ventaari Brightwish är en Skyborne-invånare i Thendal Village på Zephras Isle.",kw={"brightwish","skyborne","skysight","thendal village","ventaari","zephras isle"},ang={["race:Skyborne"]="Som medlem av Skyborne i Thendal Village hjälper Ventaari Brightwish besökare att lära känna kulturen och sederna på Zephras Isle."},sec={{t="En invånare i Thendal Village",b="Ventaari Brightwish bor i Thendal Village, på de höga klipporna på Zephras Isle, och tillhör den lokala gruppen Skyborne. Hon delar efternamn med Belathaan Brightwish, men hennes egna uppgifter handlar om att hjälpa nykomlingar som hittar till byn. Hon välkomnar både Alliansen och Horden och introducerar besökare till sitt folks traditioner genom uppgifter som The Gift of Skysight."}},faq={{q="Vem är Ventaari Brightwish?",a="Ventaari Brightwish är en Skyborne-NPC som finns i Thendal Village på Zephras Isle. Hon möter besökare och erbjuder uppdraget The Gift of Skysight.",al={"ventaari","vem är ventaari","ventaari brightwish"}},{q="Var hittar jag Ventaari Brightwish?",a="Hon finns i Thendal Village, på ön Zephras Isle.",al={"ventaari plats","var finns ventaari","ventaari thendal village"}},{q="Är Ventaari fientligt inställd till Horden eller Alliansen?",a="Nej. Ventaari Brightwish är neutral och pratar med äventyrare från både Alliansen och Horden.",al={"ventaari fraktion","är ventaari vänligt inställd","kan horden prata med ventaari"}}},fp="19,162,28.411.0,27.154.0,37.75.0,45.104.0"}
P.entries["npc:verdan-the-everliving"] = {n="Verdan the Everliving",s="Verdan the Everliving är ett kolossalt träskodjur som lurar djupt inne i Wailing Caverns grönskande gångar. Han lever mitt i mardrömmen som sprider sig från den sovande druiden Naralex, tillsammans med de korrumperade Druids of the Fang, och angriper våldsamt alla som vågar sig in i hans fuktiga hålor.",h="Verdan the Everliving är ett kolossalt träskodjur som lurar djupt inne i Wailing Caverns grönskande gångar.",kw={"träskodjur","druids of the fang","elementarvarelse","everliving","naralex","mardröm","verdan","wailing caverns"},ang={["class:Druid"]="Verdans lya är en dyster påminnelse om vad som växer i grottorna när The Emerald Dream förvandlas till en mardröm.",["class:Shaman"]="Verdan är en elementarande av jord och vatten som förvridits och blivit våldsam. Att fälla honom återställer balansen mellan Barrens splittrade element.",["faction:Horde"]="Wailing Caverns ligger i hjärtat av Barrens. Därför är det avgörande att besegra farliga odjur som Verdan för att skydda närliggande vägskäl och bosättningar."},sec={{t="Odjur från de frodiga djupen",b="Verdan är ett väldig träskodjur, en elementarvarelse av lövverk, slam och dy som lurar i Wailing Caverns igenvuxna djup. Ingen vet något om honom från tiden innan grottorna föll för korrumperingen. Han är helt enkelt den största och farligaste varelsen i deras frodiga, översvämmade hålor."},{t="Förvriden av mardrömmen",b="När Naralex försökte förvandla de torra Barrens till ett frodigt paradis brast hans ritual och blev en levande mardröm i The Emerald Dream. Korrumperingen sipprade sedan genom de underjordiska vattnen och besmittade allt levande i grottan. Mitt i denna förödelse strövar Verdan som en enorm, fientlig best i djupen där de vansinniga Druids of the Fang håller till."}},faq={{q="Vad är Verdan för slags varelse?",a="Verdan är ett enormt träskodjur, en elementarvarelse som formats av växtmaterial, torv och underjordisk dy.",al={"verdans monsterart","vad är verdan","verdans ras"}},{q="Varför är Verdan fientlig mot äventyrare?",a="Verdan lurar i de mardrömsbesmittade djupen av Wailing Caverns, där den sovande Naralex dröm har gjort allt fientligt. Han betraktar alla utomstående inkräktare som inkräktare som måste krossas.",al={"varför anfaller verdan","verdan fientlig","är verdan ond"}},{q="Vad har Verdan för koppling till Druids of the Fang?",a="Verdan delar de mardrömsbesmittade grottorna med de vansinniga Druids of the Fang och är lika fientlig mot inkräktare. Han vaktar grottornas djupare delar.",al={"verdan druids of the fang","verdans koppling till fang"}},{q="Var i Wailing Caverns finns Verdan?",a="Verdan bor i en rymlig, mossig kammare djupt inne bland de slingrande gångarna i Wailing Caverns, förbi flera av de korrumperade ledarna i Druids of the Fang.",al={"var finns verdan","verdans plats","hur hittar man verdan"}},{q="Kan Verdan botas eller renas?",a="Det finns inget känt sätt att rena Verdan. Äventyrarna har därför inget val än att döda det väldiga odjuret för att kunna ta sig säkert genom grottan.",al={"kan verdan räddas","rädda verdan","rena verdan"}},{q="Varför kallades Verdan ”the Everliving”?",a="Ursprunget till hans binamn är okänt. Verdan är ett träskodjur från Wailing Caverns frodiga, igenvuxna djup.",al={"varför everliving","betydelsen av everliving","verdans namns ursprung"}}},fx={["429fb6d1"]={q="Vem är Verdan the Everliving?",a="Verdan the Everliving är ett kolossalt träskmonster, en elementvarelse av växtmaterial och dy som lurar i de igenväxta djupen av Wailing Caverns. Han lever mitt i mardrömmen som sprider sig från den sovande druiden Naralex och angriper ursinnigt alla levande varelser som korsar hans väg.",al={"vem är verdan","verdan the everliving","vad är verdan"}},["58b439d8"]={q="På vems sida står Verdan the Everliving?",a="Verdan tjänar ingen fraktion. Han lurar i de mardrömsdrabbade djupen tillsammans med de korrumperade Druids of the Fang och är lika fientlig som de mot alla utomstående som vill störa grottorna eller väcka Naralex.",al={"verdans fraktion","står verdan med druiderna","verdans lojaliteter"}},["06330139"]={q="Vad vill Verdan the Everliving?",a="Verdan har inga storslagna planer utöver territoriellt försvar och förstörelse. Han vakar oupphörligt över de djupa grottorna och vill bara krossa alla inkräktare som vågar sig nära hans lya.",al={"verdans mål","vad vill verdan","verdans motiv"}},b1009155={q="Varför är Verdan the Everliving här?",a="Verdan lever i de frodiga, igenväxta djupen av Wailing Caverns, där mardrömmen från den sovande druiden Naralex har gjort grottorna fientliga. Ingenting är känt om honom från tiden före denna korrumpering.",al={"varför är verdan i wailing caverns","hur hamnade verdan här","verdans ursprung här"}},["357d8159"]={q="Varför är Verdan the Everliving fruktad?",a="Verdan är fruktad som det fysiskt brutalaste monstret i Wailing Caverns. Hans väldiga storlek och växtformade styrka gör att han kan utdela förödande slag som krossar en bepansrad krigare på bara några sekunder.",al={"varför är verdan fruktad","är verdan farlig","hur stark är verdan"}}},fp="21,286,24.282.0,24.367.1,32.108.0,37.203.0,54.159.0,47.137.0,32.146.0,39.107.0"}
P.entries["npc:verna-furlbrow"] = {n="Verna Furlbrow",s="Verna Furlbrow väntar vid sin trasiga vagn nära Westfalls norra gräns. Banditer drev bort henne från familjens pumpaodling, och vägen mot Elwynn Forest har lämnat henne strandsatt.",h="Verna Furlbrow väntar vid sin trasiga vagn nära Westfalls norra gräns.",kw={"trasig vagn","furlbrow","the jansen stead","old blanchy","flykting","theodore furlbrow","verna furlbrow","westfall stew"},ang={["faction:Alliance"]="De strandsatta Furlbrow visar vad Stormwinds försummade gränser kostar vanliga människor: de drivs från sina hem utan att kungliga soldater skickas för att försvara dem.",["profession:Cooking"]="Verna skapade Westfall Stew och lär ut hur gränsbygdens kockar kan göra en rejäl måltid av upphittat kött och vilda grödor."},sec={{t="En rad olyckor",b="Verna och hennes make odlade pumpor i norra Westfall tills laglösheten drev bort dem från deras mark. När fredlösa tog gården lastade de sin kärra med det de kunde och begav sig mot Elwynn Forest med hästen Old Blanchy. Vagnen gick sönder en bit från det övergivna The Jansen Stead. Verna kan varken laga axeln eller fortsätta färden och står nu inför väder och vind, banditräder och asätare. Hon är beroende av att resenärer håller hennes hushåll mätt och skyddat."},{t="Eldstadens hjärta",b="Verna välkomnar fortfarande dem som drivits ut till vägkanten. Hon är känd för att ha skapat Westfall Stew och delar måltider och värmande brasor med kringvandrande hemlösa och flyktingar som drabbats av liknande öden. För att fylla grytan behöver hon ingredienser från fälten, bland annat vildsvinstrynen, murlocögon, okra och segt gamkött. Av det den hårda gränsbygden ger lagar hon rejäla måltider åt de fattiga."}},faq={{q="Varför har Verna Furlbrow slagit läger längs vägen?",a="Verna och hennes make flydde från sin pumpagård efter att fredlösa tagit över norra Westfall. Vagnen gick sönder nära The Jansen Stead på väg mot Elwynn Forest, och de blev strandsatta vid vägen.",al={"varför är verna furlbrow här","verna furlbrows plats","vad hände med verna"}},{q="Vem är Farmer Furlbrow för henne?",a="Farmer Theodore Furlbrow är Vernas make. De skötte tillsammans sitt hemman i Westfall tills banditer drev bort dem från deras mark.",al={"verna furlbrows make","är farmer furlbrow hennes make"}},{q="Vad är Westfall Stew?",a="Westfall Stew är en rätt från gränsbygden som Verna skapade. Hon lagar den med tryne från vildsvin, segt gamkött, murlocögon och okra från övergivna gårdar i närheten för att mätta strandsatta flyktingar.",al={"uppdraget westfall stew","verna furlbrow gryta","vad lagar verna"}},{q="Vad hände med familjen Furlbrows gård?",a="Familjen Furlbrows pumpagård i norra Westfall togs över av organiserade banditer under kungarikets senaste sammanbrott i säkerheten. De tvingades lämna sitt hem och sina fält.",al={"furlbrows pumpagård","vad hände med furlbrows gård"}}},fx={c5a3789f={q="Vem är Verna Furlbrow?",a="Verna Furlbrow är en anspråkslös jordbrukare i Westfall och Farmer Theodore Furlbrows hustru. Hon är känd över hela landsbygden för sin mustiga Westfall Stew och generösa läggning. Hon och hennes man brukade ett pumpaland i norra Westfall tills våldsamma oroligheter slog sönder deras försörjning. Nu är hon på flykt och har blivit strandsatt vid vägkanten, men försöker hålla humöret uppe trots den ständiga oturen.",al={"vem är verna furlbrow","verna furlbrows identitet","verna furlbrows bakgrund"}},b45ce146={q="På vems sida står Verna Furlbrow?",a="Verna är en lojal undersåte till kungariket Stormwind och står stadigt på Alliansens sida. Liksom många vanliga människor i Westfall hyser hon inget gott öga till laglösa som sliter sönder provinsen. Hon önskar bara fred, trygghet och en chans att fly laglösheten som plågar landsbygden.",al={"verna furlbrows fraktion","tillhör verna furlbrow alliansen","verna furlbrows sida"}},["0d4268c1"]={q="Vad vill Verna Furlbrow?",a="Verna vill inget hellre än att mätta sin familj och ta sig ut ur Westfall oskadd. Efter att ha förlorat sin gård tänkte hon och hennes man söka skydd i Elwynn Forest, men deras trasiga vagn och hungriga, utmattade häst har stoppat dem. Just nu försöker hon få tag på förnödenheter, som ingredienser till sin gryta och havre åt Old Blanchy, så att de kan överleva vid vägkanten.",al={"vad vill verna furlbrow","verna furlbrows mål","varför hjälpa verna furlbrow"}}},fp="14,182,23.462.0,19.399.0,44.209.0,30.132.0,22.196.0,37.172.0"}
P.entries["npc:verner-osgood"] = {n="Verner Osgood",s="Verner Osgood är Lakeshires smed och håller till strax utanför stadens smedja. Han balanserar lokal handel med Stormwinds militära krav och arbetar outtröttligt för att sko hästar och beväpna försvararna medan gnollernas räder aldrig tycks ta slut.",h="Verner Osgood är Lakeshires smed och håller till strax utanför stadens smedja.",kw={"smed","gnoller","hästar","lakeshire","magistrate solomon","redridge","verner osgood","yowler"},ang={["faction:Alliance"]="Städer som Lakeshire är beroende av lokala hantverkare som Verner för sin överlevnad, medan Stormwinds militära stöd är oroväckande begränsat.",["profession:Blacksmithing"]="Verner gestaltar den kärva verkligheten i smedlivet på landsbygden, där skoning av hästar för stadens invånare måste balanseras mot garnisonens hårda försvarskrav.",["race:Human"]="Osgood står för vanligt folk i Kingdom of Stormwinds uthållighet och håller stånd mot både gnoller och brist på förnödenheter."},sec={{t="Lakeshires städ",b="Vid smedjan mitt i Lakeshire står Verner Osgood som symbol för Redridge Mountains ansträngda industriella ryggrad. Han har fått i uppgift att tillverka grundläggande förnödenheter som hästskor åt traktens hästar, men hans lager tas ständigt i anspråk för att smida vapen och rustningar åt Stormwind Guard. Medan kungariket tänjer sina gränser till bristningsgränsen och de lokala garnisonerna saknar förnödenheter måste självständiga smeder som Verner bära den logistiska bördan för rikets försvar."},{t="En plåga av gnoller",b="Verners problem sträcker sig långt bortom järnbrist. Gnollerna som härjar i Redridge Hills överfaller regelbundet boskap och för bort arbetshästar när de kommer utanför stadens gränser. Verner är förtvivlad över hur hans levebröd förstörs och rekryterar aktivt äventyrare på genomresa för att decimera de kringströvande flockarna och jaga deras våldsamma flockledare, Yowler."}},faq={{q="Vem är Verner Osgood?",a="Verner Osgood är den lokala smeden som sköter smedjan i Lakeshire. Han utför metallarbete och skoning av hästar åt staden, samtidigt som han försöker möta garnisonens stora behov av utrustning.",al={"verner osgood","smeden i lakeshire","vem är verner"}},{q="Varför har Verner ont om hästskor och järn?",a="Stadens järnleveranser tas ständigt i anspråk för att smida vapen och rustningar åt Stormwind Guard, som är stationerade i Redridge. Därför har Verner knappt tillräckligt med metall för att ta hand om traktens hästar.",al={"verner utan järn","pris på skor uppdragslore","varför inga hästskor"}},{q="Vilket problem har Verner med gnollerna?",a="Gnollernas räder går tätt inpå Lakeshire, och de rövar bort Verners hästar när de vandrar bort från staden. Han söker hämnd och trygghet genom att anlita äventyrare för att utrota bestarna.",al={"verners gnollproblem","varför hatar verner gnoller"}},{q="Vem är Yowler och varför vill Verner ha honom död?",a="Yowler är den hotfulla ledaren för traktens gnollflockar i kullarna. Verner vill att han dödas för att bryta samordningen mellan rövarna som terroriserar staden och slaktar hans hästar.",al={"vem är yowler","verner yowler uppdrag"}},{q="Vilken koppling har Verner till Magistrate Solomon?",a="Verner verkar under Magistrate Solomons civila myndighet i Lakeshire och balanserar sitt hantverk för stadsborna mot de civila och militära behov som den hårt pressade förvaltningen kräver.",al={"verner magistrate solomon","verner och stadens ledning"}},{q="Har Verner familj i Stormwind?",a="Han delar efternamn med flera andra hantverkare i Kingdom of Stormwind, som Donal och Basil Osgood. Det tyder på en etablerad släktlinje av arbetarklassens hantverkare bland människor i hela regionen.",al={"verners släktingar","osgoodfamiljen"}}},fx={["55e99553"]={q="På vems sida står Verner Osgood?",a="Verner är helhjärtat lojal mot Alliansen och samhället i Lakeshire. Som bosättningens smed lägger han mycket av sitt järn och arbete på att utrusta den lokala garnisonen och hålla Stormwind Army försedd, även när hans egen verkstad får brist på råmaterial.",al={"verners allians","vem tjänar verner osgood","verner osg oods fraktion"}},["238f7baf"]={q="Vad vill Verner Osgood?",a="Verner vill skydda Lakeshire och hålla sin smedja igång. Hans främsta uppgift just nu är att skaffa tillräckligt med järn för att sko sina hästar, fylla på verkstadens sinande förråd och se till att gnollflockarna i trakten utplånas, så att de inte längre kan slakta boskap och hota staden.",al={"verner osg oods mål","vad behöver verner","verner osg oods motiv"}},["2b67bbb2"]={q="Varför är Verner Osgood i Lakeshire?",a="Verner bor och arbetar i Lakeshire som stadens smed. Han sköter smedjan vid sjön, smider utrustning åt de lokala försvararna, rustar dragdjur och försöker hålla handeln igång som vanligt trots de ständiga hoten som närmar sig Redridge.",al={"varför är verner här","var finns verner osgood","varför är verner i redridge"}}},fp="13,190,22.328.0,18.245.0,21.147.0,41.170.0,46.173.0,48.172.0,50.180.0,37.160.0"}
P.entries["npc:veron-amberstill"] = {n="Veron Amberstill",s="Veron Amberstill är en dvärgisk baggeuppfödare som bor på Amberstill Ranch i östra Dun Morogh. Han sköter de tåliga bergsbaggarna som är Ironforges traditionella riddjur och erbjuder dem till skickliga ryttare som har vunnit hans förtroende.",h="Veron Amberstill är en dvärgisk baggeuppfödare som bor på Amberstill Ranch i östra Dun Morogh.",kw={"amberstill ranch","dun morogh","ironforge","försäljare av riddjur","bergsbagge","baggeförsäljare","veron amberstill"},ang={["faction:Alliance"]="Allierade till Ironforge som vill bemästra ridning på en bergsbagge måste först bevisa sin hängivenhet till dvärgarnas kungarike för att vinna Verons respekt.",["race:Dwarf"]="Veron står för ditt folks långa tradition med bergens bestar och erbjuder vanliga och snabba baggar som varje dvärgisk äventyrare förlitar sig på för att ta sig fram i Khaz Modan."},sec={{t="Riddjurens mästare",b="I de snötäckta kullarna i östra Dun Morogh ansvarar Veron Amberstill för den berömda boskapen på Amberstill Ranch. Bergsbaggar passar perfekt för Khaz Modans förrädiska sluttningar, med säkra hovar och tjock päls som skyddar mot fjällstormarnas bett. Veron föder upp och tränar dessa bestar för att bära dvärgiska spejare, bergsklättrare och resande äventyrare. Han förser gärna andra dvärgar med vanliga och snabba riddjur, men främlingar måste bevisa sin orubbliga lojalitet mot Ironforges tron innan han lämnar ifrån sig några av sina prisade djur."}},faq={{q="Vem är Veron Amberstill?",a="Veron Amberstill är en dvärgisk uppfödare och försäljare av riddjur på Amberstill Ranch i Dun Morogh. Han föder upp kraftiga bergsbaggar åt kungariket Ironforge och säljer dem till kvalificerade ryttare.",al={"veron amberstill","vem är veron","försäljare av amberstill-baggar"}},{q="Kan andra än dvärgar köpa baggar av Veron?",a="Ja, men bara om de har nått en upphöjd anseendenivå hos Ironforge. Dvärgar kan köpa hans baggar utan vidare, men främlingar måste bevisa att de är trogna förkämpar för bergariket innan Veron anförtror dem sina djur.",al={"kan människor köpa baggar","baggriddjur för icke-dvärgar","ironforge-anseende för baggriddjur"}},{q="Var finns Veron Amberstill?",a="Du hittar honom utanför Amberstill Ranch, som ligger bland kullarna i östra Dun Morogh, strax norr om Gol'Bolar Quarry.",al={"verons plats","var finns veron","var hittar man veron amberstill"}},{q="Varför rider dvärgar på baggar i stället för hästar?",a="Bergsbaggar har tjock päls, kraftiga kroppar och enastående balans, vilket gör dem mycket bättre lämpade än vanliga hästar för de isande vindarna och branta klippavsatserna i Dun Morogh och de omgivande bergen.",al={"varför rider dvärgar på baggar","dvärgiska riddjurens historia","bergabaggriddjurens historia"}}},fx={["601a0646"]={q="På vems sida står Veron Amberstill?",a="Veron Amberstill är helhjärtat lojal mot dvärgarnas kungarike Ironforge och den stora alliansen. Han tar hand om bergsvädurar som är dvärgfolkets uppskattade riddjur och förser sina släktingar och betrodda allierade i Alliansen med pålitliga riddjur när de har uppnått hög status i Ironforge.",al={"veron amberstills fraktion","tillhör veron amberstill alliansen","veron amberstills lojalitet"}},b4666b3f={q="Varför är Veron Amberstill här?",a="Veron Amberstill sköter Amberstill Ranch, som ligger bland de vindpinade kullarna i Dun Morogh. Den kalla, steniga terrängen passar perfekt för uppfödning av starka och tåliga bergsbaggar, så ranchen har blivit centrum för avel och träning av dessa ikoniska dvärgiska riddjur.",al={"varför är veron amberstill i dun morogh","varför finns veron amberstill här","amberstill ranch syfte"}},["8bafbe3f"]={q="Vad vill Veron Amberstill?",a="Veron Amberstill vill skydda sin försörjning och bevara ranchens värdefulla bestånd av bergsbaggar. Han fokuserar på att avla, föda upp och skydda hjordarna från farorna som stryker omkring på Dun Moroghs snöiga bergsryggar, och förser värdiga ryttare med tåliga riddjur.",al={"veron amberstills mål","vad vill veron","veron amberstills syfte"}},["921d6dac"]={q="Vilka band har Veron Amberstill?",a="Veron har band till Amberstill-klanen och ranchen som bär familjens namn. Tillsammans med sina släktingar på ranchen ser han till att ta hand om och föda upp bergsbaggarna, som har tjänat dvärgarna i Dun Morogh i generationer.",al={"veron amberstills familj","vilka släktband har veron","amberstill-familjen"}}},fp="16,99,20.426.0,24.146.0,41.148.0,34.113.0,43.164.0"}
P.entries["npc:veronica-nials"] = {n="Veronica Nials",s="Captain Veronica Nials är en officer i Stromgardes militär, stationerad vid Refuge Pointe i Arathi Highlands. Mitt i rikets sammanbrott samordnar hon försvaret mot Syndicate och ogres som översvämmar den fallna huvudstaden.",h="Captain Veronica Nials är en officer i Stromgardes militär, stationerad vid Refuge Pointe i Arathi Highlands.",kw={"arathi highlands","falconcrest","marez cowl","refuge pointe","stromgarde","syndicate","thandol span","veronica nials"},ang={["faction:Alliance"]="Captain Nials gestaltar den tragiska verkligheten för den norra Alliance: splittrade och isolerade riken kämpar för sin blotta överlevnad och kan inte ge sina grannar någon meningsfull hjälp.",["race:Human"]="För människor är Nials en symbol för Stromgardes okuvliga stolthet över sin krigarkultur. Hon vägrar överge Arathors förfädersrike trots överväldigande odds."},sec={{t="Försvarare av ett brustet rike",b="Efter det tredje kriget splittrades människoriket Stromgarde, och dess kvarlevor kämpar för att överleva mot invaderande Boulderfist ogres och Syndicates förräderi. Captain Veronica Nials är en av de främsta befälhavarna för de överlevande försvararna från Stromgarde vid Refuge Pointe. Hon har fått i uppdrag att hålla stånd och leder Alliance-hjältar mot Syndicates ledare, som Lord Falconcrest och häxmästaren Marez Cowl, samtidigt som hon försöker återfå fallna soldaters brickor så att deras sörjande familjer kan få ett avslut."},{t="En vädjan avslås",b="Captain Nials lojalitet är helt knuten till hennes sargade hemland. När Rhag Garmason och dvärgförespråkarna i Dun Modr vädjade om Stromgardes hjälp efter att Dark Iron-sabotörer ödelagt Thandol Span, tvingades Nials avvisa dem. Bundna av heder och plikt kan hennes trupper inte avvara en enda soldat utanför Arathi Highlands medan deras eget förfädersrike fortfarande är ockuperat."}},faq={{q="Vem är Veronica Nials?",a="Veronica Nials är en mänsklig kapten i Stromgardes armé. Hon är stationerad vid Refuge Pointe och leder det militära motståndet mot Syndicates infiltratörer och ogres som ockuperar Arathi Highlands.",al={"vem är veronica nials","captain nials","kapten vid refuge pointe"}},{q="Varför hjälper Captain Nials inte Dun Modr och Thandol Span?",a="Dvärgarna som håller Thandol Span behöver desperat förstärkningar mot Dark Iron Clan, men Nials kan inte avvara några soldater. Stromgarde står på randen till total förstörelse, och plikten kräver att hennes styrkor helt fokuserar på att återta sitt eget fallna rike.",al={"vädjan om thandol span","varför ingen hjälp till dvärgarna","vädjan till alliansen-uppdraget"}},{q="Vad gör Nials med Stromgarde-brickor?",a="Syndicate erbjuder belöningar för Stromgarde-brickor som tagits från slaktade soldater. Nials ber Alliance-äventyrare att återta de stulna brickorna från Syndicates mördare, så att hon kan bekräfta dödsfallen och underrätta de fallna försvararnas familjer.",al={"stromgarde-brickor","varför samla brickor","bricksuppdrag"}}},fx={c41e517e={q="Vem står Veronica Nials på sida med?",a="Captain Nials står fast vid kungariket Stromgarde och Alliansen. Som officer i Stromgarde-militären är hennes främsta lojalitet till sitt folk och deras förfäders hemland. Hon håller Refuge Pointe mot de många fiender som tränger in i Arathi Highlands.",al={"veronica nials fraktion","vem tjänar veronica nials","nials lojalitet"}},["558769df"]={q="Vad vill Captain Nials?",a="Captain Nials strävar efter att återta det fallna kungariket Stromgarde från de fientliga styrkor som ockuperar det. Hon leder militära insatser mot Boulderfist-ogrerna och Syndicate-rövarna som har tagit huvudstaden, samtidigt som hon samlar in märken från stupade Stromgarde-milismän för att underrätta deras sörjande familjer.",al={"veronica nials mål","vad vill captain nials","nials mål"}}},fp="14,171,26.423.0,13.327.0,22.174.0,59.170.0,42.212.0"}
P.entries["npc:vesprystus"] = {n="Vesprystus",s="Vesprystus är Night Elf-flygmästaren som är stationerad vid bryggorna i Rut'theran Village, vid foten av Teldrassil. Han sköter den tränade hippogryffflocken som för resenärer mellan det stora världsträdet och Kalimdors fastland.",h="Vesprystus är Night Elf-flygmästaren som är stationerad vid bryggorna i Rut'theran Village, vid foten av...",kw={"auberdine","darkshore","flygmästare","hippogryffmästare","rut'theran village","teldrassil","vesprystus"},ang={["faction:Alliance"]="Vesprystus är en viktig transportlänk för Alliance-resenärer som anländer till Teldrassils bryggor och snabbt behöver ta sig till Darkshores kust.",["race:NightElf"]="För unga Night Elf-äventyrare som lämnar Teldrassil för första gången är Vesprystus ofta den som skickar dem svävande mot deras allra första glimt av Kalimdors fastland."},sec={{t="Väktare av Rut'theran Village-hägnet",b="Vid Teldrassils södra fot i Rut'theran Village sköter Vesprystus hippogryfferna som förbinder de avskilda alvgrenarna med resten av världen. En magisk portal leder direkt från Rut'theran till Darnassus, staden uppe i trädkronorna, men hippogryffflygningar erbjuder en snabb överfart mot Darkshore och fastlandet. Vesprystus samarbetar med flygmästaren i Auberdine på andra sidan sundet och ser till att väktare, sändebud och äventyrare färdas tryggt genom Kalimdor."}},faq={{q="Vart flyger Vesprystus med resenärer?",a="Vesprystus förbinder Rut'theran Village direkt över vattnet med hamnen i Auberdine vid Darkshores kust. Från Auberdine kan resenärer ta anslutande hippogryffrutter söderut mot Ashenvale och andra Night Elf-enklaver i Kalimdor.",al={"vart kan han ta mig","vesprystus flygrutter","rut'theran flygrutt"}},{q="Vilka varelser sköter Vesprystus?",a="Han sköter en flock lojala Night Elf-hippogryffer, uråldriga bevingade bestar som hör hemma i norra Kalimdor. Night Elves har fött upp hippogryffer och knutit band till dem i generationer för att ta sig fram genom skogarnas trädkronor och längs karga kuster.",al={"vilka riddjur har han","vesprystus djur","vad flyger han"}},{q="Hur tar du dig till Darnassus från där Vesprystus står?",a="Du behöver inte flyga för att ta dig till Darnassus från Rut'theran Village. En skimrande, rosatonad portal står strax uppför stigen från Vesprystus hägn och för resenärer direkt upp till staden bland trädkronorna.",al={"hur tar man sig till darnassus från vesprystus","vesprystus till darnassus","vägen till darnassus"}}},fx={e8883b50={q="Vem är Vesprystus?",a="Vesprystus är en hippogryffmästare från Night Elf-folket, stationerad i Rut'theran Village vid foten av Teldrassil. Han sköter rastplatserna och ordnar tillförlitliga flygresor för resenärer mellan Darnassus mäktiga grenar ovanför och kustbosättningarna i norra Kalimdor.",al={"vem är vesprystus","vesprystus night elf","vesprystus bakgrund"}},f70b999e={q="Vem står Vesprystus på sida med?",a="Han är lojal mot Darnassus och Alliansen. Hans rastplatser betjänar Night Elf-väktare, druider och besökande allierade som behöver en säker och snabb väg till och från Teldrassil.",al={"vesprystus alliansen","vesprystus fraktion","vem tjänar vesprystus"}},["433ae265"]={q="Varför är Vesprystus här?",a="Rut'theran Village är en viktig hamn och ankomstplats för Teldrassil. Eftersom Världsträdet reser sig brant ur havet är det omöjligt att ta sig fram landvägen. Vesprystus stannar här för att förse rastplatserna med förnödenheter och se till att hippogryffer alltid är redo att föra budbärare, varor och resenärer över vattnet till fastlandet.",al={"varför är vesprystus i rut'theran","vesprystus syfte här","varför finns vesprystus i rut'theran"}},["5aeefd6f"]={q="Vad vill Vesprystus?",a="Han vill se till att hippogryfferna får god omsorg och att flygrutterna mellan Teldrassil och närliggande utposter förblir öppna och säkra. Han hjälper resenärer och kurirer som för med sig viktiga leveranser över havet.",al={"vad behöver vesprystus","vesprystus mål","vesprystus drivkraft"}}},fp="10,153,30.379.0,36.223.0,36.217.0,56.176.0"}
P.entries["npc:vidra-hearthstove"] = {n="Vidra Hearthstove",s="Vidra Hearthstove är en dvärgkock som bor på Stoutlager Inn i Thelsamar. Hon är känd för att laga lokala specialiteter och ber ofta resande äventyrare samla regionala ingredienser till sina berömda blodkorvar.",h="Vidra Hearthstove är en dvärgkock som bor på Stoutlager Inn i Thelsamar.",kw={"blodkorvar","dvärgkock","hearthstove","loch modan","stoutlager inn","thelsamar","vidra hearthstove"},ang={["profession:Cooking"]="Vidra förkroppsligar Khaz Modans mättande, rustika mattraditioner och förvandlar kärva lokala ingredienser till närande måltider för hungriga äventyrare och bergspatruller.",["race:Dwarf"]="För dvärgar som passerar genom Thelsamar erbjuder Vidras kök en tröstande smak av hemmet och fyller sin viktiga roll i att hålla stadens moral uppe."},sec={{t="Stoutlagers kök",b="I den livliga, varma Stoutlager Inn sköter Vidra Hearthstove köket och hjälper till att mätta lokalbefolkningen och resenärer på genomresa i Loch Modan. Hon delar efternamn med värdshusvärden och ser till att Thelsamar har goda förråd. Hennes signaturrätt, Thelsamars blodkorvar, är en mättande dvärgrätt som kräver färskt viltkött från den omgivande vildmarken, bland annat vildsvinstarmar, spindelichor och björnkött."}},faq={{q="Vem är Vidra Hearthstove?",a="Vidra Hearthstove är en dvärg som bor på Stoutlager Inn i Thelsamar. Hon är känd för sin matlagning, särskilt de mättande Thelsamars blodkorvarna som hon serverar gäster och bergsvakter som försvarar Loch Modan.",al={"vidra hearthstove berättelse","vem är vidra","stoutlagers kock"}},{q="Var hittar man Vidra Hearthstove?",a="Hon finns inne på Stoutlager Inn, som ligger mitt i Thelsamar i Loch Modan.",al={"vidras plats","var finns vidra hearthstove","vidra på stoutlager inn"}},{q="Vilka ingredienser använder hon till Thelsamars Blood Sausage?",a="Hennes berömda recept kräver ett rejält urval av lokala djurdelar, närmare bestämt björnkött, vildsvinstarmar och spindelichor från bestar som strövar omkring i Loch Modan.",al={"ingredienser i blood sausage","vad innehåller thelsamars blodkorvar","vidras recept"}}},fx={["5e429306"]={q="Vem står Vidra Hearthstove på sida med?",a="Vidra är en lojal dvärgisk medborgare i Khaz Modan och en fast allierad till Alliansen. Hon bor och arbetar mitt i Thelsamar, där hon lagar mat åt lokalsamhället och välkomnar trötta resenärer som har tagit sig genom Loch Modan.",al={"vidra hearthstoves fraktion","tillhör vidra alliansen","vidra hearthstoves sida"}},e3ca8182={q="Vad vill Vidra Hearthstove?",a="Vidra brinner för sitt matlagningshantverk och vill hålla gästerna på Stoutlager Inn mätta. Hon söker färska, rejäla ingredienser från djurlivet kring sjön, särskilt kött och inälvor från traktens bestar, för att laga sina berömda blodkorvar från Thelsamar.",al={"vidra hearthstoves drivkraft","vad vill vidra","vidra hearthstoves recept"}},["8f91522d"]={q="Varför är Vidra Hearthstove här i Thelsamar?",a="Vidra försörjer sig på arbetet inne på Stoutlager Inn, där hon lagar husmanskost åt stadens invånare, hantverkare och äventyrare på genomresa. Eftersom Thelsamar är Loch Modans viktigaste knutpunkt är hennes kök avgörande för att hålla traktens försvarare och arbetare mätta.",al={"varför är vidra på stoutlager inn","varför finns vidra hearthstove här","varför är vidra här"}}},fp="17,114,25.190.0,25.159.0,37.87.0,59.105.0"}
P.entries["npc:viktori-prism-antras"] = {n="Viktori Prism'Antras",s="Viktori Prism'Antras är en egendomlig stjärnskådare som bor i en liten stuga på sluttningen med utsikt över Darkshire. Medan staden omkring honom drabbas av skräck och hotande fasor koncentrerar sig Viktori helt på att bygga ett teleskop så att han kan se himlavalvet tydligt. För att förverkliga sin vision förlitar han sig på äventyrliga resenärer som kan skaffa intrikata delar enligt gnomiska ritningar.",h="Viktori Prism'Antras är en egendomlig stjärnskådare som bor i en liten stuga på sluttningen med utsikt över...",kw={"astronomi","cog glitzspinner","darkshire","duskwood","se mot stjärnorna","prism'antras","stjärnskådare","teleskop","viktori"},ang={["faction:Alliance"]="Att hjälpa Viktori ger dig ett sällsynt, fridfullt uppdrag i Darkshire och hjälper en Alliance-bo att söka efter förundran mitt i den utbredda tragedin.",["profession:Engineering"]="Hantverkare lär uppskatta Viktoris projekt, eftersom hans precisa observationsinstrument helt bygger på avancerade gnomiska ritningar.",["race:Gnome"]="Hela Viktoris projekt vilar på uppfinningsrikedomen hos den gnomiska uppfinnaren Cog Glitzspinner och visar hur långt gnomisk ingenjörskonst når, även i de mest ödsliga mänskliga städerna."},sec={{t="Blicken mot himlen",b="Uppe på sluttningen strax bortom Gryphon Roost tillbringar Viktori Prism'Antras dagarna med att blicka ut ur Duskwoods mörker. Mitt bland odödas angrepp, glupska spindlar och smygande skuggor riktar han sin besatthet långt bortom det kvävande lövverket. Han drömmer om att bygga ett magnifikt optiskt teleskop som kan få stjärnorna att framträda klart och skänka en stillsam flykt från skräcken som omsluter byn."},{t="Gnomiska ritningar och utspridda delar",b="Att konstruera en så ömtålig apparat är ingen enkel sak i en förhäxad skog. Viktori arbetar utifrån ritningar från sin gnomiska vän Cog Glitzspinner. För att färdigställa apparaten ber han förbipasserande leta rätt på sällsynta material för linstillverkning och mekaniska höljen, från noggrant slipat glas till metallinser som ligger utspridda i farliga trakter."}},faq={{q="Vem är Viktori Prism'Antras?",a="Viktori är en egendomlig mänsklig stjärnskådare som bor i Darkshire. I stället för att bekymra sig om stadens omedelbara politiska eller övernaturliga hot är han helt besatt av att bygga ett kraftfullt teleskop för att studera stjärnorna.",al={"vem är viktori","viktori prism'antras bakgrund","viktori duskwood"}},{q="Var hittar jag Viktori i Darkshire?",a="Han bor i en liten trästuga uppe på kullen, strax bortom gryphonmästaren i Darkshire. Stugan ligger till höger när du går uppför stigen.",al={"viktori prism'antras plats","var finns viktori","hitta viktori darkshire"}},{q="Vad försöker Viktori bygga?",a="Viktori försöker bygga ett astronomiskt teleskop med hjälp av ritningar från sin gnomiska kollega Cog Glitzspinner. Det kräver flera speciallinser och delar för att sättas ihop.",al={"viktoris teleskop","anordning för att se stjärnorna","vad bygger viktori"}},{q="Varför studerar han stjärnorna från Duskwood?",a="Trots mörkret och den ständiga skräck som genomsyrar Duskwood drivs Viktori av sin himmelska nyfikenhet. Att fästa blicken på natthimlens obefläckade storslagenhet ger honom en intellektuell tillflykt från det förfallna landet omkring honom.",al={"varför teleskop i darkshire","varför studera stjärnor i duskwood"}},{q="Vem utformade ritningarna till Viktoris teleskop?",a="Ritningarna skapades av Cog Glitzspinner, en uppfinningsrik gnom som känner Viktori och försåg honom med de scheman som behövdes för att sätta ihop observationsapparaten.",al={"cog glitzspinner","vem gjorde teleskopritningarna"}},{q="Hjälper Viktori till att försvara Darkshire?",a="Nej. Viktori är en civil forskare, inte en krigare. Han överlåter försvaret av staden åt Commander Althea Ebonlocke och Night Watch och föredrar att ägna all sin energi åt astronomin.",al={"är viktori en nattväktare","strider viktori"}}},fx={["27dfc9ca"]={q="Vem står Viktori Prism'Antras på sida med?",a="Viktori är en fridsam människa som står på Alliansens och det hårt prövade samhället i Darkshires sida. Medan staden kämpar mot skuggor, förbannelser och vildsinta bestar håller han sig för sig själv och undviker striderna. Han ägnar sig helt åt studier och stjärnskådning.",al={"viktori prism'antras fraktion","tillhör viktori alliansen","vem tjänar viktori"}}},fp="20,359,21.420.0,38.354.0,28.239.0,38.127.0,32.195.0,43.227.0,47.167.0,35.207.0"}
P.entries["npc:viscous-fallout"] = {n="Viscous Fallout",s="Viscous Fallout är en giftig vattenelemental som strövar genom Gnomeregans bestrålade korridorer, en levande massa av giftet som förorenade staden efter Mekgineer Thermapluggs förödande strålningsutsläpp.",h="Viscous Fallout är en giftig vattenelemental som strövar genom Gnomeregans bestrålade korridorer, en levande...",kw={"gnomeregan","hydrocane","strålning","thermaplugg","tinker town","viscous fallout","vattenelemental"},ang={["class:Druid"]="Druider ser varelsen som ett levande sår i naturen, ett exempel på de fasansfulla följderna av vårdslös industriell förorening som sipprar in i naturliga underjordiska vatten.",["class:Shaman"]="En schaman känner igen förvanskningen av elementarplanet och ser i Viscous Fallout en vattenelemental som besudlats av artificiellt giftigt avfall.",["race:Gnome"]="För gnomerna är Viscous Fallout en sorglig påminnelse om skadan Mekgineer Thermaplugg tillfogade deras hem, där till och med vattnet nu är giftigt."},sec={{t="En förorenad ande",b="När Gnomeregan bestrålades efter Mekgineer Thermapluggs förrädiska råd om att utplåna de invaderande troggarna, fylldes stadens nedre nivåer av giftigt slem och föroreningar. Viscous Fallout är en vattenelemental från dessa förgiftade djup, vars hela väsen är genomsyrat av stadens giftiga avfall. Det är okänt var den kom ifrån före stadens fall."},{t="Pina i avrinningen",b="Nu är varelsen föga mer än en levande pöl av giftigt slam som driver genom de bestrålade nedre gångarna. Viscous Fallout sprutar ut skurar av gift och slår mot allt i sin väg. Att fälla den är en dyster nödvändighet för dem som ger sig in i Gnomeregan för att rena de besmittade djupen."}},faq={{q="Vad är Viscous Fallout?",a="Viscous Fallout är en vattenelemental och miniboss inne i den förstörda staden Gnomeregan, helt förgiftad av giftigt slam och radioaktivt nedfall.",al={"vem är viscous fallout","viscous fallout bakgrund","vad är viscous fallout för typ av fiende"}},{q="Hur blev den förvriden?",a="Gnomeregan bestrålades efter Mekgineer Thermapluggs förrädiska råd om att slå tillbaka trogginvasionen, vilket fyllde de nedre gångarna med giftigt avfall. Det är okänt exakt hur denna elemental kom att genomsyras av giftet; den är helt enkelt en del av den bestrålade ruin staden har blivit.",al={"varför är den grön","varför är elementalen giftig","hur skapades viscous fallout"}},{q="Var i Gnomeregan strövar den?",a="Viscous Fallout patrullerar de nedre bestrålade gångarna och avloppskanalerna under Gnomeregans huvudsakliga ingångsleder. Den smälter ofta in bland de vanliga muterade slemmen och det giftiga avfall som angriper området.",al={"viscous fallout plats","var hittar man viscous fallout","hur hittar man viscous fallout"}},{q="Varför är den fientlig?",a="Precis som det mesta som nu hemsöker de bestrålade djupen går den giftiga elementalen till angrepp mot alla levande varelser som tränger in i de besmittade gångarna.",al={"varför anfaller den","kan den räddas"}},{q="Har den någon koppling till Ironforge?",a="Bara indirekt. Gnomerna som flydde från Gnomeregan bor nu som flyktingar i Tinker Town i Ironforge, och Viscous Fallout är en av fasorna som lämnades kvar i hemmet de förlorade.",al={"hydrocane ironforge","koppling till gnomer"}},{q="Kan elementalen renas eller botas?",a="Det finns inget känt botemedel för elementalen. Strålningen och de giftiga kemikalierna har genomsyrat den så fullständigt att det enda som återstår är att förgöra den.",al={"kan man bota viscous fallout","rena viscous fallout"}}},fx={c0463f1a={q="Vem står Viscous Fallout på sida med?",a="Viscous Fallout tjänar ingen herre och tillhör ingen fraktion. Dess giftiga tillstånd är en direkt följd av att Mekgineer Thermaplugg släppte ut radioaktivt avfall över staden, men varelsen är inte allierad med honom, de spetälska gnomerna eller troggarna. Den är bara en plågad elementarvarelse, vansinnig av föroreningarna och urskillningslöst våldsam mot allt som kommer i dess väg.",al={"viscous fallout fraktion","vem tjänar viscous fallout","är viscous fallout allierad med thermaplugg"}},["41523791"]={q="Vad vill Viscous Fallout?",a="Elementarvarelsen har inga storslagna ambitioner eller något förnuftigt syfte. Den består av det gift som förorenade Gnomeregan och vandrar genom de bestrålade korridorerna, där den angriper alla levande varelser som har oturen att ta sig in i stadens översvämmade gångar.",al={"viscous fallouts mål","vad gör viscous fallout","viscous fallouts drivkraft"}},["2b056577"]={q="Varför är Viscous Fallout här?",a="Den strövar omkring i Gnomeregans bestrålade djup, som översvämmades av giftigt avfall när Mekgineer Thermaplugg fyllde staden med strålning för att driva tillbaka troggarna. Ingen vet var elementarvarelsen kom ifrån innan staden föll.",al={"varför är viscous fallout i gnomeregan","hur hamnade viscous fallout här","varför finns viscous fallout här"}}},fp="15,80,17.323.0,19.253.0,24.124.0,28.266.0,35.183.0,18.133.0,41.179.0,39.142.0"}
P.entries["npc:vol-jin"] = {n="Vol'jin",s="I Orgrimmar ger Vol'jin råd till krigshövding Thrall medan han söker ett varaktigt hem åt sitt folk. Darkspear-hövdingen är en mästerskuggjägare.",h="I Orgrimmar ger Vol'jin råd till krigshövding Thrall medan han söker ett varaktigt hem åt sitt folk.",kw={"darkspear","grommash hold","orgrimmar","sen'jin","skuggjägare","thrall","vol'jin","zalazane"},ang={["faction:Horde"]="Som medlem av horden har du Vol'jin vid Thralls sida, där han erbjuder listiga råd och djungeltrollens orubbliga lojalitet.",["race:Troll"]="Som troll har du Vol'jin som hövding. Han vägleder de fördrivna Darkspear genom svårigheterna med andlig visdom och taktisk beslutsamhet."},sec={{t="Hövding över Darkspear",b="Vol'jin leder Darkspear efter att hans far Sen'jin dör på deras förfäders ö. Murlocer som dyrkar havshäxor och mänskliga styrkor är nära att utplåna den isolerade stammen, men Thralls orcher ingriper och knyter ett starkt band till trollen. Efter att ha flytt från de förstörda öarna svär Vol'jin sitt folk till den nya horden och för dem över det stora havet till Kalimdor."},{t="Råd i Visdomens dal",b="Darkspear slår sig ner i Durotar, men Zalazanes förräderi på Echo Isles driver många flyktingar till fastlandet, till Sen'jin Village. Vol'jin tillbringar mycket av sin tid i Grommash Hold i Orgrimmar, där han ger Thrall strategiska råd och delar med sig av sin skicklighet som skuggjägare. Från orchernas huvudstad vakar han över den unga horden och arbetar för att återta sitt folks länder."}},faq={{q="Vem är Vol'jin?",a="Vol'jin leder Darkspear-trollstammen och ger krigshövding Thrall råd i Orgrimmar. Som skicklig skuggjägare företräder han sitt folk bland hordens ledare.",al={"vem är trollens ledare","vol'jins historia","darkspears ledare"}},{q="Var bor Vol'jin?",a="Vol'jin bor i Grommash Hold, i Orgrimmars Visdomens dal, intill krigshövding Thrall.",al={"var finns vol'jin","vol'jins plats","hitta vol'jin"}},{q="Varför gick Darkspear med i Horden?",a="Under det tredje kriget spolades Thralls flotta upp på Darkspear Islands. Orcherna allierade sig med trollen mot fientliga människor och en fanatisk murlocarmé. Efter Sen'jins död svor Vol'jin sin stam till Thrall, och Darkspear följde med horden till Kalimdor.",al={"varför tillhör troll horden","darkspears historia i horden","thrall och vol'jin"}},{q="Varför bor inte Darkspear på sina egna öar?",a="Efter att ha slagit sig ner på Echo Isles utanför Durotar drevs häxdoktorn Zalazane till vansinne av mörk magi. Han förslavade sina stamfränder och tvingade Vol'jin och de överlevande ur Darkspear att fly till Sen'jin Village på fastlandet.",al={"vad hände med echo isles","varför är trollen i sen'jin village","zalazanes svek"}}},fx={["779e986b"]={q="Varför är Vol'jin berömd?",a="Vol'jin är känd både som Darkspear-stammens hövding och som en skicklig skuggjägare, djupt förbunden med loa. Han ledde sitt folk genom förödande murlocräder, människo-invasioner och landsflykt, och vann därigenom trollens eviga respekt och högsta aktning bland den nya Hordens grundare.",al={"varför vördas vol'jin","vol'jins rykte","är vol'jin berömd"}},["00b3c7ef"]={q="Vem står Vol'jin på sida med?",a="Vol'jin är helt hängiven Horden och sina egna landsförvisade Darkspear-troll. Ända sedan Thrall och orcherna räddade hans stam från att utplånas i deras öhemland har Vol'jin hedrat sin fars trohetsed. Han är en av Thralls mest betrodda rådgivare och ger kloka råd och taktisk vägledning från hjärtat av Orgrimmar.",al={"vol'jins fraktion","vem tjänar vol'jin","tillhör vol'jin horden"}},["9b5f7e47"]={q="Vad vill Vol'jin?",a="Framför allt vill Vol'jin säkra en trygg och välmående framtid för Darkspear-stammen och uppfylla sin far Sen'jins sista önskan. Han arbetar nära Thrall för att befästa Hordens ställning i Durotar, skydda sitt fördrivna folk från Kalimdors fientliga hot och bevara deras förfäders traditioner.",al={"vol'jins mål","vad driver vol'jin","vad söker vol'jin"}},ee20a7f7={q="Varför är Vol'jin i Orgrimmar?",a="Vol'jin bor i Grommash Hold vid Thralls sida för att representera Darkspear-trollen i Hordens lednings hjärta. Förutom att vägleda sitt folk fungerar han som krigshövdingens främste strateg och andlige rådgivare. Han samordnar stammens försvar och stärker den viktiga alliansen mellan troll och orcher.",al={"varför är vol'jin i orgrimmar","varför är vol'jin här","vad gör vol'jin i orgrimmar"}},df7c3222={q="Vilka band har Vol'jin?",a="Vol'jin är son och efterträdare till den vördnadsvärde häxdoktorn Sen'jin, vars offer räddade Darkspear. Han har ett orubbligt band till krigshövding Thrall, som han ger råd dagligen, och hans band till loa-andarna vägleder honom på vägen som skuggjägare.",al={"vol'jins allierade","vol'jins förbindelser","vilka släktband har vol'jin"}}},fp="7,141,26.363.0,31.353.0,15.158.0,24.88.0,37.267.0,53.223.0"}
P.entries["npc:volcor"] = {n="Volcor",s="Volcor är en sårad Night Elf-spejare som är strandsatt djupt inne i Blackwood Den i södra Darkshore. Han är fångad av fientliga Blackwood-furbolgs och förlitar sig på sin trogna följeslagare Grimclaw och hjälp från Auberdines försvarare för att fly.",h="Volcor är en sårad Night Elf-spejare som är strandsatt djupt inne i Blackwood Den i södra Darkshore.",kw={"auberdine","blackwood den","darkshore","fly genom att slåss","fly genom att smyga","furbolg","grimclaw","terenthis","volcor"},ang={["class:Druid"]="Bandet mellan Volcor och Grimclaw speglar den djupa samhörighet som druider har med naturens djur. Därför handlar räddningen också om att bevara naturens balans.",["class:Rogue"]="Volcor uppskattar taktisk finess och ger rogues chansen att smyga förbi Blackwood-vakterna i stället för att förlita sig på råstyrka.",["race:NightElf"]="Volcors belägenhet visar den växande fara som hotar Kaldorei i Darkshore när tidigare fredliga furbolg-allierade faller offer för korruption."},sec={{t="Fångad i The Den",b="När Volcor spårade den korrumperade Blackwood-stammen i deras underjordiska håla blev han överfallen och svårt sårad. Oförmögen att själv kämpa sig förbi de fientliga furbolgs skickade han sin trogna björnföljeslagare Grimclaw ut i Darkshores vildmark för att söka hjälp från bosättningen Auberdine."},{t="En väg till frihet",b="När spejare som Terenthis larmat hittar Volcor erbjuder han två flyktvägar, beroende på vad hans räddare är bra på. Den som föredrar direkt handling kan bana sig en blodig väg genom grottans försvarare, medan den som är skicklig på list kan smyga förbi vaktposterna obemärkt."}},faq={{q="Var finns Volcor?",a="Volcor gömmer sig djupt inne i Blackwood Den, en furbolggrotta längst söderut i Darkshore nära gränsen till Ashenvale, inte långt från vägen söderut från Auberdine.",al={"volcors plats","var finns volcor","hitta volcor"}},{q="Varför är Volcor fångad i Blackwood Den?",a="Han spanade på Blackwood-furbolgs när han blev attackerad och sårad. Avskuren från grottans ingång kunde han inte ta sig förbi de fientliga vaktposterna utan hjälp.",al={"varför är volcor i en grotta","vad hände med volcor"}},{q="Vem är Grimclaw?",a="Grimclaw är Volcors trogna björnföljeslagare. När Volcor blev fångad skickade han Grimclaw för att hämta hjälp i Auberdine, vilket till slut larmade druiden Terenthis.",al={"vem är björnen","volcors björn","grimclaws historia"}},{q="Hur kan du hjälpa Volcor att fly?",a="Volcor låter dig välja hur du ska rädda honom: du kan antingen slå dig ut genom grottans furbolgvakter i ett frontalangrepp eller smyga förbi dem obemärkt.",al={"fly med våld eller genom att smyga","volcors eskortuppdrag","rädda volcor"}},{q="Vem skickade dig för att hitta Volcor?",a="Terenthis, en Night Elf-druid stationerad i Auberdine, skickar äventyrare för att leta efter Volcor när Grimclaw hittas strövande utan sin husse.",al={"vem gav volcor-uppdraget","terenthis koppling"}},{q="Vilken furbolgstam attackerade honom?",a="Blackwood-stammen, en korrumperad grupp furbolgs från Darkshore som har dukat under för vansinne och fientlighet.",al={"vilka furbolgs","blackwood-furbolgs"}}},fx={fe864757={q="Vem är Volcor?",a="Volcor är en Night Elf-utforskare och vandrare i Darkshore. Med sin trogna björnföljeslagare Grimclaw gav han sig djupt in i skogarna, tills han råkade ut för de fientliga Blackwood-furbolgerna. Han blev sårad och strandsatt i deras håla.",al={"vem är volcor","volcors identitet","volcor night elf"}},["77334435"]={q="Vems sida står Volcor på?",a="Volcor är allierad med Night Elf-folket i Darnassus och Alliansen. Hans betrodda kontakter finns i kusttillflykten Auberdine, där vänner som Terenthis ser till att han är trygg och välkomnar resenärer som hjälper honom.",al={"volcors fraktion","tillhör volcor alliansen","volcors lojalitet"}},a5845558={q="Vad vill Volcor?",a="Volcor sitter fast, försvagad djupt inne i Blackwood Den, och vill bara ta sig ut levande och återvända till tryggheten i Auberdine. Han skickade Grimclaw i förväg för att söka hjälp och förlitar sig nu på förbipasserande allierade som kan leda honom förbi de fientliga furbolgerna.",al={"vad vill volcor","volcors mål","volcors motiv"}}},fp="6,172,18.318.0,16.268.1,24.137.0,39.167.0,16.141.0,31.123.0,28.121.0,36.130.0"}
P.entries["npc:vorn-skyseer"] = {n="Vorn Skyseer",s="Vorn Skyseer är en fridsam tauren som bor i Camp Narache på Red Cloud Mesa i Mulgore. Han vilar bland lägrets tält, hälsar unga äventyrare välkomna när de ger sig ut på sina resor och introducerar dem till livet på platsen.",h="Vorn Skyseer är en fridsam tauren som bor i Camp Narache på Red Cloud Mesa i Mulgore.",kw={"camp narache","mulgore","red cloud mesa","tauren","vorn skyseer","välkommen"},ang={["faction:Horde"]="Vorn personifierar den lugna och stadiga naturen hos slättstammarna, som har samlats under Cairne Bloodhoofs ledarskap för att bygga ett permanent hem.",["race:Tauren"]="För unga tauren på Red Cloud Mesa är Vorn Skyseer ofta ett av de första välbekanta och betryggande ansiktena som hälsar dem välkomna när de förbereder sig på att ta steget ut i Mulgore och dess vidsträckta värld."},sec={{t="Ett vänligt ansikte i Camp Narache",b="Vorn Skyseer finns i Camp Narache på Red Cloud Mesa och välkomnar unga tauren. När de genomgår sina övergångsriter innan de ger sig ut i Mulgores vidsträckta dalar, bjuder Vorn på vänliga ord och gästfrihet och hjälper nykomlingar att finna sig till rätta i lägret."},{t="En tillbakadragen betraktare",b="Vorn är ingen krigare. Han överlåter försvaret av lägret åt dess braves och lever ett stillsamt, lugnt liv, nöjd med att se ut över sitt hemlands fridfulla slätter."}},faq={{q="Vem är Vorn Skyseer?",a="Vorn Skyseer är en äldre invånare i Camp Narache i Mulgore. Framför allt välkomnar han unga tauren-braves som påbörjar sina inledande riter på Red Cloud Mesa.",al={"vorn skyseer berättelse","vem är vorn","vorn mulgore"}},{q="Var hittar jag Vorn Skyseer?",a="Han kan hittas utomhus bland tälten i Camp Narache, på Red Cloud Mesa i sydvästra Mulgore.",al={"vorn skyseer plats","var finns vorn","vorn camp narache"}},{q="Vilka uppdrag erbjuder Vorn?",a="I uppdraget Welcome! tar han emot Bloodhoof Village Gift Voucher, hälsar dess bärare välkommen och erbjuder en liten följeslagare som kan följa med på äventyren.",al={"vorn skyseer uppdrag","vorn welcome-uppdrag"}}},fx={["786f5f1f"]={q="Vems sida står Vorn Skyseer på?",a="Vorn Skyseer är en tauren som bor i Camp Narache på Red Cloud Mesa och står stadigt på Mulgore-stammarnas och Hordens sida. Han är ingen krigare; hans hem och lojalitet finns hos hans folk.",al={"vorn skyseers fraktion","vem tjänar vorn","vorns lojalitet"}},["28d2e499"]={q="Varför är Vorn Skyseer i Camp Narache?",a="Vorn Skyseer bor i Camp Narache för att hälsa de unga krigarna välkomna när de inleder sina färder på Red Cloud Mesa. Han erbjuder vänliga ord och gästfrihet och hjälper nykomlingarna att finna sig till rätta i lägret.",al={"varför är vorn här","vorn skyseers roll i bloodhoof","vad gör vorn"}}},fp="12,170,31.213.0,19.131.0,20.147.0,30.120.0,28.144.0"}
P.entries["npc:warcaller-gorlach"] = {n="Warcaller Gorlach",s="Warcaller Gorlach patrullerar Orgrimmar och kallar Hordens hjältar till avlägsna fronter. Han samlar resenärer och erfarna krigare för att lyda order vid utposter i Kalimdor och bortom.",h="Warcaller Gorlach patrullerar Orgrimmar och kallar Hordens hjältar till avlägsna fronter.",kw={"jakt i ashenvale","kalla till vapen","camp mojache","gorlach","härold","orgrimmar","warcaller gorlach"},ang={["faction:Horde"]="Som en hjälte i Horden som vill bevisa din styrka eller söka vägledning bortom Durotar kan du vända dig till Gorlach för att få vägvisning till utposter som behöver förstärkning."},sec={{t="Warchiefens kallelse",b="Warcaller Gorlach går längs Orgrimmars gator och förmedlar Hordens uppmaningar till expansion och försvar. Han ger order bland stadens invånare och söker frivilliga som är redo att pröva sin styrka. Vissa skickar han till Ashenvales omstridda trädkronor. Andra styr han mot Camp Mojache i Feralas, där spejare möter vildmarken. Han kallar också krigare till avlägsna fälttåg i Plaguelands. När hoten växer utomlands uppmanar Gorlach huvudstadens invånare att gripa till vapen."}},faq={{q="Vem är Warcaller Gorlach?",a="Warcaller Gorlach patrullerar Orgrimmar som orcisk härold och styr Hordens medlemmar mot stridszoner och avlägsna gränstrakter.",al={"gorlach","vem är gorlach","krigshärold"}},{q="Vart skickar Warcaller Gorlach äventyrare?",a="Warcaller Gorlach styr Hordens hjältar till utposter som behöver hjälp, däribland Ashenvale, Camp Mojache i Feralas och avlägsna fronter som Plaguelands.",al={"gorlachs resmål","vart skickar gorlach dig","gorlachs uppdrag"}},{q="Var hittar man Warcaller Gorlach?",a="Warcaller Gorlach patrullerar Orgrimmars gator och dalar och kallar dess invånare till vapen.",al={"gorlachs plats","var är gorlach","hitta gorlach"}}},fx={["1e435e0c"]={q="Vems sida står Warcaller Gorlach på?",a="Warcaller Gorlach är en lojal orc som tjänar Horden. Han är stationerad i Orgrimmar och samlar aktivt krigare för att försvara Hordens intressen och stärka militära fälttåg i Kalimdor och bortom.",al={"gorlachs fraktion","tillhör gorlach horden","vem tjänar gorlach"}},["5b62b1f9"]={q="Vad vill Warcaller Gorlach?",a="Gorlach söker stridsdugliga kämpar som svarar på Hordens kallelse. Han hänvisar ivriga äventyrare till omstridda gränstrakter och viktiga fästen och samlar rekryter till de pågående striderna runtom i världen.",al={"vad vill gorlach","gorlachs syfte","gorlachs uppdrag"}},["662e00c8"]={q="Varför är Warcaller Gorlach i Orgrimmar?",a="Gorlach går längs gatorna i Hordens huvudstad som krigsropare och fungerar som rekryterare och budbärare. Genom att patrullera Orgrimmar ser han till att anländande hjältar får höra om avlägsna strider som behöver omedelbar hjälp.",al={"varför är gorlach här","gorlach i orgrimmar","gorlachs roll i orgrimmar"}}},fp="17,187,28.471.0,25.119.0,46.152.0,37.91.0"}
P.entries["npc:warden-thelwater"] = {n="Warden Thelwater",s="Warden Thelwater är den belägrade föreståndaren för The Stockade, Stormwind Citys underjordiska högsäkerhetsfängelse. När ett våldsamt upplopp bröt ut bland Defias-fångarna blev han tagen på sängen. Nu rekryterar han desperat dugliga äventyrare för att slå ner upproret innan ryktet sprids till staden ovanför.",h="Warden Thelwater är den belägrade föreståndaren för The Stockade, Stormwind Citys underjordiska...",kw={"bazil thredd","defias","fängelse","upplopp","stockade","stormwind","thelwater","warden thelwater"},ang={["class:Paladin"]="För heliga krigare som vigt sig åt ordning och rättvisa är Thelwaters desperata kamp för att återta kontrollen en direkt kallelse att skipa rättfärdig disciplin åt våldsamma brottslingar.",["class:Rogue"]="Rogues som går in i The Stockade för Thelwaters skull får navigera i kaoset efter Defias-intriger och fängelsepolitik under jord.",["faction:Alliance"]="Warden Thelwater står för den sköra ordningen i Stormwind och förlitar sig på lojala Alliance-mästare för att slå ner fångarnas myteri innan det hotar huvudstadens invånare."},sec={{t="En kris i kanalerna",b="Dolt under Stormwinds kanaler hyser The Stockade kungarikets farligaste förbrytare, småtjuvar och politiska konspiratörer. Warden Thelwater fick i uppdrag att hålla dem säkert inlåsta, men ett organiserat uppror överrumplade vakterna fullständigt. När fångarna övermannade säkerhetsstyrkorna och tog kontroll över cellerna blev Thelwater barrikaderad vid ingången, där han kämpade för att hålla ett väpnat uppror i schack precis under huvudstadens gator."},{t="Att hålla sanningen dold",b="I stället för att låta paniken sprida sig på Stormwinds gator har Thelwater valt att hantera upproret med största diskretion. Hjärnan bakom utbrytningen, Bazil Thredd, har ett enormt inflytande bland Defias Brotherhood-medlemmarna som sitter inlåsta där. För att hindra upploppet från att blottlägga större svagheter i Stormwinds styre förlitar sig Thelwater på utomstående legosoldater. De ska ta sig in i cellblocken, slå ut ledarna och återta anläggningen i tysthet."}},faq={{q="Vem är Warden Thelwater?",a="Warden Thelwater är en mänsklig tjänsteman som är stationerad vid ingången till The Stockade i Stormwind City. Han ansvarar för att sköta det högsäkrade fängelsekomplexet.",al={"thelwater","föreståndare för stockade","vem är thelwater"}},{q="Vad hände med The Stockade?",a="Ett samordnat uppror bröt ut bland fångarna, främst drivet av fängslade medlemmar i Defias Brotherhood. Fångarna övermannade vakterna och tog över cellblocken, vilket lämnade Thelwater och hans återstående män fastklämda nära ingången.",al={"upplopp i stockade","vad hände i stockades","varför är stockades i kaos"}},{q="Vem leder fängelseupploppet?",a="Bazil Thredd är hjärnan bakom upproret och styr det från fängelsets djup. Han befaller Defias-fångarna och låg bakom den plötsliga attacken mot vakterna.",al={"ledare för stockade","vem leder upproret","vem är bazil thredd"}},{q="Varför har Stormwind City Guard inte ingripit med full styrka?",a="Thelwater vill lösa katastrofen i tysthet. Om det blir känt att Stormwinds mest befästa fängelsehåla föll för sina egna fångar kan det utlösa omfattande panik i staden. Därför anlitar han diskreta äventyrare för att städa upp inne i fängelset.",al={"varför inga vakter","varför anlita äventyrare","hemligt upplopp"}},{q="Vilka slags fångar hålls här?",a="Anläggningen hyser småskurkar, tjuvar, mördare och farliga politiska upprorsmakare, framför allt högt uppsatta medlemmar i Defias Brotherhood.",al={"stockades fångar","vilka finns i stockade","sorters brottslingar"}},{q="Var hittar man Warden Thelwater?",a="Han är stationerad precis utanför ingången till The Stockade, nära kanalerna mellan Mage Quarter och Cathedral Square i Stormwind City.",al={"thelwaters plats","var finns föreståndaren","hitta thelwater"}}},fx={["088280c3"]={q="Vems sida står Warden Thelwater på?",a="Thelwater tjänar kungariket Stormwind och lyder dess styrande makt. Som The Stockades officiella fångvaktare företräder han stadens fängelseförvaltning och kronan. Han försöker upprätthålla ordningen under gatorna och hindra rikets värsta brottslingar från att ta sig ut i huvudstaden.",al={"thelwaters fraktion","vem tjänar thelwater","tillhör thelwater alliansen"}},bf0ea06f={q="Vad vill Warden Thelwater?",a="Thelwater vill slå ner fängelseupproret skoningslöst innan kaoset sprider sig. Defias upplopp överrumplade honom. Hans främsta mål är att undanröja Bazil Thredd, hjärnan bakom upproret, och kuva rebellernas ledare för att återta full kontroll över anstalten så obemärkt som möjligt.",al={"vad behöver thelwater","thelwaters mål","varför behöver thelwater äventyrare"}},["4dddd3c5"]={q="Varför är Warden Thelwater här?",a="Thelwater är stationerad vid ingången till The Stockade eftersom han tvingades tillbaka när fångarna gjorde uppror. Han kan inte kuva upploppet ensam med sina kvarvarande vakter. Därför håller han sig nära kanalingången för att hålla stånd och värva dugliga legoknektar som kan tränga in och återta cellerna.",al={"varför är thelwater vid the stockade","thelwater står utanför","varför är thelwater vid ingången"}},["479dc467"]={q="Vilka band har Warden Thelwater?",a="Thelwater är knuten till Stormwinds styre och arbetar tillsammans med stadsvakterna som har i uppgift att säkra huvudstaden. Hans mest akuta koppling i fängelsehålan är hans fiendskap med fången Bazil Thredd, vars samordnade uppror hotar både Thelwaters ställning och kungarikets säkerhet.",al={"thelwaters allierade","vem arbetar thelwater för","thelwaters kontakter"}}},fp="16,194,22.421.0,20.386.1,24.119.0,30.222.0,31.139.0,56.196.0,37.146.0,36.146.0"}
P.entries["npc:warlord-goretooth"] = {n="Warlord Goretooth",s="Warlord Goretooth är den befälhavande orc-officeren som är stationerad i Kargath, i Badlands dammiga ödemarker. Från sitt vakttorn samordnar han Hordens gränskampanjer mot de närliggande Dark Iron-dvärgarna och håller uppsikt över hotet från Blackrock Mountains vulkaner. Trots att han är sträng i militära frågor kan han ibland koppla av vid lägrets lägereld.",h="Warlord Goretooth är den befälhavande orc-officeren som är stationerad i Kargath, i Badlands dammiga...",kw={"angerforge","badlands","blackrock","dark iron","eitrigg","goretooth","kargath","warlord goretooth"},ang={["class:Warrior"]="Goretooths brutala och rättframma militärorder i Blackrock Mountain ger stridsmästare chansen att pröva sin styrka mot rutinerade dvärglegionärer.",["faction:Horde"]="Warlord Goretooth är hörnstenen i Hordens fäste i Badlands och leder viktiga operationer mot Dark Iron-dvärgarna."},sec={{t="Befälhavare i Kargath",b="Warlord Lunk Goretooth sitter högt uppe i Kargaths vakttorn och leder Hordens operationer vid den fientliga östra gränsen. Kargath fungerar som Orgrimmars främsta uppmarschområde mot hoten som lurar i Blackrock Mountain och de omgivande ravinerna. Goretooth övervakar patruller, samordnar spaningsstyrkor som Kargath Expeditionary Force och utfärdar direkta dödsorder mot Dark Iron-klanens soldater och ledare. När han lämnar sin utkiksplats visar den stränge befälhavaren en lättsammare sida. Han värmer sig ofta vid lägerelden och skämtar med lägrets Forsaken-besvärjare innan han återgår till tjänstgöringen."},{t="Angrepp mot Dark Iron",b="Goretooth ser Dark Iron-dvärgarna som ett tydligt och omedelbart hot mot Hordens intressen i Eastern Kingdoms. I stället för att inta en defensiv hållning driver han offensiva krigsplaner mot General Angerforge och Emperor Dagran Thaurissans styrkor, som är förskansade i Blackrock Depths. Han inser hur allvarligt det är att angripa en så gammal underjordisk fästning och överlåter därför ofta strategiska frågor åt veteraner som Eitrigg i Orgrimmar. Han söker deras erfarna råd innan han godkänner ytterligare framryckningar in i berget."}},faq={{q="Vem är Warlord Goretooth?",a="Warlord Goretooth är Hordens högste militäre befälhavare i Badlands, stationerad i Kargath. Han organiserar Hordens patruller och leder anfall mot Dark Iron-dvärgarna.",al={"warlord goretooth","vem är goretooth","goretooth i badlands","befälhavare i kargath"}},{q="Vilken roll har han i Kargath?",a="Han leder utposten, skickar regelbundet ut Kargath Expeditionary Force och utfärdar militära order om operationer mot Dark Iron-klanen i Blackrock Depths.",al={"vad gör goretooth","goretooths uppgifter","goretooths postering"}},{q="Varför skickar Goretooth soldater mot Blackrock Depths?",a="Dark Iron-dvärgarna hotar de omgivande områdena och bekämpar aktivt Hordens närvaro där. Goretooth utfärdar direkta belöningar för att döda deras soldater, höga officerare och General Angerforge, för att försvaga deras grepp om berget.",al={"varför döda dark iron","uppdraget död åt angerforge","goretooth och dark iron"}},{q="Varför rådfrågar Goretooth Eitrigg?",a="Eitrigg är en erfaren orc-veteran som har bott i Blackrock Mountain och förstår dess inre politik och försvar bättre än nästan någon annan. Goretooth skickar äventyrare för att söka Eittriggs råd innan han trappar upp anfallen mot fästningarna i Blackrock.",al={"goretooth och eitrigg","eittriggs visdom","varför tala med eitrigg"}}},fp="17,370,20.631.0,23.528.0,25.175.0,28.187.0,59.248.0,35.254.0"}
P.entries["npc:warmaster-laggrond"] = {n="Warmaster Laggrond",s="Warmaster Laggrond är en erfaren orcisk befälhavare stationerad utanför Horde-entrén till Alterac Valley i Alterac Mountains. Han leder rekryteringen och uppmärksammar krigare i frontlinjen som svarar på kallelsen att hjälpa Frostwolf Clan. Genom hans prövningar visar kämparna sitt mod och vinner Horde-förtruppens respekt.",h="Warmaster Laggrond är en erfaren orcisk befälhavare stationerad utanför Horde-entrén till Alterac Valley i...",kw={"alterac mountains","alterac valley","frostwolf","laggrond","proving grounds","pvp","stormpike","warmaster laggrond"},ang={["class:Warrior"]="Laggrond värdesätter oräddhet i frontlinjen och prövar blivande förkämpar för att försäkra sig om att de kan hålla stånd mot tung dvärgrustning och anfall från förtruppen.",["faction:Horde"]="Warmaster Laggrond är din första kontakt i krigsinsatsen i Alterac Valley och erkänner dina insatser på slagfältet på Frostwolf Clans vägnar.",["race:Orc"]="För orcer är det en fråga om arv att hörsamma Laggonds kallelse och försvara Frostwolf Clans urgamla tillflyktsort mot dvärgarnas intrång."},sec={{t="Befälhavare vid frontlinjen",b="Warmaster Laggrond håller vakt i den bitande kylan vid gränsen till Alterac Valley och organiserar Hordes krigsinsats mot Stormpike Expedition. Han ser till att bara dugliga kämpar går in i dalen för att representera Frostwolf Clan och den större Horden."},{t="Hederns väg",b="Laggrond prövar anländande stridskämpar på Proving Grounds innan han skickar dem in i stridens hetta. När krigare spiller blod över de frusna topparna är det Laggrond som bedömer deras ställning och skänker hedersbetygelser till dem som vinner ryktbarhet bland Frostwolves."}},faq={{q="Var finns Warmaster Laggrond?",a="Warmaster Laggrond är stationerad nära Hordes läger vid portalens ingång till Alterac Valley, högt uppe i de snöiga passen i Alterac Mountains norr om Hillsbrad Foothills.",al={"laggronds plats","var finns laggrond","warmaster vid ingången till alterac valley"}},{q="Vilken roll har Warmaster Laggrond?",a="Han tjänstgör som rekryteringsofficer för Hordes krigsinsats i Alterac Valley. Han bedömer rekryter genom inledande stridsprövningar och belönar dem som uppnår anseende hos Frostwolf Clan.",al={"vad gör laggrond","laggronds syfte","varför prata med laggrond"}},{q="Vad är uppdraget Proving Grounds?",a="Laggrond ber potentiella rekryter att hämta en Frostwolf Banner från Wildpaw Den i Alterac Valley. Det visar deras påhittighet innan de ansluter sig till fälttåget.",al={"proving grounds för horden","laggronds första uppdrag"}},{q="Varför strider Horden i Alterac Valley?",a="Frostwolf Clan har länge gjort anspråk på dalen som sitt hem efter att ha förvisats under det första kriget. Stormpike Guard, en expedition med dvärgar från Alliansen, har trängt in i området på jakt efter reliker och territorium, vilket har utlöst ett bittert territoriellt krig.",al={"varför alterac valley","frostwolf-kriget","konflikten i alterac valley"}},{q="Kan spelare från Alliansen interagera med Warmaster Laggrond?",a="Nej. Warmaster Laggrond är en hängiven förkämpe för Horden och anfaller alla inkräktare från Alliansen som närmar sig hans utpost i bergen.",al={"kan alliansens spelare prata med laggrond","laggrond fientlig"}}},fx={["050e2655"]={q="Vem är Warmaster Laggrond?",a="Warmaster Laggrond är en orc-officer stationerad vid ingången till Alterac Valley, i de snöiga trakterna av Alterac Mountains. Han tjänar Frostwolf Clan och Hordens krigsinsats i stort. Han bedömer anländande hjältar och skickar dugliga soldater till striden mot Stormpike-dvärgarna.",al={"vem är laggrond","warmaster laggrond i berättelsen","laggrond i alterac"}},ccc612bb={q="Vems sida står Warmaster Laggrond på?",a="Laggrond står fast på Hordens sida och företräder särskilt Frostwolf Clans intressen. Han ser Alliansen, i synnerhet den framryckande Stormpike Expedition, som inkräktare på Frostwolf-folkets urgamla territorium.",al={"tillhör laggrond horden","warmaster laggronds fraktion","laggrond, alliansen eller horden"}},["29764588"]={q="Vad vill Warmaster Laggrond?",a="Laggrond söker orubbliga hjältar som är villiga att bevisa sig i den hårda konflikten i Alterac Valley. Han vill försvara Frostwolf-länderna, krossa dvärgarnas expedition och låta Hordens kämpar vinna anseende och ära bland klanen genom blod och plikt.",al={"vad vill laggrond","laggronds mål","laggronds målsättning"}},b3dc84d2={q="Varför är Warmaster Laggrond här?",a="Laggrond är stationerad precis utanför portalen till dalen och fungerar som grindvakt och rekryterare till fronten. Han granskar dem som svarar på Frostwolves vapenrop och ser till att bara beslutsamma kämpar bär klanens baner in i striden.",al={"varför är laggrond i alterac","laggronds plats och syfte","varför är warmaster laggrond här"}},["6fc2678d"]={q="Vilka band har Warmaster Laggrond?",a="Laggrond lyder Frostwolf Clans ledarskap och strider på uppdrag av General Drek'Thar och Hordens styrkor, som är fast beslutna att hålla Alterac Valley mot dvärgarnas utgrävningar och erövringsförsök.",al={"laggronds band","laggrond och frostwolf","vem arbetar laggrond för"}}},fp="18,212,19.212.0,17.224.0,36.166.0,34.148.0,34.185.0,44.236.0,54.118.0"}
P.entries["npc:warsong-outrider"] = {n="Warsong Outrider",s="Warsong Outrider är posterad längs den omstridda vägen österut från Ashenvale till Azshara och håller uppsikt över Hordens gräns. Hon tjänstgör som framskjuten spejare åt Warsong-klanen, bevakar resande och rapporterar viktiga underrättelser till klanens främre läger. Även om hon är beväpnad och vaksam mot intrång från Night Elf håller hon sig avvaktande om hon inte provoceras direkt.",h="Warsong Outrider är posterad längs den omstridda vägen österut från Ashenvale till Azshara och håller uppsikt...",kw={"ashenvale","azshara","hordens spejare","outrider uppdatering","warsong-klanen","warsong outrider"},ang={["faction:Alliance"]="Trots att hon är en fiendesoldat håller den här spejaren inne med elden mot alliansresande om hon inte provoceras, så försiktiga äventyrare kan passera ostörda.",["faction:Horde"]="Spejare som hon håller de bräckliga försörjnings- och spaningslederna vid liv mellan Ashenvales omstridda timmerverksamhet och Azsharas vilda kuster."},sec={{t="Ögon på den östra gränsen",b="Gränstrakterna mellan Ashenvale och Azsharas krossade ruiner är fyllda av faror. Långt från den befästa tryggheten i Splintertree Post och timmerlägren håller Warsong Outrider uppsikt över truppförflyttningar och patrullerar genomfartsleden. Beväpnad med en båge och giftiga gaddar är hon redo att försvara Hordens anspråk på området, men sparar sina krafter och skjuter bara på alliansinbrytare som aktivt angriper henne."}},faq={{q="Var hittar man Warsong Outrider?",a="Hon är posterad längs huvudvägen i östra Ashenvale, som leder direkt in i grannområdet Azshara.",al={"outrider plats","var finns warsong outrider","warsong outrider karta"}},{q="Angriper Warsong Outrider alliansspelare så fort hon ser dem?",a="Nej. Trots att hon är markerad för PvP-strid på Hordens sida är hon neutral mot alliansspelare som passerar och slåss bara i självförsvar om hon blir angripen först.",al={"är hon aggressiv","angriper warsong outrider alliansen","warsong outrider aggro"}},{q="Vilken roll har hon i Warsong-klanens verksamhet?",a="Hon agerar gränsspejare och håller uppsikt över gränsen mellan Ashenvale och Azshara, observerar hot och rapporterar till fältet via spejare som för uppdateringar vidare till klanens ledning.",al={"vad gör outrider","warsong outriders syfte","varför är hon här"}},{q="Ger det någon skatt att besegra Warsong Outrider?",a="Nej, hon lämnar inget byte eller särskild utrustning efter sig. Att besegra henne tjänar bara till att röja vägen eller störa Hordens spaning i området.",al={"warsong outrider byte","släpper hon byte","outrider byte"}}},fx={["472f02e2"]={q="Vem är Warsong Outrider?",a="Hon är en orc-spejare i Warsong Clan, stationerad vid Ashenvales avlägsna östgräns. Med båge och dödliga stick håller spejare som hon vaksam uppsikt över gränserna mellan de omstridda skogarna och de steniga markerna bortom.",al={"vem är warsong outrider","warsong outriders identitet","vad är warsong outrider"}},adb29283={q="Vems sida står Warsong Outrider på?",a="Hon har svurit direkt trohet till Warsong Clan och är lojal mot Horden. Hon tillhör Horden men håller vakt längs vägen i stället för att aktivt jaga förbipasserande resenärer, såvida hon inte blir provocerad.",al={"warsong outriders fraktion","tillhör warsong outrider horden","warsong outriders sida"}},["0609b6c9"]={q="Varför är Warsong Outrider stationerad här?",a="Hon vakar över den viktiga färdvägen som förbinder östra Ashenvale med Azshara. Hennes post ser till att hordens budbärare, timmerkaravaner och resenärer kan rapportera förändringar längs gränsen och lämna viktiga underrättelser om rörelser i regionen.",al={"varför är warsong outrider här","warsong outriders plats och syfte","varför är hon på vägen"}},["38bf0594"]={q="Vilka band har Warsong Outrider?",a="Hon tjänar Warsong-klanen och samordnar sig med dess omfattande avverkning och militära fälttåg i Ashenvale. Hennes rapporter håller klanens utposter informerade om vad som händer i territoriets ytterområden.",al={"warsong outriders band","vem arbetar warsong outrider för","warsong outriders klan"}}},fp="16,231,28.276.0,40.73.0,59.80.0,50.135.0,55.116.0"}
P.entries["npc:watch-captain-parker"] = {n="Watch Captain Parker",s="Guard Parker är en vaksam stadsvakt stationerad vid utposten Three Corners i Redridge Mountains. Han patrullerar vägarna och håller uppsikt över aggressiva gnollflockar. Där utgör han ett första försvar för resenärer på väg till Lakeshire.",h="Guard Parker är en vaksam stadsvakt stationerad vid utposten Three Corners i Redridge Mountains.",kw={"darcy","gnoller","guard parker","lakeshire","parker","redridge","three corners","watch captain parker"},ang={["faction:Alliance"]="Parker visar hur ansträngt och ensamt gränsförsvaret är för en allians som inte kan avvara trupper för att skydda sina egna gränser.",["profession:Herbalism"]="Parkers sökande efter färska blommor åt Darcy visar hur mycket den lokala floran som blommar på Redridge-sluttningarna kan betyda i det stilla.",["race:Human"]="För rikets människor påminner Parker om de vanliga vaktposter som försöker hålla rikets avlägsna byar samman under en nationell kris."},sec={{t="Vakt vid Three Corners",b="Vid den viktiga vägkorsningen Three Corners håller Parker uppsikt över vägarna mellan Elwynn Forest, Duskwood och Redridge. Stormwinds militära resurser är hårt ansträngda och få officiella förstärkningar når området. Därför bär ensamma vaktposter som Parker ansvaret för att hålla korsningen fri från banditer, rovdjur på jakt och plundrande gnoller."},{t="Bedöma gnollhotet",b="Parker oroar sig främst för gnolläger som samlas norr och öster om hans postering. När flockarna närmar sig vägen skickar han stridsdugliga resenärer till Deputy Feldon i Lakeshire för att rapportera om den växande gnollstyrkan. Redridge-flockens allt större fräckhet hotar omedelbart försörjningskonvojer och flyktingar som söker skydd i Lakeshire."},{t="En värmande gest",b="Livet vid en enslig vägpost kan vara dystert, men små vänligheter hittar ändå fram till Three Corners. Darcy, som arbetar på Lakeshire Inn, skickar en varm lunch till Parker medan han är ute och patrullerar. Rörd av gesten ber Parker The Adventurer, som levererade lunchen, att hämta en bukett hos Lakeshires örtkunniga och lämna den till Darcy som tack. Han vill inte att örtkunniga ska få veta vem blommorna kommer från eller vem de är till."}},faq={{q="Var finns Guard Parker?",a="Parker är stationerad vid Three Corners, en vägkorsning i sydvästra Redridge Mountains nära gränsövergångarna till Duskwood och Elwynn Forest.",al={"parkers plats","var finns parker","hitta guard parker"}},{q="Varför är Parker stationerad så långt bort vid Three Corners?",a="Han ska patrullera de södra vägarna och hålla uppsikt över gnollflockar som närmar sig, så att resor och försörjningsrutter till Lakeshire förblir öppna.",al={"parkers uppgifter","varför är parker ensam","vakten vid three corners"}},{q="Vilka hot bevakar Parker i Redridge?",a="Parker håller koll på Redridge-gnollflocken som närmar sig och hotar landsvägen. Samtidigt är han uppmärksam på de större farorna i området, däribland Blackrock-orcher vid Stonewatch och Shadowhide-gnoller nära Tower of Ilgalar.",al={"hot i redridge","vilka fiender finns nära parker","gnollhotet i redridge"}},{q="Vilken relation har Parker till Darcy?",a="Darcy arbetar på Lakeshire Inn och skickar en varm lunch till Parker vid hans avlägsna postering. Som tack låter Parker resenären som kom med maten hämta blommor åt henne hos byns örtkunniga, för att visa sin tacksamhet och tillgivenhet.",al={"darcy och parker","vem är darcy","berättelsen om uppdraget med gratis lunch"}},{q="Varför får Parker inga förstärkningar från Stormwind?",a="Kung Varian Wrynn är försvunnen och huvudstaden har fastnat i politisk handlingsförlamning. Stormwind har i stort sett lämnat Redridge åt sitt öde, så de lokala vakterna och magistraterna måste förlita sig på kringvandrande äventyrare.",al={"varför finns ingen stormwind-armé","stormwinds hjälp till redridge","förstärkningar till parker"}},{q="Vilka uppdrag erbjuder Guard Parker?",a="Parker ber äventyrare rapportera om gnollägren som samlas nära vägen till Deputy Feldon i Lakeshire. Han ordnar också så att färska blommor levereras till Darcy på Lakeshire Inn.",al={"parkers uppdrag","uppdrag från parker"}}},fx={bec4d61f={q="Vem är Watch Captain Parker?",a="Parker är en trogen medlem av Lakeshires stadsvakt och har i uppgift att hålla uppsikt över vägarna mot Redridge Mountains. Han är stationerad vid Three Corners, där vägarna mellan Elwynn, Duskwood och Redridge möts, och patrullerar de avlägsna vägarna för att bevaka fiendens rörelser och skydda resenärer på väg mot Lakeshire.",al={"vem är guard parker","vem är parker","watch captain parker"}},fd65fed3={q="På vems sida står Watch Captain Parker?",a="Han är lojal mot kungariket Stormwind och tjänar samhället Lakeshire som en del av den lokala vakten i Redridge. Han är redo att hjälpa alla allianshjältar som vill försvara den hårt ansatta regionen mot fientliga gnoller och orcher.",al={"parkers fraktion","är parker med i alliansen","vem tjänar parker"}},["39103803"]={q="Vad vill Watch Captain Parker?",a="Parker vill hindra de framryckande gnollerna från att inta den viktiga vägkorsningen och tränga djupare in i Redridge. Omgiven av fientliga styrkor söker han dugliga äventyrare som kan spana i vildmarken, driva bort gnollflockarna och återvända med lägesrapporter till sina överordnade i Lakeshire.",al={"parkers mål","vad behöver parker","parkers motiv"}}},fp="20,213,25.297.0,26.279.0,17.365.0,30.139.0,57.150.0,46.155.0,41.221.0,57.187.0,36.182.0"}
P.entries["npc:watcher-backus"] = {n="Watcher Backus",s="Längs vägen genom Duskwood håller Watcher Backus utkik efter faror och misstänkt trafik med koppling till Stormwinds politiska intriger. Han patrullerar mellan Darkshire och Manor Mistmantle och spanar efter odöda och märkliga resenärer.",h="Längs vägen genom Duskwood håller Watcher Backus utkik efter faror och misstänkt trafik med koppling till...",kw={"backus","darkshire","duskwood","manor mistmantle","night watch","the missing diplomat","watcher backus"},ang={["faction:Alliance"]="För Alliansens agenter som spårar en försvunnen diplomat är Backus en viktig kontakt med information från frontlinjen.",["race:Human"]="Som människa visar Backus den okuvliga styrkan hos Duskwoods försvarare, övergivna av huvudstaden men fast beslutna att hålla vägarna."},sec={{t="En patrull i skuggorna",b="Watcher Backus går ensam sin runda norr om Darkshire, förbi Manor Mistmantle. Liksom resten av Night Watch kämpar han mot Duskwoods förbannelse. Stormwinds garnison ger regionen föga stöd, så lokala frivilliga vaktar dess dimhöljda stigar på egen hand. Backus håller bestar och gastar borta från vägen."},{t="Ögon på vägen",b="Från sin avskilda rutt ser Watcher Backus mycket av trafiken som passerar runt Darkshire. När kungliga utredare följer spåren efter en högt uppsatt diplomats försvinnande söderut minns han märkliga aktiviteter från Defias kring Addle's Stead."}},faq={{q="Vem är Watcher Backus?",a="Watcher Backus är en mänsklig vakt i det hårt ansatta Night Watch, milisen som försvarar Darkshire och vägarna genom Duskwood.",al={"vem är backus","watcher backus roll","backus duskwood"}},{q="Var kan man hitta Watcher Backus?",a="Watcher Backus patrullerar huvudvägen norrut från Darkshire mot Manor Mistmantle i Duskwood.",al={"var är backus","backus plats","backus patrullrutt"}},{q="Vad är Night Watch?",a="Night Watch är en lokal frivilligmilis som bildats av Duskwoods invånare för att försvara sig mot odöda, worgen och vilda bestar efter att Stormwind dragit tillbaka sin officiella militära närvaro.",al={"vad är night watch","night watch duskwood","darkshires vakter"}},{q="Hur är Backus inblandad i The Missing Diplomat?",a="Under sökandet efter en försvunnen diplomat från Stormwind leder ledtrådar äventyrarna till Duskwood. Watcher Backus minns nylig aktivitet från Defias kring Addle's Stead och hjälper till att undersöka dokument som hittats i deras gömställe där.",al={"backus försvunnen diplomat","uppdraget missing diplomat backus"}},{q="Går det något skvaller om Watcher Backus i byn?",a="Darkshires vaktkollega Watcher Brownell sägs hysa en outtalad förälskelse i Backus, ett sällsynt inslag av lättsamt byskvaller mitt i allt elände.",al={"backus brownell","watcher brownells förälskelse"}},{q="Varför patrullerar Backus ensam nära Manor Mistmantle?",a="Night Watch är hårt ansträngt över hela området, så det finns få arbetsföra försvarare att avvara. Vakter som Backus måste ensamma ta hand om långa och farliga patrullrutter.",al={"varför ensam","backus fara"}}},fx={cd7ae440={q="På vems sida står Watcher Backus?",a="Watcher Backus står helt och hållet på Night Watchs och Darkshires hårt ansatta invånares sida. Som en av Duskwoods hängivna lokala försvarare tjänar han Alliansen och lyder under stadens ledning. Dag och natt trotsar han de skuggiga vägarna för att skydda resenärer och invånare mot de glupska fasor som stryker omkring i mörkret.",al={"backus fraktion","vem tjänar watcher backus","watcher backus lojalitet"}},f48ed911={q="Vad vill Watcher Backus?",a="Backus vill hålla Duskwoods vägar säkra och skipa rättvisa i ett land som övergivits av Stormwinds armé. När resenärer eller utredare för med sig problem till honom fokuserar han på att rensa bort farliga misstänkta, hålla sin patrullväg fri från odöda och se till att Darkshires hårt ansatta folk överlever.",al={"watcher backus mål","vad försöker backus göra","backus motiv"}},["8919f8c2"]={q="Vilka band har Watcher Backus?",a="Förutom sina kamrater i Night Watch, som patrullerar de dystra skogarna vid hans sida, har Backus fångat uppmärksamheten hos vakten Watcher Brownell, som uppenbart är förälskad i honom. Han samordnar sig också med agenter som undersöker misstänkt aktivitet längs vägarna, vilket knyter honom direkt till större utredningar som rör Stormwind.",al={"watcher backus kontakter","vem känner watcher backus","watcher backus relationer"}}},fp="14,221,23.298.0,16.228.1,22.119.0,34.94.0,24.184.0,49.220.1,57.148.0,51.176.0"}
P.entries["npc:watcher-dodds"] = {n="Watcher Dodds",s="Watcher Dodds är en mänsklig spejare i Night Watch, stationerad vid den centrala vägkorsningen i Duskwood. Från en enslig vägpost långt från Darkshires stadsmurar håller han uppsikt över de annalkande fasorna och ber resenärer att minska den lokala jättespindelpopulationen.",h="Watcher Dodds är en mänsklig spejare i Night Watch, stationerad vid den centrala vägkorsningen i Duskwood.",kw={"althea ebonlocke","vägkorsning","darkshire","duskwood","night watch","spindlar","watcher dodds"},ang={["faction:Alliance"]="För alliansresenärer som färdas genom Duskwood är Dodds lägereld en av de få trygga platserna med vänligt stöd längs de mörka vägarna mellan Darkshire och de västra länderna."},sec={{t="Vakt vid vägskälet",b="Watcher Dodds tjänar Night Watch under Commander Althea Ebonlocke och håller en utsatt post vid korsningen mellan Darkshire, Raven Hill och Deadwind Pass. Medan Darkshire håller sig innanför palissaderna lever framskjutna vakter som Dodds på gränsen mellan vargflockar, glupska gastar och jättelika spindeldjur. Från sitt läger vid vägen håller han utkik efter hot som närmar sig och anlitar kringvandrande legosoldater för att minska antalet spindlar som kryper fram ur snåren, innan de helt tar över de igenvuxna vägarna."}},faq={{q="Vem är Watcher Dodds?",a="Han är en mänsklig medlem av Night Watch, den milis som bildades för att försvara Duskwood mot de odöda och bestar som plågar regionen. Han är stationerad vid den centrala vägkorsningen, inte innanför Darkshires trygga gränser.",al={"watcher dodds","vem är dodds","dodds duskwood"}},{q="Var hittar jag Watcher Dodds?",a="Dodds har ett litet läger vid huvudkorsningen i centrala Duskwood, där vägarna mellan Darkshire, Raven Hill och de södra passen delar sig.",al={"watcher dodds plats","var finns dodds","dodds koordinater"}},{q="Varför vill han att spindlar ska dödas?",a="Giftiga jättespindlar hemsöker skogarna i trakten och jagar kringvandrande resenärer och kurirer med förnödenheter som färdas längs vägen. Dodds förlitar sig på äventyrare som passerar för att hålla antalet giftspindlar nere och hindra stigarna från att bli helt oframkomliga.",al={"åttabenta plågor","dodds spindeluppdrag","varför döda spindlar"}},{q="Vem rapporterar Watcher Dodds till?",a="Han lyder under Commander Althea Ebonlocke, ledaren för Night Watch, vars högkvarter ligger i stadshuset i Darkshire.",al={"dodds befälhavare","vem leder night watch"}}},fx={["06158fc1"]={q="På vems sida står Watcher Dodds?",a="Watcher Dodds tjänar Night Watch, den ståndaktiga milis som försvarar den hårt ansatta staden Darkshire och Duskwoods vägar. Därigenom är han lojal mot Duskwoods folk och den stora alliansen. Han står fast mot skuggorna när Stormwinds officiella garnison inte kan avvaras för att hjälpa dem.",al={"dodds fraktion","watcher dodds lojalitet","vem kämpar dodds för"}},["7998837a"]={q="Varför är Watcher Dodds stationerad vid vägkorsningen?",a="Watcher Dodds upprätthåller en utpost vid Duskwoods huvudsakliga vägkorsning för att hålla de viktiga färdvägarna öppna. Eftersom han saknar större förstärkningar bevakar han vildmarken och rekryterar dugliga resenärer för att hejda de rovgiriga fasor som hotar alla som färdas utanför Darkshires omedelbara närhet, särskilt jättespindlar och annalkande bestar.",al={"varför är dodds här","varför är watcher dodds här","varför slår dodds läger här"}}},fp="13,185,23.459.0,21.208.0,31.159.0,32.217.0,33.106.0"}
P.entries["npc:wilder-thistlenettle"] = {n="Wilder Thistlenettle",s="Wilder Thistlenettle är en dvärgbrytare som grubblar på en krog i Stormwinds Dwarven District. Han är den enda överlevande efter ett tragiskt ras djupt inne i The Deadmines, och hemsöks av sitt gruvlags och sin brors fasansfulla öde.",h="Wilder Thistlenettle är en dvärgbrytare som grubblar på en krog i Stormwinds Dwarven District.",kw={"bror","ras","the deadmines","dwarven district","gruvarbetare","stormwind","thistlenettle","wilder"},ang={["profession:Mining"]="Gruvarbetare känner väl till farorna i djupa ådror under jord, där instabil mark och bortglömd mörk magi kan begrava även rutinerade arbetslag.",["race:Dwarf"]="För dvärgars släkt väcker Wilders sorg välbekant genklang och påminner om de ständiga farorna med gruvdrift under jord och den heliga plikten att hedra fallna bröder i skrået."},sec={{t="En bitter överlevare",b="Wilder Thistlenettle kan hittas när han dränker sina sorger i en ölpub nära Dwarven Districts sydöstra portar. För flera år sedan gav han sig ut på en expedition till Moonbrooks djupa malmgångar i The Deadmines, tillsammans med sin bror och deras följeslagare. Ett katastrofalt ras stängde in resten av besättningen i mörkret, medan Wilder nätt och jämnt lyckades ta sig upp till ytan med livet i behåll."},{t="Djupets gastar",b="Katastrofen i tunnlarna slutade inte med fridfull vila. Wilder fick så småningom veta att hans bror och det förlorade gruvlaget inte bara omkom i rasmassorna – mörk magi eller oavslutade angelägenheter har väckt dem till liv som rastlösa odöda, som ständigt hemsöker ruinerna under jorden. Förtärd av sorg och överlevnadsskuld söker Wilder modiga äventyrare som vågar sig in i The Deadmines för att återfinna minnessaker från de fallna och skänka hans bror den slutliga friden."}},faq={{q="Var kan jag hitta Wilder Thistlenettle?",a="Han sitter på en stillsam pub i Stormwind Citys Dwarven District, strax innanför distriktets sydöstra ingång, på höger sida.",al={"wilder thistlenettle plats","var finns wilder","thistlenettle stormwind"}},{q="Vad hände med hans bror i The Deadmines?",a="Wilders bror blev instängd i en plötslig tunnelkollaps tillsammans med de andra gruvarbetarna. Wilder flydde och söker nu besked om dem som lämnades där nere.",al={"wilders bror deadmines","vad hände med brodern","thistlenettles brors historia"}},{q="Varför behöver Wilder äventyrare?",a="Wilder ber resande som ska in i The Deadmines att hämta personliga märken från gruvfacket åt de försvunna arbetarna och undersöka vad som hände med hans bror.",al={"wilders uppdrag","vad vill wilder","uppdrag samla minnen"}}},fx={["2e3a3cea"]={q="Vem är Wilder Thistlenettle?",a="Wilder Thistlenettle är en dvärgbrytare som just nu dricker bort sina sorger i Dwarven District i Stormwind City. Han deltog i en gruvexpedition till The Deadmines tillsammans med sin bror, men en tragedi inträffade djupt under marken.",al={"vem är wilder","wilder thistlenettles bakgrund","om wilder thistlenettle"}},cb45d77d={q="På vems sida står Wilder Thistlenettle?",a="Wilder är lojal mot Alliansen och sina dvärgsläktingar. Han tillbringar dagarna grubblande på en tom krog i Stormwind och söker hjälp från betrodda alliansäventyrare som vågar sig in i The Deadmines.",al={"wilder thistlenettles fraktion","vem arbetar wilder för","är wilder med i alliansen"}},cf83a843={q="Varför är Wilder Thistlenettle här i Stormwind?",a="Efter att med knapp nöd ha undkommit ett katastrofalt ras i The Deadmines, där hans bror och besättning omkom, flydde Wilder tillbaka till tryggheten i Stormwind City. Traumatiserad och förkrossad av sorg tog han sin tillflykt till en lugn krog i Dwarven District.",al={"varför är wilder i stormwind","varför är wilder här","varför är wilder i dwarven district"}}},fp="20,206,17.304.0,18.299.1,38.127.0,46.125.0,33.152.0"}
P.entries["npc:wiley-the-black"] = {n="Wiley the Black",s="På Lakeshire Inn håller sig Wiley the Black undan. Han har Gryan Stoutmantle att tacka för sitt liv och delar med sig av det han vet om Defias Brotherhood.",h="På Lakeshire Inn håller sig Wiley the Black undan.",kw={"defias","gryan stoutmantle","informatör","lakeshire","redridge","wiley","wiley the black"},ang={["class:Rogue"]="Som skurk visar Wiley hur yrkesknep och underrättelser kan hålla någon vid liv. Han vet när han ska byta information och vem han står i skuld till.",["faction:Alliance"]="Eftersom Stormwinds armé är frånvarande förlitar sig Alliansen på inofficiella kontakter som Wiley för att få ihop bilden av upproret i Westfall."},sec={{t="En skurks skuld",b="Wiley the Black håller sig till Lakeshire Inn, långt från oron i Westfall och gränstrakterna i Redridge, där det kryllar av gnoller. Han har Gryan Stoutmantle, befälhavare för People's Militia, att tacka för sitt liv; Stoutmantle räddade honom en gång. Stoutmantle muttrar att han borde ha låtit Wiley ruttna. När milisen behöver insikt i Defias-konspirationen vänder den sig till Wiley. Motvilligt delar han med sig av hemlig information för att betala tillbaka sin skuld."}},faq={{q="Var hittar jag Wiley the Black?",a="Wiley the Black är inne på Lakeshire Inn i staden Lakeshire, i Redridge Mountains.",al={"wiley plats","var är wiley the black","wiley redridge","wiley lakeshire inn"}},{q="Varför hjälper Wiley Gryan Stoutmantle?",a="Gryan Stoutmantle räddade en gång Wileys liv. Wiley betalar tillbaka skulden genom att dela information om Defias Brotherhood, trots att han ogärna sticker ut hakan.",al={"varför hjälpa gryan","wiley gryan relation","wiley stoutmantle skuld"}},{q="Hur känner Wiley till Defias Brotherhood?",a="Wiley känner undre världen och Defias verksamhet väl. Han delar med sig av det han vet för att betala tillbaka sin skuld till Gryan Stoutmantle, men det är obekräftat om han en gång tillhörde brödraskapet.",al={"är wiley defias","hur känner wiley till defias","wileys koppling till defias"}},{q="Vilken roll har han i utredningen av Defias?",a="När People's Militia hittar ledtrådar till en större konspiration skickar Stoutmantle äventyrare till Lakeshire med ett meddelande till Wiley. Wiley undersöker situationen och skriver en lapp som visar milisen mot upprorets ledare.",al={"wileys roll i uppdrag","vad gör wiley","defias brotherhood wiley"}}},fx={["03fe7b6d"]={q="Vem är Wiley the Black?",a="Wiley the Black är en skum skurk som för närvarande bor på värdshuset i Lakeshire. Han är känd som en skojare med olagliga kontakter och har förvånansvärt ingående kunskaper om Defias Brotherhood och deras hemliga verksamhet i människorikena.",al={"vem är wiley","wiley the blacks bakgrund","om wiley the black"}},["7107b7b4"]={q="På vems sida står Wiley the Black?",a="Wiley tänker främst på sig själv och håller sig på avstånd från Alliansens officiella politik. Men eftersom Gryan Stoutmantle en gång räddade hans liv är Wiley villig att betala tillbaka sin personliga skuld genom att hjälpa Folkets milis mot Defias.",al={"är wiley lojal mot alliansen","wiley the blacks fraktion","wiley the blacks lojalitet"}},["72fbb4af"]={q="Vad vill Wiley the Black?",a="Wiley vill göra upp sin skuld till Gryan Stoutmantle och hålla sig borta från trubbel. Genom att lämna viktiga underrättelser om Defias Brotherhood uppfyller han sin förpliktelse mot Gryan och kan betala tillbaka sin skuld på tryggt avstånd från striderna i Westfall.",al={"vad vill wiley","wiley the blacks mål","varför hjälper wiley"}},["9b688ede"]={q="Varför är Wiley the Black i Redridge?",a="Wiley har tagit in på ett rum en trappa upp på Lakeshire Inn, långt från Westfall och Stormwinds myndigheters direkta räckhåll. I Redridge kan han hålla en låg profil och samtidigt hålla öronen öppna.",al={"varför är wiley i lakeshire","varför är wiley här","wiley i redridge"}}},fp="15,151,18.384.0,33.91.0,39.152.0,49.173.0,51.234.0"}
P.entries["npc:willem"] = {n="Willem",s="Utanför Northshire Abbey skickar Willem rekryter för att möta hoten i dalen. Han tjänstgör under Marshal McBride i Stormwind Army, medan Defias Brotherhood tränger in i Northshire.",h="Utanför Northshire Abbey skickar Willem rekryter för att möta hoten i dalen.",kw={"defias","deputy willem","elwynn forest","garrick padfoot","marshal mcbride","northshire","northshire abbey","willem"},ang={["class:Warrior"]="Som krigare kan du ställa din styrka till Willems förfogande, driva bort banditer och återställa ordningen i riket.",["faction:Alliance"]="Som medlem av Alliance kan du genom Willem se hur oroligheterna kring Defias når ända in i Elwynns fridfulla hjärtland.",["race:Human"]="Som människa som lämnar Northshire Abbey kan du möta Deputy Willem, en av de första Stormwind-officerarna som välkomnar dig i rikets tjänst."},sec={{t="En väktare vid klostret",b="Deputy Willem bevakar portarna till Northshire Abbey, där Stormwind Army håller ett fäste i dalen. Rikets soldater är spridda över många områden, så det lokala försvaret ligger på små grupper som Marshal McBrides garnison. Willem möter anländande frivilliga och skickar dem för att hjälpa invånarna och bevaka dalens utkanter."},{t="Kampen mot Defias",b="Defias Brotherhood är Willems mest trängande bekymmer. Banditer med röda bandanas har tagit sig in i Northshire, stulit förnödenheter, hotat bonden Milly Osworth och skaffat sig fästen bland närliggande vingårdar och kullar. Willem utlyser belöningar för kända banditer som Garrick Padfoot i hopp om att krossa deras ledarskap innan de kan ta klostrets marker."}},faq={{q="Vem är Deputy Willem?",a="Deputy Willem tjänstgör i Stormwind Army utanför Northshire Abbey i Elwynn Forest. Under Marshal McBride leder han rekryter mot hot i dalen.",al={"vem är willem","deputy willems roll","willem northshire"}},{q="Vem rapporterar Deputy Willem till?",a="Deputy Willem rapporterar till Marshal McBride, som leder försvaret av Northshire Valley och de militära operationerna där.",al={"willems befälhavare","vem är willems chef","willems ledare"}},{q="Varför utfäster Willem belöningar för Defias?",a="Defias Brotherhood har tagit sig in i Northshire Valley, hotar klostret och terroriserar lokala arbetare. Willem skickar kämpar efter banditerna och ledare som Garrick Padfoot för att återställa ordningen.",al={"varför belöning för defias","willem röda bandanas","willem defias"}},{q="Var hittar man Deputy Willem?",a="Willem väntar utanför huvudingången till Northshire Abbey i norra Elwynn Forest, där han hälsar resenärer och rekryter som kommer in på gården.",al={"willems plats","var finns deputy willem","hitta willem"}},{q="Hur hjälper Willem de lokala arbetarna?",a="Willem skickar kämpar för att hjälpa invånare vars försörjning är hotad, däribland fruktodlaren Milly Osworth och pälsjägaren Eagan.",al={"willem milly osworth","willem eagan","willems uppdrag"}},{q="Varför har soldater som Willem svårt att upprätthålla ordningen på egen hand?",a="Stormwind står inför interna påfrestningar, politiska spänningar och militära åtaganden långt borta. Med kung Varian försvunnen måste garnisoner som Northshire förlita sig på oprövade rekryter och frivilliga för att hantera oroligheterna hemma.",al={"varför är stormwind army svagt","varför är northshire oförsvarat","stormwinds manskap i northshire"}}},fx={cea9f32f={q="På vems sida står Deputy Willem?",a="Deputy Willem är en lojal soldat i Stormwinds armé och tjänar Alliansen. Han står vakt utanför Northshire Abbey, upprätthåller kungarikets lagar och hänvisar dugliga rekryter till försvaret av dalen mot stråtrövare och tjuvar.",al={"willems fraktion","vem tjänar deputy willem","willem, alliansen eller horden"}},["29d9c6b5"]={q="Varför är Deputy Willem här i Northshire?",a="Deputy Willem är stationerad utanför Northshire Abbey för att upprätthålla ordningen och hänvisa nya rekryter dit de behövs bäst. Eftersom kungarikets försvar är hårt ansträngt fungerar han som den främsta förbindelselänken för att samordna dalens svar på lokala hot.",al={"varför är willem i northshire","vad förde willem hit","deputy willems uppgift"}}},fp="6,175,23.342.0,22.354.0,21.159.0,33.107.0,45.197.0,33.148.0,41.130.0,62.209.0"}
P.entries["npc:william-pestle"] = {n="William Pestle",s="På Lion's Pride Inn i Goldshire samlar William Pestle förnödenheter åt Stormwinds apotek. Han och hans bror Morgan driver butiken i Trade District, och William anlitar resande för att hitta ljus, kelp och örter.",h="På Lion's Pride Inn i Goldshire samlar William Pestle förnödenheter åt Stormwinds apotek.",kw={"apotek","samla kelp","goldshire","koboldljus","lion's pride inn","maclure","morgan pestle","pestle","stonefield","william pestle"},ang={["faction:Alliance"]="William hjälper till att förse Trade District i Stormwind med läkemedel och andra varor. Han är beroende av rekryter från Alliansen som passerar Goldshire och samlar material i den omgivande skogen.",["profession:Herbalism"]="Som örtletare i Goldshire kan du se hur växtinsamling bidrar till Williams verksamhet. Han förvandlar vilda växter och märklig vattenkelp till användbara blandningar."},sec={{t="Apotekaren på annan ort",b="William arbetar från Lion's Pride Inn i Goldshire medan hans bror Morgan Pestle sköter disken på Pestle's Apothecary i Stormwind Citys Trade District. I Elwynn Forest samarbetar William med lokala samlare för att säkra råvaror som stadens butiker behöver. Han skickar regelbundet leveranser till huvudstaden, där Stormwinds invånare förlitar sig på ett stadigt utbud av läkande salvor, brygder och pulver."},{t="Ovanliga ingredienser",b="William behöver ofta mer än vanliga trädgårdsörter till sitt hantverk. Han anlitar nykomlingar för att samla vaxljus som Elwynns kobolder bär på och kristallkelp från murlocer i Crystal Lake, strax öster om Goldshire. Ingredienserna kan verka märkliga för den som inte känner till alkemi, men William anser att de har kraftfulla egenskaper i en blandning."},{t="En brygd för ung kärlek",b="William är en gammal vän till Mildred Stonefield. När Maybell Maclure och Tommy Joe Stonefield hamnar mitt i sina familjers bittra fejd går William med på att brygga en Invisibility Liquor. Brygden görs på kelp som samlats i vattnen här omkring och låter Maybell smita iväg osedd för att träffa Tommy Joe."}},faq={{q="Vem är William Pestle?",a="William Pestle är en alkemist som arbetar från Lion's Pride Inn i Goldshire. Han och hans bror Morgan samlar in och förbereder förnödenheter åt apoteket i Stormwind City.",al={"william pestle","alkemist i goldshire","vem är pestle"}},{q="Var hittar man William Pestle?",a="William Pestle finns inne på Lion's Pride Inn i Goldshire, i Elwynn Forest.",al={"var finns pestle","var finns william pestle","william pestle i goldshire"}},{q="Vad gör William med koboldljusen?",a="William samlar in vaxljus som kobolder bär med sig i Elwynns gruvor, smälter dem och renar talgen för alkemiska blandningar och apotekets lager.",al={"varför vill pestle ha ljus","vad används koboldljus till"}},{q="Varför behöver William Crystal Kelp?",a="William använder Crystal Kelp från sjöar i Elwynn för att göra en Invisibility Liquor. Den hjälper Maybell Maclure att smita förbi sin familj och träffa Tommy Joe Stonefield.",al={"varför samla kelp","vad används murlockelp till"}},{q="Vilken koppling har William Pestle till Stormwind City?",a="William och hans bror Morgan driver apoteket i Stormwind Citys Trade District. William samlar ingredienser i Goldshire och skickar leveranser till stadsbutiken.",al={"pestle i stormwind","william pestles apotek"}},{q="Hur är William inblandad med familjerna Stonefield och Maclure?",a="William är en gammal vän till Mildred Stonefield. Han brygger en hemlig dryck som hjälper Tommy Joe Stonefield och Maybell Maclure att ta sig runt sina familjers bittra fejd.",al={"stonefield maclure pestle","william pestles kärleksuppdrag"}}},fx={["2d067923"]={q="Vad vill William Pestle ha?",a="William söker sällsynta och ovanliga reagenser till sina alkemiska brygder. Han ber ofta äventyrare på genomresa att samla stora mängder koboldljus för vaxet och kristallkelp från sjöarna i trakten. Ingredienserna använder han i brygder som sitt kraftfulla Invisibility Liquor.",al={"vad behöver william pestle","william pestles mål","william pestles ingredienser"}},["8d6a9bd2"]={q="Varför är William Pestle i Goldshire?",a="William och hans bror Morgan driver ett apotek i Trade District i Stormwind City. William bor på Lion's Pride Inn i Goldshire för att själv samla landsbygdens reagenser och hjälpa gamla vänner som Mildred Stonefield ute på Elwynns landsbygd.",al={"varför är william pestle här","varför är william i goldshire","varför är william pestle på lions pride inn"}},["520b1b0a"]={q="På vems sida står William Pestle?",a="William är en lojal undersåte till kungariket Stormwind och en stolt medlem av Alliansen. Från Lion's Pride Inn tjänar han sitt lokalsamhälle med sina kunskaper i alkemi, brygger läkemedel och hjälper invånarna med deras vardagliga bekymmer.",al={"william pestles fraktion","är william pestle med i alliansen","william pestles lojalitet"}}},fp="14,217,17.362.0,16.322.0,27.292.1,22.167.0,34.87.0,41.154.0,35.157.1,54.164.0,58.160.1"}
P.entries["npc:williden-marshal"] = {n="Williden Marshal",s="Williden Marshal är den ambitiösa mänskliga ledaren för Marshal's Expedition, med bas i Marshal's Refuge i norra Un'Goro Crater. Lockad av sällsynta växter, mystiska kristaller och lönsam vetenskaplig forskning tog han sitt team till kratern, där han fick se hur enorma bestar översvämmade deras lägre läger.",h="Williden Marshal är den ambitiösa mänskliga ledaren för Marshal's Expedition, med bas i Marshal's Refuge i...",kw={"djävulsaurer","marshals expedition","marshals refuge","kraftkristaller","spark nilminer","ungoro crater","williden marshal"},ang={["faction:Alliance"]="Williden och hans närmaste team verkar neutralt av nödvändighet i den vilda kratern, men har starka kulturella och handelsmässiga band till Alliansens kärnländer.",["profession:Herbalism"]="Willidens expedition lockades till Un'Goro till stor del av kraterns unika förhistoriska växtlighet, som inte växer någon annanstans på Azeroth.",["race:Human"]="Williden står för mänsklighetens vidsträckta nyfikenhet och handelsambition. Han har färdats hela vägen från Eastern Kingdoms till södra Kalimdors otämjda djup."},sec={{t="En osäker utpost",b="Williden Marshal tog med sig en hel vetenskaplig expedition djupt in i Un'Goro Crater i jakt på rikedom och upptäckter. Berättelser om främmande kristaller, okatalogiserade växter och outnyttjade resurser väckte hans intresse, och han upprättade flera framskjutna läger på dalens botten. Men den ursprungliga vildmarken vände sig snabbt mot dem. Kraterns vilda bestar ödelade deras forskningsposter och tvingade Williden och de överlevande att dra sig upp till de norra klipporna och upprätta Marshal's Refuge."},{t="Att rädda drömmen",b="Trots att han drevs till kraterns bergiga utkant vägrar Williden att packa ihop och överge sin investering. Från den relativa tryggheten i tillflyktsorten anlitar han äventyrare på genomresa för att ge sig tillbaka ner i de vilda låglanden och hämta förlorade matlådor, dyrbara vetenskapliga instrument och hans personliga expeditionsjournal. Nära kamrater som Spark Nilminer kallar honom ofta bara ”Wil”, men han tar expeditionen på allvar och insisterar på att deras arbete ska återvinnas, medan väldiga rovdjur stryker omkring i dalen nedanför."},{t="Familjeband",b="Williden är inte den enda Marshal i kratern: Hol'anyee Marshal bär samma namn och arbetar tillsammans med honom i Marshal's Refuge. Tillsammans valde de den otämjda, ursprungliga kratern i södra Kalimdor, och Williden är helt övertygad om att Un'Goros kristallfyndigheter och uråldriga mysterier rymmer den verkliga förmögenheten."}},faq={{q="Vem är Williden Marshal?",a="Williden Marshal är en mänsklig upptäcktsresande och ledare för Marshal's Expedition. Han ledde ett team av forskare och äventyrare till Un'Goro Crater för att studera dess märkliga kristaller och växter i jakt på kunskap och vinst.",al={"vem är williden marshal","williden marshals bakgrund","vem leder marshal's refuge"}},{q="Varför håller expeditionen till i en grotta?",a="Expeditionen upprättade ursprungligen flera forskningsbaser nere i Un'Goros lågland. Men expeditionen underskattade Un'Goros vildhet, och kraterns väldiga rovdjur översvämmade platserna, vilket tvingade de överlevande att fly till Marshal's Refuges norra klipphyllor.",al={"varför ligger tillflyktsorten i en grotta","vad hände med expeditionens läger","varför drog sig marshal tillbaka"}},{q="Vad ber Williden äventyrarna att göra?",a="Williden ber dugliga upptäcktsresande att våga sig in i den farliga kraterbäckenet för att hämta förnödenheter från deras förstörda läger, däribland övergivna matförråd, ömtålig forskningsutrustning och hans förlorade expeditionsjournal.",al={"willidens uppdrag","expeditionens räddning","vad vill williden"}},{q="Vad förde Williden till Un'Goro Crater från början?",a="Han kom i jakt på kraterns unika resurser: sällsynta växter, mystiska färgade kraftkristaller, uråldriga geologiska hemligheter och de stora ekonomiska vinster som vetenskapliga upptäckter skulle ge därhemma.",al={"varför kom han till ungoro","williden marshals motiv","vad forskar marshal om"}},{q="Har Williden någon familj?",a="Ja. Hans syster, Hol'anyee Marshal, arbetar tillsammans med honom i Marshal's Refuge som en del av Marshal Expeditions.",al={"willidens bror","livingston marshal","marshal-familjen"}},{q="Tillhör Williden Marshal Alliansen eller Horden?",a="Trots att Williden är människa leder han en neutral vetenskaplig expedition från Marshal's Refuge. Han tar gärna emot hjälp från både Alliansens och Hordens äventyrare som vill återvinna hans förnödenheter och röja undan hot i kratern.",al={"tillhör williden alliansen","kan horden tala med williden","vilken fraktion tillhör marshal refuge"}}},fp="16,328,21.492.0,19.517.0,11.313.0,24.215.0,41.292.0,42.207.0,59.215.0,30.111.0,55.224.0"}
P.entries["npc:winna-hazzard"] = {n="Winna Hazzard",s="Winna Hazzard är en excentrisk Forsaken-forskare som är stationerad vid Bloodvenom Post i Felwood. Hon har sällskap av en katt och är känd för sina maniska skrattattacker. Hon studerar det fördärvade ekosystemet och utför obehagliga experiment med områdets förvridna djurliv.",h="Winna Hazzard är en excentrisk Forsaken-forskare som är stationerad vid Bloodvenom Post i Felwood.",kw={"bloodvenom post","felwood","forsaken","kattunge","winna hazzard"},ang={["faction:Horde"]="Winna är tryggt stationerad vid Bloodvenom Post och ber förbipasserande Horde-resenärer samla in fördärvade ingredienser till hennes bisarra forskning.",["race:Undead"]="Winna förkroppsligar Forsakens mörkare excentricitet. Hon visar en hänsynslös nyfikenhet på fördärv, utan tanke på naturens balans."},sec={{t="En säregen forskare",b="Winna Hazzard representerar Forsakens intresse för Felwoods onaturliga förfall. Hon är stationerad i Horde-enklaven Bloodvenom Post och ägnar sin tid åt att iaktta det lokala djurlivet och planera experiment med förgiftat vatten och giftiga prover. Hennes muntra, maniska uppträdande döljer ofta hänsynslösa motiv. Det märks när hon använder förorenad vätska från marken för att förvrida den lilla kattungen som håller sig vid hennes sida."}},faq={{q="Vem är Winna Hazzard?",a="Winna Hazzard är en Forsaken-uppdragsgivare vid Bloodvenom Post i norra centrala Felwood. Hon undersöker Felwoods fördärvande krafter och ber äventyrare samla in prover från vildmarken.",al={"winna hazzard","vem är winna","kattkvinnan i felwood"}},{q="Vad händer med hennes kattunge?",a="När äventyrare kommer med en flaska fylld med fördärvad vätska från skogarna omkring henne, ger Winna den direkt till sin kattunge. Djuret förvandlas då till en Corrupted Cat, och Winna skrattar maniskt.",al={"winnas kattunge","corrupted cat","kattexperiment i felwood"}},{q="Vad vill Winna Hazzard uppnå i Felwood?",a="Liksom många Forsaken-apotekare och lärda vill Winna förstå och tygla biologiska farsoter. Hon använder Felwoods utbredda fördärv för att studera hur det förändrar och förvrider levande bestar.",al={"winnas motiv","varför är winna i felwood"}}},fp="13,270,21.417.0,21.207.0,27.205.1,40.189.0"}
P.entries["npc:winstone-wolfe"] = {n="Winstone Wolfe",s="Winstone Wolfe är en mänsklig agent med koppling till den hemlighetsfulla organisationen Ravenholdt, stationerad på dess avskilda gods mellan Hillsbrad och Alterac Mountains. Han håller uppsikt över godsets marker och trädgårdsmästare och är en av de betrodda kontakterna i det dolda förbundet av tjuvar och lönnmördare.",h="Winstone Wolfe är en mänsklig agent med koppling till den hemlighetsfulla organisationen Ravenholdt...",kw={"alterac","hillsbrad","ravenholdt","ravenholdt manor","skurk","winstone wolfe"},ang={["class:Rogue"]="Som agent vid Ravenholdt Manor är Wolfe ett välbekant ansikte för skurkar som beger sig upp i bergen för att vässa sina färdigheter med syndikatet."},sec={{t="En fixare i bergen",b="Undangömd i Ravenholdt Manors dolda dal verkar Winstone Wolfe bland medlemmarna i Lord Jorach Ravenholdts syndikat. Wolfe är tystlåten, vaksam och praktisk, och sköter en del av arbetet runt godset. Han ser till att bara de som har gott omdöme och skicklighet kan röra sig ostört på markerna."}},faq={{q="Vem är Winstone Wolfe?",a="Winstone Wolfe är en mänsklig skurk som verkar i Ravenholdt Manor, det avskilda högkvarteret för League of Assassins, högt ovanför Hillsbrad Foothills och Alterac Mountains.",al={"vem är wolfe","winstone wolfe i berättelsen","ravenholdt wolfe"}},{q="Var hittar jag Winstone Wolfe?",a="Han finns i Ravenholdt Manor, som du når via en dold stig som slingrar sig norrut genom bergen från trakten kring Durnholde Keep i Hillsbrad Foothills.",al={"wolfes plats","var finns winstone wolfe","hitta winstone wolfe"}},{q="Vilken roll har han i Ravenholdt?",a="Wolfe fungerar som agent och vakt vid godset. Han håller uppsikt över markerna och hjälper till med syndikatets skumma logistik.",al={"vad gör wolfe","wolfes uppgift"}}},fx={["2ccf77f3"]={q="Vilken sida står Winstone Wolfe på?",a="Winstone Wolfe är knuten till Ravenholdt, det hemlighetsfulla förbundet av tjuvar och lönnmördare som verkar från Ravenholdt Manor. Han håller till i de undangömda bergssluttningarna med utsikt över Hillsbrad och Alterac och tjänar gillet snarare än Alliansen eller Horden.",al={"winstone wolfes fraktion","vem arbetar winstone wolfe för","tillhör winstone wolfe ravenholdt"}},d63e8a08={q="Varför är Winstone Wolfe här?",a="Wolfe verkar från Ravenholdt Manor som en del av det undangömda rövarförbundet i bergen. Oavsett om han bevakar området eller hjälper andra i gillet, stannar han där gillets ärenden sköts.",al={"varför är winstone wolfe vid ravenholdt","varför är winstone wolfe vid ravenholdt manor"}}},fp="14,204,24.245.0,22.169.0,32.152.0,31.140.0"}
P.entries["npc:witch-doctor-jin-zil"] = {n="Witch Doctor Jin'Zil",s="Witch Doctor Jin'Zil är en mystiker bland Darkspear-trollen som bor i en grotta vid Malaka'jin i södra Stonetalon Mountains. Han är sedan länge vapenbroder med Darsok Swiftdagger och skuggjägaren Rokhan, och riktar mörk voodoo och rituell trolldom mot Hordens fiender i trakten.",h="Witch Doctor Jin'Zil är en mystiker bland Darkspear-trollen som bor i en grotta vid Malaka'jin i södra...",kw={"darsok","jin'zil","jinzil","malaka'jin","rokhan","stonetalon","voodoo","häxdoktor"},ang={["faction:Horde"]="Medan Horden säkrar Stonetalon södra leder bidrar Jin'Zil med viktigt ockult försvar och underrättelsestöd tillsammans med utpostens spejare.",["race:Troll"]="Jin'Zil för traditionella häxdoktorseder från Darkspear in i Kalimdors karga vildmark och bevarar sina nära band till framstående personer som Rokhan."},sec={{t="Eremiten i Malaka'jin",b="Jin'Zil håller sig avskild i en grotta i öster ovanför lägret i Malaka'jin och utövar uråldriga djungeltrolls konster långt från stammens hem vid kusten. Omgiven av bubblande kittlar och fångar samlar han exotiska ingredienser från Stonetalon Mountains klippor för att väva kraftfulla välsignelser och förbannelser till försvar för Hordens bergsläger."},{t="En betrodd veteran",b="Jin'Zil är ingen vanlig skogsmagiker. Han delar en lång historia med Hordens högre spejare och räknar både Darsok Swiftdagger och den berömde skuggjägaren Rokhan bland sina gamla vänner. Medan Darsok samordnar strider vid fronten mot nattalver och harpyor, utkämpar Jin'Zil kriget med andlig kraft och alkemi. Han använder skogsmagi och oberäknelig voodoo för att oskadliggöra hot innan de når lägrets portar."}},faq={{q="Var hittar jag Witch Doctor Jin'Zil?",a="Han bor i en grotta på östra sidan av Malaka'jin, en bosättning tillhörande Horden i Stonetalon Mountains södra bergspass.",al={"jin'zils plats","var finns jinzil","jinzils grotta"}},{q="Vilken koppling har Jin'Zil till Rokhan och Darsok Swiftdagger?",a="Jin'Zil är en gammal och betrodd vän till både Darsok Swiftdagger och skuggjägaren Rokhan. Tack vare sina långvariga band förlitar sig spejare i Stonetalon på hans magiska expertis när de möter ovanliga hot.",al={"jin'zils vänner","darsok och jinzil","koppling till rokhan"}},{q="Varför har Jin'Zil fångar i sin grotta?",a="Jin'Zil håller tillfångatagna fiender inlåsta i sin grottverkstad. Som traditionell häxdoktor använder han fångar och råa ingredienser för att pröva förbannelser, tyda omen och skapa defensiv voodoo åt bosättningen.",al={"jinzils fångar","jinzils burar","varför har jinzil fångar"}},{q="Vilka uppgifter ger han Hordens äventyrare?",a="Han skickar resenärer genom Stonetalon för att samla mystiska komponenter till sin skogsmagi, som han använder i sina voodooritualer.",al={"jinzils uppdrag","vad vill jinzil"}}},fx={["3fda7979"]={q="Vem är Witch Doctor Jin'Zil?",a="Witch Doctor Jin'Zil är en mystiker från djungeltrollen i Darkspear som bor i de klippiga kullarna i Stonetalon Mountains. Han håller till i en mörk grotta med utsikt över bosättningen Malaka'jin. Där utför han djupa voodooritualer och brygger kraftfull skogsmagi, och bidrar med sitt uråldriga hantverk och sin andliga klarsyn i Hordens strider vid gränsen.",al={"vem är jinzil","jin'zils bakgrund","vem är witch doctor jinzil"}},["088a369a"]={q="Vilken sida står Witch Doctor Jin'Zil på?",a="Jin'Zil står stadigt på Hordens sida och har särskilt nära band till sina trollfränder i Darkspear och deras allierade, som etablerar fästen i Kalimdor. Han riktar sina magiska ritualer och sitt strategiska stöd till de lokala utposterna och hjälper mästare som sänts genom bergspassen på krigshövdingens uppdrag.",al={"tillhör jinzil horden","witch doctor jinzils fraktion","jinzils lojalitet"}},["6d312970"]={q="Vad vill Witch Doctor Jin'Zil ha?",a="Jin'Zil söker kraftfulla reagenser från Stonetalon, från vilda djur och magiska företeelser, däribland djurdelar som bränsle till sina voodooberlocker och förbannelser. Med dessa bryggda välsignelser vill han stärka Hordens närvaro och säkra bergspassen mot hot som tränger in.",al={"vad vill jinzil ha","jinzils mål","varför samlar jinzil ingredienser"}},["5da55a71"]={q="Varför är Witch Doctor Jin'Zil i Stonetalon?",a="Han har inrättat sitt avskilda näste i Malaka'jin för att iaktta de oberäkneliga andarna och den råa naturmagin i Stonetalon Mountains. Från denna klippiga utpost väver han besvärjelser och håller uppsikt över de södra vägarna. Han ger Hordens spejare som försvarar trakten övernaturlig insikt och förtrollad hjälp.",al={"varför är jinzil i stonetalon","varför är jinzil i malakajin","varför är jinzil här"}}},fp="20,240,24.295.0,17.305.0,38.127.0,62.156.0,44.173.0,53.107.0"}
P.entries["npc:witch-doctor-uzer-i"] = {n="Witch Doctor Uzer'i",s="Witch Doctor Uzer'i är en mystiker bland djungeltrollen som bor i Camp Mojache, i Feralas urskogar. Han vill stärka Hordens magiska förmågor och forskar i metoder för att fånga och utnyttja muisek, den andliga essensen hos mäktiga naturvarelser. Genom att fånga dessa uråldriga skogsandar vill Uzer'i leda nattalvernas råa urkrafter direkt in i förtrollade vapen.",h="Witch Doctor Uzer'i är en mystiker bland djungeltrollen som bor i Camp Mojache, i Feralas urskogar.",kw={"camp mojache","älvdrake","feralas","bergjätte","muisek","neeru fireblade","treant","uzer'i","häxdoktor"},ang={["class:Shaman"]="Schamaner känner igen Uzer'is obevekliga fokus på att kommunicera med andar, även om hans aggressiva fångenskap av elementära och vilda essenser lutar mer åt tvångsmässig häxkonst än vördnadsfull balans.",["faction:Horde"]="Uzer'i ger Horden en väg att bemästra Kalimdors vildmarks urkraft och vända landets andliga kraft mot allierade som nattalverna.",["race:NightElf"]="Nattalverna ser Uzer'is sedvänjor som hädelse och ser med fasa på hur heliga varelser som treanter, hippogryfer och bergsjättar slaktas och binds till vapen.",["race:Troll"]="Uzer'i förkroppsligar trollens klassiska andliga sedvänjor och använder traditionella häxdoktorsriter, krympningskärl och voodoo för att utnyttja livets råa essenser."},sec={{t="Att utnyttja Muisek",b="Med rötter i trollens traditionella andetro har Witch Doctor Uzer'i ägnat mycket tid åt att studera den naturliga magin i Feralas otämjda vildmark. Han hävdar att nattalverna har hämtat kraft ur skogsbestarnas andar i årtusenden och anser att tiden är inne för Horden att ta samma urkrafter i besittning. Centralt i hans forskning står begreppet muisek: den livfulla andliga essens som finns kvar i en varelse. För att fånga den tillverkar Uzer'i särskilda kärl som snabbt kan krympa fallna varelser innan deras flyende ande skingras, så att essensen kan förvaras och studeras."},{t="Makabra byten och ritualkärl",b="För att fullända kärlen behövde han mörka och kraftfulla reagenser som Uzer'i inte kunde hitta ensam i vildmarken. Efter att ha dödat en alliansdvärg som strövade genom Feralas skogar högg Uzer'i huvudet av inkräktaren och ordnade så att det byttes mot Neeru Fireblade, en häxmästare i Orgrimmars skuggiga Cleft of Shadow. Som betalning för det makabra bytet gav Neeru honom sällsynta örter som behövdes för att fullborda bindningsförtrollningarna. Med dessa ingredienser färdigställde Uzer'i sina första kärl och kunde börja fånga andarna hos traktens vildkin, hippogryfer, älvdrakar, treanter och bergsjättar."},{t="Att smida andevapen",b="Att utvinna muisek var bara det första steget i Uzer'is större ambition. Han samlade seg senor, förtrollade mineraler och förstenade flisor från stockar från just de varelser vars andar han fångat, och förenade de fysiska materialen med bunden muisek. Genom dessa riter lärde han sig att binda uråldriga skogsandar permanent i vapen och rustningar och förse Horden med magiskt laddade vapen. Utöver sitt rituella hantverk är Uzer'i djupt nyfiken på dolda kraftplatser i Azeroth och följer aktivt rykten om det uråldriga, översvämmade Sunken Temple."}},faq={{q="Vad är muisek?",a="Muisek är den andliga essens som dröjer sig kvar i levande varelser. Witch Doctor Uzer'i använder särskilt förtrollade kärl för att krympa kropparna av dödade bestar och naturväktare och fånga deras flyende andar innan de löses upp i omgivningen.",al={"vad är muisek","muiseks betydelse","definiera muisek"}},{q="Varför byter Uzer'i dvärghuvuden mot varor i Orgrimmar?",a="Uzer'i behövde särskilda reagenser för att förbereda sina ritualkärl. Efter att ha dödat en alliansdvärg i Feralas lät han leverera det avhuggna huvudet till Neeru Fireblade i Orgrimmar i utbyte mot sällsynta örter som behövdes för att binda muisekandarna.",al={"uppdrag med dvärghuvud","varför skicka huvudet till neeru","neeru fireblades byteshandel"}},{q="Vilka slags varelser jagar Uzer'i?",a="Han jagar varelser med starka band till naturen och nattalvernas gamla allierade, däribland vildkin från The Hinterlands samt hippogryfer, älvdrakar, treanter och bergsjättar i Feralas.",al={"vilka bestar jagar uzer'i","uzer'is andemål","vilka djur används för muisek"}},{q="Vad gör Uzer'i med de fångade andarna?",a="När han har samlat in råa naturmaterial som flisade stockar, senor och mineraler binder Uzer'i muisek permanent i vapen och genomsyrar vanliga vapen med den råa mystiska kraften hos uråldriga skogsväktare.",al={"andevapen","varför samla muisek","belöningar med muisekvapen"}},{q="Var finns Witch Doctor Uzer'i?",a="Witch Doctor Uzer'i bor i Camp Mojache, den främsta bosättningen för Horden i Feralas frodiga och farliga skogslandskap i norr.",al={"uzer'is plats","var finns uzer'i","witch doctor uzer'is plats"}},{q="Vad känner Uzer'i till om Sunken Temple?",a="Som lärd inom andar och mystiska platser i Azeroth har Uzer'i hört talas om Atal'ais översvämmade helgedom Sunken Temple. Han hänvisar äventyrare som vill undersöka saken vidare till goblinutforskaren Marvon Rivetseeker.",al={"uzer'i och sunken temple","uppdrag om sunken temple i feralas","temple of atal hakkar och uzer'i"}}},fp="19,441,21.620.0,34.624.1,25.600.0,15.262.0,47.239.0,42.219.0,46.218.0,37.136.0,46.245.0"}
P.entries["npc:wizbang-cranktoggle"] = {n="Wizbang Cranktoggle",s="Wizbang Cranktoggle är en excentrisk gnomisk ingenjör som bor på värdshusets övre våning i Auberdine. Långt från de kugghjulsfyllda salarna i Gnomeregan och Ironforge har han riktat sin mekaniska uppfinningsrikedom mot att installera och underhålla automatiska kommunikationsapparater som kallas buzzboxar längs Darkshores vilda kust.",h="Wizbang Cranktoggle är en excentrisk gnomisk ingenjör som bor på värdshusets övre våning i Auberdine.",kw={"auberdine","buzzbox","cranktoggle","darkshore","electropellers","ingenjör","gaffer jacks","gnom","wizbang"},ang={["profession:Engineering"]="Wizbangs beroende av specialverktyg som gaffer jacks och electropellers visar den klassiska gnomiska inställningen: mekaniska lösningar på logistiska problem i oupptäckta länder.",["race:Gnome"]="Det är uppmuntrande att se en gnom driva ett experimentellt kommunikationsnätverk längs Kalimdors oländiga kust. Det påminner om Gnomeregans outtröttliga uppfinningsrikedom.",["race:NightElf"]="Medan alvernas vaktposter och druider förlitar sig på vispar, budbärare och naturens band för Wizbang med sig högljudda, surrande kugghjul och metallådor in i Darkshores heliga skogar."},sec={{t="En ingenjör i Auberdine",b="Medan nattalverna i Auberdine föredrar att leva i harmoni med naturen och följa uråldriga traditioner, står Wizbang Cranktoggle för Alliansens nyfikna och uppfinningsrika närvaro. Wizbang sitter på värdshusets översta våning i Auberdine, omgiven av verktyg och reservdelar. Han bryr sig föga om Kalimdors högtidliga druidtraditioner och fokuserar i stället på praktiska mekaniska utmaningar."},{t="Buzzbox-nätverket",b="Wizbangs främsta projekt längs Darkshore är att placera ut och underhålla sin märkliga uppfinning: buzzboxen. Apparaterna är utformade för automatisk rapportering och kommunikation över långa avstånd längs den oländiga, vidsträckta kusten. De skadas ofta av kustvädret och lokala djurs angrepp. Wizbang rekryterar ofta resenärer för att samla in komponenter, bärga verktyg som gaffer jacks och återfinna electropellers så att hans mekaniska övervakningssystem fortsätter fungera."}},faq={{q="Var hittar jag Wizbang Cranktoggle?",a="Wizbang finns på värdshusets övre våning i Auberdine, nattalvernas kustbosättning i Darkshore.",al={"wizbangs plats","var finns wizbang","gnom i auberdine"}},{q="Vad gör Wizbang Cranktoggle i Darkshore?",a="Han är en ingenjör i Alliansen som arbetar med att upprätta och underhålla ett nätverk av automatiska kommunikationsapparater som kallas buzzboxar ute i Darkshores vildmark.",al={"varför är wizbang i auberdine","wizbangs syfte","vad gör wizbang"}},{q="Vad är buzzboxar?",a="Buzzboxar är mekaniska kommunikations- och övervakningsapparater som uppfunnits av Wizbang Cranktoggle för att förmedla information över Darkshore. De går ofta sönder på grund av djurangrepp och hårt väder.",al={"vad är en buzzbox","buzzboxarnas bakgrund","buzzboxens syfte"}},{q="Är Wizbang släkt med några andra gnomer?",a="Han har samma efternamn som Delber Cranktoggle, vilket tyder på att de kan tillhöra samma uppfinnarfamilj.",al={"cranktoggle-familjen","vem är delber cranktoggle","wizbangs släktingar"}},{q="Varför tolererar nattalverna hans uppfinnande i Auberdine?",a="Som medlemmar av Storalliansen ger nattalverna allierade folk husrum och skydd i Auberdine, även om gnomiska uppfinningar står i skarp kontrast till alvernas traditionella harmoni.",al={"nattalver och gnomer","varför tillåta ingenjörskonst i auberdine"}},{q="Vilka uppgifter ger Wizbang äventyrare?",a="Wizbang ber äventyrare hjälpa till att reparera och konfigurera hans buzzboxar. Det innebär att leta längs stranden efter särskilda delar, som electropellers och gaffer jacks.",al={"wizbangs uppdrag","vilka uppdrag erbjuder wizbang"}}},fx={["97312084"]={q="Vem är Wizbang Cranktoggle?",a="Wizbang Cranktoggle är en driftig gnomisk ingenjör som för närvarande bor på värdshusets övervåning i Auberdine. Nattalver föredrar i allmänhet natur framför skramlande maskiner, men Wizbang har slagit sig ned längs kusten för att placera ut och underhålla sitt nätverk av mekaniska apparater, kallade buzzboxar.",al={"vem är wizbang","vem är wizbang cranktoggle","vem är gnomen i auberdine"}},a9ee7ecd={q="Vilken sida står Wizbang Cranktoggle på?",a="Wizbang är lojal mot Gnomeregan och Grand Alliance. Han verkar öppet från Auberdine, där nattalverna tar emot honom, och erbjuder sina tekniska kunskaper och uppdrag till alliansresenärer som passerar genom Darkshore.",al={"wizbang cranktoggles fraktion","tillhör wizbang alliansen","wizbang cranktoggles lojalitet"}},be17225f={q="Vad vill Wizbang Cranktoggle ha?",a="Wizbang vill bygga upp och underhålla ett automatiserat nätverk för övervakning och kommunikation i Darkshore med hjälp av sina buzzboxar. Vildmarken i trakten är farlig och maskiner går ofta sönder. Därför söker han äventyrare som kan samla lokala material, djurdelar och mekaniska komponenter så att nätverket fungerar.",al={"vad vill wizbang ha","wizbang cranktoggles mål","varför behöver wizbang delar"}}},fp="19,190,24.323.0,19.340.0,37.108.0,47.108.0,19.179.0,39.113.0,59.179.0,44.139.0"}
P.entries["npc:wizlo-bearingshiner"] = {n="Wizlo Bearingshiner",s="Wizlo Bearingshiner är en goblinuppfinnare som strandat vid Whitereach Post i Thousand Needles. Han är den enda överlevande efter en kentaurattack mot hans karavan och värvar resenärer för att återhämta en värdefull Hypercapacitor Gizmo från vraket.",h="Wizlo Bearingshiner är en goblinuppfinnare som strandat vid Whitereach Post i Thousand Needles.",kw={"gobliningenjör","hypercapacitor gizmo","thousand needles","whitereach post","wizlo bearingshiner"},ang={["faction:Horde"]="När de slår läger vid Whitereach Post tillsammans med de lokala tauren kan resenärer från Horde enkelt anlita Wizlos mekaniska kunnande för att få tag på användbara manicker.",["profession:Engineering"]="Ingenjörer kan känna sympati för Wizlos önskan att återhämta den mystiska Hypercapacitor Gizmo och ta reda på vad den gör."},sec={{t="En ingenjör vid utposten",b="Wizlo Bearingshiner håller till tillsammans med tauren vid Whitereach Post längs kanjonvägen och tvingas till en ovälkommen försening. Kentaurer attackerade hans karavan och lämnade honom som dess enda överlevande. Hans kunder väntar på sina varor, och han oroar sig för att inte hinna leverera dem i tid."},{t="En strandad leverans",b="Wizlos bästa mojäng hänger runt halsen på en vild panter som sitter i bur bredvid hans förstörda karavan norr om Whitereach Post. Till och med kentaurerna undviker besten. Wizlo erbjuder resenärer nyckeln till buren och en belöning för att hämta hyperkondensatorn, men medger att han ännu inte har klurat ut vad apparaten faktiskt gör."}},faq={{q="Vem är Wizlo Bearingshiner?",a="Wizlo Bearingshiner är en goblinuppfinnare som strandat vid Whitereach Post i Thousand Needles efter att kentaurer attackerat hans karavan. Han söker hjälp med att återhämta en Hypercapacitor Gizmo från en panter i bur.",al={"wizlo bearingshiner","vem är wizlo","goblin vid whitereach"}},{q="Var hittar jag Wizlo Bearingshiner?",a="Han finns vid Whitereach Post, ett Horde-läger längs vägen nära Camp E'thok i Thousand Needles.",al={"wizlos plats","var finns wizlo","hitta wizlo"}},{q="Vilken sorts experiment utför han?",a="Wizlo försöker återhämta sin Hypercapacitor Gizmo. Han medger att han fortfarande måste ta reda på vad den gör; apparatens exakta funktion är okänd.",al={"wizlos uppdrag","vad gör wizlo","wizlos manicker"}},{q="Varför arbetar en goblin med Horde vid Whitereach Post?",a="Whitereach Post är ett oplanerat stopp för Wizlo. Kentaurer attackerade hans karavan i närheten, och han har strandat medan hans kunder väntar på sina leveranser.",al={"varför är wizlo här","tillhör wizlo horde","goblin vid whitereach"}},{q="Tillhör Wizlo Steamwheedle Cartel?",a="Det finns inget fastställt samband mellan Wizlo och Steamwheedle. Han är stationerad hos Horde vid Whitereach Post och försöker återhämta sina varor och leverera dem till sina kunder.",al={"wizlos fraktion","steamwheedle wizlo","wizlo cartel"}},{q="Vad är Hypercapacitor Gizmo?",a="Hypercapacitor Gizmo är en värdefull apparat som bärs av en panter i bur bredvid Wizlos förstörda karavan. Dess exakta syfte är okänt – till och med Wizlo säger att han ännu inte har klurat ut vad den gör.",al={"hypercapacitor gizmo","wizlos apparat","gizmo-uppdrag"}}},fx={["7d59faba"]={q="Vad vill Wizlo Bearingshiner ha?",a="Wizlo vill ha tillbaka sin Hypercapacitor Gizmo, som finns hos pantern som vaktar hans förstörda karavan norr om Whitereach Post. Centaurer attackerade karavanen och lämnade honom strandsatt medan hans kunder väntar på sina varor.",al={"vad vill wizlo ha","wizlo bearingshiners mål","wizlos experiment"}},["1b304945"]={q="Varför är Wizlo Bearingshiner här i Thousand Needles?",a="Wizlo hamnade oplanerat vid Whitereach Post efter att centaurer attackerat hans karavan i närheten. Han är den enda överlevande och oroar sig för leveranserna som kunderna väntar på.",al={"varför är wizlo här","varför är wizlo i thousand needles","varför är wizlo vid whitereach post"}}},fp="19,227,23.275.0,19.307.0,27.194.0,37.99.0,37.150.0,58.145.0,45.182.0,33.190.0"}
P.entries["npc:wizzle-brassbolts"] = {n="Wizzle Brassbolts",s="Wizzle Brassbolts är en gnomisk ingenjör som är stationerad tillsammans med sina meduppfinnare på saltöknens vidder i Thousand Needles. Han arbetar med det gnomiska racingteamet vid Mirage Raceway och söker tåliga lokala material för att förstärka deras experimentella raketbilar.",h="Wizzle Brassbolts är en gnomisk ingenjör som är stationerad tillsammans med sina meduppfinnare på saltöknens...",kw={"brassbolts","mirage raceway","pilot longbeard","raketbil","the shimmering flats","thousand needles","wizzle"},ang={["profession:Engineering"]="Wizzle personifierar den gnomiska ingenjörsfilosofin: att pressa höghastighetsmaskiner till gränsen och ta till ovanliga förstärkningar när metallplåtarna inte håller.",["race:Gnome"]="Gnomer som besöker Shimmering Flats hittar en själsfrände i Wizzle, som envist tänker besegra Steamwheedle-goblinernas vårdslösa konstruktioner med överlägset hantverk."},sec={{t="Uppfinnararbete på saltöknens vidder",b="I Shimmering Flats dallrande hetta tar rivaliteten mellan gnomisk och goblinisk ingenjörskonst formen av raketbilslopp i hög hastighet. Wizzle Brassbolts ingår i gnomernas racingteam och försöker hålla deras fordon hela trots de bländande hastigheterna och det nötande saltet. För att förstärka maskinerna rekryterar han äventyrare som får jaga traktens vilda djur, till exempel de kraftiga sköldpaddorna som strövar omkring i bäckenet. Deras hårda skal används för att bygga nya bränsletankar som kan stå emot hans brors frätande nya raketbränsle."},{t="Vänner långt borta",b="Wizzle håller nära kontakt med vänner på andra kontinenter, däribland Pilot Longbeard, som skickar kurirer med racinghjälmar till bröderna. Med sådan hjälp kan Wizzle hålla det gnomiska teamet med förnödenheter trots deras avlägsna och ogästvänliga testområde i Shimmering Flats."}},faq={{q="Var hittar jag Wizzle Brassbolts?",a="Wizzle Brassbolts finns vid Mirage Raceway i Shimmering Flats, i den sydöstra delen av Thousand Needles. Han står bland gnomernas depåpersonal och deras maskiner.",al={"wizzles plats","var finns wizzle brassbolts","wizzle brassbolts karta"}},{q="Varför samlar Wizzle på sköldpaddsskal?",a="Hans bror konstruerar ett nytt raketbränsle som är så starkt att det kan fräta rakt igenom bilens chassi. Wizzle använder de stenhårda skalen från landsköldpaddorna i Shimmering Flats för att bygga nya bränsletankar som kan hålla det.",al={"uppdrag med härdade skal","varför vill wizzle ha skal","sköldpaddsskal vid racerbanan"}},{q="Vilka är Brassbolts-bröderna?",a="Brassbolts-bröderna är Wizzle och hans bröder Fizzle och Rizzle, gnomiska uppfinnare som driver gnomernas raketbilsteam vid Mirage Raceway och tävlar mot goblinerna. Pilot Longbeard är en vän till dem.",al={"brassbolts-familjen","brassbolts-bröderna","wizzles bröder"}},{q="Är Wizzle vänligt inställd till Horde-spelare?",a="Ja. Mirage Raceway är neutral mark, och Wizzles uppgifter, som att samla härdade landsköldpaddsskal, är öppna för både Horde- och Alliance-äventyrare.",al={"kan horde prata med wizzle","wizzle brassbolts horde"}}},fx={ae9cecf8={q="Vem är Wizzle Brassbolts?",a="Wizzle Brassbolts är en orädd gnomisk ingenjör som arbetar ute på saltöknens skimrande vidder i Thousand Needles. Tillsammans med sina släktingar arbetar han målmedvetet med banbrytande ingenjörsprojekt och mekaniska innovationer. Han representerar Gnomeregans uppfinningsrikedom i den obarmhärtiga hettan på saltöknens vidder.",al={"vem är wizzle","wizzle brassbolts bakgrund","vem är wizzle brassbolts"}},["704bc566"]={q="Vad vill Wizzle Brassbolts ha?",a="Wizzle söker sällsynta och tåliga material från hela trakten för att förstärka och fullända sina ingenjörskonstruktioner. Han ber äventyrslystna resenärer om allt från hårdnade sköldpaddsskal till delar från väldiga djur, som stjärtfenor. Han behöver de exotiska komponenterna till sina mekaniska tester.",al={"vad vill wizzle ha","wizzle brassbolts mål","wizzle brassbolts uppdrag"}},["96d92e19"]={q="Varför är Wizzle Brassbolts här?",a="Wizzle är stationerad vid Mirage Raceway på The Shimmering Flats för att stödja gnomernas ingenjörsarbete och de pågående fordonskapplöpningarna mot deras rivaler från goblinerna. Den väldiga, platta saltbassängen är en perfekt testplats för höghastighetsmaskiner och experimentella apparater.",al={"varför är wizzle här","varför är wizzle vid mirage raceway","varför är wizzle i thousand needles"}}},fp="17,259,27.539.0,25.286.0,35.182.0,39.214.0,32.212.0,36.160.0"}
P.entries["npc:wizzlecrank-s-shredder"] = {n="Wizzlecrank's Shredder",s="I The Sludge Fen sitter Wizzlecrank's Shredder fast bland Venture Company-operatörer. Piloten Wizzlecrank klättrade in i maskinen för att stjäla den, men den rör sig inte utan en nyckel. Motorn måste startas innan goblinen kan försöka fly.",h="I The Sludge Fen sitter Wizzlecrank's Shredder fast bland Venture Company-operatörer.",kw={"the barrens","tändning","pilot wizzlecrank","the sludge fen","flykten","venture company","wizzlecrank","wizzlecranks flismaskin"},ang={["faction:Horde"]="Horden avskyr vanligtvis Venture Companys skogsskövling och giftiga exploatering av The Barrens. Att hjälpa en strandsatt pilot ger dig chansen att slå sönder deras borrverksamhet.",["profession:Engineering"]="Goblinernas shredder använder enkel ång- och kolvteknik. Piloten Wizzlecranks situation visar hur lätt ett proprietärt tändningssystem kan fallera ute i fält."},sec={{t="Instängd i dyn",b="Djupt inne i The Sludge Fen väntar Wizzlecrank i en stillastående shredder. Venture Company-maskinen är omringad av fientliga legosoldater i den förorenade sänkan. Wizzlecrank klättrade ombord för att stjäla den, men upptäckte sedan att han behövde en nyckel för att låsa upp maskinens rörelsekolonn. När en annan shredder-operatör frågade om allt stod rätt till fick han panik och skyllde på ett mekaniskt fel. Nu sitter han kvar där inne, medan vakter och förmän håller till i närheten, och hoppas att någon hämtar nyckeln innan Venture Company fattar misstankar."},{t="En skramlande flykt",b="Med tändningsnyckeln från arbetsledaren i kontrollrummet högst upp i borrtornet skramlar shreddern igång igen. Piloten Wizzlecrank kör den tunga maskinen genom legosoldaterna omkring sig, medan bladen snurrar och metallplåtarna tar emot slagen. Förbipasserande som känner med den instängda piloten eskorterar den sårbara maskinen ut ur sänkan och mot säkerheten."}},faq={{q="Vem sitter i Wizzlecrank's Shredder?",a="Piloten Wizzlecrank är en goblin som befinner sig inuti den mekaniska gångmaskinen. Han klättrade in i Venture Company-maskinen för att stjäla den, men blev fast i deras område utan nyckeln.",al={"vem styr flismaskinen","pilot wizzlecrank","vem sitter i wizzlecranks flismaskin"}},{q="Varför har flismaskinen fastnat i Sludge Fen?",a="Wizzlecrank klättrade in i shreddern utan att veta att den behövde en nyckel för att låsa upp rörelsekolonnen. Omgiven av Venture Company-arbetare, borrare och vakter sa han till en misstänksam operatör att maskinen hade ett mekaniskt fel. Nu väntar han där inne på att någon ska hämta nyckeln från arbetsledaren högst upp i borrtornet.",al={"varför har flismaskinen fastnat","wizzlecrank har fastnat","vad hände med flismaskinen"}},{q="Varför saknas flismaskinen ibland?",a="När shreddern saknas i den norra sänkan i The Sludge Fen har en annan resenär startat tändningen och eskorterar Wizzlecrank i säkerhet. Den återvänder till sin startplats kort efter att eskorteringen är över.",al={"flismaskinen försvunnen","var finns wizzlecranks flismaskin","flismaskinen saknas"}},{q="Vad gör Venture Company i Sludge Fen?",a="Venture Company utvinner råolja, tjära och timmer i norra The Barrens. Arbetet har förvandlat en naturlig vattenkälla till ett giftigt, oljigt träsk, fullt av inhyrda skurkar och förmän.",al={"vad är sludge fen","venture company i sludge fen"}}},fx={["8b008c47"]={q="Vilken sida står Wizzlecrank på?",a="Piloten Wizzlecrank arbetar inte för Venture Company. Han samarbetar med Sputtervalve i Ratchet och klättrade in i Venture Companys skördare för att stjäla den. Han sitter fast djupt inne på fientligt Venture Company-territorium vid The Sludge Fen och är beroende av att äventyrare från endera sidan hämtar nyckeln och eskorterar honom i säkerhet.",al={"wizzlecranks fraktion","tillhör wizzlecrank horden","vem arbetar wizzlecrank för"}},["0d614a8d"]={q="Vad vill Wizzlecrank ha?",a="Wizzlecrank vill inget hellre än att få igång den stulna skördaren och fly från The Sludge Fen. Han är fångad bland aggressiva arbetare från Venture Company och dödliga maskiner. Han behöver någon som hämtar maskinens nyckel och eskorterar honom genom fiendelinjerna i säkerhet.",al={"vad behöver wizzlecrank","wizzlecranks skördares mål","wizzlecranks motiv"}}},fp="22,241,21.497.0,21.372.1,37.181.0,43.317.0,38.213.0,48.195.0"}
P.entries["npc:wrenix-the-wretched"] = {n="Wrenix the Wretched",s="Bredvid sin märkliga apparat i Ratchet hjälper Wrenix the Wretched till att dyrka upp svåra lås. Goblintinkaren erbjuder verktyg för att öppna väl förseglade gömmor.",h="Bredvid sin märkliga apparat i Ratchet hjälper Wrenix the Wretched till att dyrka upp svåra lås.",kw={"the barrens","gizmotronisk","goblin","låsdyrkning","pirater","ratchet","wrenix","usling"},ang={["class:Rogue"]="Som skurk kan du få verktyg av Wrenix och öva på att kringgå låsen på Southsea-piraternas kassaskrin.",["profession:Engineering"]="Wrenix gizmotronic-apparat visar Steamwheedles tekniska kunnande i arbete: högljutt, nyckfullt och effektivt vid precisionsarbete."},sec={{t="En mekaniker i Ratchet",b="Wrenix the Wretched arbetar bredvid sina maskiner i Ratchet, goblinhamnen vid The Barrens kust. Som tinkrare i Steamwheedle Cartel känner han till mekanismer och sinnrika konstruktioner, och vet hur man kringgår lås och tar till vara på det som finns bakom dem. Skurkar och spanare som arbetar längs kusten kan vända sig till honom för hjälp."},{t="Den gizmotroniska apparaten",b="Wrenix håller sin gizmotronic-apparat nära till hands. Med den och sin mekaniska skicklighet tillhandahåller han inbrottsverktyg och dyrkar. De som vill återta stulet smuggelgods från Southsea-pirater längs The Merchant Coast kan ha nytta av dem."}},faq={{q="Vem är Wrenix the Wretched?",a="Wrenix är en goblintinkrare i Ratchet, i The Barrens. Han arbetar bredvid sin gizmotronic-apparat och säljer sinnrika konstruktioner och dyrkar.",al={"wrenix","vem är wrenix","wrenix the wretched"}},{q="Var hittar man Wrenix?",a="Wrenix finns bredvid sin stora mekaniska apparat i Ratchet, hamnstaden på östkusten av The Barrens.",al={"wrenix plats","var finns wrenix","wrenix ratchet"}},{q="Vad är den gizmotroniska apparaten bredvid honom?",a="Wrenix gizmotronic-apparat är en goblintillverkad maskin för finmekanik och diagnostik. Han använder den för att tillverka specialverktyg, som precisionsverktyg för inbrott.",al={"gizmotronisk apparat","wrenix maskin","vad är det för maskin"}},{q="Varför hjälper han äventyrare mot Southsea Freebooters?",a="Southsea-pirater längs The Barrens kust förvarar värdefullt byte i låsta kassaskrin. Wrenix mekaniska verktyg hjälper påhittiga skurkar att öppna dem, till ömsesidig vinning.",al={"varför southsea","historien om att plundra plundrarna","wrenix pirater"}}},fx={["6e51c7f3"]={q="Vilken sida står Wrenix the Wretched på?",a="Wrenix håller sig till Steamwheedle Cartel, som verkar från Ratchet. Liksom de flesta gobliner i hamnen är han främst lojal mot handel, praktiska affärer och sitt eget skinn, snarare än det större kriget mellan Alliansen och Horden. Han förblir neutral mot alla resenärer som vill göra affärer eller hjälpa till med lokala problem.",al={"wrenix fraktion","vem tjänar wrenix","wrenix lojalitet"}},eba18045={q="Varför är Wrenix the Wretched i Ratchet?",a="Wrenix försörjer sig bland de livliga hamnarna i Ratchet och arbetar med sin bisarra gizmotroniska apparat. Där strömmar godtrogna äventyrare, skrotsamlare och skurkar förbi, vilket gör Ratchet till en idealisk utpost för en excentrisk goblinuppfinnare. Här kan han hyra ut smutsjobb och skydda sina affärsintressen mot hoten längs kusten.",al={"varför är wrenix här","varför är wrenix i ratchet","vad förde wrenix till ratchet"}}},fp="19,139,19.295.0,25.249.0,27.145.0,26.117.0,46.168.0,63.163.0"}
P.entries["npc:wynne-larson"] = {n="Wynne Larson",s="I Stormwinds Mage Quarter förser Wynne Larson magiker i hela kungariket med kåpor. Människoskräddaren Wynne förlitar sig på lokala hantverkare sedan Dalaran och Quel'Thalas föll under det tredje kriget, och visar magiker vägen till sällsynta material för förtrollade plagg.",h="I Stormwinds Mage Quarter förser Wynne Larson magiker i hela kungariket med kåpor.",kw={"astral knot garment","dalaran","mage quarter","manaweave robe","quel'thalas","kåpförsäljare","stormwind","wynne larson"},ang={["class:Mage"]="Som magiker kan du vända dig till Wynne tidigt på din magiska bana för att få hjälp med att skräddarsy Manaweave- och Astral Knot-plagg.",["faction:Alliance"]="Som medlem i Alliance kan du se hur Stormwind tar steg mot självförsörjning inom magiskt hantverk för de överlevande Alliance-folken.",["profession:Tailoring"]="Som skräddare kan du se hur tygmakare och skräddare hjälper Stormwind efter att textilcentrumen i norr föll."},sec={{t="En ny marknad för magiska tyger",b="Före det tredje kriget levererade Dalaran och Quel'Thalas de finaste vävda tygerna och förtrollade klädnaderna. Deras förstörelse slog ut de gamla handelsvägarna och produktionen av magiska textilier. I Stormwinds Mage Quarter samarbetar Wynne Larson nu med lokala skräddare och förtrollare som Lucan Cordell. Tillsammans möter de stadens växande efterfrågan på kåpor och magiskt vävda plagg."},{t="Att tillverka magiska kåpor",b="Nybörjarmagiker och lärlingar som söker magiska plagg kommer till Wynnes butik. Hon vet vilka material som behövs till klädnader som Manaweave Robes och Astral Knot Garments. För att hitta materialen skickar hon magiutövare till farliga platser för att hämta sällsynta ingredienser som Pristine Spider Silk. Hennes arbete hjälper Stormwinds magiker att få de kläder de behöver trots bristen på varor från norr."}},faq={{q="Var hittar jag Wynne Larson?",a="Du hittar Wynne Larson i Stormwind Citys Mage Quarter, där hon säljer magiska tygbröstplagg och klädnader till magiker.",al={"wynne larson plats","var finns wynne larson","försäljare av magikerkåpor i stormwind"}},{q="Varför nämner Wynne Dalaran och Quel'Thalas?",a="Före det tredje kriget var Dalaran och Quel'Thalas Eastern Kingdoms främsta källor till förtrollade tyger. Deras förstörelse stoppade importen, så Stormwinds köpmän förlitar sig på lokala hantverkare och sällsynta material från avlägsna trakter.",al={"wynnes dialog om dalaran","quel'thalas-kåpor","varför är kåpor svåra att hitta"}},{q="Vilka uppdrag berör Wynne Larson?",a="Wynne hjälper magiker att få skräddarsydda magiska plagg genom Gathering Materials, Manaweave Robe, Pristine Spider Silk och Astral Knot Garment.",al={"wynne larsons uppdrag","kåpuppdrag i stormwind","uppdrag med manaweave robe"}},{q="Vad säljer Wynne Larson?",a="Wynne säljer enkla och medelsvåra tygkåpor, däribland Burning Robes, Chromatic Robes, Double-Stitched Robes och Silver Dress Robes.",al={"wynne larsons varor","vilka kåpor säljer wynne"}},{q="Vem förlitar sig Wynne på för hantverksmaterial i Stormwind?",a="Wynne förlitar sig på lokala hantverkare, särskilt förtrollaren Lucan Cordell och andra Stormwind-hantverkare, för att väva och förtrolla varorna hon säljer.",al={"vem tillverkar wynnes kåpor","lucan cordells koppling"}},{q="Är Wynne Larson släkt med andra Larson i Stormwind?",a="Wynne har samma efternamn som Evan Larson, en tygmakare i Stormwind, och Jenny Larson. Det gemensamma namnet antyder att de tillhör en hantverkarfamilj inom stadens klädhandel.",al={"larsonfamiljen i stormwind","evan larson","jenny larson"}}},fx={["61901341"]={q="Vem är Wynne Larson?",a="Wynne Larson är en ansedd mänsklig klädhandlare som driver affärer i Mage Quarter i Stormwind City. Hon vänder sig främst till magiker och skräddar lärlingar och säljer kläder av hög kvalitet samt magiska material från lokala hantverkare.",al={"vem är wynne larson","wynne larsons identitet","vem är wynne"}},f66b818d={q="Vilken sida står Wynne Larson på?",a="Wynne Larson är en lojal medborgare i Stormwind och stolt medlem av Alliance. Hon samarbetar nära med lokala mänskliga hantverkare och stadens magiker för att förse Alliance-magiker med fina kläder.",al={"wynne larsons fraktion","vem tjänar wynne larson","wynne larson och alliance"}},["3ea6d1a4"]={q="Varför är Wynne Larson i Mage Quarter?",a="Wynne öppnar sin butik i Mage Quarter eftersom det är där Stormwinds lärda, arkanister och besvärjare samlas. Att sälja kläder och hjälpa magilärlingar gör stadsdelen till den naturliga platsen för hennes handel.",al={"varför är wynne här","varför är wynne i mage quarter","wynne larsons plats och syfte"}},d20d9bb4={q="Vad vill Wynne Larson?",a="Efter att Dalaran förstördes och Quel'Thalas lades i ruiner är fina magiska tyger sällsynta. Wynne vill hålla Stormwinds magiker klädda i förstklassiga plagg genom att skaffa exotiska material, som Pristine Spider Silk, och stödja lokala hantverkare.",al={"vad vill wynne","wynne larsons mål","wynne larsons motiv"}}},fp="12,238,19.362.0,24.362.0,30.130.0,47.231.0,33.141.0,28.136.0,58.139.0,54.159.0"}
P.entries["npc:xavathras"] = {n="Xavathras",s="Xavathras är en grym satyrbefälhavare som håller till bland tälten vid Ruins of Constellas i Felwood. Han leder en grupp Jadefire-satyrer och övervakar fördärvandet av en uråldrig månskensbrunn i sin herres, Xavarics, tjänst.",h="Xavathras är en grym satyrbefälhavare som håller till bland tälten vid Ruins of Constellas i Felwood.",kw={"constellas","felwood","jadefire","månskensbrunn","satyr","xavaric","xavathras"},ang={["class:Druid"]="Druider som försöker häva den demoniska förödelsen i Felwood ser Xavathras avsiktliga förgiftning av rent vatten som en kränkning av naturen som måste stoppas.",["race:NightElf"]="För nattalverna står Xavathras för tragedin i att deras uråldriga fränder förvandlats till demoniska bestar, och för ett pågående vanhelgande av deras heliga månskensbrunnar."},sec={{t="Fördärvaren av Constellas",b="I Felwoods fördärvade lundar har Ruins of Constellas fallit i händerna på Jadefire-satyrerna. Xavathras håller till i ett läger bland alvernas stenverk och leder vanhelgandet av en närbelägen månskensbrunn åt en annan grym satyr, Xavaric. Genom att förgifta det rena vattnet med demonisk energi fördjupar Xavathras det fördärv som håller skogen i sitt grepp. Hans närvaro hotar direkt alla försök att återställa skogen och väcker vrede hos nattalver som Eridan Bluewind, som har dömt honom till döden."}},faq={{q="Vem är Xavathras?",a="Xavathras är en grym satyrledare som för befäl över Jadefire-satyrerna i Ruins of Constellas i Felwood. Han tjänar Xavaric och har fått i uppdrag att fördärva den uråldriga alviska månskensbrunnen bland ruinerna.",al={"vem är xavathras","xavathras bakgrund","vem är satyrledaren i constellas"}},{q="Var finns Xavathras?",a="Xavathras har sitt läger bland satyrernas tält vid Ruins of Constellas, en uråldrig plats för nattalver i södra centrala Felwood.",al={"xavathras plats","var finns xavathras","satyrer i ruins of constellas"}},{q="Varför vill Eridan Bluewind se Xavathras död?",a="Eridan Bluewind vill försvara Felwood och hejda den demoniska vanhelgningens okontrollerade spridning. Xavathras arbetar aktivt med att fördärva en månskensbrunn, så att döda honom är högsta prioritet för dem som försöker rena landet.",al={"varför döda xavathras"}},{q="Vem arbetar Xavathras för?",a="Xavathras arbetar åt Xavaric, en annan grym och mäktig satyr som verkar i Felwood för att stärka Legionens kvarvarande grepp om den fördärvade skogen.",al={"vem är xavathras herre","xavaric xavathras"}}},fp="9,222,23.533.0,17.220.0,29.137.0,45.226.0,29.160.0"}
P.entries["npc:yaw-sharpmane"] = {n="Yaw Sharpmane",s="Yaw Sharpmane är en erfaren tränare för taurenjägare i Bloodhoof Village i Mulgore. Han vägleder unga jägare som ger sig ut från Camp Narache och hjälper dem att bemästra de vilda bestarna på sina förfäders slätter.",h="Yaw Sharpmane är en erfaren tränare för taurenjägare i Bloodhoof Village i Mulgore.",kw={"bestar","bloodhoof","jägare","mulgore","sharpmane","tämja","tauren","instruktör","yaw"},ang={["class:Hunter"]="För taurenjägare som lämnar tryggheten i Red Cloud Mesa är Yaw Sharpmane en oumbärlig mentor som vägleder dig när du knyter band till din allra första vilda följeslagare.",["race:Tauren"]="Yaw står för den vördnadsvärda Shu'halo-traditionen att leva i harmoni med naturen och hedra andarna hos Mulgore vilda bestar."},sec={{t="En vägvisare på slätterna",b="Bland tälten och lägereldarna i Bloodhoof Village tjänar Yaw Sharpmane Shu'halo som instruktör i prickskytte, spårning och överlevnad. Unga jägare som visat vad de går för i Red Cloud Mesa hänvisas till Yaw för att finslipa sina färdigheter när de tar steget ut på Mulgore vidsträckta slätter."},{t="Att knyta band",b="Yaw har främst till uppgift att vägleda nybörjarjägare genom den uråldriga riten att tämja vilda bestar. Han låter nykomlingar knyta band till Mulgore inhemska djurliv och prövar deras tålamod och respekt för naturens balans innan han lär dem att ta hand om och träna en permanent följeslagare."}},faq={{q="Vem är Yaw Sharpmane?",a="Yaw Sharpmane är den lokala jägareinstruktören i Bloodhoof Village. Han lär unga taurenjägare prickskytte, överlevnad i vildmarken och konsten att tämja djurföljeslagare.",al={"yaw sharpmane","vem är yaw","jägarinstruktör i bloodhoof"}},{q="Var hittar jag Yaw Sharpmane?",a="Yaw finns i Bloodhoof Village, mitt i Mulgore vid Stonebull Lakes strand.",al={"yaw sharpmane plats","var finns yaw","yaw koordinater"}},{q="Vad lär Yaw Sharpmane jägare?",a="Han erbjuder vanlig jägarträning, säljer uppgraderingar av grundläggande förmågor och vägleder lovande jägare genom riterna som krävs för att tämja och befalla bestar.",al={"vad lär yaw ut","yaw jägarfärdigheter","yaw förmågor"}},{q="Vilka uppdrag erbjuder Yaw?",a="Yaw erbjuder tauren-versionen av uppdragskedjan för att tämja bestar. Den börjar med 'The Hunter's Path' och fortsätter med 'Taming the Beast' och 'Training the Beast.'",al={"yaw uppdrag","yaw sharpmane uppdrag"}},{q="Varför behöver jägare tala med honom runt nivå 10?",a="När jägare når sin tionde säsong skickas de till Yaw för att lära sig de heliga metoderna för att fånga, utfodra och befalla permanenta djurföljeslagare från Mulgore vildmarker.",al={"yaw nivå 10","tämja best bloodhoof"}},{q="Interagerar Yaw Sharpmane med andra än jägare?",a="Han talar artigt med resande som valt andra yrken, men hans yrkeskunskap och särskilda uppdragsprov är strikt förbehållna jägare.",al={"yaw andra än jägare","kan andra klasser tala med yaw"}}},fx={ce9d051b={q="Vilken sida står Yaw Sharpmane på?",a="Yaw Sharpmane står stadigt på Bloodhoof-taurenernas och Hordes sida. Han är stationerad i Bloodhoof Village och hjälper till att se till att Mulgore unga försvarare kan sina förfäders läror om spårning, prickskytte och att tämja hemlandets vilda djur.",al={"yaw sharpmanes fraktion","är yaw sharpmane med i horde","yaw sharpmanes lojalitet"}},e7f68d71={q="Vad vill Yaw Sharpmane?",a="Yaw vill lära nybörjarjägare jaktens grundläggande traditioner. Han vägleder unga taurener i att leva i samklang med naturen, förstå Mulgore varelser och bemästra den urgamla riten att tämja djur, så att de kan överleva i vildmarken och tjäna sin stam.",al={"yaw sharpmanes mål","yaw sharpmanes motiv","vad gör yaw sharpmane"}},cc781595={q="Varför är Yaw Sharpmane i Bloodhoof Village?",a="Bloodhoof Village är den främsta samlingsplatsen för unga taurener som lämnar Camp Naraches träningsmarker. Yaw Sharpmane bor här för att vägleda jägare när de tar sina första stora steg genom Mulgore, och lär dem att knyta band till djurkamrater och bemästra sitt hantverk.",al={"varför är yaw sharpmane här","yaw sharpmanes syfte i bloodhoof village"}}},fp="13,131,21.223.0,18.253.0,21.144.0,31.103.0,38.125.0,27.141.0,52.149.0,45.112.0"}
P.entries["npc:yeh-kinya"] = {n="Yeh'kinya",s="Yeh'kinya är en djungeltrollforskare som bor i Steamwheedle Port vid Tanaris ökenkust. Han påstår sig söka forntida kunskap och artefakter för att förstå mörka krafter, och skickar villiga äventyrare på uppdrag över Azeroth för att samla förlorade trollreliker.",h="Yeh'kinya är en djungeltrollforskare som bor i Steamwheedle Port vid Tanaris ökenkust.",kw={"hakkar","ironboot","mosh'aru","soulflayer","steamwheedle port","tanaris","vindorm","yeh'kinya","yehkinya"},ang={["class:Priest"]="Präster som är känsliga för andlig essens kan finna Yeh'kinyas nonchalanta insamling av fångade skriandar djupt oroande.",["race:Troll"]="Darkspear Trolls inser den dödliga faran med Hakkars återkomst."},sec={{t="Forskaren i Steamwheedle Port",b="Yeh'kinya håller till bland Steamwheedle Ports gobliner och hamnarbetare och framställer sig som en stillsam student av historia och andar. Han rekryterar resenärer för att spåra upp obskyra magiska föremål i Kalimdor och Eastern Kingdoms, från forntida ägg i The Hinterlands till stentavlor med profetior begravda i ruinerna av Zul'Farrak. Han hävdar att dessa ärenden tjänar fredlig akademisk forskning om trollens forntida historia, men hans särskilda intresse för blodguden Hakkar väcker misstankar hos uppmärksamma betraktare."},{t="Ormarnas svek",b="Bakom sin lärda fasad är Yeh'kinya en fanatisk dyrkare av Hakkar the Soulflayer. Varje artefakt och själaväsen han samlar in manipuleras noggrant för att förbereda den fruktade Blodgudens fysiska återfödelse i Azeroth. När Prospector Ironboot har pusslat ihop hans plan och avslöjat den släpper Yeh'kinya all låtsad vänskap. I stället för att stå till svars för sitt förräderi förvandlas han till en grön vindorm och flyr över öppet hav mot South Seas, medan de lurade hjältarna får söka hjälp hos Zandalari på Yojamba Isle."}},faq={{q="Vem är Yeh'kinya?",a="Yeh'kinya är ett djungeltroll som står nära vattnet i Steamwheedle Port i Tanaris. Han framställer sig som en forskare som söker historiska reliker och andar, med ett särskilt intresse för trollguden Hakkar.",al={"yeh'kinyas historia","vem är yehkinya","yehkinya npc"}},{q="Varför vill Yeh'kinya ha Prophecy of Mosh'aru och Ancient Egg?",a="Yeh'kinya säger att han behöver artefakterna för sina studier av trollens forntida historia och andar. Mosh'aru-tavlorna finns i ruinerna av Zul'Farrak och Ancient Egg i The Hinterlands, och båda har koppling till hans intresse för Hakkar.",al={"varför ancient egg","prophecy of mosharu troll","yehkinyas syfte"}}},fp="9,258,32.506.0,20.540.2,17.214.2,69.225.2"}
P.entries["npc:yvette-farthing"] = {n="Yvette Farthing",s="Yvette Farthing är en Forsaken som bor i Brill i Tirisfal Glades, på Gallows' End Tavern tillsammans med sin far Coleman. Hon verkar lika hårdhudad och avståndstagande som Sylvanas andra anhängare, men bär på minnet av en kärlek som Scourge satte stopp för.",h="Yvette Farthing är en Forsaken som bor i Brill i Tirisfal Glades, på Gallows' End Tavern tillsammans med sin...",kw={"ett olevererat brev","agamand mills","brill","coleman farthing","gallows' end tavern","thurman agamand","tirisfal glades","yvette farthing"},ang={["race:Undead"]="Yvette gestaltar den djupa känslomässiga konflikt som många Forsaken brottas med: de kämpar mellan kvardröjande mänskliga minnen av kärlek och odödhetens bittra, hårda verklighet."},sec={{t="Ekon från kvarnarna",b="Innan det tredje kriget lade Lordaeron i ruiner var Yvette förälskad i Thurman Agamand, en av arvingarna till det välmående Agamand Mills. När Scourges pest närmade sig bad Yvette och hennes far Coleman Thurman att lämna godset och fly med dem. Thurman vägrade av respekt för familjens arv. Båda skulle till slut dö och återuppstå som odöda, men medan Yvette fann en plats bland de frihetstörstande Forsaken i Brill förblev Thurmans tragiska öde okänt för henne."},{t="Ett sista farväl",b="Innan kvarnarna blev övermannade skrev Thurman ett brådskande kärleksbrev till Yvette. Där beskrev han sin bror Devlins förräderi och sörjde sitt val att stanna. Scourge snappade upp brevet, som blev liggande bland ruinerna av Agamand Mills tills äventyrare hittade det. När Yvette läser Thurmans sista bekännelse visar hon för ett ögonblick äkta sorg som en dödlig, innan hon tvingar sig tillbaka till sin kalla likgiltighet. Hon är bitter över att sådana gamla band inte har någon plats i Forsakens bistra verklighet."}},faq={{q="Vem är Yvette Farthing?",a="Yvette Farthing är en Forsaken som bor på Gallows' End Tavern i Brill. Hon är dotter till Coleman Farthing och bodde tidigare på Tirisfal Glades jordbruksmarker, innan det tredje kriget förstörde kungariket.",al={"yvette farthing historia","vem är yvette","yvette i brill"}},{q="Vad har Yvette med Agamand Mills att göra?",a="I livet hade Yvette ett kärleksförhållande med Thurman Agamand. När pesten hotade området försökte hon övertala honom att fly med henne, men han valde att stanna och försvara familjens gods.",al={"yvette agamand","thurman agamand och yvette","yvettes älskare"}},{q="Vad händer när du lämnar Thurmans brev till henne?",a="När en äventyrare lämnar Thurmans sedan länge försvunna brev till Yvette krossas hon för ett ögonblick av sorg när hon läser hans sista ord om kärlek och svek. Men hon hårdnar snabbt och säger att hon är Forsaken nu och att dödligas känslor är meningslösa.",al={"lämna in ett olevererat brev","belöning för thurmans brev","yvettes reaktion på brevet"}},{q="Vem är Yvettes far?",a="Hennes far är Coleman Farthing, som också är Forsaken och bor på Gallows' End Tavern i Brill. De lyckades först fly tillsammans, men båda dukade till slut under för pesten och blev Forsaken.",al={"yvettes far","coleman och yvette","vem är coleman farthing"}}},fx={["71e9f93d"]={q="Vilken sida står Yvette Farthing på?",a="Yvette står helt och hållet på Forsakens och Hordes sida. Även om minnen från hennes dödliga liv och tidigare kärlekar fortfarande kan väcka smärta har hon lagt sina mänskliga känslor bakom sig. Nu bejakar hon sin identitet som en av de viljestarka odöda som tjänar Lady Sylvanas.",al={"yvette farthings fraktion","vilken sida står yvette farthing på","vem tjänar yvette"}},["99950259"]={q="Vad vill Yvette Farthing?",a="Yvette söker avslut efter tragedin som slukade hennes tidigare liv. Hon flydde från Agamand Mills under Scourges invasion medan hennes älskade Thurman stannade kvar, och bar på en outsagd sorg. När hon får höra om hans sista stunder kan hon äntligen stänga dörren till sitt dödliga hjärta och bejaka sin kalla tillvaro bland Forsaken.",al={"vad vill yvette","yvette farthings mål","yvette farthings motiv"}},["8e2cc8a4"]={q="Varför är Yvette Farthing här i Brill?",a="Efter att Agamand Mills ödelagts och Lordaeron fallit för Pesten sökte Yvette och hennes far Coleman skydd i Brill. I odöden tjänar Brill som den främsta Forsaken-staden utanför huvudstaden och är därför en naturlig fristad för överlevare som återtar sitt forna hemland.",al={"varför är yvette farthing i brill","varför är yvette farthing här","varför är yvette här"}}},fp="15,153,19.422.0,16.493.1,23.199.0,45.167.0,54.212.1,23.185.0"}
P.entries["npc:zaldimar-wefhellt"] = {n="Zaldimar Wefhellt",s="På övervåningen i Goldshire lär Zaldimar Wefhellt unga magiker sina första besvärjelser. När de växer ur hans lektioner skickar han dem till Stormwind City för vidare träning.",h="På övervåningen i Goldshire lär Zaldimar Wefhellt unga magiker sina första besvärjelser.",kw={"elwynn forest","goldshire","lion's pride inn","magikermästare","wefhellt","zaldimar"},ang={["class:Mage"]="Som ung mänsklig magiker lämnar du Northshire Abbey och möter Zaldimar först ute i den större världen. Han lär dig tidiga besvärjelser och hänvisar dig sedan till Wizard's Sanctum i Stormwind.",["faction:Alliance"]="På Lion's Pride Inn undervisar Zaldimar Alliansens magiker i Elwynn Forest, så att du kan lära dig magi innan du reser till Stormwind."},sec={{t="Magikern i Goldshire",b="På övervåningen på Lion's Pride Inn lär Zaldimar Wefhellt noviser magins första konster inom det mystiska, eld och frost. När en lärling växer ur lektionerna skickar han hen norrut till Mage Quarter i Stormwind, där Jennea Cannon kan lära hen mer."}},faq={{q="Vem är Zaldimar Wefhellt?",a="Zaldimar Wefhellt lär noviser sina första besvärjelser på Lion's Pride Inn i Goldshire. Han visar dem vägen till vidare träning i Stormwind City.",al={"vem är zaldimar","zaldimar wefhellts roll","magikermästare i goldshire"}},{q="Var hittar jag Zaldimar Wefhellt?",a="Zaldimar Wefhellt finns på andra våningen på Lion's Pride Inn i Goldshire, i rummet längst till vänster högst upp i trappan.",al={"zaldimars plats","var finns zaldimar","hur hittar man zaldimar"}},{q="Vart skickar Zaldimar noviser?",a="När en magiker har lärt sig grunderna skickar Zaldimar hen till Stormwinds Mage Quarter för att tala med Jennea Cannon i Wizard's Sanctum.",al={"zaldimars uppdrag","vem skickar zaldimar dig till","uppdrag tala med jennea"}},{q="Är Zaldimar släkt med andra magiker?",a="Inga släktingar till Zaldimar är kända. Han undervisar på Lion's Pride Inn.",al={"wefhellts familj","zalna wefhellt","zaldimars släktingar"}}},fx={["10a0eae6"]={q="Vilken sida står Zaldimar Wefhellt på?",a="Zaldimar är en lojal medlem av Grand Alliance och tjänar kungariket Stormwind. Han är stationerad mitt i Elwynn Forest och använder sin arkana skicklighet till att vägleda unga magiker som träder fram för att försvara riket och upprätthålla kronans makt.",al={"zaldimar wefhellts fraktion","är zaldimar med i alliance"}},["063cda12"]={q="Vad vill Zaldimar Wefhellt?",a="Zaldimar vill vägleda blivande magiker genom den arkaniska studiens faror. När lärlingarna har förstått grunderna i besvärjelser i Goldshire skickar han dem vidare till mer avancerade lärare, som Jennea Cannon i Mage Quarter i Stormwind, så att de kan förfina sin skicklighet.",al={"zaldimar wefhellts motiv","vad vill zaldimar"}},d06c7379={q="Varför är Zaldimar Wefhellt i Goldshire?",a="Zaldimar håller till på övervåningen i Lion's Pride Inn och tjänstgör som Goldshires magilärare. Goldshire är en viktig anhalt för äventyrare som just lämnat Northshire Valley, så det är en perfekt plats för honom att möta blivande magiker och lära dem grundläggande arkaniska besvärjelser.",al={"varför är zaldimar här","zaldimar i lions pride inn"}}},fp="17,183,21.249.0,25.154.0,35.125.0,38.146.0,39.71.0"}
P.entries["npc:zamja"] = {n="Zamja",s="I Orgrimmars Drag lär Zamja Horde-resenärer att laga mat. Darkspear-trollet tränar kockar i att tillaga måltider av Kalimdors bestar.",h="I Orgrimmars Drag lär Zamja Horde-resenärer att laga mat.",kw={"matlagningstränare","darkspear","orgrimmar","drag","to gadgetzan you go","troll","zamja"},ang={["profession:Cooking"]="Zamja är en av de främsta matlagningsinstruktörerna för Horde-karaktärer i Orgrimmar. Hon lär ut grundläggande recept och hänvisar erfarna kockar söderut till Tanaris för avancerad undervisning.",["race:Troll"]="Liksom många Darkspear-troll har Zamja slagit sig ner i Orgrimmar under krigshövdingen Thralls baner. Hon bidrar med trollens påhittighet och kulinariska kunnande till Hordes huvudstad."},sec={{t="En Cleaver i Drag",b="Zamja arbetar i Drag, där hon styckar kött och lär Horde-resenärer att laga mat. Matlagning hjälper resenärer i Durotars och The Barrens karga trakter att förvandla rått vilt till ransoner. Kockar som behärskar grundrecept kan söka vidare utbildning i Gadgetzan i söder."}},faq={{q="Vem är Zamja?",a="Zamja är en Darkspear-troll som tränar kockar i Orgrimmars Drag. Hon undervisar Horde-kockar och hjälper dem att utveckla sitt hantverk.",al={"zamja npc","vem är zamja","zamja orgrimmar"}},{q="Var hittar jag Zamja?",a="Du hittar Zamja i Drag, den skuggiga skyttegrav som slingrar sig mellan Orgrimmars Valley of Strength och Valley of Honor.",al={"zamjas plats","var finns zamja","zamjas tränarplats"}},{q="Vilken träning erbjuder Zamja?",a="Zamja lär ut matlagning och recept för att tillaga mat av bestar och vilt som samlats in över hela Kalimdor. Kockar som är redo för vidare utbildning kan söka mer avancerade instruktörer.",al={"vad lär zamja ut","zamjas matlagningsrecept","matlagningstränare orgrimmar"}},{q="Vart skickar Zamja avancerade kockar?",a="När en kock växer ur utbildningen som finns i Orgrimmar hänvisar Zamja dem till Gadgetzan i Tanaris för att hitta Dirge Quikcleave.",al={"zamjas uppdrag","uppdraget to gadgetzan you go","hordes expertmatlagning"}}},fx={["85904c39"]={q="Vilken sida står Zamja på?",a="Zamja är lojal mot Horde och sina Darkspear-troll. Hon bor och arbetar i Orgrimmars myllrande hjärta och tjänar stadens invånare och resenärer med stolthet. Hon delar med sig av sina matlagningskunskaper till alla i Horde som vill lära sig hantverket.",al={"zamjas fraktion","zamjas lojalitet","är zamja med i horde"}},ae32e7ed={q="Vad vill Zamja?",a="Zamja ägnar sig åt sitt hantverk och tillbringar dagarna med att stycka kött och laga näringsrik mat i Orgrimmar. Hon vill inget hellre än att dela med sig av sina matlagningskunskaper till blivande kockar i Horde, se till att resenärer får äta sig mätta och hänvisa skickliga utövare till mer avancerade lärare när de vuxit ur hennes undervisning.",al={"zamjas mål","vad behöver zamja","zamjas motiv"}},["16342b16"]={q="Varför är Zamja här i Orgrimmar?",a="Som en skicklig trollkock i orkernas huvudstad har Zamja sitt hem i Orgrimmar, där hon utövar sitt hantverk och stödjer Horde. I ett hårt och torrt land där överlevnad kräver praktiska färdigheter ser hon till att äventyrare och försvarare får lära sig ordentlig köttstyckning och matlagning.",al={"varför är zamja i orgrimmar","zamjas plats och syfte","varför är zamja här"}}},fp="5,133,21.272.0,13.125.0,23.122.0,31.168.0,37.126.0"}
P.entries["npc:zangen-stonehoof"] = {n="Zangen Stonehoof",s="Zangen Stonehoof är en tauren som vakar vid elden på High Rise, mitt i Thunder Bluff. Plikttrogen och respekterad bland sina likar sköter han troget de centrala lågorna varje kväll och samordnar hjälp till sina avlägsna fränder i Kalimdor.",h="Zangen Stonehoof är en tauren som vakar vid elden på High Rise, mitt i Thunder Bluff.",kw={"brasa","high rise","vatten från månskensbrunnen","rau cliffrunner","den heliga lågan","thunder bluff","zangen stonehoof"},ang={["faction:Horde"]="För resenärer som besöker Thunder Bluffs stora platå erbjuder Zangen en kontakt för färder till omstridda områden som Ashenvale.",["race:Tauren"]="Zangen förkroppsligar stammarnas samhörighet och knyter Mulgore civila centrum direkt till avlägsna fränder som Cliffrunners i Thousand Needles."},sec={{t="Väktare av elden på High Rise",b="Zangen Stonehoof håller den gemensamma elden vid liv på High Rise i Thunder Bluff, där den blickar ut över stadens högsta klippor. När skymningen faller över Mulgore tänder Zangen elden, som ger värme och lyser som en beständig fyr för stammarna samlade under överhövding Cairne Bloodhoof. Han håller också kontakt med allierade utanför Mulgoreplatån och förmedlar andliga och rituella uppdrag runt om på kontinenten."},{t="Hjälp till Cliffrunners",b="Zangen förmedlar uppdrag åt Rau Cliffrunner, som är stationerad söderut i Thousand Needles. När Rau behövde det mystiska vattnet från en Night Elf-månskensbrunn till heliga riter, bad Zangen pålitliga äventyrare från Horde att ta sig genom Ashenvales omstridda skogar. Genom att hämta den fyllda flaskan från de urgamla dungarna och skicka den söderut till Freewind Post hjälper Zangen i det tysta till att bevara forntida riter och bistå taurenposter långt borta."}},faq={{q="Vem är Zangen Stonehoof?",a="Zangen Stonehoof är en tauren som bor i Thunder Bluff och står bredvid den stora gemensamma elden på High Rise. Han sköter elden varje kväll och hjälper avlägsna fränder genom att samordna bistånd och kuriruppdrag i Kalimdor.",al={"vem är zangen","zangen stonehoof","vad gör zangen"}},{q="Vad gör Zangen med elden?",a="Varje kväll när mörkret faller tänder Zangen den stora elden framför sig på High Rise. Den ger ljus och värme åt klippans övre terrass.",al={"varför står zangen vid elden","zangens brasa","tända elden"}},{q="Varför behöver Zangen vatten från en månskensbrunn i Ashenvale?",a="Zangen agerar på Rau Cliffrunners vägnar, som är stationerad vid Freewind Post i Thousand Needles. Rau behöver vatten från en månskensbrunn i Ashenvale till en helig rit, och Zangen ber dugliga resenärer att hämta det och bära det söderut.",al={"zangen månskensbrunn uppdrag","den heliga lågan","varför vatten från månskensbrunnen"}},{q="Var hittar man Zangen Stonehoof?",a="Han står mitt på High Rise i Thunder Bluff, precis bredvid den gemensamma eldstaden på den övre platån.",al={"zangens plats","hitta zangen stonehoof","var finns zangen"}}},fx={["44db2024"]={q="Vilken sida står Zangen Stonehoof på?",a="Zangen Stonehoof är helt hängiven Horde och sina taurenbröder. Från sin post på High Rise i Thunder Bluff hjälper han sitt folk genom att samordna med allierade som Rau Cliffrunner och värva dugliga Horde-resenärer till heliga uppdrag runt om i Kalimdor.",al={"zangen stonehoofs fraktion","är zangen med i horde","vem tjänar zangen"}},edd8b42e={q="Vilka har Zangen Stonehoof band till?",a="Zangen arbetar nära Rau Cliffrunner, som är stationerad ute i Thousand Needles karga vidder. När Rau behöver heliga material, som kraftfullt månskensbrunnsvatten från Ashenvales skogar, fungerar Zangen som hans kontakt i huvudstaden och söker resenärer som är villiga att göra resan.",al={"zangen stonehoofs allierade","vem arbetar med zangen stonehoof","rau cliffrunner och zangen"}}},fp="16,162,29.379.0,23.391.0,24.172.0,37.146.0,51.205.0,36.115.0"}
P.entries["npc:zankaja"] = {n="Zankaja",s="I Orgrimmar väntar den unga orckvinnan Zankaja oroligt på besked om sin partner, Dogran. Han fick tjänstgöra vid The Crossroads, längs The Barrens farliga gränstrakt.",h="I Orgrimmar väntar den unga orckvinnan Zankaja oroligt på besked om sin partner, Dogran.",kw={"the barrens","the crossroads","dogran","gazrog","orgrimmar","valley of strength","valley of wisdom","zankaja"},ang={["faction:Horde"]="Som medlem av Horden kan du förstå av Zankajas vädjan att det kostar verkligt blod och stora uppoffringar för de meniga soldater som är stationerade vid utposter som The Crossroads.",["race:Orc"]="Som orc kan du se det personliga priset för vanliga familjer i Durotar, där plikten mot krigshövdingens nya rike skickar deras närmaste ut i otämjda, dödliga gränstrakter."},sec={{t="Ett vakande hjärta",b="I Orgrimmar väntar Zankaja på nyheter om sin partner Dogran. Dogran befordrades och reste söderut för att förstärka utposten vid The Crossroads i The Barrens. Uppdraget är en ära för en krigare, men gränstrakten är hård, med quilboarer, kentaurer och aggressiva bestar. När Dogran inte hörde av sig eller återvände som väntat började Zankaja be resande att leta efter nyheter om honom."},{t="Tragiska bud",b="Nyheter från The Barrens besannade Zankajas värsta farhåga: Dogran föll i quilboarernas klor. Hon håller ändå fast vid hoppet innanför Orgrimmars ravinväggar, trots att gränstrakten är oförsonlig. Nyheterna som resande för med sig målar upp en dyster bild av uppoffring vid Hordens farliga gränser."}},faq={{q="Var hittar jag Zankaja?",a="Zankaja bor längs stigen mellan Valley of Strength och Visdomens dal i Orgrimmar.",al={"zankajas plats","var är zankaja","hitta zankaja"}},{q="Vem är Dogran?",a="Dogran är Zankajas partner, en orcisk krigare vars nyliga befordran skickade honom till en post vid The Crossroads i The Barrens.",al={"vem är dogran","dogran","zankajas partner"}},{q="Varför är Zankaja orolig?",a="Dogran skickades i tjänst till The Crossroads i det hårda The Barrens, men återvände inte och hörde inte av sig. Zankaja fruktar att något har hänt honom vid gränsen.",al={"vad vill zankaja","zankajas problem","varför är zankaja ledsen"}},{q="Vad ber Zankaja äventyrarna att göra?",a="Zankaja ber äventyrare på väg ut ur Orgrimmar att besöka kapten Gazrog vid The Crossroads och fråga var Dogran befinner sig och hur han mår.",al={"zankajas uppdrag","uppdrag om nyheter från dogran"}},{q="Vad hände med Dogran i The Barrens?",a="Zankaja vet inte vad som hände Dogran i The Barrens. Hon ber resande tala med Gazrog vid The Crossroads och följa spåret därifrån.",al={"är dogran död","dograns öde","vad hände med dogran"}}},fx={d77e4e41={q="Vem är Zankaja?",a="Zankaja är en ung ork som bor i Orgrimmar. Hon dröjer sig dagarna igenom mellan Valley of Strength och Valley of Wisdom, uppslukad av sorg och oro över sin partner Dograns öde. Han gav sig av på uppdrag i The Barrens hårda vildmark.",al={"vem är zankaja","zankajas identitet","zankajas historia"}},c2de3af5={q="Vilken sida står Zankaja på?",a="Zankaja är en lojal civil i Horde och bor i huvudstaden Orgrimmar. Hennes bekymmer är personliga och handlar om hemmet, inte om politik. Allt kretsar kring hennes partners säkerhet och tryggheten i hemmet bland hennes orkfränder.",al={"zankajas fraktion","är zankaja med i horde","zankajas lojalitet"}},b4e1ea75={q="Varför är Zankaja här?",a="Zankaja stannar i Orgrimmar och väntar oroligt på besked om sin partner Dogran. När han skickades söderut till The Crossroads blev hon kvar i huvudstadens trygghet, men nu sitter hon fast i plågsam ovisshet eftersom hans brev och rapporter har upphört.",al={"varför är zankaja i orgrimmar","varför står zankaja här","orsaken till zankajas plats"}}},fp="7,171,16.369.0,14.280.1,25.98.0,14.119.0,23.156.0,40.149.0,39.152.1"}
P.entries["npc:zardeth-of-the-black-claw"] = {n="Zardeth of the Black Claw",s="I Stormwinds Mage Quarter skyddar Zardeth of the Black Claw en hemlig grupp häxmästare från granskning. Han håller till i kamrarna under Slaughtered Lamb och låtsas vara en vanlig gäst. När nyfikna adelsmän börjar ställa för många frågor ser han till att de aldrig frågar igen.",h="I Stormwinds Mage Quarter skyddar Zardeth of the Black Claw en hemlig grupp häxmästare från granskning.",kw={"en ädel brygd","baurles wishock","black claw","mage quarter","musquash root","slaughtered lamb","tear of tilloa","häxmästare","zardeth"},ang={["class:Warlock"]="Som mänsklig häxmästare visar Zardeth den kalla pragmatism som vissa förlitar sig på för att överleva i Alliansens hjärta, där överlevnad kan bero på att döda i förebyggande syfte.",["faction:Alliance"]="För en lojal anhängare av Alliansen blottar Zardeth ett korrumperat undre skikt under Stormwinds glänsande gator.",["profession:Herbalism"]="Som örtkunnig kan du se hur Zardeths plan förvandlar giftiga växter som Tear of Tilloa och Musquash Root till dödliga verktyg."},sec={{t="En skugga under värdshuset",b="Under Slaughtered Lamb ligger tunnlar där de som utövar mörkare konster finner skydd, medan spirorna i Mage Quarter öppet ägnar sig åt arkana studier. Zardeth of the Black Claw verkar från kryptorna och skyddar häxmästarna som gömmer sig mitt under stadsvaktens näsa. Alliansen fördömer felmagi, så gruppen överlever genom att hålla sin närvaro hemlig och undanröja hot innan kungliga utredare anländer."},{t="Tysta adeln",b="Lord Baurles K. Wishock fick höra rykten om den dolda häxmästarkulten och började mana Adelsrådet att inleda en fullskalig utredning. Zardeth fruktade att granskningen skulle förstöra enklaven under Slaughtered Lamb och ordnade därför ett hemligt svar. Eftersom han visste att lorden uppskattade fin sprit skickade Zardeth en agent genom Eastern Kingdoms för att samla in två sällsynta, dödliga växter: Tear of Tilloa från Duskwood och Musquash Root från under Stonewrought Dam."},{t="En ädel brygd",b="Zardeth blandade de insamlade växterna med mörkt öl och skapade Black Claw Stout, en dödlig dryck förklädd till en vanlig lyxgåva. Det förgiftade ölet nådde Wishocks gods och dödade honom snabbt och ljudlöst. När lorden var död och hans kampanj stoppad innan kronan hann ingripa kunde Zardeth och de andra häxmästarna hålla sin dolda enklav under Slaughtered Lamb säker."}},faq={{q="Vem är Zardeth of the Black Claw?",a="Zardeth är en mänsklig häxmästare som vakar över det dolda brödraskapet i kryptorna under Slaughtered Lamb i Stormwinds Mage Quarter. Han avleder misstankar och hanterar hot mot häxmästarnas hemliga närvaro i staden.",al={"zardeth","vem är zardeth","zardeth stormwind"}},{q="Var hittar jag Zardeth?",a="Zardeth finns under Slaughtered Lamb i den södra delen av Stormwind Citys Mage Quarter. Gå in på värdshuset, leta efter passagen längst in som leder nedåt och följ de slingrande katakomberna till häxmästarnas enklav.",al={"zardeths plats","var finns zardeth","zardeth slaughtered lamb"}},{q="Varför vill Zardeth att Lord Wishock ska dö?",a="Lord Baurles K. Wishock upptäckte bevis på häxmästare under Stormwind och uppmanade stadens adel att utreda saken. En officiell undersökning kunde ha lett till att myndigheterna spårade upp och avrättade kulten i Slaughtered Lamb.",al={"varför döda wishock","lord wishock måltavla","orsak till den ädla brygden"}},{q="Vad är Black Claw Stout?",a="Black Claw Stout är en dödlig dryck som Zardeth bryggde av mörkt öl och två sällsynta giftiga växter: Tear of Tilloa från Darkshire och Musquash Root från Wetlands. Han fick den att se ut som en dyr årgångsdryck för att i tysthet döda Lord Wishock.",al={"black claw stout","vad är brygden","wishock förgiftning"}},{q="Vad är Black Claw?",a="Black Claw är Zardeths tillhörighet eller titel inom Stormwinds dolda nätverk av häxmästare. Dess medlemmar undkommer Stormwinds vakter och Kirin Tor och tar till dödliga metoder för att skydda sin hemlighet.",al={"black claw betydelse","vilka är black claw","black claw häxmästare"}},{q="Varför tillåts häxmästare alls i Stormwind?",a="Häxmästare tolereras inte öppet i Stormwind, så de gömmer sig i källarna under Slaughtered Lamb. Myndigheterna kanske ser mellan fingrarna av praktiska skäl, eller känner inte till dem eftersom agenter som Zardeth dödar dem som är på väg att avslöja häxmästarna.",al={"är häxmästare lagliga","häxmästarlore i stormwind","varför häxmästare i staden"}}},fx={ec5a54de={q="Vems sida står Zardeth of the Black Claw på?",a="Zardeth ser till att Stormwinds gömda häxmästare överlever, snarare än att följa kronans lagar. Han verkar under Alliansens fana från en plats under Mage Quarter, men hans lojalitet tillhör helt och hållet häxmästarkretsen som håller sig gömd i Slaughtered Lamb, beredd att undanröja varje adelsman eller ämbetsman som hotar att avslöja deras mörka studier.",al={"zardeths fraktion","vem tjänar zardeth","är zardeth lojal mot stormwind"}},["212e3858"]={q="Vad vill Zardeth of the Black Claw?",a="Zardeth vill skydda sin enklav av häxmästare från Stormwinds adel och dess granskning. När Lord Wishock fick nys om deras underjordiska etablissemang och krävde en formell utredning, försökte Zardeth genast iscensätta den besvärlige adelsmannens tysta och permanenta undanröjande.",al={"vad är zardeths mål","zardeths plan","vad vill zardeth"}},f970876d={q="Varför är Zardeth of the Black Claw här i Stormwind?",a="Zardeth verkar från katakomberna under Slaughtered Lamb och använder värdshusets anspråkslösa fasad för att utöva demonerisk magi i hemlighet. Han håller vakt för att hejda yttre hot och ser till att utövarna där nere kan ägna sig åt sina förbjudna konster utan att stadens myndigheter stör dem.",al={"varför är zardeth här","zardeths syfte i slaughtered lamb","varför kom zardeth till stormwind"}}},fp="25,241,25.383.0,22.451.1,12.371.2,33.220.0,25.220.0,40.217.0,25.234.0,23.196.0,45.258.0"}
P.entries["npc:zargh"] = {n="Zargh",s="Vid The Crossroads i The Barrens säljer Zargh kött och skickar utvalda köttbitar till Orgrimmar.",h="Vid The Crossroads i The Barrens säljer Zargh kött och skickar utvalda köttbitar till Orgrimmar.",kw={"the barrens","slaktare","the crossroads","gryshka","hot lion chops","kött","zargh"},ang={["faction:Horde"]="Som medlem av Horden kan du se hur rutten mellan The Crossroads och Orgrimmar använder vindryttare för att föra budbärare mellan The Barrens och Durotar.",["profession:Cooking"]="Som kock kan du köpa Zarghs recept på Hot Lion Chops, ett av få sådana recept som säljs i The Barrens. Det låter dig tillaga kött från lokala rovdjur."},sec={{t="Slaktare vid The Crossroads",b="Vid The Crossroads säljer Zargh saltat kött, lägg och vilt från de omgivande slätterna. Resenärer som beger sig ut i vildmarken kan köpa proviant i hans butik. Han skickar också utvalda köttbitar tvärs över Durotar till Innkeeper Gryshka i Valley of Strength i Orgrimmar."},{t="Ett budärende",b="Zargh skickar färskt kött till Innkeeper Gryshka i Orgrimmar med vindryttare, så att det når henne innan det blir dåligt. Ett brev från Gryshka berättar att Zargh förlorade ett finger i en olycka. Efter att ha fått ett meddelande från henne antyder Zargh att en bröllopsinbjudan kan finnas i resenärens framtid."}},faq={{q="Var hittar jag Zargh?",a="Du hittar Zargh vid The Crossroads, den centrala bosättningen för Horden i The Barrens. Han säljer kött bland lägrets handlare.",al={"zarghs plats","var finns zargh","zargh npc"}},{q="Vilken relation har Zargh till Innkeeper Gryshka?",a="Zargh förser Innkeeper Gryshka i Orgrimmar med utvalt kött från The Barrens. Deras brev vittnar om ett varmt och personligt band, och efter att ett brev kommit fram antyder Zargh att en bröllopsinbjudan kan vara på väg.",al={"zargh gryshka","zarghs relation","vem gifter sig zargh med"}},{q="Vad hände med Zarghs finger?",a="Ett brev från Gryshka berättar att Zargh förlorade ett finger i en olycka vid styckning. Olyckan är fortfarande ett internt skämt mellan dem om innehållet i hans köttpaket.",al={"zargh förlorade finger","zarghs olycka"}},{q="Vad säljer Zargh?",a="Zargh säljer bland annat köttlår, saltade skinkbiffar, vildsvinslägg och ett recept på Hot Lion Chops.",al={"zarghs handelsvaror","zarghs varor"}}},fx={["84a718e2"]={q="Vem är Zargh?",a="Zargh är en orcisk slaktare och köttförsäljare vid The Crossroads i The Barrens. Han förser resenärer, vakter och allierade i hela hordens territorium med proviant och utvalda styckningsdetaljer från det lokala villebrådet.",al={"vem är zargh","zarghs historia","zargh vid the crossroads"}},["9d177987"]={q="Vems sida står Zargh på?",a="Zargh är en lojal medlem av Horden och verkar från den strategiskt viktiga bosättningen The Crossroads. Han samordnar regelbundet handel och leveranser med hordens bosättningar, däribland huvudstaden Orgrimmar.",al={"tillhör zargh horden","zarghs fraktion","zarghs lojaliteter"}},db26839a={q="Vad vill Zargh?",a="Zargh vill sköta sin slakterihandel smidigt och se till att hans leveranser når fram. Han anlitar pålitliga kurirer för att leverera förstklassigt kött från The Barrens till sin nära vän Innkeeper Gryshka vid Valley of Strength i Orgrimmar.",al={"vad vill zargh","zarghs uppdragsmål","zarghs motiv"}},a9ecc79a={q="Varför är Zargh vid The Crossroads?",a="The Crossroads är ett viktigt nav för handel och resor i The Barrens, vilket gör platsen idealisk för en slaktare. Zargh omges av ett överflöd av vilt och kan därför enkelt tillreda och exportera utvalt kött till avlägsna bosättningar.",al={"varför är zargh här","varför är zargh vid the crossroads","orsaken till zarghs plats"}}},fp="5,86,25.260.0,18.277.1,23.124.0,48.202.0,32.156.0,21.118.0"}
P.entries["npc:zarlman-two-moons"] = {n="Zarlman Two-Moons",s="Zarlman Two-Moons är en vördad taurenmystiker som bor i Bloodhoof Village i centrala Mulgore. Medan Baine Bloodhoof sköter byns dagliga, världsliga angelägenheter vägleder Zarlman dess andliga liv och kommunicerar med andarna. Han spelar en viktig roll när unga tauren går in i vuxenlivet genom den heliga Rite of Vision.",h="Zarlman Two-Moons är en vördad taurenmystiker som bor i Bloodhoof Village i centrala Mulgore.",kw={"bloodhoof","mulgore","rit","shaman","andar","tauren","two-moons","by","vision","zarlman"},ang={["class:Shaman"]="Zarlman förkroppsligar den klassiska tauren-traditionen av shamanism och balanserar kontakten med andarna med praktiskt stamledarskap.",["faction:Horde"]="Från sin plats i Mulgore centrala nav introducerar Zarlman nyanlända Horde-allierade till de djupa andliga seder som formar taurenkulturen.",["race:Tauren"]="För taurenäventyrare är Zarlman en oumbärlig vägledare som hjälper dig att fullborda ungdomens heliga riter och väcka din andliga syn."},sec={{t="Den osynligas väktare",b="I Bloodhoof Village är ledarskapet delat mellan det fysiska och det mystiska. Baine Bloodhoof ansvarar för bosättningens försvar och världsliga behov, men det är Zarlman Two-Moons som upprätthåller harmonin i andevärlden. I en kultur som har djup vördnad för Earth Mother och förfädernas visdom fungerar Zarlman som en förbindelselänk mellan slätternas vardagliga prövningar och det förflutnas tidlösa röster."},{t="Rite of Vision",b="Zarlmans viktigaste plikt mot sitt folk är att leda Rite of Vision, en traditionell prövning som varje tauren på väg mot vuxenlivet måste genomgå. Genom att vägleda de invigda när de bereder heliga drycker och lyssnar noga efter förfädernas tecken hjälper han unga jägare, shamaner och krigare att finna sin utstakade väg och sina andliga vägvisare. Under hans ledning lär sig de invigda att fysisk styrka på slätterna betyder föga utan andlig klarhet."}},faq={{q="Vem är Zarlman Two-Moons?",a="Zarlman Two-Moons är en framstående taurenmystiker i Bloodhoof Village. Medan Baine Bloodhoof sköter det världsliga ledarskapet och byns praktiska försvar vakar Zarlman över bosättningens andliga välmående och vägleder unga äventyrare genom gamla stamtraditioner.",al={"vem är zarlman","zarlman two-moons bakgrund","vem är shamanen i bloodhoof"}},{q="Vilken roll har Zarlman i Bloodhoof Village?",a="Zarlman ansvarar för andliga angelägenheter, kontakt med förfäderna och kulturella riter för invånarna i Bloodhoof Village. Han kompletterar Baine Bloodhoofs fysiska ledarskap genom att se till att stammen förblir i harmoni med naturandarna och sina förfäder.",al={"zarlmans uppgift","zarlmans syfte","mystiker i bloodhoof village"}},{q="Vad är Rite of Vision?",a="Rite of Vision är en traditionell övergångsrit för unga tauren som färdas genom Mulgore. Under Zarlmans ledning dricker de invigda en rituell brygd som öppnar deras andliga syn och låter dem följa visioner och få vägledning från naturandar.",al={"rite of vision-uppdrag","vad är rite of vision","tauren-visionuppdrag"}},{q="Var hittar man Zarlman Two-Moons?",a="Zarlman Two-Moons finns i Bloodhoof Village, mitt i Mulgore, vid Stonebull Lakes krök.",al={"var finns zarlman","zarlmans plats","hur hittar man zarlman"}},{q="Hur förhåller sig Zarlman till Baine Bloodhoof?",a="Zarlman arbetar tillsammans med Baine Bloodhoof som hans andliga motsvarighet. Medan Baine leder byn i fysiska och militära frågor bidrar Zarlman med mystisk visdom och vakar över stammens andliga balans.",al={"baine och zarlman","zarlmans relation till baine"}},{q="Varför är Rite of Vision viktig för unga tauren?",a="Rite of Vision är avgörande för varje tauren som når vuxen ålder. Den markerar övergången från oprövad ungdom till erkänd medlem av stammen, uppenbarar deras inre andliga vägvisare och befäster deras band till Earth Mother.",al={"varför genomföra rite of vision","rite of visions betydelse"}}},fx={caff3cf9={q="Vems sida står Zarlman Two-Moons på?",a="Zarlman Two-Moons är helt hängiven Bloodhoof-stammen och Horden. I Bloodhoof Village arbetar han nära Baine Bloodhoof för att se till att deras folk förblir andligt motståndskraftiga mot alla hot som drabbar Mulgore.",al={"vem tjänar zarlman","zarlman two-moons fraktion","tillhör zarlman horden"}},["45ee9eb7"]={q="Vad vill Zarlman Two-Moons?",a="Zarlman vill värna om Bloodhoof Villages andliga välmående. Baine Bloodhoof leder folket i praktiska frågor, medan Zarlman vägleder unga äventyrare genom uråldriga traditioner som Synens ritual, så att de kan tala med andarna och finna sin sanna väg.",al={"vad vill zarlman","zarlmans mål","vad gör zarlman"}},["1734c724"]={q="Varför är Zarlman Two-Moons här?",a="Zarlman stannar i Bloodhoof Village för att vara byns främsta andliga väktare. När stammens medlemmar växer upp leder han de heliga riter som krävs för att tala med förfädernas andar och skydda deras förfäders land från osedda andliga faror.",al={"varför är zarlman i bloodhoof village","varför är zarlman här"}}},fp="17,213,20.298.0,18.363.0,25.252.0,44.221.0,27.197.0,37.107.0,43.202.0,52.191.0"}
P.entries["npc:zarrin"] = {n="Zarrin",s="Zarrin är en Night Elf-matlagningsmentor i Dolanaar, bland Teldrassils grenar. Vid en öppen eldstad bakom byns värdshus lär han unga Night Elves och besökare traditionella Kaldorei-matlagningsmetoder.",h="Zarrin är en Night Elf-matlagningsmentor i Dolanaar, bland Teldrassils grenar.",kw={"matlagning","dolanaar","kaldorei","teldrassil","tränare","zarrin"},ang={["profession:Cooking"]="För äventyrare som börjar sin resa i Teldrassil är Zarrin den främsta mentorn som lär dem att förvandla kött från vilda djur och insamlade råvaror till näringsrika måltider.",["race:NightElf"]="Zarrin bevarar Kaldoreis vardagliga matkultur och ser till att traditionella smaker och metoder lever vidare i Världsträdets trädkrona."},sec={{t="Eldstadsväktare i Dolanaar",b="Bakom värdshuset i Dolanaar, avsides från huvudvägen, sköter Zarrin en öppen eld där han delar med sig av Kaldoreis matlagningskonst. För att överleva i Teldrassil måste man ta till vara på det väldiga trädets inhemska växt- och djurliv, och Zarrin undervisar dem som vill försörja sig genom att samla föda och laga mat hemma."}},faq={{q="Var hittar jag Zarrin?",a="Zarrin står bakom värdshuset i Dolanaar på Teldrassil och lagar mat över en eld på den öppna gården mittemot vägen.",al={"zarrins plats","var är zarrin","matlagningstränare i dolanaar"}},{q="Vad lär Zarrin ut?",a="Han är en Cooking-tränare som lär nybörjare grunderna i matlagning och traditionella recept från Night Elf.",al={"zarrin tränare","vad lär zarrin ut"}},{q="Vilka uppgifter erbjuder Zarrin?",a="Zarrin ber resenärer hjälpa honom att laga traditionella rätter och erbjuder uppdraget 'Recipe of the Kaldorei' för att lära nykomlingar lokal matlagning.",al={"zarrin uppdrag","recipe of the kaldorei-uppdraget"}}},fx={["43472bbf"]={q="Vem är Zarrin?",a="Zarrin är en Night Elf och matlagningslärare som sköter sin eldstad i Dolanaar. Han håller till strax bakom byns värdshus och tillbringar dagarna vid den öppna elden med att lära unga resenärer och lokala väktare kaldoreiernas traditionella kokkonst.",al={"vem är zarrin","zarrins historia","zarrins identitet"}},["9b474307"]={q="Vems sida står Zarrin på?",a="Zarrin står troget på Darnassus och den större Alliansens sida. Han bor i lugn och ro inom Teldrassils gränser och erbjuder sin eldstad och sina matlagningskunskaper till vänligt sinnade resenärer som besöker bosättningen Dolanaar.",al={"zarrins fraktion","zarrin och alliansen","vem tjänar zarrin"}},["08ffbf8a"]={q="Vad vill Zarrin?",a="Zarrin ägnar sig åt att bevara kaldoreiernas traditionella matkultur och föra den vidare. Han vill lära nyblivna äventyrare att laga näringsrika måltider av det rika djur- och växtliv som finns på Teldrassil.",al={"vad vill zarrin","zarrins mål","zarrins syfte"}},["351be696"]={q="Varför är Zarrin i Dolanaar?",a="Dolanaar är den viktigaste vägkorsningen för unga Night Elf som ger sig av från Shadowglen. Zarrin har sitt grillspett och sin kokeld bakom det lokala värdshuset, så att han snabbt kan ge nybörjare viktiga överlevnadsrecept innan de möter större faror.",al={"varför är zarrin i dolanaar","varför är zarrin här","varför zarrin är här"}}},fp="6,206,24.232.0,24.96.0,23.82.0,29.132.0"}
P.entries["npc:zenn-foulhoof"] = {n="Zenn Foulhoof",s="Zenn Foulhoof är en satyr som håller till strax öster om Dolanaar i Teldrassil. Han ber förbipasserande om skogsreagenser, medan de lokala nattalverna håller noga uppsikt över honom.",h="Zenn Foulhoof är en satyr som håller till strax öster om Dolanaar i Teldrassil.",kw={"fördärvad kotte","dolanaar","satyr","sök försoning","teldrassil","zenn foulhoof"},ang={["class:Druid"]="Zenns manipulation med vilda reagenser och avsiktliga spridning av korrumperande orenheter strider direkt mot Cenarions lära, som vill bevara Teldrassil orört.",["race:NightElf"]="Satyrer är det yttersta sveket mot kaldoreiernas arv. Att se en av dem ligga och slöa på Teldrassils heliga grenar är en förolämpning mot Elune och vildmarkens andar."},sec={{t="En intrigmakare i skogen",b="Till skillnad från de flesta satyrer, som är öppet fientliga och tjänar demoniska härskare, har Zenn Foulhoof på något vis fått nattalverna att tolerera honom strax utanför Dolanaar. Han upprätthåller en vänlig fasad och hävdar att han har förändrats eller vill byta till sig harmlösa skogsreagenser som nattsebertänder, strigidugglors fjädrar och Webwood Spider Silk. I själva verket manipulerar han lättlurade ungdomar till att skaffa ingredienser för vidriga ritualer. Dolanaars råd vägrar låta honom verka utan uppsikt. I stället för att avrätta honom genast ger de äventyrare i uppdrag att förödmjuka honom genom att mata honom med fördärvad skogsfrukt, som tillfälligt förvandlar den intrigerande satyren till en harmlös groda."}},faq={{q="Varför angriper nattalverna inte Zenn Foulhoof genast?",a="Zenn upprätthåller en vänlig fasad och har ännu inte öppet begått några grymheter mot Världsträdet. Därför väljer Dolanaars råd att tillrättavisa honom med offentlig förödmjukelse och hålla honom under uppsikt, i stället för att genast döma honom till döden.",al={"varför är zenn vänlig","varför dödar inte nattalverna zenn","är zenn foulhoof ond"}},{q="Vad händer när du matar Zenn med de fördärvade kottarna och bären?",a="De äldste i Dolanaar beordrar detta som botgöring för Zenns illgärningar. Straffets följd blir tydlig när han äter den fördärvade frukten.",al={"zenns försoningsuppdrag","sök försoning-uppdraget","zenn groda"}},{q="Vad är en satyr?",a="Satyrer är nattalver som förvandlades till hornade, klövhövdade bestar under De äldstes krig, efter att ha svurit trohet till Burning Legion. De flesta är fullständigt korrumperade och våldsamt fientliga mot sina okorrumperade släktingar.",al={"vad är satyrer","satyrernas historia"}}},fx={["1240b4a1"]={q="Vem är Zenn Foulhoof?",a="Zenn Foulhoof är en ensam satyr som håller sig gömd strax öster om Dolanaar på Teldrassil. Satyrer är demoniska varelser och Night Elfs urgamla fiender, men Zenn säger sig vilja leva i fred. Han bor stillsamt bland Världsträdets grenar i stället för att öppet angripa dem som bor där.",al={"vem är zenn","zenn foulhoofs historia","vem är foulhoof"}},["8f35fa9f"]={q="Vems sida står Zenn Foulhoof på?",a="I grund och botten står Zenn på sin egen sida och döljer sina ondskefulla avsikter bakom en harmlös och samarbetsvillig fasad. Han uppträder fredligt mot unga äventyrare och visar ingen öppen fientlighet, men han har onda avsikter. Han manipulerar främlingar till att hjälpa honom med sina fördärvade planer och balanserar på gränsen under Dolanaars råds vaksamma blickar.",al={"är zenn ond","zenn foulhoofs fraktion","är zenn vänligt sinnad"}},["7266a9e7"]={q="Vad vill Zenn Foulhoof?",a="Zenn ber förbipasserande äventyrare samla in nätterbladständer, strigidugglors fjädrar och Webwood Spider Silk som ingredienser till sina hemliga affärer i skogen.",al={"vad vill zenn","zenn foulhoofs motiv","zenns uppdragsmål"}}},fp="13,102,22.547.1,64.190.0,64.124.1,16.214.0"}
P.entries["npc:zevrost"] = {n="Zevrost",s="I Cleft of Shadow i Orgrimmar tränar Zevrost häxmästare i ond magi. Han vägleder Hordens noviser genom åkallelseseremonier och hantering av mörka artefakter.",h="I Cleft of Shadow i Orgrimmar tränar Zevrost häxmästare i ond magi.",kw={"cleft of shadow","felmagi","felsteed","orgrimmar","tränare","häxmästare","zevrost"},ang={["class:Warlock"]="Som häxmästare i Horden kan du lära dig avancerade besvärjelser av Zevrost och skickas ut för att söka särskilda vapen, föremål i vänsterhanden och en flammande riddjur.",["race:Orc"]="Som orch lever du bland ett folk som till stor del skyr demonisk magi. Zevrost representerar utövarna som fortfarande brukar de mörka konsterna under krigshövdingens stränga uppsikt."},sec={{t="Mörkrets konster",b="I Cleft of Shadow under Orgrimmar är Zevrost en av de främsta mentorerna för Hordens häxmästare i Thralls huvudstad. Orcher är fortfarande misstänksamma mot ond magi efter sin tidigare demoniska korrumpering, så utövarna står under sträng uppsikt. Zevrost lär ut disciplinen som krävs för att betvinga demoner utan att ge efter för deras korrumpering. Han säger att ond magi bara fördärvar dem som saknar inre styrka."},{t="Att vägleda de ambitiösa",b="Zevrost vägleder häxmästare bortom besvärjelser och förbannelser och öppnar vägen till större mörka företag. Noviser som söker avancerade redskap som Orb of Orahil eller sätt att åkalla en flammande Felsteed passerar ofta genom hans händer. Han skickar ambitiösa utövare till andra mästare, däribland Menara Voidrender i The Barrens, så att de kan driva sitt herravälde över skuggmagi till dess yttersta gräns."}},faq={{q="Vem är Zevrost?",a="Zevrost tränar Hordens häxmästare i Cleft of Shadow under Orgrimmar. Han lär ut besvärjelser till både nybörjare och erfarna utövare och vägleder dem genom viktiga klassritualer.",al={"zevrosts roll","vem är zevrost","zevrost npc"}},{q="Var hittar man Zevrost?",a="Zevrost finns i Cleft of Shadow, en grotta under Orgrimmars huvudkvarter.",al={"zevrosts plats","var finns zevrost","hitta zevrost"}},{q="Varför tillåts häxmästare som Zevrost i Orgrimmar?",a="Thralls Horde låter häxmästare utöva sin magi i den avskilda Cleft of Shadow under sträng uppsikt. Orcher minns korrumperingen som demonblodet förde med sig, men Horden värdesätter den skoningslösa kraft som häxmästare kan rikta mot dess fiender.",al={"varför tillåts häxmästare i orgrimmar","häxmästare cleft of shadow"}},{q="Vad har Zevrost för syn på demonisk magi?",a="Zevrost tror att mörka och arkana energier bara korrumperar dem som har svag vilja. Han uppmanar sina elever att studera med sträng disciplin, så att de inte faller offer för de destruktiva krafter de betvingar.",al={"zevrosts citat","zevrosts tro"}}},fx={a3e2c8b2={q="Vems sida står Zevrost på?",a="Zevrost tjänar Horden som häxmästartränare i Orgrimmar. Många orcher misstror häxmästare på grund av Burning Blades mörka arv och demonisk korrumpering, men Zevrost utövar sin konst under staden och lär lojala utövare att bemästra demonisk magi säkert till hordens gagn.",al={"zevrosts fraktion","är zevrost lojal mot thrall","vem tjänar zevrost"}},["66627367"]={q="Vad vill Zevrost?",a="Zevrost söker disciplinerade häxmästare som kan bruka flyktig magi utan att ge efter för den. Han tror att magisk och demonisk kraft bara fördärvar de viljesvaga. Han vill träna elever som behåller strikt kontroll, så att de undgår undergång och kan tjäna Horden effektivt.",al={"zevrosts mål","vad önskar zevrost","zevrosts syfte"}}},fp="7,157,23.376.0,21.388.0,15.184.0,27.91.0,53.230.0,46.195.0"}
P.entries["npc:zjolnir"] = {n="Zjolnir",s="I Sen'jin Village föder Zjolnir upp rovfåglar åt Darkspear-ryttare och betrodda Horde-mästare. Hans tränade riddjur väcker stor kulturell stolthet hos trollryttarna.",h="I Sen'jin Village föder Zjolnir upp rovfåglar åt Darkspear-ryttare och betrodda Horde-mästare.",kw={"darkspear","durotar","riddjur","raptor","sen'jin village","trollriddjur","zjolnir"},ang={["faction:Horde"]="Som Horde-krigare kan du förtjäna rätten att rida en av Zjolnirs rovfåglar i strid genom att bevisa din orubbliga hängivenhet till Darkspear-stammen.",["race:Troll"]="Som Darkspear-troll kan du rida de snabba, klobeväpnade bestar som är centrala för ditt arv och dina stridstraditioner. Zjolnir tillhandahåller dem åt ditt folk."},sec={{t="Uppfödare av Darkspear Trolls raptorer",b="Nära hägnaderna i Sen'jin Village föder Zjolnir upp de vilda rovfåglar som Darkspear föredrar som riddjur. De är rovdjur med häftigt temperament och behöver en expert innan de kan tränas och sadlas för krig. Zjolnir ger gärna dessa värdefulla riddjur till andra troll som har lärt sig rida. Andra Horde-medlemmar måste först vinna Darkspear-stammens högsta förtroende innan han anförtror dem en av sina rovfåglar."}},faq={{q="Var hittar jag Zjolnir?",a="Zjolnir sköter rovfågelshägnen i Sen'jin Village, en Darkspear-bosättning på Durotars sydkust.",al={"zjolnirs plats","var finns zjolnir","raptorförsäljarens plats"}},{q="Vad säljer Zjolnir?",a="Zjolnir säljer rovfåglar som kallas fram med visselpipa, Darkspear-trollens rasmont. Hans utbud omfattar flera raser och färger för både nyutbildade ryttare och erfarna veteraner.",al={"zjolnir försäljare","vad säljer han","trollens riddjursförsäljare"}},{q="Kan andra än troll köpa raptorer av honom?",a="Ja. Icke-troll måste nå högsta anseende hos Darkspear Trolls innan Zjolnir säljer till dem. Troll kan köpa när de har den ridfärdighet som krävs.",al={"kan orcher köpa raptorer","vem kan köpa riddjur av zjolnir","hordens raptorriddjur"}}},fx={a5db9414={q="Vem är Zjolnir?",a="Zjolnir är en trollskötare och uppfödare bland Darkspear, med ansvar för stammens värdefulla raptorer. Han är stationerad i Sen'jin Village vid Durotars kust och förser sina trollfränder och betrodda hjältar i Horden, som visat sin hängivenhet till Darkspear-stammen, med tåliga raptor-riddjur.",al={"vem är zjolnir","zjolnirs bakgrund","vem säljer raptorer"}},["324eb78a"]={q="På vems sida står Zjolnir?",a="Han är djupt lojal mot Darkspear-stammen och Horden. Han bor i Sen'jin Village under hövdingen Vol'jins ledning och erbjuder sina noggrant tränade bestar enbart till sina stamfränder och utomstående som har uppnått upphöjd status hos Darkspear.",al={"zjolnirs fraktion","vem tjänar zjolnir","är zjolnir med horden"}},["58f60087"]={q="Varför är Zjolnir här?",a="Sen'jin Village är Darkspear-trollens främsta tillflyktsort vid kusten efter deras förvisning från Echo Isles. Zjolnir stannar här för att föda upp, ta hand om och förse stammen med dess vilda raptor-riddjur, som används av spejare, plundrare och ryttare som försvarar deras nya hem i Durotar.",al={"varför är zjolnir i sen'jin village","vad gör zjolnir här"}},["4b978e02"]={q="Vad vill Zjolnir?",a="Zjolnir vill se Darkspear-stammen väl beriden och stark. Han söker skickliga ryttare som kan hantera stammens rovdjurslika raptorer och anförtror de dödliga bestarna enbart åt trollfränder eller allierade vars tjänster och lojalitet mot Darkspear är ställda bortom allt tvivel.",al={"vad vill zjolnir","zjolnirs mål"}},bad296c7={q="Vilka är Zjolnir knuten till?",a="Han är direkt knuten till Darkspear-trollen och tjänar samhället som etablerats i Sen'jin Village. Hans arbete stödjer direkt stammens försvar och rörlighet under hövdingen Vol'jin och den större Horde-allians som grundades tillsammans med Thrall.",al={"zjolnirs anknytningar","vem arbetar zjolnir med"}}},fp="7,155,32.411.0,25.101.0,23.169.0,36.159.0"}
P.entries["npc:zor-lonetree"] = {n="Zor Lonetree",s="I Grommash Hold studerar Zor Lonetree Hordens angelägenheter bortom Durotar. Hans kunskap om Alliansens politik hjälper hovet att bedöma utrikesfrågor i Kalimdor.",h="I Grommash Hold studerar Zor Lonetree Hordens angelägenheter bortom Durotar.",kw={"rådgivare","alliansens politik","grommash hold","orgrimmar","stonetalon","valley of strength","zor lonetree"},ang={["class:Shaman"]="Som schaman som bemöter störda elementarkrafter har du ett gemensamt mål med Zor Lonetree, som vakar över de lidande andarna i Stonetalon Mountains.",["faction:Horde"]="Som spejare för Horden nära mänskliga enklaver eller omstridda gränser kan du vända dig till Zor Lonetree i Orgrimmar för att tolka fiendens avsikter och reliker."},sec={{t="Rådgivare i Grommash Hold",b="Zor Lonetree håller uppsikt bortom Durotar från Grommash Hold. Som en klarsynt rådgivare åt Hordens högsta ledning har han ovanligt god förståelse för människor och Alliansens politik. När främmande kuriositeter når Orgrimmar studerar han dem. När oro sprider sig bland landets andar leder han resenärer dit. Han har granskat ädla smycken som återfunnits i mänskliga bosättningar och följt oroligheter bland andarna i Stonetalon Mountains. På så vis håller han krigshövdingens hov informerat om både politiska och andliga frågor."}},faq={{q="Vem är Zor Lonetree?",a="Zor Lonetree ger Horden råd inifrån Grommash Hold i Orgrimmar. Hans goda förståelse för Alliansens politik och hans intresse för Kalimdors andliga angelägenheter gör honom till en värdefull rådgivare.",al={"zor lonetree vem är han","vem är zor","zor orgrimmar"}},{q="Var hittar jag Zor Lonetree?",a="Du hittar Zor Lonetree inne i Grommash Hold, i Visdomens dal i hjärtat av Orgrimmar.",al={"zor lonetree plats","var finns zor lonetree","zor i orgrimmar"}},{q="Vilka uppgifter ger Zor Lonetree äventyrare?",a="Zor Lonetree skickar Hordens förkämpar för att hjälpa andarna vid Stonetalon Peak och stilla den elementära oron i Stonetalon Mountains. Han analyserar också märkliga mänskliga reliker som spejare för med sig till huvudstaden.",al={"zor lonetree uppdrag","stonetalons andar zor"}},{q="Varför är Zor Lonetree kunnig om Alliansen?",a="Zor Lonetree är specialist på utrikesfrågor och statskonst. Han studerar mänskliga aristokratiska seder och Alliansens rörelser, vilket hjälper honom att tyda adliga sigillringar, regalier och taktiska motiv som andra orcher kanske förbiser.",al={"zor lonetree alliansens historia","varför kan zor alliansens politik"}}},fx={["2fe5d96a"]={q="På vems sida står Zor Lonetree?",a="Zor Lonetree står troget på Hordens sida. Från Grommash Hold, alldeles intill krigschefen Thralls närmaste krets i Orgrimmar, leder han krigare och spejare på sätt som främjar Hordens strategiska och territoriella intressen över hela Kalimdor.",al={"zor lonetrees fraktion","är zor lonetree med horden","vem tjänar zor"}},["74ebfad4"]={q="Vad vill Zor Lonetree?",a="Zor arbetar för att stärka Hordens fotfäste och skydda dess landområden. Han söker information om yttre hot, däribland genom att studera Alliansens rörelser och artefakter, och ger betrodda hjältar i uppdrag att lugna oroliga krafter, som den rastlösa jorden och andarna i Stonetalon Mountains.",al={"vad vill zor","zor lonetrees motiv","zor lonetrees mål"}},["891b1ec8"]={q="Varför är Zor Lonetree här i Grommash Hold?",a="Zor bor i Grommash Hold och är rådgivare och samordnare åt Hordens ledning. Han är ovanligt väl insatt i Alliansens politik, vilket gör hans närvaro ovärderlig för krigschefen när denne bedömer yttre hot, utländska adelsintriger och regionala andliga oroligheter på Kalimdor.",al={"varför är zor i grommash hold","varför är zor lonetree i orgrimmar","zor lonetrees roll"}},ebf76354={q="Vilka är Zor Lonetree knuten till?",a="Zor arbetar nära viktiga spejare och agenter för Horden i fält, däribland Nazeer Bloodpike i Brackenwall Village i Dustwallow Marsh. Han analyserar rapporter från gränstrakterna och ger råd till ledarna som samlats i Grommash Hold.",al={"zor lonetrees kontakter","vem arbetar zor med","zor lonetrees allierade"}}},fp="12,167,24.532.0,20.182.0,30.98.0,46.201.0,53.215.0"}
P.entries["npc:zureetha-fargaze"] = {n="Zureetha Fargaze",s="I Valley of Trials håller Zureetha Fargaze utkik efter hot mot hordens unga rekryter. Tillsammans med Foreman Thazz'ril i Durotar skickar hon dem för att avslöja och röja ut kulten Burning Blade, som gömmer sig i dalen.",h="I Valley of Trials håller Zureetha Fargaze utkik efter hot mot hordens unga rekryter.",kw={"burning blade","burning blade medallion","durotar","foreman thazz'ril","valley of trials","zureetha fargaze"},ang={["class:Warlock"]="Som trollkarl i Valley of Trials möter du Zureethas första uppdrag och ställs mot de fördärvade, vidriga tjänsteandar som hör samman med Burning Blades mörka åkallelser.",["race:Orc"]="Som ung orch som tar dina första steg ut i världen ser du hos Zureetha den vaksamhet som krävs för att hindra det förflutnas demoniska smitta från att förorena ditt nya hemland."},sec={{t="Ögon i dalen",b="Zureetha Fargaze håller utkik efter faror utöver arbetet och disciplinen som Foreman Thazz'ril ansvarar för. Kulten Burning Blade har i hemlighet tagit sig in i Valley of Trials, fördärvat mindre demoner och samlat styrka i den närbelägna Burning Blade Coven. Hon skickar oprövade äventyrare för att hämta medaljonger från kultisterna, bekräfta deras närvaro och störa deras första försök. Sedan leder hon erfarna rekryter längre in i Durotar."}},faq={{q="Vem är Zureetha Fargaze?",a="Zureetha Fargaze vakar över Valley of Trials i Durotar. Hon står nära Foreman Thazz'ril och håller utkik efter dolda hot mot träningsmarkerna.",al={"zureetha fargazes historia","vem är zureetha","fargaze valley of trials"}},{q="Varför oroar hon sig för Burning Blade?",a="Kulten Burning Blade har fått fäste i en närbelägen grotta, där den samlar vidriga tjänsteandar och fördärvar de fridfulla prövningsmarkerna. Zureetha skickar rekryter för att hämta kultistmedaljonger som bevis och decimera kultens led.",al={"burning blade valley of trials","varför vill zureetha ha medaljonger","burning blade-kulten durotar"}},{q="Vart skickar hon rekryterna efter deras första prövningar?",a="När unga orcher och troll har bevisat sig mot lokala hot skickar Zureetha dem sydost över bergsryggen till Sen'jin Village för att hjälpa Darkspear-stammen.",al={"vart går jag efter zureetha","zureethas nästa uppdrag","rapportera till sen'jin"}}},fx={b30f15ad={q="På vems sida står Zureetha Fargaze?",a="Zureetha står stadigt på Thralls Hordes sida. Hon är stationerad i Valley of Trials tillsammans med Foreman Thazz'ril, och hennes uppgift är att vägleda unga rekryter och skydda träningsområdet från inre fördärv och dolda fiender.",al={"zureetha fargazes fraktion","vem tjänar zureetha","är zureetha med horden"}},["497b9432"]={q="Varför är Zureetha Fargaze här i Valley of Trials?",a="Hon är placerad i Valley of Trials för att hålla uppsikt över de nyanlända orcherna och trollen när de börjar sin träning. Än mer angeläget är att hon vakar mot Burning Blade-kultens skuggor, som har börjat smyga sig in i grottorna i dalens närhet.",al={"varför är zureetha i valley of trials","zureethas syfte i durotar","varför är zureetha här"}}},fp="16,210,18.429.0,24.150.0,45.218.0,56.161.0"}
P.entries["quest:10"] = {n="The Scrimshank Redemption",s="I Gadgetzan är Senior Surveyor Fizzledowser bekymrad: Junior Surveyor Scrimshank, en av hans främsta assistenter, skickades till The Gaping Chasm, ett ökenområde sydost om staden, och har försvunnit. Du ombeds ta reda på vad som hänt Scrimshank, eller åtminstone hitta mätutrustningen.",h="I Gadgetzan är Senior Surveyor Fizzledowser bekymrad: Junior Surveyor Scrimshank, en av hans främsta...",kw={"fizzledowser","gadgetzan","the gaping chasm","scrimshank","mätning","tanaris"},sec={{t="En försvunnen mätare",b="Senior Surveyor Fizzledowser är bekymrad. Junior Surveyor Scrimshank begav sig till The Gaping Chasm och har inte synts till sedan dess, och den senaste rapporten därifrån nämnde fler av de där märkliga insekterna. Fizzledowser undrar om insekterna nu har tagit över två stora områden av öknen på en gång. Du ombeds bege dig dit och leta efter Scrimshank, eller i andra hand efter mätutrustningen, som Fizzledowser befarar kan vara det enda som finns kvar."},{t="Fizzledowsers dom",b="Scrimshank, en bra goblin enligt Fizzledowser, överlevde inte. Fizzledowser hoppas att förlusten betyder något med tanke på vad mätutrustningen lyckades registrera. Insekterna visar en oroande list, och forskningen hittills tyder på att en tredje part styr dem, vilket bådar illa för Gadgetzan och hela öknen."}},faq={{q="Vem är Senior Surveyor Fizzledowser?",a="Fizzledowser är Senior Surveyor i Gadgetzan. Han har undersökt öknens märkliga insekter och är Scrimshanks överordnade.",al={"fizzledowser","vem ger det här uppdraget","mätaren fizzledowser"}},{q="Vem är Junior Surveyor Scrimshank?",a="Scrimshank var Fizzledowsers främsta assistent. Han skickades till öknen sydost om Gadgetzan och försvann där.",al={"scrimshank","vem är scrimshank","junior mätare"}},{q="Var ligger The Gaping Chasm?",a="Det är ökenområdet sydost om Gadgetzan som mätarna kallar The Gaping Chasm.",al={"gaping chasm plats","var ligger gaping chasm","plats för klyftan"}},{q="Vad kom före det här steget?",a="Det följer efter Noxious Lair Investigation.",al={"föregående uppdrag","förutsättning","vilket uppdrag kommer först"}}},fp="25,284,23.422.0,22.325.1,36.131.0,34.110.0,34.89.0,27.42.0"}
P.entries["quest:100"] = {n="Call of Water",s="Detta rituella steg markerar höjdpunkten i shamanens prövning vid Brazier of Everfount längs Silverpine Forests kust. Efter att ha krossat de fördärvade andarna som hotade källan med ett utbrott av elementärt ljus står shamanen inför en uppenbarelse av rent vatten för att ta emot dess gemenskap.",h="Detta rituella steg markerar höjdpunkten i shamanens prövning vid Brazier of Everfount längs Silverpine...",kw={"brazier of everfount","call of water","elementär","minor manifestation of water","shamanprövning","silverpine forest","water totem"},ang={["class:Shaman"]="Denna gemenskap prövar direkt en shamans beslutsamhet att läka lidande vatten långt från hemtrakterna och vinna gemenskap med själva vattenanden.",["faction:Horde"]="Hordens andliga ledare måste rena fördärvade vattendrag även i territorier under de Fördärvades kontroll, som Silverpine, för att bevara den elementära harmonin."},sec={{t="Ett utbrott av renande ljus",b="När den sista besvärjelsen läses upp vid Brazier of Everfount sveper en ljusexplosion bort områdets kringliggande fördärv. De förgiftade vattendropparnas väsande protester när de förångas över elementareld tonar bort, och den närmaste stranden blir tyst när de illvilliga mindre andarna skingras."},{t="Vattnets tacksamhet",b="Efter andarnas förintelse visar sig en Minor Manifestation of Water bredvid eldstaden. Anden är tacksam för ritualens ingripande och ser den växande börda som vilar på Hordens shamaner: även om den lokala föroreningen har avtagit, fortsätter livet i Silverpines förfallande marker att sina och kräver vaksamhet för att bevaras."}},faq={{q="Vad händer när ritualen vid eldstaden är klar?",a="När besvärjelsen fullbordas vid Brazier of Everfount frigörs en explosion av strålande ljus. Den förstör de fördärvade andarna i området och renar det närmaste elementflödet.",al={"rituell eldskål ljus","explosion vid everfount"}},{q="Vad är Minor Manifestation of Water?",a="Det är en mindre elementvarelse av rent vatten som visar sig efter att de fördärvade elementvarelserna nära Brazier of Everfount har förstörts.",al={"vattenande silverpine","vattnets uppenbarelse"}},{q="Vad säger vattenanden om Silverpine?",a="Anden tackar shamanerna och påpekar att även om just denna förorening har avtagit, fortsätter livet i hela landet att sina och kräver ständig omsorg för att skyddas.",al={"vattenandens varning","fördärv i silverpine"}},{q="Var äger ritualen rum?",a="Ritualen äger rum vid Brazier of Everfount, som ligger längs Silverpine Forests kust.",al={"eldskålens plats","call of water plats"}},{q="Varför måste shamaner ingripa i Silverpine?",a="Som en del av sina elementära prövningar för att förtjäna Water Totem måste shamaner visa sitt engagemang för balansen genom att försvara avlägsna, hårt ansatta naturvatten mot farsot och kvardröjande fördärv.",al={"varför shamaner här","shamanens plikt i silverpine"}},{q="Vad händer härnäst i prövningarna?",a="Efter att ha talat med Minor Manifestation of Water får shamanen elementära kvarlevor eller vägledning för att slutföra sin färd och smida sin Water Totem.",al={"nästa steg call of water","efter vattenuppenbarelsen"}}},fp="13,161,26.157.0,21.277.0,46.162.0,40.156.0,48.150.0,34.89.0,41.179.0,30.146.0"}
P.entries["quest:1001"] = {n="Buzzbox 411",s="Buzzbox 411 är ett alliansuppdrag längs Darkshores vindpinade kust. Den berusade uppfinnaren Wizbang Cranktoggle använder ett egensinnigt nätverk av mekaniska reläer och ber resande samla kustnära Thresher Eyes för att få igång sin andra forskningsmaskin igen.",h="Buzzbox 411 är ett alliansuppdrag längs Darkshores vindpinade kust.",kw={"auberdine","buzzbox 411","crawler wine","darkshore","gnom","thresherögon","mekande","wizbang cranktoggle"},ang={["profession:Engineering"]="Att använda organiska thresherögon för att kalibrera en mekanisk sändare visar de egensinniga och gränsöverskridande metoder som okonventionella uppfinnare föredrar.",["race:Gnome"]="Wizbang Cranktoggle står för det typiskt gnomiska sättet att bedriva fältarbete: djärv innovation, märkliga komponentval och att låta den som råkar passera sköta den farliga simningen.",["race:NightElf"]="Auberdines väktare håller noggrann uppsikt över Darkshores vatten, men brukar låta märkliga gnomiska apparater på stranden sköta sig själva."},sec={{t="En röst genom bruset",b="Efter att ha hjälpt till att reparera Buzzbox 827 längre söderut hörs den gnomiska uppfinnaren Wizbang Cranktoggle återigen spraka genom den mekaniska sändaren. Wizbang befinner sig på en trygg plats utom synhåll och leder äventyrare längre norrut längs Darkshores dimhöljda strand för att hitta ännu en skadad terminal: Buzzbox 411. Mellan sändningarna, som avbryts av hickningar och mumlade lovord om crawler wine, avslöjar han att traktens vattenrovdjur har de komponenter som behövs för att hålla hans kustapparat i drift."},{t="Ögon under vågorna",b="För att återställa Buzzbox 411 måste du dyka ner i det kalla, turbulenta vattnet utanför Auberdines kust. Darkshore Threshers stryker omkring på grunt vatten. Dessa aggressiva havsdjur har ögonorgan med precis de egenskaper som Wizbang säger behövs för att kalibrera om apparaten. När du matar in de efterfrågade Thresher Eyes i maskinens väntande lucka rycker apparaten igång igen. Du får en belöning för leveransen, och en ny uppgift öppnar sig på linjen, allt mer sluddrigt framförd."}},faq={{q="Vad är Buzzbox 411?",a="Buzzbox 411 är en mekanisk sändare på stranden norr om Auberdine, längs Darkshores kust. Den ingår i ett experimentellt nätverk för avlyssning och forskning som drivs av den gnomiska ingenjören Wizbang Cranktoggle.",al={"buzzbox 411","vad är buzzbox 411","buzzbox 411:s syfte"}},{q="Vem är Wizbang Cranktoggle?",a="Wizbang Cranktoggle är en egensinnig gnomisk uppfinnare som kommunicerar på distans genom Buzzbox-nätverket. Under sitt fältarbete dricker han gärna mycket crawler wine och förlitar sig på förbipasserande äventyrare för det farliga arbetet med att samla in djurdelar.",al={"wizbang","vem är wizbang","vem byggde buzzbox"}},{q="Varför behöver en maskin Thresher Eyes?",a="Gnomisk ingenjörskonst blandar ofta märkliga organiska ämnen med mekaniska delar för att utföra okonventionella uppgifter. Oavsett om Wizbang verkligen behöver ögonen till optiska sensorer eller bara använder dem i biologisk forskning medan han är full, insisterar han på att de är nödvändiga för att reparera Buzzbox 411.",al={"varför thresherögon","thresherögon till maskinen","buzzboxögon"}},{q="Var ligger Buzzbox 411?",a="Buzzbox 411 står direkt på stranden i Darkshore, norr om nattalvernas bosättning Auberdine.",al={"var ligger buzzbox 411","buzzbox 411:s plats","hitta buzzbox 411"}},{q="Var hittar jag Darkshore Threshers?",a="Darkshore Threshers simmar i kustvattnen utanför Auberdine och längs de närliggande stränderna. Du hittar dem lätt genom att simma ut förbi bränningarna.",al={"var finns threshers","varifrån kommer thresher eyes","thresherns plats"}},{q="Vad händer när Buzzbox 411 är lagad?",a="När Buzzbox 411 börjar surra igen tackar Wizbang Cranktoggle dig genom bruset, sveper ännu en drink och frågar genast om du kan laga hans nästa maskin, Buzzbox 323.",al={"nästa buzzbox","vad händer efter buzzbox 411","buzzbox-kedjan"}}},fx={e6ddd018={q="Varför vill Wizbang Cranktoggle att Buzzbox 411 repareras?",a="Wizbang Cranktoggle arbetar längs Darkshores kust för att återställa sitt nätverk av automatiska kommunikationsenheter. Han sköter maskinerna på distans och förlitar sig på förbipasserande äventyrare för att få tag på lokala organiska komponenter. På så sätt kan han hålla sina apparater igång ute i vildmarken utan att behöva avbryta drickandet i lägret.",al={"wizbangs motiv","varför reparera buzzbox 411","varför behöver wizbang detta"}},b4fb6bd9={q="Vad är Darkshore-threshers?",a="Darkshore-threshers är rovgiriga havsbestar som stryker omkring i det kalla kustvattnet utanför Auberdine. De har skarpa sinnen och flera ögonlinser som passar i grumliga djup. Deras kroppsdelar råkar ha de ovanliga optiska egenskaper som Wizbang behöver för att kalibrera Buzzbox 411:s mekanismer.",al={"darkshore-threshers","vilka är threshers","vad är threshers"}},["5ee0d229"]={q="Varför behöver Wizbang dig i stället för att göra det själv?",a="Wizbang är en excentrisk uppfinnare som uppenbart föredrar bekvämligheten i sin verkstad och en stadig tillgång på crawler-vin framför att trotsa det iskalla bränningarna. Eftersom farliga threshers stryker omkring i kustvattnen kan han utöka sitt nätverk utan att lämna pallen genom att låta skickliga äventyrare sköta jakten och reparationerna i fält.",al={"varför jag åt buzzbox 411","varför gör wizbang det inte själv","varför behöver wizbang en äventyrare"}}},fp="11,224,24.451.0,21.369.0,20.203.0,27.237.0,38.219.0,29.89.0,36.134.0,40.156.0"}
P.entries["quest:1002"] = {n="Buzzbox 323",s="Buzzbox 323 är det tredje uppdraget i en fältforskningskedja längs Darkshores kust, beställd via en högtalare av den excentriske gnomingenjören Wizbang Cranktoggle. Du ska samla in Moonstalker-huggtänder från traktens rovdjur och lägga dem i den surrande apparaten norr om Auberdine.",h="Buzzbox 323 är det tredje uppdraget i en fältforskningskedja längs Darkshores kust, beställd via en högtalare...",kw={"auberdine","buzzbox","buzzbox 323","cranktoggle","darkshore","huggtänder","moonstalker","wizbang"},ang={["profession:Engineering"]="Buzzbox-serien visar hur automatiserad materialbearbetning kombineras med långdistansöverföring av röster, en imponerande teknisk konstruktion trots den skakiga driften.",["race:Gnome"]="Wizbangs fjärrstyrda nätverk för ljudkommunikation visar prov på typisk gnomisk uppfinningsrikedom, även om hans personliga disciplin lämnar en del övrigt att önska.",["race:NightElf"]="Medan nattalverna som bor här behandlar de vilda Moonstalkers med vördnadsfull försiktighet, gör gnomisk vetenskap deras dödliga huggtänder till krossat maskinbränsle."},sec={{t="Ett sluddrigt meddelande",b="Efter att ha använt Buzzbox 411 längre söderut sprakar den gnomiska uppfinnaren Wizbang Cranktoggles röst till liv ur högtalaren. Mellan ljud av häftigt drickande och sluddriga vägbeskrivningar skickar Wizbang äventyrarna norr om Auberdine, till Buzzbox 323 nära en vägbro. För hans forskning behövs sex Moonstalker-huggtänder från de vilda kattjägarna som strövar i Darkshores skuggiga skogar."},{t="Gnomisk fältutrustning",b="När du närmar dig Buzzbox 323 hörs ett sprakande och ett svagt mummel från maskinen, redan innan du börjar reparera den. Så snart du lägger de efterfrågade huggtänderna i intagstratten skakar maskinen våldsamt igång och mal högljutt ner tänderna till damm. Wizbangs berusade röst återkommer genast över sändaren. Han firar leveransen och skickar sedan resenären vidare till nästa maskin i sitt utspridda nätverk."}},faq={{q="Var ligger Buzzbox 323?",a="Buzzbox 323 står vid huvudvägen norr om Auberdine, nära bron över den lokala floden i Darkshore.",al={"buzzbox 323 plats","var ligger buzzbox 323","hitta buzzbox 323"}},{q="Vem talar genom Buzzbox?",a="Rösten tillhör Wizbang Cranktoggle, en gnomuppfinnare som befinner sig någon annanstans i Darkshore. Han kommunicerar via fjärrsändare medan han dricker stora mängder öl.",al={"vem talar i buzzbox","buzzbox gnom","wizbang cranktoggle"}},{q="Vad gör Buzzbox 323 med huggtänderna?",a="När du släpper ner Moonstalker-huggtänderna mals de genast till fint pulver av maskinens inre kugghjul. Det är en del av Wizbangs automatiserade biologiska provtagningsmekanism.",al={"vad händer med huggtänderna","varför moonstalker-huggtänder","buzzbox malning"}},{q="Var hittar jag Moonstalkers i Darkshore?",a="Moonstalkers och deras små ungar strövar i de skuggiga skogarna och kullarna längs vägen, både norr och söder om Auberdine.",al={"var finns moonstalkers","farma moonstalker-huggtänder","moonstalkers plats"}},{q="Vilket uppdrag kommer före och efter Buzzbox 323?",a="Det här uppdraget följer på Buzzbox 411, som krävde threshers ögon, och följs direkt av Buzzbox 525. Där ska du samla grånade skalper från tistelbjörnar långt söderut längs vägen.",al={"buzzbox-uppdragskedja","vad följer efter buzzbox 323","buzzbox-ordning"}},{q="Varför låter Wizbang så osammanhängande?",a="Wizbang är redlöst berusad medan han ger instruktioner. Han pausar för att leta efter sin öl och tar högljudda klunkar mellan meningarna.",al={"varför är wizbang full","buzzbox sluddrig röst"}}},fx={c1fdd18c={q="Varför vill Wizbang att Moonstalker-fångar placeras i Buzzbox 323?",a="Wizbang arbetar sig igenom underhållet av sitt nätverk av automatiska Buzzbox-provtagningsmaskiner som är utspridda över Darkshore. Varje apparat är konstruerad för att bearbeta delar från det lokala djurlivet, och Buzzbox 323 behöver särskilt sex Moonstalker-fångar för att kalibrera sina inre malmekanismer och fortsätta sitt gåtfulla fältarbete.",al={"varför buzzbox 323","wizbangs motiv med buzzbox","varför moonstalker-fångar"}},["78de9795"]={q="Vad är Moonstalkers som du skickas ut för att jaga?",a="Moonstalkers är smygande sabelkatter som hör hemma i Darkshores skuggiga skogar. De stryker omkring bland forntida ruiner och snåriga skogsområden, jagar under den eviga skymningens täcke och ger sig på resenärer som vandrar för långt från Auberdines bevakade vägar.",al={"vad är moonstalkers","moonstalkers i darkshore","vilka är målen"}}},fp="11,184,22.315.0,23.330.0,29.108.0,36.120.0,40.136.0,43.110.0,46.180.0,37.128.0"}
P.entries["quest:1003"] = {n="Buzzbox 525",s="Buzzbox 525 är den sista i en serie talande maskiner längs Darkshores kust. Den excentriske gnomuppfinnaren Wizbang Cranktoggle byggde dem. Maskinen kräver djurrester för att fungera och ber resenärer om allt märkligare reparationsmaterial.",h="Buzzbox 525 är den sista i en serie talande maskiner längs Darkshores kust.",kw={"auberdine","buzzbox 525","darkshore","grizzled scalp","tisteltaggbjörn","tisteltaggbjörnöl","wizbang cranktoggle"},ang={["race:Gnome"]="Wizbangs mångsidiga transceivrar visar prov på typisk gnomisk ambition och blandar avancerad ingenjörskonst med tveksamma praktiska prioriteringar.",["race:NightElf"]="Darkshores strikta naturvård lämnar föga utrymme för vårdslöst gnomiskt experimenterande."},sec={{t="Ett sluddrigt meddelande",b="Efter att ha servat Buzzbox 323 får resenärerna förvrängda instruktioner som sänds direkt genom maskinens skallrande högtalare. Wizbang Cranktoggles tal blir allt sluddrigare, fyllt av berusat fniss och virriga vägbeskrivningar långt söderut längs Darkshores huvudväg. Han ber sina medhjälpare jaga områdets grånade tisteltaggbjörnar och lägga fyra av deras tjocka skalper i facket på Buzzbox 525, som är noggrant gömd bakom ett staket i snåren vid vägen."},{t="Destillatörens hemlighet",b="När de kommer fram till den gömda maskinen dränks dess nyfikna surr av högljudd sång som ekar inifrån järnhöljet. När grizzlybjörnsskalperna läggs i behållaren avslöjar Wizbang till slut sanningen om sitt nätverk. Maskinerna är mycket mer än enkel kommunikationsutrustning: de fungerar också som automatiserade mikrobryggerier och destillerier. Nattalverna uppskattar inte hans sprithandel i sina städer, så gnomen gömde maskinerna ute i vildmarken och använder djurdelar, som björnsskalper, för att brygga starka satser av ”tisteltaggbjörnöl”."}},faq={{q="Var ligger Buzzbox 525?",a="Buzzbox 525 står långt söderut längs huvudvägen från Auberdine. Wizbang gömde den strax intill stigen vid ett rustikt staket, delvis dold under buskar.",al={"buzzbox 525 plats","var ligger buzzbox 525","hitta buzzbox 525"}},{q="Varför vill Wizbang ha grånade skalper?",a="Wizbang hävdar att skalperna behövs för att reparera Buzzbox 525, precis som de tidigare maskinerna behövde krabbarben, tröskarfiskögon och månstalkertänder. Den berusade sången om tisteltaggbjörnöl som hörs från lådan antyder ett annat syfte.",al={"varför grånade skalper","buzzbox björnsskalper","vad ska skalperna användas till"}},{q="Varför gömmer Wizbang Buzzboxarna ute i vildmarken?",a="Wizbang placerade maskinerna utanför Auberdine och förlitar sig på att resenärer hittar fram till dem. Den sista Buzzbox avslöjar varför han valde dessa avskilda platser.",al={"varför är buzzboxarna gömda","varför gömma buzzbox","wizbangs hemlighet"}},{q="Vem talar genom Buzzboxen?",a="Rösten tillhör Wizbang Cranktoggle, en driftig gnomuppfinnare som installerade röst­sändare i sina Buzzboxar runt om i Darkshore.",al={"vem talar i buzzboxen","buzzboxens röst","vem är wizbang"}},{q="Kan Wizbang tala genom maskinen utan skalperna?",a="Ja. Wizbang kan tala genom maskinen innan skalperna läggs i. Han förklarar varför han bad om materialet när uppgiften är slutförd.",al={"är buzzboxen trasig","ljög wizbang"}},{q="Vilken sång sjunger Buzzboxen?",a="Innan du lägger i skalperna mässar högtalaren upprepade gånger en berusad limerick: ”Krabbarbsvin må vara sött, tröskaröl gott, och månstalkarsprit är grand. Men inget är kärare än tisteltaggbjörnöl, snart har jag det i min hand!”",al={"buzzboxsång","sång om tisteltaggbjörnöl"}}},fx={["7fe06fd4"]={q="Vad skickas du ut för att jaga åt Buzzbox 525?",a="Wizbang behöver grånade skalper för att hålla sin Buzzbox igång.",al={"vad ska jag döda åt buzzbox 525","buzzbox 525:s mål","grånade tistelbjörnar i darkshore"}},["4f91b84e"]={q="Varför ber Wizbang dig i stället för vaktposterna att samla björnskalper?",a="Wizbang förlitar sig på resenärer som kan nå hans avskilda apparater och samla in de efterfrågade djurdelarna. Han förklarar sitt val av platser när arbetet är klart.",al={"varför inte fråga vaktposterna","varför behöver wizbang mig till buzzbox","varför fråga en äventyrare om buzzbox"}}},fp="11,189,22.404.0,22.428.1,29.131.0,38.215.1,58.190.1,36.138.0,57.125.1,32.245.0"}
P.entries["quest:1007"] = {n="The Ancient Statuette",s="Talen, en alv som slagit läger nära den farliga The Zoram Strand i nordvästra Ashenvale, söker en förlorad relik. Efter ett bakhåll av skoningslösa naga och en våldsam grundstötning tappade han sin älskade forntida statyett i bränningarna och behöver en äventyrare som hämtar den ur ruinerna.",h="Talen, en alv som slagit läger nära den farliga The Zoram Strand i nordvästra Ashenvale, söker en förlorad...",kw={"ancient statuette","ashenvale","naga","zorams ruiner","ruuzel","talen","the zoram strand"},ang={["faction:Alliance"]="Alliansens styrkor som rycker fram genom Ashenvale hotas inte bara av Hordens utposter i öster, utan också av fientliga naga som gör anspråk på den västra kusten.",["race:NightElf"]="Zorams ruiner vittnar om Kaldoreis förlorade civilisation från tiden före den Stora Sunderingen. Att bevara föremål som den här statyetten är därför en del av minnet av förfäderna."},sec={{t="Bakhåll vid kusten",b="De sjunkna ruinerna av Zoram längs Ashenvales nordvästra kust har länge lockat dem som är nyfikna på nattalvernas forntida förflutna. Talen färdades genom det grunda vattnet i en liten båt när fientliga naga dök upp och gick till angrepp med klor och treuddar. Han lyckades ta sig i land med knappa förnödenheter och slå läger i all hast, men i sin desperata flykt för livet tappade han sitt mest värdefulla fynd i sanden."},{t="Gamla Zorams hemligheter",b="Den forntida statyetten som ligger halvt begravd på stranden är mer än en enkel souvenir. Talen anser att den är hela skälet till att trotsa monstren vid The Zoram Strand. När han får tillbaka den avslöjar han att den drunknade staden rymmer århundraden av glömda mysterier och att den sköra snidningen är en viktig nyckel till att förstå vad som fortfarande döljer sig under tidvattnet."}},faq={{q="Vem är Talen och varför är han ensam vid The Zoram Strand?",a="Talen är en alvutforskare som slagit läger längs den södra kanten av The Zoram Strand. Hans historiska nyfikenhet drev honom att utforska Zorams sjunkna ruiner, men skoningslösa naga överföll hans båt och spolade upp honom på stranden.",al={"vem är talen","talen i wow","talen ashenvale"}},{q="Var tappade Talen statyetten?",a="Talen tappade snidningen nära stranden norr om sitt läger. Den ligger halvt begravd i sanden vid en vält båt och ett fallet träd, längs bränningarna där hans båt angreps.",al={"var finns ancient statuette","statyettens plats","hitta ancient statuette"}},{q="Vad är den forntida statyetten?",a="Det är en forntida nattalverelikt som bärgats ur Zorams nedsänkta ruiner. Enligt Talen har snidningen historisk och mystisk betydelse och fungerar som en viktig nyckel till att låsa upp den drunknade stadens kvarvarande hemligheter.",al={"vad är statyetten","statyettens betydelse"}},{q="Varför finns det naga vid The Zoram Strand?",a="Ashenvales kust rymmer forntida alvruiner från tiden före Sunderingen, som sjönk i havet för tiotusen år sedan. Naga har gjort Zorams dränkta byggnader till sitt revir och patrullerar stränderna aggressivt för att hålla främlingar borta.",al={"varför finns naga här","naga vid zoram strand","naga i ashenvale"}},{q="Vad händer när statyetten lämnas tillbaka?",a="När statyetten återfås kan Talen tyda fler av traktens mysterier. Men för att hantera hotet från naga längs stranden krävs fler insatser, och du leds vidare till deras ledare, Ruuzel.",al={"vad händer efter statyetten","fortsättning på uppdraget"}},{q="Vaktas statyetten?",a="Statyetten ligger vid vattenbrynet i ett område fullt av fientliga nagakrigare och rovdjur som stryker längs stranden. Därför är det farligt för ensamma vandrare att hämta den.",al={"vaktas statyetten","fiender nära statyetten"}}},fx={["16a428a2"]={q="Varför vill Talen att Ancient Statuette hämtas?",a="Den uråldriga statuetten är Talens käraste ägodel och hela anledningen till att han vågade sig till det farliga Zoram Strand. Han tror att ruinerna under vattnet i det forntida Zoram döljer stora hemligheter och att reliken kan vara nyckeln till att avslöja dem. Efter att ha flytt med livet i behåll när naga överföll honom står han inte ut med att lämna sitt livsverk i sanden.",al={"varför vill talen ha statuetten","talens motiv","varför behöver talen statuetten"}},ceee75b8={q="Varför kan Talen inte hämta statuetten själv?",a="Talen överlevde nätt och jämnt sitt första möte ute på vattnet. När naga svärmade upp ur djupet och slet sönder hans lilla farkost med sina klor tog han sig i land med bara knappa förnödenheter innan han flydde i skräck. Skakad, sårad och utan militärt stöd på den avlägsna kusten är han inte i skick att möta strandens lurande bestar och aggressiva naga för att hämta det han tappade.",al={"varför kan talen inte hämta den själv","varför behöver talen mig","varför behöver talen hjälp"}}},fp="21,187,19.300.0,20.262.0,47.196.0,35.183.0,30.193.0,39.209.0,43.150.1,25.161.0"}
P.entries["quest:1008"] = {n="The Zoram Strand",s="Shindrell Swiftfire från Astranaar ger Alliansens hjältar i uppdrag att genomsöka Ashenvales nordvästra kust, där en uråldrig, ruinerad stad ligger. Naga har dykt upp i stort antal längs The Zoram Strand och hotar att tränga in från havet. Genom att hejda deras fotfäste skyddar du skogen från ett hemsökande eko av nattalvernas avlägsna förflutna.",h="Shindrell Swiftfire från Astranaar ger Alliansens hjältar i uppdrag att genomsöka Ashenvales nordvästra kust...",kw={"ashenvale","astranaar","nagor","shindrell","strand","sunderingen","swiftfire","wrathtail","zoram"},ang={["class:Hunter"]="Den vindpinade kusten och de sönderslagna ruinerna erbjuder utmärkta utsiktspunkter för att spåra de amfibiska plundrarna när de kommer upp ur vågorna.",["faction:Alliance"]="Genom att säkra Ashenvales västra flank hindrar du Astranaar från att hamna mellan inkräktare från kusten och Hordes framryckande timmerverksamhet.",["race:NightElf"]="Varje naga som dödas på stranden är en bister påminnelse om Azsharas högmod och Sunderingen som krossade den forntida världen. Väktarna kommer aldrig att låta dessa förvridna fränder återta mark i Kalimdor."},sec={{t="Skuggor vid stranden",b="Nordväst om Astranaar, där Ashenvales täta trädkronor möter Veiled Sea, ligger den vindpinade kust som kallas The Zoram Strand. Stranden har länge varit tyst och beströdd med de blekta stenarna från en civilisation som slets sönder för tiotusen år sedan, men nu vimlar den plötsligt av ormlika fasor. Wrathtail-nagorna har slingrat sig upp ur de mörka tidvattnen och upprättat ett fientligt brohuvud precis vid gränsen till nattalvernas territorium."},{t="Den dränkta staden Zoram",b="Under de piskande vågorna vilar den dömda staden Zoram, krossad och nedsänkt under den stora klyvningen. I långa tider förblev den en övergiven relik, nästan bortglömd av kaldorei. Nagornas plötsliga uppdykande bland ruinerna väcker bittra minnen hos Astranaars försvarare. Väktare som Shindrell Swiftfire känner igen de ormlika inkräktarna som förvridna fränder, sprungna ur deras egen uråldriga katastrof, och vägrar låta djupen ta stranden ännu en gång."}},faq={{q="Vad är The Zoram Strand?",a="The Zoram Strand är Ashenvales karga nordvästra kust, vänd mot Veiled Sea. Där låg det forntida Zoram, en kaldorei-stad som svaldes av havet under Sunderingen för tiotusen år sedan.",al={"the zoram strand","var ligger zoram strand","vad är zoram"}},{q="Varför anfaller nagorna Ashenvales kust?",a="Väktarna i Astranaar känner inte till deras exakta motiv. Vad som än lockade dem upp ur djupen gör deras militära läger och aggression dem till ett omedelbart hot mot skogarna, och tvingar nattalverna att slå till i förebyggande syfte.",al={"varför är nagorna här","nagornas motiv vid zoram","varför wrathtail"}},{q="Vem är Shindrell Swiftfire?",a="Shindrell Swiftfire är en nattalvsväktare stationerad i hjärtat av Astranaar. Hon bevakar hot mot Ashenvale i regionen och organiserar anfall mot fientliga intrång, däribland nagorna vid kusten.",al={"shindrell","uppdragsgivare i astranaar","swiftfire"}},{q="Vilken historia delar nattalverna med nagorna?",a="Nagorna var en gång högborna nattalver som tjänade drottning Azshara. När Evighetens brunn kollapsade under Sunderingen drogs de ner i avgrundens djup och förvandlades till ormlika varelser, vilket gör varje möte djupt bittert för dagens kaldorei.",al={"koppling mellan nagor och alver","historia med nagorna","delad historia"}},{q="Vad händer när The Zoram Strand har rensats?",a="När nagorna längs stranden har blivit färre skickar Shindrell Swiftfire Alliansens försvarare vidare för att hantera andra luftburna hot som dykt upp vid gränsen. Hon skickar spejare söderut mot Stonetalon för att ta hand om våldsamma pridewings.",al={"nästa uppdrag","vad händer efter zoram strand","pridewings"}},{q="Är Horde också närvarande vid The Zoram Strand?",a="Ja. Medan Alliansens hjältar från Astranaar jagar nagor längs kusten har Horde en befäst kustpost på stranden, kallad Zoram'gar Outpost. De kämpar om kontrollen över området mot både nagor och Alliansen.",al={"horde vid zoram strand","zoram'gar","är horde där"}}},fx={a15c1f29={q="Varför vill Shindrell Swiftfire att nagaerna dödas?",a="Shindrell ser nagaerna som samlas vid The Zoram Strand som ett direkt hot mot Ashenvales nordvästra gränser. Ruinerna av den sjunkna staden Zoram väcker smärtsamma minnen av Sundringen, och nattalverna tänker inte låta ormfolket få fäste på helig mark, oavsett vilket mörkt syfte som förde dem tillbaka till stranden. Genom att döda dem och ta deras huvuden ska deras framryckning hejdas och de drivas tillbaka ut på djuphavet innan invasionen sprider sig längre inåt land.",al={"varför döda naga vid zoram","shindrell swiftfires motiv","varför vill shindrell ha nagahuvuden"}},["99414e89"]={q="Vem ska du jaga vid The Zoram Strand?",a="Du skickas för att jaga Wrathtail-nagaerna som krälar upp ur Veiled Sea på stränderna vid The Zoram Strand. Dessa ormfolk har upprättat ett fientligt läger kring de sjunkna alvruinerna och hotar vildmarken i norra Ashenvale. Shindrell kräver avhuggna huvuden som bevis på att de besegrats. Hon hoppas hejda deras invasionsstyrka innan nattalvernas uråldriga fiender kan komma närmare Astranaar.",al={"wrathtail-naga","vem ska jag döda vid zoram strand","målet vid zoram strand"}}},fp="16,271,20.423.0,25.422.0,25.202.0,45.207.0,27.187.0,52.277.0,45.212.1,46.227.0"}
P.entries["quest:1009"] = {n="Ruuzel",s="Ruuzel är ett alliansuppdrag från Talen vid The Zoram Strand i Ashenvale. Efter att ha hämtat en forntida Kaldorei-statyett från kusten får äventyrare i uppdrag att ta Ring of Zoram från naga-ledaren Ruuzel och låsa upp dess förseglade hemligheter.",h="Ruuzel är ett alliansuppdrag från Talen vid The Zoram Strand i Ashenvale.",kw={"ashenvale","naga","ring of zoram","ruuzel","sunderingen","talen","the zoram strand"},ang={["faction:Alliance"]="Genom att döda Ruuzel och hjälpa Talen hejdar alliansens styrkor naga-hotet som tränger i land längs norra Ashenvale.",["race:NightElf"]="När du återtar Ring of Zoram återvinner du en del av ditt förfädersarv från naga som vanhelgar dina förfäders sjunkna ruiner."},sec={{t="Zorams nyckel",b="Innan den stora Sunderingen slet Kalimdor itu och sänkte dess storslagna kuststäder under havet styrdes staden Zoram av mäktiga nattalviska adelsfamiljer. Främst bland deras regalier var Ring of Zoram, som Talen tror är nyckeln till låset på den forntida statyetten. Efter katastrofen försvann ringen i tidvattnet i årtusenden och bevarade de sjunkna relikernas hemligheter från nyfikna blickar."},{t="Nagaernas invasion",b="När naga nyligen anlände till The Zoram Strand började de ormlika inkräktarna genomsöka ruinerna av sitt forna hemland. Ruuzel, matriarken som leder den lokala yngelgruppen, fann Ring of Zoram och bar den till sitt näste på en ö i norr. För att öppna statyetten som dragits upp ur det grunda vattnet ger nattalven Talen alliansens resenärer i uppdrag att spåra upp Ruuzel och återta den forntida familjeklenoden."}},faq={{q="Vem är Ruuzel?",a="Ruuzel är ledare för de naga som håller till vid The Zoram Strand i nordvästra Ashenvale. Hon har sitt näste på en ö utanför kusten i norr, där hon vaktar bärgade skatter från den sjunkna nattalviska civilisationen.",al={"ruuzels historia","vem är nagaledaren","ruuzel-boss"}},{q="Vad är Ring of Zoram?",a="Ring of Zoram var en förtrollad familjeklenod som tillhörde Zorams forntida härskare före Sunderingen. Talen tror att den är nyckeln till låset på den forntida statyetten.",al={"ring of zorams historia","vad gör ringen","zorams nyckel"}},{q="Varför behöver Talen ringen?",a="Talen vill avslöja hemligheterna i en forntida Kaldorei-statyett som nyligen hämtats från stranden. Artefakten är förseglad med ett lås som bara Ring of Zoram kan öppna.",al={"varför hämta ring of zoram","talens statyettlås"}},{q="Vad hände med staden Zoram?",a="Zoram var en forntida Kaldorei-stad som förstördes under den stora Sunderingen för tiotusen år sedan. Det mesta av dess storslagna stenverk rasade ner i Veiled Sea, och bara utspridda kustruiner återstår.",al={"vad hände med zoram","zorams ruiner"}},{q="Var finns Ruuzel?",a="Ruuzel bor på en stor klippö utanför den norra änden av The Zoram Strand, omgiven av sina ormlika följeslagare.",al={"var finns ruuzel","ruuzels ö"}},{q="Vad händer när ringen har återtagits?",a="När du återlämnar ringen till Talen är hans undersökning av stranden avslutad. Tacksam för din hjälp med att låsa upp artefaktens hemligheter belönar han dig och minns din insats.",al={"vad gör talen sedan","uppföljning efter ruuzel"}}},fp="6,135,16.362.0,18.356.0,14.195.0,26.140.0,29.161.0,31.183.0,24.122.0,39.124.0"}
P.entries["quest:101"] = {n="The Totem of Infliction",s="Madame Eva i Darkshire erbjuder sig att skapa ett skyddande värn som kallas Totem of Infliction åt resenärer genom de skuggiga skogarna. Genom att samla kvarlevor från gastar, skelett och giftiga spindlar som hemsöker trakten förtrollar hon en amulett som slår tillbaka mot angripare. Uppgiften är både ett bistert överlevnadsprov och ett vidskepligt skydd mot det genomträngande mörkret i Duskwood.",h="Madame Eva i Darkshire erbjuder sig att skapa ett skyddande värn som kallas Totem of Infliction åt resenärer...",kw={"darkshire","duskwood","gasttänder","madame eva","skyddande värn","skelettfingrar","spindelgift","totem of infliction"},ang={["class:Paladin"]="Paladiner kanske ser snett på att sätta samman värn av odöda ben och spindelgift, men i Duskwoods dystra mörker måste även heliga krigare ibland förhålla sig till praktisk folktrolldom.",["class:Priest"]="Medan den Heliga Ljusets kyrkas ortodoxi betonar tro och hängivenhet kanaliserar hedgehäxor som Madame Eva andlig vilja genom handfasta, bistert utformade talismaner.",["class:Warlock"]="Warlocks känner lätt igen principerna bakom de vedergällningsförbannelser som vävts in i Evas skyddande amulett.",["faction:Alliance"]="I ett gränsland som är avskuret från större militära förstärkningar förlitar sig Alliance-resenärer ofta på lokal mystikers folktro och skyddande värn, som Madame Evas, för att uthärda skogens fasor."},sec={{t="En spådom om blodspillan",b="I sitt levande ljus upplysta hem i Darkshire ser Madame Eva bortom slöjan och skådar ödet för dem som träder över hennes tröskel. Hon anar faror och våld som tålmodigt väntar vid horisonten och erbjuder mer än enkel spådom: praktisk trolldom. Genom att samla tio gasttänder, tio skelettfingrar och fem flaskor spindelgift från de hemsökta snåren får en äventyrare fram råvarorna som behövs för att skapa ett skyddande värn mot Duskwoods glupska rovdjur."},{t="Evas förtrollning",b="Gasttänder fyllda av förtärande hunger, fingerben ryckta från rastlösa döda och kraftigt spindelgift vävs samman med Madame Evas förtrollningar. När totemet hålls i handen i livsfara utstrålar det en magisk aura som ska återspegla grymhet och tillfoga själslig och fysisk skada på alla som är dumdristiga nog att slå dess bärare."}},faq={{q="Vem är Madame Eva?",a="Madame Eva är spåkvinna och mystiker i den hårt ansatta staden Darkshire. Hon tyder omen och brygger skyddande värn åt lokalbor och äventyrare på genomresa som försöker överleva Duskwoods övernaturliga faror.",al={"madame eva","vem ger det här uppdraget","eva darkshire"}},{q="Vad är syftet med Totem of Infliction?",a="Totemet är en förtrollad talisman som ska hålla angripare borta. När den hålls i handen vid hot slår dess magi tillbaka mot fiender som försöker skada bäraren.",al={"syftet med totem of infliction","vad gör totemet","totemets historia"}},{q="Varför behöver Madame Eva gasttänder, skelettfingrar och spindelgift?",a="Genom att använda de anatomiska vapnen och kvarlevorna från skogens mest aggressiva monster – gastarnas bett, skelettens gripande klor och spindelgift – skapar Eva en skyddande förtrollning som slår tillbaka.",al={"varför spindelgift","ingredienser till totemet","varför skelettfingrar"}},{q="Var hittar man totemets beståndsdelar?",a="Beståndsdelarna samlas från de odöda och bestar som hemsöker Duskwood. Skelett och gastar hemsöker kyrkogårdarna och de hemsökta fruktodlingarna i området, medan stora giftiga spindlar bygger bo i de skuggiga skogarna.",al={"var hittar man tänder","var får man tag på material","var finns gastar och spindlar"}},{q="Vilken fara förutser Madame Eva?",a="Eva varnar för att viskande vindar talar om ett hot som snart väntar. Hon säger särskilt till äventyraren att hon förutser omfattande blodspillan längs vägen framåt.",al={"evas spådom","vilken fara är på väg","blodspillan i framtiden"}},{q="Räknas det som mörk magi att skapa totemet?",a="Att skapa föremål av likdelar och gift snuddar vid skuggmagi, men i Duskwoods desperata omgivningar är folkmagi och skyddande amuletter allmänt accepterade försvarsmetoder mot fasorna runt omkring.",al={"är det här nekromanti","är eva ond","totem med mörk magi"}}},fx={c4af218f={q="Varför vill Madame Eva att Totem of Infliction tillverkas?",a="Madame Eva lyssnar noga på vindens viskningar och förutser en stor och våldsam fara som tålmodigt väntar på dig inom en snar framtid. Den mystiska vanhelgelsen hotar hela Duskwood, men erbjudandet att skapa Totem of Infliction är särskilt tänkt att skydda dig mot den förestående blodsutgjutelse hon ser i din väg.",al={"madame evas motiv","varför tillverka totem of infliction","varför hjälper eva mig"}}},fp="23,210,22.335.0,17.212.0,18.173.0,47.159.0,73.131.0,45.176.0,36.115.0,44.131.0"}
P.entries["quest:1010"] = {n="Bathran's Hair",s="Bathran's Hair är ett Alliance-uppdrag som Orendil Broadleaf erbjuder vid Maestra's Post i västra Ashenvale. För att behandla ett mystiskt sjukt Night Elf-barn, vars sjukdom sträcker sig bortom kroppen, skickar Orendil äventyrare norrut för att genomsöka de gamla ruinerna vid Bathran's Haunt efter en läkande växt som sägs bota själens åkommor.",h="Bathran's Hair är ett Alliance-uppdrag som Orendil Broadleaf erbjuder vid Maestra's Post i västra Ashenvale.",kw={"ashenvale","bathran's hair","bathran's haunt","darkshore","forsaken","maestra's post","orendil broadleaf","örtknippe"},ang={["faction:Alliance"]="Att säkra medicin åt barnet i Astranaar stärker utposterna vid frontlinjen, som håller västra Ashenvale mot fientliga Horde och Forsakens expansion.",["profession:Herbalism"]="Örtknippena som ligger utspridda i Bathran's Haunt kan upptäckas med örtspårning, vilket gör sökandet bland ruinerna betydligt enklare.",["race:NightElf"]="Forsakens växande närvaro vid Bathran's Haunt utgör ett allvarligt hot mot de helgade gränserna i norra Ashenvale och mot barnens välbefinnande."},sec={{t="En åkomma i själen",b="Vid Maestra's Post, strax söder om gränsen till Darkshore, står Night Elf-örtisten Orendil Broadleaf inför en bekymmersam medicinsk kris. Ett litet barn i Astranaar har blivit svårt sjukt och visar symtom som vanliga fysiska botemedel inte rår på. Orendil är övertygad om att sjukdomen plågar barnets själ, inte bara kroppen, och söker Bathran's Hair, en ovanlig läkande ört som förr samlades bland de gamla alviska ruinerna norrut."},{t="Inkräktare i ruinerna",b="Sökandet för äventyrarna till Bathran's Haunt, en förstörd enklav längs vägens östra sida på väg mot Darkshore. Det är farligt att samla ihop örtknippena, eftersom Forsaken-agenter har tagit sig in på den gamla platsen. När Orendil får växterna kan han brygga en lindrande dryck, men upptäckten av odöda inkräktare som rör sig öppet i norra Ashenvale oroar örtisten djupt."}},faq={{q="Vad är Bathran's Hair?",a="Bathran's Hair är en sällsynt medicinalväxt som hör hemma bland ruinerna vid Bathran's Haunt i Ashenvale. Night Elf-örtister värdesätter den för dess kraftigt läkande egenskaper, särskilt förmågan att lindra och läka åkommor som drabbar själen snarare än vanliga fysiska sår.",al={"växten bathrans hair","vad är hair","bathran-ört"}},{q="Vem är sjuk vid Maestra's Post?",a="Ingen på själva utposten. Patienten är Relara Whitemoon, ett litet Night Elf-barn i Astranaar och dotter till Pelturas Whitemoon. Barnets tillstånd förvärras för varje timme, och vanliga botemedel har misslyckats eftersom sjukdomen verkar vara av andlig natur. Därför söker Orendil Broadleaf gamla läkande växter.",al={"sjukt barn maestra","vem läker orendil","vem behöver botemedlet"}},{q="Var ligger Bathran's Haunt?",a="Bathran's Haunt ligger i nordvästra Ashenvale, norr om Maestra's Post och strax öster om huvudvägen mot gränsen till Darkshore. Ruinerna är fulla av fientliga Forsaken-agenter.",al={"bathrans haunt plats","var hittar man bathrans hair","var ligger bathran"}},{q="Varför finns Forsaken vid Bathran's Haunt?",a="Ingen vet vad de är ute efter. Orendil får reda på dem först när örterna kommer tillbaka till honom, och odöda som lurar så långt in i Night Elf-land oroar honom djupt.",al={"odöda vid bathran","varför forsaken i ashenvale","forsaken bathrans haunt"}},{q="Vad händer när man har samlat växten?",a="När du har lämnat över fem knippen av örten tillagar Orendil en medicinaldryck och ber dig skynda den till det sjuka barnet i Astranaar. Då börjar uppföljningsuppdraget 'Orendil's Cure'.",al={"nästa uppdrag efter bathrans hair","vad gör orendil med hair","orendils cure-uppdragskedja"}},{q="Kan örtister lättare hitta örtknippena?",a="Ja. Knippena med den skördade växten ligger utspridda på marken och kan vara svåra att upptäcka med blotta ögat, men äventyrare som kan Herbalism kan hitta dem med sin förmåga att spåra örter.",al={"herbalism bathrans hair","spåra bathrans hair","örtknippe örtsökning"}}},fx={b8c70a70={q="Varför vill Orendil Broadleaf ha Bathran's Hair?",a="Ett barn i Astranaar har blivit svårt sjukt, och Orendil Broadleaf fruktar att åkomman drabbar mer än bara kroppen. Han tror att barnets själ själv är angripen och behöver Bathran's Hair för att brygga en särskild blandning som kan läka själens plågor innan sjukdomen tar barnets liv.",al={"varför behöver orendil bathran's hair","orendil broadleafs motiv","varför hjälpa orendil"}}},fp="14,265,24.401.0,24.333.1,23.231.0,30.308.0,33.191.0,42.159.0,40.199.1,45.171.0"}
P.entries["quest:1011"] = {n="Forsaken Diseases",s="Djupt i östra Ashenvale vakar nattalvsspejaren Kayneth Stillwind över de framryckande Forsaken med växande oro. Han tror att de odöda brygger farsoter för att härja alvernas heliga marker och skickar därför alliansens mästare att anfalla ett läger nära The Dor'Danil Barrow Den och säkra ett prov på deras avskyvärda brygder.",h="Djupt i östra Ashenvale vakar nattalvsspejaren Kayneth Stillwind över de framryckande Forsaken med växande...",kw={"apotekare","ashenvale","bottle of disease","the dor'danil barrow den","forest song","forsaken","forsaken diseases","kayneth stillwind","night elf"},ang={["class:Druid"]="Druiderna betraktar gravkamrarna som helig mark där de förenas med The Emerald Dream. Upptäckten av buteljerade farsoter nära Dor'Danil slår mot själva kärnan i Cenarion Circles beskydd.",["faction:Alliance"]="Hordens allierade Forsaken för med sig fasansfull kemisk krigföring till Ashenvale och visar Alliansens ledning att konflikten i skogen handlar om långt mer än enkla gränstvister om timmer.",["race:NightElf"]="För kaldorei är de odödas intrång nära en helig gravkammare en outhärdlig skändning. Att försvara de sovande druidernas och Ashenvales renhet mot vidriga gifter är en fråga om överlevnad och heder."},sec={{t="En farsot i skogarna",b="Ashenvales nattalver har länge kämpat mot satyrer, rasande elementarer och orkers skogshuggarlag, men Forsakens ankomst innebär en mörkare vändning. De odöda, en del av Horden, fäller inte bara träd utan etablerar också fästen nära forntida ruiner och heliga gravkammare. Deras närvaro för med sig inte bara krig, utan också det fasansfulla hotet från alkemisk pest till Kaldoreis orörda lundar."},{t="Infiltration vid Dor'Danil",b="Söder om Forest Song, nära The Dor'Danil Barrow Den, har Forsakens apotekare och spejare upprättat ett befäst läger. Där, bland kokande kittlar och vidriga reagenser, tappar de oprövade gifter på flaska. Kayneth Stillwind ger spejare i uppdrag att infiltrera lägret och hämta en oskadad Bottle of Disease, så att dess flyktiga innehåll kan analyseras innan Forsaken släpper lös det över skogen."}},faq={{q="Vem är Kayneth Stillwind?",a="Kayneth Stillwind är en nattalv som håller vakt från ruinerna av Forest Song i östra Ashenvale. Han bevakar fiendens rörelser i hela regionen och följer särskilt hoten från Forsaken och de korrumperande krafterna nära gravkamrarna.",al={"kayneth stillwind","vem ger forsaken sjukdomar","uppdragsgivare i forest song"}},{q="Var ligger Forsakens läger?",a="Forsakens läger ligger rakt söder om Forest Song, i närheten av The Dor'Danil Barrow Den. De odöda styrkorna har samlats där kring bryggbord och tält för att blanda sina biologiska brygder.",al={"var ligger lägret","var finns de smittade flaskorna","dor'danil lägrets plats"}},{q="Varför är Forsaken i Ashenvale?",a="Orkerna söker främst timmer och territorium i Ashenvale, medan Forsaken har mörka alkemiska och biologiska syften. De verkar nära forntida kaldoreiska gravkamrar, samlar reagenser och brygger giftiga ämnen, vilket väcker alvernas farhågor om att de tänker förgifta själva landet.",al={"varför forsaken i ashenvale","odöda i ashenvale","forsakens motiv"}},{q="Vad händer när flaskan har hämtats?",a="Kayneth Stillwind undersöker den beslagtagna flaskan för att identifiera dess innehåll. Hans undersökning leder genast vidare till upptäckten av de sovande druidernas belägenhet inne i den närliggande The Dor'Danil Barrow Den, vilket föranleder uppföljningsuppdraget Insane Druids.",al={"vad händer sedan","efter forsaken diseases","uppföljningsuppdrag"}},{q="Vad är Forest Song?",a="Forest Song är en forntida, nästan övergiven nattalvsruin längst österut i Ashenvale, nära gränsen till Azshara. Kayneth Stillwind är dess enda invånare och leder därifrån kampen mot Forsaken i regionen.",al={"utposten forest song","vad är forest song"}},{q="Vad är gravkamrarna i Ashenvale?",a="Gravkamrar är heliga underjordiska tillflyktsorter där nattalvsdruider sover i gemenskap med The Emerald Dream. The Dor'Danil Barrow Den är en sådan plats, vilket gör Forsakens närvaro i närheten särskilt oroväckande för kaldorei.",al={"vad är en gravkammare","dor'danils syfte","gravkamrar"}}},fx={["78e58974"]={q="Varför vill Kayneth Stillwind ha en flaska med sjukdom?",a="Kayneth fruktar att Forsaken planerar att fördärva Ashenvale genom att sprida sina vidriga smittor över nattalvernas heliga marker. Han behöver konkreta bevis på deras experiment så att han själv kan undersöka blandningen och fastställa exakt vilka illvilliga farsoter de odöda brygger nära gravkullarna.",al={"varför vill kayneth få detta gjort","kayneth stillwinds motiv","varför hämta bottle of disease"}},["53e7622a"]={q="Vad ska Bottle of Disease användas till?",a="Flaskan innehåller en ytterst smittsam blandning av gifter och farsoter, tillverkad av Forsaken-apotekare i deras provisoriska läger nära The Dor'Danil Barrow Den. Kayneth Stillwind tänker analysera provet för att avslöja de verkliga målen och omfattningen av Forsakens biologiska krigföring i Ashenvale.",al={"vad är bottle of disease","bottle of disease syfte","forsakens bottle of disease"}},["1459855f"]={q="Vilka skickas du ut mot i det här uppdraget?",a="Du skickas mot en hemlighetsfull grupp Forsaken-odöda som befäst sig söder om Forest Song, nära The Dor'Danil Barrow Den. De har smugit sig in i Ashenvale för att skapa onaturliga farsoter och experimentera nära uråldriga heliga alvplatser. De hotar både skogen och dess väktare.",al={"vilka strider vi mot","forsakenfiender i ashenvale","vem finns vid lägret"}}},fp="17,225,23.309.0,25.342.0,25.217.0,35.162.0,34.198.0,41.199.1,20.206.0,38.217.0"}
